(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("herodotus-1-e", [{"sp": "HDR", "t": "Ἱστοριῶν Α· Κλειώ", "st": "1"}, {"sp": "N", "t": "Ἡροδότου Ἁλικαρνησσέος ἱστορίης ἀπόδεξις ἥδε, ὡς μήτε τὰ γενόμενα ἐξ ἀνθρώπων τῷ χρόνῳ ἐξίτηλα γένηται, μήτε ἔργα μεγάλα τε καὶ θωμαστά, τὰ μὲν Ἕλλησι τὰ δὲ βαρβάροισι ἀποδεχθέντα, ἀκλεᾶ γένηται, τά τε ἄλλα καὶ δι’ ἣν αἰτίην ἐπολέμησαν ἀλλήλοισι.", "st": "1.0"}, {"sp": "N", "t": "Περσέων μέν νυν οἱ λόγιοι Φοίνικας αἰτίους φασὶ γενέσθαι τῆς διαφορῆς. τούτους γὰρ ἀπὸ τῆς Ἐρυθρῆς καλεομένης θαλάσσης ἀπικομένους ἐπὶ τήνδε τὴν θάλασσαν, καὶ οἰκήσαντας τοῦτον τὸν χῶρον τὸν καὶ νῦν οἰκέουσι, αὐτίκα ναυτιλίῃσι μακρῇσι ἐπιθέσθαι, ἀπαγινέοντας δὲ φορτία Αἰγύπτιά τε καὶ Ἀσσύρια τῇ τε ἄλλῃ ἐσαπικνέεσθαι καὶ δὴ καὶ ἐς Ἄργος. τὸ δὲ Ἄργος τοῦτον τὸν χρόνον προεῖχε ἅπασι τῶν ἐν τῇ νῦν Ἑλλάδι καλεομένῃ χωρῇ. ἀπικομένους δὲ τούς Φοίνικας ἐς δὴ τὸ Ἄργος τοῦτο διατίθεσθαι τὸν φόρτον. πέμπτῃ δὲ ἢ ἕκτῃ ἡμέρῃ ἀπ’ ἧς ἀπίκοντο, ἐξεμπολημένων σφι σχεδόν πάντων, ἐλθεῖν ἐπὶ τὴν θάλασσαν γυναῖκας ἄλλας τε πολλάς καὶ δὴ καὶ τοῦ βασιλέος θυγατέρα· τὸ δέ οἱ οὔνομα εἶναι, κατὰ τὠυτὸ τὸ καὶ Ἕλληνές λέγουσι, Ἰοῦν τὴν Ἰνάχου· ταύτας στάσας κατά πρύμνην τῆς νεὸς ὠνέεσθαι τῶν φορτίων τῶν σφι ἦν θυμός μάλιστα· καὶ τοὺς Φοίνικας διακελευσαμένους ὁρμῆσαι ἐπ’ αὐτάς. τὰς μὲν δὴ πλεῦνας τῶν γυναικῶν ἀποφυγεῖν, τὴν δὲ Ἰοῦν σὺν ἄλλῃσι ἁρπασθῆναι. ἐσβαλομένους δὲ ἐς τὴν νέα οἴχεσθαι ἀποπλέοντας ἐπ’ Αἰγύπτου.", "st": "1.1"}, {"sp": "N", "t": "οὕτω μὲν Ἰοῦν ἐς Αἴγυπτον ἀπικέσθαι λέγουσι Πέρσαι, οὐκ ὡς Ἕλληνές, καὶ τῶν ἀδικημάτων πρῶτον τοῦτο ἄρξαι. μετὰ δὲ ταῦτα Ἑλλήνων τινάς (οὐ γὰρ ἔχουσι τοὔνομα ἀπηγήσασθαι) φασὶ τῆς Φοινίκης ἐς Τύρον προσσχόντας ἁρπάσαι τοῦ βασιλέος τὴν θυγατέρα Εὐρώπην. εἴησαν δ’ ἄν οὗτοι Κρῆτες. ταῦτα μὲν δὴ ἴσα πρὸς ἴσα σφι γενέσθαι, μετὰ δὲ ταῦτα Ἕλληνας αἰτίους τῆς δευτέρης ἀδικίης γενέσθαι· καταπλώσαντας γὰρ μακρῇ νηί ἐς Αἶαν τε τὴν Κολχίδα καὶ ἐπὶ Φᾶσιν ποταμόν, ἐνθεῦτεν, διαπρηξαμένους καὶ τἄλλα τῶν εἵνεκεν ἀπίκατο, ἁρπάσαι τοῦ βασιλέος τὴν θυγατέρα Μηδείην. πέμψαντά δὲ τὸν Κόλχων βασιλέα ἐς τὴν Ἑλλάδα κήρυκα αἰτέειν τε δίκας τῆς ἁρπαγῆς καὶ ἀπαιτέειν τὴν θυγατέρα. τοὺς δὲ ὑποκρίνασθαι ὡς οὐδὲ ἐκεῖνοι Ἰοῦς τῆς Ἀργείης ἔδοσάν σφι δίκας τῆς ἁρπαγῆς· οὐδὲ ὦν αὐτοὶ δώσειν ἐκείνοισι.", "st": "1.2"}, {"sp": "N", "t": "δευτέρῃ δὲ λέγουσι γενεῇ μετὰ ταῦτα Ἀλέξανδρον τὸν Πριάμου, ἀκηκοότα ταῦτα, ἐθελῆσαί οἱ ἐκ τῆς Ἑλλάδος δι’ ἁρπαγῆς γενέσθαι γυναῖκα, ἐπιστάμενον πάντως ὅτι οὐ δώσει δίκας. οὐδὲ γὰρ ἐκείνους διδόναι. οὕτω δὴ ἁρπάσαντος αὐτοῦ Ἑλένην, τοῖσι Ἕλλησι δόξαι πρῶτον πέμψαντας ἀγγέλους ἀπαιτέειν τε Ἑλένην καὶ δίκας τῆς ἁρπαγῆς αἰτέειν. τοὺς δέ, προϊσχομένων ταῦτα, προφέρειν σφι Μηδείης τὴν ἁρπαγήν, ὡς οὐ δόντες αὐτοὶ δίκας οὐδὲ ἐκδόντες ἀπαιτεόντων βουλοίατό σφι παρ’ ἄλλων δίκας γίνεσθαι.", "st": "1.3"}, {"sp": "N", "t": "μέχρι μὲν ὦν τούτου ἁρπαγάς μούνας εἶναι παρ’ ἀλλήλων, τὸ δὲ ἀπὸ τούτου Ἕλληνας δὴ μεγάλως αἰτίους γενέσθαι· προτέρους γὰρ ἄρξαι στρατεύεσθαι ἐς τὴν Ἀσίην ἢ σφέας ἐς τὴν Εὐρώπην. τὸ μέν νυν ἁρπάζειν γυναῖκας ἀνδρῶν ἀδίκων νομίζειν ἔργον εἶναι, τὸ δὲ ἁρπασθεισέων σπουδήν ποιήσασθαι τιμωρέειν ἀνοήτων, τὸ δὲ μηδεμίαν ὤρην ἔχειν ἁρπασθεισέων σωφρόνων· δῆλα γὰρ δὴ ὅτι, εἰ μὴ αὐταὶ ἐβούλοντο, οὐκ ἂν ἡρπάζοντο. σφέας μὲν δὴ τοὺς ἐκ τῆς Ἀσίης λέγουσι Πέρσαι ἁρπαζομενέων τῶν γυναικῶν λόγον οὐδένα ποιήσασθαι, Ἕλληνας δὲ Λακεδαιμονίης εἵνεκεν γυναικὸς στόλον μέγαν συναγεῖραι καὶ ἔπειτα ἐλθόντας ἐς τὴν Ἀσίην τὴν Πριάμου δύναμιν κατελεῖν. ἀπὸ τούτου αἰεὶ ἡγήσασθαι τὸ Ἑλληνικὸν σφίσι εἶναι πολέμιον. τὴν γὰρ Ἀσίην καὶ τὰ ἐνοικέοντα ἔθνεα βάρβαρα οἰκηιεῦνται οἱ Πέρσαι, τὴν δὲ Εὐρώπην καὶ τὸ Ἑλληνικόν ἥγηνται κεχωρίσθαι.", "st": "1.4"}, {"sp": "N", "t": "οὕτω μὲν Πέρσαι λέγουσι γενέσθαι, καὶ διὰ τὴν Ἰλίου ἅλωσιν εὑρίσκουσι σφίσι ἐοῦσαν τὴν ἀρχήν τῆς ἔχθρης τῆς ἐς τοὺς Ἕλληνας. περὶ δὲ τῆς Ἰοῦς οὐκ ὁμολογέουσι Πέρσῃσι οὕτω Φοίνικες· οὐ γὰρ ἁρπαγῇ σφέας χρησαμένους λέγουσι ἀγαγεῖν αὐτήν ἐς Αἴγυπτον, ἀλλ’ ὡς ἐν τῷ Ἄργεϊ ἐμίσγετο τῷ ναυκλήρῳ τῆς νέος· ἐπεὶ δ’ ἔμαθε ἔγκυος ἐοῦσα, αἰδεομένη τοὺς τοκέας οὕτω δὴ ἐθελοντήν αὐτήν τοῖσι Φοίνιξι συνεκπλῶσαι, ὡς ἂν μὴ κατάδηλος γένηται. ταῦτα μέν νυν Πέρσαι τε καὶ Φοίνικες λέγουσι· ἐγὼ δὲ περὶ μὲν τούτων οὐκ ἔρχομαι ἐρέων ὡς οὕτω ἢ ἄλλως κως ταῦτα ἐγένετο, τὸν δὲ οἶδα αὐτὸς πρῶτον ὑπάρξαντα ἀδίκων ἔργων ἐς τοὺς Ἕλληνας, τοῦτον σημήνας προβήσομαι ἐς τὸ πρόσω τοῦ λόγου, ὁμοίως σμικρὰ καὶ μεγάλα ἄστεα ἀνθρώπων ἐπεξιών. τὰ γὰρ τὸ πάλαι μεγάλα ἦν, τὰ πολλὰ σμικρὰ αὐτῶν γέγονε· τὰ δὲ ἐπ’ ἐμεῦ ἦν μεγάλα, πρότερον ἦν σμικρά. τὴν ἀνθρωπηίην ὦν ἐπιστάμενος εὐδαιμονίην οὐδαμὰ ἐν τὠυτῷ μένουσαν, ἐπιμνήσομαι ἀμφοτέρων ὁμοίως.", "st": "1.5"}, {"sp": "N", "t": "Κροῖσος ἦν Λυδὸς μὲν γένος, παῖς δὲ Ἀλυάττεω, τύραννος δὲ ἐθνέων τῶν ἐντός Ἅλυος ποταμοῦ, ὃς ῥέων ἀπὸ μεσαμβρίης μεταξὺ Συρίων τε καὶ Παφλαγόνων ἐξιεῖ πρὸς βορέην ἄνεμον ἐς τὸν Εὔξεινον καλεόμενον πόντον. οὗτος ὁ Κροῖσος βαρβάρων πρῶτος τῶν ἡμεῖς ἴδμεν τοὺς μὲν κατεστρέψατο Ἑλλήνων ἐς φόρου ἀπαγωγήν, τοὺς δὲ φίλους προσεποιήσατο. κατεστρέψατο μὲν Ἴωνάς τε καὶ Αἰολέας καὶ Δωριέας τοὺς ἐν τῇ Ἀσίῃ, φίλους δὲ προσεποιήσατο Λακεδαιμονίους. πρὸ δὲ τῆς Κροίσου ἀρχῆς πάντες Ἕλληνες ἦσαν ἐλεύθεροι· τὸ γὰρ Κιμμερίων στράτευμα τὸ ἐπὶ τὴν Ἰωνίην ἀπικόμενον Κροίσου ἐὸν πρεσβύτερον οὐ καταστροφὴ ἐγένετο τῶν πολίων ἀλλ’ ἐξ ἐπιδρομῆς ἁρπαγή.", "st": "1.6"}, {"sp": "N", "t": "ἡ δὲ ἡγεμονίη οὕτω περιῆλθε, ἐοῦσα Ἡρακλειδέων ἐς τὸ γένος τὸ Κροίσου, καλεομένους δὲ Μερμνάδας. ἦν Κανδαύλης, τὸν οἱ Ἕλληνές Μυρσίλον ὀνομάζουσι, τύραννος Σαρδίων, ἀπόγονος δὲ Ἀλκαίου τοῦ Ἡρακλέος. Ἄγρων μὲν γὰρ ὁ Νίνου τοῦ Βήλου τοῦ Ἀλκαίου πρῶτος Ἡρακλειδέων βασιλεὺς ἐγένετο Σαρδίων, Κανδαύλης δὲ ὁ Μύρσου ὕστατος. οἱ δὲ πρότερον Ἄγρωνος βασιλεύσαντες ταύτης τῆς χώρης ἦσαν ἀπόγονοι Λυδοῦ τοῦ Ἄτυος, ἀπ’ ὅτευ ὁ δῆμος Λύδιος ἐκλήθη ὁ πᾶς οὗτος, πρότερον Μηίων καλεόμενος. παρὰ τούτων Ἡρακλεῖδαι ἐπιτραφθέντες ἔσχον τὴν ἀρχήν ἐκ θεοπροπίου, ἐκ δούλης τε τῆς Ἰαρδάνου γεγονότες καὶ Ἡρακλέος, ἄρξαντες μὲν ἐπὶ δύο τε καὶ εἴκοσι γενεᾶς ἀνδρῶν ἔτεα πέντε τε καὶ πεντακόσια, παῖς παρὰ πατρὸς ἐκδεκόμενος τὴν ἀρχήν, μέχρι Κανδαύλεω τοῦ Μύρσου.", "st": "1.7"}, {"sp": "N", "t": "οὗτος δὴ ὦν ὁ Κανδαύλης ἠράσθη τῆς ἑωυτοῦ γυναικός, ἐρασθεὶς δὲ ἐνόμιζέ οἱ εἶναι γυναῖκα πολλὸν πασέων καλλίστην. ὥστε δὲ ταῦτα νομίζων, ἦν γάρ οἱ τῶν αἰχμοφόρων Γύγης ὁ Δασκύλου ἀρεσκόμενος μάλιστα, τούτῳ τῷ Γύγῃ καὶ τὰ σπουδαιέστερα τῶν πρηγμάτων ὑπερετίθετο ὁ Κανδαύλης καὶ δὴ καὶ τὸ εἶδος τῆς γυναικὸς ὑπερεπαινέων. χρόνου δὲ οὐ πολλοῦ διελθόντος (χρῆν γὰρ Κανδαύλῃ γενέσθαι κακῶς) ἔλεγε πρὸς τὸν Γύγην τοιάδε. Γύγη, οὐ γὰρ σε δοκέω πείθεσθαι μοι λέγοντι περὶ τοῦ εἴδεος τῆς γυναικός (ὦτα γὰρ τυγχάνει ἀνθρώποισι ἐόντα ἀπιστότερα ὀφθαλμῶν), ποίεε ὅκως ἐκείνην θεήσεαι γυμνήν. ὃ δ’ ἀμβώσας εἶπε δέσποτα, τίνα λέγεις λόγον οὐκ ὑγιέα, κελεύων με δέσποιναν τὴν ἐμὴν θεήσασθαι γυμνήν; ἅμα δὲ κιθῶνι ἐκδυομένῳ συνεκδύεται καὶ τὴν αἰδῶ γυνή. πάλαι δὲ τὰ καλὰ ἀνθρώποισι ἐξεύρηται, ἐκ τῶν μανθάνειν δεῖ· ἐν τοῖσι ἓν τόδε ἐστί, σκοπέειν τινὰ τὰ ἑωυτοῦ. ἐγὼ δὲ πείθομαι ἐκείνην εἶναι πασέων γυναικῶν καλλίστην, καὶ σέο δέομαι μὴ δέεσθαι ἀνόμων.", "st": "1.8"}, {"sp": "N", "t": "ὃ μὲν δὴ λέγων τοιαῦτα ἀπεμάχετο, ἀρρωδέων μὴ τί οἱ ἐξ αὐτῶν γένηται κακόν, ὃ δ’ ἀμείβετο τοῖσιδε. θάρσεε, Γύγη, καὶ μὴ φοβεῦ μήτε ἐμέ, ὡς σέο πειρώμενος λέγω λόγον τόνδε, μήτε γυναῖκα τὴν ἐμήν, μὴ τὶ τοι ἐξ αὐτῆς γένηται βλάβος. ἀρχήν γὰρ ἐγὼ μηχανήσομαι οὕτω ὥστε μηδέ μαθεῖν μιν ὀφθεῖσαν ὑπὸ σεῦ. ἐγὼ γάρ σε ἐς τὸ οἴκημα ἐν τῷ κοιμώμεθα ὄπισθε τῆς ἀνοιγομένης θύρης στήσω. μετὰ δ’ ἐμὲ ἐσελθόντα παρέσται καὶ ἡ γυνὴ ἡ ἐμὴ ἐς κοῖτον. κεῖται δὲ ἀγχοῦ τῆς ἐσόδου θρόνος· ἐπὶ τοῦτον τῶν ἱματίων κατὰ ἕν ἕκαστον ἐκδύνουσα θήσει, καὶ κατ’ ἡσυχίην πολλὴν παρέξει τοι θεήσασθαι. ἐπεὰν δέ ἀπὸ τοῦ θρόνου στείχῃ ἐπὶ τὴν εὐνήν κατὰ νώτου τε αὐτῆς γένῃ, σοὶ μελέτω τὸ ἐνθεῦτεν ὅκως μὴ σε ὄψεται ἰόντα διὰ θυρέων.", "st": "1.9"}, {"sp": "N", "t": "ὃ μὲν δὴ ὡς οὐκ ἐδύνατο διαφυγεῖν, ἦν ἕτοιμος· ὁ δὲ Κανδαύλης, ἐπεὶ ἐδόκεε ὥρη τῆς κοίτης εἶναι, ἤγαγε τὸν Γύγεα ἐς τὸ οἴκημα. καὶ μετὰ ταῦτα αὐτίκα παρῆν καὶ ἡ γυνή. ἐσελθοῦσαν δὲ καὶ τιθεῖσαν τὰ εἵματα ἐθηεῖτο ὁ Γύγης. ὡς δὲ κατὰ νώτου ἐγένετο ἰούσης τῆς γυναικός ἐς τὴν κοίτην, ὑπεκδὺς ἐχώρεε ἔξω, καὶ ἡ γυνὴ ἐπορᾷ μιν ἐξιόντα. μαθοῦσα δὲ τὸ ποιηθέν ἐκ τοῦ ἀνδρὸς οὔτε ἀνέβωσε αἰσχυνθεῖσα οὔτε ἔδοξε μαθεῖν, ἐν νοῶ ἔχουσα τίσεσθαι τὸν Κανδαύλεα. παρὰ γὰρ τοῖσι Λυδοῖσι, σχεδὸν δὲ καὶ παρὰ τοῖσι ἄλλοισι βαρβάροισι καὶ ἄνδρα ὀφθῆναι γυμνόν ἐς αἰσχύνην μεγάλην φέρει.", "st": "1.10"}, {"sp": "N", "t": "τότε μὲν δὴ οὕτω οὐδέν δηλώσασα ἡσυχίην εἶχε. ὡς δὲ ἡμέρη τάχιστα ἐγεγόνεε, τῶν οἰκετέων τοὺς μάλιστα ὥρα πιστοὺς ἐόντας ἑωυτῇ, ἑτοίμους ποιησαμένη ἐκάλεε τὸν Γύγεα. ὁ δὲ οὐδὲν δοκέων αὐτήν τῶν πρηχθέντων ἐπίστασθαι ἦλθε καλεόμενος· ἐώθεε γὰρ καὶ πρόσθε, ὅκως ἡ βασίλεια καλέοι, φοιτᾶν. ὡς δὲ ὁ Γύγης ἀπίκετο, ἔλεγε ἡ γυνὴ τάδε. νῦν τοί δυῶν ὁδῶν παρεουσέων Γύγη δίδωμί αἵρεσιν, ὁκοτέρην βούλεαι τραπέσθαι. ἢ γὰρ Κανδαύλεα ἀποκτείνας ἐμέ τε καὶ τὴν βασιληίην ἔχε τὴν Λυδῶν, ἢ αὐτόν σε αὐτίκα οὕτω ἀποθνήσκειν δεῖ, ὡς ἂν μὴ πάντα πειθόμενος Κανδαύλῃ τοῦ λοιποῦ ἴδῃς τὰ μὴ σε δεῖ. ἀλλ’ ἤτοι κεῖνόν γε τὸν ταῦτα βουλεύσαντα δεῖ ἀπόλλυσθαι, ἢ σε τὸν ἐμὲ γυμνήν θεησάμενον καὶ ποιήσαντα οὐ νομιζόμενα. ὁ δὲ Γύγης τέως μὲν ἀπεθώμαζε τὰ λεγόμενα, μετὰ δὲ ἱκέτευε μὴ μιν ἀναγκαίῃ ἐνδέειν διακρῖναι τοιαύτην αἵρεσιν. οὔκων δὴ ἔπειθε, ἀλλ’ ὥρα ἀναγκαίην ἀληθέως προκειμένην ἢ τὸν δεσπότεα ἀπολλύναι ἢ αὐτὸν ὑπ’ ἄλλων ἀπόλλυσθαι· αἱρέεται αὐτὸς περιεῖναι. ἐπειρώτα δὴ λέγων τάδε. ἐπεί με ἀναγκάζεις δεσπότεα τὸν ἐμὸν κτείνειν οὐκ ἐθέλοντα, φέρε ἀκούσω τέῳ καὶ τρόπῳ ἐπιχειρήσομεν αὐτῷ. ἣ δὲ ὑπολαβοῦσα ἔφη ἐκ τοῦ αὐτοῦ μὲν χωρίου ἡ ὁρμή ἔσται ὅθεν περ καὶ ἐκεῖνος ἐμέ ἐπεδέξατο γυμνήν, ὑπνωμένῳ δὲ ἡ ἐπιχείρησις ἔσται.", "st": "1.11"}, {"sp": "N", "t": "ὡς δὲ ἤρτυσαν τὴν ἐπιβουλήν, νυκτὸς γενομένης (οὐ γὰρ ἐμετίετο ὁ Γύγης, οὐδέ οἱ ἦν ἀπαλλαγὴ οὐδεμία, ἀλλ’ ἔδεε ἤ αὐτὸν ἀπολωλέναι ἢ Κανδαύλεα) εἵπετο ἐς τὸν θάλαμον τῇ γυναικί, καί μιν ἐκείνη, ἐγχειρίδιον δοῦσα, κατακρύπτει ὑπὸ τὴν αὐτὴν θύρην. καὶ μετὰ ταῦτα ἀναπαυομένου Κανδαύλεω ὑπεκδύς τε καὶ ἀποκτείνας αὐτὸν ἔσχε καὶ τὴν γυναῖκα καὶ τὴν βασιληίην Γύγης τοῦ καὶ Ἀρχίλοχος ὁ Πάριος κατὰ τὸν αὐτὸν χρόνον γενόμενος ἐν ἰάμβῳ τριμέτρῳ ἐπεμνήσθη.", "st": "1.12"}, {"sp": "N", "t": "ἔσχε δὲ τὴν βασιληίην καὶ ἐκρατύνθη ἐκ τοῦ ἐν Δελφοῖσι χρηστηρίου. ὡς γὰρ δὴ οἱ Λυδοὶ δεινόν ἐποιεῦντο τὸ Κανδαύλεω πάθος καὶ ἐν ὅπλοισι ἦσαν, συνέβησαν ἐς τὠυτὸ οἳ τε τοῦ Γύγεω στασιῶται καί οἱ λοιποὶ Λυδοί, ἤν μὲν τὸ χρηστήριον ἀνέλῃ μιν βασιλέα εἶναι Λυδῶν, τόν δὲ βασιλεύειν, ἤν δὲ μή, ἀποδοῦναι ὀπίσω ἐς Ἡρακλείδας τὴν ἀρχήν. ἀνεῖλέ τε δὴ τὸ χρηστήριον καὶ ἐβασίλευσε οὕτω Γύγης. τοσόνδε μέντοι εἶπε ἡ Πυθίη, ὡς Ἡρακλείδῃσι τίσις ἥξει ἐς τὸν πέμπτον ἀπόγονον Γύγεω. τούτου τοῦ ἔπεος Λυδοί τε καί οἱ βασιλέες αὐτῶν λόγον οὐδένα ἐποιεῦντο, πρὶν δὴ ἐπετελέσθη.", "st": "1.13"}, {"sp": "N", "t": "τὴν μὲν δὴ τυραννίδα οὕτω ἔσχον οἱ Μερμνάδαι τοὺς Ἡρακλείδας ἀπελόμενοι, Γύγης δὲ τυραννεύσας ἀπέπεμψε ἀναθήματα ἐς Δελφοὺς οὐκ ὀλίγα, ἀλλ’ ὅσα μὲν ἀργύρου ἀναθήματα, ἔστι οἱ πλεῖστα ἐν Δελφοῖσι, πάρεξ δὲ τοῦ ἀργύρου χρυσὸν ἄπλετον ἀνέθηκε ἄλλον τε καὶ τοῦ μάλιστα μνήμην ἄξιον ἔχειν ἐστί, κρητῆρες οἱ ἀριθμὸν ἓξ χρύσεοι ἀνακέαται. ἑστᾶσι δὲ οὗτοι ἐν τῷ Κορινθίων θησαυρῷ, σταθμὸν ἔχοντες τριήκοντα τάλαντα· ἀληθέι δὲ λόγῳ χρεωμένῳ οὐ Κορινθίων τοῦ δημοσίου ἐστὶ ὁ θησαυρός, ἀλλὰ Κυψέλου τοῦ Ἠετίωνος. οὗτος δὲ ὁ Γύγης πρῶτος βαρβάρων τῶν ἡμεῖς ἴδμεν ἐς Δελφοὺς ἀνέθηκε ἀναθήματα μετὰ Μίδην τὸν Γορδίεω Φρυγίης βασιλέα. ἀνέθηκε γὰρ δὴ καὶ Μίδης τὸν βασιλήιον θρόνον ἐς τὸν προκατίζων ἐδίκαζε, ἐόντα ἀξιοθέητον· κεῖται δὲ ὁ θρόνος οὗτος ἔνθα περ οἱ τοῦ Γύγεω κρητῆρες. ὁ δὲ χρυσός οὗτος καὶ ὁ ἄργυρος τὸν ὁ Γύγης ἀνέθηκε, ὑπὸ Δελφῶν καλέεται Γυγάδας ἐπὶ τοῦ ἀναθέντος ἐπωνυμίην.", "st": "1.14"}, {"sp": "N", "t": "ἐσέβαλε μέν νυν στρατιὴν καὶ οὗτος ἐπείτε ἦρξε ἔς τε Μίλητον καὶ ἐς Σμύρνην, καὶ Κολοφῶνος τὸ ἄστυ εἷλε· ἀλλ’ οὐδὲν γὰρ μέγα ἀπ’ αὐτοῦ ἄλλο ἔργον ἐγένετο βασιλεύσαντος δυῶν δέοντα τεσσεράκοντα ἔτεα, τοῦτον μὲν παρήσομεν τοσαῦτα ἐπιμνησθέντες, Ἄρδυος δὲ τοῦ Γύγεω μετὰ Γύγην βασιλεύσαντος μνήμην ποιήσομαι.", "st": "1.15"}, {"sp": "N", "t": "οὗτος δὲ Πριηνέας τε εἷλε ἐς Μίλητόν τε ἐσέβαλε, ἐπὶ τούτου τε τυραννεύοντος Σαρδίων Κιμμέριοι ἐξ ἠθέων ὑπὸ Σκυθέων τῶν νομάδων ἐξαναστάντες ἀπίκοντο ἐς τὴν Ἀσίην καὶ Σάρδις πλὴν τῆς ἀκροπόλιος εἷλον.", "st": "1.15b"}, {"sp": "N", "t": "Ἄρδυος δὲ βασιλεύσαντος ἑνὸς δέοντα πεντήκοντα ἔτεα ἐξεδέξατο Σαδυάττης ὁ Ἄρδυος, καὶ ἐβασίλευσε ἔτεα δυώδεκα, Σαδυάττεω δὲ Ἀλυάττης. οὗτος δὲ Κυαξάρῃ τε τῷ Δηιόκεω ἀπογόνῳ ἐπολέμησε καὶ Μήδοισι, Κιμμερίους τε ἐκ τῆς Ἀσίης ἐξήλασε, Σμύρνην τε τὴν ἀπὸ Κολοφῶνος κτισθεῖσαν εἷλε, ἐς Κλαζομενάς τε ἐσέβαλε. ἀπὸ μέν νυν τούτων οὐκ ὡς ἤθελε ἀπήλλαξε, ἀλλὰ προσπταίσας μεγάλως· ἄλλα δὲ ἔργα ἀπεδέξατο ἐὼν ἐν τῇ ἀρχῇ ἀξιαπηγητότατα τάδε.", "st": "1.16"}, {"sp": "N", "t": "ἐπολέμησε Μιλησίοισι, παραδεξάμενος τὸν πόλεμον παρὰ τοῦ πατρός. ἐπελαύνων γὰρ ἐπολιόρκεε τὴν Μίλητον τρόπῳ τοιῷδε· ὅκως μὲν εἴη ἐν τῇ γῇ καρπὸς ἁδρός, τηνικαῦτα ἐσέβαλλε τὴν στρατιήν· ἐστρατεύετο δὲ ὑπὸ συρίγγων τε καὶ πηκτίδων καὶ αὐλοῦ γυναικηίου τε καὶ ἀνδρηίου. ὡς δὲ ἐς τὴν Μιλησίην ἀπίκοιτο, οἰκήματα μὲν τὰ ἐπὶ τῶν ἀγρῶν οὔτε κατέβαλλε οὔτε ἐνεπίμπρη οὔτε θύρας ἀπέσπα, ἔα δὲ κατὰ χώρην ἑστάναι· ὁ δὲ τὰ τε δένδρεα καὶ τὸν καρπὸν τὸν ἐν τῇ γῇ ὅκως διαφθείρειε, ἀπαλλάσσετο ὀπίσω. τῆς γὰρ θαλάσσης οἱ Μιλήσιοι ἐπεκράτεον, ὥστε ἐπέδρης μὴ εἶναι ἔργον τῇ στρατιῇ. τὰς δὲ οἰκίας οὐ κατέβαλλε ὁ Λυδὸς τῶνδε εἵνεκα, ὅκως ἔχοιεν ἐνθεῦτεν ὁρμώμενοι τὴν γῆν σπείρειν τε καὶ ἐργάζεσθαι οἱ Μιλήσιοι, αὐτὸς δὲ ἐκείνων ἐργαζομένων ἔχοι τι καὶ σίνεσθαι ἐσβάλλων.", "st": "1.17"}, {"sp": "N", "t": "ταῦτα ποιέων ἐπολέμεε ἔτεα ἕνδεκα, ἐν τοῖσι τρώματα μεγάλα διφάσια Μιλησίων ἐγένετο, ἔν τε Λιμενηίῳ χώρης τῆς σφετέρης μαχεσαμένων καὶ ἐν Μαιάνδρου πεδίῳ. τὰ μέν νυν ἓξ ἔτεα τῶν ἕνδεκα Σαδυάττης ὁ Ἄρδυος ἔτι Λυδῶν ἦρχε, ὁ καὶ ἐσβάλλων τηνικαῦτα ἐς τὴν Μιλησίην τὴν στρατιήν· Σαδυάττης οὗτος γὰρ καὶ ὁ τὸν πόλεμον ἦν συνάψας· τὰ δὲ πέντε τῶν ἐτέων τὰ ἑπόμενα τοῖσι ἓξ Ἀλυάττης ὁ Σαδυάττεω ἐπολέμεε, ὃς παραδεξάμενος, ὡς καὶ πρότερον μοι δεδήλωται, παρὰ τοῦ πατρὸς τὸν πόλεμον προσεῖχε ἐντεταμένως. τοῖσι δὲ Μιλησίοισι οὐδαμοὶ Ἰώνων τὸν πόλεμον τοῦτον συνεπελάφρυνον ὅτι μὴ Χῖοι μοῦνοι. οὗτοι δὲ τὸ ὅμοιον ἀνταποδιδόντες ἐτιμώρεον· καὶ γὰρ δὴ πρότερον οἱ Μιλήσιοι τοῖσι Χίοισι τὸν πρὸς Ἐρυθραίους πόλεμον συνδιήνεικαν.", "st": "1.18"}, {"sp": "N", "t": "τῷ δὲ δυωδεκάτῳ ἔτεϊ ληίου ἐμπιπραμένου ὑπὸ τῆς στρατιῆς συνηνείχθη τι τοιόνδε γενέσθαι πρῆγμα· ὡς ἅφθη τάχιστα τὸ λήιον, ἀνέμῳ βιώμενον ἅψατο νηοῦ Ἀθηναίης ἐπίκλησιν Ἀσσησίης, ἁφθεὶς δὲ ὁ νηὸς κατεκαύθη. καὶ τὸ παραυτίκα μὲν λόγος οὐδεὶς ἐγένετο, μετὰ δὲ τῆς στρατιῆς ἀπικομένης ἐς Σάρδις ἐνόσησε ὁ Ἀλυάττης. μακροτέρης δέ οἱ γινομένης τῆς νούσου πέμπει ἐς Δελφοὺς θεοπρόπους, εἴτε δὴ συμβουλεύσαντός τευ, εἴτε καὶ αὐτῷ ἔδοξε πέμψαντα τὸν θεὸν ἐπειρέσθαι περὶ τῆς νούσου. τοῖσι δὲ ἡ Πυθίη ἀπικομένοισι ἐς Δελφοὺς οὐκ ἔφη χρήσειν πρὶν ἢ τὸν νηὸν τῆς Ἀθηναίης ἀνορθώσωσι, τὸν ἐνέπρησαν χώρης τῆς Μιλησίης ἐν Ἀσσησῷ.", "st": "1.19"}, {"sp": "N", "t": "Δελφῶν οἶδα ἐγὼ οὕτω ἀκούσας γενέσθαι· Μιλήσιοι δὲ τάδε προστιθεῖσι τούτοισι, Περίανδρον τὸν Κυψέλου ἐόντα Θρασυβούλῳ τῷ τότε Μιλήτου τυραννεύοντι ξεῖνον ἐς τὰ μάλιστα, πυθόμενον τὸ χρηστήριον τὸ τῷ Ἀλυάττῃ γενόμενον, πέμψαντα ἄγγελον κατειπεῖν, ὅκως ἄν τι προειδὼς πρὸς τὸ παρεὸν βουλεύηται.", "st": "1.20"}, {"sp": "N", "t": "Μιλήσιοι μέν νυν οὕτω λέγουσι γενέσθαι. Ἀλυάττης δέ, ὡς οἱ ταῦτα ἐξαγγέλθη, αὐτίκα ἔπεμπε κήρυκα ἐς Μίλητον βουλόμενος σπονδὰς ποιήσασθαι Θρασυβούλῳ τε καὶ Μιλησίοισι χρόνον ὅσον ἂν τὸν νηὸν οἰκοδομέῃ. ὃ μὲν δὴ ἀπόστολος ἐς τὴν Μίλητον ἦν, Θρασύβουλος δὲ σαφέως προπεπυσμένος πάντα λόγον, καὶ εἰδὼς τὰ Ἀλυάττης μέλλοι ποιήσειν, μηχανᾶται τοιάδε· ὅσος ἦν ἐν τῷ ἄστεϊ σῖτος καὶ ἑωυτοῦ καὶ ἰδιωτικός, τοῦτον πάντα συγκομίσας ἐς τὴν ἀγορὴν προεῖπε Μιλησίοισι, ἐπεὰν αὐτὸς σημήνῃ, τότε πίνειν τε πάντας καὶ κώμῳ χρᾶσθαι ἐς ἀλλήλους.", "st": "1.21"}, {"sp": "N", "t": "ταῦτα δὲ ἐποίεέ τε καὶ προηγόρευε Θρασύβουλος τῶνδε εἵνεκεν, ὅκως ἂν δὴ ὁ κῆρυξ ὁ Σαρδιηνὸς ἰδών τε σωρὸν μέγαν σίτου κεχυμένον καὶ τοὺς ἀνθρώπους ἐν εὐπαθείῃσι ἐόντας ἀγγείλῃ Ἀλυάττῃ· τὰ δὴ καὶ ἐγένετο. ὡς γὰρ δὴ ἰδών τε ἐκεῖνα ὁ κῆρυξ καὶ εἶπας πρὸς Θρασύβουλον τοῦ Λυδοῦ τὰς ἐντολὰς ἀπῆλθε ἐς τὰς Σάρδις, ὡς ἐγὼ πυνθάνομαι, δι’ οὐδὲν ἄλλο ἐγένετο ἡ διαλλαγή. ἐλπίζων γὰρ ὁ Ἀλυάττης σιτοδείην τε εἶναι ἰσχυρὴν ἐν τῇ Μιλήτῳ καὶ τὸν λεὼν τετρῦσθαι ἐς τὸ ἔσχατον κακοῦ, ἤκουε τοῦ κήρυκος νοστήσαντος ἐκ τῆς Μιλήτου τοὺς ἐναντίους λόγους ἢ ὡς αὐτὸς κατεδόκεε. μετὰ δὲ ἥ τε διαλλαγή σφι ἐγένετο ἐπ’ ᾧ τε ξείνους ἀλλήλοισι εἶναι καὶ συμμάχους, καὶ δύο τε ἀντὶ ἑνὸς νηοὺς τῇ Ἀθηναίῃ οἰκοδόμησε ὁ Ἀλυάττης ἐν τῇ Ἀσσησῷ, αὐτός τε ἐκ τῆς νούσου ἀνέστη. κατὰ μέν τὸν πρὸς Μιλησίους τε καὶ Θρασύβουλον πόλεμον Ἀλυάττῃ ὧδε ἔσχε.", "st": "1.22"}, {"sp": "N", "t": "Περίανδρος δὲ ἦν Κυψέλου παῖς οὗτος ὁ τῷ Θρασυβούλῳ τὸ χρηστήριον μηνύσας· ἐτυράννευε δὲ ὁ Περίανδρος Κορίνθου· τῷ δὴ λέγουσι Κορίνθιοι (ὁμολογέουσι δέ σφι Λέσβιοι) ἐν τῷ βίῳ θῶμα μέγιστον παραστῆναι, Ἀρίονα τὸν Μηθυμναῖον ἐπὶ δελφῖνος ἐξενειχθέντα ἐπὶ Ταίναρον, ἐόντα κιθαρῳδὸν τῶν τότε ἐόντων οὐδενὸς δεύτερον, καὶ διθύραμβον πρῶτον ἀνθρώπων τῶν ἡμεῖς ἴδμεν ποιήσαντά τε καὶ ὀνομάσαντα καὶ διδάξαντα ἐν Κορίνθῳ.", "st": "1.23"}, {"sp": "N", "t": "τοῦτον τὸν Ἀρίονα λέγουσι, τὸν πολλὸν τοῦ χρόνου διατρίβοντα παρὰ Περιάνδρῳ ἐπιθυμῆσαι πλῶσαι ἐς Ἰταλίην τε καὶ Σικελίην, ἐργασάμενον δὲ χρήματα μεγάλα θελῆσαι ὀπίσω ἐς Κόρινθον ἀπικέσθαι. ὁρμᾶσθαι μέν νυν ἐκ Τάραντος, πιστεύοντα δὲ οὐδαμοῖσι μᾶλλον ἢ Κορινθίοισι μισθώσασθαι πλοῖον ἀνδρῶν Κορινθίων. τοὺς δὲ ἐν τῷ πελάγεϊ ἐπιβουλεύειν τὸν Ἀρίονα ἐκβαλόντας ἔχειν τὰ χρήματα. τὸν δὲ συνέντα τοῦτο λίσσεσθαι, χρήματα μὲν σφι προϊέντα, ψυχὴν δὲ παραιτεόμενον. οὔκων δὴ πείθειν αὐτὸν τούτοισι, ἀλλὰ κελεύειν τοὺς πορθμέας ἢ αὐτὸν διαχρᾶσθαί μιν, ὡς ἂν ταφῆς ἐν γῇ τύχῃ, ἢ ἐκπηδᾶν ἐς τὴν θάλασσαν τὴν ταχίστην· ἀπειληθέντα δὴ τὸν Ἀρίονα ἐς ἀπορίην παραιτήσασθαι, ἐπειδή σφι οὕτω δοκέοι, περιιδεῖν αὐτὸν ἐν τῇ σκευῇ πάσῃ στάντα ἐν τοῖσι ἑδωλίοισι ἀεῖσαι· ἀείσας δὲ ὑπεδέκετο ἑωυτὸν κατεργάσασθαι. καὶ τοῖσι ἐσελθεῖν γὰρ ἡδονὴν εἰ μέλλοιεν ἀκούσεσθαι τοῦ ἀρίστου ἀνθρώπων ἀοιδοῦ, ἀναχωρῆσαι ἐκ τῆς πρύμνης ἐς μέσην νέα. τὸν δὲ ἐνδύντα τε πᾶσαν τὴν σκευὴν καὶ λαβόντα τὴν κιθάρην, στάντα ἐν τοῖσι ἑδωλίοισι διεξελθεῖν νόμον τὸν ὄρθιον, τελευτῶντος δὲ τοῦ νόμου ῥῖψαί μιν ἐς τὴν θάλασσαν ἑωυτὸν ὡς εἶχε σὺν τῇ σκευῇ πάσῃ. καὶ τοὺς μὲν ἀποπλέειν ἐς Κόρινθον, τὸν δὲ δελφῖνα λέγουσι ὑπολαβόντα ἐξενεῖκαι ἐπὶ Ταίναρον. ἀποβάντα δέ αὐτὸν χωρέειν ἐς Κόρινθον σὺν τῇ σκευῇ, καὶ ἀπικόμενον ἀπηγέεσθαι πᾶν τὸ γεγονός. Περίανδρον δὲ ὑπὸ ἀπιστίης Ἀρίονα μὲν ἐν φυλακῇ ἔχειν οὐδαμῇ μετιέντα, ἀνακῶς δὲ ἔχειν τῶν πορθμέων. ὡς δὲ ἄρα παρεῖναι αὐτούς, κληθέντας ἱστορέεσθαι εἴ τι λέγοιεν περὶ Ἀρίονος. φαμένων δὲ ἐκείνων ὡς εἴη τε σῶς περὶ Ἰταλίην καί μιν εὖ πρήσσοντα λίποιεν ἐν Τάραντι, ἐπιφανῆναί σφι τὸν Ἀρίονα ὥσπερ ἔχων ἐξεπήδησε· καὶ τοὺς ἐκπλαγέντας οὐκ ἔχειν ἔτι ἐλεγχομένους ἀρνέεσθαι. ταῦτα μέν νυν Κορίνθιοί τε καὶ Λέσβιοι λέγουσι, καὶ Ἀρίονος ἐστὶ ἀνάθημα χάλκεον οὐ μέγα ἐπὶ Ταινάρῳ, ἐπὶ δελφῖνος ἐπέων ἄνθρωπος.", "st": "1.24"}, {"sp": "N", "t": "Ἀλυάττης δὲ ὁ Λυδὸς τὸν πρὸς Μιλησίους πόλεμον διενείκας μετέπειτα τελευτᾷ, βασιλεύσας ἔτεα ἑπτὰ καὶ πεντήκοντα. ἀνέθηκε δὲ ἐκφυγὼν τὴν νοῦσον δεύτερος οὗτος τῆς οἰκίης ταύτης ἐς Δελφοὺς κρητῆρά τε ἀργύρεον μέγαν καὶ ὑποκρητηρίδιον σιδήρεον κολλητόν, θέης ἄξιον διὰ πάντων τῶν ἐν Δελφοῖσι ἀναθημάτων, Γλαύκου τοῦ Χίου ποίημα, ὃς μοῦνος δὴ πάντων ἀνθρώπων σιδήρου κόλλησιν ἐξεῦρε.", "st": "1.25"}, {"sp": "N", "t": "τελευτήσαντος δὲ Ἀλυάττεω ἐξεδέξατο τὴν βασιληίην Κροῖσος ὁ Ἀλυάττεω, ἐτέων ἐὼν ἡλικίην πέντε καὶ τριήκοντα· ὃς δὴ Ἑλλήνων πρώτοισι ἐπεθήκατο Ἐφεσίοισι. ἔνθα δὴ οἱ Ἐφέσιοι πολιορκεόμενοι ὑπ’ αὐτοῦ ἀνέθεσαν τὴν πόλιν τῇ Ἀρτέμιδι, ἐξάψαντες ἐκ τοῦ νηοῦ σχοινίον ἐς τὸ τεῖχος. ἔστι δὲ μεταξὺ τῆς τε παλαιῆς πόλιος, ἣ τότε ἐπολιορκέετο, καὶ τοῦ νηοῦ ἑπτὰ στάδιοι. πρώτοισι μὲν δὴ τούτοισι ἐπεχείρησε ὁ Κροῖσος, μετὰ δὲ ἐν μέρεϊ ἑκάστοισι Ἰώνων τε καὶ Αἰολέων, ἄλλοισι ἄλλας αἰτίας ἐπιφέρων, τῶν μὲν ἐδύνατο μέζονας παρευρίσκειν, μέζονα ἐπαιτιώμενος, τοῖσι δὲ αὐτῶν καὶ φαῦλα ἐπιφέρων.", "st": "1.26"}, {"sp": "N", "t": "ὡς δὲ ἄρα οἱ ἐν τῇ Ἀσίῃ Ἕλληνες κατεστράφατο ἐς φόρου ἀπαγωγήν, τὸ ἐνθεῦτεν ἐπενόεε νέας ποιησάμενος ἐπιχειρέειν τοῖσι νησιώτῃσι. ἐόντων δέ οἱ πάντων ἑτοίμων ἐς τὴν ναυπηγίην, οἳ μὲν Βίαντα λέγουσι τὸν Πριηνέα ἀπικόμενον ἐς Σάρδις, οἳ δὲ Πιττακὸν τὸν Μυτιληναῖον, εἰρομένου Κροίσου εἴ τι εἴη νεώτερον περὶ τὴν Ἑλλάδα, εἰπόντα τάδε καταπαῦσαι τὴν ναυπηγίην· ὦ βασιλεῦ, νησιῶται ἵππον συνωνέονται μυρίην, ἐς Σάρδις τε καὶ ἐπὶ σὲ ἐν νόῳ ἔχοντες στρατεύεσθαι. Κροῖσον δὲ ἐλπίσαντα λέγειν ἐκεῖνον ἀληθέα εἰπεῖν αἲ γὰρ τοῦτο θεοὶ ποιήσειαν ἐπὶ νόον νησιώτῃσι, ἐλθεῖν ἐπὶ Λυδῶν παῖδας σὺν ἵπποισι. τὸν δὲ ὑπολαβόντα φάναι ὦ βασιλεῦ, προθύμως μοι φαίνεαι εὔξασθαι νησιώτας ἱππευομένους λαβεῖν ἐν ἠπείρῳ, οἰκότα ἐλπίζων. νησιώτας δὲ τί δοκέεις εὔχεσθαι ἄλλο ἤ, ἐπείτε τάχιστα ἐπύθοντό σε μέλλοντα ἐπὶ σφίσι ναυπηγέεσθαι νέας, λαβεῖν ἀρώμενοι Λυδούς ἐν θαλάσσῃ, ἵνα ὕπερ τῶν ἐν τῇ ἠπείρῳ οἰκημένων Ἑλλήνων τίσωνταί σε, τοὺς σὺ δουλώσας ἔχεις; κάρτα τε ἡσθῆναι Κροῖσον τῷ ἐπιλόγῳ καί οἱ, προσφυέως γὰρ δόξαι λέγειν, πειθόμενον παύσασθαι τῆς ναυπηγίης. καὶ οὕτω τοῖσι τὰς νήσους οἰκημένοισι Ἴωσι ξεινίην συνεθήκατο.", "st": "1.27"}, {"sp": "N", "t": "χρόνου δὲ ἐπιγινομένου καὶ κατεστραμμένων σχεδὸν πάντων τῶν ἐντὸς Ἅλυος ποταμοῦ οἰκημένων· πλὴν γὰρ Κιλίκων καὶ Λυκίων τοὺς ἄλλους πάντας ὑπ’ ἑωυτῷ εἶχε καταστρεψάμενος ὁ Κροῖσος. εἰσὶ δὲ οἵδε, Λυδοί, Φρύγες, Μυσοί, Μαριανδυνοί, Χάλυβες, Παφλαγόνες, Θρήικες οἱ Θυνοί τε καὶ Βιθυνοί, Κᾶρες, Ἴωνες, Δωριέες, Αἰολέες, Πάμφυλοι κατεστραμμένων δὲ τούτων καὶ προσεπικτωμένου Κροίσου Λυδοῖσι,", "st": "1.28"}, {"sp": "N", "t": "ἀπικνέονται ἐς Σάρδις ἀκμαζούσας πλούτῳ ἄλλοι τε οἱ πάντες ἐκ τῆς Ἑλλάδος σοφισταί, οἳ τοῦτον τὸν χρόνον ἐτύγχανον ἐόντες, ὡς ἕκαστος αὐτῶν ἀπικνέοιτο, καὶ δὴ καὶ Σόλων ἀνὴρ Ἀθηναῖος, ὃς Ἀθηναίοισι νόμους κελεύσασι ποιήσας ἀπεδήμησε ἔτεα δέκα κατά θεωρίης πρόφασιν ἐκπλώσας, ἵνα δὴ μή τινα τῶν νόμων ἀναγκασθῇ, λῦσαι τῶν ἔθετο. αὐτοὶ γὰρ οὐκ οἷοί τε ἦσαν αὐτὸ ποιῆσαι Ἀθηναῖοι· ὁρκίοισι γὰρ μεγάλοισι κατείχοντο δέκα ἔτεα χρήσεσθαι νόμοισι τοὺς ἄν σφι Σόλων θῆται.", "st": "1.29"}, {"sp": "N", "t": "αὐτῶν δὴ ὦν τούτων καὶ τῆς θεωρίης ἐκδημήσας ὁ Σόλων εἵνεκεν ἐς Αἴγυπτον ἀπίκετο παρὰ Ἄμασιν καὶ δὴ καὶ ἐς Σάρδις παρὰ Κροῖσον. ἀπικόμενος δὲ ἐξεινίζετο ἐν τοῖσι βασιληίοισι ὑπὸ τοῦ Κροίσου· μετὰ δὲ ἡμέρῃ τρίτῃ ἢ τετάρτῃ κελεύσαντος Κροίσου τὸν Σόλωνα θεράποντες περιῆγον κατὰ τοὺς θησαυρούς, καὶ ἐπεδείκνυσαν πάντα ἐόντα μεγάλα τε καὶ ὄλβια. θεησάμενον δέ μιν τὰ πάντα καὶ σκεψάμενον ὥς οἱ κατὰ καιρὸν ἦν, εἴρετο ὁ Κροῖσος τάδε. ξεῖνε Ἀθηναῖε, παρ’ ἡμέας γὰρ περὶ σέο λόγος ἀπῖκται πολλὸς καὶ σοφίης εἵνεκεν τῆς σῆς καὶ πλάνης, ὡς φιλοσοφέων γῆν πολλὴν θεωρίης εἵνεκεν ἐπελήλυθας· νῦν ὦν ἐπειρέσθαι με ἵμερος ἐπῆλθέ σε εἴ τινα ἤδη πάντων εἶδες ὀλβιώτατον. ὃ μὲν ἐλπίζων εἶναι ἀνθρώπων ὀλβιώτατος ταῦτα ἐπειρώτα· Σόλων δὲ οὐδὲν ὑποθωπεύσας ἀλλὰ τῷ ἐόντι χρησάμενος λέγει ὦ βασιλεῦ, Τέλλον Ἀθηναῖον. ἀποθωμάσας δὲ Κροῖσος τὸ λεχθὲν εἴρετο ἐπιστρεφέως· κοίῃ δὴ κρίνεις Τέλλον εἶναι ὀλβιώτατον; ὁ δὲ εἶπε Τέλλῳ τοῦτο μὲν τῆς πόλιος εὖ ἡκούσης παῖδες ἦσαν καλοί τε κἀγαθοί, καί σφι εἶδε ἅπασι τέκνα ἐκγενόμενα καὶ πάντα παραμείναντα· τοῦτο δὲ τοῦ βίου εὖ ἥκοντι, ὡς τὰ παρ’ ἡμῖν, τελευτὴ τοῦ βίου λαμπροτάτη ἐπεγένετο· γενομένης γὰρ Ἀθηναίοισι μάχης πρὸς τοὺς ἀστυγείτονας ἐν Ἐλευσῖνι, βοηθήσας καὶ τροπὴν ποιήσας τῶν πολεμίων ἀπέθανε κάλλιστα, καί μιν Ἀθηναῖοι δημοσίῃ τε ἔθαψαν αὐτοῦ τῇ περ ἔπεσε καὶ ἐτίμησαν μεγάλως.", "st": "1.30"}, {"sp": "N", "t": "ὣς δὲ τὰ κατὰ τὸν Τέλλον προετρέψατο ὁ Σόλων τὸν Κροῖσον εἴπας πολλά τε καὶ ὀλβία, ἐπειρώτα τίνα δεύτερον μετ’ ἐκεῖνον ἴδοι, δοκέων πάγχυ δευτερεῖα γῶν οἴσεσθαι. ὃ δ’ εἶπε Κλέοβίν τε καὶ Βίτωνα. τούτοισι γὰρ ἐοῦσι γένος Ἀργείοισι βίος τε ἀρκέων ὑπῆν, καὶ πρὸς τούτῳ ῥώμη σώματος τοιήδε· ἀεθλοφόροι τε ἀμφότεροι ὁμοίως ἦσαν, καὶ δὴ καὶ λέγεται ὅδε ὁ λόγος. ἐούσης ὁρτῆς τῇ Ἥρῃ τοῖσι Ἀργείοισι ἔδεε πάντως τὴν μητέρα αὐτῶν ζεύγεϊ κομισθῆναι ἐς τὸ ἱρόν, οἱ δέ σφι βόες ἐκ τοῦ ἀγροῦ οὐ παρεγίνοντο ἐν ὥρῃ· ἐκκληιόμενοι δὲ τῇ ὥρῃ οἱ νεηνίαι ὑποδύντες αὐτοὶ ὑπὸ τὴν ζεύγλην εἷλκον τὴν ἅμαξαν, ἐπὶ τῆς ἁμάξης δέ σφι ὠχέετο ἡ μήτηρ· σταδίους δὲ πέντε καὶ τεσσεράκοντα διακομίσαντες ἀπίκοντο ἐς τὸ ἱρόν. ταῦτα δέ σφι ποιήσασι καὶ ὀφθεῖσι ὑπὸ τῆς πανηγύριος τελευτὴ τοῦ βίου ἀρίστη ἐπεγένετο, διέδεξέ τε ἐν τούτοισι ὁ θεὸς ὡς ἄμεινον εἴη ἀνθρώπῳ τεθνάναι μᾶλλον ἢ ζώειν. Ἀργεῖοι μὲν γὰρ περιστάντες ἐμακάριζον τῶν νεηνιέων τὴν ῥώμην, αἱ δὲ Ἀργεῖαι τὴν μητέρα αὐτῶν, οἵων τέκνων ἐκύρησε· ἡ δὲ μήτηρ περιχαρής ἐοῦσα τῷ τε ἔργῳ καὶ τῇ φήμῃ, στᾶσα ἀντίον τοῦ ἀγάλματος εὔχετο Κλεόβι τε καὶ Βίτωνι τοῖσι ἑωυτῆς τέκνοισι, οἵ μιν ἐτίμησαν μεγάλως, τὴν θεὸν δοῦναι τὸ ἀνθρώπῳ τυχεῖν ἄριστον ἐστί. μετὰ ταύτην δὲ τὴν εὐχὴν ὡς ἔθυσάν τε καὶ εὐωχήθησαν, κατακοιμηθέντες ἐν αὐτῷ τῷ ἱρῷ οἱ νεηνίαι οὐκέτι ἀνέστησαν ἀλλ’ ἐν τέλεϊ τούτῳ ἔσχοντο. Ἀργεῖοι δὲ σφέων εἰκόνας ποιησάμενοι ἀνέθεσαν ἐς Δελφοὺς ὡς ἀριστῶν γενομένων.", "st": "1.31"}, {"sp": "N", "t": "Σόλων μὲν δὴ εὐδαιμονίης δευτερεῖα ἔνεμε τούτοισι, Κροῖσος δὲ σπερχθεὶς εἶπε ὦ ξεῖνε Ἀθηναῖε, ἡ δ’ ἡμετέρη εὐδαιμονίη οὕτω τοι ἀπέρριπται ἐς τὸ μηδὲν ὥστε οὐδὲ ἰδιωτέων ἀνδρῶν ἀξίους ἡμέας ἐποίησας; ὁ δὲ εἶπε ὦ Κροῖσε, ἐπιστάμενόν με τὸ θεῖον πᾶν ἐὸν φθονερόν τε καὶ ταραχῶδες ἐπειρωτᾷς ἀνθρωπηίων πρηγμάτων πέρι. ἐν γὰρ τῷ μακρῷ χρόνῳ πολλὰ μὲν ἐστὶ ἰδεῖν τὰ μή τις ἐθέλει, πολλὰ δὲ καὶ παθεῖν. ἐς γὰρ ἑβδομήκοντα ἔτεα οὖρον τῆς ζόης ἀνθρώπῳ προτίθημι. οὗτοι ἐόντες ἐνιαυτοὶ ἑβδομήκοντα παρέχονται ἡμέρας διηκοσίας καὶ πεντακισχιλίας καὶ δισμυρίας, ἐμβολίμου μηνὸς μὴ γινομένου· εἰ δὲ δὴ ἐθελήσει τοὔτερον τῶν ἐτέων μηνὶ μακρότερον γίνεσθαι, ἵνα δὴ αἱ ὧραι συμβαίνωσι παραγινόμεναι ἐς τὸ δέον, μῆνες μὲν παρὰ τὰ ἑβδομήκοντα ἔτεα οἱ ἐμβόλιμοι γίνονται τριήκοντα πέντε, ἡμέραι δὲ ἐκ τῶν μηνῶν τούτων χίλιαι πεντήκοντα. τουτέων τῶν ἁπασέων ἡμερέων τῶν ἐς τὰ ἑβδομήκοντα ἔτεα, ἐουσέων πεντήκοντα καὶ διηκοσιέων καὶ ἑξακισχιλιέων καὶ δισμυριέων, ἡ ἑτέρη αὐτέων τῇ ἑτέρῃ ἡμέρῃ τὸ παράπαν οὐδὲν ὅμοιον προσάγει πρῆγμα. οὕτω ὦν Κροῖσε πᾶν ἐστὶ ἄνθρωπος συμφορή. ἐμοὶ δὲ σὺ καὶ πλουτέειν μέγα φαίνεαι καὶ βασιλεὺς πολλῶν εἶναι ἀνθρώπων· ἐκεῖνο δὲ τὸ εἴρεό με, οὔκω σε ἐγὼ λέγω, πρὶν τελευτήσαντα καλῶς τὸν αἰῶνα πύθωμαι. οὐ γάρ τι ὁ μέγα πλούσιος μᾶλλον τοῦ ἐπ’ ἡμέρην ἔχοντος ὀλβιώτερος ἐστί, εἰ μή οἱ τύχη ἐπίσποιτο πάντα καλὰ ἔχοντα εὖ τελευτῆσαι τὸν βίον. πολλοὶ μὲν γὰρ ζάπλουτοι ἀνθρώπων ἀνόλβιοι εἰσί, πολλοὶ δὲ μετρίως ἔχοντες βίου εὐτυχέες. ὁ μὲν δὴ μέγα πλούσιος ἀνόλβιος δὲ δυοῖσι προέχει τοῦ εὐτυχέος μοῦνον, οὗτος δὲ τοῦ πλουσίου καὶ ἀνόλβου πολλοῖσι· ὃ μὲν ἐπιθυμίην ἐκτελέσαι καί ἄτην μεγάλην προσπεσοῦσαν ἐνεῖκαι δυνατώτερος, ὁ δὲ τοῖσιδε προέχει ἐκείνου· ἄτην μὲν καὶ ἐπιθυμίην οὐκ ὁμοίως δυνατὸς ἐκείνῳ ἐνεῖκαι, ταῦτα δὲ ἡ εὐτυχίη οἱ ἀπερύκει, ἄπηρος δὲ ἐστί, ἄνουσος, ἀπαθὴς κακῶν, εὔπαις, εὐειδής. εἰ δὲ πρὸς τούτοισι ἔτι τελευτήσῃ τὸν βίον εὖ, οὗτος ἐκεῖνος τὸν σὺ ζητέεις, ὁ ὄλβιος κεκλῆσθαι ἄξιος ἐστί· πρὶν δ’ ἂν τελευτήσῃ, ἐπισχεῖν, μηδὲ καλέειν κω ὄλβιον ἀλλ’ εὐτυχέα. τὰ πάντα μέν νυν ταῦτα συλλαβεῖν ἄνθρωπον ἐόντα ἀδύνατον ἐστί, ὥσπερ χωρῇ οὐδεμία καταρκέει πάντα ἑωυτῇ παρέχουσα, ἀλλὰ ἄλλο μὲν ἔχει ἑτέρου δὲ ἐπιδέεται· ἣ δὲ ἂν τὰ πλεῖστα ἔχῃ, αὕτη ἀρίστη. ὣς δὲ καὶ ἀνθρώπου σῶμα ἓν οὐδὲν αὔταρκες ἐστί· τὸ μὲν γὰρ ἔχει, ἄλλου δὲ ἐνδεές ἐστι· ὃς δ’ ἂν αὐτῶν πλεῖστα ἔχων διατελέῃ καὶ ἔπειτα τελευτήσῃ εὐχαρίστως τὸν βίον, οὗτος παρ’ ἐμοὶ τὸ οὔνομα τοῦτο ὦ βασιλεῦ δίκαιος ἐστὶ φέρεσθαι. σκοπέειν δὲ χρὴ παντὸς χρήματος τὴν τελευτήν, κῇ ἀποβήσεται· πολλοῖσι γὰρ δὴ ὑποδέξας ὄλβον ὁ θεὸς προρρίζους ἀνέτρεψε.", "st": "1.32"}, {"sp": "N", "t": "ταῦτα λέγων τῷ Κροίσῳ οὔ κως οὔτε ἐχαρίζετο, οὔτε λόγου μιν ποιησάμενος οὐδενὸς ἀποπέμπεται, κάρτα δόξας ἀμαθέα εἶναι, ὃς τὰ παρεόντα ἀγαθὰ μετεὶς τὴν τελευτὴν παντὸς χρήματος ὁρᾶν ἐκέλευε.", "st": "1.33"}, {"sp": "N", "t": "μετὰ δὲ Σόλωνα οἰχόμενον ἔλαβέ ἐκ θεοῦ νέμεσις μεγάλη Κροῖσον, ὡς εἰκάσαι, ὅτι ἐνόμισε ἑωυτὸν εἶναι ἀνθρώπων ἁπάντων ὀλβιώτατον. αὐτίκα δέ οἱ εὕδοντι ἐπέστη ὄνειρος, ὅς οἱ τὴν ἀληθείην ἔφαινε τῶν μελλόντων γενέσθαι κακῶν κατὰ τὸν παῖδα. ἦσαν δὲ τῷ Κροίσῳ δύο παῖδες, τῶν οὕτερος μὲν διέφθαρτο, ἦν γὰρ δὴ κωφός, ὁ δὲ ἕτερος τῶν ἡλίκων μακρῷ τὰ πάντα πρῶτος· οὔνομα δέ οἱ ἦν Ἄτυς. τοῦτον δὴ ὦν τὸν Ἄτυν σημαίνει τῷ Κροίσῳ ὁ ὄνειρος, ὡς ἀπολέει μιν αἰχμῇ σιδηρέῃ βληθέντα. ὃ δ’ ἐπείτε ἐξηγέρθη καὶ ἑωυτῷ λόγον ἔδωκε, καταρρωδήσας τὸν ὄνειρον ἄγεται μὲν τῷ παιδὶ γυναῖκα, ἐωθότα δὲ στρατηγέειν μιν τῶν Λυδῶν οὐδαμῇ ἔτι ἐπὶ τοιοῦτο πρῆγμα ἐξέπεμπε· ἀκόντια δὲ καὶ δοράτια καὶ τά τοιαῦτα πάντα τοῖσι χρέωνται ἐς πόλεμον ἄνθρωποι, ἐκ τῶν ἀνδρεώνων ἐκκομίσας ἐς τοὺς θαλάμους συνένησε, μή τί οἱ κρεμάμενον τῷ παιδὶ ἐμπέσῃ.", "st": "1.34"}, {"sp": "N", "t": "ἔχοντι δέ οἱ ἐν χερσὶ τοῦ παιδὸς τὸν γάμον, ἀπικνέεται ἐς τὰς Σάρδις ἀνὴρ συμφορῇ ἐχόμενος καὶ οὐ καθαρὸς χεῖρας, ἐὼν Φρὺξ μὲν γενεῇ, γένεος δὲ τοῦ βασιληίου. παρελθὼν δὲ οὗτος ἐς τὰ Κροίσου οἰκία κατὰ νόμους τοὺς ἐπιχωρίους καθαρσίου ἐδέετο κυρῆσαι, Κροῖσος δέ μιν ἐκάθηρε. ἔστι δὲ παραπλησίη ἡ κάθαρσις τοῖσι Λυδοῖσι καὶ τοῖσι Ἕλλησι. ἐπείτε δὲ τὰ νομιζόμενα ἐποίησε ὁ Κροῖσος, ἐπυνθάνετο ὁκόθεν τε καὶ τίς εἴη, λέγων τάδε· ὤνθρωπε, τίς τε ἐὼν καὶ κόθεν τῆς Φρυγίης ἥκων ἐπίστιός μοι ἐγένεο; τίνα τε ἀνδρῶν ἢ γυναικῶν ἐφόνευσας; ὁ δὲ ἀμείβετο ὦ βασιλεῦ, Γορδίεω μὲν τοῦ Μίδεω εἰμὶ παῖς, ὀνομάζομαι δὲ Ἄδρηστος, φονεύσας δὲ ἀδελφεὸν ἐμεωυτοῦ ἀέκων πάρειμι ἐξεληλαμένος τε ὑπὸ τοῦ πατρὸς καὶ ἐστερημένος πάντων. Κροῖσος δέ μιν ἀμείβετο τοῖσιδε· ἀνδρῶν τε φίλων τυγχάνεις ἔκγονος ἐὼν καὶ ἐλήλυθας ἐς φίλους, ἔνθα ἀμηχανήσεις χρήματος οὐδενὸς μένων ἐν ἡμετέρου, συμφορήν τε ταύτην ὡς κουφότατα φέρων κερδανέεις πλεῖστον.", "st": "1.35"}, {"sp": "N", "t": "ὃ μὲν δὴ δίαιταν εἶχε ἐν Κροίσου. ἐν δὲ τῷ αὐτῷ χρόνῳ τούτῳ ἐν τῷ Μυσίῳ Ὀλύμπῳ ὑὸς χρῆμα γίνεται μέγα· ὁρμώμενος δὲ οὗτος ἐκ τοῦ ὄρεος τούτου τὰ τῶν Μυσῶν ἔργα διαφθείρεσκε. πολλάκις δὲ οἱ Μυσοὶ ἐπ’ αὐτὸν ἐξελθόντες ποιέεσκον μὲν κακὸν οὐδέν, ἔπασχον δὲ πρὸς αὐτοῦ. τέλος δὲ ἀπικόμενοι παρὰ τὸν Κροῖσον τῶν Μυσῶν ἄγγελοι ἔλεγον τάδε. ὦ βασιλεῦ, ὑὸς χρῆμα μέγιστον ἀνεφάνη ἡμῖν ἐν τῇ χώρῃ, ὃς τὰ ἔργα διαφθείρει. τοῦτον προθυμεόμενοι ἑλεῖν οὐ δυνάμεθα. νῦν ὦν προσδεόμεθά σευ τὸν παῖδα καὶ λογάδας νεηνίας καὶ κύνας συμπέμψαι ἡμῖν, ὡς ἄν μιν ἐξέλωμεν ἐκ τῆς χώρης. οἳ μὲν δὴ τούτων ἐδέοντο, Κροῖσος δὲ μνημονεύων τοῦ ὀνείρου τὰ ἔπεα ἔλεγέ σφι τάδε. παιδὸς μὲν πέρι τοῦ ἐμοῦ μὴ μνησθῆτε ἔτι· οὐ γὰρ ἂν ὑμῖν συμπέμψαιμι· νεόγαμός τε γὰρ ἐστὶ καὶ ταῦτά οἱ νῦν μέλει. Λυδῶν μέντοι λογάδας καὶ τὸ κυνηγέσιον πᾶν συμπέμψω, καὶ διακελεύσομαι τοῖσι ἰοῦσι εἶναι ὡς προθυμοτάτοισι συνεξελεῖν ὑμῖν τὸ θηρίον ἐκ τῆς χώρης.", "st": "1.36"}, {"sp": "N", "t": "ταῦτα ἀμείψατο· ἀποχρεωμένων δὲ τούτοισι τῶν Μυσῶν, ἐπεσέρχεται ὁ τοῦ Κροίσου παῖς ἀκηκοὼς τῶν ἐδέοντο οἱ Μυσοί. οὐ φαμένου δὲ τοῦ Κροίσου τόν γε παῖδά σφι συμπέμψειν, λέγει πρὸς αὐτὸν ὁ νεηνίης τάδε. ὦ πάτερ, τὰ κάλλιστα πρότερον κοτὲ καὶ γενναιότατα ἡμῖν ἦν ἔς τε πολέμους καὶ ἐς ἄγρας φοιτέοντας εὐδοκιμέειν· νῦν δὲ ἀμφοτέρων με τούτων ἀποκληίσας ἔχεις, οὔτε τινὰ δειλίην μοι παριδὼν οὔτε ἀθυμίην νῦν τε τέοισί με χρὴ ὄμμασι ἔς τε ἀγορὴν καὶ ἐξ ἀγορῆς φοιτέοντα φαίνεσθαι; κοῖος μέν τις τοῖσι πολιήτῃσι δόξω εἶναι, κοῖος δέ τις τῇ νεογάμῳ γυναικί; κοίῳ δὲ ἐκείνη δόξει ἀνδρὶ συνοικέειν; ἐμὲ ὦν σὺ ἢ μέτες ἰέναι ἐπὶ τὴν θήρην, ἢ λόγῳ ἀνάπεισον ὅκως μοι ἀμείνω ἐστὶ ταῦτα οὕτω ποιεόμενα.", "st": "1.37"}, {"sp": "N", "t": "ἀμείβεται Κροῖσος τοῖσιδε. ὦ παῖ, οὔτε δειλίην οὔτε ἄλλο οὐδὲν ἄχαρι παριδών, τοι ποιέω ταῦτα, ἀλλά μοι ὄψις ὀνείρου ἐν τῷ ὕπνῳ ἐπιστᾶσα ἔφη σε ὀλιγοχρόνιον ἔσεσθαι· ὑπὸ γὰρ αἰχμῆς σιδηρέης ἀπολέεσθαι. πρὸς ὧν τὴν ὄψιν ταύτην τόν τε γάμον τοι τοῦτον ἔσπευσα καὶ ἐπὶ τὰ παραλαμβανόμενα οὐκ ἀποπέμπω, φυλακὴν ἔχων, εἴ κως δυναίμην ἐπὶ τῆς ἐμῆς σε ζόης διακλέψαι. εἷς γὰρ μοι μοῦνος τυγχάνεις ἐὼν παῖς· τὸν γὰρ δὴ ἕτερον διεφθαρμένον τὴν ἀκοὴν οὐκ εἶναί μοι λογίζομαι.", "st": "1.38"}, {"sp": "N", "t": "ἀμείβεται ὁ νεηνίης τοῖσιδε. συγγνώμη μὲν ὦ πάτερ τοι, ἰδόντι γε ὄψιν τοιαύτην, περὶ ἐμὲ φυλακὴν ἔχειν· τὸ δὲ οὐ μανθάνεις ἀλλὰ λέληθέ σε τὸ ὄνειρον, ἐμέ τοί δίκαιον ἐστί φράζειν. φής τοι τὸ ὄνειρον ὑπὸ αἰχμῆς σιδηρέης φάναι ἐμὲ τελευτήσειν. ὑὸς δὲ κοῖαι μὲν εἰσὶ χεῖρες, κοίη δὲ αἰχμὴ σιδηρέη τὴν σὺ φοβέαι; εἰ μὲν γὰρ ὑπὸ ὀδόντος τοι εἶπε τελευτήσειν με, ἢ ἄλλου τευ ὅ τι τούτῳ ἔοικε, χρῆν δή σε ποιέειν τὰ ποιέεις· νῦν δὲ ὑπὸ αἰχμῆς. ἐπείτε ὦν οὐ πρὸς ἄνδρας ἡμῖν γίνεται ἡ μάχη, μέτες με.", "st": "1.39"}, {"sp": "N", "t": "ἀμείβεται Κροῖσος ὦ παῖ, ἔστι τῇ με νικᾷς γνώμην ἀποφαίνων περὶ τοῦ ἐνυπνίου. ὡς ὦν νενικημένος ὑπὸ σέο μεταγινώσκω, μετίημί τε σὲ ἰέναι ἐπὶ τὴν ἄγρην.", "st": "1.40"}, {"sp": "N", "t": "εἴπας δὲ ταῦτα ὁ Κροῖσος μεταπέμπεται τὸν Φρύγα Ἄδρηστον, ἀπικομένῳ δέ οἱ λέγει τάδε. Ἄδρηστε, ἐγώ σε συμφορῇ, πεπληγμένον ἀχάρι, τήν τοι οὐκ ὀνειδίζω, ἐκάθηρα καὶ οἰκίοισι ὑποδεξάμενος ἔχω, παρέχων πᾶσαν δαπάνην. νῦν ὦν (ὀφείλεις γὰρ ἐμοῦ προποιήσαντος χρηστὰ ἐς σὲ χρηστοῖσί με ἀμείβεσθαι) φύλακα παιδός σε τοῦ ἐμοῦ χρηίζω γενέσθαι ἐς ἄγρην ὁρμωμένου, μή τινες κατ’ ὁδὸν κλῶπες κακοῦργοι ἐπὶ δηλήσι φανέωσι ὑμῖν. πρὸς δὲ τούτῳ καὶ σέ τοι χρεόν ἐστι ἰέναι ἔνθα ἀπολαμπρυνέαι τοῖσι ἔργοισι· πατρώιόν τε γάρ τοι ἐστὶ καὶ προσέτι ῥώμη ὑπάρχει.", "st": "1.41"}, {"sp": "N", "t": "ἀμείβεται ὁ Ἄδρηστος ὦ βασιλεῦ, ἄλλως μὲν ἔγωγε ἂν οὐκ ἤια ἐς ἄεθλον τοιόνδε· οὔτε γὰρ συμφορῇ τοιῇδε κεχρημένον οἰκός ἐστι ἐς ὁμήλικας εὖ πρήσσοντας ἰέναι, οὔτε τὸ βούλεσθαι πάρα, πολλαχῇ τε ἂν ἶσχον ἐμεωυτόν. νῦν δέ, ἐπείτε σὺ σπεύδεις καὶ δεῖ τοί χαρίζεσθαι, ὀφείλω γάρ σε ἀμείβεσθαι χρηστοῖσι, ποιέειν εἰμὶ ἕτοιμος ταῦτα, παῖδα τε σόν, τὸν διακελεύεαι φυλάσσειν, ἀπήμονα τοῦ φυλάσσοντος εἵνεκεν προσδόκα τοι ἀπονοστήσειν.", "st": "1.42"}, {"sp": "N", "t": "τοιούτοισι ἐπείτε οὗτος ἀμείψατο Κροῖσον, ἤισαν μετὰ ταῦτα ἐξηρτυμένοι λογάσι τε νεηνίῃσι καὶ κυσί. ἀπικόμενοι δὲ ἐς τὸν Ὄλυμπον τὸ ὄρος ἐζήτεον τὸ θηρίον, εὑρόντες δὲ καὶ περιστάντες αὐτὸ κύκλῳ ἐσηκόντιζον. ἔνθα δὴ ὁ ξεῖνος, οὗτος δὴ ὁ καθαρθεὶς τὸν φόνον, καλεόμενος δὲ Ἄδρηστος, ἀκοντίζων τὸν ὗν τοῦ μὲν ἁμαρτάνει, τυγχάνει δὲ τοῦ Κροίσου παιδός. ὃ μὲν δὴ βληθεὶς τῇ αἰχμῇ ἐξέπλησε τοῦ ὀνείρου τὴν φήμην, ἔθεε δέ τις ἀγγελέων τῷ Κροίσῳ τὸ γεγονός, ἀπικόμενος δὲ ἐς τὰς Σάρδις τὴν τε μάχην καὶ τὸν τοῦ παιδὸς μόρον ἐσήμηνέ οἱ. ὁ δὲ Κροῖσος τῳ θανάτῳ τοῦ παιδὸς συντεταραγμένος μᾶλλον τι ἐδεινολογέετο ὅτι μιν ἀπέκτεινε τὸν αὐτὸς φόνου ἐκάθηρε· περιημεκτέων δὲ τῇ συμφορῇ δεινῶς ἐκάλεε μὲν Δία καθάρσιον μαρτυρόμενος τὰ ὑπὸ τοῦ ξείνου πεπονθὼς εἴη ἐκάλεε δὲ ἐπίστιόν τε καὶ ἑταιρήιον, τὸν αὐτὸν τοῦτον ὀνομάζων θεόν, τὸν μὲν ἐπίστιον καλέων, διότι δὴ οἰκίοισι ὑποδεξάμενος τὸν ξεῖνον φονέα τοῦ παιδὸς ἐλάνθανε βόσκων, τὸν δὲ ἑταιρήιον, ὡς φύλακα συμπέμψας αὐτὸν εὑρήκοι πολεμιώτατον.", "st": "1.43"}, {"sp": "N", "t": "παρῆσαν δὲ μετὰ τοῦτο οἱ Λυδοὶ φέροντες τὸν νεκρόν, ὄπισθε δὲ εἵπετό οἱ ὁ φονεύς. στὰς δὲ οὗτος πρὸ τοῦ νεκροῦ παρεδίδου ἑωυτὸν Κροίσῳ προτείνων τὰς χεῖρας, ἐπικατασφάξαι μιν κελεύων τῷ νεκρῷ, λέγων τήν τε προτέρην ἑωυτοῦ συμφορήν, καὶ ὡς ἐπ’ ἐκείνῃ τὸν καθήραντα ἀπολωλεκὼς εἴη, οὐδέ οἱ εἴη βιώσιμον. Κροῖσος δὲ τούτων ἀκούσας τόν τε Ἄδρηστον κατοικτείρει, καίπερ ἐὼν ἐν κακῷ οἰκηίῳ τοσούτῳ καὶ λέγει πρὸς αὐτόν ἔχω ὦ ξεῖνε παρὰ σεῦ πᾶσαν τὴν δίκην, ἐπειδὴ σεωυτοῦ καταδικάζεις θάνατον. εἶς δὲ οὐ σύ μοι τοῦδε τοῦ κακοῦ αἴτιος, εἰ μὴ ὅσον ἀέκων ἐξεργάσαο, ἀλλὰ θεῶν κού τις, ὅς μοι καὶ πάλαι προεσήμαινε τὰ μέλλοντα ἔσεσθαι. Κροῖσος μέν νυν ἔθαψε ὡς οἰκὸς ἦν τὸν ἑωυτοῦ παῖδα· Ἄδρηστος δὲ ὁ Γορδίεω τοῦ Μίδεω, οὗτος δὴ ὁ φονεὺς μὲν τοῦ ἑωυτοῦ ἀδελφεοῦ γενόμενος φονεὺς δὲ τοῦ καθήραντος, ἐπείτε ἡσυχίη τῶν ἀνθρώπων ἐγένετο περὶ τὸ σῆμα, συγγινωσκόμενος ἀνθρώπων εἶναι τῶν αὐτὸς ᾔδεε βαρυσυμφορώτατος, ἐπικατασφάζει τῷ τύμβῳ ἑωυτόν.", "st": "1.45"}, {"sp": "N", "t": "Κροῖσος δὲ ἐπὶ δύο ἔτεα ἐν πένθεϊ μεγάλῳ κατῆστο τοῦ παιδὸς ἐστερημένος. μετὰ δὲ ἡ Ἀστυάγεος τοῦ Κυαξάρεω ἡγεμονίη καταιρεθεῖσα ὑπὸ Κύρου τοῦ Καμβύσεω καὶ τὰ τῶν Περσέων πρήγματα αὐξανόμενα πένθεος μὲν Κροῖσον ἀπέπαυσε, ἐνέβησε δὲ ἐς φροντίδα, εἴ κως δύναιτο, πρὶν μεγάλους γενέσθαι τοὺς Πέρσας, καταλαβεῖν αὐτῶν αὐξανομένην τὴν δύναμιν.", "st": "1.46"}, {"sp": "N", "t": "μετὰ ὦν τὴν διάνοιαν ταύτην αὐτίκα ἀπεπειρᾶτο τῶν μαντείων τῶν τε ἐν Ἕλλησι καὶ τοῦ ἐν Λιβύῃ, διαπέμψας ἄλλους ἄλλῃ, τοὺς μὲν ἐς Δελφοὺς ἰέναι, τοὺς δὲ ἐς Ἄβας τὰς Φωκέων, τοὺς δὲ ἐς Δωδώνην· οἳ δὲ τινὲς ἐπέμποντο παρὰ τε Ἀμφιάρεων καὶ παρὰ Τροφώνιον, οἳ δὲ τῆς Μιλησίης ἐς Βραγχίδας. ταῦτα μέν νυν τὰ Ἑλληνικὰ μαντήια ἐς τὰ ἀπέπεμψε μαντευσόμενος Κροῖσος· Λιβύης δὲ παρὰ Ἄμμωνα ἀπέστελλε ἄλλους χρησομένους. διέπεμπε δὲ πειρώμενος τῶν μαντηίων ὅ τι φρονέοιεν, ὡς εἰ φρονέοντα τὴν ἀληθείην εὑρεθείη, ἐπείρηται σφέα δεύτερα πέμπων εἰ ἐπιχειρέοι ἐπὶ Πέρσας στρατεύεσθαι.", "st": "1.46.2"}, {"sp": "N", "t": "ἐντειλάμενος δὲ τοῖσι Λυδοῖσι τάδε ἀπέπεμπε ἐς τὴν διάπειραν τῶν χρηστηρίων, ἀπ’ ἧς ἂν ἡμέρης ὁρμηθέωσι ἐκ Σαρδίων, ἀπὸ ταύτης ἡμερολογέοντας τὸν λοιπὸν χρόνον ἑκατοστῇ ἡμέρῃ χρᾶσθαι τοῖσι χρηστηρίοισι, ἐπειρωτῶντας ὅ τι ποιέων τυγχάνοι ὁ Λυδῶν βασιλεὺς Κροῖσος ὁ Ἀλυάττεω· ἅσσα δ’ ἂν ἕκαστα τῶν χρηστηρίων θεσπίσῃ, συγγραψαμένους ἀναφέρειν παρ’ ἑωυτόν. ὅ τι μέν νυν τὰ λοιπὰ τῶν χρηστηρίων ἐθέσπισε, οὐ λέγεται πρὸς οὐδαμῶν· ἐν δὲ Δελφοῖσι ὡς ἐσῆλθον τάχιστα ἐς τὸ μέγαρον οἱ Λυδοὶ χρησόμενοι τῷ θεῷ καὶ ἐπειρώτων τὸ ἐντεταλμένον, ἡ Πυθίη ἐν ἑξαμέτρῳ τόνῳ λέγει τάδε.", "st": "1.47"}, {"sp": "N", "t": "οἶδα δ’ ἐγὼ ψάμμου τ’ ἀριθμὸν καὶ μέτρα θαλάσσης,<br>καὶ κωφοῦ συνίημι, καὶ οὐ φωνεῦντος ἀκούω.<br>ὀδμή μ’ ἐς φρένας ἦλθε κραταιρίνοιο χελώνης<br>ἑψομένης ἐν χαλκῷ ἅμ’ ἀρνείοισι κρέεσσιν,<br>ᾗ χαλκὸς μὲν ὑπέστρωται, χαλκὸν δ’ ἐπιέσται.", "st": "1.47.3"}, {"sp": "N", "t": "ταῦτα οἱ Λυδοὶ θεσπισάσης τῆς Πυθίης συγγραψάμενοι οἴχοντο ἀπιόντες ἐς τὰς Σάρδις. ὡς δὲ καὶ ὧλλοι οἱ περιπεμφθέντες παρῆσαν φέροντες τοὺς χρησμούς, ἐνθαῦτα ὁ Κροῖσος ἕκαστα ἀναπτύσσων ἐπώρα τῶν συγγραμμάτων, τῶν μὲν δὴ οὐδὲν προσίετό μιν· ὁ δὲ ὡς τὸ ἐκ Δελφῶν ἤκουσε, αὐτίκα προσεύχετό τε καὶ προσεδέξατο, νομίσας μοῦνον εἶναι μαντήιον τὸ ἐν Δελφοῖσι, ὅτι οἱ ἐξευρήκεε τὰ αὐτὸς ἐποίησε. ἐπείτε γὰρ δὴ διέπεμψε παρὰ τὰ χρηστήρια τοὺς θεοπρόπους, φυλάξας τὴν κυρίην τῶν ἡμερέων ἐμηχανᾶτο τοιάδε· ἐπινοήσας τὰ ἦν ἀμήχανον ἐξευρεῖν τε καὶ ἐπιφράσασθαι, χελώνην καὶ ἄρνα κατακόψας ὁμοῦ ἧψε αὐτὸς ἐν λέβητι χαλκέῳ, χάλκεον ἐπίθημα ἐπιθείς.", "st": "1.48"}, {"sp": "N", "t": "τὰ μὲν δὴ ἐκ Δελφῶν οὕτω τῷ, Κροίσῳ ἐχρήσθη· κατὰ δὲ τὴν Ἀμφιάρεω τοῦ μαντηίου ὑπόκρισιν, οὐκ ἔχω εἰπεῖν ὅ τι τοῖσι Λυδοῖσι ἔχρησε ποιήσασι περὶ τὸ ἱρὸν τὰ νομιζόμενα (οὐ γὰρ ὦν οὐδὲ τοῦτο λέγεται), ἄλλο γε ἢ ὅτι καὶ τοῦτο ἐνόμισε μαντήιον ἀψευδὲς ἐκτῆσθαι.", "st": "1.49"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα θυσίῃσι μεγάλῃσι τὸν ἐν Δελφοῖσι θεὸν ἱλάσκετο· κτήνεά τε γὰρ τὰ θύσιμα πάντα τρισχίλια ἔθυσε, κλίνας τε ἐπιχρύσους καὶ ἐπαργύρους καὶ φιάλας χρυσέας καὶ εἵματα πορφύρεα καὶ κιθῶνας, νήσας πυρὴν μεγάλην, κατέκαιε, ἐλπίζων τὸν θεὸν μᾶλλον τι τούτοισι ἀνακτήσεσθαι· Λυδοῖσι τε πᾶσι προεῖπε θύειν πάντα τινὰ αὐτῶν τούτῳ ὅ τι ἔχοι ἕκαστος. ὡς δὲ ἐκ τῆς θυσίης ἐγένετο, καταχεάμενος χρυσὸν ἄπλετον ἡμιπλίνθια ἐξ αὐτοῦ ἐξήλαυνε, ἐπὶ μὰν τὰ μακρότερα ποιέων ἑξαπάλαιστα, ἐπὶ δὲ τὰ βραχύτερα τριπάλαιστα, ὕψος δὲ παλαιστιαῖα. ἀριθμὸν δὲ ἑπτακαίδεκα καὶ ἑκατόν, καὶ τούτων ἀπέφθου χρυσοῦ τέσσερα, τρίτον ἡμιτάλαντον ἕκαστον ἕλκοντα, τὰ δὲ ἄλλα ἡμιπλίνθια λευκοῦ χρυσοῦ, σταθμὸν διτάλαντα. ἐποιέετο δὲ καὶ λέοντος εἰκόνα χρυσοῦ ἀπέφθου ἕλκουσαν σταθμὸν τάλαντα δέκα. οὗτος ὁ λέων, ἐπείτε κατεκαίετο ὁ ἐν Δελφοῖσι νηός, κατέπεσε ἀπὸ τῶν ἡμιπλινθίων (ἐπὶ γὰρ τούτοισι ἵδρυτο), καὶ νῦν κεῖται ἐν τῷ Κορινθίων θησαυρῷ, ἕλκων σταθμὸν ἕβδομον ἡμιτάλαντον· ἀπετάκη γὰρ αὐτοῦ τέταρτον ἡμιτάλαντον.", "st": "1.50"}, {"sp": "N", "t": "ἐπιτελέσας δὲ ὁ Κροῖσος ταῦτα ἀπέπεμπε ἐς Δελφούς, καὶ τάδε ἄλλα ἅμα τοῖσι, κρητῆρας δύο μεγάθεϊ μεγάλους, χρύσεον καὶ ἀργύρεον, τῶν ὁ μὲν χρύσεος ἔκειτο ἐπὶ δεξιὰ ἐσιόντι ἐς τὸν νηόν, ὁ δὲ ἀργύρεος ἐπ’ ἀριστερά. μετεκινήθησαν δὲ καὶ οὗτοι ὑπὸ τὸν νηὸν κατακαέντα καὶ ὁ μὲν χρύσεος κεῖται ἐν τῷ Κλαζομενίων θησαυρῷ, ἕλκων σταθμὸν εἴνατον ἡμιτάλαντον καὶ ἔτι δυώδεκα μνέας, ὁ δὲ ἀργύρεος ἐπὶ τοῦ προνηίου τῆς γωνίης, χωρέων ἀμφορέας ἑξακοσίους· ἐπικίρναται γὰρ ὑπὸ Δελφῶν Θεοφανίοισι. φασὶ δὲ μιν Δελφοὶ Θεοδώρου τοῦ Σαμίου ἔργον εἶναι, καὶ ἐγὼ δοκέω· οὐ γὰρ τὸ συντυχὸν φαίνεταί μοι ἔργον εἶναι. καὶ πίθους τε ἀργυρέους τέσσερας ἀπέπεμψε, οἳ ἐν τῷ Κορινθίων θησαυρῷ ἑστᾶσι, καὶ περιρραντήρια δύο ἀνέθηκε, χρύσεόν τε καὶ ἀργύρεον, τῶν τῷ χρυσέῳ ἐπιγέγραπται Λακεδαιμονίων φαμένων εἶναι ἀνάθημα, οὐκ ὀρθῶς λέγοντες· ἔστι γὰρ καὶ τοῦτο Κροίσου, ἐπέγραψε δὲ τῶν τις Δελφῶν Λακεδαιμονίοισι βουλόμενος χαρίζεσθαι, τοῦ ἐπιστάμενος τὸ οὔνομα οὐκ ἐπιμνήσομαι. ἀλλ’ ὁ μὲν παῖς, δι’ οὗ τῆς χειρὸς ῥέει τὸ ὕδωρ, Λακεδαιμονίων ἐστί, οὐ μέντοι τῶν γε περιρραντηρίων οὐδέτερον. ἄλλα τε ἀναθήματα οὐκ ἐπίσημα πολλὰ ἀπέπεμψε ἅμα τούτοισι ὁ Κροῖσος, καὶ χεύματα ἀργύρεα κυκλοτερέα, καὶ δὴ καὶ γυναικὸς εἴδωλον χρύσεον τρίπηχυ, τὸ Δελφοὶ τῆς ἀρτοκόπου τῆς Κροίσου εἰκόνα λέγουσι εἶναι. πρὸς δὲ καὶ τῆς ἑωυτοῦ γυναικὸς τὰ ἀπὸ τῆς δειρῆς ἀνέθηκε ὁ Κροῖσος καὶ τὰς ζώνας.", "st": "1.51"}, {"sp": "N", "t": "ταῦτα μὲν ἐς Δελφοὺς ἀπέπεμψε, τῷ δὲ Ἀμφιάρεῳ, πυθόμενος αὐτοῦ τήν τε ἀρετὴν καὶ τὴν πάθην, ἀνέθηκε σάκος τε χρύσεον πᾶν ὁμοίως καὶ αἰχμὴν στερεὴν πᾶσαν χρυσέην, τὸ ξυστὸν τῇσι λόγχῃσι ἐὸν ὁμοίως χρύσεον· τὰ ἔτι καὶ ἀμφότερα ἐς ἐμὲ ἦν κείμενα ἐν Θήβῃσι καὶ Θηβέων ἐν τῳ νηῷ τοῦ Ἰσμηνίου Ἀπόλλωνος.", "st": "1.52"}, {"sp": "N", "t": "τοῖσι δὲ ἄγειν μέλλουσι τῶν Λυδῶν ταῦτα τὰ δῶρα ἐς τὰ ἱρὰ ἐνετέλλετο ὁ Κροῖσος ἐπειρωτᾶν τὰ χρηστήρια εἰ στρατεύηται ἐπὶ Πέρσας Κροῖσος καὶ εἴ τινα στρατὸν ἀνδρῶν προσθέοιτο φίλον, ὡς δὲ ἀπικόμενοι ἐς τὰ ἀπεπέμφθησαν, οἱ Λυδοὶ ἀνέθεσαν τὰ ἀναθήματα, ἐχρέωντο τοῖσι χρηστηρίοισι λέγοντες Κροῖσος ὁ Λυδῶν τε καὶ ἄλλων ἐθνέων βασιλεύς, νομίσας τάδε μαντήια εἶναι μοῦνα ἐν ἀνθρώποισι, ὑμῖν τε ἄξια δῶρα ἔδωκε τῶν ἐξευρημάτων, καὶ νῦν ὑμέας ἐπειρωτᾷ εἰ στρατεύηται ἐπὶ Πέρσας καὶ εἴ τινα στρατὸν ἀνδρῶν προσθέοιτο σύμμαχον. οἳ μὲν ταῦτα ἐπειρώτων, τῶν δὲ μαντηίων ἀμφοτέρων ἐς τὠυτὸ αἱ γνῶμαι συνέδραμον, προλέγουσαι Κροίσῳ, ἢν στρατεύηται ἐπὶ Πέρσας, μεγάλην ἀρχὴν μιν καταλύσειν· τοὺς δὲ Ἑλλήνων δυνατωτάτους συνεβούλευόν οἱ ἐξευρόντα φίλους προσθέσθαι.", "st": "1.53"}, {"sp": "N", "t": "ἐπείτε δὲ ἀνενειχθέντα τὰ θεοπρόπια ἐπύθετο ὁ Κροῖσος, ὑπερήσθη τε τοῖσι χρηστηρίοισι, πάγχυ τε ἐλπίσας καταλύσειν τὴν Κύρου βασιληίην, πέμψας αὖτις ἐς Πυθὼ Δελφοὺς δωρέεται, πυθόμενος αὐτῶν τὸ πλῆθος, κατ’ ἄνδρα δύο στατῆρσι ἕκαστον χρυσοῦ. Δελφοὶ δὲ ἀντὶ τούτων ἔδοσαν Κροίσῳ καὶ Λυδοῖσι προμαντηίην καὶ ἀτελείην καὶ προεδρίην, καὶ ἐξεῖναι τῷ βουλομένῳ αὐτῶν γίνεσθαι Δελφὸν ἐς τὸν αἰεὶ χρόνον.", "st": "1.54"}, {"sp": "N", "t": "δωρησάμενος δὲ τοὺς Δελφοὺς ὁ Κροῖσος ἐχρηστηριάζετο τὸ τρίτον· ἐπείτε γὰρ δὴ παρέλαβε τοῦ μαντείου ἀληθείην, ἐνεφορέετο αὐτοῦ. ἐπειρώτα δὲ τάδε χρηστηριαζόμενος, εἴ οἱ πολυχρόνιος ἔσται ἡ μουναρχίη. ἡ δὲ Πυθίη οἱ χρᾷ τάδε.", "st": "1.55"}, {"sp": "N", "t": "ἀλλ’ ὅταν ἡμίονος βασιλεὺς Μήδοισι γένηται,<br>καὶ τότε, Λυδὲ ποδαβρέ, πολυψήφιδα παρ’ Ἕρμον<br>φεύγειν μηδὲ μένειν μηδ’ αἰδεῖσθαι κακός εἶναι.", "st": "1.55b"}, {"sp": "N", "t": "τούτοισι ἐλθοῦσι τοῖσι ἔπεσι ὁ Κροῖσος πολλόν τι μάλιστα πάντων ἥσθη, ἐλπίζων ἡμίονον οὐδαμὰ ἀντ’ ἀνδρὸς βασιλεύσειν Μήδων, οὐδ’ ὦν αὐτὸς οὐδὲ οἱ ἐξ αὐτοῦ παύσεσθαι κοτὲ τῆς ἀρχῆς. μετὰ δὲ ταῦτα ἐφρόντιζε ἱστορέων τοὺς ἂν Ἑλλήνων δυνατωτάτους ἐόντας προσκτήσαιτο φίλους, ἱστορέων δὲ εὕρισκε Λακεδαιμονίους καὶ Ἀθηναίους προέχοντας τοὺς μὲν τοῦ Δωρικοῦ γένεος τοὺς δὲ τοῦ Ἰωνικοῦ. ταῦτα γὰρ ἦν τὰ προκεκριμένα, ἐόντα τὸ ἀρχαῖον τὸ μὲν Πελασγικὸν τὸ δὲ Ἑλληνικὸν ἔθνος. καὶ τὸ μὲν οὐδαμῇ κω ἐξεχώρησε, τὸ δὲ πολυπλάνητον κάρτα. ἐπὶ μὲν γὰρ Δευκαλίωνος βασιλέος οἴκεε γῆν τὴν Φθιῶτιν, ἐπὶ δὲ Δώρου τοῦ Ἕλληνος τὴν ὑπὸ τὴν Ὄσσαν τε καὶ τὸν Ὄλυμπον χώρην, καλεομένην δὲ Ἱστιαιῶτιν· ἐκ δὲ τῆς Ἱστιαιώτιδος ὡς ἐξανέστη ὑπὸ Καδμείων, οἴκεε ἐν Πίνδῳ Μακεδνὸν καλεόμενον· ἐνθεῦτεν δὲ αὖτις ἐς τὴν Δρυοπίδα μετέβη καὶ ἐκ τῆς Δρυοπίδος οὕτω ἐς Πελοπόννησον ἐλθὸν Δωρικὸν ἐκλήθη.", "st": "1.56"}, {"sp": "N", "t": "ἥντινα δὲ γλῶσσαν ἵεσαν οἱ Πελασγοί, οὐκ ἔχω ἀτρεκέως εἰπεῖν. εἰ δὲ χρεόν ἐστι τεκμαιρόμενον λέγειν τοῖσι νῦν ἔτι ἐοῦσι Πελασγῶν τῶν ὑπὲρ Τυρσηνῶν Κρηστῶνα πόλιν οἰκεόντων, οἳ ὅμουροι κοτὲ ἦσαν τοῖσι νῦν Δωριεῦσι καλεομένοισι (οἴκεον δὲ τηνικαῦτα γῆν τὴν νῦν Θεσσαλιῶτιν καλεομένην), καὶ τῶν Πλακίην τε καὶ Σκυλάκην Πελασγῶν οἰκησάντων ἐν Ἑλλησπόντῳ, οἳ σύνοικοι ἐγένοντο Ἀθηναίοισι, καὶ ὅσα ἄλλα Πελασγικὰ ἐόντα πολίσματα τὸ οὔνομα μετέβαλε· εἰ τούτοισι τεκμαιρόμενον δεῖ λέγειν, ἦσαν οἱ Πελασγοὶ βάρβαρον γλῶσσαν ἱέντες. εἰ τοίνυν ἦν καὶ πᾶν τοιοῦτο τὸ Πελασγικόν, τὸ Ἀττικὸν ἔθνος ἐὸν Πελασγικὸν ἅμα τῇ μεταβολῇ τῇ ἐς Ἕλληνας καὶ τὴν γλῶσσαν μετέμαθε. καὶ γὰρ δὴ οὔτε οἱ Κρηστωνιῆται οὐδαμοῖσι τῶν νῦν σφέας περιοικεόντων εἰσὶ ὁμόγλωσσοι οὔτε οἱ Πλακιηνοί, σφίσι δὲ ὁμόγλωσσοι· δηλοῦσί τε ὅτι τὸν ἠνείκαντο γλώσσης χαρακτῆρα μεταβαίνοντες ἐς ταῦτα τὰ χωρία, τοῦτον ἔχουσι ἐν φυλακῇ.", "st": "1.57"}, {"sp": "N", "t": "τὸ δὲ Ἑλληνικὸν γλώσσῃ μὲν ἐπείτε ἐγένετο αἰεί κοτε τῇ αὐτῇ διαχρᾶται, ὡς ἐμοὶ καταφαίνεται εἶναι· ἀποσχισθὲν μέντοι ἀπὸ τοῦ Πελασγικοῦ ἐόν ἀσθενές, ἀπό σμικροῦ τεο τὴν ἀρχὴν ὁρμώμενον αὔξηται ἐς πλῆθος τῶν ἐθνέων, Πελασγῶν μάλιστα προσκεχωρηκότων αὐτῷ καὶ ἄλλων ἐθνέων βαρβάρων συχνῶν. πρόσθε δὲ ὦν ἔμοιγε δοκέει οὐδὲ τὸ Πελασγικὸν ἔθνος, ἐὸν βάρβαρον, οὐδαμὰ μεγάλως αὐξηθῆναι.", "st": "1.58"}, {"sp": "N", "t": "τούτων δὴ ὦν τῶν ἐθνέων τὸ μὲν Ἀττικὸν κατεχόμενόν τε καὶ διεσπασμένον ἐπυνθάνετο ὁ Κροῖσος ὑπὸ Πεισιστράτου τοῦ Ἱπποκράτεος τοῦτον τὸν χρόνον τυραννεύοντος Ἀθηναίων. Ἱπποκράτεϊ γὰρ ἐόντι ἰδιώτῃ καὶ θεωρέοντι τὰ Ὀλύμπια τέρας ἐγένετο μέγα· θύσαντος γὰρ αὐτοῦ τὰ ἱρὰ οἱ λέβητες ἐπεστεῶτες καὶ κρεῶν τε ἐόντες ἔμπλεοι καὶ ὕδατος ἄνευ πυρὸς ἔζεσαν καὶ ὑπερέβαλον. Χίλων δὲ ὁ Λακεδαιμόνιος παρατυχὼν καὶ θεησάμενος τὸ τέρας συνεβούλευε Ἱπποκράτεϊ πρῶτα μὲν γυναῖκα μὴ ἄγεσθαι τεκνοποιὸν ἐς τὰ οἰκία, εἰ δὲ τυγχάνει ἔχων, δευτέρα τὴν γυναῖκα ἐκπέμπειν, καὶ εἴ τίς οἱ τυγχάνει ἐὼν παῖς, τοῦτον ἀπείπασθαι. οὔκων ταῦτα παραινέσαντος Χίλωνος πείθεσθαι θέλειν τὸν Ἱπποκράτεα· γενέσθαι οἱ μετὰ ταῦτα τὸν Πεισίστρατον τοῦτον, ὃς στασιαζόντων τῶν παράλων καὶ τῶν ἐκ τοῦ πεδίου Ἀθηναίων, καὶ τῶν μὲν προεστεῶτος Μεγακλέος τοῦ Ἀλκμέωνος, τῶν δὲ ἐκ τοῦ πεδίου Λυκούργου Ἀριστολαΐδεω, καταφρονήσας τὴν τυραννίδα ἤγειρε τρίτην στάσιν· συλλέξας δὲ στασιώτας καὶ τῷ λόγῳ τῶν ὑπερακρίων προστὰς μηχανᾶται τοιάδε. τρωματίσας ἑωυτόν τε καὶ ἡμιόνους ἤλασε ἐς τὴν ἀγορὴν τὸ ζεῦγος ὡς ἐκπεφευγὼς τοὺς ἐχθρούς, οἵ μιν ἐλαύνοντα ἐς ἀγρὸν ἠθέλησαν ἀπολέσαι δῆθεν, ἐδέετό τε τοῦ δήμου φυλακῆς τινος πρὸς αὐτοῦ κυρῆσαι, πρότερον εὐδοκιμήσας ἐν τῇ πρὸς Μεγαρέας γενομένῃ στρατηγίῃ, Νίσαιάν τε ἑλὼν καὶ ἄλλα ἀποδεξάμενος μεγάλα ἔργα. ὁ δὲ δῆμος ὁ τῶν Ἀθηναίων ἐξαπατηθεὶς ἔδωκέ οἱ τῶν ἀστῶν καταλέξας ἄνδρας τούτους οἳ δορυφόροι μὲν οὐκ ἐγένοντο Πεισιστράτου, κορυνηφόροι δέ· ξύλων γὰρ κορύνας ἔχοντες εἵποντό οἱ ὄπισθε. συνεπαναστάντες δὲ οὗτοι ἅμα Πεισιστράτῳ ἔσχον τὴν ἀκρόπολιν. ἔνθα δὴ ὁ Πεισίστρατος ἦρχε Ἀθηναίων, οὔτε τιμὰς τὰς ἐούσας συνταράξας οὔτε θέσμια μεταλλάξας, ἐπί τε τοῖσι κατεστεῶσι ἔνεμε τὴν πόλιν κοσμέων καλῶς τε καὶ εὖ.", "st": "1.59"}, {"sp": "N", "t": "μετὰ δὲ οὐ πολλὸν χρόνον τὠυτὸ φρονήσαντες οἵ τε τοῦ Μεγακλέος στασιῶται καὶ οἱ τοῦ Λυκούργου ἐξελαύνουσί μιν. οὕτω μὲν Πεισίστρατος ἔσχε τὸ πρῶτον Ἀθήνας, καὶ τὴν τυραννίδα οὔκω κάρτα ἐρριζωμένην ἔχων ἀπέβαλε. οἳ δὲ ἐξελάσαντες Πεισίστρατον αὖτις ἐκ νέης ἐπ’ ἀλλήλοισι ἐστασίασαν. περιελαυνόμενος δὲ τῇ στάσι ὁ Μεγακλέης ἐπεκηρυκεύετο Πεισιστράτῳ, εἰ βούλοιτό οἱ τὴν θυγατέρα ἔχειν γυναῖκα ἐπὶ τῇ τυραννίδι. ἐνδεξαμένου δὲ τὸν λόγον καὶ ὁμολογήσαντος ἐπὶ τούτοισι Πεισιστράτου, μηχανῶνται δὴ ἐπὶ τῇ κατόδῳ πρῆγμα εὐηθέστατον, ὡς ἐγὼ εὑρίσκω, μακρῷ, ἐπεί γε ἀπεκρίθη ἐκ παλαιτέρου τοῦ βαρβάρου ἔθνεος τὸ Ἑλληνικὸν ἐὸν καὶ δεξιώτερον καὶ εὐηθείης ἠλιθίου ἀπηλλαγμένον μᾶλλον, εἰ καὶ τότε γε οὗτοι ἐν Ἀθηναίοισι τοῖσι πρώτοισι λεγομένοισι εἶναι Ἑλλήνων σοφίην μηχανῶνται τοιάδε. ἐν τῷ δήμῳ τῷ Παιανιέι ἦν γυνὴ τῇ οὔνομα ἦν Φύη, μέγαθος ἀπὸ τεσσέρων πηχέων ἀπολείπουσα τρεῖς δακτύλους καὶ ἄλλως εὐειδής· ταύτην τὴν γυναῖκα σκευάσαντες πανοπλίῃ, ἐς ἅρμα ἐσβιβάσαντες καὶ προδέξαντες σχῆμα οἷόν τι ἔμελλε εὐπρεπέστατον φανέεσθαι ἔχουσα, ἤλαυνον ἐς τὸ ἄστυ, προδρόμους κήρυκας προπέμψαντες· οἳ τὰ ἐντεταλμένα ἠγόρευον ἀπικόμενοι ἐς τὸ ἄστυ, λέγοντες τοιάδε· ὦ Ἀθηναῖοι, δέκεσθε ἀγαθῷ νόῳ Πεισίστρατον, τὸν αὐτὴ ἡ Ἀηθναίη τιμήσασα ἀνθρώπων μάλιστα κατάγει ἐς τὴν ἑωυτῆς ἀκρόπολιν. οἳ μὲν δὴ ταῦτα διαφοιτέοντες ἔλεγον· αὐτίκα δὲ ἔς τε τοὺς δήμους φάτις ἀπίκετο ὡς Ἀθηναίη Πεισίστρατον κατάγει, καὶ οἱ ἐν τῷ ἄστεϊ πειθόμενοι τὴν γυναῖκα εἶναι αὐτὴν τὴν θεὸν προσεύχοντό τε τὴν ἄνθρωπον καὶ ἐδέκοντο Πεισίστρατον.", "st": "1.60"}, {"sp": "N", "t": "ἀπολαβὼν δὲ τὴν τυραννίδα τρόπῳ τῷ εἰρημένῳ ὁ Πεισίστρατος κατὰ τὴν ὁμολογίην τὴν πρὸς Μεγακλέα γενομένην γαμέει τοῦ Μεγακλέος τὴν θυγατέρα. οἷα δὲ παίδων τέ οἱ ὑπαρχόντων νεηνιέων καὶ λεγομένων ἐναγέων εἶναι τῶν Ἀλκμεωνιδέων, οὐ βουλόμενός οἱ γενέσθαι ἐκ τῆς νεογάμου γυναικὸς τέκνα ἐμίσγετό οἱ οὐ κατὰ νόμον. τὰ μέν νυν πρῶτα ἔκρυπτε ταῦτα ἡ γυνή, μετὰ δὲ εἴτε ἱστορεύσῃ εἴτε καὶ οὒ φράζει τῇ ἑωυτῆς μητρί, ἣ δὲ τῷ ἀνδρί. ὀργῇ δὲ ὡς εἶχε καταλλάσσετο τὴν ἔχθρην τοῖσι στασιώτῃσι. μαθὼν δὲ ὁ Πεισίστρατος τὰ ποιεύμενα ἐπ’ ἑωυτῷ ἀπαλλάσσετο ἐκ τῆς χώρης τὸ παράπαν, ἀπικόμενος δὲ ἐς Ἐρέτριαν ἐβουλεύετο ἅμα τοῖσι παισί. Ἱππίεω δὲ γνώμῃ νικήσαντος ἀνακτᾶσθαι ὀπίσω τὴν τυραννίδα, ἐνθαῦτα ἤγειρον δωτίνας ἐκ τῶν πολίων αἵτινές σφι προαιδέοντό κού τι. πολλῶν δὲ μεγάλα παρασχόντων χρήματα, Θηβαῖοι ὑπερεβάλοντο τῇ δόσι τῶν χρημάτων. μετὰ δέ, οὐ πολλῷ λόγῳ εἰπεῖν, χρόνος διέφυ καὶ πάντα σφι ἐξήρτυτο ἐς τὴν κάτοδον· καὶ γὰρ Ἀργεῖοι μισθωτοὶ ἀπίκοντο ἐκ Πελοποννήσου, καὶ Νάξιός σφι ἀνὴρ ἀπιγμένος ἐθελοντής, τῷ οὔνομα ἦν Λύγδαμις, προθυμίην πλείστην παρείχετο, κομίσας καὶ χρήματα καὶ ἄνδρας.", "st": "1.61"}, {"sp": "N", "t": "ἐξ Ἐρετρίης δὲ ὁρμηθέντες διὰ ἑνδεκάτου ἔτεος ἀπίκοντο ὀπίσω, καὶ πρῶτον τῆς Ἀττικῆς ἴσχουσι Μαραθῶνα. ἐν δὲ τούτῳ τῷ χώρῳ σφι στρατοπεδευομένοισι οἵ τε ἐκ τοῦ ἄστεος στασιῶται ἀπίκοντο ἄλλοι τε ἐκ τῶν δήμων προσέρρεον, τοῖσι ἡ τυραννὶς πρὸ ἐλευθερίης ἦν ἀσπαστότερον. οὗτοι μὲν δὴ συνηλίζοντο, Ἀθηναίων δὲ οἱ ἐκ τοῦ ἄστεος, ἕως μὲν Πεισίστρατος τὰ χρήματα ἤγειρε, καὶ μεταῦτις ὡς ἔσχε Μαραθῶνα, λόγον οὐδένα εἶχον· ἐπείτε δὲ ἐπύθοντο ἐκ τοῦ Μαραθῶνος αὐτὸν πορεύεσθαι ἐπὶ τὸ ἄστυ, οὕτω δὴ βοηθέουσι ἐπ’ αὐτόν. καὶ οὗτοί τε πανστρατιῇ ἤισαν ἐπὶ τοὺς κατιόντας καὶ οἱ ἀμφὶ Πεισίστρατον, ὡς ὁρμηθέντες ἐκ Μαραθῶνος ἤισαν ἐπὶ τὸ ἄστυ, ἐς τὠυτὸ συνιόντες ἀπικνέονται ἐπὶ Παλληνίδος Ἀθηναίης ἱρόν, καὶ ἀντία ἔθεντο τὰ ὅπλα. ἐνθαῦτα θείῃ πομπῇ χρεώμενος παρίσταται Πεισιστράτῳ Ἀμφίλυτος ὁ Ἀκαρνὰν χρησμολόγος ἀνήρ, ὅς οἱ προσιὼν χρᾷ ἐν ἑξαμέτρῳ τόνῳ τάδε λέγων·", "st": "1.62"}, {"sp": "N", "t": "ἔρριπται δ’ ὁ βόλος, τὸ δὲ δίκτυον ἐκπεπέτασται,<br>θύννοι δ’ οἰμήσουσι σεληναίης διὰ νυκτός.", "st": "1.62b"}, {"sp": "N", "t": "ὃ μὲν δή οἱ ἐνθεάζων χρᾷ τάδε, Πεισίστρατος δὲ συλλαβὼν τὸ χρηστήριον καὶ φὰς δέκεσθαι τὸ χρησθὲν ἐπῆγε τὴν στρατιήν. Ἀθηναῖοι δὲ οἱ ἐκ τοῦ ἄστεος πρὸς ἄριστον τετραμμένοι ἦσαν δὴ τηνικαῦτα, καὶ μετὰ τὸ ἄριστον μετεξέτεροι αὐτῶν οἳ μὲν πρὸς κύβους οἳ δὲ πρὸς ὕπνον. οἱ δὲ ἀμφὶ Πεισίστρατον ἐσπεσόντες τοὺς Ἀθηναίους τρέπουσι. φευγόντων δὲ τούτων βουλὴν ἐνθαῦτα σοφωτάτην Πεισίστρατος ἐπιτεχνᾶται, ὅκως μήτε ἁλισθεῖεν ἔτι οἱ Ἀθηναῖοι διεσκεδασμένοι τε εἶεν· ἀναβιβάσας τοὺς παῖδας ἐπὶ ἵππους προέπεμπε, οἳ δὲ καταλαμβάνοντες τοὺς φεύγοντας ἔλεγον τὰ ἐντεταλμένα ὑπὸ Πεισιστράτου, θαρσέειν τε κελεύοντες καὶ ἀπιέναι ἕκαστον ἐπὶ τὰ ἑωυτοῦ.", "st": "1.63"}, {"sp": "N", "t": "πειθομένων δὲ τῶν Ἀθηναίων, οὕτω δὴ Πεισίστρατος τὸ τρίτον σχὼν Ἀθήνας ἐρρίζωσε τὴν τυραννίδα ἐπικούροισί τε πολλοῖσι καὶ χρημάτων συνόδοισι, τῶν μὲν αὐτόθεν τῶν δὲ ἀπὸ Στρυμόνος ποταμοῦ συνιόντων, ὁμήρους τε τῶν παραμεινάντων Ἀθηναίων καὶ μὴ αὐτίκα φυγόντων παῖδας λαβὼν καὶ καταστήσας ἐς Νάξον (καὶ γὰρ ταύτην ὁ Πεισίστρατος κατεστρέψατο πολέμῳ καὶ ἐπέτρεψε Λυγδάμι) πρὸς τε ἔτι τούτοισι τὴν νῆσον Δῆλον καθήρας ἐκ τῶν λογίων καθήρας δὲ ὧδε· ἐπ’ ὅσον ἔποψις τοῦ ἱροῦ εἶχε, ἐκ τούτου τοῦ χώρου παντὸς ἐξορύξας τοὺς νεκροὺς μετεφόρεε ἐς ἄλλον χῶρον τῆς Δήλου. καὶ Πεισίστρατος μὲν ἐτυράννευε Ἀθηνέων, Ἀθηναίων δὲ οἳ μὲν ἐν τῇ μάχη ἐπεπτώκεσαν, οἳ δὲ αὐτῶν μετ’ Ἀλκμεωνιδέων ἔφευγον ἐκ τῆς οἰκηίης.", "st": "1.64"}, {"sp": "N", "t": "τοὺς μέν νυν Ἀθηναίους τοιαῦτα τὸν χρόνον τοῦτον ἐπυνθάνετο ὁ Κροῖσος κατέχοντα, τοὺς δὲ Λακεδαιμονίους ἐκ κακῶν τε μεγάλων πεφευγότας καὶ ἐόντας ἤδη τῷ πολέμῳ κατυπερτέρους Τεγεητέων. ἐπὶ γὰρ Λέοντος βασιλεύοντος καὶ Ἡγησικλέος ἐν Σπάρτῃ τοὺς ἄλλους πολέμους εὐτυχέοντες οἱ Λακεδαιμόνιοι πρὸς Τεγεήτας μούνους προσέπταιον. τὸ δὲ ἔτι πρότερον τούτων καί κακονομώτατοι ἦσαν σχεδὸν πάντων Ἑλλήνων κατά τε σφέας αὐτοὺς καὶ ξείνοισι ἀπρόσμικτοι· μετέβαλον δὲ ὧδε ἐς εὐνομίην. Λυκούργου τῶν Σπαρτιητέων δοκίμου ἀνδρὸς ἐλθόντος ἐς Δελφοὺς ἐπὶ τὸ χρηστήριον, ὡς ἐσήιε ἐς τὸ μέγαρον, εὐθὺς ἡ Πυθίη λέγει τάδε. ἥκεις ὦ Λυκόοργε ἐμὸν ποτὶ πίονα νηόν<br>Ζηνὶ φίλος καὶ πᾶσιν Ὀλύμπια δώματ’ ἔχουσι.<br>δίζω ἤ σε θεὸν μαντεύσομαι ἢ ἄνθρωπον.<br>ἀλλ’ ἔτι καὶ μᾶλλον θεὸν ἔλπομαι, ὦ Λυκόοργε. οἳ μὲν δή τινες πρὸς τούτοισι λέγουσι καὶ φράσαι αὐτῷ τὴν Πυθίην τὸν νῦν κατεστεῶτα κόσμον Σπαρτιήτῃσι. ὡς δ’ αὐτοὶ Λακεδαιμόνιοι λέγουσι, Λυκοῦργον ἐπιτροπεύσαντα Λεωβώτεω, ἀδελφιδέου μὲν ἑωυτοῦ βασιλεύοντος δὲ Σπαρτιητέων, ἐκ Κρήτης ἀγαγέσθαι ταῦτα.", "st": "1.65"}, {"sp": "N", "t": "ὡς γὰρ ἐπετρόπευσε τάχιστα, μετέστησε τὰ νόμιμα πάντα, καὶ ἐφύλαξε ταῦτα μὴ παραβαίνειν· μετὰ δὲ τὰ ἐς πόλεμον ἔχοντα, ἐνωμοτίας καὶ τριηκάδας καὶ συσσίτια, πρός τε τούτοισι τοὺς ἐφόρους καὶ γέροντας ἔστησε Λυκοῦργος.", "st": "1.65.5"}, {"sp": "N", "t": "οὕτω μὲν μεταβαλόντες εὐνομήθησαν, τῷ δὲ Λυκούργῳ τελευτήσαντι ἱρὸν εἱσάμενοι σέβονται μεγάλως. οἷα δὲ ἐν τε χώρῃ ἀγαθῇ καὶ πλήθεϊ οὐκ ὀλίγων ἀνδρῶν, ἀνά τε ἔδραμον αὐτίκα καὶ εὐθηνήθησαν, καὶ δή σφι οὐκέτι ἀπέχρα ἡσυχίην ἄγειν, ἀλλὰ καταφρονήσαντες Ἀρκάδων κρέσσονες εἶναι ἐχρηστηριάζοντο ἐν Δελφοῖσι ἐπὶ πάσῃ τῇ Ἀρκάδων χωρῇ. ἡ δὲ Πυθίη σφι χρᾷ τάδε.", "st": "1.66"}, {"sp": "N", "t": "Ἀρκαδίην μ’ αἰτεῖς· μέγα μ’ αἰτεῖς· οὐ τοι δώσω.<br>πολλοὶ ἐν Ἀρκαδίῃ βαλανηφάγοι ἄνδρες ἔασιν,<br>οἵ σ’ ἀποκωλύσουσιν. ἐγὼ δὲ τοι οὔτι μεγαίρω·<br>δώσω τοί Τεγέην ποσσίκροτον ὀρχήσασθαι<br>καὶ καλὸν πεδίον σχοίνῳ διαμετρήσασθαι.", "st": "1.66b"}, {"sp": "N", "t": "ταῦτα ὡς ἀπενειχθέντα ἤκουσαν οἱ Λακεδαιμόνιοι, Ἀρκάδων μὲν τῶν ἄλλων ἀπείχοντο, οἳ δὲ πέδας φερόμενοι ἐπὶ Τεγεήτας ἐστρατεύοντο, χρησμῷ κιβδήλῳ πίσυνοι, ὡς δὴ ἐξανδραποδιούμενοι τοὺς Τεγεήτας. ἑσσωθέντες δὲ τῇ συμβολῇ, ὅσοι αὐτῶν ἐζωγρήθησαν, πέδας τε ἔχοντες τὰς ἐφέροντο αὐτοὶ καὶ σχοίνῳ διαμετρησάμενοι τὸ πεδίον τὸ Τεγεητέων ἐργάζοντο. αἱ δὲ πέδαι αὗται ἐν τῇσι ἐδεδέατο ἔτι καὶ ἐς ἐμὲ ἦσαν σόαι ἐν Τεγέῃ περὶ τὸν νηὸν τῆς Ἀλέης Ἀθηναίης κρεμάμεναι.", "st": "1.66.3"}, {"sp": "N", "t": "κατὰ μὲν δὴ τὸν πρότερον πόλεμον συνεχέως αἰεὶ κακῶς ἀέθλεον πρὸς τοὺς Τεγεήτας, κατὰ δὲ τὸν κατὰ Κροῖσον χρόνον καὶ τὴν Ἀναξανδρίδεώ τε καὶ Ἀρίστωνος βασιληίην ἐν Λακεδαίμονι ἤδη οἱ Σπαρτιῆται κατυπέρτεροι τῷ πολέμῳ ἐγεγόνεσαν, τρόπῳ τοιῷδε γενόμενοι. ἐπειδὴ αἰεὶ τῷ πολέμῳ ἑσσοῦντο ὑπὸ Τεγεητέων, πέμψαντες θεοπρόπους ἐς Δελφοὺς ἐπειρώτων τίνα ἂν θεῶν ἱλασάμενοι κατύπερθε τῷ πολέμῳ Τεγεητέων γενοίατο. ἡ δὲ Πυθίη σφι ἔχρησε τὰ Ὀρέστεω τοῦ Ἀγαμέμνονος ὀστέα ἐπαγαγομένους. ὡς δὲ ἀνευρεῖν οὐκ οἷοί τε ἐγίνοντο τὴν θήκην τοῦ Ὀρέστεω ἔπεμπον αὖτις τὴν ἐς θεὸν ἐπειρησομένους τὸν χῶρον ἐν τῷ κέοιτο Ὀρέστης. εἰρωτῶσι δὲ ταῦτα τοῖσι θεοπρόποισι λέγει ἡ Πυθίη τάδε.", "st": "1.67"}, {"sp": "N", "t": "ἔστι τις Ἀρκαδίης Τεγέη λευρῷ ἐνὶ χώρῳ,<br>ἔνθ’ ἄνεμοι πνείουσι δύω κρατερῆς ὑπ’ ἀνάγκης,<br>καὶ τύπος ἀντίτυπος, καὶ πῆμ’ ἐπὶ πήματι κεῖται.<br>ἔνθ’ Ἀγαμεμνονίδην κατέχει φυσίζοος αἶα,<br>τὸν σὺ κομισσάμενος Τεγέης ἐπιτάρροθος ἔσσῃ.", "st": "1.67.4"}, {"sp": "N", "t": "ὡς δὲ καὶ ταῦτα ἤκουσαν οἱ Λακεδαιμόνιοι, ἀπεῖχον τῆς ἐξευρέσιος οὐδὲν ἔλασσον, πάντα διζήμενοι, ἐς οὗ δὴ Λίχης τῶν ἀγαθοεργῶν καλεομένων Σπαρτιητέων ἀνεῦρε, οἱ δὲ ἀγαθοεργοὶ εἰσὶ τῶν ἀστῶν, ἐξιόντες ἐκ τῶν ἱππέων αἰεὶ οἱ πρεσβύτατοι, πέντε ἔτεος ἑκάστου· τοὺς δεῖ τοῦτον τὸν ἐνιαυτόν, τὸν ἂν ἐξίωσι ἐκ τῶν ἱππέων, Σπαρτιητέων τῷ κοινῷ διαπεμπομένους μὴ ἐλινύειν ἄλλους ἄλλῃ.", "st": "1.67.5"}, {"sp": "N", "t": "τούτων ὦν τῶν ἀνδρῶν Λίχης ἀνεῦρε ἐν Τεγέῃ καὶ συντυχίῃ χρησάμενος καὶ σοφίῃ. ἐούσης γὰρ τοῦτον τὸν χρόνον ἐπιμιξίης πρὸς τοὺς Τεγεήτας, ἐλθὼν ἐς χαλκήιον ἐθηεῖτο σίδηρον ἐξελαυνόμενον, καὶ ἐν θώματι ἦν ὀρέων τὸ ποιεόμενον. μαθὼν, δέ μιν ὁ χαλκεὺς ἀποθωμάζοντα εἶπε παυσάμενος τοῦ ἔργου ἦ κου ἄν, ὦ ξεῖνε Λάκων εἴ περ εἶδες τό περ ἐγώ, κάρτα ἂν ἐθώμαζες, ὅκου νῦν οὕτω τυγχάνεις θῶμα ποιεύμενος τὴν ἐργασίην τοῦ σιδήρου. ἐγὼ γὰρ ἐν τῇδε θέλων τῇ αὐλῇ φρέαρ ποιήσασθαι, ὀρύσσων ἐπέτυχον σορῷ ἑπταπήχεϊ· ὑπὸ δὲ ἀπιστίης μὴ μὲν γενέσθαι μηδαμὰ μέζονας ἀνθρώπους τῶν νῦν ἄνοιξα αὐτὴν καὶ εἶδον τὸν νεκρὸν μήκεϊ ἴσον ἐόντα τῇ σορῷ· μετρήσας δὲ συνέχωσα ὀπίσω. ὃ μὲν δή οἱ ἔλεγε τά περ ὀπώπεε, ὁ δὲ ἐννώσας τὰ λεγόμενα συνεβάλλετο τὸν Ὀρέστεα κατὰ τὸ θεοπρόπιον τοῦτον εἶναι, τῇδε συμβαλλόμενος· τοῦ χαλκέος δύο ὁρέων φύσας τοὺς ἀνέμους εὕρισκε ἐόντας, τὸν δὲ ἄκμονα καὶ τὴν σφῦραν τόν τε τύπον καὶ τὸν ἀντίτυπον, τὸν δὲ ἐξελαυνόμενον σίδηρον τὸ πῆμα ἐπὶ πήματι κείμενον, κατὰ τοιόνδε τι εἰκάζων, ὡς ἐπὶ κακῷ ἀνθρώπου σίδηρος ἀνεύρηται. συμβαλόμενος δὲ ταῦτα καὶ ἀπελθὼν ἐς Σπάρτην ἔφραζε Λακεδαιμονίοισι πᾶν τὸ πρῆγμα. οἳ δὲ ἐκ λόγου πλαστοῦ ἐπενείκαντές οἱ αἰτίην ἐδίωξαν. ὁ δὲ ἀπικόμενος ἐς Τεγέην καὶ φράζων τὴν ἑωυτοῦ συμφορὴν πρὸς τὸν χαλκέα ἐμισθοῦτο παρ’ οὐκ ἐκδιδόντος τὴν αὐλήν· χρόνῳ δὲ ὡς ἀνέγνωσε, ἐνοικίσθη, ἀνορύξας δὲ τὸν τάφον καὶ τὰ ὀστέα συλλέξας οἴχετο φέρων ἐς Σπάρτην. καὶ ἀπὸ τούτου τοῦ χρόνου, ὅκως πειρῴατο ἀλλήλων, πολλῷ κατυπέρτεροι τῷ πολέμῳ ἐγίνοντο οἱ Λακεδαιμόνιοι· ἤδη δέ σφι καὶ ἡ πολλὴ τῆς Πελοποννήσου ἦν κατεστραμμένη.", "st": "1.68"}, {"sp": "N", "t": "ταῦτα δὴ ὦν πάντα πυνθανόμενος ὁ Κροῖσος ἔπεμπε ἐς Σπάρτην ἀγγέλους δῶρά τε φέροντας καὶ δεησομένους συμμαχίης, ἐντειλάμενός τε τὰ λέγειν χρῆν. οἳ δὲ ἐλθόντες ἔλεγον ἔπεμψε ἡμέας Κροῖσος ὁ Λυδῶν τε καὶ ἄλλων ἐθνέων βασιλεύς, λέγων τάδε. ὦ Λακεδαιμόνιοι, χρήσαντος τοῦ θεοῦ τὸν Ἕλληνα φίλον προσθέσθαι, ὑμέας γὰρ πυνθάνομαι προεστάναι τῆς Ἑλλάδος, ὑμέας ὦν κατὰ τὸ χρηστήριον προσκαλέομαι φίλος τε θέλων γενέσθαι καὶ σύμμαχος ἄνευ τε δόλου καὶ ἀπάτης. Κροῖσος μὲν δὴ ταῦτα δι’ ἀγγέλων ἐπεκηρυκεύετο, Λακεδαιμόνιοι δὲ ἀκηκοότες καὶ αὐτοὶ τὸ θεοπρόπιον τὸ Κροίσῳ γενόμενον ἥσθησάν τε τῇ ἀπίξι τῶν Λυδῶν καὶ ἐποιήσαντο ὅρκια ξεινίης πέρι καὶ συμμαχίης· καὶ γὰρ τινὲς αὐτοὺς εὐεργεσίαι εἶχον ἐκ Κροίσου πρότερον ἔτι γεγονυῖαι. πέμψαντες γὰρ οἱ Λακεδαιμόνιοι ἐς Σάρδις χρυσὸν ὠνέοντο, ἐς ἄγαλμα βουλόμενοι χρήσασθαι τοῦτο τὸ νῦν τῆς Λακωνικῆς ἐν Θόρνακι ἵδρυται Ἀπόλλωνος· Κροῖσος δέ σφι ὠνεομένοισι ἔδωκε δωτίνην.", "st": "1.69"}, {"sp": "N", "t": "τούτων τε ὦν εἵνεκεν οἱ Λακεδαιμόνιοι τὴν συμμαχίην ἐδέξαντο, καὶ ὅτι ἐκ πάντων σφέας προκρίνας Ἑλλήνων αἱρέετο φίλους. καὶ τοῦτο μὲν αὐτοὶ ἦσαν ἕτοιμοι ἐπαγγείλαντι, τοῦτο δὲ ποιησάμενοι κρητῆρα χάλκεον ζῳδίων τε ἔξωθεν πλήσαντες περὶ τὸ χεῖλος καὶ μεγάθεϊ τριηκοσίους ἀμφορέας χωρέοντα ἦγον, δῶρον βουλόμενοι ἀντιδοῦναι Κροίσῳ. οὗτος ὁ κρητὴρ οὐκ ἀπίκετο ἐς Σάρδις δι’ αἰτίας διφασίας λεγομένας τάσδε· οἱ μὲν Λακεδαιμόνιοι λέγουσι ὡς ἐπείτε ἀγόμενος ἐς τὰς Σάρδις ὁ κρητὴρ ἐγίνετο κατὰ τὴν Σαμίην, πυθόμενοι Σάμιοι ἀπελοίατο αὐτὸν νηυσὶ μακρῇσι ἐπιπλώσαντες· αὐτοὶ δὲ Σάμιοι λέγουσι ὡς ἐπείτε ὑστέρησαν οἱ ἄγοντες τῶν Λακεδαιμονίων τὸν κρητῆρα, ἐπυνθάνοντο δὲ Σάρδις τε καὶ Κροῖσον ἡλωκέναι, ἀπέδοντο τὸν κρητῆρα ἐν Σάμῳ, ἰδιώτας δὲ ἄνδρας πριαμένους ἀναθεῖναί μιν ἐς τὸ Ἥραιον. τάχα δὲ ἂν καὶ οἱ ἀποδόμενοι λέγοιεν ἀπικόμενοι ἐς Σπάρτην ὡς ἀπαιρεθείησαν ὑπὸ Σαμίων. κατὰ μέν νυν τὸν κρητῆρα οὕτω ἔσχε.", "st": "1.70"}, {"sp": "N", "t": "Κροῖσος δὲ ἁμαρτὼν τοῦ χρησμοῦ ἐποιέετο στρατηίην ἐς Καππαδοκίην, ἐλπίσας καταιρήσειν Κῦρόν τε καὶ τὴν Περσέων δύναμιν. παρασκευαζομένου δὲ Κροίσου στρατεύεσθαι ἐπὶ Πέρσας, τῶν τις Λυδῶν νομιζόμενος καὶ πρόσθε εἶναι σοφός, ἀπὸ δὲ ταύτης τῆς γνώμης καὶ τὸ κάρτα οὔνομα ἐν Λυδοῖσι ἔχων, συνεβούλευσε Κροίσῳ τάδε· οὔνομά οἱ ἦν Σάνδανις. ὦ βασιλεῦ, ἐπ’ ἄνδρας τοιούτους στρατεύεσθαι παρασκευάζεαι, οἳ σκυτίνας μὲν ἀναξυρίδας σκυτίνην δὲ τὴν ἄλλην ἐσθῆτα φορέουσι, σιτέονται δὲ οὐκ ὅσα ἐθέλουσι ἀλλ’ ὅσα ἔχουσι, χώρην ἔχοντες τρηχέαν. πρὸς δὲ οὐκ οἴνῳ διαχρέωνται ἀλλὰ ὑδροποτέουσι, οὐ σῦκα δὲ ἔχουσι τρώγειν, οὐκ ἄλλο ἀγαθὸν οὐδέν. τοῦτο μὲν δή, εἰ νικήσεις, τί σφέας ἀπαιρήσεαι, τοῖσί γε μὴ ἔστι μηδέν; τοῦτο δέ, ἢν νικηθῇς, μάθε ὅσα ἀγαθὰ ἀποβαλέεις· γευσάμενοι γὰρ τῶν ἡμετέρων ἀγαθῶν περιέξονται οὐδὲ ἀπωστοὶ ἔσονται. ἐγὼ μέν νυν θεοῖσι ἔχω χάριν, οἳ οὐκ ἐπὶ νόον ποιέουσι Πέρσῃσι στρατεύεσθαι ἐπὶ Λυδούς. ταῦτα λέγων οὐκ ἔπειθε τὸν Κροῖσον. Πέρσῃσι γάρ, πρὶν Λυδοὺς καταστρέψασθαι, ἦν οὔτε ἁβρὸν οὔτε ἀγαθὸν οὐδέν.", "st": "1.71"}, {"sp": "N", "t": "οἱ δὲ Καππαδόκαι ὑπὸ Ἑλλήνων Σύριοι ὀνομάζονται· ἦσαν δὲ οἱ Σύριοι οὗτοι τὸ μὲν πρότερον ἢ Πέρσας ἄρξαι Μήδων κατήκοοι, τότε δὲ Κύρου. ὁ γὰρ οὖρος ἦν τῆς τε Μηδικῆς ἀρχῆς καὶ τῆς Λυδικῆς ὁ Ἅλυς ποταμός, ὃς ῥέει ἐξ Ἀρμενίου ὄρεος διὰ Κιλίκων, μετὰ δὲ Ματιηνοὺς μὲν ἐν δεξιῇ ἔχει ῥέων, ἐκ δὲ τοῦ ἑτέρου Φρύγας· παραμειβόμενος δὲ τούτους καὶ ῥέων ἄνω πρὸς βορέην ἄνεμον ἔνθεν μὲν Συρίους Καππαδόκας ἀπέργει, ἐξ εὐωνύμου δὲ Παφλαγόνας. οὕτω ὁ Ἅλυς ποταμὸς ἀποτάμνει σχεδὸν πάντα τῆς Ἀσίης τὰ κάτω ἐκ θαλάσσης τῆς ἀντίον Κύπρου ἐς τὸν Εὔξεινον πόντον. ἔστι δὲ αὐχὴν οὗτος τῆς χώρης ταύτης ἁπάσης· μῆκος ὁδοῦ εὐζώνῳ ἀνδρὶ πέντε ἡμέραι ἀναισιμοῦνται.", "st": "1.72"}, {"sp": "N", "t": "ἐστρατεύετο δὲ ὁ Κροῖσος ἐπὶ τὴν Καππαδοκίην τῶνδε εἵνεκα, καὶ γῆς ἱμέρῳ προσκτήσασθαι πρὸς τὴν ἑωυτοῦ μοῖραν βουλόμενος, καὶ μάλιστα τῷ χρηστηρίῳ πίσυνος ἐὼν καὶ τίσασθαι θέλων ὑπὲρ Ἀστυάγεος Κῦρον. Ἀστυάγεα γὰρ τὸν Κυαξάρεω, ἐόντα Κροίσου μὲν γαμβρὸν Μήδων δὲ βασιλέα, Κῦρος ὁ Καμβύσεω καταστρεψάμενος εἶχε, γενόμενον γαμβρὸν Κροίσῳ ὧδε. Σκυθέων τῶν νομάδων εἴλῃ ἀνδρῶν στασιάσασα ὑπεξῆλθε ἐς γῆν τὴν Μηδικήν· ἐτυράννευε δὲ τὸν χρόνον τοῦτον Μήδων Κυαξάρης ὁ Φραόρτεω τοῦ Δηιόκεω, ὃς τοὺς Σκύθας τούτους τὸ μὲν πρῶτον περιεῖπε εὖ ὡς ἐόντας ἱκέτας· ὥστε δὲ περὶ πολλοῦ ποιεόμενος αὐτούς, παῖδάς σφι παρέδωκε τὴν γλῶσσάν τε ἐκμαθεῖν καὶ τὴν τέχνην τῶν τόξων. χρόνου δὲ γενομένου, καὶ αἰεὶ φοιτεόντων τῶν Σκυθέων ἐπ’ ἄγρην καὶ αἰεί τι φερόντων, καὶ κοτε συνήνεικε ἑλεῖν σφεας μηδέν· νοστήσαντας δὲ αὐτοὺς κεινῇσι χερσὶ ὁ Κυαξάρης (ἦν γάρ, ὡς διέδεξε, ὀργὴν ἄκρος) τρηχέως κάρτα περιέσπε ἀεικείῃ. οἳ δὲ ταῦτα πρὸς Κυαξάρεω παθόντες, ὥστε ἀνάξια σφέων αὐτῶν πεπονθότες, ἐβούλευσαν τῶν παρὰ σφίσι διδασκομένων παίδων ἕνα κατακόψαι, σκευάσαντες δὲ αὐτὸν ὥσπερ ἐώθεσαν καὶ τὰ θηρία σκευάζειν, Κυαξάρῃ δοῦναι φέροντες ὡς ἄγρην δῆθεν, δόντες δὲ τὴν ταχίστην κομίζεσθαι παρὰ Ἀλυάττεα τὸν Σαδυάττεω ἐς Σάρδις. ταῦτα καὶ ἐγένετο. καὶ γὰρ Κυαξάρης καὶ οἱ παρεόντες δαιτυμόνες τῶν κρεῶν τούτων ἐπάσαντο, καὶ οἱ Σκύθαι ταῦτα ποιήσαντες Ἀλυάττεω ἱκέται ἐγένοντο.", "st": "1.73"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα, οὐ γὰρ δὴ ὁ Ἀλυάττης ἐξεδίδου τοὺς Σκύθας ἐξαιτέοντι Κυαξάρῃ, πόλεμος τοῖσι Λυδοῖσι καὶ τοῖσι Μήδοισι ἐγεγόνεε ἐπ’ ἔτεα πέντε, ἐν τοῖσι πολλάκις μὲν οἱ Μῆδοι τοὺς Λυδοὺς ἐνίκησαν, πολλάκις δὲ οἱ Λυδοὶ τοὺς Μήδους, ἐν δὲ καὶ νυκτομαχίην τινὰ ἐποιήσαντο· διαφέρουσι δέ σφι ἐπὶ ἴσης τὸν πόλεμον τῷ ἕκτῳ ἔτεϊ συμβολῆς γενομένης συνήνεικε ὥστε τῆς μάχης συνεστεώσης τὴν ἡμέρην ἐξαπίνης νύκτα γενέσθαι. τὴν δὲ μεταλλαγὴν ταύτην τῇ ἡμέρης Θαλῆς ὁ Μιλήσιος τοῖσι Ἴωσι προηγόρευσε ἔσεσθαι, οὖρον προθέμενος ἐνιαυτὸν τοῦτον ἐν τῷ δὴ καὶ ἐγένετο ἡ μεταβολή. οἱ δὲ Λυδοί τε καὶ οἱ Μῆδοι ἐπείτε εἶδον νύκτα ἀντὶ ἡμέρης γενομένην, τῆς μάχης τε ἐπαύσαντο καὶ μᾶλλόν τι ἔσπευσαν καὶ ἀμφότεροι εἰρήνην ἑωυτοῖσι γενέσθαι. οἱ δὲ συμβιβάσαντες αὐτοὺς ἦσαν οἵδε, Συέννεσίς τε ὁ Κίλιξ καὶ Λαβύνητος ὁ Βαβυλώνιος. οὗτοί σφι καὶ τὸ ὅρκιον οἱ σπεύσαντες γενέσθαι ἦσαν καὶ γάμων ἐπαλλαγὴν ἐποίησαν· Ἀλυάττεα γὰρ ἔγνωσαν δοῦναι τὴν θυγατέρα Ἀρύηνιν Ἀστυάγεϊ τῷ Κυαξάρεω παιδί· ἄνευ γὰρ ἀναγκαίης ἰσχυρῆς συμβάσιες ἰσχυραὶ οὐκ ἐθέλουσι συμμένειν. ὅρκια δὲ ποιέεται ταῦτα τὰ ἔθνεα τὰ πέρ τε Ἕλληνες, καὶ πρὸς τούτοισι, ἐπεὰν τοὺς βραχίονας ἐπιτάμωνται ἐς τὴν ὁμοχροίην, τὸ αἷμα ἀναλείχουσι ἀλλήλων.", "st": "1.74"}, {"sp": "N", "t": "τοῦτον δὴ ὦν τὸν Ἀστυάγεα Κῦρος ἐόντα ἑωυτοῦ μητροπάτορα καταστρεψάμενος ἔσχε δι’ αἰτίην τὴν ἐγὼ ἐν τοῖσι ὀπίσω λόγοισι σημανέω· τὰ Κροῖσος ἐπιμεμφόμενος τῷ Κύρῳ ἔς τε τὰ χρηστήρια ἔπεμπε εἰ στρατεύηται ἐπὶ Πέρσας, καὶ δὴ καὶ ἀπικομένου χρησμοῦ κιβδήλου, ἐλπίσας πρὸς ἑωυτοῦ τὸν χρησμὸν εἶναι, ἐστρατεύετο ἐς τὴν Περσέων μοῖραν. ὡς δὲ ἀπίκετο ἐπὶ τὸν Ἅλυν ποταμὸν ὁ Κροῖσος, τὸ ἐνθεῦτεν, ὡς μὲν ἐγὼ λέγω, κατὰ τὰς ἐούσας γεφύρας διεβίβασε τὸν στρατόν, ὡς δὲ ὁ πολλὸς λόγος Ἑλλήνων, Θαλῆς οἱ ὁ Μιλήσιος διεβίβασε. ἀπορέοντος γὰρ Κροίσου ὅκως οἱ διαβήσεται τὸν ποταμὸν ὁ στρατός (οὐ γὰρ δὴ εἶναι κω τοῦτον τὸν χρόνον τὰς γεφύρας ταύτας) λέγεται παρεόντα τὸν Θαλῆν ἐν τῷ στρατοπέδῳ ποιῆσαι αὐτῷ τὸν ποταμὸν ἐξ ἀριστερῆς χειρὸς ῥέοντα τοῦ στρατοῦ καὶ ἐκ δεξιῆς ῥέειν, ποιῆσαι δὲ ὧδε· ἄνωθεν τοῦ στρατοπέδου ἀρξάμενον διώρυχα βαθέαν ὀρύσσειν, ἄγοντα μηνοειδέα, ὅκως ἂν τὸ στρατόπεδον ἱδρυμένον κατὰ νώτου λάβοι, ταύτῃ κατὰ τὴν διώρυχα ἐκτραπόμενος ἐκ τῶν ἀρχαίων ῥεέθρων, καὶ αὖτις παραμειβόμενος τὸ στρατόπεδον ἐς τὰ ἀρχαῖα ἐσβάλλοι· ὥστε ἐπείτε καὶ ἐσχίσθη τάχιστα ὁ ποταμός, ἀμφοτέρῃ διαβατὸς ἐγένετο, οἳ δὲ καὶ τὸ παράπαν λέγουσι καὶ τὸ ἀρχαῖον ῥέεθρον ἀποξηρανθῆναι. ἀλλὰ τοῦτο μὲν οὐ προσίεμαι· κῶς γὰρ ὀπίσω πορευόμενοι διέβησαν αὐτόν;", "st": "1.75"}, {"sp": "N", "t": "Κροῖσος δὲ ἐπείτε διαβὰς σὺν τῷ στρατῷ ἀπίκετο τῆς Καππαδοκίης ἐς τὴν Πτερίην καλεομένην (ἡ δὲ Πτερίη ἐστὶ τῆς χώρης ταύτης τὸ ἰσχυρότατον, κατὰ Σινώπην πόλιν τὴν ἐν Εὐξείνῳ πόντῳ μάλιστά κῃ κειμένη), ἐνθαῦτα ἐστρατοπεδεύετο φθείρων τῶν Συρίων τοὺς κλήρους· καὶ εἷλε μὲν τῶν Πτερίων τὴν πόλιν καὶ ἠνδραποδίσατο, εἷλε δὲ τὰς περιοικίδας αὐτῆς πάσας, Συρίους τε οὐδὲν ἐόντας αἰτίους ἀναστάτους ἐποίησε. Κῦρος δὲ ἀγείρας τὸν ἑωυτοῦ στρατὸν καὶ παραλαβὼν τοὺς μεταξὺ οἰκέοντας πάντας ἠντιοῦτο Κροίσῳ. πρὶν δὲ ἐξελαύνειν ὁρμῆσαι τὸν στρατόν, πέμψας κήρυκας ἐς τοὺς Ἴωνας ἐπειρᾶτο σφέας ἀπὸ Κροίσου ἀπιστάναι. Ἴωνες μέν νυν οὐκ ἐπείθοντο. Κῦρος δὲ ὡς ἀπίκετο καὶ ἀντεστρατοπεδεύσατο Κροίσῳ, ἐνθαῦτα ἐν τῇ Πτερίῃ χωρῇ ἐπειρῶντο κατὰ τὸ ἰσχυρὸν ἀλλήλων. μάχης δὲ καρτερῆς γενομένης καὶ πεσόντων ἀμφοτέρων πολλῶν, τέλος οὐδέτεροι νικήσαντες διέστησαν νυκτὸς ἐπελθούσης. καὶ τὰ μὲν στρατόπεδα ἀμφότερα οὕτω ἠγωνίσατο.", "st": "1.76"}, {"sp": "N", "t": "Κροῖσος δὲ μεμφθεὶς κατὰ τὸ πλῆθος τὸ ἑωυτοῦ στράτευμα (ἦν γάρ οἱ ὁ συμβαλὼν στρατὸς πολλὸν ἐλάσσων ἢ ὁ Κύρου), τοῦτο μεμφθείς, ὡς τῇ ὑστεραίῃ οὐκ ἐπειρᾶτο ἐπιὼν ὁ Κῦρος, ἀπήλαυνε ἐς τὰς Σάρδις ἐν νόῳ ἔχων παρακαλέσας μὲν Αἰγυπτίους κατὰ τὸ ὅρκιον (ἐποιήσατο γὰρ καὶ πρὸς Ἄμασιν βασιλεύοντα Αἰγύπτου συμμαχίην πρότερον ἤ περ πρὸς Λακεδαιμονίους), μεταπεμψάμενος δὲ καὶ Βαβυλωνίους (καὶ γὰρ πρὸς τούτους αὐτῷ ἐπεποίητο συμμαχίη, ἐτυράννευε δὲ τὸν χρόνον τοῦτον τῶν Βαβυλωνίων Λαβύνητος), ἐπαγγείλας δὲ καὶ Λακεδαιμονίοισι παρεῖναι ἐς χρόνον ῥητόν ἁλίσας τε δὴ τούτους καὶ τὴν ἑωυτοῦ συλλέξας στρατιὴν ἐνένωτο τὸν χειμῶνα παρείς, ἅμα τῷ ἔαρι στρατεύειν ἐπὶ τοὺς Πέρσας. καὶ ὃ μὲν ταῦτα φρονέων, ὡς ἀπίκετο ἐς τὰς Σάρδις, ἔπεμπε κήρυκας κατὰ τὰς συμμαχίας προερέοντας ἐς πέμπτον μῆνα συλλέγεσθαι ἐς Σάρδις· τὸν δὲ παρεόντα καὶ μαχεσάμενον στρατὸν Πέρσῃσι, ὃς ἦν αὐτοῦ ξεινικός, πάντα ἀπεὶς διεσκέδασε οὐδαμὰ ἐλπίσας μὴ κοτε ἄρα ἀγωνισάμενος οὕτω παραπλησίως Κῦρος ἐλάσῃ ἐπὶ Σάρδις.", "st": "1.77"}, {"sp": "N", "t": "ταῦτα ἐπιλεγομένῳ Κροίσῳ τὸ προάστειον πᾶν ὀφίων ἐνεπλήσθη· φανέντων δὲ αὐτῶν οἱ ἵπποι μετιέντες τὰς νομὰς νέμεσθαι φοιτέοντες κατήσθιον. ἰδόντι δὲ τοῦτο Κροίσῳ, ὥσπερ καὶ ἦν ἔδοξε τέρας εἶναι· αὐτίκα δὲ ἔπεμπε θεοπρόπους ἐς τῶν ἐξηγητέων Τελμησσέων. ἀπικομένοισι δὲ τοῖσι θεοπρόποισι καὶ μαθοῦσι πρὸς Τελμησσέων τὸ θέλει σημαίνειν τὸ τέρας, οὐκ ἐξεγένετο Κροίσῳ ἀπαγγεῖλαι· πρὶν γὰρ ἢ ὀπίσω σφέας ἀναπλῶσαι ἐς τὰς Σάρδις ἥλω ὁ Κροῖσος. Τελμησσέες μέντοι τάδε ἔγνωσαν, στρατὸν ἀλλόθροον προσδόκιμον εἶναι Κροίσῳ ἐπὶ τὴν χώρην, ἀπικόμενον δὲ τοῦτον καταστρέψεσθαι τοὺς ἐπιχωρίους, λέγοντες ὄφιν εἶναι γῆς παῖδα, ἵππον δὲ πολέμιόν τε καὶ ἐπήλυδα. Τελμησσέες μέν νυν ταῦτα ὑπεκρίναντο Κροίσῳ ἤδη ἡλωκότι, οὐδὲν κω εἰδότες τῶν ἦν περὶ Σάρδις τε καὶ αὐτὸν Κροῖσον.", "st": "1.78"}, {"sp": "N", "t": "Κῦρος δὲ αὐτίκα ἀπελαύνοντος Κροίσου μετὰ τὴν μάχην τὴν γενομένην ἐν τῇ Πτερίῃ, μαθὼν ὡς ἀπελάσας μέλλοι Κροῖσος διασκεδᾶν τὸν στρατόν, βουλευόμενος εὕρισκε πρῆγμά οἷ εἶναι ἐλαύνειν ὡς δύναιτο τάχιστα ἐπὶ τὰς Σάρδις, πρὶν ἢ τὸ δεύτερον ἁλισθῆναι τῶν Λυδῶν τὴν δύναμιν. ὡς δέ οἱ ταῦτα ἔδοξε, καὶ ἐποίεε κατὰ τάχος· ἐλάσας γὰρ τὸν στρατὸν ἐς τὴν Λυδίην αὐτὸς ἄγγελος Κροίσῳ ἐληλύθεε. ἐνθαῦτα Κροῖσος ἐς ἀπορίην πολλὴν ἀπιγμένος, ὥς οἱ παρὰ δόξαν ἔσχε τὰ πρήγματα ἢ ὡς αὐτὸς κατεδόκεε, ὅμως τοὺς Λυδοὺς ἐξῆγε ἐς μάχην. ἦν δὲ τοῦτον τὸν χρόνον ἔθνος οὐδὲν ἐν τῇ Ἀσίῃ οὔτε ἀνδρηιότερον οὔτε ἀλκιμώτερον τοῦ Λυδίου. ἡ δὲ μάχη σφέων ἦν ἀπ’ ἵππων, δόρατά τε ἐφόρεον μεγάλα, καὶ αὐτοὶ ἦσαν ἱππεύεσθαι ἀγαθοί.", "st": "1.79"}, {"sp": "N", "t": "ἐς τὸ πεδίον δὲ συνελθόντων τοῦτο τὸ πρὸ τοῦ ἄστεος ἐστὶ τοῦ Σαρδιηνοῦ, ἐὸν μέγα τε καὶ ψιλὸν (διὰ δὲ αὐτοῦ ποταμοὶ ῥέοντες καὶ ἄλλοι καὶ Ὕλλος συρρηγνῦσι ἐς τὸν μέγιστον, καλεόμενον δὲ Ἕρμον, ὃς ἐξ ὄρεος ἱροῦ μητρὸς Δινδυμήνης ῥέων ἐκδιδοῖ ἐς θάλασσαν κατὰ Φωκαίην πόλιν), ἐνθαῦτα ὁ Κῦρος ὡς εἶδε τοὺς Λυδοὺς ἐς μάχην τασσομένους, καταρρωδήσας τὴν ἵππον ἐποίησε Ἁρπάγου ὑποθεμένου ἀνδρὸς Μήδου τοιόνδε· ὅσαι τῷ στρατῷ τῷ ἑωυτοῦ εἵποντο σιτοφόροι τε καὶ σκευοφόροι κάμηλοι, ταύτας πάσας ἁλίσας καὶ ἀπελὼν τὰ ἄχθεα ἄνδρας ἐπ’ αὐτὰς ἀνέβησε ἱππάδα στολὴν ἐνεσταλμένους, σκευάσας δὲ αὐτοὺς προσέταξε τῆς ἄλλης στρατιῆς προϊέναι πρὸς τὴν Κροίσου ἵππον, τῇ δὲ καμήλῳ ἕπεσθαι τὸν πεζὸν στρατὸν ἐκέλευσε, ὄπισθε δὲ τοῦ πεζοῦ ἐπέταξε τὴν πᾶσαν ἵππον. ὡς δέ οἱ πάντες διετετάχατο, παραίνεσε τῶν μὲν ἄλλων Λυδῶν μὴ φειδομένους κτείνειν πάντα τὸν ἐμποδὼν γινόμενον, Κροῖσον δὲ αὐτὸν μὴ κτείνειν, μηδὲ ἢν συλλαμβανόμενος ἀμύνηται. ταῦτα μὲν παραίνεσε, τὰς δὲ καμήλους ἔταξε ἀντία τῆς ἵππου τῶνδε εἵνεκεν· κάμηλον ἵππος φοβέεται, καὶ οὐκ ἀνέχεται οὔτε τὴν ἰδέην αὐτοῦ ὁρέων οὔτε τὴν ὀδμὴν ὀσφραινόμενος. αὐτοῦ δὴ ὦν τούτου εἵνεκεν ἐσεσόφιστο, ἵνα τῷ Κροίσῳ ἄχρηστον ᾖ τὸ ἱππικόν, τῷ δή τι καὶ ἐπεῖχε ἐλλάμψεσθαι ὁ Λυδός. ὡς δὲ καὶ συνήισαν ἐς τὴν μάχην, ἐνθαῦτα ὡς ὤσφροντο τάχιστα τῶν καμήλων οἱ ἵπποι καὶ εἶδον αὐτάς, ὀπίσω ἀνέστρεφον, διέφθαρτό τε τῷ Κροίσῳ ἡ ἐλπίς. οὐ μέντοι οἵ γε Λυδοὶ τὸ ἐνθεῦτεν δειλοὶ ἦσαν, ἀλλ’ ὡς ἔμαθον τὸ γινόμενον, ἀποθορόντες ἀπὸ τῶν ἵππων πεζοὶ τοῖσι Πέρσῃσι συνέβαλλον. χρόνῳ δὲ πεσόντων ἀμφοτέρων πολλῶν ἐτράποντο οἱ Λυδοί, κατειληθέντες δὲ ἐς τὸ τεῖχος ἐπολιορκέοντο ὑπὸ τῶν Περσέων.", "st": "1.80"}, {"sp": "N", "t": "τοῖσι μὲν δὴ κατεστήκεε πολιορκίη. Κροῖσος δὲ δοκέων οἱ χρόνον ἐπὶ μακρὸν ἔσεσθαι τὴν πολιορκίην ἔπεμπε ἐκ τοῦ τείχεος ἄλλους ἀγγέλους ἐς τὰς συμμαχίας. οἱ μὲν γὰρ πρότεροι διεπέμποντο ἐς πέμπτον μῆνα προερέοντες συλλέγεσθαι ἐς Σάρδις, τούτους δὲ ἐξέπεμπε τὴν ταχίστην δέεσθαι βοηθέειν ὡς πολιορκεομένου Κροίσου.", "st": "1.81"}, {"sp": "N", "t": "ἔς τε δὴ ὦν τὰς ἄλλας ἔπεμπε συμμαχίας καὶ δὴ καὶ ἐς Λακεδαίμονα. τοῖσι δὲ καὶ αὐτοῖσι τοῖσι Σπαρτιήτῃσι κατ’ αὐτὸν τοῦτον τὸν χρόνον συνεπεπτώκεε ἔρις ἐοῦσα πρὸς Ἀργείους περὶ χώρου καλεομένου Θυρέης· τὰς γὰρ Θυρέας ταύτας ἐούσας τῆς Ἀργολίδος μοίρης ἀποταμόμενοι ἔσχον οἱ Λακεδαιμόνιοι. ἦν δὲ καὶ ἡ μέχρι Μαλέων ἡ πρὸς ἑσπέρην Ἀργείων, ἥ τε ἐν τῇ ἠπείρῳ χώρῃ καὶ ἡ Κυθηρίη νῆσος καὶ αἱ λοιπαὶ τῶν νήσων. βοηθησάντων δὲ Ἀργείων τῇ σφετέρῃ ἀποταμνομένῃ, ἐνθαῦτα συνέβησαν ἐς λόγους συνελθόντες ὥστε τριηκοσίους ἑκατέρων μαχέσασθαι, ὁκότεροι δ’ ἂν περιγένωνται, τούτων εἶναι τὸν χῶρον· τὸ δὲ πλῆθος τοῦ στρατοῦ ἀπαλλάσσεσθαι ἑκάτερον ἐς τὴν ἑωυτοῦ μηδὲ παραμένειν ἀγωνιζομένων, τῶνδε εἵνεκεν ἵνα μὴ παρεόντων τῶν στρατοπέδων ὁρῶντες οἱ ἕτεροι ἑσσουμένους τοὺς σφετέρους ἀπαμύνοιεν. συνθέμενοι ταῦτα ἀπαλλάσσοντο, λογάδες δὲ ἑκατέρων ὑπολειφθέντες συνέβαλον. μαχομένων δὲ σφέων καὶ γινομένων ἰσοπαλέων ὑπελείποντο ἐξ ἀνδρῶν ἑξακοσίων τρεῖς, Ἀργείων μὲν Ἀλκήνωρ τε καὶ Χρομίος, Λακεδαιμονίων δὲ Ὀθρυάδης· ὑπελείφθησαν δὲ οὗτοι νυκτὸς ἐπελθούσης. οἱ μὲν δὴ δύο τῶν Ἀργείων ὡς νενικηκότες ἔθεον ἐς τὸ Ἄργος, ὁ δὲ τῶν Λακεδαιμονίων Ὀθρυάδης σκυλεύσας τοὺς Ἀργείων νεκροὺς καὶ προσφορήσας τὰ ὅπλα πρὸς τὸ ἑωυτοῦ στρατόπεδον ἐν τῇ τάξι εἶχε ἑωυτόν. ἡμέρῃ δὲ δευτέρῃ παρῆσαν πυνθανόμενοι ἀμφότεροι. τέως μὲν δὴ αὐτοὶ ἑκάτεροι ἔφασαν νικᾶν, λέγοντες οἳ μὲν ὡς ἑωυτῶν πλεῦνες περιγεγόνασι, οἳ δὲ τοὺς μὲν ἀποφαίνοντες πεφευγότας, τὸν δὲ σφέτερον παραμείναντα καὶ σκυλεύσαντα τοὺς ἐκείνων νεκρούς· τέλος δὲ ἐκ τῆς ἔριδος συμπεσόντες ἐμάχοντο, πεσόντων δὲ καὶ ἀμφοτέρων πολλῶν ἐνίκων Λακεδαιμόνιοι. Ἀργεῖοι μέν νυν ἀπὸ τούτου τοῦ χρόνου κατακειράμενοι τὰς κεφαλάς, πρότερον ἐπάναγκες κομῶντες, ἐποιήσαντο νόμον τε καὶ κατάρην μὴ πρότερον θρέψειν κόμην Ἀργείων μηδένα, μηδὲ τὰς γυναῖκάς σφι χρυσοφορήσειν, πρὶν Θυρέας ἀνασώσωνται. Λακεδαιμόνιοι δὲ τὰ ἐναντία τούτων ἔθεντο νόμον· οὐ γὰρ κομῶντες πρὸ τούτου ἀπὸ τούτου κομᾶν. τὸν δὲ ἕνα λέγουσι τὸν περιλειφθέντα τῶν τριηκοσίων Ὀθρυάδην, αἰσχυνόμενον ἀπονοστέειν ἐς Σπάρτην τῶν οἱ συλλοχιτέων διεφθαρμένων, αὐτοῦ μιν ἐν τῇσι Θυρέῃσι καταχρήσασθαι ἑωυτόν.", "st": "1.82"}, {"sp": "N", "t": "τοιούτων δὲ τοῖσι Σπαρτιήτῃσι ἐνεστεώτων πρηγμάτων ἧκε ὁ Σαρδιηνὸς κῆρυξ δεόμενος Κροίσῳ βοηθέειν πολιορκεομένῳ. οἳ δὲ ὅμως, ἐπείτε ἐπύθοντο τοῦ κήρυκος, ὁρμέατο βοηθέειν. καί σφι ἤδη παρεσκευασμένοισι καὶ νεῶν ἐουσέων ἑτοίμων ἦλθε ἄλλη ἀγγελίη, ὡς ἡλώκοι τὸ τεῖχος τῶν Λυδῶν καὶ ἔχοιτο Κροῖσος ζωγρηθείς. οὕτω δὴ οὗτοι μὲν συμφορὴν ποιησάμενοι μεγάλην ἐπέπαυντο.", "st": "1.83"}, {"sp": "N", "t": "Σάρδιες δὲ ἥλωσαν ὧδε. ἐπειδὴ τεσσερεσκαιδεκάτη ἐγένετο ἡμέρη πολιορκεομένῳ Κροίσῳ, Κῦρος τῇ στρατιῇ τῇ ἑωυτοῦ διαπέμψας ἱππέας προεῖπε τῷ πρώτῳ ἐπιβάντι τοῦ τείχεος δῶρα δώσειν. μετὰ δὲ τοῦτο πειρησαμένης τῆς στρατιῆς ὡς οὐ προεχώρεε, ἐνθαῦτα τῶν ἄλλων πεπαυμένων ἀνὴρ Μάρδος ἐπειρᾶτο προσβαίνων, τῷ οὔνομα ἦν Ὑροιάδης, κατὰ τοῦτο τῆς ἀκροπόλιος τῇ οὐδεὶς ἐτέτακτο φύλακος· οὐ γὰρ ἦν δεινὸν κατὰ τοῦτο μὴ ἁλῷ κοτέ. ἀπότομός τε γὰρ ἐστὶ ταύτῃ ἡ ἀκρόπολις καὶ ἄμαχος· τῇ οὐδὲ Μήλης ὁ πρότερον βασιλεὺς Σαρδίων μούνῃ οὐ περιήνεικε τὸν λέοντα τὸν οἱ ἡ παλλακὴ ἔτεκε, Τελμησσέων δικασάντων ὡς περιενειχθέντος τοῦ λέοντος τὸ τεῖχος ἔσονται Σάρδιες ἀνάλωτοι. ὁ δὲ Μήλης κατὰ τὸ ἄλλο τεῖχος περιενείκας, τῇ ἦν ἐπίμαχον τὸ χωρίον τῆς ἀκροπόλιος, κατηλόγησε τοῦτο ὡς ἐὸν ἄμαχόν τε καὶ ἀπότομον· ἔστι δὲ πρὸς τοῦ Τμώλου τετραμμένον τῆς πόλιος. ὁ ὦν δὴ Ὑροιάδης οὗτος ὁ Μάρδος ἰδὼν τῇ προτεραίῃ τῶν τινα Λυδῶν κατὰ τοῦτο τῆς ἀκροπόλιος καταβάντα ἐπὶ κυνέην ἄνωθεν κατακυλισθεῖσαν καὶ ἀνελόμενον, ἐφράσθη καὶ ἐς θυμὸν ἐβάλετο· τότε δὲ δὴ αὐτός τε ἀναβεβήκεε καὶ κατ’ αὐτὸν ἄλλοι Περσέων ἀνέβαινον· προσβάντων δὲ συχνῶν οὕτω δὴ Σάρδιές τε ἡλώκεσαν καὶ πᾶν τὸ ἄστυ ἐπορθέετο.", "st": "1.84"}, {"sp": "N", "t": "κατ’ αὐτὸν δὲ Κροῖσον τάδε ἐγίνετο. ἦν οἱ παῖς, τοῦ καὶ πρότερον ἐπεμνήσθην, τὰ μὲν ἄλλα ἐπιεικής, ἄφωνος δέ. ἐν τῇ ὦν παρελθούσῃ εὐεστοῖ ὁ Κροῖσος τὸ πᾶν ἐς αὐτὸν ἐπεποιήκεε, ἄλλα τε ἐπιφραζόμενος, καὶ δὴ καὶ ἐς Δελφοὺς περὶ αὐτοῦ ἐπεπόμφεε χρησομένους. ἡ δὲ Πυθίη οἱ εἶπε τάδε.", "st": "1.85"}, {"sp": "N", "t": "Λυδὲ γένος, πολλῶν βασιλεῦ, μέγα νήπιε Κροῖσε,<br>μὴ βούλου πολύευκτον ἰὴν ἀνὰ δώματ’ ἀκούειν<br>παιδὸς φθεγγομένου. τὸ δέ σοι πολὺ λώιον ἀμφὶς<br>ἔμμεναι· αὐδήσει γὰρ ἐν ἤματι πρῶτον ἀνόλβῳ. ἁλισκομένου δὴ τοῦ τείχεος, ἤιε γὰρ τῶν τις Περσέων ἀλλογνώσας Κροῖσον ὡς ἀποκτενέων, Κροῖσος μέν νυν ὁρέων ἐπιόντα ὑπὸ τῆς παρεούσης συμφορῆς παρημελήκεε, οὐδὲ τί οἱ διέφερε πληγέντι ἀποθανεῖν·", "st": "1.85.3"}, {"sp": "N", "t": "ὁ δὲ παῖς οὗτος ὁ ἄφωνος ὡς εἶδε ἐπιόντα τὸν Πέρσην, ὑπὸ δέους τε καὶ κακοῦ ἔρρηξε φωνήν, εἶπε δὲ ὤνθρωπε, μὴ κτεῖνε Κροῖσον. οὗτος μὲν δὴ τοῦτο πρῶτον ἐφθέγξατο, μετὰ δὲ τοῦτο ἤδη ἐφώνεε τὸν πάντα χρόνον τῆς ζόης.", "st": "1.85.4"}, {"sp": "N", "t": "οἱ δὲ Πέρσαι τάς τε δὴ Σάρδις ἔσχον καὶ αὐτὸν Κροῖσον ἐζώγρησαν, ἄρξαντα ἔτεα τεσσερεσκαίδεκα καὶ τεσσερεσκαίδεκα ἡμέρας πολιορκηθέντα, κατὰ τὸ χρηστήριόν τε καταπαύσαντα τὴν ἑωυτοῦ μεγάλην ἀρχήν. λαβόντες δὲ αὐτὸν οἱ Πέρσαι ἤγαγον παρὰ Κῦρον. ὁ δὲ συννήσας πυρὴν μεγάλην ἀνεβίβασε ἐπ’ αὐτὴν τὸν Κροῖσόν τε ἐν πέδῃσι δεδεμένον καὶ δὶς ἑπτὰ Λυδῶν παρ’ αὐτὸν παῖδας, ἐν νόῳ ἔχων εἴτε δὴ ἀκροθίνια ταῦτα καταγιεῖν θεῶν ὅτεῳ δή, εἴτε καὶ εὐχὴν ἐπιτελέσαι θέλων, εἴτε καὶ πυθόμενος τὸν Κροῖσον εἶναι θεοσεβέα τοῦδε εἵνεκεν ἀνεβίβασε ἐπὶ τὴν πυρήν, βουλόμενος εἰδέναι εἴ τίς μιν δαιμόνων ῥύσεται τοῦ μὴ ζῶντα κατακαυθῆναι. τὸν μὲν δὴ ποιέειν ταῦτα· τῷ δὲ Κροίσῳ ἑστεῶτι ἐπὶ τῆς πυρῆς ἐσελθεῖν, καίπερ ἐν κακῷ ἐόντι τοσούτῳ, τὸ τοῦ Σόλωνος ὥς οἱ εἴη σὺν θεῷ εἰρημένον, τὸ μηδένα εἶναι τῶν ζωόντων ὄλβιον. ὡς δὲ ἄρα μιν προσστῆναι τοῦτο, ἀνενεικάμενόν τε καὶ ἀναστενάξαντα ἐκ πολλῆς ἡσυχίης ἐς τρὶς ὀνομάσαι Σόλων. καὶ τὸν Κῦρον ἀκούσαντα κελεῦσαι τοὺς ἑρμηνέας ἐπειρέσθαι τὸν Κροῖσον τίνα τοῦτον ἐπικαλέοιτο, καὶ τοὺς προσελθόντας ἐπειρωτᾶν· Κροῖσον δὲ τέως μὲν σιγὴν ἔχειν εἰρωτώμενον, μετὰ δὲ ὡς ἠναγκάζετο, εἰπεῖν τὸν ἂν ἐγὼ πᾶσι τυράννοισι προετίμησα μεγάλων χρημάτων ἐς λόγους ἐλθεῖν. ὡς δέ σφι ἄσημα ἔφραζε, πάλιν ἐπειρώτων τὰ λεγόμενα. λιπαρεόντων δὲ αὐτῶν καὶ ὄχλον παρεχόντων, ἔλεγε δὴ ὡς ἦλθε ἀρχὴν ὁ Σόλων ἐὼν Ἀθηναῖος, καὶ θεησάμενος πάντα τὸν ἑωυτοῦ ὄλβον ἀποφλαυρίσειε οἷα δὴ εἶπας, ὥς τε αὐτῷ πάντα ἀποβεβήκοι τῇ περ ἐκεῖνος εἶπε, οὐδέν τι μᾶλλον ἐς ἑωυτὸν λέγων ἢ οὐκ ἐς ἅπαν τὸ ἀνθρώπινον καὶ μάλιστα τοὺς παρὰ σφίσι αὐτοῖσι ὀλβίους δοκέοντας εἶναι. τὸν μὲν Κροῖσον ταῦτα ἀπηγέεσθαι, τῆς δὲ πυρῆς ἤδη ἁμμένης καίεσθαι τὰ περιέσχατα. καὶ τὸν Κῦρον ἀκούσαντα τῶν ἑρμηνέων τὰ Κροῖσος εἶπε, μεταγνόντα τε καὶ ἐννώσαντα ὅτι καὶ αὐτὸς ἄνθρωπος ἐὼν ἄλλον ἄνθρωπον, γενόμενον ἑωυτοῦ εὐδαιμονίῃ οὐκ ἐλάσσω, ζῶντα πυρὶ διδοίη, πρός τε τούτοισι δείσαντα τὴν τίσιν καὶ ἐπιλεξάμενον ὡς οὐδὲν εἴη τῶν ἐν ἀνθρώποισι ἀσφαλέως ἔχον, κελεύειν σβεννύναι τὴν ταχίστην τὸ καιόμενον πῦρ καὶ καταβιβάζειν Κροῖσόν τε καὶ τοὺς μετὰ Κροίσου. καὶ τοὺς πειρωμένους οὐ δύνασθαι ἔτι τοῦ πυρὸς ἐπικρατῆσαι.", "st": "1.86"}, {"sp": "N", "t": "ἐνθαῦτα λέγεται ὑπὸ Λυδῶν Κροῖσον μαθόντα τὴν Κύρου μετάγνωσιν, ὡς ὥρα πάντα μὲν ἄνδρα σβεννύντα τὸ πῦρ, δυναμένους δὲ οὐκέτι καταλαβεῖν, ἐπιβώσασθαι τὸν Ἀπόλλωνα ἐπικαλεόμενον, εἴ τί οἱ κεχαρισμένον ἐξ αὐτοῦ ἐδωρήθη, παραστῆναι καὶ ῥύσασθαι αὐτὸν ἐκ τοῦ παρεόντος κακοῦ. τὸν μὲν δακρύοντα ἐπικαλέεσθαι τὸν θεόν, ἐκ δὲ αἰθρίης τε καὶ νηνεμίης συνδραμεῖν ἐξαπίνης νέφεα καὶ χειμῶνά τε καταρραγῆναι καὶ ὗσαι ὕδατι λαβροτάτῳ, κατασβεσθῆναί τε τὴν πυρήν. οὕτω δὴ μαθόντα τὸν Κῦρον ὡς εἴη ὁ Κροῖσος καὶ θεοφιλὴς καὶ ἀνὴρ ἀγαθός, καταβιβάσαντα αὐτὸν ἀπὸ τῆς πυρῆς εἰρέσθαι τάδε. Κροῖσε, τίς σε ἀνθρώπων ἀνέγνωσε ἐπὶ γῆν τὴν ἐμὴν στρατευσάμενον πολέμιον ἀντὶ φίλου ἐμοὶ καταστῆναι; ὁ δὲ εἶπε ὦ βασιλεῦ, ἐγὼ ταῦτα ἔπρηξα τῇ σῇ μὲν εὐδαιμονίῃ, τῇ ἐμεωυτοῦ δὲ κακοδαιμονίῃ, αἴτιος δὲ τούτων ἐγένετο ὁ Ἑλλήνων θεὸς ἐπαείρας ἐμὲ στρατεύεσθαι. οὐδεὶς γὰρ οὕτω ἀνόητος ἐστὶ ὅστις πόλεμον πρὸ εἰρήνης αἱρέεται· ἐν μὲν γὰρ τῇ οἱ παῖδες τοὺς πατέρας θάπτουσι, ἐν δὲ τῷ οἱ πατέρες τοὺς παῖδας. ἀλλὰ ταῦτα δαίμοσί κου φίλον ἦν οὕτω γενέσθαι.", "st": "1.87"}, {"sp": "N", "t": "ὅ μὲν ταῦτα ἔλεγε, Κῦρος δὲ αὐτὸν λύσας κατεῖσέ τε ἐγγὺς ἑωυτοῦ καὶ κάρτα ἐν πολλῇ προμηθίῃ εἶχε, ἀπεθώμαζέ τε ὁρέων καὶ αὐτὸς καὶ οἱ περὶ ἐκεῖνον ἐόντες πάντες. ὁ δὲ συννοίῃ ἐχόμενος ἥσυχος ἦν· μετὰ δὲ ἐπιστραφείς τε καὶ ἰδόμενος τοὺς Πέρσας τὸ τῶν Λυδῶν ἄστυ κεραΐζοντας εἶπε ὦ βασιλεῦ, κότερον λέγειν πρὸς σὲ τὰ νοέων τυγχάνω ἢ σιγᾶν ἐν τῷ παρεόντι χρή; Κῦρος δέ μιν θαρσέοντα ἐκέλευε λέγειν ὅ τι βούλοιτο. ὁ δὲ αὐτὸν εἰρώτα λέγων οὗτος ὁ πολλὸς ὅμιλος τί ταῦτα πολλῇ σπουδῇ ἐργάζεται; ὁ δὲ εἶπε πόλιν τε τὴν σὴν διαρπάζει καὶ χρήματα τὰ σὰ διαφορέει. Κροῖσος δὲ ἀμείβετο οὔτε πόλιν τὴν ἐμὴν οὔτε χρήματα τὰ ἐμὰ διαρπάζει· οὐδὲν γὰρ ἐμοὶ ἔτι τούτων μέτα· ἀλλὰ φέρουσί τε καὶ ἄγουσι τὰ σά.", "st": "1.88"}, {"sp": "N", "t": "Κύρῳ δὲ ἐπιμελὲς ἐγένετο τὰ Κροῖσος εἶπε· μεταστησάμενος δὲ τοὺς ἄλλους, εἴρετο Κροῖσον ὅ τι οἱ ἐνορῴη ἐν τοῖσι ποιευμένοισι. ὁ δὲ εἶπε ἐπείτε με θεοὶ ἔδωκαν δοῦλον σοί, δικαιῶ, εἴ τι ἐνορέω πλέον, σημαίνειν σοί. Πέρσαι φύσιν ἐόντες ὑβρισταὶ εἰσὶ ἀχρήματοι. ἢν ὦν σὺ τούτους περιίδῃς διαρπάσαντας καὶ κατασχόντας χρήματα μεγάλα, τάδε τοὶ ἐξ αὐτῶν ἐπίδοξα γενέσθαι. ὃς ἂν αὐτῶν πλεῖστα κατάσχῃ, τοῦτον προσδέκεσθαί τοι ἐπαναστησόμενον. νῦν ὦν ποίησον ὧδε, εἲ τοι ἀρέσκει τὰ ἐγὼ λέγω· κάτισον τῶν δορυφόρων ἐπὶ πάσῃσι τῇσι πύλῃσι φυλάκους, οἳ λεγόντων πρὸς τοὺς ἐκφέροντας τὰ χρήματα ἀπαιρεόμενοι ὡς σφέα ἀναγκαίως ἔχει δεκατευθῆναι τῷ Διί. καὶ σύ τέ σφι οὐκ ἀπεχθήσεαι βίῃ ἀπαιρεόμενος τὰ χρήματα, καὶ ἐκεῖνοι συγγνόντες ποιέειν σε δίκαια ἑκόντες προήσουσι.", "st": "1.89"}, {"sp": "N", "t": "ταῦτα ἀκούων ὁ Κῦρος ὑπερήδετο, ὥς οἱ ἐδόκεε εὖ ὑποτίθεσθαι· αἰνέσας δὲ πολλά, καὶ ἐντειλάμενος τοῖσι δορυφόροισι τὰ Κροῖσος ὑπεθήκατο ἐπιτελέειν, εἶπε πρὸς Κροῖσον τάδε. Κροῖσε, ἀναρτημένου σεῦ ἀνδρὸς βασιλέος χρηστὰ ἔργα καὶ ἔπεα ποιέειν, αἰτέο δόσιν ἥντινα βούλεαί τοι γενέσθαι παραυτίκα. ὁ δὲ εἶπε ὦ δέσποτα, ἐάσας με χαριεῖ μάλιστα τὸν θεὸν τῶν Ἑλλήνων, τὸν ἐγὼ ἐτίμησα θεῶν μάλιστα, ἐπειρέσθαι πέμψαντα τάσδε τὰς πέδας, εἰ ἐξαπατᾶν τοὺς εὖ ποιεῦντας νόμος ἐστί οἱ. Κῦρος δὲ εἴρετο ὅ τι οἱ τοῦτο ἐπηγορέων παραιτέοιτο. Κροῖσος δέ οἱ ἐπαλιλλόγησε πᾶσαν τὴν ἑωυτοῦ διάνοιαν καὶ τῶν χρηστηρίων τὰς ὑποκρίσιας καὶ μάλιστα τὰ ἀναθήματα, καὶ ὡς ἐπαερθεὶς τῷ μαντηίῳ ἐστρατεύσατο ἐπὶ Πέρσας· λέγων δὲ ταῦτα κατέβαινε αὖτις παραιτεόμενος ἐπεῖναί οἱ τῷ θεῷ τοῦτο ὀνειδίσαι. Κῦρος δὲ γελάσας εἶπε καὶ τούτου τεύξεαι παρ’ ἐμεῦ, Κροῖσε, καὶ ἄλλου παντὸς τοῦ ἂν ἑκάστοτε δέῃ. ὡς δὲ ταῦτα ἤκουσε ὁ Κροῖσος, πέμπων τῶν Λυδῶν ἐς Δελφοὺς ἐνετέλλετο τιθέντας τὰς πέδας ἐπὶ τοῦ νηοῦ τὸν οὐδὸν εἰρωτᾶν εἰ οὔ τι ἐπαισχύνεται τοῖσι μαντηίοισι ἐπαείρας Κροῖσον στρατεύεσθαι ἐπὶ Πέρσας ὡς καταπαύσοντα τὴν Κύρου δύναμιν, ἀπ’ ἧς οἱ ἀκροθίνια τοιαῦτα γενέσθαι, δεικνύντας τὰς πέδας· ταῦτά τε ἐπειρωτᾶν, καὶ εἰ ἀχαρίστοισι νόμος εἶναι τοῖσι Ἑλληνικοῖσι θεοῖσι.", "st": "1.90"}, {"sp": "N", "t": "ἀπικομένοισι δὲ τοῖσι Λυδοῖσι καὶ λέγουσι τὰ ἐντεταλμένα τὴν Πυθίην λέγεται εἰπεῖν τάδε. τὴν πεπρωμένην μοῖραν ἀδύνατα ἐστὶ ἀποφυγεῖν καὶ θεῷ· Κροῖσος δὲ πέμπτου γονέος ἁμαρτάδα ἐξέπλησε, ὃς ἐὼν δορυφόρος Ἡρακλειδέων, δόλῳ γυναικηίῳ ἐπισπόμενος ἐφόνευσε τὸν δεσπότεα καὶ ἔσχε τὴν ἐκείνου τιμὴν οὐδέν οἱ προσήκουσαν. προθυμεομένου δὲ Λοξίεω ὅκως ἂν κατὰ τοὺς παῖδας τοῦ Κροίσου γένοιτο τὸ Σαρδίων πάθος καὶ μὴ κατ’ αὐτὸν Κροῖσον, οὐκ οἷόν τε ἐγίνετο παραγαγεῖν μοίρας. ὅσον δὲ ἐνέδωκαν αὗται, ἤνυσέ τε καὶ ἐχαρίσατό οἱ· τρία γὰρ ἔτεα ἐπανεβάλετο τὴν Σαρδίων ἅλωσιν, καὶ τοῦτο ἐπιστάσθω Κροῖσος ὡς ὕστερον τοῖσι ἔτεσι τούτοισι ἁλοὺς τῆς πεπρωμένης. δευτέρα δὲ τούτων καιομένῳ αὐτῷ ἐπήρκεσε. κατὰ δὲ τὸ μαντήιον τὸ γενόμενον οὐκ ὀρθῶς Κροῖσος μέμφεται. προηγόρευε γὰρ οἱ Λοξίης, ἢν στρατεύηται ἐπὶ Πέρσας, μεγάλην ἀρχὴν αὐτὸν καταλύσειν. τὸν δὲ πρὸς ταῦτα χρῆν εὖ μέλλοντα βουλεύεσθαι ἐπειρέσθαι πέμψαντα κότερα τὴν ἑωυτοῦ ἢ τὴν Κύρου λέγοι ἀρχήν. οὐ συλλαβὼν δὲ τὸ ῥηθὲν οὐδ’ ἐπανειρόμενος ἑωυτὸν αἴτιον ἀποφαινέτω· τῷ καὶ τὸ τελευταῖον χρηστηριαζομένῳ εἶπε Λοξίης περὶ ἡμιόνου, οὐδὲ τοῦτο συνέλαβε. ἦν γὰρ δὴ ὁ Κῦρος οὗτος ἡμίονος· ἐκ γὰρ δυῶν οὐκ ὁμοεθνέων ἐγεγόνεε, μητρὸς ἀμείνονος, πατρὸς δὲ ὑποδεεστέρου· ἣ μὲν γὰρ ἦν Μηδὶς καὶ Ἀστυάγεος θυγάτηρ τοῦ Μήδων βασιλέος, ὁ δὲ Πέρσης τε ἦν καὶ ἀρχόμενος ὑπ’ ἐκείνοισι καὶ ἔνερθε ἐὼν τοῖσι ἅπασι δεσποίνῃ τῇ ἑωυτοῦ συνοίκεε. ταῦτα μὲν ἡ Πυθίη ὑπεκρίνατο τοῖσι Λυδοῖσι, οἳ δὲ ἀνήνεικαν ἐς Σάρδις καὶ ἀπήγγειλαν Κροίσῳ. ὁ δὲ ἀκούσας συνέγνω ἑωυτοῦ εἶναι τὴν ἁμαρτάδα καὶ οὐ τοῦ θεοῦ. κατὰ μὲν δὴ τὴν Κροίσου τε ἀρχὴν καὶ Ἰωνίης τὴν πρώτην καταστροφὴν ἔσχε οὕτω.", "st": "1.91"}, {"sp": "N", "t": "Κροίσῳ δὲ ἐστὶ ἄλλα ἀναθήματα ἐν τῇ Ἑλλάδι πολλὰ καὶ οὐ τὰ εἰρημένα μοῦνα. ἐν μὲν γὰρ Θήβῃσι τῇσι Βοιωτῶν τρίπους χρύσεος, τὸν ἀνέθηκέ τῷ Ἀπόλλωνι τῷ Ἰσμηνίῳ, ἐν δὲ Ἐφέσῳ αἵ τε βόες αἱ χρύσεαι καὶ τῶν κιόνων αἱ πολλαί, ἐν δὲ Προνηίης τῆς ἐν Δελφοῖσι ἀσπὶς χρυσέη μεγάλη. ταῦτα μὲν καὶ ἔτι ἐς ἐμὲ ἦν περιεόντα, τὰ δ’ ἐξαπόλωλε τῶν ἀναθημάτων· τὰ δ’ ἐν Βραγχίδῃσι τῇσι Μιλησίων ἀναθήματα Κροίσῳ, ὡς ἐγὼ πυνθάνομαι, ἴσα τε σταθμὸν καὶ ὅμοια τοῖσι ἐν Δελφοῖσι … τὰ μέν νυν ἔς τε Δελφοὺς καὶ ἐς τοῦ Ἀμφιάρεω ἀνέθηκε οἰκήιά τε ἐόντα καὶ τῶν πατρωίων χρημάτων ἀπαρχήν· τὰ δὲ ἄλλα ἀναθήματα ἐξ ἀνδρὸς ἐγένετο οὐσίης ἐχθροῦ, ὅς οἱ πρὶν ἢ βασιλεῦσαι ἀντιστασιώτης κατεστήκεε, συσπεύδων Πανταλέοντι γενέσθαι τὴν Λυδῶν ἀρχήν. ὁ δὲ Πανταλέων ἦν Ἀλυάττεω μὲν παῖς, Κροίσου δὲ ἀδελφεὸς οὐκ ὁμομήτριος· Κροῖσος μὲν γὰρ ἐκ Καείρης ἦν γυναικὸς Ἀλυάττῃ, Πανταλέων δὲ ἐξ Ἰάδος. ἐπείτε δὲ δόντος τοῦ πατρὸς ἐκράτησε τῆς ἀρχῆς ὁ Κροῖσος, τὸν ἄνθρωπον τὸν ἀντιπρήσσοντα ἐπὶ κνάφου ἕλκων διέφθειρε, τὴν δὲ οὐσίην αὐτοῦ ἔτι πρότερον κατιρώσας τότε τρόπῳ τῷ εἰρημένῳ ἀνέθηκε ἐς τὰ εἴρηται. καὶ περὶ μὲν ἀναθημάτων τοσαῦτα εἰρήσθω.", "st": "1.92"}, {"sp": "N", "t": "θώματα δὲ γῆ ἡ Λυδίη ἐς συγγραφὴν οὐ μάλα ἔχει, οἷά τε καὶ ἄλλη χώρη, πάρεξ τοῦ ἐκ τοῦ Τμώλου καταφερομένου ψήγματος. ἓν δὲ ἔργον πολλὸν μέγιστον παρέχεται χωρὶς τῶν τε Αἰγυπτίων ἔργων καὶ τῶν Βαβυλωνίων· ἔστι αὐτόθι Ἀλυάττεω τοῦ Κροίσου πατρὸς σῆμα, τοῦ ἡ κρηπὶς μὲν ἐστὶ λίθων μεγάλων, τὸ δὲ ἄλλο σῆμα χῶμα γῆς. ἐξεργάσαντο δέ μιν οἱ ἀγοραῖοι ἄνθρωποι καὶ οἱ χειρώνακτες καὶ αἱ ἐνεργαζόμεναι παιδίσκαι. οὖροι δὲ πέντε ἐόντες ἔτι καὶ ἐς ἐμὲ ἦσαν ἐπὶ τοῦ σήματος ἄνω, καί σφι γράμματα ἐνεκεκόλαπτο τὰ ἕκαστοι ἐξεργάσαντο, καὶ ἐφαίνετο μετρεόμενον τὸ τῶν παιδισκέων ἔργον ἐὸν μέγιστον. τοῦ γὰρ δὴ Λυδῶν δήμου αἱ θυγατέρες πορνεύονται πᾶσαι, συλλέγουσαι σφίσι φερνάς, ἐς ὃ ἂν συνοικήσωσι τοῦτο ποιέουσαι· ἐκδιδοῦσι δὲ αὐταὶ ἑωυτάς. ἡ μὲν δὴ περίοδος τοῦ σήματός εἰσὶ στάδιοι ἓξ καὶ δύο πλέθρα, τὸ δὲ εὖρος ἐστὶ πλέθρα τρία καὶ δέκα. λίμνη δὲ ἔχεται τοῦ σήματος μεγάλη, τὴν λέγουσι Λυδοὶ ἀείναον εἶναι· καλέεται δὲ αὕτη Γυγαίη. τοῦτο μὲν δὴ τοιοῦτο ἐστί.", "st": "1.93"}, {"sp": "N", "t": "Λυδοὶ δὲ νόμοισι μὲν παραπλησίοισι χρέωνται καὶ Ἕλληνές, χωρὶς ἢ ὅτι τὰ θήλεα τέκνα καταπορνεύουσι, πρῶτοι δὲ ἀνθρώπων τῶν ἡμεῖς ἴδμεν νόμισμα χρυσοῦ καὶ ἀργύρου κοψάμενοι ἐχρήσαντο, πρῶτοι δὲ καὶ κάπηλοι ἐγένοντο. φασὶ δὲ αὐτοὶ Λυδοὶ καὶ τὰς παιγνίας τὰς νῦν σφίσι τε καὶ Ἕλλησι κατεστεώσας ἑωυτῶν ἐξεύρημα γενέσθαι· ἅμα δὲ ταύτας τε ἐξευρεθῆναι παρὰ σφίσι λέγουσι καὶ Τυρσηνίην ἀποικίσαι, ὧδε περὶ αὐτῶν λέγοντες. ἐπὶ Ἄτυος τοῦ Μάνεω βασιλέος σιτοδείην ἰσχυρὴν ἀνὰ τὴν Λυδίην πᾶσαν γενέσθαι, καὶ τοὺς Λυδοὺς τέως μὲν διάγειν λιπαρέοντας, μετὰ δὲ ὡς οὐ παύεσθαι, ἄκεα δίζησθαι, ἄλλον δὲ ἄλλο ἐπιμηχανᾶσθαι αὐτῶν. ἐξευρεθῆναι δὴ ὦν τότε καὶ τῶν κύβων καὶ τῶν ἀστραγάλων καὶ τῆς σφαίρης καὶ τῶν ἀλλέων πασέων παιγνιέων τὰ εἴδεα, πλὴν πεσσῶν τούτων γὰρ ὦν τὴν ἐξεύρεσιν οὐκ οἰκηιοῦνται Λυδοί. ποιέειν δὲ ὧδε πρὸς τὸν λιμὸν ἐξευρόντας, τὴν μὲν ἑτέρην τῶν ἡμερέων παίζειν πᾶσαν, ἵνα δὴ μὴ ζητέοιεν σιτία, τὴν δὲ ἑτέρην σιτέεσθαι παυομένους τῶν παιγνιέων. τοιούτῳ τρόπῳ διάγειν ἐπ’ ἔτεα δυῶν δέοντα εἴκοσι. ἐπείτε δὲ οὐκ ἀνιέναι τὸ κακὸν ἀλλ’ ἔτι ἐπὶ μᾶλλον βιάζεσθαι οὕτω δὴ τὸν βασιλέα αὐτῶν δύο μοίρας διελόντα Λυδῶν πάντων κληρῶσαι τὴν μὲν ἐπὶ μόνῃ τὴν δὲ ἐπὶ ἐξόδῳ ἐκ τῆς χώρης, καὶ ἐπὶ μὲν τῇ μένειν αὐτοῦ λαγχανούσῃ τῶν μοιρέων ἑωυτὸν τὸν βασιλέα προστάσσειν, ἐπὶ δὲ τῇ ἀπαλλασσομένῃ τὸν ἑωυτοῦ παῖδα, τῷ οὔνομα εἶναι Τυρσηνόν. λαχόντας δὲ αὐτῶν τοὺς ἑτέρους ἐξιέναι ἐκ τῆς χώρης καταβῆναι ἐς Σμύρνην καὶ μηχανήσασθαι πλοῖα, ἐς τὰ ἐσθεμένους τὰ πάντα ὅσα σφι ἦν χρηστὰ ἐπίπλοα, ἀποπλέειν κατὰ βίου τε καὶ γῆς ζήτησιν, ἐς ὃ ἔθνεα πολλὰ παραμειψαμένους ἀπικέσθαι ἐς Ὀμβρικούς, ἔνθα σφέας ἐνιδρύσασθαι πόλιας καὶ οἰκέειν τὸ μέχρι τοῦδε. ἀντὶ δὲ Λυδῶν μετονομασθῆναι αὐτοὺς ἐπὶ τοῦ βασιλέος τοῦ παιδός, ὅς σφεας ἀνήγαγε, ἐπὶ τούτου τὴν ἐπωνυμίην ποιευμένους ὀνομασθῆναι Τυρσηνούς.", "st": "1.94"}, {"sp": "N", "t": "Λυδοὶ μὲν δὴ ὑπὸ Πέρσῃσι ἐδεδούλωντο.", "st": "1.94b"}, {"sp": "N", "t": "ἐπιδίζηται δὲ δὴ τὸ ἐνθεῦτεν ἡμῖν ὁ λόγος τόν τε Κῦρον ὅστις ἐὼν τὴν Κροίσου ἀρχὴν κατεῖλε, καὶ τοὺς Πέρσας ὅτεῳ τρόπῳ ἡγήσαντο τῆς Ἀσίης. ὡς ὦν Περσέων μετεξέτεροι λέγουσι, οἱ μὴ βουλόμενοι σεμνοῦν τὰ περὶ Κῦρον ἀλλὰ τὸν ἐόντα λέγειν λόγον, κατὰ ταῦτα γράψω, ἐπιστάμενος περὶ Κύρου καὶ τριφασίας ἄλλας λόγων ὁδοὺς φῆναι.", "st": "1.95"}, {"sp": "N", "t": "Ἀσσυρίων ἀρχόντων τῆς ἄνω Ἀσίης ἐπ’ ἔτεα εἴκοσι καὶ πεντακόσια, πρῶτοι ἀπ’ αὐτῶν Μῆδοι ἤρξαντο ἀπίστασθαι, καὶ κως οὗτοι περὶ τῆς ἐλευθερίης μαχεσάμενοι τοῖσι Ἀσσυρίοισι ἐγένοντο ἄνδρες ἀγαθοί, καὶ ἀπωσάμενοι τὴν δουλοσύνην ἐλευθερώθησαν. μετὰ δὲ τούτους καὶ τὰ ἄλλα ἔθνεα ἐποίεε τὠυτὸ τοῖσι Μήδοισι.", "st": "1.95.2"}, {"sp": "N", "t": "ἐόντων δὲ αὐτονόμων πάντων ἀνὰ τὴν ἤπειρον, ὧδε αὖτις ἐς τυραννίδα περιῆλθον. ἀνὴρ ἐν τοῖσι Μήδοισι ἐγένετο σοφὸς τῷ οὔνομα ἦν Δηιόκης, παῖς δ’ ἦν Φραόρτεω. οὗτος ὁ Δηιόκης ἐρασθεὶς τυραννίδος ἐποίεε τοιάδε. κατοικημένων τῶν Μήδων κατὰ κώμας, ἐν τῇ ἑωυτοῦ ἐὼν καὶ πρότερον δόκιμος καὶ μᾶλλόν τι καὶ προθυμότερον δικαιοσύνην ἐπιθέμενος ἤσκεε· καὶ ταῦτα μέντοι ἐούσης ἀνομίης πολλῆς ἀνὰ πᾶσαν τὴν Μηδικὴν ἐποίεε, ἐπιστάμενος ὅτι τῷ δικαίῳ τὸ ἄδικον πολέμιον ἐστί. οἱ δ’ ἐκ τῆς αὐτῆς κώμης Μῆδοι ὁρῶντες αὐτοῦ τοὺς τρόπους δικαστήν μιν ἑωυτῶν αἱρέοντο. ὁ δὲ δή, οἷα μνώμενος ἀρχήν, ἰθύς τε καὶ δίκαιος ἦν, ποιέων τε ταῦτα ἔπαινον εἶχε οὐκ ὀλίγον πρὸς τῶν πολιητέων, οὕτω ὥστε πυνθανόμενοι οἱ ἐν τῇσι ἄλλῃσι κώμῃσι ὡς Δηιόκης εἴη ἀνὴρ μοῦνος κατὰ τὸ ὀρθὸν δικάζων, πρότερον περιπίπτοντες ἀδίκοισι γνώμῃσι, τότε ἐπείτε ἤκουσαν ἄσμενοι, ἐφοίτων παρὰ τὸν Δηιόκεα καὶ αὐτοὶ δικασόμενοι, τέλος δὲ οὐδενὶ ἄλλῳ ἐπετράποντο.", "st": "1.96"}, {"sp": "N", "t": "πλεῦνος δὲ αἰεὶ γινομένου τοῦ ἐπιφοιτέοντος, οἷα πυνθανομένων τὰς δίκας ἀποβαίνειν κατὰ τὸ ἐόν, γνοὺς ὁ Δηιόκης ἐς ἑωυτὸν πᾶν ἀνακείμενον οὔτε κατίζειν ἔτι ἤθελε ἔνθα περ πρότερον προκατίζων ἐδίκαζε, οὔτ’ ἔφη δίκαν ἔτι· οὐ γὰρ οἱ λυσιτελέειν τῶν ἑωυτοῦ ἐξημεληκότα τοῖσι πέλας δι’ ἡμέρης δικάζειν. ἐούσης ὦν ἁρπαγῆς καὶ ἀνομίης ἔτι πολλῷ μᾶλλον ἀνὰ τὰς κώμας ἢ πρότερον ἦν, συνελέχθησαν οἱ Μῆδοι ἐς τὠυτὸ καὶ ἐδίδοσαν σφίσι λόγον, λέγοντες περὶ τῶν κατηκόντων. ὡς δ’ ἐγὼ δοκέω, μάλιστα ἔλεγον οἱ τοῦ Δηιόκεω φίλοι οὐ γὰρ δὴ τρόπῳ τῷ παρεόντι χρεώμενοι δυνατοὶ εἰμὲν οἰκέειν τὴν χώρην, φέρε στήσωμεν ἡμέων αὐτῶν βασιλέα· καὶ οὕτω ἥ τε χώρη εὐνομήσεται καὶ αὐτοὶ πρὸς ἔργα τρεψόμεθα, οὐδὲ ὑπ’ ἀνομίης ἀνάστατοι ἐσόμεθα. ταῦτά κῃ λέγοντες πείθουσι ἑωυτοὺς βασιλεύεσθαι.", "st": "1.97"}, {"sp": "N", "t": "αὐτίκα δὲ προβαλλομένων ὅντινα στήσονται βασιλέα, ὁ Δηιόκης ἦν πολλὸς ὑπὸ παντὸς ἀνδρὸς καὶ προβαλλόμενος καὶ αἰνεόμενος, ἐς ὃ τοῦτον καταινέουσι βασιλέα σφίσι εἶναι. ὃ δ’ ἐκέλευε αὐτοὺς οἰκία τε ἑωυτῷ ἄξια τῆς βασιληίης οἰκοδομῆσαι καὶ κρατῦναι αὐτὸν δορυφόροισι· ποιεῦσι δὴ ταῦτα οἱ Μῆδοι. οἰκοδομέουσί τε γὰρ αὐτῷ οἰκία μεγάλα τε καὶ ἰσχυρά, ἵνα αὐτὸς ἔφρασε τῆς χώρης, καὶ δορυφόρους αὐτῷ ἐπιτρέπουσι ἐκ πάντων Μήδων καταλέξασθαι. ὁ δὲ ὡς ἔσχε τὴν ἀρχήν, τοὺς Μήδους ἠνάγκασε ἓν πόλισμα ποιήσασθαι καὶ τοῦτο περιστέλλοντας τῶν ἄλλων ἧσσον ἐπιμέλεσθαι. πειθομένων δὲ καὶ ταῦτα τῶν Μήδων οἰκοδομέει τείχεα μεγάλα τε καὶ καρτερὰ ταῦτα τὰ νῦν Ἀγβάτανα κέκληται, ἕτερον ἑτέρῳ κύκλῳ ἐνεστεῶτα. μεμηχάνηται δὲ οὕτω τοῦτο τὸ τεῖχος ὥστε ὁ ἕτερος τοῦ ἑτέρου κύκλος τοῖσι προμαχεῶσι μούνοισι ἐστι ὑψηλότερος. τὸ μέν κού τι καὶ τὸ χωρίον συμμαχέει κολωνὸς ἐὼν ὥστε τοιοῦτο εἶναι, τὸ δὲ καὶ μᾶλλόν τι ἐπετηδεύθη. κύκλων δ’ ἐόντων τῶν συναπάντων ἑπτά, ἐν δὴ τῷ τελευταίῳ τὰ βασιλήια ἔνεστι καὶ οἱ θησαυροί. τὸ δ’ αὐτῶν μέγιστον ἐστὶ τεῖχος κατὰ τὸν Ἀθηνέων κύκλον μάλιστά κῃ τὸ μέγαθος. τοῦ μὲν δὴ πρώτου κύκλου οἱ προμαχεῶνες εἰσὶ λευκοί, τοῦ δὲ δευτέρου μέλανες, τρίτου δὲ κύκλου φοινίκεοι, τετάρτου δὲ κυάνεοι, πέμπτου δὲ σανδαράκινοι. οὕτω τῶν πέντε κύκλων οἱ προμαχεῶνες ἠνθισμένοι εἰσὶ φαρμάκοισι· δύο δὲ οἱ τελευταῖοί εἰσὶ ὃ μὲν καταργυρωμένους ὁ δὲ κατακεχρυσωμένους ἔχων τοὺς προμαχεῶνας.", "st": "1.98"}, {"sp": "N", "t": "ταῦτα μὲν δὴ ὁ Δηιόκης ἑωυτῷ τε ἐτείχεε καὶ περὶ τὰ ἑωυτοῦ οἰκία, τὸν δὲ ἄλλον δῆμον πέριξ ἐκέλευε τὸ τεῖχος οἰκέειν. οἰκοδομηθέντων δὲ πάντων κόσμον τόνδε Δηιόκης πρῶτος ἐστὶ ὁ καταστησάμενος, μήτε ἐσιέναι παρὰ βασιλέα μηδένα, δι’ ἀγγέλων δὲ πάντα χρᾶσθαι, ὁρᾶσθαι τε βασιλέα ὑπὸ μηδενός, πρός τε τούτοισι ἔτι γελᾶν τε καὶ ἀντίον πτύειν καὶ ἅπασι εἶναι τοῦτό γε αἰσχρόν. ταῦτα δὲ περὶ ἑωυτὸν ἐσέμνυνε τῶνδε εἵνεκεν, ὅκως ἂν μὴ ὁρῶντες οἱ ὁμήλικες, ἐόντες σύντροφοί τε ἐκείνῳ καὶ οἰκίης οὐ φλαυροτέρης οὐδὲ ἐς ἀνδραγαθίην λειπόμενοι, λυπεοίατο καὶ ἐπιβουλεύοιεν, ἀλλ’ ἑτεροῖός σφι δοκέοι εἶναι μὴ ὁρῶσι.", "st": "1.99"}, {"sp": "N", "t": "ἐπείτε δὲ ταῦτα διεκόσμησε καὶ ἐκράτυνε ἑωυτὸν τῇ τυραννίδι, ἦν τὸ δίκαιον φυλάσσων χαλεπός· καὶ τάς τε δίκας γράφοντες ἔσω παρ’ ἐκεῖνον ἐσπέμπεσκον, καὶ ἐκεῖνος διακρίνων τὰς ἐσφερομένας ἐκπέμπεσκε. ταῦτα μὲν κατὰ τὰς δίκας ἐποίεε, τάδε δὲ ἄλλα ἐκεκοσμέατό οἱ· εἴ τινα πυνθάνοιτο ὑβρίζοντα, τοῦτον ὅκως μεταπέμψαιτο κατ’ ἀξίην ἑκάστου ἀδικήματος ἐδικαίευ, καὶ οἱ κατάσκοποί τε καὶ κατήκοοι ἦσαν ἀνὰ πᾶσαν τὴν χώρην τῆς ἦρχε.", "st": "1.100"}, {"sp": "N", "t": "Δηιόκης μέν νυν τὸ Μηδικὸν ἔθνος συνέστρεψε μοῦνον καὶ τοῦτον ἦρξε· ἔστι δὲ Μήδων τοσάδε γένεα, Βοῦσαι Παρητακηνοὶ Στρούχατες Ἀριζαντοὶ Βούδιοι Μάγοι. γένεα μὲν δὴ Μήδων ἐστὶ τοσάδε.", "st": "1.101"}, {"sp": "N", "t": "Δηιόκεω δὲ παῖς γίνεται Φραόρτης, ὃς τελευτήσαντος Δηιόκεω, βασιλεύσαντος τρία καὶ πεντήκοντα ἔτεα, παρεδέξατο τὴν ἀρχήν, παραδεξάμενος δὲ οὐκ ἀπεχρᾶτο μούνων Μήδων ἄρχειν, ἀλλὰ στρατευσάμενος ἐπὶ τοὺς Πέρσας πρώτοισί τε τούτοισι ἐπεθήκατο καὶ πρώτους Μήδων ὑπηκόους ἐποίησε. μετὰ δὲ ἔχων δύο ταῦτα ἔθνεα καὶ ἀμφότερα ἰσχυρά, κατεστρέφετο τὴν Ἀσίην ἀπ’ ἄλλου ἐπ’ ἄλλο ἰὼν ἔθνος, ἐς ὃ στρατευσάμενος ἐπὶ τοὺς Ἀσσυρίους καὶ Ἀσσυρίων, τούτους οἳ Νίνον εἶχον καὶ ἦρχον πρότερον πάντων, τότε δὲ ἦσαν μεμουνωμένοι μὲν συμμάχων ἅτε ἀπεστεώτων, ἄλλως μέντοι ἑωυτῶν εὖ ἥκοντες, ἐπὶ τούτους δὴ στρατευσάμενος ὁ Φραόρτης αὐτός τε διεφθάρη, ἄρξας δύο καὶ εἴκοσι ἔτεα, καὶ ὁ στρατὸς αὐτοῦ ὁ πολλός.", "st": "1.102"}, {"sp": "N", "t": "Φραόρτεω δὲ τελευτήσαντος ἐξεδέξατο Κυαξάρης ὁ Φραόρτεω τοῦ Δηιόκεω παῖς. οὗτος λέγεται πολλὸν ἔτι γενέσθαι ἀλκιμώτερος τῶν προγόνων, καὶ πρῶτός τε ἐλόχισε κατὰ τέλεα τοὺς ἐν τῇ Ἀσίῃ καὶ πρῶτος διέταξε χωρὶς ἑκάστους εἶναι, τούς τε αἰχμοφόρους καὶ τοὺς τοξοφόρους καὶ τοὺς ἱππέας· πρὸ τοῦ δὲ ἀναμὶξ ἦν πάντα ὁμοίως ἀναπεφυρμένα. οὗτος ὁ τοῖσι Λυδοῖσι ἐστὶ μαχεσάμενος ὅτε νὺξ ἡ ἡμέρη ἐγένετό σφι μαχομένοισι, καὶ ὁ τὴν Ἅλυος ποταμοῦ ἄνω Ἀσίην πᾶσαν συστήσας ἑωυτῷ. συλλέξας δὲ τοὺς ὑπ’ ἑωυτῷ ἀρχομένους πάντας ἐστρατεύετο ἐπὶ τὴν Νίνον, τιμωρέων τε τῷ πατρὶ καὶ τὴν πόλιν ταύτην θέλων ἐξελεῖν. καί οἱ, ὡς συμβαλὼν ἐνίκησε τοὺς Ἀσσυρίους, περικατημένῳ τὴν Νίνον ἐπῆλθε Σκυθέων στρατὸς μέγας, ἦγε δὲ αὐτοὺς βασιλεὺς ὁ Σκυθέων Μαδύης Προτοθύεω παῖς· οἳ ἐσέβαλον μὲν ἐς τὴν Ἀσίην Κιμμερίους ἐκβαλόντες ἐκ τῆς Εὐρώπης, τούτοισι δὲ ἐπισπόμενοι φεύγουσι οὕτω ἐς τὴν Μηδικὴν χώρην ἀπίκοντο.", "st": "1.103"}, {"sp": "N", "t": "ἔστι δὲ ἀπὸ τῆς λίμνης τῆς Μαιήτιδος ἐπὶ Φᾶσιν ποταμὸν καὶ ἐς Κόλχους τριήκοντα ἡμερέων εὐζώνῳ ὁδός, ἐκ δὲ τῆς Κολχίδος οὐ πολλὸν ὑπερβῆναι ἐς τὴν Μηδικήν, ἀλλ’ ἓν τὸ διὰ μέσου ἔθνος αὐτῶν ἐστι, Σάσπειρες, τοῦτο δὲ παραμειβομένοισι εἶναι ἐν τῇ Μηδικῇ. οὐ μέντοι οἵ γε Σκύθαι ταύτῃ ἐσέβαλον, ἀλλὰ τὴν κατύπερθε ὁδὸν πολλῷ μακροτέρην ἐκτραπόμενοι, ἐν δεξιῇ ἔχοντες τὸ Καυκάσιον ὄρος. ἐνθαῦτα οἱ μὲν Μῆδοι συμβαλόντες τοῖσι Σκύθῃσι καὶ ἑσσωθέντες τῇ μάχῃ τῆς ἀρχῆς κατελύθησαν. οἱ δὲ Σκύθαι τὴν Ἀσίην πᾶσαν ἐπέσχον.", "st": "1.104"}, {"sp": "N", "t": "ἐνθεῦτεν δὲ ἤισαν ἐπ’ Αἴγυπτον. καὶ ἐπείτε ἐγένοντο ἐν τῇ Παλαιστίνῃ Συρίῃ, Ψαμμήτιχος σφέας Αἰγύπτου βασιλεὺς ἀντιάσας δώροισί τε καὶ λιτῇσι ἀποτράπει τὸ προσωτέρω μὴ πορεύεσθαι. οἳ δὲ ἐπείτε ἀναχωρέοντες ὀπίσω ἐγένοντο τῆς Συρίης ἐν Ἀσκάλωνι πόλι, τῶν πλεόνων Σκυθέων παρεξελθόντων ἀσινέων, ὀλίγοι τινὲς αὐτῶν ὑπολειφθέντες ἐσύλησαν τῆς οὐρανίης Ἀφροδίτης τὸ ἱρόν. ἔστι δὲ τοῦτο τὸ ἱρόν, ὡς ἐγὼ πυνθανόμενος εὑρίσκω, πάντων ἀρχαιότατον ἱρῶν ὅσα ταύτης τῆς θεοῦ· καὶ γὰρ τὸ ἐν Κύπρῳ ἱρὸν ἐνθεῦτεν ἐγένετο, ὡς αὐτοὶ Κύπριοι λέγουσι, καὶ τὸ ἐν Κυθήροισι Φοίνικές εἰσὶ οἱ ἱδρυσάμενοι ἐκ ταύτης τῆς Συρίης ἐόντες. τοῖσι δὲ τῶν Σκυθέων συλήσασι τὸ ἱρὸν τὸ ἐν Ἀσκάλωνι καὶ τοῖσι τούτων αἰεὶ ἐκγόνοισι ἐνέσκηψε ὁ θεὸς θήλεαν νοῦσον· ὥστε ἅμα λέγουσί τε οἱ Σκύθαι διὰ τοῦτο σφέας νοσέειν, καὶ ὁρᾶν παρ’ ἑωυτοῖσι τοὺς ἀπικνεομένους ἐς τὴν Σκυθικὴν χώρην ὡς διακέαται τοὺς καλέουσι Ἐνάρεας οἱ Σκύθαι.", "st": "1.105"}, {"sp": "N", "t": "ἐπὶ μέν νυν ὀκτὼ καὶ εἴκοσι ἔτεα ἦρχον τῆς Ἀσίης οἱ Σκύθαι, καὶ τὰ πάντα σφι ὑπό τε ὕβριος καὶ ὀλιγωρίης ἀνάστατα ἦν· χωρὶς μὲν γὰρ φόρον ἔπρησσον παρ’ ἑκάστων τὸν ἑκάστοισι ἐπέβαλλον, χωρὶς δὲ τοῦ φόρου ἥρπαζον περιελαύνοντες τοῦτο ὅ τι ἔχοιεν ἕκαστοι. καὶ τούτων μὲν τοὺς πλεῦνας Κυαξάρης τε καὶ Μῆδοι ξεινίσαντες καὶ καταμεθύσαντες κατεφόνευσαν, καὶ οὕτω ἀνεσώσαντο τὴν ἀρχὴν Μῆδοι καὶ ἐπεκράτεον τῶν περ καὶ πρότερον, καὶ τήν τε Νίνον εἷλον (ὡς δὲ εἷλον ἐν ἑτέροισι λόγοισι δηλώσω) καὶ τοὺς Ἀσσυρίους ὑποχειρίους ἐποιήσαντο πλὴν τῆς Βαβυλωνίης μοίρης.", "st": "1.106"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα Κυαξάρης μέν, βασιλεύσας τεσσεράκοντα ἔτεα σὺν τοῖσι Σκύθαι ἦρξαν, τελευτᾷ, ἐκδέκεται δὲ Ἀστυάγης Κυαξάρεω παῖς τὴν βασιληίην. Καὶ οἱ ἐγένετο θυγάτηρ τῇ οὔνομα ἔθετο Μανδάνην· τὴν ἐδόκεε Ἀστυάγης ἐν τῷ ὕπνῳ οὐρῆσαι τοσοῦτον ὥστε πλῆσαι μὲν τὴν ἑωυτοῦ πόλιν, ἐπικατακλύσαι δὲ καὶ τὴν Ἀσίην πᾶσαν. ὑπερθέμενος δὲ τῶν Μάγων τοῖσι ὀνειροπόλοισι τὸ ἐνύπνιον, ἐφοβήθη παρ’ αὐτῶν αὐτὰ ἕκαστα μαθών. μετὰ δὲ τὴν Μανδάνην ταύτην ἐοῦσαν ἤδη ἀνδρὸς ὡραίην Μήδων μὲν τῶν ἑωυτοῦ ἀξίων οὐδενὶ διδοῖ γυναῖκα, δεδοικὼς τὴν ὄψιν· ὁ δὲ Πέρσῃ διδοῖ τῷ οὔνομα ἦν Καμβύσης, τὸν εὕρισκε οἰκίης μὲν ἐόντα ἀγαθῆς τρόπου δὲ ἡσυχίου, πολλῷ ἔνερθε ἄγων αὐτὸν μέσου ἀνδρὸς Μήδου.", "st": "1.107"}, {"sp": "N", "t": "συνοικεούσης δὲ τῷ Καμβύσῃ τῆς Μανδάνης, ὁ Ἀστυάγης τῷ πρώτῳ ἔτεϊ εἶδε ἄλλην ὄψιν, ἐδόκεε δέ οἱ ἐκ τῶν αἰδοίων τῆς θυγατρὸς ταύτης φῦναι ἄμπελον, τὴν δὲ ἄμπελον ἐπισχεῖν τὴν Ἀσίην πᾶσαν. ἰδὼν δὲ τοῦτο καὶ ὑπερθέμενος τοῖσι ὀνειροπόλοισι, μετεπέμψατο ἐκ τῶν Περσέων τὴν θυγατέρα ἐπίτεκα ἐοῦσαν, ἀπικομένην δὲ ἐφύλασσε βουλόμενος τὸ γενόμενον ἐξ αὐτῆς διαφθεῖραι· ἐκ γάρ οἱ τῆς ὄψιος οἱ τῶν Μάγων ὀνειροπόλοι ἐσήμαινον ὅτι μέλλοι ὁ τῆς θυγατρὸς αὐτοῦ γόνος βασιλεύσειν ἀντὶ ἐκείνου. ταῦτα δὴ ὦν φυλασσόμενος ὁ Ἀστυάγης, ὡς ἐγένετο ὁ Κῦρος, καλέσας Ἅρπαγον ἄνδρα οἰκήιον καὶ πιστότατόν τε Μήδων καὶ πάντων ἐπίτροπον τῶν ἑωυτοῦ, ἔλεγέ οἱ τοιάδε. Ἅρπαγε, πρῆγμα τὸ ἄν τοι προσθέω, μηδαμῶς παραχρήσῃ, μηδὲ ἐμέ τε παραβάλῃ καὶ ἄλλους ἑλόμενος ἐξ ὑστέρης σοὶ αὐτῷ περιπέσῃς· λάβε τὸν Μανδάνη ἔτεκε παῖδα, φέρων δὲ ἐς σεωυτοῦ ἀπόκτεινον, μετὰ δὲ θάψον τρόπῳ ὅτεῳ αὐτὸς βούλεαι. ὁ δὲ ἀμείβεται ὦ βασιλεῦ, οὔτε ἄλλοτε κω παρεῖδες ἀνδρὶ τῷδε ἄχαρι οὐδέν, φυλασσόμεθα δὲ ἐς σὲ καὶ ἐς τὸν μετέπειτα χρόνον μηδὲν ἐξαμαρτεῖν. ἀλλ’ εἲ τοι φίλον τοῦτο οὕτω γίνεσθαι, χρὴ δὴ τό γε ἐμὸν ὑπηρετέεσθαι ἐπιτηδέως.", "st": "1.108"}, {"sp": "N", "t": "τούτοισι ἀμειψάμενος ὁ Ἅρπαγος, ὥς οἱ παρεδόθη τὸ παιδίον κεκοσμημένον τὴν ἐπὶ θανάτῳ ἤιε κλαίων ἐς τὰ οἰκία· παρελθὼν δὲ ἔφραζε τῇ ἑωυτοῦ γυναικὶ τὸν πάντα Ἀστυάγεος ῥηθέντα λόγον. ἣ δὲ πρὸς αὐτὸν λέγει νῦν ὦν τί σοὶ ἐν νόῳ ἐστὶ ποιέειν; ὁ δὲ ἀμείβεται οὐ τῇ ἐνετέλλετο Ἀστυάγης, οὐδ’ εἰ παραφρονήσει τε καὶ μανέεται κάκιον ἢ νῦν μαίνεται, οὔ οἱ ἔγωγε προσθήσομαι τῇ γνώμῃ οὐδὲ ἐς φόνον τοιοῦτον ὑπηρετήσω. πολλῶν δὲ εἵνεκα οὐ φονεύσω μιν, καὶ ὅτι αὐτῷ μοι συγγενής ἐστὶ ὁ παῖς, καὶ ὅτι Ἀστυάγης μὲν ἐστὶ γέρων καὶ ἅπαις ἔρσενος γόνου· εἰ δ’ ἐθελήσει τούτου τελευτήσαντος ἐς τὴν θυγατέρα ταύτην ἀναβῆναι ἡ τυραννίς, τῆς νῦν τὸν υἱὸν κτείνει δι’ ἐμεῦ, ἄλλο τι ἢ λείπεται τὸ ἐνθεῦτεν ἐμοὶ κινδύνων ὁ μέγιστος; ἀλλὰ τοῦ μὲν ἀσφαλέος εἵνεκα ἐμοὶ δεῖ τοῦτον τελευτᾶν τὸν παῖδα, δεῖ μέντοι τῶν τινα Ἀστυάγεος αὐτοῦ φονέα γενέσθαι καὶ μὴ τῶν ἐμῶν.", "st": "1.109"}, {"sp": "N", "t": "ταῦτα εἶπε καὶ αὐτίκα ἄγγελον ἔπεμπε ἐπὶ τῶν βουκόλων τῶν Ἀστυάγεος τὸν ἠπίστατο νομάς τε ἐπιτηδεοτάτας νέμοντα καὶ ὄρεα θηριωδέστατα· τῷ οὔνομα ἦν Μιτραδάτης, συνοίκεε δὲ ἑωυτοῦ συνδούλῃ, οὔνομα δὲ τῇ γυναικὶ ἦν τῇ συνοίκεε Κυνὼ κατὰ τὴν Ἑλλήνων γλῶσσαν, κατὰ δὲ τὴν Μηδικὴν Σπακώ· τὴν γὰρ κύνα καλέουσι σπάκα Μῆδοι. αἱ δὲ ὑπώρεαί εἰσὶ τῶν ὀρέων, ἔνθα τὰς νομὰς τῶν βοῶν εἶχε οὗτος δὴ ὁ βουκόλος, πρὸς βορέω τε ἀνέμου τῶν Ἀγβατάνων καὶ πρὸς τοῦ πόντου τοῦ Εὐξείνου· ταύτῃ μὲν γὰρ ἡ Μηδικὴ χωρῇ πρὸς Σασπείρων ὀρεινή ἐστι κάρτα καὶ ὑψηλή τε καὶ ἴδῃσι συνηρεφής, ἡ δὲ ἄλλη Μηδικὴ χωρῇ ἐστὶ πᾶσα ἄπεδος. ἐπεὶ ὦν ὁ βουκόλος σπουδῇ πολλῇ καλεόμενος ἀπίκετο, ἔλεγε ὁ Ἅρπαγος τάδε. κελεύει σε Ἀστυάγης τὸ παιδίον τοῦτο λαβόντα θεῖναι ἐς τὸ ἐρημότατον τῶν ὀρέων, ὅκως ἂν τάχιστα διαφθαρείη· καὶ τάδε τοὶ ἐκέλευσε εἰπεῖν, ἢν μὴ ἀποκτείνῃς αὐτὸ ἀλλὰ τεῷ τρόπῳ περιποιήσῃς, ὀλέθρῳ τῷ κακίστῳ σε διαχρήσεσθαι. ἐπορᾶν δὲ ἐκκείμενον τέταγμαι ἐγώ.", "st": "1.110"}, {"sp": "N", "t": "ταῦτα ἀκούσας ὁ βουκόλος καὶ ἀναλαβὼν τὸ παιδίον ἤιε τὴν αὐτὴν ὀπίσω ὁδὸν καὶ ἀπικνέεται ἐς τὴν ἔπαυλιν. τῷ δ’ ἄρα καὶ αὐτῷ ἡ γυνή, ἐπίτεξ ἐοῦσα πᾶσαν ἡμέρην, τότε κως κατὰ δαίμονα τίκτει οἰχομένου τοῦ βουκόλου ἐς πόλιν. ἦσαν δὲ ἐν φροντίδι ἀμφότεροι ἀλλήλων πέρι, ὃ μὲν τοῦ τόκου τῆς γυναικὸς ἀρρωδέων, ἡ δὲ γυνὴ ὅ τι οὐκ ἐωθὼς ὁ Ἅρπαγος μεταπέμψαιτο αὐτῆς τὸν ἄνδρα. ἐπείτε δὲ ἀπονοστήσας ἐπέστη, οἷα ἐξ ἀέλπτου ἰδοῦσα ἡ γυνὴ εἴρετο προτέρη ὅ τι μιν οὕτω προθύμως Ἅρπαγος μετεπέμψατο. ὁ δὲ εἶπε ὤ γύναι, εἶδόν τε ἐς πόλιν ἐλθὼν καὶ ἤκουσα τὸ μήτε ἰδεῖν ὄφελον μήτε κοτὲ γενέσθαι ἐς δεσπότας τοὺς ἡμετέρους. οἶκος μὲν πᾶς Ἁρπάγου κλαυθμῷ κατείχετο, ἐγὼ δὲ ἐκπλαγεὶς ἤια ἔσω. ὡς δὲ τάχιστα ἐσῆλθον, ὁρέω παιδίον προκείμενον ἀσπαῖρόν τε καὶ κραυγανόμενον, κεκοσμημένον χρυσῷ τε καὶ ἐσθῆτι ποικίλῃ. Ἅρπαγος δὲ ὡς εἶδέ με, ἐκέλευε τὴν ταχίστην ἀναλαβόντα τὸ παιδίον οἴχεσθαι φέροντα καὶ θεῖναι ἔνθα θηριωδέστατον εἴη τῶν ὀρέων, φὰς Ἀστυάγεα εἶναι τὸν ταῦτα ἐπιθέμενόν μοι, πόλλ’ ἀπειλήσας εἰ μή σφεα ποιήσαιμι. καὶ ἐγὼ ἀναλαβὼν ἔφερον, δοκέων τῶν τινος οἰκετέων εἶναι· οὐ γὰρ ἂν κοτὲ κατέδοξα ἔνθεν γε ἦν. ἐθάμβεον δὲ ὁρέων χρυσῷ τε καὶ εἵμασι κεκοσμημένον, πρὸς δὲ καὶ κλαυθμὸν κατεστεῶτα ἐμφανέα ἐν Ἁρπάγου. καὶ πρόκατε δὴ κατ’ ὁδὸν πυνθάνομαι τὸν πάντα λόγον θεράποντος, ὃς ἐμὲ προπέμπων ἔξω πόλιος ἐνεχείρισε τὸ βρέφος, ὡς ἄρα Μανδάνης τε εἴη παῖς τῆς Ἀστυάγεος θυγατρὸς καὶ Καμβύσεω τοῦ Κύρου, καί μιν Ἀστυάγης ἐντέλλεται ἀποκτεῖναι. νῦν τε ὅδε ἐστί.", "st": "1.111"}, {"sp": "N", "t": "ἅμα δὲ ταῦτα ἔλεγε ὁ βουκόλος καὶ ἐκκαλύψας ἀπεδείκνυε. ἣ δὲ ὡς εἶδε τὸ παιδίον μέγα τε καὶ εὐειδὲς ἐόν, δακρύσασα καὶ λαβομένη τῶν γουνάτων τοῦ ἀνδρὸς ἐχρήιζε μηδεμιῇ τέχνῃ ἐκθεῖναί μιν. ὁ δὲ οὐκ ἔφη οἷός τ’ εἶναι ἄλλως αὐτὰ ποιέειν· ἐπιφοιτήσειν γὰρ κατασκόπους ἐξ Ἁρπάγου ἐποψομένους, ἀπολέεσθαί τε κάκιστα ἢν μὴ σφεα ποιήσῃ. ὡς δὲ οὐκ ἔπειθε ἄρα τὸν ἄνδρα, δευτέρα λέγει ἡ γυνὴ τάδε. ἐπεὶ τοίνυν οὐ δύναμαί σε πείθειν μὴ ἐκθεῖναι, σὺ δὲ ὧδε ποίησον, εἰ δὴ πᾶσα ἀνάγκη ὀφθῆναι ἐκκείμενον. τέτοκα γὰρ καὶ ἐγώ, τέτοκα δὲ τεθνεός. τοῦτο μὲν φέρων πρόθες, τὸν δὲ τῆς Ἀστυάγεος θυγατρὸς παῖδα ὡς ἐξ ἡμέων ἐόντα τρέφωμεν. καὶ οὕτω οὔτε σὺ ἁλώσεαι ἀδικέων τοὺς δεσπότας οὔτε ἡμῖν κακῶς βεβουλευμένα ἔσται· ὅ τε γὰρ τεθνεὼς βασιληίης ταφῆς κυρήσει καὶ ὁ περιεὼν οὐκ ἀπολέει τὴν ψυχήν.", "st": "1.112"}, {"sp": "N", "t": "κάρτα τε ἔδοξε τῷ βουκόλῳ πρὸς τὰ παρεόντα εὖ λέγειν ἡ γυνή, καὶ αὐτίκα ἐποίεε ταῦτα· τὸν μὲν ἔφερε θανατώσων παῖδα, τοῦτον μὲν παραδιδοῖ τῇ ἑωυτοῦ γυναικί, τὸν δὲ ἑωυτοῦ ἐόντα νεκρὸν λαβὼν ἔθηκε ἐς τὸ ἄγγος ἐν τῷ ἔφερε τὸν ἕτερον· κοσμήσας δὲ τῷ κόσμῳ παντὶ τοῦ ἑτέρου παιδός, φέρων ἐς τὸ ἐρημότατον τῶν ὀρέων τίθει. ὡς δὲ τρίτη ἡμέρη τῷ παιδίῳ ἐκκειμένῳ ἐγένετο, ἤιε ἐς πόλιν ὁ βουκόλος, τῶν τινα προβοσκῶν φύλακον αὐτοῦ καταλιπών, ἐλθὼν δὲ ἐς τοῦ Ἁρπάγου ἀποδεικνύναι ἔφη ἕτοιμος εἶναι τοῦ παιδίου τὸν νέκυν. πέμψας δὲ ὅ Ἅρπαγος τῶν ἑωυτοῦ δορυφόρων τοὺς πιστοτάτους εἶδέ τε διὰ τούτων καὶ ἔθαψε τοῦ βουκόλου τὸ παιδίον, καὶ τὸ μὲν ἐτέθαπτο, τὸν δὲ ὕστερον τούτων Κῦρον ὀνομασθέντα παραλαβοῦσα ἔτρεφε ἡ γυνὴ τοῦ βουκόλου, οὔνομα ἄλλο κού τι καὶ οὐ Κῦρον θεμένη.", "st": "1.113"}, {"sp": "N", "t": "καὶ ὅτε ἦν δεκαέτης ὁ παῖς, πρῆγμα ἐς αὑτὸν τοιόνδε γενόμενον ἐξέφηνέ μιν. ἔπαιζε ἐν τῇ κώμῃ ταύτῃ ἐν τῇ ἦσαν καὶ αἱ βουκολίαι αὗται, ἔπαιζε δὲ μετ’ ἄλλων ἡλίκων ἐν ὁδῷ. καὶ οἱ παῖδες παίζοντες εἵλοντο ἑωυτῶν βασιλέα εἶναι τοῦτον δὴ τὸν τοῦ βουκόλου ἐπίκλησιν παῖδα. ὁ δὲ αὐτῶν διέταξε τοὺς μὲν οἰκίας οἰκοδομέειν, τοὺς δὲ δορυφόρους εἶναι, τὸν δέ κου τινὰ αὐτῶν ὀφθαλμὸν βασιλέος εἶναι, τῷ δὲ τινὶ τὰς ἀγγελίας φέρειν ἐδίδου γέρας, ὡς ἑκάστῳ ἔργον προστάσσων. εἷς δὴ τούτων τῶν παίδων συμπαίζων, ἐὼν Ἀρτεμβάρεος παῖς ἀνδρὸς δοκίμου ἐν Μήδοισι, οὐ γὰρ δὴ ἐποίησε τὸ προσταχθὲν ἐκ τοῦ Κύρου, ἐκέλευε αὐτὸν τοὺς ἄλλους παῖδας διαλαβεῖν, πειθομένων δὲ τῶν παίδων ὁ Κῦρος τὸν παῖδα τρηχέως κάρτα περιέσπε μαστιγέων. ὁ δὲ ἐπείτε μετείθη τάχιστα, ὡς γε δὴ ἀνάξια ἑωυτοῦ παθών, μᾶλλόν τι περιημέκτεε, κατελθὼν δὲ ἐς πόλιν πρὸς τὸν πατέρα ἀποικτίζετο τῶν ὑπὸ Κύρου ἤντησε, λέγων δὲ οὐ Κύρου (οὐ γάρ κω ἦν τοῦτο τοὔνομα), ἀλλὰ πρὸς τοῦ βουκόλου τοῦ Ἀστυάγεος παιδός. ὁ δὲ Ἀρτεμβάρης ὀργῇ ὡς εἶχε ἐλθὼν παρὰ τὸν Ἀστυάγεα καὶ ἅμα ἀγόμενος τὸν παῖδα ἀνάρσια πρήγματα ἔφη πεπονθέναι, λέγων ὦ βασιλεῦ, ὑπὸ τοῦ σοῦ δούλου, βουκόλου δὲ παιδὸς ὧδε περιυβρίσμεθα, δεικνὺς τοῦ παιδὸς τοὺς ὤμους.", "st": "1.114"}, {"sp": "N", "t": "ἀκούσας δὲ καὶ ἰδὼν Ἀστυάγης, θέλων τιμωρῆσαι τῷ παιδὶ τιμῆς τῆς Ἀρτεμβάρεος εἵνεκα, μετεπέμπετο τόν τε βουκόλον καὶ τὸν παῖδα. ἐπείτε δὲ παρῆσαν ἀμφότεροι, βλέψας πρὸς τὸν Κῦρον ὁ Ἀστυάγης ἔφη σὺ δὴ ἐὼν τοῦδε τοιούτου ἐόντος παῖς ἐτόλμησας τὸν τοῦδε παῖδα ἐόντος πρώτου παρ’ ἐμοὶ ἀεικείῃ τοιῇδε περισπεῖν; ὁ δὲ ἀμείβετο ὧδε. ὦ δέσποτα, ἐγὼ ταῦτα τοῦτον ἐποίησα σὺν δίκῃ. οἱ γάρ με ἐκ τῆς κώμης παῖδες, τῶν καὶ ὅδε ἦν, παίζοντες σφέων αὐτῶν ἐστήσαντο βασιλέα· ἐδόκεον γὰρ σφι εἶναι ἐς τοῦτο ἐπιτηδεότατος. οἱ μέν νυν ἄλλοι παῖδες τὰ ἐπιτασσόμενα ἐπετέλεον, οὗτος δὲ ἀνηκούστεέ τε καὶ λόγον εἶχε οὐδένα, ἐς ὃ ἔλαβε τὴν δίκην. εἰ ὦν δὴ τοῦδε εἵνεκα ἄξιός τευ κακοῦ εἰμί, ὅδε τοὶ πάρειμι.", "st": "1.115"}, {"sp": "N", "t": "ταῦτα λέγοντος τοῦ παιδὸς τὸν Ἀστυάγεα ἐσήιε ἀνάγνωσις αὐτοῦ, καὶ οἱ ὅ τε χαρακτὴρ τοῦ προσώπου προσφέρεσθαι ἐδόκεε ἐς ἑωυτὸν καὶ ἡ ὑπόκρισις ἐλευθερωτέρη εἶναι, ὅ τε χρόνος τῆς ἐκθέσιος τῇ ἡλικίῃ τοῦ παιδὸς ἐδόκεε συμβαίνειν. ἐκπλαγεὶς δὲ τούτοισι ἐπὶ χρόνον ἄφθογγος ἦν· μόγις δὲ δή κοτε ἀνενειχθεὶς εἶπε, θέλων ἐκπέμψαι τὸν Ἀρτεμβάρεα, ἵνα τὸν βουκόλον μοῦνον λαβὼν βασανίσῃ, Ἀρτέμβαρες, ἐγὼ ταῦτα ποιήσω ὥστε σὲ καὶ τὸν παῖδα τὸν σὸν μηδὲν ἐπιμέμφεσθαι. τὸν μὲν δὴ Ἀρτεμβάρεα πέμπει, τὸν δὲ Κῦρον ἦγον ἔσω οἱ θεράποντες κελεύσαντος τοῦ Ἀστυάγεος, ἐπεὶ δὲ ὑπελέλειπτο ὁ βουκόλος μοῦνος μουνόθεν, τάδε αὐτὸν εἴρετο ὁ Ἀστυάγεος, κόθεν λάβοι τὸν παῖδα καὶ τίς εἴη ὁ παραδούς. ὁ δὲ ἐξ ἑωυτοῦ τε ἔφη γεγονέναι καὶ τὴν τεκοῦσαν αὐτὸν εἶναι ἔτι παρ’ ἑωυτῷ. Ἀστυάγης δὲ μιν οὐκ εὖ βουλεύεσθαι ἔφη ἐπιθυμέοντα ἐς ἀνάγκας μεγάλας ἀπικνέεσθαι, ἅμα τε λέγων ταῦτα ἐσήμαινε τοῖσι δορυφόροισι λαμβάνειν αὐτόν. ὁ δὲ ἀγόμενος ἐς τὰς ἀνάγκας οὕτω δὴ ἔφαινε τὸν ἐόντα λόγον· ἀρχόμενος δὲ ἀπ’ ἀρχῆς διεξήιε τῇ ἀληθείῃ χρεώμενος, καὶ κατέβαινε ἐς λιτάς τε καὶ συγγνώμην ἑωυτῷ κελεύων ἔχειν αὐτόν.", "st": "1.116"}, {"sp": "N", "t": "Ἀστυάγης δὲ τοῦ μὲν βουκόλου τὴν ἀληθείην ἐκφήναντος λόγον ἤδη καὶ ἐλάσσω ἐποιέετο, Ἁρπάγῳ δὲ καὶ μεγάλως μεμφόμενος καλέειν αὐτὸν τοὺς δορυφόρους ἐκέλευε. ὡς δέ οἱ παρῆν ὁ Ἅρπαγος, εἴρετό μιν ὁ Ἀστυάγης Ἅρπαγε, τέῳ δὴ μόρῳ τὸν παῖδα κατεχρήσαο τόν τοι παρέδωκα ἐκ θυγατρὸς γεγονότα τῆς ἐμῆς; ὁ δὲ Ἅρπαγος ὡς εἶδε τὸν βουκόλον ἔνδον ἐόντα, οὐ τρέπεται ἐπὶ ψευδέα ὁδόν, ἵνα μὴ ἐλεγχόμενος ἁλίσκηται, ἀλλὰ λέγει τάδε. ὦ βασιλεῦ, ἐπείτε παρέλαβον τὸ παιδίον, ἐβούλευον σκοπέων ὅκως σοί τε ποιήσω κατὰ νόον, καὶ ἐγὼ πρὸς σὲ γινόμενος ἀναμάρτητος μήτε θυγατρὶ τῇ σῇ μήτε αὐτῷ σοὶ εἴην αὐθέντης. ποιέω δὴ ὧδε· καλέσας τὸν βουκόλον τόνδε παραδίδωμι τὸ παιδίον, φὰς σέ τε εἶναι τὸν κελεύοντα ἀποκτεῖναι αὐτό. καὶ λέγων τοῦτό γε οὐκ ἐψευδόμην· σὺ γὰρ ἐνετέλλεο οὕτω. παραδίδωμι μέντοι τῷδε κατὰ τάδε ἐντειλάμενος, θεῖναί μιν ἐς ἔρημον ὄρος καὶ παραμένοντα φυλάσσειν ἄχρι οὗ τελευτήσῃ, ἀπειλήσας παντοῖα τῷδε ἢν μὴ τάδε ἐπιτελέα ποιήσῃ. ἐπείτε δὲ ποιήσαντος τούτου τὰ κελευόμενα ἐτελεύτησε τὸ παιδίον, πέμψας τῶν εὐνούχων τοὺς πιστοτάτους καὶ εἶδον δι’ ἐκείνων καὶ ἔθαψά μιν. οὕτω ἔσχε ὦ βασιλεῦ περὶ τοῦ πρήγματος τούτου, καὶ τοιούτῳ μόρῳ ἐχρήσατο ὁ παῖς.", "st": "1.117"}, {"sp": "N", "t": "Ἅρπαγος μὲν δὴ τὸν ἰθὺν ἔφαινε λόγον· Ἀστυάγης δὲ κρύπτων τὸν οἱ ἐνεῖχε χόλον διὰ τὸ γεγονός, πρῶτα μέν, κατά περ ἤκουσε αὐτὸς πρὸς τοῦ βουκόλου τὸ πρῆγμα, πάλιν ἀπηγέετο τῷ Ἁρπάγῳ, μετὰ δὲ ὣς οἱ ἐπαλιλλόγητο, κατέβαινε λέγων ὡς περίεστί τε ὁ παῖς καὶ τὸ γεγονὸς ἔχει καλῶς· τῷ τε γὰρ πεποιημένῳ ἔφη λέγων ἐς τὸν παῖδα τοῦτον ἔκαμνον μεγάλως, καὶ θυγατρὶ τῇ ἐμῇ διαβεβλημένος οὐκ ἐν ἐλαφρῷ ἐποιεύμην. ὡς ὦν τῆς τύχης εὖ μετεστεώσης, τοῦτο μὲν τὸν σεωυτοῦ παῖδα ἀπόπεμψον παρὰ τὸν παῖδα τὸν νεήλυδα, τοῦτο δὲ (σῶστρα γὰρ τοῦ παιδὸς μέλλω θύειν τοῖσι θεῶν τιμὴ αὕτη προσκέεται) πάρισθί μοι ἐπὶ δεῖπνον.", "st": "1.118"}, {"sp": "N", "t": "Ἅρπαγος μὲν ὡς ἤκουσε ταῦτα, προσκυνήσας καὶ μεγάλα ποιησάμενος ὅτι τε ἡ ἁμαρτὰς οἱ ἐς δέον ἐγεγόνεε καὶ ὅτι ἐπὶ τύχῃσι χρηστῇσι ἐπὶ δεῖπνον ἐκέκλητο, ἤιε ἐς τὰ οἰκία. ἐσελθὼν δὲ τὴν ταχίστην, ἦν γὰρ οἱ παῖς εἷς μοῦνος ἔτεα τρία καὶ δέκα κου μάλιστα γεγονώς, τοῦτον ἐκπέμπεν ἰέναι τε κελεύων ἐς Ἀστυάγεος καὶ ποιέειν ὅ τι ἂν ἐκεῖνος κελεύῃ, αὐτὸς δὲ περιχαρὴς ἐὼν φράζει τῇ γυναικὶ τὰ συγκυρήσαντα. Ἀστυάγης δέ, ὥς οἱ ἀπίκετο ὁ Ἁρπάγου παῖς, σφάξας αὐτὸν καὶ κατὰ μέλεα διελὼν τὰ μὲν ὤπτησε τὰ δὲ ἥψησε τῶν κρεῶν, εὔτυκα δὲ ποιησάμενος εἶχε ἕτοιμα. ἐπείτε δὲ τῆς ὥρης γινομένης τοῦ δείπνου παρῆσαν οἵ τε ἄλλοι δαιτυμόνες καὶ ὁ Ἅρπαγος, τοῖσι μὲν ἄλλοισι καὶ αὐτῷ Ἀστυάγεϊ παρετιθέατο τράπεζαι ἐπίπλεαι μηλέων κρεῶν, Ἁρπάγῳ δὲ τοῦ παιδὸς τοῦ ἑωυτοῦ, πλὴν κεφαλῆς τε καὶ ἄκρων χειρῶν τε καὶ ποδῶν, τἄλλα πάντα· ταῦτα δὲ χωρὶς ἔκειτο ἐπὶ κανέῳ κατακεκαλυμμένα, ὡς δὲ τῷ Ἁρπάγῳ ἐδόκεε ἅλις ἔχειν τῆς βορῆς, Ἀστυάγης εἴρετό μιν εἰ ἡσθείη τι τῇ θοίνῃ. φαμένου δὲ Ἁρπάγου καὶ κάρτα ἡσθῆναι, παρέφερον τοῖσι προσέκειτο τὴν κεφαλὴν τοῦ παιδὸς κατακεκαλυμμένην καὶ τὰς χεῖρας καὶ τοὺς πόδας, Ἅρπαγον δὲ ἐκέλευον προσστάντες ἀποκαλύπτειν τε καὶ λαβεῖν τὸ βούλεται αὐτῶν. πειθόμενος δὲ ὁ Ἅρπαγος καὶ ἀποκαλύπτων ὁρᾷ τοῦ παιδὸς τὰ λείμματα, ἰδὼν δὲ οὔτε ἐξεπλάγη ἐντός τε ἑωυτοῦ γίνεται. εἴρετο δὲ αὐτὸν ὁ Ἀστυάγης εἰ γινώσκοι ὅτευ θηρίου κρέα βεβρώκοι. ὁ δὲ καὶ γινώσκειν ἔφη καὶ ἀρεστὸν εἶναι πᾶν τὸ ἂν βασιλεὺς ἔρδῃ. τούτοισι δὲ ἀμειψάμενος καὶ ἀναλαβὼν τὰ λοιπὰ τῶν κρεῶν ἤιε ἐς τὰ οἰκία, ἐνθεῦτεν δὲ ἔμελλε, ὡς ἐγὼ δοκέω, ἁλίσας θάψειν τὰ πάντα.", "st": "1.119"}, {"sp": "N", "t": "Ἁρπάγῳ μὲν Ἀστυάγης δίκην ταύτην ἐπέθηκε, Κύρου δὲ πέρι βουλεύων ἐκάλεε τοὺς αὐτοὺς τῶν Μάγων οἳ τὸ ἐνύπνιόν οἱ ταύτῃ ἔκριναν. ἀπικομένους δὲ εἴρετο ὁ Ἁστυάγης τῇ ἔκρινάν οἱ τὴν ὄψιν. οἳ δὲ κατὰ ταὐτὰ εἶπαν λέγοντες ὡς βασιλεῦσαι χρῆν τὸν παῖδα, εἰ ἐπέζωσε καὶ μὴ ἀπέθανε πρότερον. ὁ δὲ ἀμείβεται αὐτοὺς τοῖσιδε. ἔστι τε ὁ παῖς καὶ περίεστι, καί μιν ἐπ’ ἀγροῦ διαιτώμενον οἱ ἐκ τῆς κώμης παῖδες ἐστήσαντο βασιλέα. ὁ δὲ πάντα ὅσα περ οἱ ἀληθέι λόγῳ βασιλέες ἐτελέωσε ποιήσας· καὶ γὰρ δορυφόρους καὶ θυρωροὺς καὶ ἀγγελιηφόρους καὶ τὰ λοιπὰ πάντα διατάξας ἦρχε. καὶ νῦν ἐς τί ὑμῖν ταῦτα φαίνεται φέρειν; εἶπαν οἱ Μάγοι εἰ μὲν περίεστί τε καὶ ἐβασίλευσε ὁ παῖς μὴ ἐκ προνοίης τινός, θάρσεέ τε τούτου εἵνεκα καὶ θυμὸν ἔχε ἀγαθόν· οὐ γὰρ ἔτι τὸ δεύτερον ἄρχει. παρὰ σμικρὰ γὰρ καὶ τῶν λογίων ἡμῖν ἔνια κεχώρηκε, καὶ τά γε τῶν ὀνειράτων ἐχόμενα τελέως ἐς ἀσθενὲς ἔρχεται. ἀμείβεται ὁ Ἀστυάγης τοῖσιδε. καὶ αὐτὸς ὦ Μάγοι ταύτῃ πλεῖστος γνώμην εἰμί, βασιλέος ὀνομασθέντος τοῦ παιδὸς ἐξήκειν τε τὸν ὄνειρον καί μοι τὸν παῖδα τοῦτον εἶναι δεινὸν ἔτι οὐδέν. ὅμως μέν γέ τοι συμβουλεύσατέ μοι εὖ περισκεψάμενοι τὰ μέλλει ἀσφαλέστατα εἶναι οἴκῳ τε τῷ ἐμῷ καὶ ὑμῖν. εἶπαν πρὸς ταῦτα οἱ Μάγοι ὦ βασιλεῦ, καὶ αὐτοῖσι ἡμῖν περὶ πολλοῦ ἐστι κατορθοῦσθαι ἀρχὴν τὴν σήν. κείνως μὲν γὰρ ἀλλοτριοῦται ἐς τὸν παῖδα τοῦτον περιιοῦσα ἐόντα Πέρσην, καὶ ἡμεῖς ἐόντες Μῆδοι δουλούμεθά τε καὶ λόγου οὐδενὸς γινόμεθα πρὸς Περσέων, ἐόντες ξεῖνοι· σέο δ’ ἐνεστεῶτος βασιλέος, ἐόντος πολιήτεω, καὶ ἄρχομεν τὸ μέρος καὶ τιμὰς πρὸς σέο μεγάλας ἔχομεν. οὕτω ὦν πάντως ἡμῖν σέο καὶ τῆς σῆς ἀρχῆς προοπτέον ἐστί. καὶ νῦν εἰ φοβερόν τι ἐνωρῶμεν, πᾶν ἂν σοὶ προεφράζομεν. νῦν δὲ ἀποσκήψαντος τοῦ ἐνυπνίου ἐς φαῦλον, αὐτοί τε θαρσέομεν καὶ σοὶ ἕτερα τοιαῦτα παρακελευόμεθα. τὸν δὲ παῖδα τοῦτον ἐξ ὀφθαλμῶν ἀπόπεμψαι ἐς Πέρσας τε καὶ τοὺς γειναμένους.", "st": "1.120"}, {"sp": "N", "t": "ἀκούσας ταῦτα ὁ Ἀστυάγης ἐχάρη τε καὶ καλέσας τὸν Κῦρον ἔλεγέ οἱ τάδε. ὦ παῖ, σὲ γὰρ ἐγὼ δι’ ὄψιν ὀνείρου οὐ τελέην ἠδίκεον, τῇ σεωυτοῦ δὲ μοίρῃ περίεις· νῦν ὦν ἴθι χαίρων ἐς Πέρσας, πομποὺς δὲ ἐγὼ ἅμα πέμψω. ἐλθὼν δὲ ἐκεῖ πατέρα τε καὶ μητέρα εὑρήσεις οὐ κατὰ Μιτραδάτην τε τὸν βουκόλον καὶ τὴν γυναῖκα αὐτοῦ.", "st": "1.121"}, {"sp": "N", "t": "ταῦτα εἶπας ὁ Ἀστυάγης ἀποπέμπει τὸν Κῦρον. νοστήσαντα δέ μιν ἐς τοῦ Καμβύσεω τὰ οἰκία ἐδέξαντο οἱ γεινάμενοι, καὶ δεξάμενοι ὡς ἐπύθοντο, μεγάλως ἀσπάζοντο οἷα δὴ ἐπιστάμενοι αὐτίκα τότε τελευτῆσαι, ἱστόρεόν τε ὅτεῳ τρόπῳ περιγένοιτο. ὁ δέ σφι ἔλεγε, φὰς πρὸ τοῦ μὲν οὐκ εἰδέναι ἀλλ’ ἡμαρτηκέναι πλεῖστον, κατ’ ὁδὸν δὲ πυθέσθαι πᾶσαν τὴν ἑωυτοῦ πάθην· ἐπίστασθαι μὲν γὰρ ὡς βουκόλου τοῦ Ἀστυάγεος εἴη παῖς, ἀπὸ δὲ τῆς κεῖθεν ὁδοῦ τὸν πάντα λόγον τῶν πομπῶν πυθέσθαι. τραφῆναι δὲ ἔλεγε ὑπὸ τῆς τοῦ βουκόλου γυναικός, ἤιέ τε ταύτην αἰνέων διὰ παντός, ἦν τέ οἱ ἐν τῷ λόγῳ τὰ πάντα ἡ Κυνώ. οἱ δὲ τοκέες παραλαβόντες τὸ οὔνομα τοῦτο, ἵνα θειοτέρως δοκέῃ τοῖσι Πέρσῃσι περιεῖναί σφι ὁ παῖς, κατέβαλον φάτιν ὡς ἐκκείμενον Κῦρον κύων ἐξέθρεψε.", "st": "1.122"}, {"sp": "N", "t": "ἐνθεῦτεν μὲν ἡ φάτις αὕτη κεχώρηκε. Κύρῳ δὲ ἀνδρευμένῳ καὶ ἐόντι τῶν ἡλίκων ἀνδρηιοτάτῳ καὶ προσφιλεστάτῳ προσέκειτο ὁ Ἅρπαγος δῶρα πέμπων, τίσασθαι Ἀστυάγεα ἐπιθυμέων· ἀπ’ ἑωυτοῦ γὰρ ἐόντος ἰδιώτεω οὐκ ἐνώρα τιμωρίην ἐσομένην ἐς Ἀστυάγεα, Κῦρον δὲ ὁρέων ἐπιτρεφόμενον ἐποιέετο σύμμαχον, τὰς πάθας τὰς Κύρου τῇσι ἑωυτοῦ ὁμοιούμενος. πρὸ δ’ ἔτι τούτου τάδε οἱ κατέργαστο· ἐόντος τοῦ Ἀστυάγεος πικροῦ ἐς τοὺς Μήδους, συμμίσγων ἑνὶ ἑκάστῳ ὁ Ἅρπαγος τῶν πρώτων Μήδων ἀνέπειθε ὡς χρὴ Κῦρον προστησαμένους Ἀστυάγεα παῦσαι τῆς βασιληίης. κατεργασμένου δέ οἱ τούτου καὶ ἐόντος ἑτοίμου, οὕτω δὴ τῷ Κύρῳ διαιτωμένῳ ἐν Πέρσῃσι βουλόμενος Ἅρπαγος δηλῶσαι τὴν ἑωυτοῦ γνώμην ἄλλως μὲν οὐδαμῶς εἶχε ἅτε τῶν ὁδῶν φυλασσομενέων, ὁ δὲ ἐπιτεχνᾶται τοιόνδε· λαγὸν μηχανησάμενος, καὶ ἀνασχίσας τούτου τὴν γαστέρα καὶ οὐδὲν ἀποτίλας, ὡς δὲ εἶχε οὕτω ἐσέθηκε βυβλίον, γράψας τά οἱ ἐδόκεε· ἀπορράψας δὲ τοῦ λαγοῦ τὴν γαστέρα, καὶ δίκτυα δοὺς ἅτε θηρευτῇ τῶν οἰκετέων τῷ πιστοτάτῳ, ἀπέστελλε ἐς τοὺς Πέρσας, ἐντειλάμενός οἱ ἀπὸ γλώσσης διδόντα τὸν λαγὸν Κύρῳ ἐπειπεῖν αὐτοχειρίῃ μιν διελεῖν καὶ μηδένα οἱ ταῦτα ποιεῦντι παρεῖναι.", "st": "1.123"}, {"sp": "N", "t": "ταῦτά τε δὴ ὦν ἐπιτελέα ἐγίνετο καὶ ὁ Κῦρος παραλαβὼν τὸν λαγὸν ἀνέσχισε· εὑρὼν δὲ ἐν αὐτῷ τὸ βυβλίον ἐνεὸν λαβὼν ἐπελέγετο, τὰ δὲ γράμματα ἔλεγε τάδε. ὦ παῖ Καμβύσεω, σὲ γὰρ θεοὶ ἐπορῶσι· οὐ γὰρ ἂν κοτὲ ἐς τοσοῦτο τύχης ἀπίκευ· σύ νυν Ἀστυάγεα τὸν σεωυτοῦ φονέα τῖσαι. κατὰ μὲν γὰρ τὴν τούτου προθυμίην τέθνηκας, τὸ δὲ κατὰ θεούς τε καὶ ἐμὲ περίεις· τά σε καὶ πάλαι δοκέω πάντα ἐκμεμαθηκέναι, σέο τε αὐτοῦ περὶ ὡς ἐπρήχθη, καὶ οἷα ἐγὼ ὑπὸ Ἀστυάγεος πέπονθα, ὅτι σε οὐκ ἀπέκτεινα ἀλλὰ ἔδωκα τῷ βουκόλῳ. σύ νυν, ἢν βούλῃ ἐμοὶ πείθεσθαι, τῆς περ Ἀστυάγης ἄρχει χώρης, ταύτης ἁπάσης ἄρξεις. Πέρσας γὰρ ἀναπείσας ἀπίστασθαι στρατηλάτεε ἐπὶ Μήδους· καὶ ἤν τε ἐγὼ ὑπὸ Ἀστυάγεος ἀποδεχθέω στρατηγὸς ἀντία σεῦ, ἔστι τοι τὰ σὺ βούλεαι, ἤν τε τῶν τις δοκίμων ἄλλος Μήδων· πρῶτοι γὰρ οὗτοι ἀποστάντες ἀπ’ ἐκείνου καὶ γενόμενοι πρὸς σέο Ἀστυάγεα καταιρέειν πειρήσονται. ὡς ὦν ἑτοίμου τοῦ γε ἐνθάδε ἐόντος, ποίεε ταῦτα καὶ ποίεε κατὰ τάχος.", "st": "1.124"}, {"sp": "N", "t": "ἀκούσας ταῦτα ὁ Κῦρος ἐφρόντιζε ὅτεῳ τρόπῳ σοφωτάτῳ Πέρσας ἀναπείσει ἀπίστασθαι, φροντίζων δὲ εὑρίσκεται ταῦτα καιριώτατα εἶναι· ἐποίεε δὴ ταῦτα. γράψας ἐς βυβλίον τὰ ἐβούλετο, ἁλίην τῶν Περσέων ἐποιήσατο, μετὰ δὲ ἀναπτύξας τὸ βυβλίον καὶ ἐπιλεγόμενος ἔφη Ἀστυάγεά μιν στρατηγὸν Περσέων ἀποδεικνύναι. νῦν τε, ἔφη λέγων, ὦ Πέρσαι, προαγορεύω ὑμῖν παρεῖναι ἕκαστον ἔχοντα δρέπανον. Κῦρος μὲν ταῦτα προηγόρευσε. ἔστι δὲ Πέρσεων συχνὰ γένεα, καὶ τὰ μὲν αὐτῶν ὁ Κῦρος συνάλισε καὶ ἀνέπεισε ἀπίστασθαι ἀπὸ Μήδων. ἔστι δὲ τάδε, ἐξ ὧν ὧλλοι πάντες ἀρτέαται Πέρσαι, Πασαργάδαι Μαράφιοι Μάσπιοι. τούτων Πασαργάδαι εἰσὶ ἄριστοι, ἐν τοῖσι καὶ Ἀχαιμενίδαι εἰσὶ φρήτρη, ἔνθεν οἱ βασιλέες οἱ Περσεῖδαι γεγόνασι. ἄλλοι δὲ Πέρσαι εἰσὶ οἵδε, Πανθιαλαῖοι Δηρουσιαῖοι Γερμάνιοι. οὗτοι μὲν πάντες ἀροτῆρες εἰσί, οἱ δὲ ἄλλοι νομάδες, Δάοι Μάρδοι Δροπικοὶ Σαγάρτιοι.", "st": "1.125"}, {"sp": "N", "t": "ὡς δὲ παρῆσαν ἅπαντες ἔχοντες τὸ προειρημένον, ἐνθαῦτα ὁ Κῦρος, ἦν γάρ τις χῶρος τῆς Περσικῆς ἀκανθώδης ὅσον τε ἐπὶ ὀκτωκαίδεκα σταδίους ἢ εἴκοσι πάντῃ, τοῦτον σφι τὸν χῶρον προεῖπε ἐξημερῶσαι ἐν ἡμέρῃ. ἐπιτελεσάντων δὲ τῶν Περσέων τὸν προκείμενον ἄεθλον, δεύτερα σφι προεῖπε ἐς τὴν ὑστεραίην παρεῖναι λελουμένους. ἐν δὲ τούτῳ τά τε αἰπόλια καὶ τὰς ποίμνας καὶ τὰ βουκόλια ὁ Κῦρος πάντα τοῦ πατρὸς συναλίσας ἐς τὠυτὸ ἔθυσε καὶ παρεσκεύαζε ὡς δεξόμενος τὸν Περσέων στρατόν, πρὸς δὲ οἴνῳ τε καὶ σιτίοισι ὡς ἐπιτηδεοτάτοισι. ἀπικομένους δὲ τῇ ὑστεραίῃ τοὺς Πέρσας κατακλίνας ἐς λειμῶνα εὐώχεε. ἐπείτε δὲ ἀπὸ δείπνου ἦσαν, εἴρετο σφέας ὁ Κῦρος κότερα τὰ τῇ προτεραίῃ εἶχον ἢ τὰ παρεόντα σφι εἴη αἱρετώτερα. οἳ δὲ ἔφασαν πολλὸν εἶναι αὐτῶν τὸ μέσον· τὴν μὲν γὰρ προτέρην ἡμέρην πάντα σφι κακὰ ἔχειν, τὴν δὲ τότε παρεοῦσαν πάντα ἀγαθά. παραλαβὼν δὲ τοῦτο τὸ ἔπος ὁ Κῦρος παρεγύμνου τὸν πάντα λόγον, λέγων ἄνδρες Πέρσαι, οὕτω ὑμῖν ἔχει. βουλομένοισι μὲν ἐμέο πείθεσθαί ἔστι τάδε τε καὶ ἄλλα μυρία ἀγαθά, οὐδένα πόνον δουλοπρεπέα ἔχουσι, μὴ βουλομένοισι δὲ ἐμέο πείθεσθαι εἰσὶ ὑμῖν πόνοι τῷ χθιζῷ παραπλήσιοι ἀναρίθμητοι. νῦν ὦν ἐμέο πειθόμενοι γίνεσθε ἐλεύθεροι. αὐτός τε γὰρ δοκέω θείῃ τύχῃ γεγονὼς τάδε ἐς χεῖρας ἄγεσθαι, καὶ ὑμέας ἥγημαι ἄνδρας Μήδων εἶναι οὐ φαυλοτέρους οὔτε τἄλλα οὔτε τὰ πολέμια. ὡς ὦν ἐχόντων ὧδε, ἀπίστασθε ἀπ’ Ἀστυάγεος τὴν ταχίστην.", "st": "1.126"}, {"sp": "N", "t": "πέρσαι μέν νυν προστάτεω ἐπιλαβόμενοι ἄσμενοι ἐλευθεροῦντο, καὶ πάλαι δεινὸν ποιεύμενοι ὑπὸ Μήδων ἄρχεσθαι. Ἀστυάγης δὲ ὡς ἐπύθετο Κῦρον ταῦτα πρήσσοντα, πέμψας ἄγγελον ἐκάλεε αὐτόν. ὁ δὲ Κῦρος ἐκέλευε τὸν ἄγγελον ἀπαγγέλλειν ὅτι πρότερον ἥξοι παρ’ ἐκεῖνον ἢ Ἀστυάγης αὐτὸς βουλήσεται. ἀκούσας δὲ ταῦτα ὁ Ἀστυάγης Μήδους τε ὥπλισε πάντας, καὶ στρατηγὸν αὐτῶν ὥστε θεοβλαβὴς ἐὼν Ἅρπαγον ἀπέδεξε, λήθην ποιεύμενος τά μιν ἐόργεε. ὡς δὲ οἱ Μῆδοι στρατευσάμενοι τοῖσι Πέρσῃσι συνέμισγον, οἳ μέν τινὲς αὐτῶν ἐμάχοντο, ὅσοι μὴ τοῦ λόγου μετέσχον, οἳ δὲ αὐτομόλεον πρὸς τοὺς Πέρσας, οἱ δὲ πλεῖστοι ἐθελοκάκεόν τε καὶ ἔφευγον.", "st": "1.127"}, {"sp": "N", "t": "διαλυθέντος δὲ τοῦ Μηδικοῦ στρατεύματος αἰσχρῶς, ὡς ἐπύθετο τάχιστα ὁ Ἀστυάγης, ἔφη ἀπειλέων τῷ Κύρῳ ἀλλ’ οὐδ’ ὣς Κῦρός γε χαιρήσει. τοσαῦτα εἶπας πρῶτον μὲν τῶν Μάγων τοὺς ὀνειροπόλους, οἵ μιν ἀνέγνωσαν μετεῖναι τὸν Κῦρον, τούτους ἀνεσκολόπισε, μετὰ δὲ ὥπλισε τοὺς ὑπολειφθέντας ἐν τῷ ἄστεϊ τῶν Μήδων, νέους τε καὶ πρεσβύτας ἄνδρας. ἐξαγαγὼν δὲ τούτους καὶ συμβαλὼν τοῖσι Πέρῃσι ἑσσώθη, καὶ αὐτός τε Ἀστυάγης ἐζωγρήθη καὶ τοὺς ἐξήγαγε τῶν Μήδων ἀπέβαλε.", "st": "1.128"}, {"sp": "N", "t": "ἐόντι δὲ αἰχμαλώτῳ τῷ Ἀστυάγεϊ προσστὰς ὁ Ἅρπαγος κατέχαιρέ τε καὶ κατεκερτόμεε, καὶ ἄλλα λέγων ἐς αὐτὸν θυμαλγέα ἔπεα, καὶ δὴ καὶ εἴρετό μιν πρὸς τὸ ἑωυτοῦ δεῖπνον, τὸ μιν ἐκεῖνος σαρξὶ τοῦ παιδὸς ἐθοίνησε, ὅ τι εἴη ἡ ἐκείνου δουλοσύνη ἀντὶ τῆς βασιληίης. ὁ δέ μιν προσιδὼν ἀντείρετο εἰ ἑωυτοῦ ποιέεται τὸ Κύρου ἔργον. Ἅρπαγος δὲ ἔφη, αὐτὸς γὰρ γράψαι, τὸ πρῆγμα ἑωυτοῦ δὴ δικαίως εἶναι. Ἀστυάγης δέ μιν ἀπέφαινε τῷ λόγῳ σκαιότατόν τε καὶ ἀδικώτατον ἐόντα πάντων ἀνθρώπων, σκαιότατον μέν γε, εἰ παρεὸν αὐτῷ βασιλέα γενέσθαι, εἰ δὴ δι’ ἑωυτοῦ γε ἐπρήχθη τὰ παρεόντα, ἄλλῳ περιέθηκε τὸ κράτος, ἀδικώτατον δέ, ὅτι τοῦ δείπνου εἵνεκεν Μήδους κατεδούλωσε. εἰ γὰρ δὴ δεῖν πάντως περιθεῖναι ἄλλῳ τεῷ τὴν βασιληίην καὶ μὴ αὐτὸν ἔχειν, δικαιότερον εἶναι Μήδων τεῷ περιβαλεῖν τοῦτο τὸ ἀγαθὸν ἢ Περσέων. νῦν δὲ Μήδους μὲν ἀναιτίους τούτου ἐόντας δούλους ἀντὶ δεσποτέων γεγονέναι, Πέρσας δὲ δούλους ἐόντας τὸ πρὶν Μήδων νῦν γεγονέναι δεσπότας.", "st": "1.129"}, {"sp": "N", "t": "Ἀστυάγης μέν νυν βασιλεύσας ἐπ’ ἔτεα πέντε καὶ τριήκοντα οὕτω τῆς βασιληίης κατεπαύσθη, Μῆδοι δὲ ὑπέκυψαν Πέρσῃσι διὰ τὴν τούτου πικρότητα, ἄρξαντες τῆς ἄνω Ἅλυος ποταμοῦ Ἀσίης ἐπ’ ἔτεα τριήκοντα καὶ ἑκατὸν δυῶν δέοντα, πάρεξ ἢ ὅσον οἱ Σκύθαι ἦρχον. ὑστέρῳ μέντοι χρόνῳ μετεμέλησέ τέ σφι ταῦτα ποιήσασι καὶ ἀπέστησαν ἀπὸ Δαρείου, ἀποστάντες δὲ ὀπίσω κατεστράφθησαν μάχῃ νικηθέντες. τότε δὲ ἐπὶ Ἀστυάγεος οἱ Πέρσαι τε καὶ ὁ Κῦρος ἐπαναστάντες τοῖσι Μήδοισι ἦρχον τὸ ἀπὸ τούτου τῆς Ἀσίης. Ἀστυάγεα δὲ Κῦρος κακὸν οὐδὲν ἄλλο ποιήσας εἶχε παρ’ ἑωυτῷ, ἐς ὃ ἐτελεύτησε. οὕτω δὴ Κῦρος γενόμενός τε καὶ τραφεὶς ἐβασίλευσε καὶ Κροῖσον ὕστερον τούτων ἄρξαντα ἀδικίης κατεστρέψατο, ὡς εἴρηταί μοι πρότερον, τοῦτον δὲ καταστρεψάμενος οὕτω πάσης τῆς Ἀσίης ἦρξε.", "st": "1.130"}, {"sp": "N", "t": "Πέρσας δὲ οἶδα νόμοισι τοιοῖσιδε χρεωμένους, ἀγάλματα μὲν καὶ νηοὺς καὶ βωμοὺς οὐκ ἐν νόμῳ ποιευμένους ἱδρύεσθαι, ἀλλὰ καὶ τοῖσι ποιεῦσι μωρίην ἐπιφέρουσι, ὡς μὲν ἐμοὶ δοκέειν, ὅτι οὐκ ἀνθρωποφυέας ἐνόμισαν τοὺς θεοὺς κατά περ οἱ Ἕλληνες εἶναι· οἳ δὲ νομίζουσι Διὶ μὲν ἐπὶ τὰ ὑψηλότατα τῶν ὀρέων ἀναβαίνοντες θυσίας ἔρδειν, τὸν κύκλον πάντα τοῦ οὐρανοῦ Δία καλέοντες· θύουσι δὲ ἡλίῳ τε καὶ σελήνῃ καὶ γῇ καὶ πυρὶ καὶ ὕδατι καὶ ἀνέμοισι. τούτοισι μὲν δὴ θύουσι μούνοισι ἀρχῆθεν, ἐπιμεμαθήκασι δὲ καὶ τῇ Οὐρανίῃ θύειν, παρά τε Ἀσσυρίων μαθόντες καὶ Ἀραβίων. καλέουσι δὲ Ἀσσύριοι τὴν Ἀφροδίτην Μύλιττα, Ἀράβιοι δὲ Ἀλιλάτ, Πέρσαι δὲ Μίτραν.", "st": "1.131"}, {"sp": "N", "t": "θυσίη δὲ τοῖσι Πέρσῃσι περὶ τοὺς εἰρημένους θεοὺς ἥδε κατέστηκε· οὔτε βωμοὺς ποιεῦνται οὔτε πῦρ ἀνακαίουσι μέλλοντες θύειν, οὐ σπονδῇ χρέωνται, οὐκὶ αὐλῷ, οὐ στέμμασι, οὐκὶ οὐλῇσι· τῶν δὲ ὡς ἑκάστῳ θύειν θέλῃ, ἐς χῶρον καθαρὸν ἀγαγὼν τὸ κτῆνος καλέει τὸν θεόν, ἐστεφανωμένος τὸν τιάραν μυρσίνῃ μάλιστα. ἑωυτῷ μὲν δὴ τῷ θύοντι ἰδίῃ μούνῳ οὔ οἱ ἐγγίνεται ἀρᾶσθαι ἀγαθά, ὁ δὲ τοῖσι πᾶσι Πέρσῃσι κατεύχεται εὖ γίνεσθαι καὶ τῷ βασιλέι· ἐν γὰρ δὴ τοῖσι ἅπασι Πέρσῃσι καὶ αὐτὸς γίνεται. ἐπεὰν δὲ διαμιστύλας κατὰ μέλεα τὸ ἱρήιον ἑψήσῃ τὰ κρέα ὑποπάσας ποίην ὡς ἁπαλωτάτην, μάλιστα δὲ τὸ τρίφυλλον, ἐπὶ ταύτης ἔθηκε ὦν πάντα τὰ κρέα. διαθέντος δὲ αὐτοῦ Μάγος ἀνὴρ παρεστεὼς ἐπαείδει θεογονίην, οἵην δὴ ἐκεῖνοι λέγουσι εἶναι τὴν ἐπαοιδήν· ἄνευ γὰρ δὴ Μάγου οὔ σφι νόμος ἐστὶ θυσίας ποιέεσθαι. ἐπισχὼν δὲ ὀλίγον χρόνον ἀποφέρεται ὁ θύσας τὰ κρέα καὶ χρᾶται ὅ τι μιν λόγος αἱρέει.", "st": "1.132"}, {"sp": "N", "t": "ἡμέρην δὲ ἁπασέων μάλιστα ἐκείνην τιμᾶν νομίζουσι τῇ ἕκαστος ἐγένετο. ἐν ταύτῃ δὲ πλέω δαῖτα τῶν ἀλλέων δικαιεῦσι προτίθεσθαι· ἐν τῇ οἱ εὐδαίμονες αὐτῶν βοῦν καὶ ἵππον καὶ κάμηλον καὶ ὄνον προτιθέαται ὅλους ὀπτοὺς ἐν καμίνοισι, οἱ δὲ πένητες αὐτῶν τὰ λεπτὰ τῶν προβάτων προτιθέαται. σίτοισι δὲ ὀλίγοισι χρέωνται, ἐπιφορήμασι δὲ πολλοῖσι καὶ οὐκ ἁλέσι· καὶ διὰ τοῦτο φασὶ Πέρσαι τοὺς Ἕλληνας σιτεομένους πεινῶντας παύεσθαι, ὅτι σφι ἀπὸ δείπνου παραφορέεται οὐδὲν λόγου ἄξιον· εἰ δέ τι παραφέροιτο, ἐσθίοντας ἂν οὐ παύεσθαι. οἴνῳ δὲ κάρτα προσκέαται, καί σφι οὐκ ἐμέσαι ἔξεστι, οὐκὶ οὐρῆσαι ἀντίον ἄλλου. ταῦτα μέν νυν οὕτω φυλάσσεται, μεθυσκόμενοι δὲ ἐώθασι βουλεύεσθαι τὰ σπουδαιέστατα τῶν πρηγμάτων· τὸ δ’ ἂν ἅδῃ σφι βουλευομένοισι, τοῦτο τῇ ὑστεραίῃ νήφουσι προτιθεῖ ὁ στέγαρχος, ἐν τοῦ ἂν ἐόντες βουλεύωνται, καὶ ἢν μὲν ἅδῃ καὶ νήφουσι, χρέωνται αὐτῷ, ἢν δὲ μὴ ἅδῃ, μετιεῖσι. τὰ δ’ ἂν νήφοντες προβουλεύσωνται, μεθυσκόμενοι ἐπιδιαγινώσκουσι.", "st": "1.133"}, {"sp": "N", "t": "ἐντυγχάνοντες δ’ ἀλλήλοισι ἐν τῇσι ὁδοῖσι, τῷδε ἄν τις διαγνοίη εἰ ὅμοιοί εἰσὶ οἱ συντυγχάνοντες· ἀντὶ γὰρ τοῦ προσαγορεύειν ἀλλήλους φιλέουσι τοῖσι στόμασι· ἢν δὲ ᾖ οὕτερος ὑποδεέστερος ὀλίγῳ, τὰς παρειὰς φιλέονται· ἢν δὲ πολλῷ ᾖ οὕτερος ἀγεννέστερος, προσπίπτων προσκυνέει τὸν ἕτερον. τιμῶσι δὲ ἐκ πάντων τοὺς ἄγχιστα ἑωυτῶν οἰκέοντας μετά γε ἑωυτούς, δευτέρα δὲ τοὺς δευτέρους· μετὰ δὲ κατὰ λόγον προβαίνοντες τιμῶσι· ἥκιστα δὲ τοὺς ἑωυτῶν ἑκαστάτω οἰκημένους ἐν τιμῇ ἄγονται, νομίζοντες ἑωυτοὺς εἶναι ἀνθρώπων μακρῷ τὰ πάντα ἀρίστους, τοὺς δὲ ἄλλους κατὰ λόγον τῆς ἀρετῆς ἀντέχεσθαι, τοὺς δὲ ἑκαστάτω οἰκέοντας ἀπὸ ἑωυτῶν κακίστους εἶναι. ἐπὶ δὲ Μήδων ἀρχὸν τῶν καὶ ἦρχε τὰ ἔθνεα ἀλλήλων, συναπάντων μὲν Μῆδοι καὶ τῶν ἄγχιστα οἰκεόντων σφίσι, οὗτοι δὲ καὶ τῶν ὁμούρων, οἳ δὲ μάλα τῶν ἐχομένων, κατὰ τὸν αὐτὸν δὴ λόγον καὶ οἱ Πέρσαι τιμῶσι· προέβαινε γὰρ δὴ τὸ ἔθνος ἄρχον τε καὶ ἐπιτροπεῦον.", "st": "1.134"}, {"sp": "N", "t": "ξεινικὰ δὲ νόμαια Πέρσαι προσίενται ἀνδρῶν μάλιστα. καὶ γὰρ δὴ τὴν Μηδικὴν ἐσθῆτα νομίσαντες τῆς ἑωυτῶν εἶναι καλλίω φορέουσι, καὶ ἐς τοὺς πολέμους τοὺς Αἰγυπτίους θώρηκας· καὶ εὐπαθείας τε παντοδαπὰς πυνθανόμενοι ἐπιτηδεύουσι, καὶ δὴ καὶ ἀπ’ Ἑλλήνων μαθόντες παισὶ μίσγονται. γαμέουσι δὲ ἕκαστος αὐτῶν πολλὰς μὲν κουριδίας γυναῖκας, πολλῷ δ’ ἔτι πλεῦνας παλλακὰς κτῶνται.", "st": "1.135"}, {"sp": "N", "t": "ἀνδραγαθίη δὲ αὕτη ἀποδέδεκται, μετὰ τὸ μάχεσθαι εἶναι ἀγαθόν, ὃς ἂν πολλοὺς ἀποδέξῃ παῖδας· τῷ δὲ τοὺς πλείστους ἀποδεικνύντι δῶρα ἐκπέμπει βασιλεὺς ἀνὰ πᾶν ἔτος. τὸ πολλὸν δ’ ἡγέαται ἰσχυρὸν εἶναι. παιδεύουσι δὲ τοὺς παῖδας ἀπὸ πενταέτεος ἀρξάμενοι μέχρι εἰκοσαέτεος τρία μοῦνα, ἰππεύειν καὶ τοξεύειν καὶ ἀληθίζεσθαι. πρὶν δὲ ἢ πενταέτης γένηται, οὐκ ἀπικνέεται ἐς ὄψιν τῷ πατρί, ἀλλὰ παρὰ τῇσι γυναιξὶ δίαιταν ἔχει. τοῦδε δὲ εἵνεκα τοῦτο οὕτω ποιέεται, ἵνα ἢν ἀποθάνῃ τρεφόμενος, μηδεμίαν ἄσην τῷ πατρὶ προσβάλῃ.", "st": "1.136"}, {"sp": "N", "t": "αἰνέω μέν νυν τόνδε τὸν νόμον, αἰνέω δὲ καὶ τόνδε, τὸ μὴ μιῆς αἰτίης εἵνεκα μήτε αὐτὸν τὸν βασιλέα μηδένα φονεύειν, μήτε τῶν ἄλλων Περσέων μηδένα τῶν ἑωυτοῦ οἰκετέων ἐπὶ μιῇ αἰτίῃ ἀνήκεστον πάθος ἔρδειν· ἀλλὰ λογισάμενος ἢν εὑρίσκῃ πλέω τε καὶ μέζω τὰ ἀδικήματα ἐόντα τῶν ὑπουργημάτων, οὕτω τῷ θυμῷ χρᾶται. ἀποκτεῖναι δὲ οὐδένα κω λέγουσι τὸν ἑωυτοῦ πατέρα οὐδὲ μητέρα, ἀλλὰ ὁκόσα ἤδη τοιαῦτα ἐγένετο, πᾶσαν ἀνάγκην φασὶ ἀναζητεόμενα ταῦτα ἀνευρεθῆναι ἤτοι ὑποβολιμαῖα ἐόντα ἢ μοιχίδια· οὐ γὰρ δή φασι οἰκὸς εἶναι τόν γε ἀληθέως τοκέα ὑπὸ τοῦ ἑωυτοῦ παιδὸς ἀποθνήσκειν.", "st": "1.137"}, {"sp": "N", "t": "ἅσσα δέ σφι ποιέειν οὐκ ἔξεστι, ταῦτα οὐδὲ λέγειν ἔξεστι. αἴσχιστον δὲ αὐτοῖσι τὸ ψεύδεσθαι νενόμισται, δεύτερα δὲ τὸ ὀφείλειν χρέος, πολλῶν μὲν καὶ ἄλλων εἵνεκα, μάλιστα δὲ ἀναγκαίην φασὶ εἶναι τὸν ὀφείλοντα καί τι ψεῦδος λέγειν. ὃς ἂν δὲ τῶν ἀστῶν λέπρην ἢ λεύκην ἔχῃ, ἐς πόλιν οὗτος οὐ κατέρχεται οὐδὲ συμμίσγεται τοῖσι ἄλλοισι Πέρσῃσι· φασὶ δέ μιν ἐς τὸν ἥλιον ἁμαρτόντα τι ταῦτα ἔχειν. ξεῖνον δὲ πάντα τὸν λαμβανόμενον ὑπὸ τουτέων πολλοὶ ἐξελαύνουσι ἐκ τῆς χώρης, καὶ τὰς λευκὰς περιστεράς, τὴν αὐτὴν αἰτίην ἐπιφέροντες. ἐς ποταμὸν δὲ οὔτε ἐνουρέουσι οὔτε ἐμπτύουσι, οὐ χεῖρας ἐναπονίζονται, οὐδὲ ἄλλον οὐδένα περιορῶσι, ἀλλὰ σέβονται ποταμοὺς μάλιστα.", "st": "1.138"}, {"sp": "N", "t": "καὶ τόδε ἄλλο σφι ὧδε συμπέπτωκε γίνεσθαι, τὸ Πέρσας μὲν αὐτοὺς λέληθε, ἡμέας μέντοι οὔ· τὰ οὐνόματά σφι ἐόντα ὅμοια τοῖσι σώμασι καὶ τῇ μεγαλοπρεπείῃ τελευτῶσι πάντα ἐς τὠυτὸ γράμμα, τὸ Δωριέες μὲν σὰν καλέουσι, Ἴωνες δὲ σίγμα· ἐς τοῦτο διζήμενος εὑρήσεις τελευτῶντα τῶν Περσέων τὰ οὐνόματα, οὐ τὰ μὲν τὰ δ’ οὔ, ἀλλὰ πάντα ὁμοίως.", "st": "1.139"}, {"sp": "N", "t": "ταῦτα μὲν ἀτρεκέως ἔχω περὶ αὐτῶν εἰδὼς εἰπεῖν· τάδε μέντοι ὡς κρυπτόμενα λέγεται καὶ οὐ σαφηνέως περὶ τοῦ ἀποθανόντος, ὡς οὐ πρότερον θάπτεται ἀνδρὸς Πέρσεω ὁ νέκυς πρὶν ἂν ὑπ’ ὄρνιθος ἢ κυνὸς ἑλκυσθῇ. Μάγους μὲν γὰρ ἀτρεκέως οἶδα ταῦτα ποιέοντας· ἐμφανέως γὰρ δὴ ποιεῦσι. κατακηρώσαντες δὲ ὦν τὸν νέκυν Πέρσαι γῇ κρύπτουσι. Μάγοι δὲ κεχωρίδαται πολλὸν τῶν τε ἄλλων ἀνθρώπων καὶ τῶν ἐν Αἰγύπτῳ ἱρέων. οἳ μὲν γὰρ ἁγνεύουσι ἔμψυχον μηδὲν κτείνειν, εἰ μὴ ὅσα θύουσι· οἱ δὲ δὴ Μάγοι αὐτοχειρίῃ πάντα πλὴν κυνὸς καὶ ἀνθρώπου κτείνουσι, καὶ ἀγώνισμα μέγα τοῦτο ποιεῦνται, κτείνοντες ὁμοίως μύρμηκάς τε καὶ ὄφις καὶ τἆλλα ἑρπετὰ καὶ πετεινά. καὶ ἀμφὶ μὲν τῷ νόμῳ τούτῳ ἐχέτω ὡς καὶ ἀρχὴν ἐνομίσθη, ἄνειμι δὲ ἐπὶ τὸν πρότερον λόγον.", "st": "1.140"}, {"sp": "N", "t": "Ἴωνες δὲ καὶ Αἰολέες, ὡς οἱ Λυδοὶ τάχιστα κατεστράφατο ὑπὸ Περσέων, ἔπεμπον ἀγγέλους ἐς Σάρδις παρὰ Κῦρον, ἐθέλοντες ἐπὶ τοῖσι αὐτοῖσι εἶναι τοῖσι καὶ Κροίσῳ ἦσαν κατήκοοι. ὁ δὲ ἀκούσας αὐτῶν τὰ προΐσχοντο ἔλεξέ σφι λόγον, ἄνδρα φὰς αὐλητὴν ἰδόντα ἰχθῦς ἐν τῇ θαλάσσῃ αὐλέειν, δοκέοντα σφέας ἐξελεύσεσθαι ἐς γῆν· ὡς δὲ ψευσθῆναι τῆς ἐλπίδος, λαβεῖν ἀμφίβληστρον καὶ περιβαλεῖν τε πλῆθος πολλὸν τῶν ἰχθύων καὶ ἐξειρύσαι, ἰδόντα δὲ παλλομένους εἰπεῖν ἄρα αὐτὸν πρὸς τοὺς ἰχθῦς παύεσθέ μοι ὀρχεόμενοι, ἐπεὶ οὐδ’ ἐμέο αὐλέοντος ἠθέλετε ἐκβαίνειν ὀρχεόμενοι. Κῦρος μὲν τοῦτον τὸν λόγον τοῖσι Ἴωσι καὶ τοῖσι Αἰολεῦσι τῶνδε εἵνεκα ἔλεξε, ὅτι δὴ οἱ Ἴωνες πρότερον αὐτοῦ Κύρου δεηθέντος δι’ ἀγγέλων ἀπίστασθαι σφέας ἀπὸ Κροίσου οὐκ ἐπείθοντο, τότε δὲ κατεργασμένων τῶν πρηγμάτων ἦσαν ἕτοιμοι πείθεσθαι Κύρῳ. ὃ μὲν δὴ ὀργῇ ἐχόμενος ἔλεγέ σφι τάδε· Ἴωνες δὲ ὡς ἤκουσαν τούτων ἀνενειχθέντων ἐς τὰς πόλιας, τείχεά τε περιεβάλοντο ἕκαστοι καὶ συνελέγοντο ἐς Πανιώνιον οἱ ἄλλοι, πλὴν Μιλησίων· πρὸς μούνους γὰρ τούτους ὅρκιον Κῦρος ἐποιήσατο ἐπ’ οἷσί περ ὁ Λυδός. τοῖσι δὲ λοιποῖσι Ἴωσι ἔδοξε κοινῷ λόγῳ πέμπειν ἀγγέλους ἐς Σπάρτην δεησομένους Ἴωσι τιμωρέειν.", "st": "1.141"}, {"sp": "N", "t": "οἱ δὲ Ἴωνες οὗτοι, τῶν καὶ τὸ Πανιώνιον ἐστί, τοῦ μὲν οὐρανοῦ καὶ τῶν ὡρέων ἐν τῷ καλλίστῳ ἐτύγχανον ἱδρυσάμενοι πόλιας πάντων ἀνθρώπων τῶν ἡμεῖς ἴδμεν· οὔτε γὰρ τὰ ἄνω αὐτῆς χωρία τὠυτὸ ποιέει τῇ Ἰωνίῃ οὔτε τὰ κάτω οὔτε τὰ πρὸς τὴν ἠῶ οὔτε τὰ πρὸς τὴν ἑσπέρην, τὰ μὲν ὑπὸ τοῦ ψυχροῦ τε καὶ ὑγροῦ πιεζόμενα, τὰ δὲ ὑπὸ τοῦ θερμοῦ τε καὶ αὐχμώδεος. γλῶσσαν δὲ οὐ τὴν αὐτὴν οὗτοι νενομίκασι, ἀλλὰ τρόπους τέσσερας παραγωγέων. Μίλητος μὲν αὐτέων πρώτη κέεται πόλις πρὸς μεσαμβρίην, μετὰ δὲ Μυοῦς τε καὶ Πριήνη. αὗται μὲν ἐν τῇ Καρίῃ κατοίκηνται κατὰ ταὐτὰ διαλεγόμεναι σφίσι, αἵδε δὲ ἐν τῇ Λυδίῃ, Ἔφεσος Κολοφὼν Λέβεδος Τέως Κλαζομεναὶ Φώκαια· αὗται δὲ αἱ πόλιες τῇσι πρότερον λεχθείσῃσι ὁμολογέουσι κατὰ γλῶσσαν οὐδέν, σφισι δὲ ὁμοφωνέουσι. ἔτι δὲ τρεῖς ὑπόλοιποι Ἰάδες πόλιες, τῶν αἱ δύο μὲν νήσους οἰκέαται, Σάμον τε καὶ Χίον, ἡ δὲ μία ἐν τῇ ἠπείρῳ ἵδρυται, Ἐρυθραί. Χῖοι μέν νυν καὶ Ἐρυθραῖοι κατὰ τὠυτὸ διαλέγονται, Σάμιοι δὲ ἐπ’ ἑωυτῶν μοῦνοι. οὗτοι χαρακτῆρες γλώσσης τέσσερες γίνονται.", "st": "1.142"}, {"sp": "N", "t": "τούτων δὴ ὦν τῶν Ἰώνων οἱ Μιλήσιοι μὲν ἦσαν ἐν σκέπῃ τοῦ φόβου, ὅρκιον ποιησάμενοι, τοῖσι δὲ αὐτῶν νησιώτῃσι ἦν δεινὸν οὐδέν· οὔτε γὰρ Φοίνικες ἦσαν κω Περσέων κατήκοοι οὔτε αὐτοὶ οἱ Πέρσαι ναυβάται. ἀπεσχίσθησαν δὲ ἀπὸ τῶν ἄλλων Ἰώνων οὗτοι κατ’ ἄλλο μὲν οὐδέν, ἀσθενέος δὲ ἐόντος τοῦ παντὸς τότε Ἑλληνικοῦ γένεος, πολλῷ δὴ ἦν ἀσθενέστατον τῶν ἐθνέων τὸ Ἰωνικὸν καὶ λόγου ἐλαχίστου· ὅτι γὰρ μὴ Ἀθῆναι, ἦν οὐδὲν ἄλλο πόλισμα λόγιμον. οἱ μέν νυν ἄλλοι Ἴωνες καὶ οἱ Ἀθηναῖοι ἔφυγον τὸ οὔνομα, οὐ βουλόμενοι Ἴωνες κεκλῆσθαι, ἀλλὰ καὶ νῦν φαίνονταί μοι οἱ πολλοὶ αὐτῶν ἐπαισχύνεσθαι τῷ οὐνόματι· αἱ δὲ δυώδεκα πόλιες αὗται τῷ τε οὐνόματι ἠγάλλοντο καὶ ἱρὸν ἱδρύσαντο ἐπὶ σφέων αὐτέων, τῷ οὔνομα ἔθεντο Πανιώνιον, ἐβουλεύσαντο δὲ αὐτοῦ μεταδοῦναι μηδαμοῖσι ἄλλοισι Ἰώνων (οὐδ’ ἐδεήθησαν δὲ οὐδαμοὶ μετασχεῖν ὅτι μὴ Σμυρναῖοι)·", "st": "1.143"}, {"sp": "N", "t": "κατά περ οἱ ἐκ τῆς πενταπόλιος νῦν χώρης Δωριέες, πρότερον δὲ ἑξαπόλιος τῆς αὐτῆς ταύτης καλεομένης, φυλάσσονται ὦν μηδαμοὺς ἐσδέξασθαι τῶν προσοίκων Δωριέων ἐς τὸ Τριοπικὸν ἱρόν, ἀλλὰ καὶ σφέων αὐτῶν τοὺς περὶ τὸ ἱρόν ἀνομήσαντας ἐξεκλήισαν τῆς μετοχῆς, ἐν γὰρ τῷ ἀγῶνι τοῦ Τριοπίου Ἀπόλλωνος ἐτίθεσαν τὸ πάλαι τρίποδας χαλκέους τοῖσι νικῶσι, καὶ τούτους χρῆν τοὺς λαμβάνοντας ἐκ τοῦ ἱροῦ μὴ ἐκφέρειν ἀλλ’ αὐτοῦ ἀνατιθέναι τῷ θεῷ. ἀνὴρ ὦν Ἁλικαρνησσεύς, τῷ οὔνομα ἦν Ἀγασικλέης, νικήσας τὸν νόμον κατηλόγησε, φέρων δὲ πρὸς τὰ ἑωυτοῦ οἰκία προσεπασσάλευσε τὸν τρίποδα. διὰ ταύτην τὴν αἰτίην αἱ πέντε πόλιες, Λίνδος καὶ Ἰήλυσός τε καὶ Κάμειρος καὶ Κῶς τε καὶ Κνίδος ἐξεκλήισαν τῆς μετοχῆς τὴν ἕκτην πόλιν Ἁλικαρνησσόν. τούτοισι μέν νυν οὗτοι ταύτην τὴν ζημίην ἐπέθηκαν.", "st": "1.144"}, {"sp": "N", "t": "δυώδεκα δὲ μοι δοκέουσι πόλιας ποιήσασθαι οἱ Ἴωνες καὶ οὐκ ἐθελῆσαι πλεῦνας ἐσδέξασθαι τοῦδε εἵνεκα, ὅτι καὶ ὅτε ἐν Πελοποννήσῳ οἴκεον, δυώδεκα ἦν αὐτῶν μέρεα, κατά περ νῦν Ἀχαιῶν τῶν ἐξελασάντων Ἴωνας δυώδεκα ἐστὶ μέρεα, Πελλήνη μέν γε πρώτη πρὸς Σικυῶνος, μετὰ δὲ Αἴγειρα καὶ Αἰγαί, ἐν τῇ Κρᾶθις ποταμὸς ἀείναος ἐστί, ἀπ’ ὅτευ ὁ ἐν Ἰταλίῃ ποταμὸς τὸ οὔνομα ἔσχε, καὶ Βοῦρα καὶ Ἑλίκη, ἐς τὴν κατέφυγον Ἴωνες ὑπὸ Ἀχαιῶν μάχῃ ἑσσωθέντες, καὶ Αἴγιον καὶ Ῥύπες καὶ Πατρέες καὶ Φαρέες καὶ Ὤλενος, ἐν τῷ Πεῖρος ποταμὸς μέγας ἐστί, καὶ Δύμη καὶ Τριταιέες, οἳ μοῦνοι τούτων μεσόγαιοι οἰκέουσι. ταῦτα δυώδεκα μέρεα νῦν Ἀχαιῶν ἐστὶ καὶ τότε γε Ἰώνων ἦν.", "st": "1.145"}, {"sp": "N", "t": "τούτων δὴ εἵνεκα καὶ οἱ Ἴωνες δυώδεκα πόλιας ἐποιήσαντο· ἐπεὶ ὥς γέ τι μᾶλλον οὗτοι Ἴωνες εἰσὶ τῶν ἄλλων Ἰώνων ἢ κάλλιόν τι γεγόνασι, μωρίη πολλὴ λέγειν· τῶν Ἄβαντες μὲν ἐξ Εὐβοίες εἰσὶ οὐκ ἐλαχίστη μοῖρα, τοῖσι Ἰωνίης μέτα οὐδὲ τοῦ οὐνόματος οὐδέν, Μινύαι δὲ Ὀρχομένιοί σφι ἀναμεμίχαται καὶ Καδμεῖοι καὶ Δρύοπες καὶ Φωκέες ἀποδάσμιοι καὶ Μολοσσοὶ καὶ Ἀρκάδες Πελασγοὶ καὶ Δωριέες Ἐπιδαύριοι, ἄλλα τε ἔθνεα πολλὰ ἀναμεμίχαται· οἱ δὲ αὐτῶν ἀπὸ τοῦ πρυτανηίου τοῦ Ἀθηναίων ὁρμηθέντες καὶ νομίζοντες γενναιότατοι εἶναι Ἰώνων, οὗτοι δὲ οὐ γυναῖκας ἠγάγοντο ἐς τὴν ἀποικίην ἀλλὰ Καείρας ἔσχον, τῶν ἐφόνευσαν τοὺς γονέας. διὰ τοῦτον δὲ τὸν φόνον αἱ γυναῖκες αὗται νόμον θέμεναι σφίσι αὐτῇσι ὅρκους ἐπήλασαν καὶ παρέδοσαν τῇσι θυγατράσι, μή κοτε ὁμοσιτῆσαι τοῖσι ἀνδράσι μηδὲ οὐνόματι βῶσαι τὸν ἑωυτῆς ἄνδρα, τοῦδε εἵνεκα ὅτι ἐφόνευσαν σφέων τοὺς πατέρας καὶ ἄνδρας καὶ παῖδας καὶ ἔπειτα ταῦτα ποιήσαντες αὐτῇσι συνοίκεον.", "st": "1.146"}, {"sp": "N", "t": "ταῦτα δὲ ἦν γινόμενα ἐν Μιλήτῳ. βασιλέας δὲ ἐστήσαντο οἳ μὲν αὐτῶν Λυκίους ἀπὸ Γλαύκου τοῦ Ἱππολόχου γεγονότας, οἳ δὲ Καύκωνας Πυλίους ἀπὸ Κόδρου τοῦ Μελάνθου, οἳ δὲ καὶ συναμφοτέρους. ἀλλὰ γὰρ περιέχονται τοῦ οὐνόματος μᾶλλόν τι τῶν ἄλλων Ἰώνων, ἔστωσαν δὴ καὶ οἱ καθαρῶς γεγονότες Ἴωνες. εἰσὶ δὲ πάντες Ἴωνες ὅσοι ἀπ’ Ἀθηνέων γεγόνασι καὶ Ἀπατούρια ἄγουσι ὁρτήν. ἄγουσι δὲ πάντες πλὴν Ἐφεσίων καὶ Κολοφωνίων· οὗτοι γὰρ μοῦνοι Ἰώνων οὐκ ἄγουσι Ἀπατούρια, καὶ οὗτοι κατὰ φόνου τινὰ σκῆψιν.", "st": "1.147"}, {"sp": "N", "t": "τὸ δὲ Πανιώνιον ἐστὶ τῆς Μυκάλης χῶρος ἱρὸς πρὸς ἄρκτον τετραμμένος, κοινῇ ἐξαραιρημένος ὑπὸ Ἰώνων Ποσειδέωνι Ἑλικωνίῳ.", "st": "1.148"}, {"sp": "N", "t": "ἡ δὲ Μυκάλη ἐστὶ τῆς ἠπείρου ἄκρη πρὸς ζέφυρον ἄνεμον κατήκουσα Σάμῳ καταντίον, ἐς τὴν συλλεγόμενοι ἀπὸ τῶν πολίων Ἴωνες ἄγεσκον ὁρτὴν τῇ ἔθεντο οὔνομα Πανιώνια. [πεπόνθασι δὲ οὔτι μοῦναι αἱ Ἰώνων ὁρταὶ τοῦτο, ἀλλὰ καὶ Ἑλλήνων πάντων ὁμοίως πᾶσαι ἐς τὠυτὸ γράμμα τελευτῶσι, κατά περ τῶν Περσέων τὰ οὐνόματα.]", "st": "1.148b"}, {"sp": "N", "t": "αὗται μὲν αἱ Ἰάδες πόλιες εἰσί, αἵδε δὲ αἱ Αἰολίδες, Κύμη ἡ Φρικωνὶς καλεομένη, Λήρισαι, Νέον τεῖχος, Τῆμνος, Κίλλα, Νότιον, Αἰγιρόεσσα, Πιτάνη, Αἰγαῖαι, Μύρινα, Γρύνεια. αὗται ἕνδεκα Αἰολέων πόλιες αἱ ἀρχαῖαι· μία γὰρ σφέων παρελύθη Σμύρνη ὑπὸ Ἰώνων· ἦσαν γὰρ καὶ αὗται δυώδεκα αἱ ἐν τῇ ἠπείρῳ. οὗτοι δὲ οἱ Αἰολέες χώρην μὲν ἔτυχον κτίσαντες ἀμείνω Ἰώνων, ὡρέων δὲ ἥκουσαν οὐκ ὁμοίως.", "st": "1.149"}, {"sp": "N", "t": "σμύρνην δὲ ὧδε ἀπέβαλον Αἰολέες. Κολοφωνίους ἄνδρας στάσι ἑσσωθέντας καὶ ἐκπεσόντας ἐκ τῆς πατρίδος ὑπεδέξαντο. μετὰ δὲ οἱ φυγάδες τῶν Κολοφωνίων φυλάξαντες τοὺς Σμυρναίους ὁρτὴν ἔξω τείχεος ποιευμένους Διονύσῳ, τὰς πύλας ἀποκληίσαντες ἔσχον τὴν πόλιν. βοηθησάντων δὲ πάντων Αἰολέων, ὁμολογίῃ ἐχρήσαντο τὰ ἔπιπλα ἀποδόντων τῶν Ἰώνων ἐκλιπεῖν Σμύρνην Αἰολέας. ποιησάντων δὲ ταῦτα Σμυρναίων ἐπιδιείλοντο σφέας αἱ ἕνδεκα πόλιες καὶ ἐποιήσαντο σφέων αὐτέων πολιήτας.", "st": "1.150"}, {"sp": "N", "t": "αὗται μέν νυν αἱ ἠπειρώτιδες Αἰολίδες πόλιες, ἔξω τῶν ἐν τῇ Ἴδῃ οἰκημενέων· κεχωρίδαται γὰρ αὗται. αἱ δὲ τὰς νήσους ἔχουσαι πέντε μὲν πόλιες τὴν Λέσβον νέμονται (τὴν γὰρ ἕκτην ἐν τῇ Λέσβῳ οἰκημένην Ἀρίσβαν ἠνδραπόδισαν Μηθυμναῖοι ἐόντας ὁμαίμους), ἐν Τενέδῳ δὲ μία οἴκηται πόλις, καὶ ἐν τῇσι Ἑκατὸν νήσοισι καλεομένῃσι ἄλλη μία. Λεσβίοισι μέν νῦν καὶ Τενεδίοισι, κατά περ Ἰώνων τοῖσι τὰς νήσους ἔχουσι, ἦν δεινὸν οὐδέν· τῇσι δὲ λοιπῇσι πόλισι ἕαδε κοινῇ Ἴωσι ἕπεσθαι τῇ ἂν οὗτοι ἐξηγέωνται.", "st": "1.151"}, {"sp": "N", "t": "ὡς δὲ ἀπίκοντο ἐς τὴν Σπάρτην τῶν Ἰώνων καὶ Αἰολέων οἱ ἄγγελοι (κατὰ γὰρ δὴ τάχος ἦν ταῦτα πρησσόμενα), εἵλοντο πρὸ πάντων λέγειν τὸν Φωκαέα, τῷ οὔνομα ἦν Πύθερμος. ὁ δὲ πορφύρεόν τε εἷμα περιβαλόμενος, ὡς ἂν πυνθανόμενοι πλεῖστοι συνέλθοιεν Σπαρτιητέων, καὶ καταστὰς ἔλεγε πολλὰ τιμωρέειν ἑωυτοῖσι χρηίζων. Λακεδαιμόνιοι δὲ οὔ κως ἐσήκουον, ἀλλ’ ἀπέδοξέ σφι μὴ τιμωρέειν Ἴωσι. οἳ μὲν δὴ ἀπαλλάσσοντο, Λακεδαιμόνιοι δὲ ἀπωσάμενοι τῶν Ἰώνων τοὺς ἀγγέλους ὅμως ἀπέστειλαν πεντηκοντέρῳ ἄνδρας, ὡς μὲν ἐμοὶ δοκέει, κατασκόπους τῶν τε Κύρου πρηγμάτων καὶ Ἰωνίης. ἀπικόμενοι δὲ οὗτοι ἐς Φώκαιαν ἔπεμπον ἐς Σάρδις σφέων αὐτῶν τὸν δοκιμώτατον, τῷ οὔνομα ἦν Λακρίνης, ἀπερέοντα Κύρῳ Λακεδαιμονίων ῥῆσιν, γῆς τῆς Ἑλλάδος μηδεμίαν πόλιν σιναμωρέειν, ὡς αὐτῶν οὐ περιοψομένων.", "st": "1.152"}, {"sp": "N", "t": "ταῦτα εἰπόντος τοῦ κήρυκος, λέγεται Κῦρον ἐπειρέσθαι τοὺς παρεόντας οἱ Ἑλλήνων τίνες ἐόντες ἄνθρωποι Λακεδαιμόνιοι καὶ κόσοι πλῆθος ταῦτα ἑωυτῷ προαγορεύουσι· πυνθανόμενον δέ μιν εἰπεῖν πρὸς τὸν κήρυκα τὸν Σπαρτιήτην· οὐκ ἔδεισά κω ἄνδρας τοιούτους, τοῖσι ἐστι χῶρος ἐν μέσῃ ἑωυτῷ προαγορεύουσι· τῇ πόλι ἀποδεδεγμένος ἐς τὸν συλλεγόμενοι ἀλλήλους ὀμνύντες ἐξαπατῶσι· τοῖσι, ἢν ἐγὼ ὑγιαίνω, οὐ τὰ Ἰώνων πάθεα ἔσται ἔλλεσχα ἀλλὰ τὰ οἰκήια. ταῦτα ἐς τοὺς πάντας Ἕλληνας ἀπέρριψε ὁ Κῦρος τὰ ἔπεα, ὅτι ἀγορὰς στησάμενοι ὠνῇ τε καὶ πρήσι χρέωνται· αὐτοὶ γὰρ οἱ Πέρσαι ἀγορῇσι οὐδὲν ἐώθασι χρᾶσθαι, οὐδέ σφι ἐστὶ τὸ παράπαν ἀγορή. μετὰ ταῦτα ἐπιτρέψας τὰς μὲν Σάρδις Ταβάλῳ ἀνδρὶ Πέρσῃ, τὸν δὲ χρυσὸν τόν τε Κροίσου καὶ τὸν τῶν ἄλλων Λυδῶν Πακτύῃ ἀνδρὶ Λυδῷ κομίζειν, ἀπήλαυνε αὐτὸς ἐς Ἀγβάτανα, Κροῖσόν τε ἅμα ἀγόμενος καὶ τοὺς Ἴωνας ἐν οὐδενὶ λόγῳ ποιησάμενος τὴν πρώτην εἶναι. ἡ τε γὰρ Βαβυλών οἱ ἦν ἐμπόδιος καὶ τὸ Βάκτριον ἔθνος καὶ Σάκαι τε καὶ Αἰγύπτιοι, ἐπ’ οὓς ἐπεῖχέ τε στρατηλατέειν αὐτός, ἐπὶ δὲ Ἴωνας ἄλλον πέμπειν στρατηγόν.", "st": "1.153"}, {"sp": "N", "t": "ὡς δὲ ἀπήλασε ὁ Κῦρος ἐκ τῶν Σαρδίων, τοὺς Λυδοὺς ἀπέστησε ὁ Πακτύης ἀπό τε Ταβάλου καὶ Κύρου, καταβὰς δὲ ἐπὶ θάλασσαν, ἅτε τὸν χρυσὸν ἔχων πάντα τὸν ἐκ τῶν Σαρδίων, ἐπικούρους τε ἐμισθοῦτο καὶ τοὺς ἐπιθαλασσίους ἀνθρώπους ἔπειθε σὺν ἑωυτῷ στρατεύεσθαι. ἐλάσας δὲ ἐπὶ τὰς Σάρδις ἐπολιόρκεε Τάβαλον ἀπεργμένον ἐν τῇ ἀκροπόλι.", "st": "1.154"}, {"sp": "N", "t": "πυθόμενος δὲ κατ’ ὁδὸν ταῦτα ὁ Κῦρος εἶπε πρὸς Κροῖσον τάδε. Κροῖσε, τί ἔσται τέλος τῶν γινομένων τούτων ἐμοί; οὐ παύσονται Λυδοί, ὡς οἴκασι, πρήγματα παρέχοντες καὶ αὐτοὶ ἔχοντες. φροντίζω μὴ ἄριστον ᾖ ἐξανδραποδίσασθαι σφέας. ὁμοίως γὰρ μοι νῦν γε φαίνομαι πεποιηκέναι ὡς εἴ τις πατέρα ἀποκτείνας τῶν παίδων αὐτοῦ φείσατο· ὡς δὲ καὶ ἐγὼ Λυδῶν τὸν μὲν πλέον τι ἢ πατέρα ἐόντα σὲ λαβὼν ἄγω, αὐτοῖσι δὲ Λυδοῖσι τὴν πόλιν παρέδωκα, καὶ ἔπειτα θωμάζω εἰ μοι ἀπεστᾶσι. ὃ μὲν δὴ τά περ ἐνόεε ἔλεγε, ὃ δ’ ἀμείβετο τοῖσιδε, δείσας μὴ ἀναστάτους ποιήσῃ τὰς Σάρδις. ὦ βασιλεῦ, τὰ μὲν οἰκότα εἴρηκας, σὺ μέντοι μὴ πάντα θυμῷ χρέο, μηδὲ πόλιν ἀρχαίην ἐξαναστήσῃς ἀναμάρτητον ἐοῦσαν καὶ τῶν πρότερον καὶ τῶν νῦν ἑστεώτων. τὰ μὲν γὰρ πρότερον ἐγώ τε ἔπρηξα καὶ ἐγὼ κεφαλῇ ἀναμάξας φέρω· τὰ δὲ νῦν παρεόντα Πακτύης γὰρ ἐστὶ ὁ ἀδικέων, τῷ σὺ ἐπέτρεψας Σάρδις, οὗτος δότω τοι δίκην. Λυδοῖσι δὲ συγγνώμην ἔχων τάδε αὐτοῖσι ἐπίταξον, ὡς μήτε ἀποστέωσι μήτε δεινοί τοι ἔωσι· ἄπειπε μέν σφι πέμψας ὅπλα ἀρήια μὴ ἐκτῆσθαι, κέλευε δὲ σφέας κιθῶνάς τε ὑποδύνειν τοῖσι εἵμασι καὶ κοθόρνους ὑποδέεσθαι, πρόειπε δ’ αὐτοῖσι κιθαρίζειν τε καὶ ψάλλειν καὶ καπηλεύειν παιδεύειν τοὺς παῖδας. καὶ ταχέως σφέας ὦ βασιλεῦ γυναῖκας ἀντ’ ἀνδρῶν ὄψεαι γεγονότας, ὥστε οὐδὲν δεινοί τοι ἔσονται μὴ ἀποστέωσι.", "st": "1.155"}, {"sp": "N", "t": "Κροῖσος μὲν δὴ ταῦτά οἱ ὑπετίθετο, αἱρετώτερα ταῦτα εὑρίσκων Λυδοῖσι ἢ ἀνδραποδισθέντας πρηθῆναι σφέας, ἐπιστάμενος ὅτι ἢν μὴ ἀξιόχρεον πρόφασιν προτείνῃ, οὐκ ἀναπείσει μιν μεταβουλεύσασθαι, ἀρρωδέων δὲ μὴ καὶ ὕστερον κοτὲ οἱ Λυδοί, ἢν τὸ παρεὸν ὑπεκδράμωσι, ἀποστάντες ἀπὸ τῶν Περσέων ἀπόλωνται. Κῦρος δὲ ἡσθεὶς τῇ ὑποθήκῃ καὶ ὑπεὶς τῆς ὀργῆς ἔφη οἱ πείθεσθαι. καλέσας δὲ Μαζάρεα ἄνδρα Μῆδον, ταῦτά τέ οἱ ἐνετείλατο προειπεῖν Λυδοῖσι τὰ ὁ Κροῖσος ὑπετίθετο, καὶ πρὸς ἐξανδραποδίσασθαι τοὺς ἄλλους πάντας οἳ μετὰ Λυδῶν ἐπὶ Σάρδις ἐστρατεύσαντο, αὐτὸν δὲ Πακτύην πάντως ζῶντα ἀγαγεῖν παρ’ ἑωυτόν.", "st": "1.156"}, {"sp": "N", "t": "ὃ μὲν δὴ ταῦτα ἐκ τῆς ὁδοῦ ἐντειλάμενος ἀπήλαυνε ἐς ἤθεα τὰ Περσέων, Πακτύης δὲ πυθόμενος ἀγχοῦ εἶναι στρατὸν ἐπ’ ἑωυτὸν ἰόντα δείσας οἴχετο φεύγων ἐς Κύμην. Μαζάρης δὲ ὁ Μῆδος ἐλάσας ἐπὶ τὰς Σάρδις τοῦ Κύρου στρατοῦ μοῖραν ὅσην δή κοτε ἔχων, ὡς οὐκ εὗρε ἔτι ἐόντας τοὺς ἀμφὶ Πακτύην ἐν Σάρδισι, πρῶτα μὲν τοὺς Λυδοὺς ἠνάγκασε τὰς Κύρου ἐντολὰς ἐπιτελέειν, ἐκ τούτου δὲ κελευσμοσύνης Λυδοὶ τὴν πᾶσαν δίαιταν τῆς ζόης μετέβαλον. Μαζάρης δὲ μετὰ τοῦτο ἔπεμπε ἐς τὴν Κύμην ἀγγέλους ἐκδιδόναι κελεύων Πακτύην. οἱ δὲ Κυμαῖοι ἔγνωσαν συμβουλῆς πέρι ἐς θεὸν ἀνοῖσαι τὸν ἐν Βραγχίδῃσι· ἦν γὰρ αὐτόθι μαντήιον ἐκ παλαιοῦ ἱδρυμένον, τῷ Ἴωνές τε πάντες καὶ Αἰολέες ἐώθεσαν χρᾶσθαι. ὁ δὲ χῶρος οὗτος ἐστὶ τῆς Μιλησίης ὑπὲρ Πανόρμου λιμένος.", "st": "1.157"}, {"sp": "N", "t": "πέμψαντες ὦν οἱ Κυμαῖοι ἐς τοὺς Βραγχίδας θεοπρόπους εἰρώτευν περὶ Πακτύην ὁκοῖόν τι ποιέοντες θεοῖσι μέλλοιεν χαριεῖσθαι. ἐπειρωτῶσι δέ σφι ταῦτα χρηστήριον ἐγένετο ἐκδιδόναι Πακτύην Πέρσῃσι. ταῦτα δὲ ὡς ἀπενειχθέντα ἤκουσαν οἱ Κυμαῖοι, ὁρμέατο ἐκδιδόναι· ὁρμημένου δὲ ταύτῃ τοῦ πλήθεος, Ἀριστόδικος ὁ Ἡρακλείδεω ἀνὴρ τῶν ἀστῶν ἐὼν δόκιμος ἔσχε μὴ ποιῆσαι ταῦτα Κυμαίους, ἀπιστέων τε τῷ χρησμῷ καὶ δοκέων τοὺς θεοπρόπους οὐ λέγειν ἀληθέως, ἐς ὃ τὸ δεύτερον περὶ Πακτύεω ἐπειρησόμενοι ἤισαν ἄλλοι θεοπρόποι, τῶν καὶ Ἀριστόδικος ἦν.", "st": "1.158"}, {"sp": "N", "t": "ἀπικομένων δὲ ἐς Βραγχίδας ἐχρηστηριάζετο ἐκ πάντων Ἀριστόδικος ἐπειρωτῶν τάδε. ὦναξ, ἦλθε παρ’ ἡμέας ἱκέτης Πακτύης ὁ Λυδός, φεύγων θάνατον βίαιον πρὸς Περσέων· οἳ δέ μιν ἐξαιτέονται, προεῖναι Κυμαίους κελεύοντες. ἡμεῖς δὲ δειμαίνοντες τὴν Περσέων δύναμιν τὸν ἱκέτην ἐς τόδε οὐ τετολμήκαμεν ἐκδιδόναι, πρὶν ἂν τὸ ἀπὸ σεῦ ἡμῖν δηλωθῇ ἀτρεκέως ὁκότερα ποιέωμεν. ὃ μὲν ταῦτα ἐπειρώτα, ὃ δ’ αὖτις τὸν αὐτόν σφι χρησμὸν ἔφαινε, κελεύων ἐκδιδόναι Πακτύην Πέρσῃσι. πρὸς ταῦτα ὁ Ἀριστόδικος ἐκ προνοίης ἐποίεε τάδε· περιιὼν τὸν νηὸν κύκλῳ ἐξαίρεε τοὺς στρουθοὺς καὶ ἄλλα ὅσα ἦν νενοσσευμένα ὀρνίθων γένεα ἐν τῷ νηῷ. ποιέοντος δὲ αὐτοῦ ταῦτα λέγεται φωνὴν ἐκ τοῦ ἀδύτου γενέσθαι φέρουσαν μὲν πρὸς τὸν Ἀριστόδικον, λέγουσαν δὲ τάδε ἀνοσιώτατε ἀνθρώπων, τί τάδε τολμᾷς ποιέειν; τοὺς ἱκέτας μου ἐκ τοῦ νηοῦ κεραΐζεις; Ἀριστόδικον δὲ οὐκ ἀπορήσαντα πρὸς ταῦτα εἰπεῖν ὦναξ, αὐτὸς μὲν οὕτω τοῖσι ἱκέτῃσι βοηθέεις, Κυμαίους δὲ κελεύεις τὸν ἱκέτην ἐκδιδόναι; τὸν δὲ αὖτις ἀμείψασθαι τοῖσιδε ναὶ κελεύω, ἵνα γε ἀσεβήσαντες θᾶσσον ἀπόλησθε, ὡς μὴ τὸ λοιπὸν περὶ ἱκετέων ἐκδόσιος ἔλθητε ἐπὶ τὸ χρηστήριον.", "st": "1.159"}, {"sp": "N", "t": "ταῦτα ὡς ἀπενειχθέντα ἤκουσαν οἱ Κυμαῖοι, οὐ βουλόμενοι οὔτε ἐκδόντες ἀπολέσθαι οὔτε παρ’ ἑωυτοῖσι ἔχοντες πολιορκέεσθαι, ἐκπέμπουσι αὐτὸν ἐς Μυτιλήνην. οἱ δὲ Μυτιληναῖοι ἐπιπέμποντος τοῦ Μαζάρεος ἀγγελίας ἐκδιδόναι τὸν Πακτύην παρεσκευάζοντο ἐπὶ μισθῷ ὅσῳ δή· οὐ γὰρ ἔχω τοῦτό γε εἰπεῖν ἀτρεκέως· οὐ γὰρ ἐτελεώθη. Κυμαῖοι γὰρ ὡς ἔμαθον ταῦτα πρησσόμενα ἐκ τῶν Μυτιληναίων, πέμψαντες πλοῖον ἐς Λέσβον ἐκκομίζουσι Πακτύην ἐς Χίον. ἐνθεῦτεν δὲ ἐξ ἱροῦ Ἀθηναίης πολιούχου ἀποσπασθεὶς ὑπὸ Χίων ἐξεδόθη· ἐξέδοσαν δὲ οἱ Χῖοι ἐπὶ τῷ Ἀταρνέι μισθῷ· τοῦ δὲ Ἀταρνέος τούτου ἐστὶ χῶρος τῆς Μυσίης, Λέσβου ἀντίος. Πακτύην μέν νυν παραδεξάμενοι οἱ Πέρσαι εἶχον ἐν φυλακῇ, θέλοντες Κύρῳ ἀποδέξαι. ἦν δὲ χρόνος οὗτος οὐκ ὀλίγος γινόμενος, ὅτε Χίων οὐδεὶς ἐκ τοῦ Ἀταρνέος τούτου οὔτε οὐλὰς κριθέων πρόχυσιν ἐποιέετο θεῶν οὐδενὶ οὔτε πέμματα ἐπέσσετο καρποῦ τοῦ ἐνθεῦτεν, ἀπείχετο τε τῶν πάντων ἱρῶν τὰ πάντα ἐκ τῆς χώρης ταύτης γινόμενα.", "st": "1.160"}, {"sp": "N", "t": "Χῖοι μέν νυν Πακτύην ἐξέδοσαν. Μαζάρης δὲ μετὰ ταῦτα ἐστρατεύετο ἐπὶ τοὺς συμπολιορκήσαντας Τάβαλον, καὶ τοῦτο μὲν Πριηνέας ἐξηνδραποδίσατο, τοῦτο δὲ Μαιάνδρου πεδίον πᾶν ἐπέδραμε ληίην ποιεύμενος τῷ στρατῷ, Μαγνησίην τε ὡσαύτως. μετὰ δὲ ταῦτα αὐτίκα νούσῳ τελευτᾷ.", "st": "1.161"}, {"sp": "N", "t": "ἀποθανόντος δὲ τούτου, Ἅρπαγος κατέβη διάδοχος τῆς στρατηγίης, γένος καὶ αὐτὸς ἐὼν Μῆδος, τὸν ὁ Μήδων βασιλεὺς Ἀστυάγης ἀνόμῳ τραπέζῃ ἔδαισε, ὁ τῷ Κύρῳ τὴν βασιληίην συγκατεργασάμενος. οὗτος ὡνὴρ τότε ὑπὸ Κύρου στρατηγὸς ἀποδεχθεὶς ὡς ἀπίκετο ἐς τὴν Ἰωνίην, αἵρεε τὰς πόλιας χώμασι· ὅκως γὰρ τειχήρεας ποιήσειε, τὸ ἐνθεῦτεν χώματα χῶν πρὸς τὰ τείχεα ἐπόρθεε.", "st": "1.162"}, {"sp": "N", "t": "πρώτῃ δὲ Φωκαίῃ Ἰωνίης ἐπεχείρησε. οἱ δὲ Φωκαιέες οὗτοι ναυτιλίῃσι μακρῇσι πρῶτοι Ἑλλήνων ἐχρήσαντο, καὶ τὸν τε Ἀδρίην καὶ τὴν Τυρσηνίην καὶ τὴν Ἰβηρίην καὶ τὸν Ταρτησσὸν οὗτοι εἰσὶ οἱ καταδέξαντες· ἐναυτίλλοντο δὲ οὐ στρογγύλῃσι νηυσὶ ἀλλὰ πεντηκοντέροισι. ἀπικόμενοι δὲ ἐς τὸν Ταρτησσὸν προσφιλέες ἐγένοντο τῷ βασιλέι τῶν Ταρτησσίων, τῷ οὔνομα μὲν ἦν, Ἀργανθώνιος, ἐτυράννευσε δὲ Ταρτησσοῦ ὀγδώκοντα ἔτεα, ἐβίωσε δὲ πάντα εἴκοσι καὶ ἑκατόν. τούτῳ δὴ τῷ ἀνδρὶ προσφιλέες οἱ Φωκαιέες οὕτω δή τι ἐγένοντο ὡς τὰ μὲν πρῶτα σφέας ἐκλιπόντας Ἰωνίην ἐκέλευε τῆς ἑωυτοῦ χώρης οἰκῆσαι ὅκου βούλονται· μετὰ δέ, ὡς τοῦτό γε οὐκ ἔπειθε τοὺς Φωκαιέας, ὁ δὲ πυθόμενος τὸν Μῆδον παρ’ αὐτῶν ὡς αὔξοιτο, ἐδίδου σφι χρήματα τεῖχος περιβαλέσθαι τὴν πόλιν, ἐδίδου δὲ ἀφειδέως· καὶ γὰρ καὶ ἡ περίοδος τοῦ τείχεος οὐκ ὀλίγοι στάδιοι εἰσί, τοῦτο δὲ πᾶν λίθων μεγάλων καὶ εὖ συναρμοσμένων.", "st": "1.163"}, {"sp": "N", "t": "τὸ μὲν δὴ τεῖχος τοῖσι Φωκαιεῦσι τρόπῳ τοιῷδε ἐξεποιήθη. ὁ δὲ Ἅρπαγος ὡς ἐπήλασε τὴν στρατιήν, ἐπολιόρκεε αὐτούς, προισχόμενος ἔπεα ὥς οἱ καταχρᾷ εἰ βούλονται Φωκαιέες προμαχεῶνα ἕνα μοῦνον τοῦ τείχεος ἐρεῖψαι καὶ οἴκημα ἓν κατιρῶσαι. οἱ δὲ Φωκαιέες περιημεκτέοντες τῇ δουλοσύνη ἔφασαν θέλειν βουλεύσασθαι ἡμέρην μίαν καὶ ἔπειτα ὑποκρινέεσθαι· ἐν ᾧ δὲ βουλεύονται αὐτοί, ἀπαγαγεῖν ἐκεῖνον ἐκέλευον τὴν στρατιὴν ἀπὸ τοῦ τείχεος. ὁ δ’ Ἅρπαγος ἔφη εἰδέναι μὲν εὖ τὰ ἐκεῖνοι μέλλοιεν ποιέειν, ὅμως δὲ σφι παριέναι βουλεύσασθαι. ἐν ᾧ ὦν ὁ Ἅρπαγος ἀπὸ τοῦ τείχεος ἀπήγαγε τὴν στρατιήν, οἱ Φωκαιέες ἐν τούτῳ κατασπάσαντες τὰς πεντηκοντέρους, ἐσθέμενοι τέκνα καὶ γυναῖκας καὶ ἔπιπλα πάντα, πρὸς δὲ καὶ τὰ ἀγάλματα τὰ ἐν τῶν ἱρῶν καὶ τὰ ἄλλα ἀναθήματα, χωρὶς ὅ τι χαλκὸς ἢ λίθος ἢ γραφὴ ἦν, τὰ δὲ ἄλλα πάντα ἐσθέντες καὶ αὐτοὶ εἰσβάντες ἔπλεον ἐπὶ Χίου. τὴν δὲ Φωκαίην ἐρημωθεῖσαν ἀνδρῶν ἔσχον οἱ Πέρσαι.", "st": "1.164"}, {"sp": "N", "t": "οἱ δὲ Φωκαιέες, ἐπείτε σφι Χῖοι τὰς νήσους τὰς Οἰνούσσας καλεομένας οὐκ ἐβούλοντο ὠνευμένοισι πωλέειν, δειμαίνοντες μὴ αἳ μὲν ἐμπόριον γένωνται, ἡ δὲ αὐτῶν νῆσος ἀποκληισθῇ τούτου εἵνεκα, πρὸς ταῦτα οἱ Φωκαίες ἐστέλλοντο ἐς Κύρνον· ἐν γὰρ τῇ Κύρνῳ εἴκοσι ἔτεσι πρότερον τούτων ἐκ θεοπροπίου ἀνεστήσαντο πόλιν, τῇ οὔνομα ἦν Ἀλαλίη. Ἀργανθώνιος δὲ τηνικαῦτα ἤδη τετελευτήκεε. στελλόμενοι δὲ ἐπὶ τὴν Κύρνον, πρῶτα καταπλεύσαντες ἐς τὴν Φωκαίην κατεφόνευσαν τῶν Περσέων τὴν φυλακήν, ἣ ἐφρούρεε παραδεξαμένη παρὰ Ἁρπάγου τὴν πόλιν. μετὰ δέ, ὡς τοῦτο σφι ἐξέργαστο, ἐποιήσαντο ἰσχυρὰς κατάρας τῷ ὑπολειπομένῳ ἑωυτῶν τοῦ στόλου, πρὸς δὲ ταύτῃσι καὶ μύδρον σιδήρεον κατεπόντωσαν καὶ ὤμοσαν μὴ πρὶν ἐς Φωκαίην ἥξειν πρὶν ἢ τὸν μύδρον τοῦτον ἀναφανῆναι. στελλομένων δὲ αὐτῶν ἐπὶ τὴν Κύρνον, ὑπερημίσεας τῶν ἀστῶν ἔλαβε πόθος τε καὶ οἶκτος τῆς πόλιος καὶ τῶν ἠθέων τῆς χώρης, ψευδόρκιοι δὲ γενόμενοι ἀπέπλεον ὀπίσω ἐς τὴν Φωκαίην. οἳ δὲ αὐτῶν τὸ ὅρκιον ἐφύλασσον, ἀερθέντες ἐκ τῶν Οἰνουσσέων ἔπλεον.", "st": "1.165"}, {"sp": "N", "t": "ἐπείτε δὲ ἐς τὴν Κύρνον ἀπίκοντο, οἴκεον κοινῇ μετὰ τῶν πρότερον ἀπικομένων ἐπ’ ἔτεα πέντε, καὶ ἱρὰ ἐνιδρύσαντο. καὶ ἦγον γὰρ δὴ καὶ ἔφερον τοὺς περιοίκους ἅπαντας, στρατεύονται ὦν ἐπ’ αὐτοὺς κοινῷ λόγῳ χρησάμενοι Τυρσηνοὶ καὶ Καρχηδόνιοι, νηυσὶ ἑκάτεροι ἑξήκοντα. οἱ δὲ Φωκαιέες πληρώσαντες καὶ αὐτοὶ τὰ πλοῖα, ἐόντα ἀριθμὸν ἑξήκοντα, ἀντίαζον ἐς τὸ Σαρδόνιον καλεόμενον πέλαγος. συμμισγόντων δὲ τῇ ναυμαχίῃ Καδμείη τις νίκη τοῖσι Φωκαιεῦσι ἐγένετο· αἱ μὲν γὰρ τεσσεράκοντά σφι νέες διεφθάρησαν, αἱ δὲ εἴκοσι αἱ περιεοῦσαι ἦσαν ἄχρηστοι· ἀπεστράφατο γὰρ τοὺς ἐμβόλους. καταπλώσαντες δὲ ἐς τὴν Ἀλαλίην ἀνέλαβον τὰ τέκνα καὶ τὰς γυναῖκας καὶ τὴν ἄλλην κτῆσιν ὅσην οἷαι τε ἐγίνοντο αἱ νέες σφι ἄγειν, καὶ ἔπειτα ἀπέντες τὴν Κύρνον ἔπλεον ἐς Ῥήγιον.", "st": "1.166"}, {"sp": "N", "t": "τῶν δὲ διαφθαρεισέων νεῶν τοὺς ἄνδρας οἱ τε Καρχηδόνιοι καὶ οἱ Τυρσηνοὶ [διέλαχον, τῶν δὲ Τυρσηνῶν οἱ Ἀγυλλαῖοι] ἔλαχόν τε αὐτῶν πολλῷ πλείστους καὶ τούτους ἐξαγαγόντες κατέλευσαν. μετὰ δὲ Ἀγυλλαίοισι πάντα τὰ παριόντα τὸν χῶρον, ἐν τῶ οἱ Φωκαιέες καταλευσθέντες ἐκέατο, ἐγίνετο διάστροφα καὶ ἔμπηρα καὶ ἀπόπληκτα, ὁμοίως πρόβατα καὶ ὑποζύγια καὶ ἄνθρωποι. οἱ δὲ Ἀγυλλαῖοι ἐς Δελφοὺς ἔπεμπον βουλόμενοι ἀκέσασθαι τὴν ἁμαρτάδα. ἡ δὲ Πυθίη σφέας ἐκέλευσε ποιέειν τὰ καὶ νῦν οἱ Ἀγυλλαῖοι ἔτι ἐπιτελέουσι· καὶ γὰρ ἐναγίζουσί σφι μεγάλως καὶ ἀγῶνα γυμνικὸν καὶ ἱππικὸν ἐπιστᾶσι. καὶ οὗτοι μὲν τῶν Φωκαιέων τοιούτῳ μόρῳ διεχρήσαντο, οἱ δὲ αὐτῶν ἐς τὸ Ῥήγιον καταφυγόντες ἐνθεῦτεν ὁρμώμενοι ἐκτήσαντο πόλιν γῆς τῆς Οἰνωτρίης ταύτην ἥτις νῦν Ὑέλη καλέεται· ἔκτισαν δὲ ταύτην πρὸς ἀνδρὸς Ποσειδωνιήτεω μαθόντες ὡς τὸν Κύρνον σφι ἡ Πυθίη ἔχρησε κτίσαι ἥρων ἐόντα, ἀλλ’ οὐ τὴν νῆσον.", "st": "1.167"}, {"sp": "N", "t": "Φωκαίης μέν νυν πέρι τῆς ἐν Ἰωνίῃ οὕτω ἔσχε παραπλήσια δὲ τούτοισι καὶ Τήιοι ἐποίησαν. ἐπείτε γὰρ σφέων εἷλε χώματι τὸ τεῖχος Ἅρπαγος, ἐσβάντες πάντες ἐς τὰ πλοῖα οἴχοντο πλέοντες ἐπὶ τῆς Θρηίκης, καὶ ἐνθαῦτα ἔκτισαν πόλιν Ἄβδηρα, τὴν πρότερος τούτων Κλαζομένιος Τιμήσιος κτίσας οὐκ ἀπόνητο, ἀλλ’ ὑπὸ Θρηίκων ἐξελασθεὶς τιμὰς νῦν ὑπὸ Τηίων τῶν ἐν Ἀβδήροισι ὡς ἥρως ἔχει.", "st": "1.168"}, {"sp": "N", "t": "οὗτοι μέν νυν Ἰώνων μοῦνοι τὴν δουλοσύνην οὐκ ἀνεχόμενοι ἐξέλιπον τὰς πατρίδας· οἱ δ’ ἄλλοι Ἴωνες πλὴν Μιλησίων διὰ μάχης μὲν ἀπίκοντο Ἁρπάγῳ κατά περ οἱ ἐκλιπόντες, καὶ ἄνδρες ἐγένοντο ἀγαθοὶ περὶ τῆς ἑωυτοῦ ἕκαστος μαχόμενοι, ἑσσωθέντες δὲ καὶ ἁλόντες ἔμενον κατὰ χώρην ἕκαστοι καὶ τὰ ἐπιτασσόμενα ἐπετέλεον. Μιλήσιοι δέ, ὡς καὶ πρότερόν μοι ἔρηται, αὐτῷ Κύρῳ ὅρκιον ποιησάμενοι ἡσυχίην ἦγον. οὕτω δὴ τὸ δεύτερον Ἰωνίη ἐδεδούλωτο. ὡς δὲ τοὺς ἐν τῇ ἠπείρῳ Ἴωνας ἐχειρώσατο Ἅρπαγος, οἱ τὰς νήσους ἔχοντες Ἴωνες καταρρωδήσαντες ταῦτα σφέας αὐτοὺς ἔδοσαν Κύρῳ.", "st": "1.169"}, {"sp": "N", "t": "κεκακωμένων δὲ Ἰώνων καὶ συλλεγομένων οὐδὲν ἧσσον ἐς τὸ Πανιώνιον, πυνθάνομαι γνώμην Βίαντα ἄνδρα Πριηνέα ἀποδέξασθαι Ἴωσι χρησιμωτάτην, τῇ εἰ ἐπείθοντο, παρεῖχε ἂν σφι εὐδαιμονέειν Ἑλλήνων μάλιστα· ὃς ἐκέλευε κοινῷ στόλῳ Ἴωνας ἀερθέντας πλέειν ἐς Σαρδὼ καὶ ἔπειτα πόλιν μίαν κτίζειν πάντων Ἰώνων, καὶ οὕτω ἀπαλλαχθέντας σφέας δουλοσύνης εὐδαιμονήσειν, νήσων τε ἁπασέων μεγίστην νεμομένους καὶ ἄρχοντας ἄλλων· μένουσι δέ σφι ἐν τῇ Ἰωνίῃ οὐκ ἔφη ἐνορᾶν ἐλευθερίην ἔτι ἐσομένην. αὕτη μὲν Βίαντος τοῦ Πριηνέος γνώμη ἐπὶ διεφθαρμένοισι Ἴωσι γενομένη, χρηστὴ δὲ καὶ πρὶν ἢ διαφθαρῆναι Ἰωνίην Θάλεω ἀνδρὸς Μιλησίου ἐγένετο, τὸ ἀνέκαθεν γένος ἐόντος Φοίνικος, ὃς ἐκέλευε ἓν βουλευτήριον Ἴωνας ἐκτῆσθαι, τὸ δὲ εἶναι ἐν Τέῳ (Τέων γὰρ μέσον εἶναι Ἰωνίης), τὰς δὲ ἄλλας πόλιας οἰκεομένας μηδὲν ἧσσον νομίζεσθαι κατά περ ἐς δῆμοι εἶεν·", "st": "1.170"}, {"sp": "N", "t": "οὗτοι μὲν δή σφι γνώμας τοιάσδε ἀπεδέξαντο.", "st": "1.170b"}, {"sp": "N", "t": "Ἅρπαγος δὲ καταστρεψάμενος Ἰωνίην ἐποιέετο στρατηίην ἐπὶ Κᾶρας καὶ Καυνίους καὶ Λυκίους, ἅμα ἀγόμενος καὶ Ἴωνας καὶ Αἰολέας. εἰσὶ δὲ τούτων Κᾶρες μὲν ἀπιγμένοι ἐς τὴν ἤπειρον ἐκ τῶν νήσων. τὸ γὰρ παλαιὸν ἐόντες Μίνω κατήκοοι καὶ καλεόμενοι Λέλεγες εἶχον τὰς νήσους, φόρον μὲν οὐδένα ὑποτελέοντες, ὅσον καὶ ἐγὼ δυνατός εἰμι ἐπὶ μακρότατον ἐξικέσθαι ἀκοῇ· οἳ δέ, ὅκως Μίνως δέοιτο, ἐπλήρουν οἱ τὰς νέας. ἅτε δὴ Μίνω τε κατεστραμμένου γῆν πολλὴν καὶ εὐτυχέοντος τῷ πολέμῳ, τὸ Καρικὸν ἦν ἔθνος λογιμώτατον τῶν ἐθνέων ἁπάντων κατὰ τοῦτον ἅμα τὸν χρόνον μακρῷ μάλιστα. καί σφι τριξὰ ἐξευρήματα ἐγένετο, τοῖσι οἱ Ἕλληνες ἐχρήσαντο· καὶ γὰρ ἐπὶ τὰ κράνεα λόφους ἐπιδέεσθαι Κᾶρες εἰσὶ οἱ καταδέξαντες καὶ ἐπὶ τὰς ἀσπίδας τὰ σημήια ποιέεσθαι, καὶ ὄχανα ἀσπίσι οὗτοι εἰσὶ οἱ ποιησάμενοι πρῶτοι· τέως δὲ ἄνευ ὀχάνων ἐφόρεον τὰς ἀσπίδας πάντες οἳ περ ἐώθεσαν ἀσπίσι χρᾶσθαι, τελαμῶσι σκυτίνοισι οἰηκίζοντες, περὶ τοῖσι αὐχέσι τε καὶ τοῖσι ἀριστεροῖσι ὤμοισι περικείμενοι. μετὰ δὲ τοὺς Κᾶρας χρόνῳ ὕστερον πολλῷ Δωριέες τε καὶ Ἴωνες ἐξανέστησαν ἐκ τῶν νήσων, καὶ οὕτω ἐς τὴν ἤπειρον ἀπίκοντο. κατὰ μὲν δὴ Κᾶρας οὕτω Κρῆτες λέγουσι γενέσθαι· οὐ μέντοι αὐτοί γε ὁμολογέουσι τούτοισι οἱ Κᾶρες, ἀλλὰ νομίζουσι αὐτοὶ ἑωυτοὺς εἶναι αὐτόχθονας ἠπειρώτας, καὶ τῷ οὐνόματι τῷ αὐτῷ αἰεὶ διαχρεωμένους τῷ περ νῦν. ἀποδεικνῦσι δὲ ἐν Μυλάσοισι Διὸς Καρίου ἱρὸν ἀρχαῖον, τοῦ Μυσοῖσι μὲν καὶ Λυδοῖσι μέτεστι ὡς κασιγνήτοισι ἐοῦσι τοῖσι Καρσί· τὸν γὰρ Λυδὸν καὶ τὸν Μυσὸν λέγουσι εἶναι Καρὸς ἀδελφεούς. τούτοισι μὲν δὴ μέτεστι, ὅσοι δὲ ἐόντες ἄλλου ἔθνεος ὁμόγλωσσοι τοῖσι Καρσὶ ἐγένοντο, τούτοισι δὲ οὐ μέτα.", "st": "1.171"}, {"sp": "N", "t": "οἱ δὲ Καύνιοι αὐτόχθονες δοκέειν ἐμοὶ εἰσί, αὐτοὶ μέντοι ἐκ Κρήτης φασὶ εἶναι. προσκεχωρήκασι δὲ γλῶσσαν μὲν πρὸς τὸ Καρικὸν ἔθνος, ἢ οἱ Κᾶρες πρὸς τὸ Καυνικόν (τοῦτο γὰρ οὐκ ἔχω ἀτρεκέως διακρῖναι), νόμοισι δὲ χρέωνται κεχωρισμένοισι πολλὸν τῶν τε ἄλλων ἀνθρώπων καὶ Καρῶν. τοῖσι γὰρ κάλλιστον ἐστὶ κατ’ ἡλικίην τε καὶ φιλότητα εἰλαδὸν συγγίνεσθαι ἐς πόσιν, καὶ ἀνδράσι καὶ γυναιξὶ καὶ παισί. ἱδρυθέντων δέ σφι ἱρῶν ξεινικῶν, μετέπειτα ὥς σφι ἀπέδοξε, ἔδοξέ δὲ τοῖσι πατρίοισι μοῦνον χέασθαι θεοῖσι, ἐνδύντες τὰ ὅπλα ἅπαντες Καύνιοι ἡβηδόν, τύπτοντες δόρασι τὸν ἠέρα, μέχρι οὔρων τῶν Καλυνδικῶν εἵποντο, καὶ ἔφασαν ἐκβάλλειν τοὺς ξεινικοὺς θεούς.", "st": "1.172"}, {"sp": "N", "t": "καὶ οὗτοι μὲν τρόποισι τοιούτοισι χρέωνται, οἱ δὲ Λύκιοι ἐκ Κρήτης τὠρχαῖον γεγόνασι (τὴν γὰρ Κρήτην εἶχον τὸ παλαιὸν πᾶσαν βάρβαροι)· διενειχθέντων δὲ ἐν Κρήτῃ περὶ τῆς βασιληίης τῶν Εὐρώπης παίδων Σαρπηδόνος τε καὶ Μίνω, ὡς ἐπεκράτησε τῇ στάσι Μίνως, ἐξήλασε αὐτόν τε Σαρπηδόνα καὶ τοὺς στασιώτας αὐτοῦ, οἳ δὲ ἀπωσθέντες ἀπίκοντο τῆς Ἀσίης ἐς γῆν τὴν Μιλυάδα· τὴν γὰρ νῦν Λύκιοι νέμονται, αὕτη τὸ παλαιὸν ἦν Μιλυάς, οἱ δὲ Μιλύαι τότε Σόλυμοι ἐκαλέοντο. ἕως μὲν δὴ αὐτῶν Σαρπηδὼν ἦρχε, οἳ δὲ ἐκαλέοντο τό πέρ τε ἠνείκαντο οὔνομα καὶ νυν ἔτι καλέονται ὑπὸ τῶν περιοίκων οἱ Λύκιοι Τερμίλαι· ὡς δὲ ἐξ Ἀθηνέων Λύκος ὁ Πανδίονος, ἐξελασθεὶς καὶ οὗτος ὑπὸ τοῦ ἀδελφεοῦ Αἰγέος, ἀπίκετο ἐς τοὺς Τερμίλας παρὰ Σαρπηδόνα, οὕτω δὴ κατὰ τοῦ Λύκου τὴν ἐπωνυμίην Λύκιοι ἀνὰ χρόνον ἐκλήθησαν. νόμοισι δὲ τὰ μὲν Κρητικοῖσι τὰ δὲ Καρικοῖσι χρέωνται. ἓν δὲ τόδε ἴδιον νενομίκασι καὶ οὐδαμοῖσι ἄλλοισι συμφέρονται ἀνθρώπων· καλέουσι ἀπὸ τῶν μητέρων ἑωυτοὺς καὶ οὐκὶ ἀπὸ τῶν πατέρων· εἰρομένου δὲ ἑτέρου τὸν πλησίον τίς εἴη, καταλέξει ἑωυτὸν μητρόθεν καὶ τῆς μητρὸς ἀνανεμέεται τὰς μητέρας. καὶ ἢν μέν γε γυνὴ ἀστὴ δούλῳ συνοικήσῃ, γενναῖα τὰ τέκνα νενόμισται· ἢν δὲ ἀνὴρ ἀστὸς καὶ ὁ πρῶτος αὐτῶν γυναῖκα ξείνην ἢ παλλακὴν ἔχῃ, ἄτιμα τὰ τέκνα γίνεται.", "st": "1.173"}, {"sp": "N", "t": "οἱ μέν νυν Κᾶρες οὐδὲν λαμπρὸν ἔργον ἀποδεξάμενοι ἐδουλώθησαν ὑπὸ Ἁρπάγου, οὔτε αὐτοὶ οἱ Κᾶρες ἀποδεξάμενοι οὐδέν, οὔτε ὅσοι Ἑλλήνων ταύτην τὴν χώρην οἰκέουσι· οἰκέουσι δὲ καὶ ἄλλοι καὶ Λακεδαιμονίων ἄποικοι Κνίδιοι. οἳ τῆς χώρης τῆς σφετέρης τετραμμένης ἐς πόντον, τὸ δὴ Τριόπιον καλέεται, ἀργμένης δὲ ἐκ τῆς Χερσονήσου τῆς Βυβασσίης, ἐούσης τε πάσης τῆς Κνιδίης πλὴν ὀλίγης περιρρόου (τὰ μὲν γὰρ αὐτῆς πρὸς βορέην ἄνεμον ὁ Κεραμεικὸς κόλπος ἀπέργει, τὰ δὲ πρὸς νότον ἡ κατὰ Σύμην τε καὶ Ῥόδον θάλασσα), τὸ ὦν δὴ ὀλίγον τοῦτο, ἐὸν ὅσον τε ἐπὶ πέντε στάδια, ὤρυσσον οἱ Κνίδιοι ἐν ὅσῳ Ἅρπαγος τὴν Ἰωνίην κατεστρέφετο, βουλόμενοι νῆσον τὴν χώρην ποιῆσαι. ἐντὸς δὲ πᾶσά σφι ἐγίνετο· τῇ γὰρ ἡ Κνιδίη χώρη ἐς τὴν ἤπειρον τελευτᾷ, ταύτῃ ὁ ἰσθμός ἐστι τὸν ὤρυσσον. καὶ δὴ πολλῇ χειρὶ ἐργαζομένων τῶν Κνιδίων, μᾶλλον γάρ τι καὶ θειότερον ἐφαίνοντο τιτρώσκεσθαι οἱ ἐργαζόμενοι τοῦ οἰκότος τά τε ἄλλα τοῦ σώματος καὶ μάλιστα τὰ περὶ τοὺς ὀφθαλμοὺς θραυομένης τῆς πέτρης, ἔπεμπον ἐς Δελφοὺς θεοπρόπους ἐπειρησομένους τὸ ἀντίξοον. ἡ δὲ Πυθίη σφι, ὡς αὐτοὶ Κνίδιοι λέγουσι, χρᾷ ἐν τριμέτρῳ τόνῳ τάδε.", "st": "1.174"}, {"sp": "N", "t": "Ἰσθμὸν δὲ μὴ πυργοῦτε μηδ’ ὀρύσσετε·<br>Ζεὺς γάρ κ’ ἔθηκε νῆσον, εἴ κ’ ἐβούλετο.", "st": "1.174b"}, {"sp": "N", "t": "Κνίδιοι μὲν ταῦτα τῆς Πυθίης χρησάσης τοῦ τε ὀρύγματος ἐπαύσαντο καὶ Ἁρπάγῳ ἐπιόντι σὺν τῷ στρατῷ ἀμαχητὶ σφέας αὐτοὺς παρέδοσαν.", "st": "1.174.6"}, {"sp": "N", "t": "ἦσαν δὲ Πηδασέες οἰκέοντες ὑπὲρ Ἁλικαρνησσοῦ μεσόγαιαν· τοῖσι ὅκως τι μέλλοι ἀνεπιτήδεον ἔσεσθαι, αὐτοῖσί τε καὶ τοῖσι περιοίκοισι, ἡ ἱρείη τῆς Ἀθηναίης πώγωνα μέγαν ἴσχε. τρὶς σφι τοῦτο ἐγένετο. οὗτοι τῶν περὶ Καρίην ἀνδρῶν μοῦνοί τε ἀντέσχον χρόνον Ἁρπάγῳ καὶ πρήγματα παρέσχον πλεῖστα, ὄρος τειχίσαντες τῷ οὔνομα ἐστὶ Λίδη.", "st": "1.175"}, {"sp": "N", "t": "Πηδασέες μέν νυν χρόνῳ ἐξαιρέθησαν. Λύκιοι δέ, ὡς ἐς τὸ Ξάνθιον πεδίον ἤλασε ὁ Ἅρπαγος τὸν στρατόν, ἐπεξιόντες καὶ μαχόμενοι ὀλίγοι πρὸς πολλοὺς ἀρετᾶς ἀπεδείκνυντο, ἑσσωθέντες δὲ καὶ κατειληθέντες ἐς τὸ ἄστυ συνήλισαν ἐς τὴν ἀκρόπολιν τάς τε γυναῖκας καὶ τὰ τέκνα καὶ τὰ χρήματα καὶ τοὺς οἰκέτας, καὶ ἔπειτα ὑπῆψαν τὴν ἀκρόπολιν πᾶσαν ταύτην καίεσθαι. ταῦτα δὲ ποιήσαντες καὶ συνομόσαντες ὅρκους δεινούς, ἐπεξελθόντες ἀπέθανον πάντες Ξάνθιοι μαχόμενοι. τῶν δὲ νῦν Λυκίων φαμένων Ξανθίων εἶναι οἱ πολλοί, πλὴν ὀγδώκοντα ἱστιέων, εἰσὶ ἐπήλυδες· αἱ δὲ ὀγδώκοντα ἱστίαι αὗται ἔτυχον τηνικαῦτα ἐκδημέουσι καὶ οὕτω περιεγένοντο. τὴν μὲν δὴ Ξάνθον οὕτω ἔσχε ὁ Ἅρπαγος, παραπλησίως δὲ καὶ τὴν Καῦνον ἔσχε· καὶ γὰρ οἱ Καύνιοι τοὺς Λυκίους ἐμιμήσαντο τὰ πλέω.", "st": "1.176"}, {"sp": "N", "t": "τὰ μέν νυν κάτω τῆς Ἀσίης Ἅρπαγος ἀνάστατα ἐποίεε, τὰ δὲ ἄνω αὐτῆς αὐτὸς Κῦρος, πᾶν ἔθνος καταστρεφόμενος καὶ οὐδὲν παριείς. τὰ μέν νυν αὐτῶν πλέω παρήσομεν· τὰ δὲ οἱ παρέσχε τε πόνον πλεῖστον καὶ ἀξιαπηγητότατα ἐστί, τούτων ἐπιμνήσομαι.", "st": "1.177"}, {"sp": "N", "t": "Κῦρος ἐπείτε τὰ πάντα τῆς ἠπείρου ὑποχείρια ἐποιήσατο, Ἀσσυρίοισι ἐπετίθετο. τῆς δὲ Ἀσσυρίης ἐστὶ μὲν κου καὶ ἄλλα πολίσματα μεγάλα πολλά, τὸ δὲ ὀνομαστότατον καὶ ἰσχυρότατον καὶ ἔνθα σφι Νίνου ἀναστάτου γενομένης τὰ βασιλήια κατεστήκεε, ἦν Βαβυλών, ἐοῦσα τοιαύτη δή τις πόλις. κέεται ἐν πεδίῳ μεγάλῳ, μέγαθος ἐοῦσα μέτωπον ἕκαστον εἴκοσι καὶ ἑκατὸν σταδίων, ἐούσης τετραγώνου· οὗτοι στάδιοι τῆς περιόδου τῆς πόλιος γίνονται συνάπαντες ὀγδώκοντα καὶ τετρακόσιοι, τὸ μέν νυν μέγαθος τοσοῦτον ἐστὶ τοῦ ἄστεος τοῦ Βαβυλωνίου, ἐκεκόσμητο δὲ ὡς οὐδὲν ἄλλο πόλισμα τῶν ἡμεῖς ἴδμεν. τάφρος μὲν πρῶτά μιν βαθέα τε καὶ εὐρέα καὶ πλέη ὕδατος περιθέει, μετὰ δὲ τεῖχος πεντήκοντα μὲν πηχέων βασιληίων ἐὸν τὸ εὖρος, ὕψος δὲ διηκοσίων πηχέων· ὁ δὲ βασιλήιος πῆχυς τοῦ μετρίου ἐστὶ πήχεος μέζων τρισὶ δακτύλοισι.", "st": "1.178"}, {"sp": "N", "t": "δεῖ δή με πρὸς τούτοισι ἔτι φράσαι ἵνα τε ἐκ τῆς τάφρου ἡ γῆ ἀναισιμώθη, καὶ τὸ τεῖχος ὅντινα τρόπον ἔργαστο. ὀρύσσοντες ἅμα τὴν τάφρον ἐπλίνθευον τὴν γῆν τὴν ἐκ τοῦ ὀρύγματος ἐκφερομένην, ἑλκύσαντες δὲ πλίνθους ἱκανὰς ὤπτησαν αὐτὰς ἐν καμίνοισι· μετὰ δὲ τέλματι χρεώμενοι ἀσφάλτῳ θερμῇ καὶ διὰ τριήκοντα δόμων πλίνθου ταρσοὺς καλάμων διαστοιβάζοντες, ἔδειμαν πρῶτα μὲν τῆς τάφου τὰ χείλεα, δευτέρα δὲ αὐτὸ τὸ τεῖχος τὸν αὐτὸν τρόπον. ἐπάνω δὲ τοῦ τείχεος παρὰ τὰ ἔσχατα οἰκήματα μουνόκωλα ἔδειμαν, τετραμμένα ἐς ἄλληλα· τὸ μέσον δὲ τῶν οἰκημάτων ἔλιπον τεθρίππῳ περιέλασιν. πύλαι δὲ ἐνεστᾶσι πέριξ τοῦ τείχεος ἑκατόν, χάλκεαι πᾶσαι, καὶ σταθμοί τε καὶ ὑπέρθυρα ὡσαύτως. ἔστι δὲ ἄλλη πόλις ἀπέχουσα ὀκτὼ ἡμερέων ὁδὸν ἀπὸ Βαβυλῶνος· Ἲς οὔνομα αὐτῇ. ἔνθα ἐστὶ ποταμὸς οὐ μέγας· Ἲς καὶ τῷ ποταμῷ τὸ οὔνομα· ἐσβάλλει δὲ οὗτος ἐς τὸν Εὐφρήτην ποταμὸν τὸ ῥέεθρον. οὗτος ὦν ὁ Ἲς ποταμὸς ἅμα τῷ ὕδατι θρόμβους ἀσφάλτου ἀναδιδοῖ πολλούς, ἔνθεν ἡ ἄσφαλτος ἐς τὸ ἐν Βαβυλῶνι τεῖχος ἐκομίσθη.", "st": "1.179"}, {"sp": "N", "t": "ἐτετείχιστο μέν νυν ἡ Βαβυλὼν τρόπῳ τοιῷδε, ἔστι δὲ δύο φάρσεα τῆς πόλιος. τὸ γὰρ μέσον αὐτῆς ποταμὸς διέργει, τῷ οὔνομα ἐστὶ Εὐφρήτης· ῥέει δὲ ἐξ Ἀρμενίων, ἐὼν μέγας καὶ βαθὺς καὶ ταχύς· ἐξιεῖ δὲ οὗτος ἐς τὴν Ἐρυθρὴν θάλασσαν. τὸ ὦν δὴ τεῖχος ἑκάτερον τοὺς ἀγκῶνας ἐς τὸν ποταμὸν ἐλήλαται· τὸ δὲ ἀπὸ τούτου αἱ ἐπικαμπαὶ παρὰ χεῖλος ἑκάτερον τοῦ ποταμοῦ αἱμασιὴ πλίνθων ὀπτέων παρατείνει. τὸ δὲ ἄστυ αὐτό, ἐὸν πλῆρες οἰκιέων τριωρόφων καὶ τετρωρόφων, κατατέτμηται τὰς ὁδοὺς ἰθέας τάς τε ἄλλας καὶ τὰς ἐπικαρσίας τὰς ἐπὶ τὸν ποταμὸν ἐχούσας. κατὰ δὴ ὦν ἑκάστην ὁδὸν ἐν τῇ αἱμασιῇ τῇ παρὰ τὸν ποταμὸν πυλίδες ἐπῆσαν, ὅσαι περ αἱ λαῦραι, τοσαῦται ἀριθμόν· ἦσαν δὲ καὶ αὗται χάλκεαι … φέρουσαι [καὶ αὐταὶ] ἐς αὐτὸν τὸν ποταμόν.", "st": "1.180"}, {"sp": "N", "t": "τοῦτο μὲν δὴ τὸ τεῖχος θώρηξ ἐστί, ἕτερον δὲ ἔσωθεν τεῖχος περιθέει, οὐ πολλῷ τεῳ ἀσθενέστερον τοῦ ἑτέρου τείχεος, στεινότερον δέ. ἐν δὲ φάρσεϊ ἑκατέρῳ τῆς πόλιος ἐτετείχιστο ἐν μέσῳ ἐν τῷ μὲν τὰ βασιλήια περιβόλῳ μεγάλῳ τε καὶ ἰσχυρῷ, ἐν δὲ τῷ ἑτέρῳ Διὸς Βήλου ἱρὸν χαλκόπυλον, καὶ ἐς ἐμὲ ἔτι τοῦτο ἐόν, δύο σταδίων πάντῃ, ἐὸν τετράγωνον. ἐν μέσῳ δὲ τοῦ ἱροῦ πύργος στερεὸς οἰκοδόμηται, σταδίου καὶ τὸ μῆκος καὶ τὸ εὖρος, καὶ ἐπὶ τούτῳ τῷ πύργῳ ἄλλος πύργος ἐπιβέβηκε, καὶ ἕτερος μάλα ἐπὶ τούτῳ, μέχρι οὗ ὀκτὼ πύργων. ἀνάβασις δὲ ἐς αὐτοὺς ἔξωθεν κύκλῳ περὶ πάντας τοὺς πύργους ἔχουσα πεποίηται. μεσοῦντι δέ κου τῆς ἀναβάσιος ἐστὶ καταγωγή τε καὶ θῶκοι ἀμπαυστήριοι, ἐν τοῖσι κατίζοντες ἀμπαύονται οἱ ἀναβαίνοντες. ἐν δὲ τῷ τελευταίῳ πύργῳ νηὸς ἔπεστι μέγας· ἐν δὲ τῷ νηῷ κλίνη μεγάλη κέεται εὖ ἐστρωμένη, καὶ οἱ τράπεζα παρακέεται χρυσέη. ἄγαλμα δὲ οὐκ ἔνι οὐδὲν αὐτόθι ἐνιδρυμένον, οὐδὲ νύκτα οὐδεὶς ἐναυλίζεται ἀνθρώπων ὅτι μὴ γυνὴ μούνη τῶν ἐπιχωρίων, τὴν ἂν ὁ θεὸς ἕληται ἐκ πασέων, ὡς λέγουσι οἱ Χαλδαῖοι ἐόντες ἱρέες τούτου τοῦ θεοῦ.", "st": "1.181"}, {"sp": "N", "t": "φασὶ δὲ οἱ αὐτοὶ οὗτοι, ἐμοὶ μὲν οὐ πιστὰ λέγοντες, τὸν θεὸν αὐτὸν φοιτᾶν τε ἐς τὸν νηὸν καὶ ἀμπαύεσθαι ἐπὶ τῆς κλίνης, κατά περ ἐν Θήβῃσι τῇσι Αἰγυπτίῃσι κατὰ τὸν αὐτὸν τρόπον, ὡς λέγουσι οἱ Αἰγύπτιοι· καὶ γὰρ δὴ ἐκεῖθι κοιμᾶται ἐν τῷ τοῦ Διὸς τοῦ Θηβαιέος γυνή, ἀμφότεραι δὲ αὗται λέγονται ἀνδρῶν οὐδαμῶν ἐς ὁμιλίην φοιτᾶν· καὶ κατά περ ἐν Πατάροισι τῆς Λυκίης ἡ πρόμαντις τοῦ θεοῦ, ἐπεὰν γένηται· οὐ γὰρ ὦν αἰεί ἐστι χρηστήριον αὐτόθι· ἐπεὰν δὲ γένηται τότε ὦν συγκατακληίεται τὰς νύκτας ἔσω ἐν τῷ νηῷ.", "st": "1.182"}, {"sp": "N", "t": "ἔστι δὲ τοῦ ἐν Βαβυλῶνι ἱροῦ καὶ ἄλλος κάτω νηός, ἔνθα ἄγαλμα μέγα τοῦ Διὸς ἔνι κατήμενον χρύσεον, καὶ οἱ τράπεζα μεγάλη παρακέεται χρυσέη, καὶ τὸ βάθρον οἱ καὶ ὁ θρόνος χρύσεος ἐστί· καὶ ὡς ἔλεγον οἱ Χαλδαῖοι, ταλάντων ὀκτακοσίων χρυσίου πεποίηται ταῦτα. ἔξω δὲ τοῦ νηοῦ βωμός ἐστι χρύσεος, ἔστι δὲ καὶ ἄλλος βωμὸς μέγας, ἐπ’ οὗ θύεται τὰ τέλεα τῶν προβάτων· ἐπὶ γὰρ τοῦ χρυσέου βωμοῦ οὐκ ἔξεστι θύειν ὅτι μὴ γαλαθηνὰ μούνα, ἐπὶ δὲ τοῦ μέζονος βωμοῦ καὶ καταγίζουσι λιβανωτοῦ χίλια τάλαντα ἔτεος ἑκάστου οἱ Χαλδαῖοι τότε ἐπεὰν τὴν ὁρτὴν ἄγωσι τῷ θεῷ τούτῳ. ἦν δὲ ἐν τῷ τεμένεϊ τούτῳ ἔτι τὸν χρόνον ἐκεῖνον καὶ ἀνδριὰς δυώδεκα πηχέων χρύσεος στερεός· ἐγὼ μέν μιν οὐκ εἶδον, τὰ δὲ λέγεται ὑπὸ Χαλδαίων, ταῦτα λέγω. τούτῳ τῷ ἀνδριάντι Δαρεῖος μὲν ὁ Ὑστάσπεος ἐπιβουλεύσας οὐκ ἐτόλμησε λαβεῖν, Ξέρξης δὲ ὁ Δαρείου ἔλαβε καὶ τὸν ἱρέα ἀπέκτεινε ἀπαγορεύοντα μὴ κινέειν τὸν ἀνδριάντα. τὸ μὲν δὴ ἱρὸν τοῦτο οὕτω κεκόσμηται, ἔστι δὲ καὶ ἴδια ἀναθήματα πολλά.", "st": "1.183"}, {"sp": "N", "t": "τῆς δὲ Βαβυλῶνος ταύτης πολλοὶ μέν κου καὶ ἄλλοι ἐγένοντο βασιλέες, τῶν ἐν τοῖσι Ἀσσυρίοισι λόγοισι μνήμην ποιήσομαι, οἳ τὰ τείχεά τε ἐπεκόσμησαν καὶ τὰ ἱρά, ἐν δὲ δὴ καὶ γυναῖκες δύο. ἡ μὲν πρότερον ἄρξασα, τῆς ὕστερον γενεῇσι πέντε πρότερον γενομένη, τῇ οὔνομα ἦν Σεμίραμις, αὕτη μὲν ἀπεδέξατο χώματα ἀνὰ τὸ πεδίον ἐόντα ἀξιοθέητα· πρότερον δὲ ἐώθεε ὁ ποταμὸς ἀνὰ τὸ πεδίον πᾶν πελαγίζειν.", "st": "1.184"}, {"sp": "N", "t": "ἡ δὲ δὴ δεύτερον γενομένη ταύτης βασίλεια, τῇ οὔνομα ἦν Νίτωκρις, αὕτη δὲ συνετωτέρη γενομένη τῆς πρότερον ἀρξάσης τοῦτο μὲν μνημόσυνα ἐλίπετο τὰ ἐγὼ ἀπηγήσομαι, τοῦτο δὲ τὴν Μήδων ὁρῶσα ἀρχὴν μεγάλην τε καὶ οὐκ ἀτρεμίζουσαν, ἀλλ’ ἄλλα τε ἀραιρημένα ἄστεα αὐτοῖσι, ἐν δὲ δὴ καὶ τὴν Νίνον, προεφυλάξατο ὅσα ἐδύνατο μάλιστα. πρῶτα μὲν τὸν Εὐφρήτην ποταμὸν ῥέοντα πρότερον ἰθύν, ὅς σφι διὰ τῆς πόλιος μέσης ῥέει, τοῦτον ἄνωθεν διώρυχας ὀρύξασα οὕτω δή τι ἐποίησε σκολιὸν ὥστε δὴ τρὶς ἐς τῶν τινα κωμέων τῶν ἐν τῇ Ἀσσυρίῃ ἀπικνέεται ῥέων· τῇ δὲ κώμῃ οὔνομα ἐστί, ἐς τὴν ἀπικνέεται ὁ Εὐφρήτης, Ἀρδέρικκα. καὶ νῦν οἳ ἂν κομίζωνται ἀπὸ τῆσδε τῆς θαλάσσης ἐς Βαβυλῶνα, καταπλέοντες τὸν Εὐφρήτην ποταμὸν τρίς τε ἐς τὴν αὐτὴν ταύτην κώμην παραγίνονται καὶ ἐν τρισὶ ἡμέρῃσι. τοῦτο μὲν δὴ τοιοῦτον ἐποίησε, χῶμα δὲ παρέχωσε παρ’ ἑκάτερον τοῦ ποταμοῦ τὸ χεῖλος ἄξιον θώματος μέγαθος καὶ ὕψος ὅσον τι ἐστί. κατύπερθε δὲ πολλῷ Βαβυλῶνος ὤρυσσε ἔλυτρον λίμνῃ, ὀλίγον τι παρατείνουσα ἀπὸ τοῦ ποταμοῦ, βάθος μὲν ἐς τὸ ὕδωρ αἰεὶ ὀρύσσουσα, εὖρος δὲ τὸ περίμετρον αὐτοῦ ποιεῦσα εἴκοσί τε καὶ τετρακοσίων σταδίων· τὸν δὲ ὀρυσσόμενον χοῦν ἐκ τούτου τοῦ ὀρύγματος ἀναισίμου παρὰ τὰ χείλεα τοῦ ποταμοῦ παραχέουσα. ἐπείτε δέ οἱ ὀρώρυκτο, λίθους ἀγαγομένη κρηπῖδα κύκλῳ περὶ αὐτὴν ἤλασε. ἐποίεε δὲ ἀμφότερα ταῦτα, τόν τε ποταμὸν σκολιὸν καὶ τὸ ὄρυγμα πᾶν ἕλος, ὡς ὅ τε ποταμὸς βραδύτερος εἴη περὶ καμπὰς πολλὰς ἀγνύμενος, καὶ οἱ πλόοι ἔωσι σκολιοὶ ἐς τὴν Βαβυλῶνα, ἔκ τε τῶν πλόων ἐκδέκηται περίοδος τῆς λίμνης μακρή. κατὰ τοῦτο δὲ ἐργάζετο τῆς χώρης τῇ αἵ τε ἐσβολαὶ ἦσαν καὶ τὰ σύντομα τῆς ἐκ Μήδων ὁδοῦ, ἵνα μὴ ἐπιμισγόμενοι οἱ Μῆδοι ἐκμανθάνοιεν αὐτῆς τὰ πρήγματα.", "st": "1.185"}, {"sp": "N", "t": "ταῦτα μὲν δὴ ἐκ βάθεος περιεβάλετο, τοιήνδε δὲ ἐξ αὐτῶν παρενθήκην ἐποιήσατο. τῆς πόλιος ἐούσης δύο φαρσέων, τοῦ δὲ ποταμοῦ μέσον ἔχοντος, ἐπὶ τῶν πρότερον βασιλέων ὅκως τις ἐθέλοι ἐκ τοῦ ἑτέρου φάρσεος ἐς τοὔτερον διαβῆναι, χρῆν πλοίῳ διαβαίνειν, καὶ ἦν, ὡς ἐγὼ δοκέω, ὀχληρὸν τοῦτο. αὕτη δὲ καὶ τοῦτο προεῖδε. ἐπείτε γὰρ ὤρυσσε τὸ ἔλυτρον τῇ λίμνῃ, μνημόσυνον τόδε ἄλλο ἀπὸ τοῦ αὐτοῦ ἔργου ἐλίπετο· ἐτάμνετο λίθους περιμήκεας, ὡς δέ οἱ ἦσαν οἱ λίθοι ἕτοιμοι καὶ τὸ χωρίον ὀρώρυκτο, ἐκτρέψασα τοῦ ποταμοῦ τὸ ῥέεθρον πᾶν ἐς τὸ ὤρυσσε χωρίον, ἐν ᾧ ἐπίμπλατο τοῦτο, ἐν τούτω ἀπεξηρασμένου τοῦ ἀρχαίου ῥεέθρου τοῦτο μὲν τὰ χείλεα τοῦ ποταμοῦ κατὰ τὴν πόλιν καὶ τὰς καταβάσιας τὰς ἐκ τῶν πυλίδων ἐς τὸν ποταμὸν φερούσας ἀνοικοδόμησε πλίνθοισι ὀπτῇσι κατὰ τὸν αὐτὸν λόγον τῷ τείχεϊ, τοῦτο δὲ κατὰ μέσην κου μάλιστα τὴν πόλιν τοῖσι λίθοισι τοὺς ὠρύξατο οἰκοδόμεε γέφυραν, δέουσα τοὺς λίθους σιδήρῳ τε καὶ μολύβδῳ. ἐπιτείνεσκε δὲ ἐπ’ αὐτήν, ὅκως μὲν ἡμέρη γίνοιτο, ξύλα τετράγωνα, ἐπ’ ὧν τὴν διάβασιν ἐποιεῦντο οἱ Βαβυλώνιοι· τὰς δὲ νύκτας τὰ ξύλα ταῦτα ἀπαιρέεσκον τοῦδε εἵνεκα, ἵνα μὴ διαφοιτέοντες τὰς νύκτας κλέπτοιεν παρ’ ἀλλήλων. ὡς δὲ τό τε ὀρυχθὲν λίμνη πλήρης ἐγεγόνεε ὑπὸ τοῦ ποταμοῦ καὶ τὰ περὶ τὴν γέφυραν ἐκεκόσμητο, τὸν Εὐφρήτην ποταμὸν ἐς τὰ ἀρχαῖα ῥέεθρα ἐκ τῆς λίμνης ἐξήγαγε, καὶ οὕτω τὸ ὀρυχθὲν ἕλος γενόμενον ἐς δέον ἐδόκεε γεγονέναι καὶ τοῖσι πολιήτῃσι γέφυρα ἦν κατεσκευασμένη.", "st": "1.186"}, {"sp": "N", "t": "ἡ δ’ αὐτὴ αὕτη βασίλεια καὶ ἀπάτην τοιήνδε τινὰ ἐμηχανήσατο· ὕπερ τῶν μάλιστα λεωφόρων πυλέων τοῦ ἄστεος τάφον ἑωυτῇ κατεσκευάσατο μετέωρον ἐπιπολῆς αὐτέων τῶν πυλέων, ἐνεκόλαψε δὲ ἐς τὸν τάφον γράμματα λέγοντα τάδε. τῶν τις ἐμεῦ ὕστερον γινομένων Βαβυλῶνος βασιλέων ἢν σπανίσῃ χρημάτων, ἀνοίξας τὸν τάφον λαβέτω ὁκόσα βούλεται χρήματα· μὴ μέντοι γε μὴ σπανίσας γε ἄλλως ἀνοίξῃ· οὐ γὰρ ἄμεινον· οὗτος ὁ τάφος ἦν ἀκίνητος μέχρι οὗ ἐς Δαρεῖον περιῆλθε ἡ βασιληίη· Δαρείῳ δὲ καὶ δεινὸν ἐδόκεε εἶναι τῇσι πύλῃσι ταύτῃσι μηδὲν χρᾶσθαι, καὶ χρημάτων κειμένων καὶ αὐτῶν τῶν γραμμάτων ἐπικαλεομένων, μὴ οὐ λαβεῖν αὐτά· τῇσι δὲ πύλῃσι ταύτῃσι οὐδὲν ἐχρᾶτο τοῦδε εἵνεκα, ὅτι ὕπερ κεφαλῆς οἱ ἐγίνετο ὁ νεκρὸς διεξελαύνοντι. ἀνοίξας δὲ τὸν τάφον εὗρε χρήματα μὲν οὔ, τὸν δὲ νεκρὸν καὶ γράμματα λέγοντα τάδε· εἰ μὴ ἄπληστός τε ἔας χρημάτων καὶ αἰσχροκερδής, οὐκ ἂν νεκρῶν θήκας ἀνέῳγες. αὕτη μέν νυν ἡ βασίλεια τοιαύτη τις λέγεται γενέσθαι.", "st": "1.187"}, {"sp": "N", "t": "ὁ δὲ δὴ Κῦρος ἐπὶ ταύτης τῆς γυναικὸς τὸν παῖδα ἐστρατεύετο, ἔχοντά τε τοῦ πατρὸς τοῦ ἑωυτοῦ τοὔνομα Λαβυνήτου καὶ τὴν Ἀσσυρίων ἀρχήν. στρατεύεται δὲ δὴ βασιλεὺς ὁ μέγας καὶ σιτίοισι εὖ ἐσκευασμένος ἐξ οἴκου καὶ προβάτοισι, καὶ δὴ καὶ ὕδωρ ἀπὸ τοῦ Χοάσπεω ποταμοῦ ἅμα ἄγεται τοῦ παρὰ Σοῦσα ῥέοντος, τοῦ μούνου πίνει βασιλεὺς καὶ ἄλλου οὐδενὸς ποταμοῦ. τούτου δὲ τοῦ Χοάσπεω τοῦ ὕδατος ἀπεψημένου πολλαὶ κάρτα ἅμαξαι τετράκυκλοι ἡμιόνεαι κομίζουσαι ἐν ἀγγηίοισι ἀργυρέοισι ἕπονται, ὅκῃ ἂν ἐλαύνῃ ἑκάστοτε.", "st": "1.188"}, {"sp": "N", "t": "ἐπείτε δὲ ὁ Κῦρος πορευόμενος ἐπὶ τὴν Βαβυλῶνα ἐγίνετο ἐπὶ Γύνδῃ ποταμῷ, τοῦ αἱ μὲν πηγαὶ ἐν Ματιηνοῖσι ὄρεσι, ῥέει δὲ διὰ Δαρδανέων, ἐκδιδοῖ δὲ ἐς ἕτερον ποταμὸν Τίγρην, ὁ δὲ παρὰ Ὦπιν πόλιν ῥέων ἐς τὴν Ἐρυθρὴν θάλασσαν ἐκδιδοῖ, τοῦτον δὴ τὸν Γύνδην ποταμὸν ὡς διαβαίνειν ἐπειρᾶτο ὁ Κῦρος ἐόντα νηυσιπέρητον, ἐνθαῦτά οἱ τῶν τις ἱρῶν ἵππων τῶν λευκῶν ὑπὸ ὕβριος ἐσβὰς ἐς τὸν ποταμὸν διαβαίνειν ἐπειρᾶτο, ὁ δέ μιν συμψήσας ὑποβρύχιον οἰχώκεε φέρων. κάρτα τε δὴ ἐχαλέπαινε τῷ ποταμῷ ὁ Κῦρος τοῦτο ὑβρίσαντι, καί οἱ ἐπηπείλησε οὕτω δή μιν ἀσθενέα ποιήσειν ὥστε τοῦ λοιποῦ καὶ γυναῖκας μιν εὐπετέως τὸ γόνυ οὐ βρεχούσας διαβήσεσθαι. μετὰ δὲ τὴν ἀπειλὴν μετεὶς τὴν ἐπὶ Βαβυλῶνα στράτευσιν διαίρεε τὴν στρατιὴν δίχα, διελὼν δὲ κατέτεινε σχοινοτενέας ὑποδέξας διώρυχας ὀγδώκοντα καὶ ἑκατὸν παρ’ ἑκάτερον τὸ χεῖλος τοῦ Γύνδεω τετραμμένας πάντα τρόπον, διατάξας δὲ τὸν στρατὸν ὀρύσσειν ἐκέλευε. οἷα δὲ ὁμίλου πολλοῦ ἐργαζομένου ἤνετο μὲν τὸ ἔργον, ὅμως μέντοι τὴν θερείην πᾶσαν αὐτοῦ ταύτῃ διέτριψαν ἐργαζόμενοι.", "st": "1.189"}, {"sp": "N", "t": "ὡς δὲ τὸν Γύνδην ποταμὸν ἐτίσατο Κῦρος ἐς τριηκοσίας καὶ ἑξήκοντα διώρυχάς μιν διαλαβών, καὶ τὸ δεύτερον ἔαρ ὑπέλαμπε, οὕτω δὴ ἤλαυνε ἐπὶ τὴν Βαβυλῶνα. οἱ δὲ Βαβυλώνιοι ἐκστρατευσάμενοι ἔμενον αὐτόν. ἐπεὶ δὲ ἐγένετο ἐλαύνων ἀγχοῦ τῆς πόλιος, συνέβαλόν τε οἱ Βαβυλώνιοι καὶ ἑσσωθέντες τῇ μάχῃ κατειλήθησαν ἐς τὸ ἄστυ. οἷα δὲ ἐξεπιστάμενοι ἔτι πρότερον τὸν Κῦρον οὐκ ἀτρεμίζοντα, ἀλλ’ ὁρέοντες αὐτὸν παντὶ ἔθνεϊ ὁμοίως ἐπιχειρέοντα, προεσάξαντο σιτία ἐτέων κάρτα πολλῶν. ἐνθαῦτα οὗτοι μὲν λόγον εἶχον τῆς πολιορκίης οὐδένα, Κῦρος δὲ ἀπορίῃσι ἐνείχετο, ἅτε χρόνου τε ἐγγινομένου συχνοῦ ἀνωτέρω τε οὐδὲν τῶν πρηγμάτων προκοπτομένων.", "st": "1.190"}, {"sp": "N", "t": "εἴτε δὴ ὦν ἄλλος οἱ ἀπορέοντι ὑπεθήκατο, εἴτε καὶ αὐτὸς ἔμαθε τὸ ποιητέον οἱ ἦν, ἐποίεε δὴ τοιόνδε. τάξας τὴν στρατιὴν ἅπασαν ἐξ ἐμβολῆς τοῦ ποταμοῦ, τῇ ἐς τὴν πόλιν ἐσβάλλει, καὶ ὄπισθε αὖτις τῆς πόλιος τάξας ἑτέρους, τῇ ἐξιεῖ ἐκ τῆς πόλιος ὁ ποταμός, προεῖπε τῷ στρατῷ, ὅταν διαβατὸν τὸ ῥέεθρον ἴδωνται γενόμενον, ἐσιέναι ταύτῃ ἐς τὴν πόλιν. οὕτω τε δὴ τάξας καὶ κατὰ ταῦτα παραινέσας ἀπήλαυνε αὐτὸς σὺν τῷ ἀχρηίῳ τοῦ στρατοῦ. ἀπικόμενος δὲ ἐπὶ τὴν λίμνην, τά περ ἡ τῶν Βαβυλωνίων βασίλεια ἐποίησε κατά τε τὸν ποταμὸν καὶ κατὰ τὴν λίμνην, ἐποίεε καὶ ὁ Κῦρος ἕτερα τοιαῦτα· τὸν γὰρ ποταμὸν διώρυχι ἐσαγαγὼν ἐς τὴν λίμνην ἐοῦσαν ἕλος, τὸ ἀρχαῖον ῥέεθρον διαβατὸν εἶναι ἐποίησε, ὑπονοστήσαντος τοῦ ποταμοῦ. γενομένου δὲ τούτου τοιούτου, οἱ Πέρσαι οἵ περ ἐτετάχατο ἐπ’ αὐτῷ τούτῳ κατὰ τὸ ῥέεθρον τοῦ Εὐφρήτεω ποταμοῦ ὑπονενοστηκότος ἀνδρὶ ὡς ἐς μέσον μηρὸν μάλιστά κῃ, κατὰ τοῦτο ἐσήισαν ἐς τὴν Βαβυλῶνα. εἰ μέν νυν προεπύθοντο ἢ ἔμαθον οἱ Βαβυλώνιοι τὸ ἐκ τοῦ Κύρου ποιεύμενον, οἳ δ’ ἂν περιιδόντες τοὺς Πέρσας ἐσελθεῖν ἐς τὴν πόλιν διέφθειραν ἂν κάκιστα· κατακληίσαντες γὰρ ἂν πάσας τὰς ἐς τὸν ποταμὸν πυλίδας ἐχούσας καὶ αὐτοὶ ἐπὶ τὰς αἱμασιὰς ἀναβάντες τὰς παρὰ τὰ χείλεα τοῦ ποταμοῦ ἐληλαμένας, ἔλαβον ἂν σφέας ὡς ἐν κύρτῃ. νῦν δὲ ἐξ ἀπροσδοκήτου σφι παρέστησαν οἱ Πέρσαι.", "st": "1.191"}, {"sp": "N", "t": "ὑπὸ δὲ μεγάθεος τῆς πόλιος, ὡς λέγεται ὑπὸ τῶν ταύτῃ οἰκημένων, τῶν περὶ τὰ ἔσχατα τῆς πόλιος ἑαλωκότων τοὺς τὸ μέσον οἰκέοντας τῶν Βαβυλωνίων οὐ μανθάνειν ἑαλωκότας, ἀλλὰ τυχεῖν γάρ σφι ἐοῦσαν ὁρτήν, χορεύειν τε τοῦτον τὸν χρόνον καὶ ἐν εὐπαθείῃσι εἶναι, ἐς ὃ δὴ καὶ τὸ κάρτα ἐπύθοντο.", "st": "1.191b"}, {"sp": "N", "t": "καὶ Βαβυλὼν μὲν οὕτω τότε πρῶτον ἀραίρητο. τὴν δὲ δύναμιν τῶν Βαβυλωνίων πολλοῖσι μὲν καὶ ἄλλοισι δηλώσω ὅση τις ἐστί, ἐν δὲ δὴ καὶ τῷδε. βασιλέι τῷ μεγάλῳ ἐς τροφὴν αὐτοῦ τε καὶ τῆς στρατιῆς διαραίρηται, πάρεξ τοῦ φόρου, γῆ πᾶσα ὅσης ἄρχει· δυώδεκα ὦν μηνῶν ἐόντων ἐς τὸν ἐνιαυτὸν τοὺς τέσσερας μῆνας τρέφει μιν ἡ Βαβυλωνίη χωρῇ, τοὺς δὲ ὀκτὼ τῶν μηνῶν ἡ λοιπὴ πᾶσα Ἀσίη. οὕτω τριτημορίη ἡ Ἀσσυρίη χώρη τῇ δυνάμι τῆς ἄλλης Ἀσίης. καὶ ἡ ἀρχὴ τῆς χώρης ταύτης, τὴν οἱ Πέρσαι σατραπηίην καλέουσι, ἐστὶ ἁπασέων τῶν ἀρχέων πολλόν τι κρατίστη, ὅκου Τριτανταίχμῃ τῷ Ἀρταβάζου ἐκ βασιλέος ἔχοντι τὸν νομὸν τοῦτον ἀργυρίου μὲν προσήιε ἑκάστης ἡμέρης ἀρτάβη μεστή. ἡ δὲ ἀρτάβη, μέτρον ἐὸν Περσικόν, χωρέει μεδίμνου Ἀττικοῦ πλέον χοίνιξι τρισὶ Ἀττικῇσι, ἵπποι δὲ οἱ αὐτοῦ ἦσαν ἰδίῃ, πάρεξ τῶν πολεμιστηρίων, οἱ μὲν ἀναβαίνοντες τὰς θηλέας ὀκτακόσιοι, αἱ δὲ βαινόμεναι ἑξακισχίλιαι καὶ μυρίαι· ἀνέβαινε γὰρ ἕκαστος τῶν ἐρσένων τούτων εἴκοσι ἵππους. κυνῶν δὲ Ἰνδικῶν τοσοῦτο δή τι πλῆθος ἐτρέφετο ὥστε τέσσερες τῶν ἐν τῷ πεδίῳ κῶμαι μεγάλαι, τῶν ἄλλων ἐοῦσαι ἀτελέες, τοῖσι κυσὶ προσετετάχατο σιτία παρέχειν. τοιαῦτα μὲν τῷ ἄρχοντι τῆς Βαβυλῶνος ὑπῆρχε ἐόντα.", "st": "1.192"}, {"sp": "N", "t": "ἡ δὲ γῆ τῶν Ἀσσυρίων ὕεται μὲν ὀλίγῳ, καὶ τὸ ἐκτρέφον τὴν ῥίζαν τοῦ σίτου ἐστὶ τοῦτο· ἀρδόμενον μέντοι ἐκ τοῦ ποταμοῦ ἁδρύνεταί τε τὸ λήιον καὶ παραγίνεται ὁ σῖτος, οὐ κατὰ περ ἐν Αἰγύπτῳ αὐτοῦ τοῦ ποταμοῦ ἀναβαίνοντος ἐς τὰς ἀρούρας, ἀλλὰ χερσί τε καὶ κηλωνηίοισι ἀρδόμενος. ἡ γὰρ Βαβυλωνίη χώρη πᾶσα, κατά περ ἡ Αἰγυπτίη, κατατέτμηται ἐς διώρυχας· καὶ ἡ μεγίστη τῶν διωρύχων ἐστὶ νηυσιπέρητος, πρὸς ἥλιον τετραμμένη τὸν χειμερινόν, ἐσέχει δὲ ἐς ἄλλον ποταμὸν ἐκ τοῦ Εὐφρήτεω, ἐς τὸν Τίγρην, παρ’ ὃν Νίνος πόλις οἴκητο. ἔστι δὲ χωρέων αὕτη πασέων μακρῷ ἀρίστη τῶν ἡμεῖς ἴδμεν Δήμητρος καρπὸν ἐκφέρειν … τὰ γὰρ δὴ ἄλλα δένδρεα οὐδὲ πειρᾶται ἀρχὴν φέρειν, οὔτε συκέην οὔτε ἄμπελον οὔτε ἐλαίην. τὸν δὲ τῆς Δήμητρος καρπὸν ὧδε ἀγαθὴ ἐκφέρειν ἐστὶ ὥστε ἐπὶ διηκόσια μὲν τὸ παράπαν ἀποδιδοῖ, ἐπειδὰν δὲ ἄριστα αὐτὴ ἑωυτῆς ἐνείκῃ, ἐπὶ τριηκόσια ἐκφέρει. τὰ δὲ φύλλα αὐτόθι τῶν τε πυρῶν καὶ τῶν κριθέων τὸ πλάτος γίνεται τεσσέρων εὐπετέως δακτύλων. ἐκ δὲ κέγχρου καὶ σησάμου ὅσον τι δένδρον μέγαθος γίνεται, ἐξεπιστάμενος μνήμην οὐ ποιήσομαι, εὖ εἰδὼς ὅτι τοῖσι μὴ ἀπιγμένοισι ἐς τὴν Βαβυλωνίην χώρην καὶ τὰ εἰρημένα καρπῶν ἐχόμενα ἐς ἀπιστίην πολλὴν ἀπῖκται. χρέωνται δὲ οὐδὲν ἐλαίῳ ἀλλ’ ἢ ἐκ τῶν σησάμων ποιεῦντες. εἰσὶ δέ σφι φοίνικες πεφυκότες ἀνὰ πᾶν τὸ πεδίον, οἱ πλεῦνες αὐτῶν καρποφόροι, ἐκ τῶν καὶ σιτία καὶ οἶνον καὶ μέλι ποιεῦνται· τοὺς συκέων τρόπον θεραπεύουσι τά τε ἄλλα καὶ φοινίκων τοὺς ἔρσενας Ἕλληνες καλέουσι, τούτων τὸν καρπὸν περιδέουσι τῇσι βαλανηφόροισι τὸν φοινίκων, ἵνα πεπαίνῃ τε σφι ὁ ψὴν τὴν βάλανον ἐσδύνων καὶ μὴ ἀπορρέῃ ὁ καρπὸς τοῦ φοίνικος· ψῆνας γὰρ δὴ φέρουσι ἐν τῷ καρπῷ οἱ ἔρσενες κατά περ δὴ οἱ ὄλυνθοι.", "st": "1.193"}, {"sp": "N", "t": "τὸ δὲ ἁπάντων θῶμα μέγιστόν μοι ἐστὶ τῶν ταύτῃ μετά γε αὐτὴν τὴν πόλιν, ἔρχομαι φράσων· τὰ πλοῖα αὐτοῖσι ἐστὶ τὰ κατὰ τὸν ποταμὸν πορευόμενα ἐς τὴν Βαβυλῶνα, ἐόντα κυκλοτερέα, πάντα σκύτινα. ἐπεὰν γὰρ ἐν τοῖσι Ἀρμενίοισι τοῖσι κατύπερθε Ἀσσυρίων οἰκημένοισι νομέας ἰτέης ταμόμενοι ποιήσωνται, περιτείνουσι τούτοισι διφθέρας στεγαστρίδας ἔξωθεν ἐδάφεος τρόπον, οὔτε πρύμνην ἀποκρίνοντες οὔτε πρῴρην συνάγοντες, ἀλλ’ ἀσπίδος τρόπον κυκλοτερέα ποιήσαντες καὶ καλάμης πλήσαντες πᾶν τὸ πλοῖον τοῦτο ἀπιεῖσι κατὰ τὸν ποταμὸν φέρεσθαι, φορτίων πλήσαντες· μάλιστα δὲ βίκους φοινικηίους κατάγουσι οἴνου πλέους. ἰθύνεται δὲ ὑπό τε δύο πλήκτρων καὶ δύο ἀνδρῶν ὀρθῶν ἑστεώτων, καὶ ὃ μὲν ἔσω ἕλκει τὸ πλῆκτρον ὁ δὲ ἔξω ὠθέει. ποιέεται δὲ καὶ κάρτα μεγάλα ταῦτα τὰ πλοῖα καὶ ἐλάσσω· τὰ δὲ μέγιστα αὐτῶν καὶ πεντακισχιλίων ταλάντων γόμον ἔχει. ἐν ἑκάστῳ δὲ πλοίῳ ὄνος ζωὸς ἔνεστι, ἐν δὲ τοῖσι μέζοσι πλεῦνες. ἐπεὰν ὦν ἀπίκωνται πλέοντες ἐς τὴν Βαβυλῶνα καὶ διαθέωνται τὸν φόρτον, νομέας μὲν τοῦ πλοίου καὶ τὴν καλάμην πᾶσαν ἀπ’ ὦν ἐκήρυξαν, τὰς δὲ διφθέρας ἐπισάξαντες ἐπὶ τοὺς ὄνους ἀπελαύνουσι ἐς τοὺς Ἀρμενίους. ἀνὰ τὸν ποταμὸν γὰρ δὴ οὐκ οἷά τε ἐστὶ πλέειν οὐδενὶ τρόπῳ ὑπὸ τάχεος τοῦ ποταμοῦ· διὰ γὰρ ταῦτα καὶ οὐκ ἐκ ξύλων ποιεῦνται τὰ πλοῖα ἀλλ’ ἐκ διφθερέων. ἐπεὰν δὲ τοὺς ὄνους ἐλαύνοντες ἀπίκωνται ὀπίσω ἐς τοὺς Ἀρμενίους, ἄλλα τρόπῳ τῷ αὐτῷ ποιεῦνται πλοῖα.", "st": "1.194"}, {"sp": "N", "t": "τὰ μὲν δὴ πλοῖα αὐτοῖσι ἐστὶ τοιαῦτα· ἐσθῆτι δὲ τοιῇδε χρέωνται, κιθῶνι ποδηνεκέι λινέῳ, καὶ ἐπὶ τοῦτον ἄλλον εἰρίνεον κιθῶνα ἐπενδύνει καὶ χλανίδιον λευκὸν περιβαλλόμενος, ὑποδήματα ἔχων ἐπιχώρια, παραπλήσια τῇσι Βοιωτίῃσι ἐμβάσι. κομῶντες δὲ τὰς κεφαλὰς μίτρῃσι ἀναδέονται, μεμυρισμένοι πᾶν τὸ σῶμα. σφρηγῖδα δὲ ἕκαστος ἔχει καὶ σκῆπτρον χειροποίητον· ἐπ’ ἑκάστῳ δὲ σκήπτρῳ ἔπεστι πεποιημένον ἢ μῆλον ἢ ῥόδον ἢ κρίνον ἢ αἰετὸς ἢ ἄλλο τι· ἄνευ γὰρ ἐπισήμου οὔ σφι νόμος ἐστὶ ἔχειν σκῆπτρον.", "st": "1.195"}, {"sp": "N", "t": "αὕτη μὲν δή σφι ἄρτισις περὶ τὸ σῶμα ἐστί· νόμοι δὲ αὐτοῖσι ὧδε κατεστᾶσι, ὁ μὲν σοφώτατος ὅδε κατὰ γνώμην τὴν ἡμετέρην, τῷ καὶ Ἰλλυριῶν Ἐνετοὺς πυνθάνομαι χρᾶσθαι. κατὰ κώμας ἑκάστας ἅπαξ τοῦ ἔτεος ἑκάστου ἐποιέετο τάδε· ὡς ἂν αἱ παρθένοι γενοίατο γάμων ὡραῖαι, ταύτας ὅκως συναγάγοιεν πάσας, ἐς ἓν χωρίον ἐσάγεσκον ἁλέας, πέριξ δὲ αὐτὰς ἵστατο ὅμιλος ἀνδρῶν, ἀνιστὰς δὲ κατὰ μίαν ἑκάστην κῆρυξ πωλέεσκε, πρῶτα μὲν τὴν εὐειδεστάτην ἐκ πασέων· μετὰ δέ, ὅκως αὕτη εὑροῦσα πολλὸν χρυσίον πρηθείη, ἄλλην ἂν ἐκήρυσσε ἣ μετ’ ἐκείνην ἔσκε εὐειδεστάτη· ἐπωλέοντο δὲ ἐπὶ συνοικήσι. ὅσοι μὲν δὴ ἔσκον εὐδαίμονες τῶν Βαβυλωνίων ἐπίγαμοι, ὑπερβάλλοντες ἀλλήλους ἐξωνέοντο τὰς καλλιστευούσας· ὅσοι δὲ τοῦ δήμου ἔσκον ἐπίγαμοι, οὗτοι δὲ εἴδεος μὲν οὐδὲν ἐδέοντο χρηστοῦ, οἳ δ’ ἂν χρήματά τε καὶ αἰσχίονας παρθένους ἐλάμβανον. ὡς γὰρ δὴ διεξέλθοι ὁ κῆρυξ πωλέων τὰς εὐειδεστάτας τῶν παρθένων ἀνίστη ἂν τὴν ἀμορφεστάτην, ἢ εἴ τις αὐτέων ἔμπηρος εἴη, καὶ ταύτην ἂν ἐκήρυσσε, ὅστις θέλοι ἐλάχιστον χρυσίον λαβὼν συνοικέειν αὐτῇ, ἐς ὃ τῷ τὸ ἐλάχιστον ὑπισταμένῳ προσέκειτο. τὸ δὲ ἂν χρυσίον ἐγίνετο ἀπὸ τῶν εὐειδέων παρθένων καὶ οὕτω αἱ εὔμορφοι τὰς ἀμόρφους καὶ ἐμπήρους ἐξεδίδοσαν. ἐκδοῦναι δὲ τὴν ἑωυτοῦ θυγατέρα ὅτεῳ βούλοιτο ἕκαστος οὐκ ἐξῆν, οὐδὲ ἄνευ ἐγγυητέω ἀπάγεσθαι τὴν παρθένον πριάμενον, ἀλλ’ ἐγγυητὰς χρῆν καταστήσαντα ἦ μὲν συνοικήσειν αὐτῇ, οὕτω ἀπάγεσθαι. εἰ δὲ μὴ συμφεροίατο, ἀποφέρειν τὸ χρυσίον ἔκειτο νόμος. ἐξῆν δὲ καὶ ἐξ ἄλλης ἐλθόντα κώμης τὸν βουλόμενον ὠνέεσθαι. ὁ μέν νυν κάλλιστος νόμος οὗτός σφι ἦν, οὐ μέντοι νῦν γε διατελέει ἐών, ἄλλο δέ τι ἐξευρήκασι νεωστὶ γενέσθαι [ἵνα μὴ ἀδικοῖεν αὐτὰς μηδ’ εἰς ἑτέραν πόλιν ἄγωνται]· ἐπείτε γὰρ ἁλόντες ἐκακώθησαν καὶ οἰκοφθορήθησαν, πᾶς τις τοῦ δήμου βίου σπανίζων καταπορνεύει τὰ θήλεα τέκνα.", "st": "1.196"}, {"sp": "N", "t": "δεύτερος δὲ σοφίῃ ὅδε ἄλλος σφι νόμος κατέστηκε· τοὺς κάμνοντας ἐς τὴν ἀγορὴν ἐκφορέουσι· οὐ γὰρ δὴ χρέωνται ἰητροῖσι. προσιόντες ὦν πρὸς τὸν κάμνοντα συμβουλεύουσι περὶ τῆς νούσου, εἴ τις καὶ αὐτὸς τοιοῦτο ἔπαθε ὁκοῖον ἂν ἔχῃ ὁ κάμνων ἢ ἄλλον εἶδε παθόντα, ταῦτα προσιόντες συμβουλεύουσι καὶ παραινέουσι ἅσσα αὐτὸς ποιήσας ἐξέφυγε ὁμοίην νοῦσον ἢ ἄλλον εἶδε ἐκφυγόντα. σιγῇ δὲ παρεξελθεῖν τὸν κάμνοντα οὔ σφι ἔξεστι, πρὶν ἂν ἐπείρηται ἥντινα νοῦσον ἔχει.", "st": "1.197"}, {"sp": "N", "t": "ταφαὶ δέ σφι ἐν μέλιτι, θρῆνοι δὲ παραπλήσιοι τοῖσι ἐν Αἰγύπτῳ. ὁσάκις δ’ ἂν μιχθῇ γυναικὶ τῇ ἑωυτοῦ ἀνὴρ Βαβυλώνιος, περὶ θυμίημα καταγιζόμενον ἵζει, ἑτέρωθι δὲ ἡ γυνὴ τὠυτὸ τοῦτο ποιέει, ὄρθρου δὲ γενομένου λοῦνται καὶ ἀμφότεροι· ἄγγεος γὰρ οὐδενὸς ἅψονται πρὶν ἂν λούσωνται. ταὐτὰ δὲ ταῦτα καὶ Ἀράβιοι ποιεῦσι.", "st": "1.198"}, {"sp": "N", "t": "ὁ δὲ δὴ αἴσχιστος τῶν νόμων ἐστὶ τοῖσι Βαβυλωνίοισι ὅδε· δεῖ πᾶσαν γυναῖκα ἐπιχωρίην ἱζομένην ἐς ἱρὸν Ἀφροδίτης ἅπαξ ἐν τῇ ζόῃ μιχθῆναι ἀνδρὶ ξείνῳ. πολλαὶ δὲ καὶ οὐκ ἀξιούμεναι ἀναμίσγεσθαι τῇσι ἄλλῃσι, οἷα πλούτῳ ὑπερφρονέουσαι, ἐπὶ ζευγέων ἐν καμάρῃσι ἐλάσασαι πρὸς τὸ ἱρὸν ἑστᾶσι· θεραπηίη δέ σφι ὄπισθε ἕπεται πολλή. αἱ δὲ πλεῦνες ποιεῦσι ὧδε· ἐν τεμένεϊ Ἀφροδίτης κατέαται στέφανον περὶ τῇσι κεφαλῇσι ἔχουσαι θώμιγγος πολλαὶ γυναῖκες· αἳ μὲν γὰρ προσέρχονται, αἳ δὲ ἀπέρχονται. σχοινοτενέες δὲ διέξοδοι πάντα τρόπον ὁδῶν ἔχουσι διὰ τῶν γυναικῶν, δι’ ὧν οἱ ξεῖνοι διεξιόντες ἐκλέγονται· ἔνθα ἐπεὰν ἵζηται γυνή, οὐ πρότερον ἀπαλλάσσεται ἐς τὰ οἰκία ἤ τίς οἱ ξείνων ἀργύριον ἐμβαλὼν ἐς τὰ γούνατα μιχθῇ ἔξω τοῦ ἱροῦ· ἐμβαλόντα δὲ δεῖ εἰπεῖν τοσόνδε· ἐπικαλέω τοι τὴν θεὸν Μύλιττα. Μύλιττα δὲ καλέουσι τὴν Ἀφροδίτην Ἀσσύριοι. τὸ δὲ ἀργύριον μέγαθος ἐστὶ ὅσον ὦν· οὐ γὰρ μὴ ἀπώσηται· οὐ γάρ οἱ θέμις ἐστί· γίνεται γὰρ ἱρὸν τοῦτο τὸ ἀργύριον. τῷ δὲ πρώτῳ ἐμβαλόντι ἕπεται οὐδὲ ἀποδοκιμᾷ οὐδένα. ἐπεὰν δὲ μιχθῇ, ἀποσιωσαμένη τῇ θεῷ ἀπαλλάσσεται ἐς τὰ οἰκία, καὶ τὠπὸ τούτου οὐκ οὕτω μέγα τί οἱ δώσεις ὥς μιν λάμψεαι. ὅσσαι μέν νυν εἴδεός τε ἐπαμμέναι εἰσὶ καὶ μεγάθεος, ταχὺ ἀπαλλάσσονται, ὅσαι δὲ ἄμορφοι αὐτέων εἰσί, χρόνον πολλὸν προσμένουσι οὐ δυνάμεναι τὸν νόμον ἐκπλῆσαι· καὶ γὰρ τριέτεα καὶ τετραέτεα μετεξέτεραι χρόνον μένουσι. ἐνιαχῇ δὲ καὶ τῆς Κύπρου ἐστὶ παραπλήσιος τούτῳ νόμος.", "st": "1.199"}, {"sp": "N", "t": "νόμοι μὲν δὴ τοῖσι Βαβυλωνίοισι οὗτοι κατεστᾶσι· εἰσὶ δὲ αὐτῶν πατριαὶ τρεῖς αἳ οὐδὲν ἄλλο σιτέονται εἰ μὴ ἰχθὺς μοῦνον, τοὺς ἐπείτε ἂν θηρεύσαντες αὐήνωσι πρὸς ἥλιον, ποιεῦσι τάδε· ἐσβάλλουσι ἐς ὅλμον καὶ λεήναντες ὑπέροισι σῶσι διὰ σινδόνος, καὶ ὃς μὲν ἂν βούληται αὐτῶν ἅτε μᾶζαν μαξάμενος ἔχει, ὁ δὲ ἄρτου τρόπον ὀπτήσας.", "st": "1.200"}, {"sp": "N", "t": "ὡς δὲ τῷ Κύρῳ καὶ τοῦτο τὸ ἔθνος κατέργαστο, ἐπεθύμησε Μασσαγέτας ὑπ’ ἑωυτῷ ποιήσασθαι. τὸ δὲ ἔθνος τοῦτο καὶ μέγα λέγεται εἶναι καὶ ἄλκιμον, οἰκημένον δὲ πρὸς ἠῶ τε καὶ ἡλίου ἀνατολάς, πέρην τοῦ Ἀράξεω ποταμοῦ, ἀντίον δὲ Ἰσσηδόνων ἀνδρῶν. εἰσὶ δὲ οἵτινες καὶ Σκυθικὸν λέγουσι τοῦτο τὸ ἔθνος εἶναι.", "st": "1.201"}, {"sp": "N", "t": "ὁ δὲ Ἀράξης λέγεται καὶ μέζων καὶ ἐλάσσων εἶναι τοῦ Ἴστρου· νήσους δὲ ἐν αὐτῷ Λέσβῳ μεγάθεα παραπλησίας συχνάς φασι εἶναι, ἐν δὲ αὐτῇσι ἀνθρώπους οἳ σιτέονται μὲν ῥίζας τὸ θέρος ὀρύσσοντες παντοίας· καρποὺς δὲ ἀπὸ δενδρέων ἐξευρημένους σφι ἐς φορβὴν κατατίθεσθαι ὡραίους, καὶ τούτους σιτέεσθαι τὴν χειμερινήν. ἄλλα δέ σφι ἐξευρῆσθαι δένδρεα καρποὺς τοιούσδε τινὰς φέροντα, τοὺς ἐπείτε ἂν ἐς τὠυτὸ συνέλθωσι κατὰ εἴλας καὶ πῦρ ἀνακαύσωνται κύκλῳ περιιζομένους ἐπιβάλλειν ἐπὶ τὸ πῦρ, ὀσφραινομένους δὲ καταγιζομένου τοῦ καρποῦ τοῦ ἐπιβαλλομένου μεθύσκεσθαι τῇ ὀσμῇ κατά περ Ἕλληνας τῷ οἴνῳ πλεῦνος δὲ ἐπιβαλλομένου τοῦ καρποῦ μᾶλλον μεθύσκεσθαι, ἐς ὃ ἐς ὄρχησίν τε ἀνίστασθαι καὶ ἐς ἀοιδὴν ἀπικνέεσθαι. τούτων μὲν αὕτη λέγεται δίαιτᾳ εἶναι. ὁ δὲ Ἀράξης ποταμὸς ῥέει μὲν ἐκ Ματιηνῶν, ὅθεν περ ὁ Γύνδης τὸν ἐς τὰς διώρυχας τὰς ἑξήκοντά τε καὶ τριηκοσίας διέλαβε ὁ Κῦρος, στόμασι δὲ ἐξερεύγεται τεσσεράκοντα, τῶν τὰ πάντα πλὴν ἑνὸς ἐς ἕλεά τε καὶ τενάγεα ἐκδιδοῖ· ἐν τοῖσι ἀνθρώπους κατοικῆσθαι λέγουσι ἰχθῦς ὠμοὺς σιτεομένους, ἐσθῆτι δὲ νομίζοντας χρᾶσθαι φωκέων δέρμασι. τὸ δὲ ἓν τῶν στομάτων τοῦ Ἀράξεω ῥέει διὰ καθαροῦ ἐς τὴν Κασπίην θάλασσαν.", "st": "1.202"}, {"sp": "N", "t": "ἡ δὲ Κασπίη θάλασσα ἐστὶ ἐπ’ ἑωυτῆς, οὐ συμμίσγουσα τῇ ἑτέρῃ θαλάσσῃ. τὴν μὲν γὰρ Ἕλληνες ναυτίλλονται πᾶσα καὶ ἡ ἔξω στηλέων θάλασσα ἡ Ἀτλαντὶς καλεομένη καὶ ἡ Ἐρυθρὴ μία ἐοῦσα τυγχάνει. ἡ δὲ Κασπίη ἐστὶ ἑτέρη ἐπ’ ἑωυτῆς, ἐοῦσα μῆκος μὲν πλόου εἰρεσίῃ χρεωμένῳ πεντεκαίδεκα ἡμερέων, εὖρος δέ, τῇ εὐρυτάτη ἐστὶ αὐτὴ ἑωυτῆς, ὀκτὼ ἡμερέων. καὶ τὰ μὲν πρὸς τὴν ἑσπέρην φέροντα τῆς θαλάσσης ταύτης ὁ Καύκασος παρατείνει, ἐὸν ὀρέων καὶ πλήθεϊ μέγιστον καὶ μεγάθεϊ ὑψηλότατον. ἔθνεα δὲ ἀνθρώπων πολλὰ καὶ παντοῖα ἐν ἑωυτῷ ἔχει ὁ Καύκασος, τὰ πολλὰ πάντα ἀπ’ ὕλης ἀγρίης ζώοντα· ἐν τοῖσι καὶ δένδρεα φύλλα τοιῆσδε ἰδέης παρεχόμενα εἶναι λέγεται, τὰ τρίβοντάς τε καὶ παραμίσγοντας ὕδωρ ζῷα ἑωυτοῖσι ἐς τὴν ἐσθῆτα ἐγγράφειν· τὰ δὲ ζῷα οὐκ ἐκπλύνεσθαι, ἀλλὰ συγκαταγηράσκειν τῷ ἄλλῳ εἰρίῳ κατὰ περ ἐνυφανθέντα ἀρχήν. μῖξιν δὲ τούτων τῶν ἀνθρώπων εἶναι ἐμφανέα κατὰ περ τοῖσι προβάτοισι.", "st": "1.203"}, {"sp": "N", "t": "τὰ μὲν δὴ πρὸς ἑσπέρην τῆς θαλάσσης ταύτης τῆς Κασπίης καλεομένης ὁ Καύκασος ἀπέργει, τὰ δὲ πρὸς ἠῶ τε καὶ ἥλιον ἀνατέλλοντα πεδίον ἐκδέκεται πλῆθος ἄπειρον ἐς ἄποψιν. τοῦ ὦν δὴ πεδίου τούτου τοῦ μεγάλου οὐκ ἐλαχίστην μοῖραν μετέχουσι οἱ Μασσαγέται, ἐπ’ οὓς ὁ Κῦρος ἔσχε προθυμίην στρατεύσασθαι. πολλά τε γάρ μιν καὶ μεγάλα τὰ ἐπαείροντα καὶ ἐποτρύνοντα ἦν, πρῶτον μὲν ἡ γένεσις, τὸ δοκέειν πλέον τι εἶναι ἀνθρώπου, δευτέρα δὲ ἡ εὐτυχίη ἡ κατὰ τοὺς πολέμους γενομένη· ὅκῃ γὰρ ἰθύσειε στρατεύεσθαι Κῦρος, ἀμήχανον ἦν ἐκεῖνο τὸ ἔθνος διαφυγεῖν.", "st": "1.204"}, {"sp": "N", "t": "ἦν δὲ τοῦ ἀνδρὸς ἀποθανόντος γυνὴ τῶν Μασσαγετέων βασίλεια. Τόμυρίς οἱ ἦν οὔνομα. ταύτην πέμπων ὁ Κῦρος ἐμνᾶτο τῷ λόγῳ θέλων γυναῖκα ἣν ἔχειν. ἡ δὲ Τόμυρις συνιεῖσα οὐκ αὐτήν μιν μνώμενον ἀλλὰ τὴν Μασαγετέων βασιληίην, ἀπείπατο τὴν πρόσοδον. Κῦρος δὲ μετὰ τοῦτο, ὥς οἱ δόλῳ οὐ προεχώρεε, ἐλάσας ἐπὶ τὸν Ἀράξεα ἐποιέετο ἐκ τοῦ ἐμφανέος ἐπὶ τοὺς Μασσαγέτας στρατηίην, γεφύρας τε ζευγνύων ἐπὶ τοῦ ποταμοῦ διάβασιν τῷ στρατῷ, καὶ πύργους ἐπὶ πλοίων τῶν διαπορθμευόντων τὸν ποταμὸν οἰκοδομεόμενος.", "st": "1.205"}, {"sp": "N", "t": "ἔχοντι δέ οἱ τοῦτον τὸν πόνον πέμψασα ἡ Τόμυρις κήρυκα ἔλεγε τάδε. ὦ βασιλεῦ Μήδων, παῦσαι σπεύδων τὰ σπεύδεις· οὐ γὰρ ἂν εἰδείης εἴ τοι ἐς καιρὸν ἔσται ταῦτα τελεόμενα· παυσάμενος δὲ βασίλευε τῶν σεωυτοῦ, καὶ ἡμέας ἀνέχευ ὁρέων ἄρχοντας τῶν περ ἄρχομεν. οὔκων ἐθελήσεις ὑποθήκῃσι τῇσιδε χρᾶσθαι, ἀλλὰ πάντως μᾶλλον ἢ δι’ ἡσυχίης εἶναι· σὺ δὴ εἰ μεγάλως προθυμέαι Μασσαγετέων πειρηθῆναι, φέρε μόχθον μὲν τὸν ἔχεις ζευγνὺς τὸν ποταμὸν ἄπες, σὺ δὲ ἡμέων ἀναχωρησάντων ἀπὸ τοῦ ποταμοῦ τριῶν ἡμερέων ὁδὸν διάβαινε ἐς τὴν ἡμετέρην· εἰ δ’ ἡμέας βούλεαι ἐσδέξασθαι μᾶλλον ἐς τὴν ὑμετέρην, σὺ τὠυτὸ τοῦτο ποίεε. ταῦτα δὲ ἀκούσας ὁ Κῦρος συνεκάλεσε Περσέων τοὺς πρώτους, συναγείρας δὲ τούτους ἐς μέσον σφι προετίθεε τὸ πρῆγμα, συμβουλευόμενος ὁκότερα ποιέῃ. τῶν δὲ κατὰ τὠυτὸ αἱ γνῶμαι συνεξέπιπτον κελευόντων ἐσδέκεσθαι Τόμυρίν τε καὶ τὸν στρατὸν αὐτῆς ἐς τὴν χώρην.", "st": "1.206"}, {"sp": "N", "t": "παρεὼν δὲ καὶ μεμφόμενος τὴν γνώμην ταύτην Κροῖσος ὁ Λυδὸς ἀπεδείκνυτο ἐναντίην τῇ προκειμένῃ γνώμῃ, λέγων τάδε. ὦ βασιλεῦ, εἶπον μὲν καὶ πρότερόν τοι ὅτι ἐπεί με Ζεὺς ἔδωκέ τοι, τὸ ἂν ὁρῶ σφάλμα ἐὸν οἴκῳ τῷ σῷ κατὰ δύναμιν ἀποτρέψειν· τὰ δὲ μοι παθήματα ἐόντα ἀχάριτα μαθήματα γέγονε. εἰ μὲν ἀθάνατος δοκέεις εἶναι καὶ στρατιῆς τοιαύτης ἄρχειν, οὐδὲν ἂν εἴη πρῆγμα γνώμας ἐμὲ σοὶ ἀποφαίνεσθαι· εἰ δ’ ἔγνωκας ὅτι ἄνθρωπος καὶ σὺ εἶς καὶ ἑτέρων τοιῶνδε ἄρχεις, ἐκεῖνο πρῶτον μάθε, ὡς κύκλος τῶν ἀνθρωπηίων ἐστὶ πρηγμάτων, περιφερόμενος δὲ οὐκ ἐᾷ αἰεὶ τοὺς αὐτοὺς εὐτυχέειν. ἤδη ὦν ἔχω γνώμην περὶ τοῦ προκειμένου πρήγματος τὰ ἔμπαλιν ἢ οὗτοι. εἰ γὰρ ἐθελήσομεν ἐσδέξασθαι τοὺς πολεμίους ἐς τὴν χώρην, ὅδε τοι ἐν αὐτῷ κίνδυνος ἔνι· ἑσσωθεὶς μὲν προσαπολλύεις πᾶσαν τὴν ἀρχήν. δῆλα γὰρ δὴ ὅτι νικῶντες Μασσαγέται οὐ τὸ ὀπίσω φεύξονται ἀλλ’ ἐπ’ ἀρχὰς τὰς σὰς ἐλῶσι. νικῶν δὲ οὐ νικᾷς τοσοῦτον ὅσον εἰ διαβὰς ἐς τὴν ἐκείνων, νικῶν Μασσαγέτας, ἕποιο φεύγουσι. τὠυτὸ γὰρ ἀντιθήσω ἐκείνῳ, ὅτι νικήσας τοὺς ἀντιουμένους ἐλᾷς ἰθὺ τῆς ἀρχῆς τῆς Τομύριος. χωρίς τε τοῦ ἀπηγημένου αἰσχρὸν καὶ οὐκ ἀνασχετὸν Κῦρόν γε τὸν Καμβύσεω γυναικὶ εἴξαντα ὑποχωρῆσαι τῆς χώρης. νῦν ὦν μοι δοκέει διαβάντας προελθεῖν ὅσον ἂν ἐκεῖνοι ὑπεξίωσι, ἐνθεῦτεν δὲ τάδε ποιεῦντας πειρᾶσθαι ἐκείνων περιγενέσθαι. ὡς γὰρ ἐγὼ πυνθάνομαι, Μασσαγέται εἰσὶ ἀγαθῶν τε Περσικῶν ἄπειροι καὶ καλῶν μεγάλων ἀπαθέες. τούτοισι ὦν τοῖσι ἀνδράσι τῶν προβάτων ἀφειδέως πολλὰ κατακόψαντας καὶ σκευάσαντας προθεῖναι ἐν τῷ στρατοπέδῳ τῷ ἡμετέρῳ δαῖτα, πρὸς δὲ καὶ κρητῆρας ἀφειδέως οἴνου ἀκρήτου καὶ σιτία παντοῖα· ποιήσαντας δὲ ταῦτα, ὑπολιπομένους τῆς στρατιῆς τὸ φλαυρότατον, τοὺς λοιποὺς αὖτις ἐξαναχωρέειν ἐπὶ τὸν ποταμόν. ἢν γὰρ ἐγὼ γνώμης μὴ ἁμάρτω, κεῖνοι ἰδόμενοι ἀγαθὰ πολλὰ τρέψονταί τε πρὸς αὐτὰ καὶ ἡμῖν τὸ ἐνθεῦτεν λείπεται ἀπόδεξις ἔργων μεγάλων.", "st": "1.207"}, {"sp": "N", "t": "γνῶμαι μὲν αὗται συνέστασαν· Κῦρος δὲ μετεὶς τὴν προτέρην γνώμην, τὴν Κροίσου δὲ ἑλόμενος, προηγόρευε Τομύρι ἐξαναχωρέειν ὡς αὐτοῦ διαβησομένου ἐπ’ ἐκείνην. ἣ μὲν δὴ ἐξανεχώρεε κατὰ ὑπέσχετο πρῶτα· Κῦρος δὲ Κροῖσον ἐς τὰς χεῖρας ἐσθεὶς τῷ ἑωυτοῦ παιδὶ Καμβύσῃ, τῷ περ τὴν βασιληίην ἐδίδου, καὶ πολλὰ ἐντειλάμενός οἱ τιμᾶν τε αὐτὸν καὶ εὖ ποιέειν, ἢν ἡ διάβασις ἡ ἐπὶ Μασσαγέτας μὴ ὀρθωθῇ, ταῦτα ἐντειλάμενος καὶ ἀποστείλας τούτους ἐς Πέρσας, αὐτὸς διέβαινε τὸν ποταμὸν καὶ ὁ στρατὸς αὐτοῦ.", "st": "1.208"}, {"sp": "N", "t": "ἐπείτε δὲ ἐπεραιώθη τὸν Ἀράξεα, νυκτὸς ἐπελθούσης εἶδε ὄψιν εὕδων ἐν τῶν Μασσαγετέων τῇ χωρῇ τοιήνδε· ἐδόκεε ὁ Κῦρος ἐν τῷ ὕπνῳ ὁρᾶν τῶν Ὑστάσπεος παίδων τὸν πρεσβύτατον ἔχοντα ἐπὶ τῶν ὤμων πτέρυγας καὶ τουτέων τῇ μὲν τὴν Ἀσίην τῇ δὲ τὴν Εὐρώπην ἐπισκιάζειν. Ὑστάσπεϊ δὲ τῷ Ἀρσάμεος ἐόντι ἀνδρὶ Ἀχαιμενίδῃ ἦν τῶν παίδων Δαρεῖος πρεσβύτατος, ἐὼν τότε ἡλικίην ἐς εἴκοσί κου μάλιστα ἔτεα, καὶ οὗτος κατελέλειπτο ἐν Πέρσῃσι· οὐ γὰρ εἶχέ κω ἡλικίην στρατεύεσθαι. ἐπεὶ ὦν δὴ ἐξηγέρθη ὁ Κῦρος, ἐδίδου λόγον ἑωυτῷ περὶ τῆς ὄψιος. ὡς δέ οἱ ἐδόκεε μεγάλη εἶναι ἡ ὄψις, καλέσας Ὑστάσπεα καὶ ἀπολαβὼν μοῦνον εἶπε Ὕστασπες, παῖς σὸς ἐπιβουλεύων ἐμοί τε καὶ τῇ ἐμῇ ἀρχῇ ἑάλωκε. ὡς δὲ ταῦτα ἀτρεκέως οἶδα, ἐγὼ σημανέω· ἐμεῦ θεοὶ κήδονται καί μοι πάντα προδεικνύουσι τὰ ἐπιφερόμενα. ἤδη ὦν ἐν τῇ παροιχομένῃ νυκτὶ εὕδων εἶδον τῶν σῶν παίδων τὸν πρεσβύτατον ἔχοντα ἐπὶ τῶν ὤμων πτέρυγας καὶ τουτέων τῇ μὲν τὴν Ἀσίην τῇ δὲ τὴν Εὐρώπην ἐπισκιάζειν. οὔκων ἐστὶ μηχανὴ ἀπὸ τῆς ὄψιος ταύτης οὐδεμία τὸ μὴ ἐκεῖνον ἐπιβουλεύειν ἐμοί· σύ νυν τὴν ταχίστην πορεύεο ὀπίσω ἐς Πέρσας καὶ ποίεε ὅκως, ἐπεὰν ἐγὼ τάδε καταστρεψάμενος ἔλθω ἐκεῖ, ὥς μοι καταστήσεις τὸν παῖδα ἐς ἔλεγχον.", "st": "1.209"}, {"sp": "N", "t": "Κῦρος μὲν δοκέων οἱ Δαρεῖον ἐπιβουλεύειν ἔλεγε τάδε· τῷ δὲ ὁ δαίμων προέφαινε ὡς αὐτὸς μὲν τελευτήσειν αὐτοῦ ταύτῃ μέλλοι, ἡ δὲ βασιληίη αὐτοῦ περιχωρέοι ἐς Δαρεῖον. ἀμείβεται δὴ ὦν ὁ Ὑστάσπης τοῖσιδε. ὦ βασιλεῦ, μὴ εἴη ἀνὴρ Πέρσης γεγονὼς ὅστις τοὶ ἐπιβουλεύσειε, εἰ δ’ ἐστί, ἀπόλοιτο ὡς τάχιστα· ὃς ἀντὶ μὲν δούλων ἐποίησας ἐλευθέρους Πέρσας εἶναι, ἀντὶ δὲ ἄρχεσθαι ὑπ’ ἄλλων ἄρχειν ἁπάντων. εἰ δέ τις τοὶ ὄψις ἀπαγγέλλει παῖδα τὸν ἐμὸν νεώτερα βουλεύειν περὶ σέο, ἐγώ τοι παραδίδωμι χρᾶσθαι αὐτῷ τοῦτο ὅ τι σὺ βούλεαι.", "st": "1.210"}, {"sp": "N", "t": "Ὑστάσπης μὲν τούτοισι ἀμειψάμενος καὶ διαβὰς τὸν Ἀράξεα ἤιε ἐς Πέρσας φυλάξων Κύρῳ τὸν παῖδα Δαρεῖον, Κῦρος δὲ προελθὼν ἀπὸ τοῦ Ἀράξεω ἡμέρης ὁδὸν ἐποίεε κατὰ τὰς Κροίσου ὑποθήκας. μετὰ δὲ ταῦτα Κύρου τε καὶ Περσέων τοῦ καθαροῦ στρατοῦ ἀπελάσαντος ὀπίσω ἐπὶ τὸν Ἀράξεα, λειφθέντος δὲ τοῦ ἀχρηίου, ἐπελθοῦσα τῶν Μασσαγετέων τριτημορὶς τοῦ στρατοῦ τούς τε λειφθέντας τῆς Κύρου στρατιῆς ἐφόνευε ἀλεξομένους καὶ τὴν προκειμένην ἰδόντες δαῖτα, ὡς ἐχειρώσαντο τοὺς ἐναντίους, κλιθέντες ἐδαίνυντο, πληρωθέντες δὲ φορβῆς καὶ οἴνου ηὗδον. οἱ δὲ Πέρσαι ἐπελθόντες πολλοὺς μὲν σφέων ἐφόνευσαν, πολλῷ δ’ ἔτι πλεῦνας ἐζώγρησαν καὶ ἄλλους καὶ τὸν τῆς βασιλείης Τομύριος παῖδα στρατηγέοντα Μασσαγετέων, τῷ οὔνομα ἦν Σπαργαπίσης.", "st": "1.211"}, {"sp": "N", "t": "ἣ δὲ πυθομένη τά τε περὶ τὴν στρατιὴν γεγονότα καὶ τὰ περὶ τὸν παῖδα, πέμπουσα κήρυκα παρὰ Κῦρον ἔλεγε τάδε. ἄπληστε αἵματος Κῦρε, μηδὲν ἐπαερθῇς τῷ γεγονότι τῷδε πρήγματι, εἰ ἀμπελίνῳ καρπῷ, τῷ περ αὐτοὶ ἐμπιπλάμενοι μαίνεσθε οὕτω ὥστε κατιόντος τοῦ οἴνου ἐς τὸ σῶμα ἐπαναπλέειν ὑμῖν ἔπεα κακά, τοιούτῳ φαρμάκῳ δολώσας ἐκράτησας παιδὸς τοῦ ἐμοῦ, ἀλλ’ οὐ μάχῃ κατὰ τὸ καρτερόν. νῦν ὦν μευ εὖ παραινεούσης ὑπόλαβε τὸν λόγον· ἀποδούς μοι τὸν παῖδα ἄπιθι ἐκ τῆσδε τῆς χώρης ἀζήμιος, Μασσαγετέων τριτημορίδι τοῦ στρατοῦ κατυβρίσας. εἰ δὲ ταῦτα οὐ ποιήσεις, ἥλιον ἐπόμνυμί τοι τὸν Μασσαγετέων δεσπότην, ἦ μέν σε ἐγὼ καὶ ἄπληστον ἐόντα αἵματος κορέσω.", "st": "1.212"}, {"sp": "N", "t": "Κῦρος μὲν ἐπέων οὐδένα τούτων ἀνενειχθέντων ἐποιέετο λόγον· ὁ δὲ τῆς βασιλείης Τομύριος παῖς Σπαργαπίσης, ὥς μιν ὅ τε οἶνος ἀνῆκε καὶ ἔμαθε ἵνα ἦν κακοῦ, δεηθεὶς Κύρου ἐκ τῶν δεσμῶν λυθῆναι ἔτυχε, ὡς δὲ ἐλύθη τε τάχιστα καὶ τῶν χειρῶν ἐκράτησε, διεργάζεται ἑωυτόν.", "st": "1.213"}, {"sp": "N", "t": "καὶ δὴ οὗτος μὲν τρόπῳ τοιούτῳ τελευτᾷ· Τόμυρις δέ, ὥς οἱ Κῦρος οὐκ ἐσήκουσε, συλλέξασα πᾶσαν τὴν ἑωυτῆς δύναμιν συνέβαλε Κύρῳ. ταύτην τὴν μάχην, ὅσαι δὴ βαρβάρων ἀνδρῶν μάχαι ἐγένοντο, κρίνω ἰσχυροτάτην γενέσθαι, καὶ δὴ καὶ πυνθάνομαι οὕτω τοῦτο γενόμενον. πρῶτα μὲν γὰρ λέγεται αὐτοὺς διαστάντας ἐς ἀλλήλους τοξεύειν, μετὰ δὲ ὥς σφι τὰ βέλεα ἐξετετόξευτο, συμπεσόντας τῇσι αἰχμῇσί τε καὶ τοῖσι ἐγχειριδίοισι συνέχεσθαι. χρόνον τε δὴ ἐπὶ πολλὸν συνεστάναι μαχομένους καὶ οὐδετέρους ἐθέλειν φεύγειν. τέλος δὲ οἱ Μασσαγέται περιεγένοντο, ἥ τε δὴ πολλὴ τῆς Περσικῆς στρατιῆς αὐτοῦ ταύτῃ διεφθάρη καὶ δὴ καὶ αὐτὸς Κῦρος τελευτᾷ, βασιλεύσας τὰ πάντα ἑνὸς δέοντα τριήκοντα ἔτεα. ἀσκὸν δὲ πλήσασα αἵματος ἀνθρωπηίου Τόμυρις ἐδίζητο ἐν τοῖσι τεθνεῶσι τῶν Περσέων τὸν Κύρου νέκυν, ὡς δὲ εὗρε, ἐναπῆκε αὐτοῦ τὴν κεφαλὴν ἐς τὸν ἀσκόν, λυμαινομένη δὲ τῷ νεκρῷ ἐπέλεγε τάδε· σὺ μὲν ἐμὲ ζῶσάν τε καὶ νικῶσάν σε μάχῃ ἀπώλεσας, παῖδα τὸν ἐμὸν ἑλὼν δόλῳ· σὲ δ’ ἐγώ, κατά περ ἠπείλησα, αἵματος κορέσω. τὰ μὲν δὴ κατὰ τὴν Κύρου τελευτὴν τοῦ βίου, πολλῶν λόγων λεγομένων, ὅδε μοι ὁ πιθανώτατος εἴρηται.", "st": "1.214"}, {"sp": "N", "t": "Μασσαγέται δὲ ἐσθῆτά τε ὁμοίην τῇ Σκυθικῇ φορέουσι καὶ δίαιταν ἔχουσι, ἱππόται δὲ εἰσὶ καὶ ἄνιπποι (ἀμφοτέρων γὰρ μετέχουσι) καὶ τοξόται τε καὶ αἰχμοφόροι, σαγάρις νομίζοντες ἔχειν. χρυσῷ δὲ καὶ χαλκῷ τὰ πάντα χρέωνται· ὅσα μὲν γὰρ ἐς αἰχμὰς καὶ ἄρδις καὶ σαγάρις, χαλκῷ τὰ πάντα χρέωνται, ὅσα δὲ περὶ κεφαλὴν καὶ ζωστῆρας καὶ μασχαλιστῆρας, χρυσῷ κοσμέονται. ὣς δ’ αὕτως τῶν ἵππων τὰ μὲν περὶ τὰ στέρνα χαλκέους θώρηκας περιβάλλουσι, τὰ δὲ περὶ τοὺς χαλινοὺς καὶ στόμια καὶ φάλαρα χρυσῷ. σιδήρῳ δὲ οὐδ’ ἀργύρῳ χρέωνται οὐδέν· οὐδὲ γὰρ οὐδέ σφι ἐστὶ ἐν τῇ χωρῇ, ὁ δὲ χρυσὸς καὶ ὁ χαλκὸς ἄπλετος.", "st": "1.215"}, {"sp": "N", "t": "νόμοισι δὲ χρέωνται τοιοῖσιδε. γυναῖκα μὲν γαμέει ἕκαστος, ταύτῃσι δὲ ἐπίκοινα χρέωνται· τὸ γὰρ Σκύθας φασὶ Ἕλληνες ποιέειν, οὐ Σκύθαι εἰσὶ οἱ ποιέοντες ἀλλὰ Μασσαγέται· τῆς γὰρ ἐπιθυμήσῃ γυναικὸς Μασσαγέτης ἀνήρ, τὸν φαρετρεῶνα ἀποκρεμάσας πρὸ τῆς ἁμάξης μίσγεται ἀδεῶς. οὖρος δὲ ἡλικίης σφι πρόκειται ἄλλος μὲν οὐδείς· ἐπεὰν δὲ γέρων γένηται κάρτα, οἱ προσήκοντές οἱ πάντες συνελθόντες θύουσί μιν καὶ ἄλλα πρόβατα ἅμα αὐτῷ, ἑψήσαντες δὲ τὰ κρέα κατευωχέονται. ταῦτα μὲν τὰ ὀλβιώτατά σφι νενόμισται, τὸν δὲ νούσῳ τελευτήσαντα οὐ κατασιτέονται ἀλλ’ γῇ κρύπτουσι, συμφορὴν ποιεύμενοι ὅτι οὐκ ἵκετο ἐς τὸ τυθῆναι. σπείρουσι δὲ οὐδέν, ἀλλ’ ἀπὸ κτηνέων ζώουσι καὶ ἰχθύων· οἳ δὲ ἄφθονοί σφι ἐκ τοῦ Ἀράξεω ποταμοῦ παραγίνονται· γαλακτοπόται δ’ εἰσί. θεῶν δὲ μοῦνον ἥλιον σέβονται, τῷ θύουσι ἵππους. νόος δὲ οὗτος τῆς θυσίης· τῶν θεῶν τῷ ταχίστῳ πάντων τῶν θνητῶν τὸ τάχιστον δατέονται.", "st": "1.216"}, {"sp": "HDR", "t": "Ἱστοριῶν Β· Εὐτέρπη", "st": "2"}, {"sp": "N", "t": "τελευτήσαντος δὲ Κύρου παρέλαβε τὴν βασιληίην Καμβύσης, Κύρου ἐὼν παῖς καὶ Κασσανδάνης τῆς Φαρνάσπεω θυγατρός, τῆς προαποθανούσης Κῦρος αὐτός τε μέγα πένθος ἐποιήσατο καὶ τοῖσι ἄλλοισι προεῖπε πᾶσι τῶν ἦρχε πένθος ποιέεσθαι. ταύτης δὴ τῆς γυναικὸς ἐὼν παῖς καὶ Κύρου Καμβύσης Ἴωνας μὲν καὶ Αἰολέας ὡς δούλους πατρωίους ἐόντας ἐνόμιζε, ἐπὶ δὲ Αἴγυπτον ἐποιέετο στρατηλασίην ἄλλους τε παραλαβὼν τῶν ἦρχε καὶ δὴ καὶ Ἑλλήνων τῶν ἐπεκράτεε.", "st": "2.1"}, {"sp": "N", "t": "οἱ δὲ Αἰγύπτιοι, πρὶν μὲν ἢ Ψαμμήτιχον σφέων βασιλεῦσαι, ἐνόμιζον ἑωυτοὺς πρώτους γενέσθαι πάντων ἀνθρώπων· ἐπειδὴ δὲ Ψαμμήτιχος βασιλεύσας ἠθέλησε εἰδέναι οἵτινες γενοίατο πρῶτοι, ἀπὸ τούτου νομίζουσι Φρύγας προτέρους γενέσθαι ἑωυτῶν, τῶν δὲ ἄλλων ἑωυτούς. Ψαμμήτιχος δὲ ὡς οὐκ ἐδύνατο πυνθανόμενος πόρον οὐδένα τούτου ἀνευρεῖν, οἳ γενοίατο πρῶτοι ἀνθρώπων, ἐπιτεχνᾶται τοιόνδε. παιδία δύο νεογνὰ ἀνθρώπων τῶν ἐπιτυχόντων δίδωσι ποιμένι τρέφειν ἐς τὰ ποίμνια τροφήν τινα τοιήνδε, ἐντειλάμενος μηδένα ἀντίον αὐτῶν μηδεμίαν φωνὴν ἱέναι, ἐν στέγῃ δὲ ἐρήμῃ ἐπ’ ἑωυτῶν κέεσθαι αὐτά, καὶ τὴν ὥρην ἐπαγινέειν σφι αἶγας, πλήσαντα δὲ γάλακτος τἆλλα διαπρήσσεσθαι· ταῦτα δὲ ἐποίεέ τε καὶ ἐνετέλλετο Ψαμμήτιχος θέλων ἀκοῦσαι τῶν παιδίων, ἀπαλλαχθέντων τῶν ἀσήμων κνυζημάτων, ἥντινα φωνὴν ῥήξουσι πρώτην· τά περ ὦν καὶ ἐγένετο. ὡς γὰρ διέτης χρόνος ἐγεγόνεε ταῦτα τῷ ποιμένι πρήσσοντι, ἀνοίγοντι τὴν θύρην καὶ ἐσιόντι τὰ παιδία ἀμφότερα προσπίπτοντα βεκὸς ἐφώνεον, ὀρέγοντα τὰς χεῖρας. τὰ μὲν δὴ πρῶτα ἀκούσας ἥσυχος ἦν ὁ ποιμήν· ὡς δὲ πολλάκις φοιτέοντι καὶ ἐπιμελομένῳ πολλὸν ἦν τοῦτο τὸ ἔπος, οὕτω δὴ σημήνας τῷ δεσπότῃ ἤγαγε τὰ παιδία κελεύσαντος ἐς ὄψιν τὴν ἐκείνου. ἀκούσας δὲ καὶ αὐτὸς ὁ Ψαμμήτιχος ἐπυνθάνετο οἵτινες ἀνθρώπων βεκός τι καλέουσι, πυνθανόμενος δὲ εὕρισκε Φρύγας καλέοντας τὸν ἄρτον. οὕτω συνεχώρησαν Αἰγύπτιοι καὶ τοιούτῳ σταθμησάμενοι πρήγματι τοὺς Φρύγας πρεσβυτέρους εἶναι ἑωυτῶν. ὧδε μὲν γενέσθαι τῶν ἱρέων τοῦ Ἡφαίστου τοῦ ἐν Μέμφι ἤκουον· Ἕλληνες δὲ λέγουσι ἄλλα τε μάταια πολλὰ καὶ ὡς γυναικῶν τὰς γλώσσας ὁ Ψαμμήτιχος ἐκταμὼν τὴν δίαιταν οὕτω ἐποιήσατο τῶν παίδων παρὰ ταύτῃσι τῇσι γυναιξί.", "st": "2.2"}, {"sp": "N", "t": "κατὰ μὲν δὴ τὴν τροφὴν τῶν παίδων τοσαῦτα ἔλεγον, ἤκουσα δὲ καὶ ἄλλα ἐν Μέμφι ἐλθὼν ἐς λόγους τοῖσι ἱρεῦσι τοῦ Ἡφαίστου. καὶ δὴ καὶ ἐς Θήβας τε καὶ ἐς Ἡλίου πόλιν αὐτῶν τούτων εἵνεκεν ἐτραπόμην, ἐθέλων εἰδέναι εἰ συμβήσονται τοῖσι λόγοισι τοῖσι ἐν Μέμφι·", "st": "2.3"}, {"sp": "N", "t": "οἱ γὰρ Ἡλιοπολῖται λέγονται Αἰγυπτίων εἶναι λογιώτατοι. τὰ μέν νυν θεῖα τῶν ἀπηγημάτων οἷα ἤκουον οὐκ εἰμὶ πρόθυμος ἐξηγέεσθαι, ἔξω ἢ τὰ οὐνόματα αὐτῶν μοῦνον, νομίζων πάντας ἀνθρώπους ἴσον περὶ αὐτῶν ἐπίστασθαι· τὰ δ’ ἂν ἐπιμνησθέω αὐτῶν, ὑπὸ τοῦ λόγου ἐξαναγκαζόμενος ἐπιμνησθήσομαι.", "st": "2.3.2"}, {"sp": "N", "t": "ὅσα δὲ ἀνθρωπήια πρήγματα, ὧδε ἔλεγον ὁμολογέοντες σφίσι, πρώτους Αἰγυπτίους ἀνθρώπων ἁπάντων ἐξευρεῖν τὸν ἐνιαυτόν, δυώδεκα μέρεα δασαμένους τῶν ὡρέων ἐς αὐτόν· ταῦτα δὲ ἐξευρεῖν ἐκ τῶν ἀστέρων ἔλεγον· ἄγουσι δὲ τοσῷδε σοφώτερον Ἑλλήνων, ἐμοὶ δοκέειν, ὅσῳ Ἕλληνες μὲν διὰ τρίτου ἔτεος ἐμβόλιμον ἐπεμβάλλουσι τῶν ὡρέων εἵνεκεν, Αἰγύπτιοι δὲ τριηκοντημέρους ἄγοντες τοὺς δυώδεκα μῆνας ἐπάγουσι ἀνὰ πᾶν ἔτος πέντε ἡμέρας πάρεξ τοῦ ἀριθμοῦ, καί σφι ὁ κύκλος τῶν ὡρέων ἐς τὠυτὸ περιιὼν παραγίνεται. δυώδεκά τε θεῶν ἐπωνυμίας ἔλεγον πρώτους Αἰγυπτίους νομίσαι καὶ Ἕλληνας παρὰ σφέων ἀναλαβεῖν, βωμούς τε καὶ ἀγάλματα καὶ νηοὺς θεοῖσι ἀπονεῖμαι σφέας πρώτους καὶ ζῷα ἐν λίθοισι ἐγγλύψαι. καὶ τούτων μέν νυν τὰ πλέω ἔργῳ ἐδήλουν οὕτω γενόμενα. βασιλεῦσαι δὲ πρῶτον Αἰγύπτου ἄνθρωπον ἔλεγον Μῖνα· ἐπὶ τούτου, πλὴν τοῦ Θηβαϊκοῦ νομοῦ, πᾶσαν Αἴγυπτον εἶναι ἕλος, καὶ αὐτῆς εἶναι οὐδὲν ὑπερέχον τῶν νῦν ἔνερθε λίμνης τῆς Μοίριος ἐόντων, ἐς τὴν ἀνάπλοος ἀπὸ θαλάσσης ἑπτὰ ἡμερέων ἐστὶ ἀνὰ τὸν ποταμόν.", "st": "2.4"}, {"sp": "N", "t": "καὶ εὖ μοι ἐδόκεον λέγειν περὶ τῆς χώρης· δῆλα γὰρ δὴ καὶ μὴ προακούσαντι ἰδόντι δέ, ὅστις γε σύνεσιν ἔχει, ὅτι Αἴγυπτος, ἐς τὴν Ἕλληνες ναυτίλλονται, ἐστὶ Αἰγυπτίοισι ἐπίκτητός τε γῆ καὶ δῶρον τοῦ ποταμοῦ, καὶ τὰ κατύπερθε ἔτι τῆς λίμνης ταύτης μέχρι τριῶν ἡμερέων πλόου, τῆς πέρι ἐκεῖνοι οὐδὲν ἔτι τοιόνδε ἔλεγον, ἔστι δὲ ἕτερον τοιόνδε. Αἰγύπτου γὰρ φύσις ἐστὶ τῆς χώρης τοιήδε. πρῶτα μὲν προσπλέων ἔτι καὶ ἡμέρης δρόμον ἀπέχων ἀπὸ γῆς, κατεὶς καταπειρητηρίην πηλόν τε ἀνοίσεις καὶ ἐν ἕνδεκα ὀργυιῇσι ἔσεαι. τοῦτο μὲν ἐπὶ τοσοῦτο δηλοῖ πρόχυσιν τῆς γῆς ἐοῦσαν.", "st": "2.5"}, {"sp": "N", "t": "αὖτις δὲ αὐτῆς ἐστι Αἰγύπτου μῆκος τὸ παρὰ θάλασσαν ἑξήκοντα σχοῖνοι, κατὰ ἡμεῖς διαιρέομεν εἶναι Αἴγυπτον ἀπὸ τοῦ Πλινθινήτεω κόλπου μέχρι Σερβωνίδος λίμνης, παρ’ ἣν τὸ Κάσιον ὄρος τείνει· ταύτης ὦν ἄπο οἱ ἑξήκοντα σχοῖνοι εἰσί. ὅσοι μὲν γὰρ γεωπεῖναι εἰσὶ ἀνθρώπων, ὀργυιῇσι μεμετρήκασι τὴν χώρην, ὅσοι δὲ ἧσσον γεωπεῖναι, σταδίοισι, οἳ δὲ πολλὴν ἔχουσι, παρασάγγῃσι, οἳ δὲ ἄφθονον λίην, σχοίνοισι. δύναται δὲ ὁ παρασάγγης τριήκοντα στάδια, ὁ δὲ σχοῖνος, μέτρον ἐὸν Αἰγύπτιον, ἑξήκοντα στάδια.", "st": "2.6"}, {"sp": "N", "t": "οὕτω ἂν εἴησαν Αἰγύπτου στάδιοι ἑξακόσιοι καὶ τρισχίλιοι τὸ παρὰ θάλασσαν. ἐνθεῦτεν μὲν καὶ μέχρι Ἡλίου πόλιος ἐς τὴν μεσόγαιαν ἐστὶ εὐρέα Αἴγυπτος, ἐοῦσα πᾶσα ὑπτίη τε καὶ ἔνυδρος καὶ ἰλύς. ἔστι δὲ ὁδὸς ἐς Ἡλίου πόλιν ἀπὸ θαλάσσης ἄνω ἰόντι παραπλησίη τὸ μῆκος τῇ ἐξ Ἀθηνέων ὁδῷ τῇ ἀπὸ τῶν δυώδεκα θεῶν τοῦ βωμοῦ φερούσῃ ἔς τε Πῖσαν καὶ ἐπὶ τὸν νηὸν τοῦ Διὸς τοῦ Ὀλυμπίου. σμικρόν τι τὸ διάφορον εὕροι τις ἂν λογιζόμενος τῶν ὁδῶν τουτέων τὸ μὴ ἴσας μῆκος εἶναι, οὐ πλέον πεντεκαίδεκα σταδίων· ἡ μὲν γὰρ ἐς Πῖσαν ἐξ Ἀθηνέων καταδεῖ πεντεκαίδεκα σταδίων μὴ εἶναι πεντακοσίων καὶ χιλίων, ἡ δὲ ἐς Ἡλίου πόλιν ἀπὸ θαλάσσης πληροῖ ἐς τὸν ἀριθμὸν τοῦτον.", "st": "2.7"}, {"sp": "N", "t": "ἀπὸ δὲ Ἡλίου πόλιος ἄνω ἰόντι στεινή ἐστι Αἴγυπτος. τῇ μὲν γὰρ τῆς Ἀραβίης ὄρος παρατέταται, φέρον ἀπ’ ἄρκτου πρὸς μεσαμβρίην τε καὶ νότον, αἰεὶ ἄνω τεῖνον ἐς τὴν Ἐρυθρὴν καλεομένην θάλασσαν· ἐν τῷ αἱ λιθοτομίαι ἔνεισι αἱ ἐς τὰς πυραμίδας κατατμηθεῖσαι τὰς ἐν Μέμφι. ταύτῃ μὲν λῆγον ἀνακάμπτει ἐς τὰ εἴρηται τὸ ὄρος· τῇ δὲ αὐτὸ ἑωυτοῦ ἐστι μακρότατον, ὡς ἐγὼ ἐπυνθανόμην, δύο μηνῶν αὐτὸ εἶναι τῆς ὁδοῦ ἀπὸ ἠοῦς πρὸς ἑσπέρην, τὰ δὲ πρὸς τὴν ἠῶ λιβανωτοφόρα αὐτοῦ τὰ τέρματα εἶναι. τοῦτο μέν νυν τὸ ὄρος τοιοῦτο ἐστί, τὸ δὲ πρὸς Λιβύης τῆς Αἰγύπτου ὄρος ἄλλο πέτρινον τείνει, ἐν τῷ αἱ πυραμίδες ἔνεισι, ψάμμῳ κατειλυμένον, κατὰ τὸν αὐτὸν τρόπον καὶ τοῦ Ἀραβίου τὰ πρὸς μεσαμβρίην φέροντα. τὸ ὦν δὴ ἀπὸ Ἡλίου πόλιος οὐκέτι πολλὸν χωρίον ὡς εἶναι Αἰγύπτου, ἀλλ’ ὅσον τε ἡμερέων τεσσέρων καὶ δέκα ἀναπλόου ἐστὶ στεινὴ Αἴγυπτος, ἐοῦσα τῶν ὀρέων τῶν εἰρημένων τὸ μεταξὺ πεδιὰς μὲν γῆ, στάδιοι δὲ μάλιστα ἐδόκεόν μοι εἶναι, τῇ στεινότατον ἐστί, διηκοσίων οὐ πλέους ἐκ τοῦ Ἀραβίου ὄρεος ἐς τὸ Λιβυκὸν καλεόμενον. τὸ δ’ ἐνθεῦτεν αὖτις εὐρέα Αἴγυπτος ἐστί. πέφυκε μέν νυν ἡ χώρη αὕτη οὕτω.", "st": "2.8"}, {"sp": "N", "t": "ἀπὸ δὲ Ἡλίου πόλιος ἐς Θήβας ἐστὶ ἀνάπλοος ἐννέα ἡμερέων, στάδιοι δὲ τῆς ὁδοῦ ἑξήκοντα καὶ ὀκτακόσιοι καὶ τετρακισχίλιοι, σχοίνων ἑνὸς καὶ ὀγδώκοντα ἐόντων. οὗτοι συντιθέμενοι οἱ στάδιοι Αἰγύπτου τὸ μὲν παρὰ θάλασσαν ἤδη μοι καὶ πρότερον δεδήλωται ὅτι ἑξακοσίων τε ἐστὶ σταδίων καὶ τρισχιλίων, ὅσον δέ τι ἀπὸ θαλάσσης ἐς μεσόγαιαν μέχρι Θηβέων ἐστί, σημανέω· στάδιοι γὰρ εἰσὶ εἴκοσι καὶ ἑκατὸν καὶ ἑξακισχίλιοι. τὸ δὲ ἀπὸ Θηβέων ἐς Ἐλεφαντίνην καλεομένην πόλιν στάδιοι χίλιοι καὶ ὀκτακόσιοι εἰσί.", "st": "2.9"}, {"sp": "N", "t": "ταύτης ὦν τῆς χώρης τῆς εἰρημένης ἡ πολλή, κατά περ οἱ ἱρέες ἔλεγον, ἐδόκεε καὶ αὐτῷ μοι εἶναι ἐπίκτητος Αἰγυπτίοισι. τῶν γὰρ ὀρέων τῶν εἰρημένων τῶν ὑπὲρ Μέμφιν πόλιν κειμένων τὸ μεταξὺ ἐφαίνετό μοι εἶναι κοτὲ κόλπος θαλάσσης, ὥσπερ γε τὰ περὶ Ἴλιον καὶ Τευθρανίην καὶ Ἔφεσόν τε καὶ Μαιάνδρου πεδίον, ὥς γε εἶναι σμικρὰ ταῦτα μεγάλοισι συμβαλεῖν· τῶν γὰρ ταῦτα τὰ χωρία προσχωσάντων ποταμῶν ἑνὶ τῶν στομάτων τοῦ Νείλου, ἐόντος πενταστόμου, οὐδεὶς αὐτῶν πλήθεος πέρι ἄξιος συμβληθῆναι ἐστί. εἰσὶ δὲ καὶ ἄλλοι ποταμοί, οὐ κατὰ τὸν Νεῖλον ἐόντες μεγάθεα, οἵτινες ἔργα ἀποδεξάμενοι μεγάλα εἰσί· τῶν ἐγὼ φράσαι ἔχω οὐνόματα καὶ ἄλλων καὶ οὐκ ἥκιστα Ἀχελῴου, ὃς ῥέων δι’ Ἀκαρνανίης καὶ ἐξιεὶς ἐς θάλασσαν τῶν Ἐχινάδων νήσων τὰς ἡμισέας ἤδη ἤπειρον πεποίηκε.", "st": "2.10"}, {"sp": "N", "t": "ἔστι δὲ τῆς Ἀραβίης χώρης, Αἰγύπτου δὲ οὐ πρόσω, κόλπος θαλάσσης ἐσέχων ἐκ τῆς Ἐρυθρῆς καλεομένης θαλάσσης, μακρὸς οὕτω δή τι καὶ στεινὸς ὡς ἔρχομαι φράσων· μῆκος μὲν πλόου ἀρξαμένῳ ἐκ μυχοῦ διεκπλῶσαι ἐς τὴν εὐρέαν θάλασσαν ἡμέραι ἀναισιμοῦνται τεσσεράκοντα εἰρεσίῃ χρεωμένῳ· εὖρος δέ, τῇ εὐρύτατος ἐστὶ ὁ κόλπος, ἥμισυ ἡμέρης πλόου. ῥηχίη δ’ ἐν αὐτῷ καὶ ἄμπωτις ἀνὰ πᾶσαν ἡμέρην γίνεται. ἕτερον τοιοῦτον κόλπον καὶ τὴν Αἴγυπτον δοκέω γενέσθαι κοτέ, τὸν μὲν ἐκ τῆς βορηίης θαλάσσης κόλπον ἐσέχοντα ἐπ’ Αἰθιοπίης, τὸν δὲ Ἀράβιον, τὸν ἔρχομαι λέξων, ἐκ τῆς νοτίης φέροντα ἐπὶ Συρίης, σχεδὸν μὲν ἀλλήλοισι συντετραίνοντας τοὺς μυχούς, ὀλίγον δέ τι παραλλάσσοντας τῆς χώρης. εἰ ὦν ἐθελήσει ἐκτρέψαι τὸ ῥέεθρον ὁ Νεῖλος ἐς τοῦτον τὸν Ἀράβιον κόλπον, τί μιν κωλύει ῥέοντος τούτου ἐκχωσθῆναι ἐντός γε δισμυρίων ἐτέων; ἐγὼ μὲν γὰρ ἔλπομαί γε καὶ μυρίων ἐντὸς χωσθῆναι ἄν· κοῦ γε δὴ ἐν τῷ προαναισιμωμένῳ χρόνῳ πρότερον ἢ ἐμὲ γενέσθαι οὐκ ἂν χωσθείη κόλπος καὶ πολλῷ μέζων ἔτι τούτου ὑπὸ τοσούτου τε ποταμοῦ καὶ οὕτω ἐργατικοῦ;", "st": "2.11"}, {"sp": "N", "t": "τὰ περὶ Αἴγυπτον ὦν καὶ τοῖσι λέγουσι αὐτὰ πείθομαι καὶ αὐτὸς οὕτω κάρτα δοκέω εἶναι, ἰδών τε τὴν Αἴγυπτον προκειμένην τῆς ἐχομένης γῆς κογχύλιά τε φαινόμενα ἐπὶ τοῖσι ὄρεσι καὶ ἅλμην ἐπανθέουσαν, ὥστε καὶ τὰς πυραμίδας δηλέεσθαι, καὶ ψάμμον μοῦνον Αἰγύπτου ὄρος τοῦτο τὸ ὑπὲρ Μέμφιος ἔχον, πρὸς δὲ τῇ χώρῃ οὔτε τῇ Ἀραβίῃ προσούρῳ ἐούσῃ τὴν Αἴγυπτον προσεικέλην οὔτε τῇ Λιβύῃ, οὐ μὲν οὐδὲ τῇ Συρίῃ (τῆς γὰρ Ἀραβίης τὰ παρὰ θάλασσαν Σύροι νέμονται), ἀλλὰ μελάγγαιόν τε καὶ καταρρηγνυμένην, ὥστε ἐοῦσαν ἰλύν τε καὶ πρόχυσιν ἐξ Αἰθιοπίης κατενηνειγμένην ὑπὸ τοῦ ποταμοῦ. τὴν δὲ Λιβύην ἴδμεν ἐρυθροτέρην τε γῆν καὶ ὑποψαμμοτέρην, τὴν δὲ Ἀραβίην τε καὶ Συρίην ἀργιλωδεστέρην τε καὶ ὑπόπετρον ἐοῦσαν.", "st": "2.12"}, {"sp": "N", "t": "ἔλεγον δὲ καὶ τόδε μοι μέγα τεκμήριον περὶ τῆς χώρης ταύτης οἱ ἱρέες, ὡς ἐπὶ Μοίριος βασιλέος, ὅκως ἔλθοι ὁ ποταμὸς ἐπὶ ὀκτὼ πήχεας τὸ ἐλάχιστον, ἄρδεσκε Αἴγυπτον τὴν ἔνερθε Μέμφιος· καὶ Μοίρι οὔκω ἦν ἔτεα εἰνακόσια τετελευτηκότι ὅτε τῶν ἱρέων ταῦτα ἐγὼ ἤκουον. νῦν δὲ εἰ μὴ ἐπ’ ἑκκαίδεκα ἢ πεντεκαίδεκα πήχεας ἀναβῇ τὸ ἐλάχιστον ὁ ποταμός, οὐκ ὑπερβαίνει ἐς τὴν χώρην. δοκέουσί τέ μοι Αἰγυπτίων οἱ ἔνερθε λίμνης τῆς Μοίριος οἰκέοντες τά τε ἄλλα χωρία καὶ τὸ καλεόμενον Δέλτα, ἢν οὕτω ἡ χώρη αὕτη κατὰ λόγον ἐπιδιδῷ ἐς ὕψος καὶ τὸ ὅμοιον ἀποδιδῷ ἐς αὔξησιν, μὴ κατακλύζοντος αὐτὴν τοῦ Νείλου πείσεσθαι τὸν πάντα χρόνον τὸν ἐπίλοιπον Αἰγύπτιοι τὸ κοτὲ αὐτοὶ Ἕλληνας ἔφασαν πείσεσθαι. πυθόμενοι γὰρ ὡς ὕεται πᾶσα ἡ χώρη τῶν Ἑλλήνων ἀλλ’ οὐ ποταμοῖσι ἄρδεται κατά περ ἡ σφετέρη, ἔφασαν Ἕλληνας ψευσθέντας κοτὲ ἐλπίδος μεγάλης κακῶς πεινήσειν. τὸ δὲ ἔπος τοῦτο ἐθέλει λέγειν ὡς, εἰ μὴ ἐθελήσει σφι ὕειν ὁ θεὸς ἀλλὰ αὐχμῷ διαχρᾶσθαι, λιμῷ οἱ Ἕλληνες αἱρεθήσονται· οὐ γὰρ δή σφι ἐστὶ ὕδατος οὐδεμία ἄλλη ἀποστροφὴ ὅτι μὴ ἐκ τοῦ Διὸς μοῦνον.", "st": "2.13"}, {"sp": "N", "t": "καὶ ταῦτα μὲν ἐς Ἕλληνας Αἰγυπτίοισι ὀρθῶς ἔχοντα εἴρηται· φέρε δὲ νῦν καὶ αὐτοῖσι Αἰγυπτίοισι ὡς ἔχει φράσω· εἴ σφι θέλοι, ὡς καὶ πρότερον εἶπον, ἡ χώρη ἡ ἔνερθε Μέμφιος (αὕτη γὰρ ἐστὶ ἡ αὐξανομένη) κατὰ λόγον τοῦ παροιχομένου χρόνου ἐς ὕψος αὐξάνεσθαι, ἄλλο τι ἢ οἱ ταύτῃ οἰκέοντες Αἰγυπτίων πεινήσουσι; εἰ μήτε γε ὕσεταί σφι ἡ χώρη μήτε ὁ ποταμὸς οἷός τ’ ἔσται ἐς τὰς ἀρούρας ὑπερβαίνειν. ἦ γὰρ δὴ νῦν γε οὗτοι ἀπονητότατα καρπὸν κομίζονται ἐκ γῆς τῶν τε ἄλλων ἀνθρώπων πάντων καὶ τῶν λοιπῶν Αἰγυπτίων· οἳ οὔτε ἀρότρῳ ἀναρρηγνύντες αὔλακας ἔχουσι πόνους οὔτε σκάλλοντες οὔτε ἄλλο ἐργαζόμενοι οὐδὲν τῶν οἱ ἄλλοι ἄνθρωποι περὶ λήιον πονέουσι, ἀλλ’ ἐπεάν σφι ὁ ποταμὸς αὐτόματος ἐπελθὼν ἄρσῃ τὰς ἀρούρας, ἄρσας δὲ ἀπολίπῃ ὀπίσω, τότε σπείρας ἕκαστος τὴν ἑωυτοῦ ἄρουραν ἐσβάλλει ἐς αὐτὴν ὗς, ἐπεὰν δὲ καταπατήσῃ τῇσι ὑσὶ τὸ σπέρμα, ἄμητον τὸ ἀπὸ τούτου μένει, ἀποδινήσας δὲ τῇσι ὑσὶ τὸν σῖτον οὕτω κομίζεται.", "st": "2.14"}, {"sp": "N", "t": "εἰ ὦν βουλόμεθα γνώμῃσι τῇσι Ἰώνων χρᾶσθαι τὰ περὶ Αἴγυπτον, οἳ φασὶ τὸ Δέλτα μοῦνον εἶναι Αἴγυπτον, ἀπὸ Περσέος καλεομένης σκοπιῆς λέγοντες τὸ παρὰ θάλασσαν εἶναι αὐτῆς μέχρι Ταριχηίων τῶν Πηλουσιακῶν, τῇ δὴ τεσσεράκοντα εἰσὶ σχοῖνοι, τὸ δὲ ἀπὸ θαλάσσης λεγόντων ἐς μεσόγαιαν τείνειν αὐτὴν μέχρι Κερκασώρου πόλιος, κατ’ ἣν σχίζεται ὁ Νεῖλος ἔς τε Πηλούσιον ῥέων καὶ ἐς Κάνωβον, τὰ δὲ ἄλλα λεγόντων τῆς Αἰγύπτου τὰ μὲν Λιβύης τὰ δὲ Ἀραβίης εἶναι, ἀποδεικνύοιμεν ἂν τούτῳ τῷ λόγῳ χρεώμενοι Αἰγυπτίοισι οὐκ ἐοῦσαν πρότερον χώρην. ἤδη γάρ σφι τό γε Δέλτα, ὡς αὐτοὶ λέγουσι Αἰγύπτιοι καὶ ἐμοὶ δοκέει, ἐστὶ κατάρρυτόν τε καὶ νεωστὶ ὡς λόγῳ εἰπεῖν ἀναπεφηνός. εἰ τοίνυν σφι χώρη γε μηδεμία ὑπῆρχε, τί περιεργάζοντο δοκέοντες πρῶτοι ἀνθρώπων γεγονέναι; οὐδὲ ἔδει σφέας ἐς διάπειραν τῶν παιδίων ἰέναι, τίνα γλῶσσαν πρώτην ἀπήσουσι. ἀλλ’ οὔτε Αἰγυπτίους δοκέω ἅμα τῷ Δέλτα τῷ ὑπὸ Ἰώνων καλεομένῳ γενέσθαι αἰεί τε εἶναι ἐξ οὗ ἀνθρώπων γένος ἐγένετο, προϊούσης δὲ τῆς χώρης πολλοὺς μὲν τοὺς ὑπολειπομένους αὐτῶν γενέσθαι πολλοὺς δὲ τοὺς ὑποκαταβαίνοντας. τὸ δ’ ὦν πάλαι αἱ Θῆβαι Αἴγυπτος ἐκαλέετο, τῆς τὸ περίμετρον στάδιοι εἰσὶ εἴκοσι καὶ ἑκατὸν καὶ ἑξακισχίλιοι.", "st": "2.15"}, {"sp": "N", "t": "εἰ ὦν ἡμεῖς ὀρθῶς περὶ αὐτῶν γινώσκομεν, Ἴωνες οὐκ εὖ φρονέουσι περὶ Αἰγύπτου· εἰ δὲ ὀρθή ἐστι ἡ γνώμη τῶν Ἰώνων, Ἕλληνάς τε καὶ αὐτοὺς Ἴωνας ἀποδείκνυμι οὐκ ἐπισταμένους λογίζεσθαι, οἳ φασὶ τρία μόρια εἶναι γῆν πᾶσαν, Εὐρώπην τε καὶ Ἀσίην καὶ Λιβύην. τέταρτον γὰρ δή σφεας δεῖ προσλογίζεσθαι Αἰγύπτου τὸ Δέλτα, εἰ μήτε γε ἐστὶ τῆς Ἀσίης μήτε τῆς Λιβύης· οὐ γὰρ δὴ ὁ Νεῖλός γε ἐστὶ κατὰ τοῦτον τὸν λόγον ὁ τὴν Ἀσίην οὐρίζων τῇ Λιβύῃ, τοῦ Δέλτα δὲ τούτου κατὰ τὸ ὀξὺ περιρρήγνυται ὁ Νεῖλος, ὥστε ἐν τῷ μεταξὺ Ἀσίης τε καὶ Λιβύης γίνοιτ’ ἄν.", "st": "2.16"}, {"sp": "N", "t": "καὶ τὴν μὲν Ἰώνων γνώμην ἀπίεμεν, ἡμεῖς δὲ ὧδε καὶ περὶ τούτων λέγομεν, Αἴγυπτον μὲν πᾶσαν εἶναι ταύτην τὴν ὑπ’ Αἰγυπτίων οἰκεομένην κατά περ Κιλικίην τὴν ὑπὸ Κιλίκων καὶ Ἀσσυρίην τὴν ὑπὸ Ἀσσυρίων, οὔρισμα δὲ Ἀσίῃ καὶ Λιβύῃ οἴδαμεν οὐδὲν ἐὸν ὀρθῷ λόγῳ εἰ μὴ τοὺς Αἰγυπτίων οὔρους. εἰ δὲ τῷ ὑπ’ Ἑλλήνων νενομισμένῳ χρησόμεθα, νομιοῦμεν Αἴγυπτον πᾶσαν ἀρξαμένην ἀπὸ Καταδούπων τε καὶ Ἐλεφαντίνης πόλιος δίχα διαιρέεσθαι καὶ ἀμφοτερέων τῶν ἐπωνυμιέων ἔχεσθαι· τὰ μὲν γὰρ αὐτῆς εἶναι τῆς Λιβύης τὰ δὲ τῆς Ἀσίης. ὁ γὰρ δὴ Νεῖλος ἀρξάμενος ἐκ τῶν Καταδούπων ῥέει μέσην Αἴγυπτον σχίζων ἐς θάλασσαν. μέχρι μέν νυν Κερκασώρου πόλιος ῥέει εἷς ἐὼν ὁ Νεῖλος, τὸ δὲ ἀπὸ ταύτης τῆς πόλιος σχίζεται τριφασίας ὁδούς. καὶ ἣ μὲν πρὸς ἠῶ τρέπεται, τὸ καλέεται Πηλούσιον στόμα, ἡ δὲ ἑτέρη τῶν ὁδῶν πρὸς ἑσπέρην ἔχει· τοῦτο δὲ Κανωβικὸν στόμα κέκληται. ἡ δὲ δὴ ἰθέα τῶν ὁδῶν τῷ Νείλῳ ἐστὶ ἥδε· ἄνωθεν φερόμενος ἐς τὸ ὀξὺ τοῦ Δέλτα ἀπικνέεται, τὸ δὲ ἀπὸ τούτου σχίζων μέσον τὸ Δέλτα ἐς θάλασσαν ἐξιεῖ, οὔτε ἐλαχίστην μοῖραν τοῦ ὕδατος παρεχόμενος ταύτην οὔτε ἥκιστα ὀνομαστήν· τὸ καλέεται Σεβεννυτικὸν στόμα. ἔστι δὲ καὶ ἕτερα διφάσια στόματα ἀπὸ τοῦ Σεβεννυτικοῦ ἀποσχισθέντα, φέροντα ἐς θάλασσαν· τοῖσι οὐνόματα κέεται τάδε, τῷ μὲν Σαϊτικὸν αὐτῶν τῷ δὲ Μενδήσιον. τὸ δὲ Βολβίτινον στόμα καὶ τὸ Βουκολικὸν οὐκ ἰθαγενέα στόματα ἐστὶ ἀλλ’ ὀρυκτά.", "st": "2.17"}, {"sp": "N", "t": "μαρτυρέει δέ μοι τῇ γνώμῃ, ὅτι τοσαύτη ἐστὶ Αἴγυπτος ὅσην τινὰ ἐγὼ ἀποδείκνυμι τῷ λόγῳ, καὶ τὸ Ἄμμωνος χρηστήριον γενόμενον· τὸ ἐγὼ τῆς ἐμεωυτοῦ γνώμης ὕστερον περὶ Αἴγυπτον ἐπυθόμην. οἱ γὰρ δὴ ἐκ Μαρέης τε πόλιος καὶ Ἄπιος, οἰκέοντες Αἰγύπτου τὰ πρόσουρα Λιβύῃ, αὐτοί τε δοκέοντες εἶναι Λίβυες καὶ οὐκ Αἰγύπτιοι καὶ ἀχθόμενοι τῇ περὶ τὰ ἱρὰ θρησκηίῃ, βουλόμενοι θηλέων βοῶν μὴ ἔργεσθαι, ἔπεμψαν ἐς Ἄμμωνα φάμενοι οὐδὲν σφίσι τε καὶ Αἰγυπτίοισι κοινὸν εἶναι· οἰκέειν τε γὰρ ἔξω τοῦ Δέλτα καὶ οὐδὲν ὁμολογέειν αὐτοῖσι, βούλεσθαί τε πάντων σφίσι ἐξεῖναι γεύεσθαι. ὁ δὲ θεός σφεας οὐκ ἔα ποιέειν ταῦτα, φὰς Αἴγυπτον εἶναι ταύτην τὴν ὁ Νεῖλος ἐπιὼν ἄρδει, καὶ Αἰγυπτίους εἶναι τούτους οἳ ἔνερθε Ἐλεφαντίνης πόλιος οἰκέοντες ἀπὸ τοῦ ποταμοῦ τούτου πίνουσι. οὕτω σφι ταῦτα ἐχρήσθη.", "st": "2.18"}, {"sp": "N", "t": "ἐπέρχεται δὲ ὁ Νεῖλος, ἐπεὰν πληθύῃ, οὐ μοῦνον τὸ Δέλτα ἀλλὰ καὶ τοῦ Λιβυκοῦ τε λεγομένου χωρίου εἶναι καὶ τοῦ Ἀραβίου ἐνιαχῇ καὶ ἐπὶ δύο ἡμερέων ἑκατέρωθι ὁδόν, καὶ πλέον ἔτι τούτου καὶ ἔλασσον.", "st": "2.19"}, {"sp": "N", "t": "τοῦ ποταμοῦ δὲ φύσιος πέρι οὔτε τι τῶν ἱρέων οὔτε ἄλλου οὐδενὸς παραλαβεῖν ἐδυνάσθην. πρόθυμος δὲ ἔα τάδε παρ’ αὐτῶν πυθέσθαι, ὅ τι κατέρχεται μὲν ὁ Νεῖλος πληθύων ἀπὸ τροπέων τῶν θερινέων ἀρξάμενος ἐπὶ ἑκατὸν ἡμέρας, πελάσας δὲ ἐς τὸν ἀριθμὸν τουτέων τῶν ἡμερέων ὀπίσω ἀπέρχεται ἀπολείπων τὸ ῥέεθρον, ὥστε βραχὺς τὸν χειμῶνα ἅπαντα διατελέει ἐὼν μέχρι οὗ αὖτις τροπέων τῶν θερινέων. τούτων ὦν πέρι οὐδενὸς οὐδὲν οἷός τε ἐγενόμην παραλαβεῖν παρὰ τῶν Αἰγυπτίων, ἱστορέων αὐτοὺς ἥντινα δύναμιν ἔχει ὁ Νεῖλος τὰ ἔμπαλιν πεφυκέναι τῶν ἄλλων ποταμῶν· ταῦτά τε δὴ τὰ λελεγμένα βουλόμενος εἰδέναι ἱστόρεον καὶ ὅ τι αὔρας ἀποπνεούσας μοῦνος ποταμῶν πάντων οὐ παρέχεται.", "st": "2.19.2"}, {"sp": "N", "t": "ἀλλὰ Ἑλλήνων μὲν τινὲς ἐπίσημοι βουλόμενοι γενέσθαι σοφίην ἔλεξαν περὶ τοῦ ὕδατος τούτου τριφασίας ὁδούς· τῶν τὰς μὲν δύο τῶν ὁδῶν οὐδ’ ἀξιῶ μνησθῆναι εἰ μὴ ὅσον σημῆναι βουλόμενος μοῦνον· τῶν ἡ ἑτέρη μὲν λέγει τοὺς ἐτησίας ἀνέμους εἶναι αἰτίους πληθύειν τὸν ποταμόν, κωλύοντας ἐς θάλασσαν ἐκρέειν τὸν Νεῖλον. πολλάκις δὲ ἐτησίαι μὲν οὔκων ἔπνευσαν, ὁ δὲ Νεῖλος τὠυτὸ ἐργάζεται. πρὸς δέ, εἰ ἐτησίαι αἴτιοι ἦσαν, χρῆν καὶ τοὺς ἄλλους ποταμούς, ὅσοι τοῖσι ἐτησίῃσι ἀντίοι ῥέουσι, ὁμοίως πάσχειν καὶ κατὰ τὰ αὐτὰ τῷ Νείλῳ, καὶ μᾶλλον ἔτι τοσούτῳ ὅσῳ ἐλάσσονες ἐόντες ἀσθενέστερα τὰ ῥεύματα παρέχονται. εἰσὶ δὲ πολλοὶ μὲν ἐν τῇ Συρίῃ ποταμοὶ πολλοὶ δὲ ἐν τῇ Λιβύῃ, οἳ οὐδὲν τοιοῦτο πάσχουσι οἷόν τι καὶ ὁ Νεῖλος.", "st": "2.20"}, {"sp": "N", "t": "ἡ δ’ ἑτέρη ἀνεπιστημονεστέρη μὲν ἐστὶ τῆς λελεγμένης, λόγῳ δὲ εἰπεῖν θωμασιωτέρη· ἣ λέγει ἀπὸ τοῦ Ὠκεανοῦ ῥέοντα αὐτὸν ταῦτα μηχανᾶσθαι, τὸν δὲ Ὠκεανὸν γῆν περὶ πᾶσαν ῥέειν.", "st": "2.21"}, {"sp": "N", "t": "ἡ δὲ τρίτη τῶν ὁδῶν πολλὸν ἐπιεικεστάτη ἐοῦσα μάλιστα ἔψευσται· λέγει γὰρ δὴ οὐδ’ αὕτη οὐδέν, φαμένη τὸν Νεῖλον ῥέειν ἀπὸ τηκομένης χιόνος· ὃς ῥέει μὲν ἐκ Λιβύης διὰ μέσων Αἰθιόπων, ἐκδιδοῖ δὲ ἐς Αἴγυπτον. κῶς ὦν δῆτα ῥέοι ἂν ἀπὸ χιόνος, ἀπὸ τῶν θερμοτάτων ῥέων ἐς τὰ ψυχρότερα τὰ πολλά ἐστι; ἀνδρί γε λογίζεσθαι τοιούτων πέρι οἵῳ τε ἐόντι, ὡς οὐδὲ οἰκὸς ἀπὸ χιόνος μιν ῥέειν, πρῶτον μὲν καὶ μέγιστον μαρτύριον οἱ ἄνεμοι παρέχονται πνέοντες ἀπὸ τῶν χωρέων τουτέων θερμοί· δεύτερον δὲ ὅτι ἄνομβρος ἡ χώρη καὶ ἀκρύσταλλος διατελέει ἐοῦσα, ἐπὶ δὲ χιόνι πεσούσῃ πᾶσα ἀνάγκη ἐστὶ ὗσαι ἐν πέντε ἡμέρῃσι, ὥστε, εἰ ἐχιόνιζε, ὕετο ἂν ταῦτα τὰ χωρία· τρίτα δὲ οἱ ἄνθρωποι ὑπὸ τοῦ καύματος μέλανες ἐόντες. ἰκτῖνοι δὲ καὶ χελιδόνες δι’ ἔτεος ἐόντες οὐκ ἀπολείπουσι, γέρανοι δὲ φεύγουσαι τὸν χειμῶνα τὸν ἐν τῇ Σκυθικῇ χώρῃ γινόμενον φοιτῶσι ἐς χειμασίην ἐς τοὺς τόπους τούτους. εἰ τοίνυν ἐχιόνιζε καὶ ὅσον ὦν ταύτην τὴν χώρην δι’ ἧς τε ῥέει καὶ ἐκ τῆς ἄρχεται ῥέων ὁ Νεῖλος, ἦν ἂν τούτων οὐδέν, ὡς ἡ ἀνάγκη ἐλέγχει.", "st": "2.22"}, {"sp": "N", "t": "ὁ δὲ περὶ τοῦ Ὠκεανοῦ λέξας ἐς ἀφανὲς τὸν μῦθον ἀνενείκας οὐκ ἔχει ἔλεγχον· οὐ γὰρ τινὰ ἔγωγε οἶδα ποταμὸν Ὠκεανὸν ἐόντα, Ὅμηρον δὲ ἢ τινὰ τῶν πρότερον γενομένων ποιητέων δοκέω τὸ οὔνομα εὑρόντα ἐς ποίησιν ἐσενείκασθαι.", "st": "2.23"}, {"sp": "N", "t": "εἰ δὲ δεῖ μεμψάμενον γνώμας τὰς προκειμένας αὐτὸν περὶ τῶν ἀφανέων γνώμην ἀποδέξασθαι, φράσω δι’ ὅ τι μοι δοκέει πληθύνεσθαι ὁ Νεῖλος τοῦ θέρεος· τὴν χειμερινὴν ὥρην ἀπελαυνόμενος ὁ ἥλιος ἐκ τῆς ἀρχαίης διεξόδου ὑπὸ τῶν χειμώνων ἔρχεται τῆς Λιβύης τὰ ἄνω. ὡς μέν νυν ἐν ἐλαχίστῳ δηλῶσαι, πᾶν εἴρηται· τῆς γὰρ ἂν ἀγχοτάτω τε ᾖ χώρης οὗτος ὁ θεὸς καὶ κατὰ ἥντινα, ταύτην οἰκὸς διψῆν τε ὑδάτων μάλιστα καὶ τὰ ἐγχώρια ῥεύματα μαραίνεσθαι τῶν ποταμῶν.", "st": "2.24"}, {"sp": "N", "t": "ὡς δὲ ἐν πλέονι λόγῳ δηλῶσαι, ὧδε ἔχει. διεξιὼν τῆς Λιβύης τὰ ἄνω ὁ ἥλιος τάδε ποιέει· ἅτε διὰ παντὸς τοῦ χρόνου αἰθρίου τε ἐόντος τοῦ ἠέρος τοῦ κατὰ ταῦτα τὰ χωρία καὶ ἀλεεινῆς τῆς χώρης ἐούσης καὶ ἀνέμων ψυχρῶν, διεξιὼν ποιέει οἷόν περ καὶ τὸ θέρος ἔωθε ποιέειν ἰὼν τὸ μέσον τοῦ οὐρανοῦ· ἕλκει γὰρ ἐπ’ ἑωυτὸν τὸ ὕδωρ, ἑλκύσας δὲ ἀπωθέει ἐς τὰ ἄνω χωρία, ὑπολαμβάνοντες δὲ οἱ ἄνεμοι καὶ διασκιδνάντες τήκουσι· καὶ εἰσὶ οἰκότως οἱ ἀπὸ ταύτης τῆς χώρης πνέοντες, ὅ τε νότος καὶ ὁ λίψ, ἀνέμων πολλὸν τῶν πάντων ὑετιώτατοι δοκέει δέ μοι οὐδὲ πᾶν τὸ ὕδωρ τὸ ἐπέτειον ἑκάστοτε ἀποπέμπεσθαι τοῦ Νείλου ὁ ἥλιος, ἀλλὰ καὶ ὑπολείπεσθαι περὶ ἑωυτόν. πρηϋνομένου δὲ τοῦ χειμῶνος ἀπέρχεται ὁ ἥλιος ἐς μέσον τὸν οὐρανὸν ὀπίσω, καὶ τὸ ἐνθεῦτεν ἤδη ὁμοίως ἀπὸ πάντων ἕλκει τῶν ποταμῶν. τέως δὲ οἳ μὲν ὀμβρίου ὕδατος συμμισγομένου πολλοῦ αὐτοῖσι, ἅτε ὑομένης τε τῆς χώρης καὶ κεχαραδρωμένης, ῥέουσι μεγάλοι· τοῦ δὲ θέρεος τῶν τε ὄμβρων ἐπιλειπόντων αὐτοὺς καὶ ὑπὸ τοῦ ἡλίου ἑλκόμενοι ἀσθενέες εἰσί. ὁ δὲ Νεῖλος ἐὼν ἄνομβρος, ἑλκόμενος δὲ ὑπὸ τοῦ ἡλίου μοῦνος ποταμῶν τοῦτον τὸν χρόνον, οἰκότως αὐτὸς ἑωυτοῦ ῥέει πολλῷ ὑποδεέστερος ἢ τοῦ θέρεος· τότε μὲν γὰρ μετὰ πάντων τῶν ὑδάτων ἴσον ἕλκεται, τὸν δὲ χειμῶνα μοῦνος πιέζεται.", "st": "2.25"}, {"sp": "N", "t": "οὕτω τὸν ἥλιον νενόμικα τούτων αἴτιον εἶναι. αἴτιος δὲ ὁ αὐτὸς οὗτος κατὰ γνώμην τὴν ἐμὴν καὶ τὸν ἠέρα ξηρὸν τὸν ταύτῃ εἶναι, διακαίων τὴν διέξοδον ἑωυτοῦ· οὕτω τῆς Λιβύης τὰ ἄνω θέρος αἰεὶ κατέχει. εἰ δὲ ἡ στάσις ἤλλακτο τῶν ὡρέων, καὶ τοῦ οὐρανοῦ τῇ μὲν νῦν ὁ βορέης τε καὶ ὁ χειμὼν ἑστᾶσι, ταύτῃ μὲν τοῦ νότου ἦν ἡ στάσις καὶ τῆς μεσαμβρίης, τῇ δὲ ὁ νότος νῦν ἕστηκε, ταύτῃ δὲ ὁ βορέης, εἰ ταῦτα οὕτω εἶχε, ὁ ἥλιος ἂν ἀπελαυνόμενος ἐκ μέσου τοῦ οὐρανοῦ ὑπὸ τοῦ χειμῶνος καὶ τοῦ βορέω ἤιε ἂν τὰ ἄνω τῆς Εὐρώπης κατά περ νῦν τῆς Λιβύης ἔρχεται, διεξιόντα δ’ ἄν μιν διὰ πάσης Εὐρώπης ἔλπομαι ποιέειν ἂν τὸν Ἴστρον τά περ νῦν ἐργάζεται τὸν Νεῖλον.", "st": "2.26"}, {"sp": "N", "t": "τῆς αὔρης δὲ πέρι, ὅτι οὐκ ἀποπνέει, τήνδε ἔχω γνώμην, ὡς κάρτα ἀπὸ θερμέων χωρέων οὐκ οἰκός ἐστι οὐδὲν ἀποπνέειν, αὔρη δὲ ἀπὸ ψυχροῦ τινος φιλέει πνέειν.", "st": "2.27"}, {"sp": "N", "t": "ταῦτα μέν νυν ἔστω ὡς ἔστι τε καὶ ὡς ἀρχὴν ἐγένετο· τοῦ δὲ Νείλου τὰς πηγὰς οὔτε Αἰγυπτίων οὔτε Λιβύων οὔτε Ἑλλήνων τῶν ἐμοὶ ἀπικομένων ἐς λόγους οὐδεὶς ὑπέσχετο εἰδέναι, εἰ μὴ ἐν Αἰγύπτῳ ἐν Σάι πόλι ὁ γραμματιστὴς τῶν ἱρῶν χρημάτων τῆς Ἀθηναίης. οὗτος δ’ ἔμοιγε παίζειν ἐδόκεε φάμενος εἰδέναι ἀτρεκέως· ἔλεγε δὲ ὧδε, εἶναι δύο ὄρεα ἐς ὀξὺ τὰς κορυφὰς ἀπηγμένα, μεταξὺ Συήνης τε πόλιος κείμενα τῆς Θηβαΐδος καὶ Ἐλεφαντίνης, οὐνόματα δὲ εἶναι τοῖσι ὄρεσι τῷ μὲν Κρῶφι τῷ δὲ Μῶφι· τὰς ὦν δὴ πηγὰς τοῦ Νείλου ἐούσας ἀβύσσους ἐκ τοῦ μέσου τῶν ὀρέων τούτων ῥέειν, καὶ τὸ μὲν ἥμισυ τοῦ ὕδατος ἐπ’ Αἰγύπτου ῥέειν καὶ πρὸς βορέην ἄνεμον, τὸ δ’ ἕτερον ἥμισυ ἐπ’ Αἰθιοπίης τε καὶ νότου. ὡς δὲ ἄβυσσοι εἰσι αἱ πηγαί, ἐς διάπειραν ἔφη τούτου Ψαμμήτιχον Αἰγύπτου βασιλέα ἀπικέσθαι· πολλέων γὰρ αὐτὸν χιλιάδων ὀργυιέων πλεξάμενον κάλον κατεῖναι ταύτῃ καὶ οὐκ ἐξικέσθαι ἐς βυσσόν. οὕτω μὲν δὴ ὁ γραμματιστής, εἰ ἄρα ταῦτα γινόμενα ἔλεγε, ἀπέφαινε, ὡς ἐμὲ κατανοέειν, δίνας τινὰς ταύτῃ ἐούσας ἰσχυρὰς καὶ παλιρροίην, οἷα δὲ ἐμβάλλοντος τοῦ ὕδατος τοῖσι ὄρεσι, μὴ δύνασθαι κατιεμένην καταπειρητηρίην ἐς βυσσὸν ἰέναι.", "st": "2.28"}, {"sp": "N", "t": "ἄλλου δὲ οὐδενὸς οὐδὲν ἐδυνάμην πυθέσθαι. ἀλλὰ τοσόνδε μὲν ἄλλο ἐπὶ μακρότατον ἐπυθόμην, μέχρι μὲν Ἐλεφαντίνης πόλιος αὐτόπτης ἐλθών, τὸ δὲ ἀπὸ τούτου ἀκοῇ ἤδη ἱστορέων. ἀπὸ Ἐλεφαντίνης πόλιος ἄνω ἰόντι ἄναντες ἐστὶ χωρίον· ταύτῃ ὦν δεῖ τὸ πλοῖον διαδήσαντας ἀμφοτέρωθεν κατά περ βοῦν πορεύεσθαι· ἢν δὲ ἀπορραγῇ τὸ πλοῖον οἴχεται φερόμενον ὑπὸ ἰσχύος τοῦ ῥόου. τὸ δὲ χωρίον τοῦτο ἐστὶ ἐπ’ ἡμέρας τέσσερας πλόος, σκολιὸς δὲ ταύτῃ κατά περ ὁ Μαίανδρος ἐστὶ ὁ Νεῖλος· σχοῖνοι δὲ δυώδεκα εἰσὶ οὗτοι τοὺς δεῖ τούτῳ τῷ τρόπῳ διεκπλῶσαι. καὶ ἔπειτα ἀπίξεαι ἐς πεδίον λεῖον, ἐν τῷ νῆσον περιρρέει ὁ Νεῖλος· Ταχομψὼ οὔνομα αὐτῇ ἐστι. οἰκέουσι δὲ τὰ ἀπὸ Ἐλεφαντίνης ἄνω Αἰθίοπες ἤδη καὶ τῆς νήσου τὸ ἥμισυ, τὸ δὲ ἥμισυ Αἰγύπτιοι. ἔχεται δὲ τῆς νήσου λίμνην μεγάλη, τὴν πέριξ νομάδες Αἰθίοπες νέμονται· τὴν διεκπλώσας ἐς τοῦ Νείλου τὸ ῥέεθρον ἥξεις, τὸ ἐς τὴν λίμνην ταύτην ἐκδιδοῖ. καὶ ἔπειτα ἀποβὰς παρὰ τὸν ποταμὸν ὁδοιπορίην ποιήσεαι ἡμερέων τεσσεράκοντα· σκόπελοί τε γὰρ ἐν τῷ Νείλῳ ὀξέες ἀνέχουσι καὶ χοιράδες πολλαί εἰσι, δι’ ὧν οὐκ οἷά τε ἐστὶ πλέειν. διεξελθὼν δὲ ἐν τῇσι τεσσεράκοντα ἡμέρῃσι τοῦτο τὸ χωρίον, αὖτις ἐς ἕτερον πλοῖον ἐσβὰς δυώδεκα ἡμέρας πλεύσεαι, καὶ ἔπειτα ἥξεις ἐς πόλιν μεγάλην τῇ οὔνομα ἐστὶ Μερόη· λέγεται δὲ αὕτη ἡ πόλις εἶναι μητρόπολις τῶν ἄλλων Αἰθιόπων. οἱ δ’ ἐν ταύτῃ Δία θεῶν καὶ Διόνυσον μούνους σέβονται, τούτους τε μεγάλως τιμῶσι, καί σφι μαντήιον Διὸς κατέστηκε· στρατεύονται δὲ ἐπεάν σφεας ὁ θεὸς οὗτος κελεύῃ διὰ θεσπισμάτων, καὶ τῇ ἂν κελεύῃ, ἐκεῖσε.", "st": "2.29"}, {"sp": "N", "t": "ἀπὸ δὲ ταύτης τῆς πόλιος πλέων ἐν ἴσῳ χρόνῳ ἄλλῳ ἥξεις ἐς τοὺς αὐτομόλους ἐν ὅσῳ περ ἐξ Ἐλεφαντίνης ἦλθες ἐς τὴν μητρόπολιν τὴν Αἰθιόπων. τοῖσι δὲ αὐτομόλοισι τούτοισι οὔνομα ἐστὶ Ἀσμάχ, δύναται δὲ τοῦτο τὸ ἔπος κατὰ τὴν Ἑλλήνων γλῶσσαν οἱ ἐξ ἀριστερῆς χειρὸς παριστάμενοι βασιλέι. ἀπέστησαν δὲ αὗται τέσσερες καὶ εἴκοσι μυριάδες Αἰγυπτίων τῶν μαχίμων ἐς τοὺς Αἰθίοπας τούτους δι’ αἰτίην τοιήνδε. ἐπὶ Ψαμμητίχου βασιλέος φυλακαὶ κατέστησαν ἔν τε Ἐλεφαντίνῃ πόλι πρὸς Αἰθιόπων καὶ ἐν Δάφνῃσι τῇσι Πηλουσίῃσι ἄλλη πρὸς Ἀραβίων τε καὶ Ἀσσυρίων, καὶ ἐν Μαρέῃ πρὸς Λιβύης ἄλλη. ἔτι δὲ ἐπ’ ἐμεῦ καὶ Περσέων κατὰ ταὐτὰ αἱ φυλακαὶ ἔχουσι ὡς καὶ ἐπὶ Ψαμμητίχου ἦσαν· καὶ γὰρ ἐν Ἐλεφαντίνῃ Πέρσαι φρουρέουσι καὶ ἐν Δάφνῃσι. τοὺς ὦν δὴ Αἰγυπτίους τρία ἔτεα φρουρήσαντας ἀπέλυε οὐδεὶς τῆς φρουρῆς· οἳ δὲ βουλευσάμενοι καὶ κοινῷ λόγῳ χρησάμενοι πάντες ἀπὸ τοῦ Ψαμμητίχου ἀποστάντες ἤισαν ἐς Αἰθιοπίην. Ψαμμήτιχος δὲ πυθόμενος ἐδίωκε· ὡς δὲ κατέλαβε, ἐδέετο πολλὰ λέγων καί σφεας θεοὺς πατρωίους ἀπολιπεῖν οὐκ ἔα καὶ τέκνα καὶ γυναῖκας. τῶν δὲ τινὰ λέγεται δέξαντα τὸ αἰδοῖον εἰπεῖν, ἔνθα ἂν τοῦτο ᾖ, ἔσεσθαι αὐτοῖσι ἐνθαῦτα καὶ τέκνα καὶ γυναῖκας. οὗτοι ἐπείτε ἐς Αἰθιοπίην ἀπίκοντο, διδοῦσι σφέας αὐτοὺς τῷ Αἰθιόπων βασιλέι, ὁ δὲ σφέας τῷδε ἀντιδωρέεται· ἦσάν οἱ διάφοροι τινὲς γεγονότες τῶν Αἰθιόπων· τούτους ἐκέλευε ἐξελόντας τὴν ἐκείνων γῆν οἰκέειν. τούτων δὲ ἐσοικισθέντων ἐς τοὺς Αἰθίοπας ἡμερώτεροι γεγόνασι Αἰθίοπες, ἤθεα μαθόντες Αἰγύπτια.", "st": "2.30"}, {"sp": "N", "t": "μέχρι μέν νυν τεσσέρων μηνῶν πλόου καὶ ὁδοῦ γινώσκεται ὁ Νεῖλος πάρεξ τοῦ ἐν Αἰγύπτῳ ῥεύματος· τοσοῦτοι γὰρ συμβαλλομένῳ μῆνες εὑρίσκονται ἀναισιμούμενοι ἐξ Ἐλεφαντίνης πορευομένῳ ἐς τοὺς αὐτομόλους τούτους. ῥέει δὲ ἀπὸ ἑσπέρης τε καὶ ἡλίου δυσμέων. τὸ δὲ ἀπὸ τοῦδε οὐδεὶς ἔχει σαφέως φράσαι· ἔρημος γὰρ ἐστὶ ἡ χώρη αὕτη ὑπὸ καύματος.", "st": "2.31"}, {"sp": "N", "t": "ἀλλὰ τάδε μὲν ἤκουσα ἀνδρῶν Κυρηναίων φαμένων ἐλθεῖν τε ἐπὶ τὸ Ἄμμωνος χρηστήριον καὶ ἀπικέσθαι ἐς λόγους Ἐτεάρχῳ τῷ Ἀμμωνίων βασιλέι, καί κως ἐκ λόγων ἄλλων ἀπικέσθαι ἐς λέσχην περὶ τοῦ Νείλου, ὡς οὐδεὶς αὐτοῦ οἶδε τὰς πηγάς, καὶ τὸν Ἐτέαρχον φάναι ἐλθεῖν κοτε παρ’ αὐτὸν Νασαμῶνας ἄνδρας. τὸ δὲ ἔθνος τοῦτο ἐστὶ μὲν Λιβυκόν, νέμεται δὲ τὴν Σύρτιν τε καὶ τὴν πρὸς ἠῶ χώρην τῆς Σύρτιος οὐκ ἐπὶ πολλόν. ἀπικομένους δὲ τοὺς Νασαμῶνας καὶ εἰρωτωμένους εἴ τι ἔχουσι πλέον λέγειν περὶ τῶν ἐρήμων τῆς Λιβύης, φάναι παρὰ σφίσι γενέσθαι ἀνδρῶν δυναστέων παῖδας ὑβριστάς, τοὺς ἄλλα τε μηχανᾶσθαι ἀνδρωθέντας περισσὰ καὶ δὴ καὶ ἀποκληρῶσαι πέντε ἑωυτῶν ὀψομένους τὰ ἔρημα τῆς Λιβύης, καὶ εἴ τι πλέον ἴδοιεν τῶν τὰ μακρότατα ἰδομένων. τῆς γὰρ Λιβύης τὰ μὲν κατὰ τὴν βορηίην θάλασσαν ἀπ’ Αἰγύπτου ἀρξάμενοι μέχρι Σολόεντος ἄκρης, ἣ τελευτᾷ τῆς Λιβύης, παρήκουσι παρὰ πᾶσαν Λίβυες καὶ Λιβύων ἔθνεα πολλά, πλὴν ὅσον Ἕλληνες καὶ Φοίνικες ἔχουσι· τὰ δὲ ὑπὲρ θαλάσσης τε καὶ τῶν ἐπὶ θάλασσαν κατηκόντων ἀνθρώπων, τὰ κατύπερθε θηριώδης ἐστὶ ἡ Λιβύη· τὰ δὲ κατύπερθε τῆς θηριώδεος ψάμμος τε ἐστὶ καὶ ἄνυδρος δεινῶς καὶ ἔρημος πάντων. εἶπαι ὦν τοὺς νεηνίας ἀποπεμπομένους ὑπὸ τῶν ἡλίκων, ὕδασί τε καὶ σιτίοισι εὖ ἐξηρτυμένους, ἰέναι τὰ πρῶτα μὲν διὰ τῆς οἰκεομένης, ταύτην δὲ διεξελθόντας ἐς τὴν θηριώδεα ἀπικέσθαι, ἐκ δὲ ταύτης τὴν ἔρημον διεξιέναι, τὴν ὁδὸν ποιευμένους πρὸς ζέφυρον ἄνεμον, διεξελθόντας δὲ χῶρον πολλὸν ψαμμώδεα καὶ ἐν πολλῇσι ἡμέρῃσι ἰδεῖν δή κοτε δένδρεα ἐν πεδίῳ πεφυκότα, καί σφεας προσελθόντας ἅπτεσθαι τοῦ ἐπεόντος ἐπὶ τῶν δενδρέων καρποῦ, ἁπτομένοισι δέ σφι ἐπελθεῖν ἄνδρας μικρούς, μετρίων ἐλάσσονας ἀνδρῶν, λαβόντας δὲ ἄγειν σφέας· φωνῆς δὲ οὔτε τι τῆς ἐκείνων τοὺς Νασαμῶνας γινώσκειν οὔτε τοὺς ἄγοντας τῶν Νασαμώνων· ἄγειν τε δὴ αὐτοὺς δι’ ἑλέων μεγίστων, καὶ διεξελθόντας ταῦτα ἀπικέσθαι ἐς πόλιν ἐν τῇ πάντας εἶναι τοῖσι ἄγουσι τὸ μέγαθος ἴσους, χρῶμα δὲ μέλανας. παρὰ δὲ τὴν πόλιν ῥέειν ποταμὸν μέγαν, ῥέειν δὲ ἀπὸ ἑσπέρης αὐτὸν πρὸς ἥλιον ἀνατέλλοντα, φαίνεσθαι δὲ ἐν αὐτῷ κροκοδείλους.", "st": "2.32"}, {"sp": "N", "t": "ὁ μὲν δὴ τοῦ Ἀμμωνίου Ἐτεάρχου λόγος ἐς τοῦτό μοι δεδηλώσθω, πλὴν ὅτι ἀπονοστῆσαί τε ἔφασκε τοὺς Νασαμῶνας, ὡς οἱ Κυρηναῖοι ἔλεγον, καὶ ἐς τοὺς οὗτοι ἀπίκοντο ἀνθρώπους, γόητας εἶναι ἅπαντας. τὸν δὲ δὴ ποταμὸν τοῦτον τὸν παραρρέοντα καὶ Ἐτέαρχος συνεβάλλετο εἶναι Νεῖλον, καὶ δὴ καὶ ὁ λόγος οὕτω αἱρέει. ῥέει γὰρ ἐκ Λιβύης ὁ Νεῖλος καὶ μέσην τάμνων Λιβύην, καὶ ὡς ἐγὼ συμβάλλομαι τοῖσι ἐμφανέσι τὰ μὴ γινωσκόμενα τεκμαιρόμενος, τῷ Ἴστρῳ ἐκ τῶν ἴσων μέτρων ὁρμᾶται. Ἴστρος τε γὰρ ποταμὸς ἀρξάμενος ἐκ Κελτῶν καὶ Πυρήνης πόλιος ῥέει μέσην σχίζων τὴν Εὐρώπην· οἱ δὲ Κελτοὶ εἰσὶ ἔξω Ἡρακλέων στηλέων, ὁμουρέουσι δὲ Κυνησίοισι, οἳ ἔσχατοι πρὸς δυσμέων οἰκέουσι τῶν ἐν τῇ Εὐρώπῃ κατοικημένων· τελευτᾷ δὲ ὁ Ἴστρος ἐς θάλασσαν ῥέων τὴν τοῦ Εὐξείνου πόντου διὰ πάσης Εὐρώπης, τῇ Ἰστρίην οἱ Μιλησίων οἰκέουσι ἄποικοι.", "st": "2.33"}, {"sp": "N", "t": "ὁ μὲν δὴ Ἴστρος, ῥέει γὰρ δι’ οἰκεομένης, πρὸς πολλῶν γινώσκεται, περὶ δὲ τῶν τοῦ Νείλου πηγέων οὐδεὶς ἔχει λέγειν· ἀοίκητός τε γὰρ καὶ ἔρημος ἐστὶ ἡ Λιβύη δι’ ἧς ῥέει. περὶ δὲ τοῦ ῥεύματος αὐτοῦ, ἐπ’ ὅσον μακρότατον ἱστορεῦντα ἦν ἐξικέσθαι, εἴρηται· ἐκδιδοῖ δὲ ἐς Αἴγυπτον. ἡ δὲ Αἴγυπτος τῆς ὀρεινῆς Κιλικίης μάλιστά κῃ ἀντίη κέεται· ἐνθεῦτεν δὲ ἐς Σινώπην τὴν ἐν τῷ Εὐξείνῳ πόντῳ πέντε ἡμερέων ἰθέα ὁδὸς εὐζώνῳ ἀνδρί· ἡ δὲ Σινώπη τῷ Ἴστρῳ ἐκδιδόντι ἐς θάλασσαν ἀντίον κέεται.", "st": "2.34"}, {"sp": "N", "t": "οὕτω τὸν Νεῖλον δοκέω διὰ πάσης τῆς Λιβύης διεξιόντα ἐξισοῦσθαι τῷ Ἴστρῳ.", "st": "2.34b"}, {"sp": "N", "t": "Νείλου μέν νυν πέρι τοσαῦτα εἰρήσθω· ἔρχομαι δὲ περὶ Αἰγύπτου μηκυνέων τὸν λόγον, ὅτι πλεῖστα θωμάσια ἔχει ἢ ἡ ἄλλη πᾶσα χώρη καὶ ἔργα λόγου μέζω παρέχεται πρὸς πᾶσαν χώρην· τούτων εἵνεκα πλέω περὶ αὐτῆς εἰρήσεται.", "st": "2.35"}, {"sp": "N", "t": "Αἰγύπτιοι ἅμα τῷ οὐρανῷ τῷ κατὰ σφέας ἐόντι ἑτεροίῳ καὶ τῷ ποταμῷ φύσιν ἀλλοίην παρεχομένῳ ἢ οἱ ἄλλοι ποταμοί, τὰ πολλὰ πάντα ἔμπαλιν τοῖσι ἄλλοισι ἀνθρώποισι ἐστήσαντο ἤθεά τε καὶ νόμους· ἐν τοῖσι αἱ μὲν γυναῖκες ἀγοράζουσι καὶ καπηλεύουσι, οἱ δὲ ἄνδρες κατ’ οἴκους ἐόντες ὑφαίνουσι· ὑφαίνουσι δὲ οἱ μὲν ἄλλοι ἄνω τὴν κρόκην ὠθέοντες, Αἰγύπτιοι δὲ κάτω. τὰ ἄχθεα οἱ μὲν ἄνδρες ἐπὶ τῶν κεφαλέων φορέουσι, αἱ δὲ γυναῖκες ἐπὶ τῶν ὤμων. οὐρέουσι αἱ μὲν γυναῖκες ὀρθαί, οἱ δὲ ἄνδρες κατήμενοι. εὐμαρείῃ χρέωνται ἐν τοῖσι οἴκοισι, ἐσθίουσι δὲ ἔξω ἐν τῇσι ὁδοῖσι ἐπιλέγοντες ὡς τὰ μὲν αἰσχρὰ ἀναγκαῖα δὲ ἐν ἀποκρύφῳ ἐστὶ ποιέειν χρεόν, τὰ δὲ μὴ αἰσχρὰ ἀναφανδόν. ἱρᾶται γυνὴ μὲν οὐδεμία οὔτε ἔρσενος θεοῦ οὔτε θηλέης, ἄνδρες δὲ πάντων τε καὶ πασέων. τρέφειν τοὺς τοκέας τοῖσι μὲν παισὶ οὐδεμία ἀνάγκη μὴ βουλομένοισι, τῇσι δὲ θυγατράσι πᾶσα ἀνάγκη καὶ μὴ βουλομένῃσι.", "st": "2.35.2"}, {"sp": "N", "t": "οἱ ἱρέες τῶν θεῶν τῇ μὲν ἄλλῃ κομέουσι, ἐν Αἰγύπτῳ δὲ ξυρῶνται. τοῖσι ἄλλοισι ἀνθρώποισι νόμος ἅμα κήδεϊ κεκάρθαι τὰς κεφαλὰς τοὺς μάλιστα ἱκνέεται, Αἰγύπτιοι δὲ ὑπὸ τοὺς θανάτους ἀνιεῖσι τὰς τρίχας αὔξεσθαι τάς τε ἐν τῇ κεφαλῇ καὶ τῷ γενείῳ, τέως ἐξυρημένοι. τοῖσι μὲν ἄλλοισι ἀνθρώποισι χωρὶς θηρίων ἡ δίαιτα ἀποκέκριται, Αἰγυπτίοισι δὲ ὁμοῦ θηρίοισι ἡ δίαιτα ἐστί. ἀπὸ πυρῶν καὶ κριθέων ὧλλοι ζώουσι, Αἰγυπτίων δὲ τῷ ποιευμένῳ ἀπὸ τούτων τὴν ζόην ὄνειδος μέγιστον ἐστί, ἀλλὰ ἀπὸ ὀλυρέων ποιεῦνται σιτία, τὰς ζειὰς μετεξέτεροι καλέουσι. φυρῶσι τὸ μὲν σταῖς τοῖσι ποσί, τὸν δὲ πηλὸν τῇσι χερσί, καὶ τὴν κόπρον ἀναιρέονται. τὰ αἰδοῖα ὧλλοι μὲν ἐῶσι ὡς ἐγένοντο, πλὴν ὅσοι ἀπὸ τούτων ἔμαθον, Αἰγύπτιοι δὲ περιτάμνονται. εἵματα τῶν μὲν ἀνδρῶν ἕκαστος ἔχει δύο, τῶν δὲ γυναικῶν ἓν ἑκάστη. τῶν ἱστίων τοὺς κρίκους καὶ τοὺς κάλους οἱ μὲν ἄλλοι ἔξωθεν προσδέουσι, Αἰγύπτιοι δὲ ἔσωθεν. γράμματα γράφουσι καὶ λογίζονται ψήφοισι Ἕλληνες μὲν ἀπὸ τῶν ἀριστερῶν ἐπὶ τὰ δεξιὰ φέροντες τὴν χεῖρα, Αἰγύπτιοι δὲ ἀπὸ τῶν δεξιῶν ἐπὶ τὰ ἀριστερά· καὶ ποιεῦντες ταῦτα αὐτοὶ μὲν φασὶ ἐπὶ δεξιὰ ποιέειν, Ἕλληνας δὲ ἐπ’ ἀριστερά. διφασίοισι δὲ γράμμασι χρέωνται, καὶ τὰ μὲν αὐτῶν ἱρὰ τὰ δὲ δημοτικὰ καλέεται.", "st": "2.36"}, {"sp": "N", "t": "θεοσεβέες δὲ περισσῶς ἐόντες μάλιστα πάντων ἀνθρώπων νόμοισι τοιοῖσιδε χρέωνται. ἐκ χαλκέων ποτηρίων πίνουσι, διασμῶντες ἀνὰ πᾶσαν ἡμέρην, οὐκ ὃ μὲν ὃ δ’ οὔ, ἀλλὰ πάντες. εἵματα δὲ λίνεα φορέουσι αἰεὶ νεόπλυτα, ἐπιτηδεύοντες τοῦτο μάλιστα, τά τε αἰδοῖα περιτάμνονται καθαρειότητος εἵνεκεν, προτιμῶντες καθαροὶ εἶναι ἢ εὐπρεπέστεροι. οἱ δὲ ἱρέες ξυρῶνται πᾶν τὸ σῶμα διὰ τρίτης ἡμέρης, ἵνα μήτε φθεὶρ μήτε ἄλλο μυσαρὸν μηδὲν ἐγγίνηταί σφι θεραπεύουσι τοὺς θεούς. ἐσθῆτα δὲ φορέουσι οἱ ἱρέες λινέην μούνην καὶ ὑποδήματα βύβλινα· ἄλλην δέ σφι ἐσθῆτα οὐκ ἔξεστι λαβεῖν οὐδὲ ὑποδήματα ἄλλα. λοῦνται δὲ δὶς τῆς ἡμέρης ἑκάστης ψυχρῷ καὶ δὶς ἑκάστης νυκτός, ἄλλας τε θρησκηίας ἐπιτελέουσι μυρίας ὡς εἰπεῖν λόγῳ. πάσχουσι δὲ καὶ ἀγαθὰ οὐκ ὀλίγα· οὔτε τι γὰρ τῶν οἰκηίων τρίβουσι οὔτε δαπανῶνται, ἀλλὰ καὶ σιτία σφι ἐστὶ ἱρὰ πεσσόμενα, καὶ κρεῶν βοέων καὶ χηνέων πλῆθός τι ἑκάστῳ γίνεται πολλὸν ἡμέρης ἑκάστης, δίδοται δέ σφι καὶ οἶνος ἀμπέλινος· ἰχθύων δὲ οὔ σφι ἔξεστι πάσασθαι. κυάμους δὲ οὔτε τι μάλα σπείρουσι Αἰγύπτιοι ἐν τῇ χώρῃ, τούς τε γινομένους οὔτε τρώγουσι οὔτε ἕψοντες πατέονται, οἱ δὲ δὴ ἱρέες οὐδὲ ὁρέοντες ἀνέχονται, νομίζοντες οὐ καθαρὸν εἶναί μιν ὄσπριον. ἱρᾶται δὲ οὐκ εἷς ἑκάστου τῶν θεῶν ἀλλὰ πολλοί, τῶν εἷς ἐστι ἀρχιερεύς· ἐπεὰν δέ τις ἀποθάνῃ, τούτου ὁ παῖς ἀντικατίσταται.", "st": "2.37"}, {"sp": "N", "t": "τοὺς δὲ βοῦς τοὺς ἔρσενας τοῦ Ἐπάφου εἶναι νομίζουσι, καὶ τούτου εἵνεκα δοκιμάζουσι αὐτοὺς ὧδε· τρίχα ἢν καὶ μίαν ἴδηται ἐπεοῦσαν μέλαιναν, οὐ καθαρὸν εἶναι νομίζει. δίζηται δὲ ταῦτα ἐπὶ τούτῳ τεταγμένος τῶν τις ἱρέων καὶ ὀρθοῦ ἑστεῶτος τοῦ κτήνεος καὶ ὑπτίου, καὶ τὴν γλῶσσαν ἐξειρύσας, εἰ καθαρὴ τῶν προκειμένων σημηίων, τὰ ἐγὼ ἐν ἄλλῳ λόγῳ ἐρέω· κατορᾷ δὲ καὶ τὰς τρίχας τῆς οὐρῆς εἰ κατὰ φύσιν ἔχει πεφυκυίας. ἢν δὲ τούτων πάντων ᾖ καθαρός, σημαίνεται βύβλῳ περὶ τὰ κέρεα εἱλίσσων καὶ ἔπειτα γῆν σημαντρίδα ἐπιπλάσας ἐπιβάλλει τὸν δακτύλιον, καὶ οὕτω ἀπάγουσι. ἀσήμαντον δὲ θύσαντι θάνατος ἡ ζημίη ἐπικέεται. δοκιμάζεται μέν νυν τὸ κτῆνος τρόπῳ τοιῷδε, θυσίη δέ σφι ἥδε κατέστηκε.", "st": "2.38"}, {"sp": "N", "t": "ἀγαγόντες τὸ σεσημασμένον κτῆνος πρὸς τὸν βωμὸν ὅκου ἂν θύωσι, πῦρ ἀνακαίουσι, ἔπειτα δὲ ἐπ’ αὐτοῦ οἶνον κατὰ τοῦ ἱρηίου ἐπισπείσαντες καὶ ἐπικαλέσαντες τὸν θεὸν σφάζουσι, σφάξαντες δὲ ἀποτάμνουσι τὴν κεφαλήν. σῶμα μὲν δὴ τοῦ κτήνεος δείρουσι, κεφαλῇ δὲ κείνῃ πολλὰ καταρησάμενοι φέρουσι, τοῖσι μὲν ἂν ᾖ ἀγορὴ καὶ Ἕλληνές σφι ἔωσι ἐπιδήμιοι ἔμποροι, οἳ δὲ φέροντες ἐς τὴν ἀγορὴν ἀπ’ ὦν ἔδοντο, τοῖσι δὲ ἂν μὴ παρέωσι Ἕλληνες, οἳ δ’ ἐκβάλλουσι ἐς τὸν ποταμόν· καταρῶνται δὲ τάδε λέγοντες τῇσι κεφαλῇσι, εἴ τι μέλλοι ἢ σφίσι τοῖσι θύουσι ἢ Αἰγύπτῳ τῇ συναπάσῃ κακὸν γενέσθαι, ἐς κεφαλὴν ταύτην τραπέσθαι. κατὰ μέν νυν τὰς κεφαλὰς τῶν θυομένων κτηνέων καὶ τὴν ἐπίσπεισιν τοῦ οἴνου πάντες Αἰγύπτιοι νόμοισι τοῖσι αὐτοῖσι χρέωνται ὁμοίως ἐς πάντα τὰ ἱρά, καὶ ἀπὸ τούτου τοῦ νόμου οὐδὲ ἄλλου οὐδενὸς ἐμψύχου κεφαλῆς γεύσεται Αἰγυπτίων οὐδείς.", "st": "2.39"}, {"sp": "N", "t": "ἡ δὲ δὴ ἐξαίρεσις τῶν ἱρῶν καὶ ἡ καῦσις ἄλλη περὶ ἄλλο ἱρόν σφι κατέστηκε· τὴν δ’ ὦν μεγίστην τε δαίμονα ἥγηνται εἶναι καὶ μεγίστην οἱ ὁρτὴν ἀνάγουσι, ταύτην ἔρχομαι ἐρέων … ἐπεὰν ἀποδείρωσι τὸν βοῦν, κατευξάμενοι κοιλίην μὲν κείνην πᾶσαν ἐξ ὦν εἷλον, σπλάγχνα δὲ αὐτοῦ λείπουσι ἐν τῷ σώματι καὶ τὴν πιμελήν, σκέλεα δὲ ἀποτάμνουσι καὶ τὴν ὀσφὺν ἄκρην καὶ τοὺς ὤμους τε καὶ τὸν τράχηλον. ταῦτα δὲ ποιήσαντες τὸ ἄλλο σῶμα τοῦ βοὸς πιμπλᾶσι ἄρτων καθαρῶν καὶ μέλιτος καὶ ἀσταφίδος καὶ σύκων καὶ λιβανωτοῦ καὶ σμύρνης καὶ τῶν ἄλλων θυωμάτων, πλήσαντες δὲ τούτων καταγίζουσι, ἔλαιον ἄφθονον καταχέοντες· προνηστεύσαντες δὲ θύουσι, καιομένων δὲ τῶν ἱρῶν τύπτονται πάντες, ἐπεὰν δὲ ἀποτύψωνται, δαῖτα προτίθενται τὰ ἐλίποντο τῶν ἱρῶν.", "st": "2.40"}, {"sp": "N", "t": "τοὺς μέν νυν καθαροὺς βοῦς τοὺς ἔρσενας καὶ τοὺς μόσχους οἱ πάντες Αἰγύπτιοι θύουσι, τὰς δὲ θηλέας οὔ σφι ἔξεστι θύειν, ἀλλὰ ἱραί εἰσι τῆς Ἴσιος· τὸ γὰρ τῆς Ἴσιος ἄγαλμα ἐὸν γυναικήιον βούκερων ἐστὶ κατά περ Ἕλληνες τὴν Ἰοῦν γράφουσι, καὶ τὰς βοῦς τὰς θηλέας Αἰγύπτιοι πάντες ὁμοίως σέβονται προβάτων πάντων μάλιστα μακρῷ. τῶν εἵνεκα οὔτε ἀνὴρ Αἰγύπτιος οὔτε γυνὴ ἄνδρα Ἕλληνα φιλήσειε ἂν τῷ στόματι, οὐδὲ μαχαίρῃ ἀνδρὸς Ἕλληνος χρήσεται οὐδὲ ὀβελοῖσι οὐδὲ λέβητι, οὐδὲ κρέως καθαροῦ βοὸς διατετμημένου Ἑλληνικῇ μαχαίρῃ γεύσεται. θάπτουσι δὲ τοὺς ἀποθνήσκοντας βοῦς τρόπον τόνδε· τὰς μὲν θηλέας ἐς τὸν ποταμὸν ἀπιεῖσι, τοὺς δὲ ἔρσενας κατορύσσουσι ἕκαστοι ἐν τοῖσι προαστείοισι, τὸ κέρας τὸ ἕτερον ἢ καὶ ἀμφότερα ὑπερέχοντα σημηίου εἵνεκεν· ἐπεὰν δὲ σαπῇ καὶ προσίῃ ὁ τεταγμένος χρόνος, ἀπικνέεται ἐς ἑκάστην πόλιν βᾶρις ἐκ τῆς Προσωπίτιδος καλευμένης νήσου. ἣ δ’ ἔστι μὲν ἐν τῷ Δέλτα, περίμετρον δὲ αὐτῆς εἰσὶ σχοῖνοι ἐννέα. ἐν ταύτῃ ὦν τῇ Προσωπίτιδι νήσῳ ἔνεισι μὲν καὶ ἄλλαι πόλιες συχναί, ἐκ τῆς δὲ αἱ βάριες παραγίνονται ἀναιρησόμεναι τὰ ὀστέα τῶν βοῶν, οὔνομα τῇ πόλι Ἀτάρβηχις, ἐν δ’ αὐτῇ Ἀφροδίτης ἱρὸν ἅγιον ἵδρυται. ἐκ ταύτης τῆς πόλιος πλανῶνται πολλοὶ ἄλλοι ἐς ἄλλας πόλις, ἀνορύξαντες δὲ τὰ ὀστέα ἀπάγουσι καὶ θάπτουσι ἐς ἕνα χῶρον πάντες. κατὰ ταὐτὰ δὲ τοῖσι βουσὶ καὶ τἆλλα κτήνεα θάπτουσι ἀποθνήσκοντα· καὶ γὰρ περὶ ταῦτα οὕτω σφι νενομοθέτηται· κτείνουσι γὰρ δὴ οὐδὲ ταῦτα.", "st": "2.41"}, {"sp": "N", "t": "ὅσοι μὲν δὴ Διὸς Θηβαιέος ἵδρυνται ἱρὸν ἤ νομοῦ τοῦ Θηβαίου εἰσί, οὗτοι μέν νυν πάντες ὀίων ἀπεχόμενοι αἶγας θύουσι. θεοὺς γὰρ δὴ οὐ τοὺς αὐτοὺς ἅπαντες ὁμοίως Αἰγύπτιοι σέβονται, πλὴν Ἴσιός τε καὶ Ὀσίριος, τὸν δὴ Διόνυσον εἶναι λέγουσι· τούτους δὲ ὁμοίως ἅπαντες σέβονται. ὅσοι δὲ τοῦ Μένδητος ἔκτηνται ἱρὸν ἢ νομοῦ τοῦ Μενδησίου εἰσί, οὗτοι δὲ αἰγῶν ἀπεχόμενοι ὄις θύουσι. Θηβαῖοι μέν νυν καὶ ὅσοι διὰ τούτους ὀίων ἀπέχονται, διὰ τάδε λέγουσι τὸν νόμον τόνδε σφίσι τεθῆναι. Ἡρακλέα θελῆσαι πάντως ἰδέσθαι τὸν Δία, καὶ τὸν οὐκ ἐθέλειν ὀφθῆναι ὑπ’ αὐτοῦ· τέλος δέ, ἐπείτε λιπαρέειν τὸν Ἡρακλέα, τάδε τὸν Δία μηχανήσασθαι· κριὸν ἐκδείραντα προσχέσθαι τε τὴν κεφαλὴν ἀποταμόντα τοῦ κριοῦ καὶ ἐνδύντα τὸ νάκος οὕτω οἱ ἑωυτὸν ἐπιδέξαι. ἀπὸ τούτου κριοπρόσωπον τοῦ Διὸς τὤγαλμα ποιεῦσι Αἰγύπτιοι, ἀπὸ δὲ Αἰγυπτίων Ἀμμώνιοι, ἐόντες Αἰγυπτίων τε καὶ Αἰθιόπων ἄποικοι καὶ φωνὴν μεταξὺ ἀμφοτέρων νομίζοντες. δοκέειν δέ μοι, καὶ τὸ οὔνομα Ἀμμώνιοι ἀπὸ τοῦδε σφίσι τὴν ἐπωνυμίην ἐποιήσαντο· Ἀμοῦν γὰρ Αἰγύπτιοι καλέουσι τὸν Δία. τοὺς δὲ κριοὺς οὐ θύουσι Θηβαῖοι, ἀλλ’ εἰσί σφι ἱροὶ διὰ τοῦτο. μιῇ δὲ ἡμέρῃ τοῦ ἐνιαυτοῦ, ἐν ὁρτῇ τοῦ Διός, κριὸν ἕνα κατακόψαντες καὶ ἀποδείραντες κατὰ τὠυτὸ ἐνδύουσι τὤγαλμα τοῦ Διός, καὶ ἔπειτα ἄλλο ἄγαλμα Ἡρακλέος προσάγουσι πρὸς αὐτό. ταῦτα δὲ ποιήσαντες τύπτονται οἱ περὶ τὸ ἱρὸν ἅπαντες τὸν κριὸν καὶ ἔπειτα ἐν ἱρῇ θήκῃ θάπτουσι αὐτόν.", "st": "2.42"}, {"sp": "N", "t": "Ἡρακλέος δὲ πέρι τόνδε τὸν λόγον ἤκουσα, ὅτι εἴη τῶν δυώδεκα θεῶν· τοῦ ἑτέρου δὲ πέρι Ἡρακλέος, τὸν Ἕλληνες οἴδασι, οὐδαμῇ Αἰγύπτου ἐδυνάσθην ἀκοῦσαι. καὶ μὴν ὅτι γε οὐ παρ’ Ἑλλήνων ἔλαβον τὸ οὔνομα Αἰγύπτιοι τοῦ Ἡρακλέος, ἀλλὰ Ἕλληνες μᾶλλον παρ’ Αἰγυπτίων καὶ Ἑλλήνων οὗτοι οἱ θέμενοι τῷ Ἀμφιτρύωνος γόνῳ τοὔνομα Ἡρακλέα, πολλά μοι καὶ ἄλλα τεκμήρια ἐστὶ τοῦτο οὕτω ἔχειν, ἐν δὲ καὶ τόδε, ὅτι τε τοῦ Ἡρακλέος τούτου οἱ γονέες ἀμφότεροι ἦσαν Ἀμφιτρύων καὶ Ἀλκμήνη γεγονότες τὸ ἀνέκαθεν ἀπ’ Αἰγύπτου, καὶ διότι Αἰγύπτιοι οὔτε Ποσειδέωνος οὔτε Διοσκούρων τὰ οὐνόματα φασὶ εἰδέναι, οὐδέ σφι θεοὶ οὗτοι ἐν τοῖσι ἄλλοισι θεοῖσι ἀποδεδέχαται. καὶ μὴν εἴ γε παρ’ Ἑλλήνων ἔλαβον οὔνομά τευ δαίμονος, τούτων οὐκ ἥκιστα ἀλλὰ μάλιστα ἔμελλον μνήμην ἕξειν, εἴ περ καὶ τότε ναυτιλίῃσι ἐχρέωντο καὶ ἦσαν Ἑλλήνων τινὲς ναυτίλοι, ὡς ἔλπομαί τε καὶ ἐμὴ γνώμη αἱρέει· ὥστε τούτων ἂν καὶ μᾶλλον τῶν θεῶν τὰ οὐνόματα ἐξεπιστέατο Αἰγύπτιοι ἢ τοῦ Ἡρακλέος. ἀλλά τις ἀρχαῖος ἐστὶ θεὸς Αἰγυπτίοισι Ἡρακλέης· ὡς δὲ αὐτοὶ λέγουσι, ἔτεα ἐστὶ ἑπτακισχίλια καὶ μύρια ἐς Ἄμασιν βασιλεύσαντα, ἐπείτε ἐκ τῶν ὀκτὼ θεῶν οἱ δυώδεκα θεοὶ ἐγένοντο τῶν Ἡρακλέα ἕνα νομίζουσι.", "st": "2.43"}, {"sp": "N", "t": "καὶ θέλων δὲ τούτων πέρι σαφές τι εἰδέναι ἐξ ὧν οἷόν τε ἦν, ἔπλευσα καὶ ἐς Τύρον τῆς Φοινίκης, πυνθανόμενος αὐτόθι εἶναι ἱρὸν Ἡρακλέος ἅγιον. καὶ εἶδον πλουσίως κατεσκευασμένον ἄλλοισί τε πολλοῖσι ἀναθήμασι, καὶ ἐν αὐτῷ ἦσαν στῆλαι δύο, ἣ μὲν χρυσοῦ ἀπέφθου, ἣ δὲ σμαράγδου λίθου λάμποντος τὰς νύκτας μέγαθος. ἐς λόγους δὲ ἐλθὼν τοῖσι ἱρεῦσι τοῦ θεοῦ εἰρόμην ὁκόσος χρόνος εἴη ἐξ οὗ σφι τὸ ἱρὸν ἵδρυται. εὗρον δὲ οὐδὲ τούτους τοῖσι Ἕλλησι συμφερομένους· ἔφασαν γὰρ ἅμα Τύρῳ οἰκιζομένῃ καὶ τὸ ἱρὸν τοῦ θεοῦ ἱδρυθῆναι, εἶναι δὲ ἔτεα ἀπ’ οὗ Τύρον οἰκέουσι τριηκόσια καὶ δισχίλια. εἶδον δὲ ἐν τῇ Τύρῳ καὶ ἄλλο ἱρὸν Ἡρακλέος ἐπωνυμίην ἔχοντος Θασίου εἶναι· ἀπικόμην δὲ καὶ ἐς Θάσον, ἐν τῇ εὗρον ἱρὸν Ἡρακλέος ὑπὸ Φοινίκων ἱδρυμένον, οἳ κατ’ Εὐρώπης ζήτησιν ἐκπλώσαντες Θάσον ἔκτισαν· καὶ ταῦτα καὶ πέντε γενεῇσι ἀνδρῶν πρότερα ἐστὶ ἢ τὸν Ἀμφιτρύωνος Ἡρακλέα ἐν τῇ Ἑλλάδι γενέσθαι. τὰ μέν νυν ἱστορημένα δηλοῖ σαφέως παλαιὸν θεὸν Ἡρακλέα ἐόντα, καὶ δοκέουσι δέ μοι οὗτοι ὀρθότατα Ἑλλήνων ποιέειν, οἳ διξὰ Ἡράκλεια ἱδρυσάμενοι ἔκτηνται, καὶ τῷ μὲν ὡς ἀθανάτῳ Ὀλυμπίῳ δὲ ἐπωνυμίην θύουσι, τῷ δὲ ἑτέρῳ ὡς ἥρωι ἐναγίζουσι.", "st": "2.44"}, {"sp": "N", "t": "λέγουσι δὲ πολλὰ καὶ ἄλλα ἀνεπισκέπτως οἱ Ἕλληνες, εὐήθης δὲ αὐτῶν καὶ ὅδε ὁ μῦθος ἐστὶ τὸν περὶ τοῦ Ἡρακλέος λέγουσι, ὡς αὐτὸν ἀπικόμενον ἐς Αἴγυπτον στέψαντες οἱ Αἰγύπτιοι ὑπὸ πομπῆς ἐξῆγον ὡς θύσοντες τῷ Διί· τὸν δὲ τέως μὲν ἡσυχίην ἔχειν, ἐπεὶ δὲ αὐτοῦ πρὸς τῷ βωμῷ κατάρχοντο, ἐς ἀλκὴν τραπόμενον πάντας σφέας καταφονεῦσαι. ἐμοὶ μέν νυν δοκέουσι ταῦτα λέγοντες τῆς Αἰγυπτίων φύσιος καὶ τῶν νόμων πάμπαν ἀπείρως ἔχειν οἱ Ἕλληνες· τοῖσι γὰρ οὐδὲ κτήνεα ὁσίη θύειν ἐστὶ χωρὶς ὑῶν καὶ ἐρσένων βοῶν καὶ μόσχων, ὅσοι ἂν καθαροὶ ἔωσι, καὶ χηνῶν, κῶς ἂν οὗτοι ἀνθρώπους θύοιεν; ἔτι δὲ ἕνα ἐόντα τὸν Ἡρακλέα καὶ ἔτι ἄνθρωπον, ὡς δὴ φασί, κῶς φύσιν ἔχει πολλὰς μυριάδας φονεῦσαι; καὶ περὶ μὲν τούτων τοσαῦτα ἡμῖν εἰποῦσι καὶ παρὰ τῶν θεῶν καὶ παρὰ τῶν ἡρώων εὐμένεια εἴη.", "st": "2.45"}, {"sp": "N", "t": "τὰς δὲ δὴ αἶγας καὶ τοὺς τράγους τῶνδε εἵνεκα οὐ θύουσι Αἰγυπτίων οἱ εἰρημένοι· τὸν Πᾶνα τῶν ὀκτὼ θεῶν λογίζονται εἶναι οἱ Μενδήσιοι, τοὺς δὲ ὀκτὼ θεοὺς τούτους προτέρους τῶν δυώδεκα θεῶν φασι γενέσθαι. γράφουσί τε δὴ καὶ γλύφουσι οἱ ζωγράφοι καὶ οἱ ἀγαλματοποιοὶ τοῦ Πανὸς τὤγαλμα κατά περ Ἕλληνες αἰγοπρόσωπον καὶ τραγοσκελέα, οὔτι τοιοῦτον νομίζοντες εἶναί μιν ἀλλὰ ὁμοῖον τοῖσι ἄλλοισι θεοῖσι· ὅτευ δὲ εἵνεκα τοιοῦτον γράφουσι αὐτόν, οὔ μοι ἥδιον ἐστὶ λέγειν. σέβονται δὲ πάντας τοὺς αἶγας οἱ Μενδήσιοι, καὶ μᾶλλον τοὺς ἔρσενας τῶν θηλέων, καὶ τούτων οἱ αἰπόλοι τιμὰς μέζονας ἔχουσι· ἐκ δὲ τούτων ἕνα μάλιστα, ὅστις ἐπεὰν ἀποθάνῃ, πένθος μέγα παντὶ τῷ Μενδησίῳ νομῷ τίθεται. καλέεται δὲ ὅ τε τράγος καὶ ὁ Πὰν Αἰγυπτιστὶ Μένδης. ἐγένετο δὲ ἐν τῷ νομῷ τούτῳ ἐπ’ ἐμεῦ τοῦτο τὸ τέρας· γυναικὶ τράγος ἐμίσγετο ἀναφανδόν. τοῦτο ἐς ἐπίδεξιν ἀνθρώπων ἀπίκετο.", "st": "2.46"}, {"sp": "N", "t": "ὗν δὲ Αἰγύπτιοι μιαρὸν ἥγηνται θηρίον εἶναι, καὶ τοῦτο μὲν ἤν τις ψαύσῃ αὐτῶν παριὼν αὐτοῖσι τοῖσι ἱματίοισι ἀπ’ ὦν ἔβαψε ἑωυτὸν βὰς ἐς τὸν ποταμόν· τοῦτο δὲ οἱ συβῶται ἐόντες Αἰγύπτιοι ἐγγενέες ἐς ἱρὸν οὐδὲν τῶν ἐν Αἰγύπτῳ ἐσέρχονται μοῦνοι πάντων, οὐδέ σφι ἐκδίδοσθαι οὐδεὶς θυγατέρα ἐθέλει οὐδ’ ἄγεσθαι ἐξ αὐτῶν, ἀλλ’ ἐκδίδονταί τε οἱ συβῶται καὶ ἄγονται ἐξ ἀλλήλων. τοῖσι μέν νυν ἄλλοισι θεοῖσι θύειν ὗς οὐ δικαιοῦσι Αἰγύπτιοι, Σελήνῃ δὲ καὶ Διονύσῳ μούνοισι τοῦ αὐτοῦ χρόνου, τῇ αὐτῇ πανσελήνῳ, τοὺς ὗς θύσαντες πατέονται τῶν κρεῶν. διότι δὲ τοὺς ὗς ἐν μὲν τῇσι ἄλλῃσι ὁρτῇσι ἀπεστυγήκασι ἐν δὲ ταύτῃ θύουσι, ἔστι μὲν λόγος περὶ αὐτοῦ ὑπ’ Αἰγυπτίων λεγόμενος, ἐμοὶ μέντοι ἐπισταμένῳ οὐκ εὐπρεπέστερος ἐστὶ λέγεσθαι. θυσίη δὲ ἥδε τῶν ὑῶν τῇ Σελήνῃ ποιέεται· ἐπεὰν θύσῃ, τὴν οὐρὴν ἄκρην καὶ τὸν σπλῆνα καὶ τὸν ἐπίπλοον συνθεὶς ὁμοῦ κατ’ ὦν ἐκάλυψε πάσῃ τοῦ κτήνεος τῇ πιμελῇ τῇ περὶ τὴν νηδὺν γινομένῃ, καὶ ἔπειτα καταγίζει πυρί· τὰ δὲ ἄλλα κρέα σιτέονται ἐν τῇ πανσελήνῳ ἐν τῇ ἂν τὰ ἱρὰ θύσωσι, ἐν ἄλλῃ δὲ ἡμέρῃ οὐκ ἂν ἔτι γευσαίατο. οἱ δὲ πένητες αὐτῶν ὑπ’ ἀσθενείης βίου σταιτίνας πλάσαντες ὗς καὶ ὀπτήσαντες ταύτας θύουσι.", "st": "2.47"}, {"sp": "N", "t": "τῷ δὲ Διονύσῳ τῆς ὁρτῆς τῇ δορπίῃ χοῖρον πρὸ τῶν θυρέων σφάξας ἕκαστος διδοῖ ἀποφέρεσθαι τὸν χοῖρον αὐτῷ τῷ ἀποδομένῳ τῶν συβωτέων. τὴν δὲ ἄλλην ἀνάγουσι ὁρτὴν τῷ Διονύσῳ οἱ Αἰγύπτιοι πλὴν χορῶν κατὰ ταὐτὰ σχεδὸν πάντα Ἕλλησι· ἀντὶ δὲ φαλλῶν ἄλλα σφι ἐστὶ ἐξευρημένα, ὅσον τε πηχυαῖα ἀγάλματα νευρόσπαστα, τὰ περιφορέουσι κατὰ κώμας γυναῖκες, νεῦον τὸ αἰδοῖον, οὐ πολλῷ τεῳ ἔλασσον ἐὸν τοῦ ἄλλου σώματος· προηγέεται δὲ αὐλός, αἳ δὲ ἕπονται ἀείδουσαι τὸν Διόνυσον. διότι δὲ μέζον τε ἔχει τὸ αἰδοῖον καὶ κινέει μοῦνον τοῦ σώματος, ἔστι λόγος περὶ αὐτοῦ ἱρὸς λεγόμενος.", "st": "2.48"}, {"sp": "N", "t": "ἤδη ὦν δοκέει μοι Μελάμπους ὁ Ἀμυθέωνος τῆς θυσίης ταύτης οὐκ εἶναι ἀδαὴς ἀλλ’ ἔμπειρος. Ἕλλησι γὰρ δὴ Μελάμπους ἐστὶ ὁ ἐξηγησάμενος τοῦ Διονύσου τό τε οὔνομα καὶ τὴν θυσίην καὶ τὴν πομπὴν τοῦ φαλλοῦ· ἀτρεκέως μὲν οὐ πάντα συλλαβὼν τὸν λόγον ἔφηνε, ἀλλ’ οἱ ἐπιγενόμενοι τούτῳ σοφισταὶ μεζόνως ἐξέφηναν· τὸν δ’ ὦν φαλλὸν τὸν τῷ Διονύσῳ πεμπόμενον Μελάμπους ἐστὶ ὁ κατηγησάμενος, καὶ ἀπὸ τούτου μαθόντες ποιεῦσι τὰ ποιεῦσι Ἕλληνες. ἐγὼ μέν νυν φημὶ Μελάμποδα γενόμενον ἄνδρα σοφὸν μαντικήν τε ἑωυτῷ συστῆσαι καὶ πυθόμενον ἀπ’ Αἰγύπτου ἄλλα τε πολλὰ ἐσηγήσασθαι Ἕλλησι καὶ τὰ περὶ τὸν Διόνυσον, ὀλίγα αὐτῶν παραλλάξαντα. οὐ γὰρ δὴ συμπεσεῖν γε φήσω τά τε ἐν Αἰγύπτῳ ποιεύμενα τῷ θεῷ καὶ τὰ ἐν τοῖσι Ἕλλησι· ὁμότροπα γὰρ ἂν ἦν τοῖσι Ἕλλησι καὶ οὐ νεωστὶ ἐσηγμένα. οὐ μὲν οὐδὲ φήσω ὅκως Αἰγύπτιοι παρ’ Ἑλλήνων ἔλαβον ἢ τοῦτο ἢ ἄλλο κού τι νόμαιον. πυθέσθαι δέ μοι δοκέει μάλιστα Μελάμπους τὰ περὶ τὸν Διόνυσον παρὰ Κάδμου τε τοῦ Τυρίου καὶ τῶν σὺν αὐτῷ ἐκ Φοινίκης ἀπικομένων ἐς τὴν νῦν Βοιωτίην καλεομένην χώρην.", "st": "2.49"}, {"sp": "N", "t": "σχεδὸν δὲ καὶ πάντων τὰ οὐνόματα τῶν θεῶν ἐξ Αἰγύπτου ἐλήλυθε ἐς τὴν Ἑλλάδα. διότι μὲν γὰρ ἐκ τῶν βαρβάρων ἥκει, πυνθανόμενος οὕτω εὑρίσκω ἐόν· δοκέω δ’ ὦν μάλιστα ἀπ’ Αἰγύπτου ἀπῖχθαι. ὅτι γὰρ δὴ μὴ Ποσειδέωνος καὶ Διοσκούρων, ὡς καὶ πρότερόν μοι ταῦτα εἴρηται, καὶ Ἥρης καὶ Ἱστίης καὶ Θέμιος καὶ Χαρίτων καὶ Νηρηίδων, τῶν ἄλλων θεῶν Αἰγυπτίοισι αἰεί κοτε τὰ οὐνόματα ἐστὶ ἐν τῇ χώρῃ. λέγω δὲ τὰ λέγουσι αὐτοὶ Αἰγύπτιοι. τῶν δὲ οὔ φασι θεῶν γινώσκειν τὰ οὐνόματα, οὗτοι δέ μοι δοκέουσι ὑπὸ Πελασγῶν ὀνομασθῆναι, πλὴν Ποσειδέωνος· τοῦτον δὲ τὸν θεὸν παρὰ Λιβύων ἐπύθοντο· οὐδαμοὶ γὰρ ἀπ’ ἀρχῆς Ποσειδέωνος οὔνομα ἔκτηνται εἰ μὴ Λίβυες καὶ τιμῶσι τὸν θεὸν τοῦτον αἰεί. νομίζουσι δ’ ὦν Αἰγύπτιοι οὐδ’ ἥρωσι οὐδέν.", "st": "2.50"}, {"sp": "N", "t": "ταῦτα μέν νυν καὶ ἄλλα πρὸς τούτοισι, τὰ ἐγὼ φράσω, Ἕλληνες ἀπ’ Αἰγυπτίων νενομίκασι· τοῦ δὲ Ἑρμέω τὰ ἀγάλματα ὀρθὰ ἔχειν τὰ αἰδοῖα ποιεῦντες οὐκ ἀπ’ Αἰγυπτίων μεμαθήκασι, ἀλλ’ ἀπὸ Πελασγῶν πρῶτοι μὲν Ἑλλήνων ἁπάντων Ἀθηναῖοι παραλαβόντες, παρὰ δὲ τούτων ὧλλοι. Ἀθηναίοισι γὰρ ἤδη τηνικαῦτα ἐς Ἕλληνας τελέουσι Πελασγοὶ σύνοικοι ἐγένοντο ἐν τῇ χώρῃ, ὅθεν περ καὶ Ἕλληνες ἤρξαντο νομισθῆναι. ὅστις δὲ τὰ Καβείρων ὄργια μεμύηται, τὰ Σαμοθρήικες ἐπιτελέουσι παραλαβόντες παρὰ Πελασγῶν, οὗτος ὡνὴρ οἶδε τὸ λέγω· τὴν γὰρ Σαμοθρηίκην οἴκεον πρότερον Πελασγοὶ οὗτοι οἵ περ Ἀθηναίοισι σύνοικοι ἐγένοντο, καὶ παρὰ τούτων Σαμοθρήικες τὰ ὄργια παραλαμβάνουσι. ὀρθὰ ὦν ἔχειν τὰ αἰδοῖα τἀγάλματα τοῦ Ἑρμέω Ἀθηναῖοι πρῶτοι Ἑλλήνων μαθόντες παρὰ Πελασγῶν ἐποιήσαντο· οἱ δὲ Πελασγοὶ ἱρόν τινα λόγον περὶ αὐτοῦ ἔλεξαν, τὰ ἐν τοῖσι ἐν Σαμοθρηίκῃ μυστηρίοισι δεδήλωται.", "st": "2.51"}, {"sp": "N", "t": "ἔθυον δὲ πάντα πρότερον οἱ Πελασγοὶ θεοῖσι ἐπευχόμενοι, ὡς ἐγὼ ἐν Δωδώνῃ οἶδα ἀκούσας, ἐπωνυμίην δὲ οὐδ’ οὔνομα ἐποιεῦντο οὐδενὶ αὐτῶν· οὐ γὰρ ἀκηκόεσάν κω. θεοὺς δὲ προσωνόμασαν σφέας ἀπὸ τοῦ τοιούτου, ὅτι κόσμῳ θέντες τὰ πάντα πρήγματα καὶ πάσας νομὰς εἶχον. ἔπειτα δὲ χρόνου πολλοῦ διεξελθόντος ἐπύθοντο ἐκ τῆς Αἰγύπτου ἀπικόμενα τὰ οὐνόματα τῶν θεῶν τῶν ἄλλων, Διονύσου δὲ ὕστερον πολλῷ ἐπύθοντο. καὶ μετὰ χρόνον ἐχρηστηριάζοντο περὶ τῶν οὐνομάτων ἐν Δωδώνῃ· τὸ γὰρ δὴ μαντήιον τοῦτο νενόμισται ἀρχαιότατον τῶν ἐν Ἕλλησι χρηστηρίων εἶναι, καὶ ἦν τὸν χρόνον τοῦτον μοῦνον. ἐπεὶ ὦν ἐχρηστηριάζοντο ἐν τῇ Δωδώνῃ οἱ Πελασγοὶ εἰ ἀνέλωνται τὰ οὐνόματα τὰ ἀπὸ τῶν βαρβάρων ἥκοντα, ἀνεῖλε τὸ μαντήιον χρᾶσθαι. ἀπὸ μὲν δὴ τούτου τοῦ χρόνου ἔθυον τοῖσι οὐνόμασι τῶν θεῶν χρεώμενοι· παρὰ δὲ Πελασγῶν Ἕλληνες ἐξεδέξαντο ὕστερον.", "st": "2.52"}, {"sp": "N", "t": "ἔνθεν δὲ ἐγένοντο ἕκαστος τῶν θεῶν, εἴτε αἰεὶ ἦσαν πάντες, ὁκοῖοί τε τινὲς τὰ εἴδεα, οὐκ ἠπιστέατο μέχρι οὗ πρώην τε καὶ χθὲς ὡς εἰπεῖν λόγῳ. Ἡσίοδον γὰρ καὶ Ὅμηρον ἡλικίην τετρακοσίοισι ἔτεσι δοκέω μευ πρεσβυτέρους γενέσθαι καὶ οὐ πλέοσι· οὗτοι δὲ εἰσὶ οἱ ποιήσαντες θεογονίην Ἕλλησι καὶ τοῖσι θεοῖσι τὰς ἐπωνυμίας δόντες καὶ τιμάς τε καὶ τέχνας διελόντες καὶ εἴδεα αὐτῶν σημήναντες. οἱ δὲ πρότερον ποιηταὶ λεγόμενοι τούτων τῶν ἀνδρῶν γενέσθαι ὕστερον, ἔμοιγε δοκέειν, ἐγένοντο. τούτων τὰ μὲν πρῶτα αἱ Δωδωνίδες ἱρεῖαι λέγουσι, τὰ δὲ ὕστερα τὰ ἐς Ἡσίοδόν τε καὶ Ὅμηρον ἔχοντα ἐγὼ λέγω.", "st": "2.53"}, {"sp": "N", "t": "χρηστηρίων δὲ πέρι τοῦ τε ἐν Ἕλλησι καὶ τοῦ ἐν Λιβύῃ τόνδε Αἰγύπτιοι λόγον λέγουσι. ἔφασαν οἱ ἱρέες τοῦ Θηβαιέος Διὸς δύο γυναῖκας ἱρείας ἐκ Θηβέων ἐξαχθῆναι ὑπὸ Φοινίκων, καὶ τὴν μὲν αὐτέων πυθέσθαι ἐς Λιβύην πρηθεῖσαν τὴν δὲ ἐς τοὺς Ἕλληνας· ταύτας δὲ τὰς γυναῖκας εἶναι τὰς ἱδρυσαμένας τὰ μαντήια πρώτας ἐν τοῖσι εἰρημένοισι ἔθνεσι. εἰρομένου δέ μευ ὁκόθεν οὕτω ἀτρεκέως ἐπιστάμενοι λέγουσι, ἔφασαν πρὸς ταῦτα ζήτησιν μεγάλην ἀπὸ σφέων γενέσθαι τῶν γυναικῶν τουτέων, καὶ ἀνευρεῖν μὲν σφέας οὐ δυνατοὶ γενέσθαι, πυθέσθαι δὲ ὕστερον ταῦτα περὶ αὐτέων τά περ δὴ ἔλεγον.", "st": "2.54"}, {"sp": "N", "t": "ταῦτα μέν νυν τῶν ἐν Θήβῃσι ἱρέων ἤκουον, τάδε δὲ Δωδωναίων φασὶ αἱ προμάντιες· δύο πελειάδας μελαίνας ἐκ Θηβέων τῶν Αἰγυπτιέων ἀναπταμένας τὴν μὲν αὐτέων ἐς Λιβύην τὴν δὲ παρὰ σφέας ἀπικέσθαι, ἱζομένην δέ μιν ἐπὶ φηγὸν αὐδάξασθαι φωνῇ ἀνθρωπηίῃ ὡς χρεὸν εἴη μαντήιον αὐτόθι Διὸς γενέσθαι, καὶ αὐτοὺς ὑπολαβεῖν θεῖον εἶναι τὸ ἐπαγγελλόμενον αὐτοῖσι, καί σφεας ἐκ τούτου ποιῆσαι. τὴν δὲ ἐς τοὺς Λίβυας οἰχομένην πελειάδα λέγουσι Ἄμμωνος χρηστήριον κελεῦσαι τοὺς Λίβυας ποιέειν· ἔστι δὲ καὶ τοῦτο Διός. Δωδωναίων δὲ αἱ ἱρεῖαι, τῶν τῇ πρεσβυτάτῃ οὔνομα ἦν Προμένεια, τῇ δὲ μετὰ ταύτην Τιμαρέτη, τῇ δὲ νεωτάτῃ Νικάνδρη, ἔλεγον ταῦτα· συνωμολόγεον δέ σφι καὶ οἱ ἄλλοι Δωδωναῖοι οἱ περὶ τὸ ἱρόν.", "st": "2.55"}, {"sp": "N", "t": "ἐγὼ δ’ ἔχω περὶ αὐτῶν γνώμην τήνδε· εἰ ἀληθέως οἱ Φοίνικες ἐξήγαγον τὰς ἱρὰς γυναῖκας καὶ τὴν μὲν αὐτέων ἐς Λιβύην τὴν δὲ ἐς τὴν Ἐλλάδα ἀπέδοντο, δοκέει ἐμοί ἡ γυνὴ αὕτη τῆς νῦν Ἑλλάδος, πρότερον δὲ Πελασγίης καλευμένης τῆς αὐτῆς ταύτης, πρηθῆναι ἐς Θεσπρωτούς, ἔπειτα δουλεύουσα αὐτόθι ἱδρύσασθαι ὑπὸ φηγῷ πεφυκυίῃ ἱρὸν Διός, ὥσπερ ἦν οἰκὸς ἀμφιπολεύουσαν ἐν Θήβῃσι ἱρὸν Διός, ἔνθα ἀπίκετο, ἐνθαῦτα μνήμην αὐτοῦ ἔχειν· ἐκ δὲ τούτου χρηστήριον κατηγήσατο, ἐπείτε συνέλαβε τὴν Ἑλλάδα γλῶσσαν· φάναι δέ οἱ ἀδελφεὴν ἐν Λιβύῃ πεπρῆσθαι ὑπὸ τῶν αὐτῶν Φοινίκων ὑπ’ ὧν καὶ αὐτὴ ἐπρήθη.", "st": "2.56"}, {"sp": "N", "t": "πελειάδες δέ μοι δοκέουσι κληθῆναι πρὸς Δωδωναίων ἐπὶ τοῦδε αἱ γυναῖκες, διότι βάρβαροι ἦσαν, ἐδόκεον δέ σφι ὁμοίως ὄρνισι φθέγγεσθαι· μετὰ δὲ χρόνον τὴν πελειάδα ἀνθρωπηίῃ φωνῇ αὐδάξασθαι λέγουσι, ἐπείτε συνετά σφι ηὔδα ἡ γυνή· ἕως δὲ ἐβαρβάριζε, ὄρνιθος τρόπον ἐδόκεέ σφι φθέγγεσθαι, ἐπεὶ τέῳ ἂν τρόπῳ πελειάς γε ἀνθρωπηίῃ φωνῇ φθέγξαιτο; μέλαιναν δὲ λέγοντες εἶναι τὴν πελειάδα σημαίνουσι ὅτι Αἰγυπτίη ἡ γυνὴ ἦν. ἡ δὲ μαντηίη ἥ τε ἐν Θήβῃσι τῇσι Αἰγυπτίῃσι καὶ ἐν Δωδώνῃ παραπλήσιαι ἀλλήλῃσι τυγχάνουσι ἐοῦσαι. ἔστι δὲ καὶ τῶν ἱρῶν ἡ μαντικὴ ἀπ’ Αἰγύπτου ἀπιγμένη.", "st": "2.57"}, {"sp": "N", "t": "πανηγύρις δὲ ἄρα καὶ πομπὰς καὶ προσαγωγὰς πρῶτοι ἀνθρώπων Αἰγύπτιοι εἰσὶ οἱ ποιησάμενοι, καὶ παρὰ τούτων Ἕλληνες μεμαθήκασι. τεκμήριον δέ μοι τούτου τόδε· αἱ μὲν γὰρ φαίνονται ἐκ πολλοῦ τευ χρόνου ποιεύμεναι, αἱ δὲ Ἑλληνικαὶ νεωστὶ ἐποιήθησαν.", "st": "2.58"}, {"sp": "N", "t": "πανηγυρίζουσι δὲ Αἰγύπτιοι οὐκ ἅπαξ τοῦ ἐνιαυτοῦ, πανηγύρις δὲ συχνάς, μάλιστα μὲν καὶ προθυμότατα ἐς Βούβαστιν πόλιν τῇ Ἀρτέμιδι, δεύτερα δὲ ἐς Βούσιριν πόλιν τῇ Ἴσι· ἐν ταύτῃ γὰρ δὴ τῇ πόλι ἐστὶ μέγιστον Ἴσιος ἱρόν, ἵδρυται δὲ ἡ πόλις αὕτη τῆς Αἰγύπτου ἐν μέσῳ τῷ Δέλτα· Ἶσις δὲ ἐστὶ κατὰ τὴν Ἑλλήνων γλῶσσαν Δημήτηρ. τρίτα δὲ ἐς Σάιν πόλιν τῇ Ἀθηναίῃ πανηγυρίζουσι, τέταρτα δὲ ἐς Ἡλίου πόλιν τῷ Ἡλίω, πέμπτα δὲ ἐς Βουτοῦν πόλιν τῇ Λητοῖ, ἕκτα δὲ ἐς Πάπρημιν πόλιν τῷ Ἄρεϊ.", "st": "2.59"}, {"sp": "N", "t": "ἐς μέν νυν Βούβαστιν πόλιν ἐπεὰν κομίζωνται, ποιεῦσι τοιάδε. πλέουσί τε γὰρ δὴ ἅμα ἄνδρες γυναιξὶ καὶ πολλόν τι πλῆθος ἑκατέρων ἐν ἑκάστῃ βάρι· αἳ μὲν τινὲς τῶν γυναικῶν κρόταλα ἔχουσαι κροταλίζουσι, οἳ δὲ αὐλέουσι κατὰ πάντα τὸν πλόον, αἱ δὲ λοιπαὶ γυναῖκες καὶ ἄνδρες ἀείδουσι καὶ τὰς χεῖρας κροτέουσι. ἐπεὰν δὲ πλέοντες κατά τινα πόλιν ἄλλην γένωνται, ἐγχρίμψαντες τὴν βᾶριν τῇ γῇ ποιεῦσι τοιάδε· αἳ μὲν τινὲς τῶν γυναικῶν ποιεῦσι τά περ εἴρηκα, αἳ δὲ τωθάζουσι βοῶσαι τὰς ἐν τῇ πόλι ταύτῃ γυναῖκας, αἳ δὲ ὀρχέονται, αἳ δὲ ἀνασύρονται ἀνιστάμεναι. ταῦτα παρὰ πᾶσαν πόλιν παραποταμίην ποιεῦσι· ἐπεὰν δὲ ἀπίκωνται ἐς τὴν Βούβαστιν, ὁρτάζουσι μεγάλας ἀνάγοντες θυσίας, καὶ οἶνος ἀμπέλινος ἀναισιμοῦται πλέων ἐν τῇ ὁρτῇ ταύτῃ ἢ ἐν τῷ ἅπαντι ἐνιαυτῷ τῷ ἐπιλοίπῳ. συμφοιτῶσι δέ, ὅ τι ἀνὴρ καὶ γυνή ἐστι πλὴν παιδίων, καὶ ἐς ἑβδομήκοντα μυριάδας, ὡς οἱ ἐπιχώριοι λέγουσι.", "st": "2.60"}, {"sp": "N", "t": "ταῦτα μὲν δὴ ταύτῃ ποιέεται, ἐν δὲ Βουσίρι πόλι ὡς ἀνάγουσι τῇ Ἴσι τὴν ὁρτήν, εἴρηται πρότερόν μοι· τύπτονται μὲν γὰρ δὴ μετὰ τὴν θυσίην πάντες καὶ πᾶσαι, μυριάδες κάρτα πολλαὶ ἀνθρώπων· τὸν δὲ τύπτονται, οὔ μοι ὅσιον ἐστὶ λέγειν. ὅσοι δὲ Καρῶν εἰσι ἐν Αἰγύπτῳ οἰκέοντες, οὗτοι δὲ τοσούτῳ ἔτι πλέω ποιεῦσι τούτων ὅσῳ καὶ τὰ μέτωπα κόπτονται μαχαίρῃσι, καὶ τούτῳ εἰσὶ δῆλοι ὅτι εἰσὶ ξεῖνοι καὶ οὐκ Αἰγύπτιοι.", "st": "2.61"}, {"sp": "N", "t": "ἐς Σάιν δὲ πόλιν ἐπεὰν συλλεχθέωσι, τῆς θυσίης ἐν τῇ νυκτὶ λύχνα καίουσι πάντες πολλὰ ὑπαίθρια περὶ τὰ δώματα κύκλῳ· τὰ δὲ λύχνα ἐστὶ ἐμβάφια ἔμπλεα ἁλὸς καὶ ἐλαίου, ἐπιπολῆς δὲ ἔπεστι αὐτὸ τὸ ἐλλύχνιον, καὶ τοῦτο καίεται παννύχιον, καὶ τῇ ὁρτῇ οὔνομα κέεται λυχνοκαΐη. οἳ δ’ ἂν μὴ ἔλθωσι τῶν Αἰγυπτίων ἐς τὴν πανήγυριν ταύτην, φυλάσσοντες τὴν νύκτα τῆς θυσίης καίουσι καὶ αὐτοὶ πάντες τὰ λύχνα, καὶ οὕτω οὐκ ἐν Σάι μούνῃ καίεται ἀλλὰ καὶ ἀνὰ πᾶσαν Αἴγυπτον. ὅτευ δὲ εἵνεκα φῶς ἔλαχε καὶ τιμὴν ἡ νὺξ αὕτη, ἔστι ἱρὸς περὶ αὐτοῦ λόγος λεγόμενος.", "st": "2.62"}, {"sp": "N", "t": "ἐς δὲ Ἡλίου τε πόλιν καὶ Βουτοῦν θυσίας μούνας ἐπιτελέουσι φοιτέοντες. ἐν δὲ Παπρήμι θυσίας μὲν καὶ ἱρὰ κατά περ καὶ τῇ ἄλλῃ ποιεῦσι· εὖτ’ ἂν δὲ γίνηται καταφερὴς ὁ ἥλιος, ὀλίγοι μὲν τινὲς τῶν ἱρέων περὶ τὤγαλμα πεπονέαται, οἱ δὲ πολλοὶ αὐτῶν ξύλων κορύνας ἔχοντες ἑστᾶσι τοῦ ἱροῦ ἐν τῇ ἐσόδῳ, ἄλλοι τε εὐχωλὰς ἐπιτελέοντες πλεῦνες χιλίων ἀνδρῶν, ἕκαστοι ἔχοντες ξύλα καὶ οὗτοι, ἐπὶ τὰ ἕτερα ἁλέες ἑστᾶσι. τὸ δὲ ἄγαλμα ἐὸν ἐν νηῷ μικρῷ ξυλίνῳ κατακεχρυσωμένῳ προεκκομίζουσι τῇ προτεραίῃ ἐς ἄλλο οἴκημα ἱρόν. οἱ μὲν δὴ ὀλίγοι οἱ περὶ τὤγαλμα λελειμμένοι ἕλκουσι τετράκυκλον ἅμαξαν ἄγουσαν τὸν νηόν τε καὶ τὸ ἐν τῷ νηῷ ἐνεὸν ἄγαλμα, οἳ δὲ οὐκ ἐῶσι ἐν τοῖσι προπυλαίοισι ἑστεῶτες ἐσιέναι, οἱ δὲ εὐχωλιμαῖοι τιμωρέοντες τῷ θεῷ παίουσι αὐτοὺς ἀλεξομένους. ἐνθαῦτα μάχη ξύλοισι καρτερὴ γίνεται κεφαλάς τε συναράσσονται, καὶ ὡς ἐγὼ δοκέω πολλοὶ καὶ ἀποθνήσκουσι ἐκ τῶν τρωμάτων· οὐ μέντοι οἵ γε Αἰγύπτιοι ἔφασαν ἀποθνήσκειν οὐδένα. τὴν δὲ πανήγυριν ταύτην ἐκ τοῦδε νομίσαι φασὶ οἱ ἐπιχώριοι· οἰκέειν ἐν τῷ ἱρῷ τούτῳ τοῦ Ἄρεος τὴν μητέρα, καὶ τὸν Ἄρεα ἀπότροφον γενόμενον ἐλθεῖν ἐξανδρωμένον ἐθέλοντα τῇ μητρὶ συμμῖξαι, καὶ τοὺς προπόλους τῆς μητρός, οἷα οὐκ ὀπωπότας αὐτὸν πρότερον, οὐ περιορᾶν παριέναι ἀλλὰ ἀπερύκειν, τὸν δὲ ἐξ ἄλλης πόλιος ἀγαγόμενον ἀνθρώπους τούς τε προπόλους τρηχέως περισπεῖν καὶ ἐσελθεῖν παρὰ τὴν μητέρα. ἀπὸ τούτου τῷ Ἄρεϊ ταύτην τὴν πληγὴν ἐν τῇ ὁρτῇ νενομικέναι φασί.", "st": "2.63"}, {"sp": "N", "t": "καὶ τὸ μὴ μίσγεσθαι γυναιξὶ ἐν ἱροῖσι μηδὲ ἀλούτους ἀπὸ γυναικῶν ἐς ἱρὰ ἐσιέναι οὗτοι εἰσὶ οἱ πρῶτοι θρησκεύσαντες. οἱ μὲν γὰρ ἄλλοι σχεδὸν πάντες ἄνθρωποι, πλὴν Αἰγυπτίων καὶ Ἑλλήνων, μίσγονται ἐν ἱροῖσι καὶ ἀπὸ γυναικῶν ἀνιστάμενοι ἄλουτοι ἐσέρχονται ἐς ἱρόν, νομίζοντες ἀνθρώπους εἶναι κατά περ τὰ ἄλλα κτήνεα· καὶ γὰρ τὰ ἄλλα κτήνεα ὁρᾶν καὶ ὀρνίθων γένεα ὀχευόμενα ἔν τε τοῖσι νηοῖσι τῶν θεῶν καὶ ἐν τοῖσι τεμένεσι· εἰ ὦν εἶναι τῷ θεῷ τοῦτο μὴ φίλον, οὐκ ἂν οὐδὲ τὰ κτήνεα ποιέειν. οὗτοι μέν νυν τοιαῦτα ἐπιλέγοντες ποιεῦσι ἔμοιγε οὐκ ἀρεστά·", "st": "2.64"}, {"sp": "N", "t": "Αἰγύπτιοι δὲ θρησκεύουσι περισσῶς τά τε ἄλλα περὶ τὰ ἱρὰ καὶ δὴ καὶ τάδε. ἐοῦσα ἡ Αἴγυπτος ὅμουρος τῇ Λιβύῃ οὐ μάλα θηριώδης ἐστί· τὰ δὲ ἐόντα σφι ἅπαντα ἱρὰ νενόμισται, καὶ τὰ μὲν σύντροφα αὐτοῖσι τοῖσι ἀνθρώποισι, τὰ δὲ οὔ. τῶν δὲ εἵνεκεν ἀνεῖται τὰ θηρία ἱρὰ εἰ λέγοιμι, καταβαίην ἂν τῷ λόγῳ ἐς τὰ θεῖα πρήγματα, τὰ ἐγὼ φεύγω μάλιστα ἀπηγέεσθαι· τὰ δὲ καὶ εἴρηκα αὐτῶν ἐπιψαύσας, ἀναγκαίῃ καταλαμβανόμενος εἶπον. νόμος δὲ ἐστὶ περὶ τῶν θηρίων ὧδε ἔχων· μελεδωνοὶ ἀποδεδέχαται τῆς τροφῆς χωρὶς ἑκάστων καὶ ἔρσενες καὶ θήλεαι τῶν Αἰγυπτίων, τῶν παῖς παρὰ πατρὸς ἐκδέκεται τὴν τιμήν. οἳ δὲ ἐν τῇσι πόλισι ἕκαστοι εὐχὰς τάσδε σφι ἀποτελέουσι· εὐχόμενοι τῷ θεῷ τοῦ ἂν ᾖ τὸ θηρίον, ξυρῶντες τῶν παιδίων ἢ πᾶσαν τὴν κεφαλὴν ἢ τὸ ἥμισυ ἢ τὸ τρίτον μέρος τῆς κεφαλῆς, ἱστᾶσι σταθμῷ πρὸς ἀργύριον τὰς τρίχας· τὸ δ’ ἂν ἑλκύσῃ, τοῦτο τῇ μελεδωνῷ τῶν θηρίων διδοῖ, ἣ δὲ ἀντ’ αὐτοῦ τάμνουσα ἰχθῦς παρέχει βορὴν τοῖσι θηρίοισι. τροφὴ μὲν δὴ αὐτοῖσι τοιαύτη ἀποδέδεκται· τὸ δ’ ἄν τις τῶν θηρίων τούτων ἀποκτείνῃ, ἢν μὲν ἑκών, θάνατος ἡ ζημίη, ἢν δὲ ἀέκων, ἀποτίνει ζημίην τὴν ἂν οἱ ἱρέες τάξωνται. ὃς δ’ ἂν ἶβιν ἢ ἴρηκα ἀποκτείνῃ, ἤν τε ἑκὼν ἤν τε ἀέκων, τεθνάναι ἀνάγκη.", "st": "2.65"}, {"sp": "N", "t": "πολλῶν δὲ ἐόντων ὁμοτρόφων τοῖσι ἀνθρώποισι θηρίων πολλῷ ἂν ἔτι πλέω ἐγίνετο, εἰ μὴ κατελάμβανε τοὺς αἰελούρους τοιάδε· ἐπεὰν τέκωσι αἱ θήλεαι, οὐκέτι φοιτέουσι παρὰ τοὺς ἔρσενας· οἳ δὲ διζήμενοι μίσγεσθαι αὐτῇσι οὐκ ἔχουσι. πρὸς ὦν ταῦτα σοφίζονται τάδε· ἁρπάζοντες ἀπὸ τῶν θηλέων καὶ ὑπαιρεόμενοι τὰ τέκνα κτείνουσι, κτείναντες μέντοι οὐ πατέονται· αἳ δὲ στερισκόμεναι τῶν τέκνων, ἄλλων δὲ ἐπιθυμέουσαι, οὕτω δὴ ἀπικνέονται παρὰ τοὺς ἔρσενας· φιλότεκνον γὰρ τὸ θηρίον. πυρκαϊῆς δὲ γενομένης θεῖα πρήγματα καταλαμβάνει τοὺς αἰελούρους· οἱ μὲν γὰρ Αἰγύπτιοι διαστάντες φυλακὰς ἔχουσι τῶν αἰελούρων, ἀμελήσαντες σβεννύναι τὸ καιόμενον, οἱ δὲ αἰέλουροι διαδύνοντες καὶ ὑπερθρώσκοντες τοὺς ἀνθρώπους ἐσάλλονται ἐς τὸ πῦρ. ταῦτα δὲ γινόμενα πένθεα μεγάλα τοὺς Αἰγυπτίους καταλαμβάνει. ἐν ὁτέοισι δ’ ἂν οἰκίοισι αἰέλουρος ἀποθάνῃ ἀπὸ τοῦ αὐτομάτου, οἱ ἐνοικέοντες πάντες ξυρῶνται τὰς ὀφρύας μούνας, παρ’ ὁτέοισι δ’ ἂν κύων, πᾶν τὸ σῶμα καὶ τὴν κεφαλήν.", "st": "2.66"}, {"sp": "N", "t": "ἀπάγονται δὲ οἱ αἰέλουροι ἀποφανόντες ἐς ἱρὰς στέγας, ἔνθα θάπτονται ταριχευθέντες, ἐν Βουβάστι πόλι· τὰς δὲ κύνας ἐν τῇ ἑωυτῶν ἕκαστοι πόλι θάπτουσι ἐν ἱρῇσι θήκῃσι. ὣς δὲ αὕτως τῇσι κυσὶ οἱ ἰχνευταὶ θάπτονται. τὰς δὲ μυγαλᾶς καὶ τοὺς ἴρηκας ἀπάγουσι ἐς Βουτοῦν πόλιν, τὰς δὲ ἴβις ἐς Ἑρμέω πόλιν. τὰς δὲ ἄρκτους ἐούσας σπανίας καὶ τοὺς λύκους οὐ πολλῷ τεῳ ἐόντας ἀλωπέκων μέζονας αὐτοῦ θάπτουσι τῇ ἂν εὑρεθέωσι κείμενοι.", "st": "2.67"}, {"sp": "N", "t": "τῶν δὲ κροκοδείλων φύσις ἐστὶ τοιήδε. τοὺς χειμεριωτάτους μῆνας τέσσερας ἐσθίει οὐδέν, ἐὸν δὲ τετράπουν χερσαῖον καὶ λιμναῖον ἐστί. τίκτει μὲν γὰρ ᾠὰ ἐν γῇ καὶ ἐκλέπει, καὶ τὸ πολλὸν τῆς ἡμέρης διατρίβει ἐν τῷ ξηρῷ, τὴν δὲ νύκτα πᾶσαν ἐν τῷ ποταμῷ· θερμότερον γὰρ δή ἐστι τὸ ὕδωρ τῆς τε αἰθρίης καὶ τῆς δρόσου. πάντων δὲ τῶν ἡμεῖς ἴδμεν θνητῶν τοῦτο ἐξ ἐλαχίστου μέγιστον γίνεται· τὰ μὲν γὰρ ᾠὰ χηνέων οὐ πολλῷ μέζονα τίκτει, καὶ ὁ νεοσσὸς κατὰ λόγον τοῦ ᾠοῦ γίνεται, αὐξανόμενος δὲ γίνεται καὶ ἐς ἑπτακαίδεκα πήχεας καὶ μέζων ἔτι. ἔχει δὲ ὀφθαλμοὺς μὲν ὑός, ὀδόντας δὲ μεγάλους καὶ χαυλιόδοντας κατὰ λόγον τοῦ σώματος. γλῶσσαν δὲ μοῦνον θηρίων οὐκ ἔφυσε, οὐδὲ κινέει τὴν κάτω γνάθον, ἀλλὰ καὶ τοῦτο μοῦνον θηρίων τὴν ἄνω γνάθον προσάγει τῇ κάτω. ἔχει δὲ καὶ ὄνυχας καρτεροὺς καὶ δέρμα λεπιδωτὸν ἄρρηκτον ἐπὶ τοῦ νώτου. τυφλὸν δὲ ἐν ὕδατι, ἐν δὲ τῇ αἰθρίῃ ὀξυδερκέστατον. ἅτε δὴ ὦν ἐν ὕδατι δίαιταν ποιεύμενον, τὸ στόμα ἔνδοθεν φορέει πᾶν μεστὸν βδελλέων. τὰ μὲν δὴ ἄλλα ὄρνεα καὶ θηρία φεύγει μιν, ὁ δὲ τροχίλος εἰρηναῖόν οἱ ἐστὶ ἅτε ὠφελεομένῳ πρὸς αὐτοῦ· ἐπεὰν γὰρ ἐς τὴν γῆν ἐκβῇ ἐκ τοῦ ὕδατος ὁ κροκόδειλος καὶ ἔπειτα χάνῃ (ἔωθε γὰρ τοῦτο ὡς ἐπίπαν ποιέειν πρὸς τὸν ζέφυρον), ἐνθαῦτα ὁ τροχίλος ἐσδύνων ἐς τὸ στόμα αὐτοῦ καταπίνει τὰς βδέλλας· ὁ δὲ ὠφελεύμενος ἥδεται καὶ οὐδὲν σίνεται τὸν τροχίλον.", "st": "2.68"}, {"sp": "N", "t": "τοῖσι μὲν δὴ τῶν Αἰγυπτίων ἱροί εἰσι οἱ κροκόδειλοι, τοῖσι δὲ οὔ, ἀλλ’ ἅτε πολεμίους περιέπουσι· οἱ δὲ περί τε Θήβας καὶ τὴν Μοίριος λίμνην οἰκέοντες καὶ κάρτα ἥγηνται αὐτοὺς εἶναι ἱρούς· ἐκ πάντων δὲ ἕνα ἑκάτεροι τρέφουσι κροκόδειλον δεδιδαγμένον εἶναι χειροήθεα, ἀρτήματά τε λίθινα χυτὰ καὶ χρύσεα ἐς τὰ ὦτα ἐνθέντες καὶ ἀμφιδέας περὶ τοὺς ἐμπροσθίους πόδας, καὶ σιτία ἀποτακτὰ διδόντες καὶ ἱρήια, καὶ περιέποντες ὡς κάλλιστα ζῶντας· ἀποθανόντας δὲ θάπτουσι ταριχεύσαντες ἐν ἱρῇσι θήκῃσι. οἱ δὲ περὶ Ἐλεφαντίνην πόλιν οἰκέοντες καὶ ἐσθίουσι αὐτοὺς οὐκ ἡγεόμενοι ἱροὺς εἶναι. καλέονται δὲ οὐ κροκόδειλοι ἀλλὰ χάμψαι· κροκοδείλους δὲ Ἴωνες ὠνόμασαν, εἰκάζοντες αὐτῶν τὰ εἴδεα τοῖσι παρὰ σφίσι γινομένοισι κροκοδείλοισι τοῖσι ἐν τῇσι αἱμασιῇσι.", "st": "2.69"}, {"sp": "N", "t": "ἄγραι δὲ σφέων πολλαὶ κατεστᾶσι καὶ παντοῖαι· ἣ δ’ ὦν ἔμοιγε δοκέει ἀξιωτάτη ἀπηγήσιος εἶναι, ταύτην γράφω. ἐπεὰν νῶτον ὑὸς δελεάσῃ περὶ ἄγκιστρον, μετιεῖ ἐς μέσον τὸν ποταμόν, αὐτὸς δὲ ἐπὶ τοῦ χείλεος τοῦ ποταμοῦ ἔχων δέλφακα ζωὴν ταύτην τύπτει. ἐπακούσας δὲ τῆς φωνῆς ὁ κροκόδειλος ἵεται κατὰ τὴν φωνήν, ἐντυχὼν δὲ τῷ νώτῳ καταπίνει· οἳ δὲ ἕλκουσι. ἐπεὰν δὲ ἐξελκυσθῇ ἐς γῆν, πρῶτον ἁπάντων ὁ θηρευτὴς πηλῷ κατ’ ὦν ἔπλασε αὐτοῦ τοὺς ὀφθαλμούς· τοῦτο δὲ ποιήσας κάρτα εὐπετέως τὰ λοιπὰ χειροῦται, μὴ ποιήσας δὲ τοῦτο σὺν πόνῳ.", "st": "2.70"}, {"sp": "N", "t": "οἱ δὲ ἵπποι οἱ ποτάμιοι νομῷ μὲν τῷ Παπρημίτῃ ἱροί εἰσι, τοῖσι δὲ ἄλλοισι Αἰγυπτίοισι οὐκ ἱροί. φύσιν δὲ παρέχονται ἰδέης τοιήνδε· τετράπουν ἐστί, δίχηλον, ὁπλαὶ βοός, σιμόν, λοφιὴν ἔχον ἵππου, χαυλιόδοντας φαῖνον, οὐρὴν ἵππου καὶ φωνήν, μέγαθος ὅσον τε βοῦς ὁ μέγιστος· τὸ δέρμα δ’ αὐτοῦ οὕτω δή τι παχύ ἐστι ὥστε αὔου γενομένου ξυστὰ ποιέεσθαι ἀκόντια ἐξ αὐτοῦ.", "st": "2.71"}, {"sp": "N", "t": "γίνονται δὲ καὶ ἐνύδριες ἐν τῷ ποταμῷ, τὰς ἱρὰς ἥγηνται εἶναι. νομίζουσι δὲ καὶ τῶν ἰχθύων τὸν καλεύμενον λεπιδωτὸν ἱρὸν εἶναι καὶ τὴν ἔγχελυν, ἱροὺς δὲ τούτους τοῦ Νείλου φασὶ εἶναι, καὶ τῶν ὀρνίθων τοὺς χηναλώπεκας.", "st": "2.72"}, {"sp": "N", "t": "ἔστι δὲ καὶ ἄλλος ὄρνις ἱρός, τῷ οὔνομα φοῖνιξ. ἐγὼ μέν μιν οὐκ εἶδον εἰ μὴ ὅσον γραφῇ· καὶ γὰρ δὴ καὶ σπάνιος ἐπιφοιτᾷ σφι, δι’ ἐτέων, ὡς Ἡλιοπολῖται λέγουσι, πεντακοσίων· φοιτᾶν δὲ τότε φασὶ ἐπεάν οἱ ἀποθάνῃ ὁ πατήρ. ἔστι δέ, εἰ τῇ γραφῇ παρόμοιος, τοσόσδε καὶ τοιόσδε· τὰ μὲν αὐτοῦ χρυσόκομα τῶν πτερῶν τὰ δὲ ἐρυθρὰ ἐς τὰ μάλιστα· αἰετῷ περιήγησιν ὁμοιότατος καὶ τὸ μέγαθος. τοῦτον δὲ λέγουσι μηχανᾶσθαι τάδε, ἐμοὶ μὲν οὐ πιστὰ λέγοντες· ἐξ Ἀραβίης ὁρμώμενον ἐς τὸ ἱρὸν τοῦ Ἡλίου κομίζειν τὸν πατέρα ἐν σμύρνῃ ἐμπλάσσοντα καὶ θάπτειν ἐν τοῦ Ἡλίου τῷ ἱρῷ, κομίζειν δὲ οὕτω· πρῶτον τῆς σμύρνης ᾠὸν πλάσσειν ὅσον τε δυνατός ἐστι φέρειν, μετὰ δὲ πειρᾶσθαι αὐτὸ φορέοντα, ἐπεὰν δὲ ἀποπειρηθῇ, οὕτω δὴ κοιλήναντα τὸ ᾠὸν τὸν πατέρα ἐς αὐτὸ ἐντιθέναι, σμύρνῃ δὲ ἄλλῃ ἐμπλάσσειν τοῦτο κατ’ ὅ τι τοῦ ᾠοῦ ἐκκοιλήνας ἐνέθηκε τὸν πατέρα· ἐσκειμένου δὲ τοῦ πατρὸς γίνεσθαι τὠυτὸ βάρος· ἐμπλάσαντα δὲ κομίζειν μιν ἐπ’ Αἰγύπτου ἐς τοῦ Ἡλίου τὸ ἱρόν. ταῦτα μὲν τοῦτον τὸν ὄρνιν λέγουσι ποιέειν.", "st": "2.73"}, {"sp": "N", "t": "εἰσὶ δὲ περὶ Θήβας ἱροὶ ὄφιες, ἀνθρώπων οὐδαμῶς δηλήμονες, οἳ μεγάθεϊ ἐόντες μικροὶ δύο κέρεα φορέουσι πεφυκότα ἐξ ἄκρης τῆς κεφαλῆς· τοὺς θάπτουσι ἀποθανόντας ἐν τῷ ἱρῷ τοῦ Διός· τούτου γὰρ σφέας τοῦ θεοῦ φασι εἶναι ἱρούς.", "st": "2.74"}, {"sp": "N", "t": "ἔστι δὲ χῶρος τῆς Ἀραβίης κατὰ Βουτοῦν πόλιν μάλιστά κῃ κείμενος, καὶ ἐς τοῦτο τὸ χωρίον ἦλθον πυνθανόμενος περὶ τῶν πτερωτῶν ὀφίων· ἀπικόμενος δὲ εἶδον ὀστέα ὀφίων καὶ ἀκάνθας πλήθεϊ μὲν ἀδύνατα ἀπηγήσασθαι, σωροὶ δὲ ἦσαν ἀκανθέων καὶ μεγάλοι καὶ ὑποδεέστεροι καὶ ἐλάσσονες ἔτι τούτων, πολλοὶ δὲ ἦσαν οὗτοι. ἔστι δὲ ὁ χῶρος οὗτος, ἐν τῷ αἱ ἄκανθαι κατακεχύαται, τοιόσδε τις, ἐσβολὴ ἐξ ὀρέων στεινῶν ἐς πεδίον μέγα, τὸ δὲ πεδίον τοῦτο συνάπτει τῷ Αἰγυπτίῳ πεδίῳ. λόγος δὲ ἐστὶ ἅμα τῷ ἔαρι πτερωτοὺς ὄφις ἐκ τῆς Ἀραβίης πέτεσθαι ἐπ’ Αἰγύπτου, τὰς δὲ ἴβις τὰς ὄρνιθας ἀπαντώσας ἐς τὴν ἐσβολὴν ταύτης τῆς χώρης οὐ παριέναι τοὺς ὄφις ἀλλὰ κατακτείνειν. καὶ τὴν ἶβιν διὰ τοῦτο τὸ ἔργον τετιμῆσθαι λέγουσι Ἀράβιοι μεγάλως πρὸς Αἰγυπτίων· ὁμολογέουσι δὲ καὶ Αἰγύπτιοι διὰ ταῦτα τιμᾶν τὰς ὄρνιθας ταύτας.", "st": "2.75"}, {"sp": "N", "t": "εἶδος δὲ τῆς μὲν ἴβιος τόδε· μέλαινα δεινῶς πᾶσα, σκέλεα δὲ φορέει γεράνου, πρόσωπον δὲ ἐς τὰ μάλιστα ἐπίγρυπον, μέγαθος ὅσον κρέξ. τῶν μὲν δὴ μελαινέων τῶν μαχομενέων πρὸς τοὺς ὄφις ἥδε ἰδέη, τῶν δ’ ἐν ποσὶ μᾶλλον εἱλευμενέων τοῖσι ἀνθρώποισι (διξαὶ γὰρ δή εἰσι ἴβιες) ψιλὴ τὴν κεφαλὴν καὶ τὴν δειρὴν πᾶσαν, λευκὴ πτεροῖσι πλὴν κεφαλῆς καὶ αὐχένος καὶ ἀκρέων τῶν πτερύγων καὶ τοῦ πυγαίου ἄκρου (ταῦτα δὲ τὰ εἶπον πάντα μέλανα ἐστὶ δεινῶς), σκέλεα δὲ καὶ πρόσωπον ἐμφερὴς τῇ ἑτέρῃ. τοῦ δὲ ὄφιος ἡ μορφὴ οἵη περ τῶν ὕδρων, πτίλα δὲ οὐ πτερωτὰ φορέει ἀλλὰ τοῖσι τῆς νυκτερίδος πτεροῖσι μάλιστά κῃ ἐμφερέστατα. Τοσαῦτα μὲν θηρίων πέρι ἱρῶν εἰρήσθω.", "st": "2.76"}, {"sp": "N", "t": "αὐτῶν δὲ δὴ Αἰγυπτίων οἳ μὲν περὶ τὴν σπειρομένην Αἴγυπτον οἰκέουσι, μνήμην ἀνθρώπων πάντων ἐπασκέοντες μάλιστα λογιώτατοι εἰσὶ μακρῷ τῶν ἐγὼ ἐς διάπειραν ἀπικόμην, τρόπῳ δὲ ζόης τοιῷδε διαχρέωνται· συρμαΐζουσι τρεῖς ἡμέρας ἐπεξῆς μηνὸς ἑκάστου, ἐμέτοισι θηρώμενοι τὴν ὑγιείην καὶ κλύσμασι, νομίζοντες ἀπὸ τῶν τρεφόντων σιτίων πάσας τὰς νούσους τοῖσι ἀνθρώποισι γίνεσθαι. εἰσὶ μὲν γὰρ καὶ ἄλλως Αἰγύπτιοι μετὰ Λίβυας ὑγιηρέστατοι πάντων ἀνθρώπων τῶν ὡρέων δοκέειν ἐμοὶ εἵνεκα, ὅτι οὐ μεταλλάσσουσι αἱ ὧραι· ἐν γὰρ τῇσι μεταβολῇσι τοῖσι ἀνθρώποισι αἱ νοῦσοι μάλιστα γίνονται τῶν τε ἄλλων πάντων καὶ δὴ καὶ τῶν ὡρέων μάλιστα. ἀρτοφαγέουσι δὲ ἐκ τῶν ὀλυρέων ποιεῦντες ἄρτους, τοὺς ἐκεῖνοι κυλλήστις ὀνομάζουσι. οἴνῳ δὲ ἐκ κριθέων πεποιημένῳ διαχρέωνται· οὐ γάρ σφι εἰσὶ ἐν τῇ χώρῃ ἄμπελοι. ἰχθύων δὲ τοὺς μὲν πρὸς ἥλιον αὐήναντες ὠμοὺς σιτέονται, τοὺς δὲ ἐξ ἅλμης τεταριχευμένους. ὀρνίθων δὲ τούς τε ὄρτυγας καὶ τὰς νήσσας καὶ τὰ μικρὰ τῶν ὀρνίθων ὠμὰ σιτέονται προταριχεύσαντες. τὰ δὲ ἄλλα ὅσα ἢ ὀρνίθων ἢ ἰχθύων σφι ἐστὶ ἐχόμενα, χωρὶς ἢ ὁκόσοι σφι ἱροὶ ἀποδεδέχαται, τοὺς λοιποὺς ὀπτοὺς καὶ ἑφθοὺς σιτέονται.", "st": "2.77"}, {"sp": "N", "t": "ἐν δὲ τῇσι συνουσίῃσι τοῖσι εὐδαίμοσι αὐτῶν, ἐπεὰν ἀπὸ δείπνου γένωνται, περιφέρει ἀνὴρ νεκρὸν ἐν σορῷ ξύλινον πεποιημένον, μεμιμημένον ἐς τὰ μάλιστα καὶ γραφῇ καὶ ἔργῳ, μέγαθος ὅσον τε πηχυαῖον ἢ δίπηχυν, δεικνὺς δὲ ἑκάστῳ τῶν συμποτέων λέγει ἐς τοῦτον ὁρέων πῖνέ τε καὶ τέρπευ· ἔσεαι γὰρ ἀποθανὼν τοιοῦτος. ταῦτα μὲν παρὰ τὰ συμπόσια ποιεῦσι.", "st": "2.78"}, {"sp": "N", "t": "πατρίοισι δὲ χρεώμενοι νόμοισι ἄλλον οὐδένα ἐπικτῶνται· τοῖσι ἄλλα τε ἐπάξια ἐστὶ νόμιμα, καὶ δὴ καὶ ἄεισμα ἕν ἐστι, Λίνος, ὅσπερ ἔν τε Φοινίκῃ ἀοίδιμος ἐστὶ καὶ ἐν Κύπρῳ καὶ ἄλλῃ, κατὰ μέντοι ἔθνεα οὔνομα ἔχει, συμφέρεται δὲ ὡυτὸς εἶναι τὸν οἱ Ἕλληνες Λίνον ὀνομάζοντες ἀείδουσι, ὥστε πολλὰ μὲν καὶ ἄλλα ἀποθωμάζειν με τῶν περὶ Αἴγυπτον ἐόντων, ἐν δὲ δὴ καὶ τὸν Λίνον ὁκόθεν ἔλαβον τὸ οὔνομα· φαίνονται δὲ αἰεί κοτε τοῦτον ἀείδοντες. ἔστι δὲ Αἰγυπτιστὶ ὁ Λίνος καλεύμενος Μανερῶς. ἔφασαν δέ μιν Αἰγύπτιοι τοῦ πρώτου βασιλεύσαντος Αἰγύπτου παῖδα μουνογενέα γενέσθαι, ἀποθανόντα δὲ αὐτὸν ἄνωρον θρήνοισι τούτοισι ὑπὸ Αἰγυπτίων τιμηθῆναι, καὶ ἀοιδήν τε ταύτην πρώτην καὶ μούνην σφίσι γενέσθαι.", "st": "2.79"}, {"sp": "N", "t": "συμφέρονται δὲ καὶ τόδε ἄλλο Αἰγύπτιοι Ἑλλήνων μούνοισι Λακεδαιμονίοισι· οἱ νεώτεροι αὐτῶν τοῖσι πρεσβυτέροισι συντυγχάνοντες εἴκουσι τῆς ὁδοῦ καὶ ἐκτρέπονται καὶ ἐπιοῦσι ἐξ ἕδρης ὑπανιστέαται. τόδε μέντοι ἄλλοισι Ἑλλήνων οὐδαμοῖσι συμφέρονται· ἀντὶ τοῦ προσαγορεύειν ἀλλήλους ἐν τῇσι ὁδοῖσι προσκυνέουσι κατιέντες μέχρι τοῦ γούνατος τὴν χεῖρα.", "st": "2.80"}, {"sp": "N", "t": "ἐνδεδύκασι δὲ κιθῶνας λινέους περὶ τὰ σκέλεα θυσανωτούς, τοὺς καλέουσι καλασίρις· ἐπὶ τούτοισι δὲ εἰρίνεα εἵματα λευκὰ ἐπαναβληδὸν φορέουσι. οὐ μέντοι ἔς γε τὰ ἱρὰ ἐσφέρεται εἰρίνεα οὐδὲ συγκαταθάπτεταί σφι· οὐ γὰρ ὅσιον. ὁμολογέουσι δὲ ταῦτα τοῖσι Ὀρφικοῖσι καλεομένοισι καὶ Βακχικοῖσι, ἐοῦσι δὲ Αἰγυπτίοισι καὶ Πυθαγορείοισι· οὐδὲ γὰρ τούτων τῶν ὀργίων μετέχοντα ὅσιον ἐστὶ ἐν εἰρινέοισι εἵμασι θαφθῆναι. ἔστι δὲ περὶ αὐτῶν ἱρὸς λόγος λεγόμενος.", "st": "2.81"}, {"sp": "N", "t": "καὶ τάδε ἄλλα Αἰγυπτίοισι ἐστὶ ἐξευρημένα, μείς τε καὶ ἡμέρη ἑκάστη θεῶν ὅτευ ἐστί, καὶ τῇ ἕκαστος ἡμέρῃ γενόμενος ὁτέοισι ἐγκυρήσει καὶ ὅκως τελευτήσει καὶ ὁκοῖός τις ἔσται. καὶ τούτοισι τῶν Ἑλλήνων οἱ ἐν ποιήσι γενόμενοι ἐχρήσαντο. τέρατά τε πλέω σφι ἀνεύρηται ἢ τοῖσι ἄλλοισι ἅπασι ἀνθρώποισι· γενομένου γὰρ τέρατος φυλάσσουσι γραφόμενοι τὠποβαῖνον, καὶ ἤν κοτε ὕστερον παραπλήσιον τούτῳ γένηται, κατὰ τὠυτὸ νομίζουσι ἀποβήσεσθαι.", "st": "2.82"}, {"sp": "N", "t": "μαντικὴ δὲ αὐτοῖσι ὧδε διακέεται· ἀνθρώπων μὲν οὐδενὶ προσκέεται ἡ τέχνη, τῶν δὲ θεῶν μετεξετέροισι· καὶ γὰρ Ἡρακλέος μαντήιον αὐτόθι ἐστὶ καὶ Ἀπόλλωνος καὶ Ἀθηναίης καὶ Ἀρτέμιδος καὶ Ἄρεος καὶ Διός, καὶ τό γε μάλιστα ἐν τιμῇ ἄγονται πάντων τῶν μαντηίων, Λητοῦς ἐν Βουτοῖ πόλι ἐστί. οὐ μέντοι αἵ γε μαντηίαι σφι κατὰ τὠυτὸ ἑστᾶσι, ἀλλὰ διάφοροι εἰσί.", "st": "2.83"}, {"sp": "N", "t": "ἡ δὲ ἰητρικὴ κατὰ τάδε σφι δέδασται· μιῆς νούσου ἕκαστος ἰητρός ἐστι καὶ οὐ πλεόνων. πάντα δ’ ἰητρῶν ἐστι πλέα· οἳ μὲν γὰρ ὀφθαλμῶν ἰητροὶ κατεστᾶσι, οἳ δὲ κεφαλῆς, οἳ δὲ ὀδόντων, οἳ δὲ τῶν κατὰ νηδύν, οἳ δὲ τῶν ἀφανέων νούσων.", "st": "2.84"}, {"sp": "N", "t": "θρῆνοι δὲ καὶ ταφαί σφεων εἰσὶ αἵδε· τοῖσι ἂν ἀπογένηται ἐκ τῶν οἰκίων ἄνθρωπος τοῦ τις καὶ λόγος ᾖ, τὸ θῆλυ γένος πᾶν τὸ ἐκ τῶν οἰκίων τούτων κατ’ ὦν ἐπλάσατο τὴν κεφαλὴν πηλῷ ἢ καὶ τὸ πρόσωπον, κἄπειτα ἐν τοῖσι οἰκίοισι λιποῦσαι τὸν νεκρὸν αὐταὶ ἀνὰ τὴν πόλιν στρωφώμεναι τύπτονται ἐπεζωσμέναι καὶ φαίνουσαι τοὺς μαζούς, σὺν δέ σφι αἱ προσήκουσαι πᾶσαι, ἑτέρωθεν δὲ οἱ ἄνδρες, τύπτονται ἐπεζωμένοι καὶ οὗτοι. ἐπεὰν δὲ ταῦτα ποιήσωσι, οὕτω ἐς τὴν ταρίχευσιν κομίζουσι.", "st": "2.85"}, {"sp": "N", "t": "εἰσὶ δὲ οἳ ἐπ’ αὐτῷ τούτῳ κατέαται καὶ τέχνην ἔχουσι ταύτην. οὗτοι, ἐπεάν σφι κομισθῇ νεκρός, δεικνύουσι τοῖσι κομίσασι παραδείγματα νεκρῶν ξύλινα, τῇ γραφῇ μεμιμημένα …, καὶ τὴν μὲν σπουδαιοτάτην αὐτέων φασὶ εἶναι τοῦ οὐκ ὅσιον ποιεῦμαι τὸ οὔνομα ἐπὶ τοιούτῳ πρήγματι ὀνομάζειν, τὴν δὲ δευτέρην δεικνύουσι ὑποδεεστέρην τε ταύτης καὶ εὐτελεστέρην, τὴν δὲ τρίτην εὐτελεστάτην· φράσαντες δὲ πυνθάνονται παρ’ αὐτῶν κατὰ ἥντινα βούλονταί σφι σκευασθῆναι τὸν νεκρόν. οἳ μὲν δὴ ἐκποδὼν μισθῷ ὁμολογήσαντες ἀπαλλάσσονται, οἳ δὲ ὑπολειπόμενοι ἐν οἰκήμασι ὧδε τὰ σπουδαιότατα ταριχεύουσι. πρῶτα μὲν σκολιῷ σιδήρῳ διὰ τῶν μυξωτήρων ἐξάγουσι τὸν ἐγκέφαλον, τὰ μὲν αὐτοῦ οὕτω ἐξάγοντες, τὰ δὲ ἐγχέοντες φάρμακα· μετὰ δὲ λίθῳ Αἰθιοπικῷ ὀξέι παρασχίσαντες παρὰ τὴν λαπάρην ἐξ ὦν εἷλον τὴν κοιλίην πᾶσαν, ἐκκαθήραντες δὲ αὐτὴν καὶ διηθήσαντες οἴνῳ φοινικηίῳ αὖτις διηθέουσι θυμιήμασι τετριμμένοισι· ἔπειτα τὴν νηδὺν σμύρνης ἀκηράτου τετριμμένης καὶ κασίης καὶ τῶν ἄλλων θυμιημάτων, πλὴν λιβανωτοῦ, πλήσαντες συρράπτουσι ὀπίσω. ταῦτα δὲ ποιήσαντες ταριχεύουσι λίτρῳ κρύψαντες ἡμέρας ἑβδομήκοντα· πλεῦνας δὲ τουτέων οὐκ ἔξεστι ταριχεύειν. ἐπεὰν δὲ παρέλθωσι αἱ ἑβδομήκοντα, λούσαντες τὸν νεκρὸν κατειλίσσουσι πᾶν αὐτοῦ τὸ σῶμα σινδόνος βυσσίνης τελαμῶσι κατατετμημένοισι, ὑποχρίοντες τῷ κόμμι, τῷ δὴ ἀντὶ κόλλης τὰ πολλὰ χρέωνται Αἰγύπτιοι. ἐνθεῦτεν δὲ παραδεξάμενοί μιν οἱ προσήκοντες ποιεῦνται ξύλινον τύπον ἀνθρωποειδέα, ποιησάμενοι δὲ ἐσεργνῦσι τὸν νεκρόν, καὶ κατακληίσαντες οὕτω θησαυρίζουσι ἐν οἰκήματι θηκαίῳ, ἱστάντες ὀρθὸν πρὸς τοῖχον.", "st": "2.86"}, {"sp": "N", "t": "οὕτω μὲν τοὺς τὰ πολυτελέστατα σκευάζουσι νεκρούς, τοὺς δὲ τὰ μέσα βουλομένους τὴν δὲ πολυτελείην φεύγοντας σκευάζουσι ὧδε· ἐπεὰν τοὺς κλυστῆρας πλήσωνται τοῦ ἀπὸ κέδρου ἀλείφατος γινομένου, ἐν ὦν ἔπλησαν τοῦ νεκροῦ τὴν κοιλίην, οὔτε ἀναταμόντες αὐτὸν οὔτε ἐξελόντες τὴν νηδύν, κατὰ δὲ τὴν ἕδρην ἐσηθήσαντες καὶ ἐπιλαβόντες τὸ κλύσμα τῆς ὀπίσω ὁδοῦ ταριχεύουσι τὰς προκειμένας ἡμέρας, τῇ δὲ τελευταίῃ ἐξιεῖσι ἐκ τῆς κοιλίης τὴν κεδρίην τὴν ἐσῆκαν πρότερον. ἣ δὲ ἔχει τοσαύτην δύναμιν ὥστε ἅμα ἑωυτῇ τὴν νηδὺν καὶ τὰ σπλάγχνα κατατετηκότα ἐξάγει· τὰς δὲ σάρκας τὸ λίτρον κατατήκει, καὶ δὴ λείπεται τοῦ νεκροῦ τὸ δέρμα μοῦνον καὶ τὰ ὀστέα. ἐπεὰν δὲ ταῦτα ποιήσωσι, ἀπ’ ὦν ἔδωκαν οὕτω τὸν νεκρόν, οὐδὲν ἔτι πρηγματευθέντες.", "st": "2.87"}, {"sp": "N", "t": "ἡ δὲ τρίτη ταρίχευσις ἐστὶ ἥδε, ἣ τοὺς χρήμασι ἀσθενεστέρους σκευάζει· συρμαίῃ διηθήσαντες τὴν κοιλίην ταριχεύουσι τὰς ἑβδομήκοντα ἡμέρας καὶ ἔπειτα ἀπ’ ὦν ἔδωκαν ἀποφέρεσθαι.", "st": "2.88"}, {"sp": "N", "t": "τὰς δὲ γυναῖκας τῶν ἐπιφανέων ἀνδρῶν, ἐπεὰν τελευτήσωσι, οὐ παραυτίκα διδοῦσι ταριχεύειν, οὐδὲ ὅσαι ἂν ἔωσι εὐειδέες κάρτα καὶ λόγου πλεῦνος γυναῖκες· ἀλλ’ ἐπεὰν τριταῖαι ἢ τεταρταῖαι γένωνται, οὕτω παραδιδοῦσι τοῖσι ταριχεύουσι. τοῦτο δὲ ποιεῦσι οὕτω τοῦδε εἵνεκεν, ἵνα μή σφι οἱ ταριχευταὶ μίσγωνται τῇσι γυναιξί· λαμφθῆναι γὰρ τινὰ φασὶ μισγόμενον νεκρῷ προσφάτῳ γυναικός, κατειπεῖν δὲ τὸν ὁμότεχνον.", "st": "2.89"}, {"sp": "N", "t": "ὃς δ’ ἂν ἢ αὐτῶν Αἰγυπτίων ἢ ξείνων ὁμοίως ὑπὸ κροκοδείλου ἁρπασθεὶς ἢ ὑπ’ αὐτοῦ τοῦ ποταμοῦ φαίνηται τεθνεώς, κατ’ ἣν ἂν πόλιν ἐξενειχθῇ, τούτους πᾶσα ἀνάγκη ἐστὶ ταριχεύσαντας αὐτὸν καὶ περιστείλαντας ὡς κάλλιστα θάψαι ἐν ἱρῇσι θήκῃσι· οὐδὲ ψαῦσαι ἔξεστι αὐτοῦ ἄλλον οὐδένα οὔτε τῶν προσηκόντων οὔτε τῶν φίλων, ἀλλά μιν οἱ ἱρέες αὐτοὶ τοῦ Νείλου ἅτε πλέον τι ἢ ἀνθρώπου νεκρὸν χειραπτάζοντες θάπτουσι.", "st": "2.90"}, {"sp": "N", "t": "ἑλληνικοῖσι δὲ νομαίοισι φεύγουσι χρᾶσθαι, τὸ δὲ σύμπαν εἰπεῖν, μηδ’ ἄλλων μηδαμὰ μηδαμῶν ἀνθρώπων νομαίοισι. οἱ μέν νυν ἄλλοι Αἰγύπτιοι οὕτω τοῦτο φυλάσσουσι, ἔστι δὲ Χέμμις πόλις μεγάλη νομοῦ τοῦ Θηβαϊκοῦ ἐγγὺς Νέης πόλιος· ἐν ταύτῃ τῇ πόλι ἐστὶ Περσέος τοῦ Δανάης ἱρὸν τετράγωνον, πέριξ δὲ αὐτοῦ φοίνικες πεφύκασι. τὰ δὲ πρόπυλα τοῦ ἱροῦ λίθινα ἐστὶ κάρτα μεγάλα· ἐπὶ δὲ αὐτοῖσι ἀνδριάντες δύο ἑστᾶσι λίθινοι μεγάλοι. ἐν δὲ τῷ περιβεβλημένῳ τούτῳ νηός τε ἔνι καὶ ἄγαλμα ἐν αὐτῷ ἐνέστηκε τοῦ Περσέος. οὗτοι οἱ Χεμμῖται λέγουσι τὸν Περσέα πολλάκις μὲν ἀνὰ τὴν γῆν φαίνεσθαί σφι πολλάκις δὲ ἔσω τοῦ ἱροῦ, σανδάλιόν τε αὐτοῦ πεφορημένον εὑρίσκεσθαι ἐὸν τὸ μέγαθος δίπηχυ, τὸ ἐπεὰν φανῇ, εὐθηνέειν ἅπασαν Αἴγυπτον. ταῦτα μὲν λέγουσι, ποιεῦσι δὲ τάδε Ἑλληνικὰ τῷ Περσέι· ἀγῶνα γυμνικὸν τιθεῖσι διὰ πάσης ἀγωνίης ἔχοντα, παρέχοντες ἄεθλα κτήνεα καὶ χλαίνας καὶ δέρματα. εἰρομένου δέ μευ ὅ τι σφι μούνοισι ἔωθε ὁ Περσεὺς ἐπιφαίνεσθαι καὶ ὅ τι κεχωρίδαται Αἰγυπτίων τῶν ἄλλων ἀγῶνα γυμνικὸν τιθέντες, ἔφασαν τὸν Περσέα ἐκ τῆς ἑωυτῶν πόλιος γεγονέναι· τὸν γὰρ Δαναὸν καὶ τὸν Λυγκέα ἐόντας Χεμμίτας ἐκπλῶσαι ἐς τὴν Ἑλλάδα, ἀπὸ δὲ τούτων γενεηλογέοντες κατέβαινον ἐς τὸν Περσέα. ἀπικόμενον δὲ αὐτὸν ἐς Αἴγυπτον κατ’ αἰτίην τὴν καὶ Ἕλληνες λέγουσι, οἴσοντα ἐκ Λιβύης τὴν Γοργοῦς κεφαλήν, ἔφασαν ἐλθεῖν καὶ παρὰ σφέας καὶ ἀναγνῶναι τοὺς συγγενέας πάντας· ἐκμεμαθηκότα δέ μιν ἀπικέσθαι ἐς Αἴγυπτον τὸ τῆς Χέμμιος οὔνομα, πεπυσμένον παρὰ τῆς μητρός. ἀγῶνα δέ οἱ γυμνικὸν αὐτοῦ κελεύσαντος ἐπιτελέειν.", "st": "2.91"}, {"sp": "N", "t": "ταῦτα μὲν πάντα οἱ κατύπερθε τῶν ἑλέων οἰκέοντες Αἰγύπτιοι νομίζουσι· οἱ δὲ δὴ ἐν τοῖσι ἕλεσι κατοικημένοι τοῖσι μὲν αὐτοῖσι νόμοισι χρέωνται τοῖσι καὶ οἱ ἄλλοι Αἰγύπτιοι, καὶ τὰ ἄλλα καὶ γυναικὶ μιῇ ἕκαστος αὐτῶν συνοικέει κατά περ Ἕλληνες, ἀτὰρ πρὸς εὐτελείην τῶν σιτίων τάδε σφι ἄλλα ἐξεύρηται. ἐπεὰν πλήρης γένηται ὁ ποταμὸς καὶ τὰ πεδία πελαγίσῃ, φύεται ἐν τῷ ὕδατι κρίνεα πολλά, τὰ Αἰγύπτιοι καλέουσι λωτόν· ταῦτ’ ἐπεὰν δρέψωσι αὐαίνουσι πρὸς ἥλιον καὶ ἔπειτα τὸ ἐκ μέσου τοῦ λωτοῦ, τῇ μήκωνι ἐὸν ἐμφερές, πτίσαντες ποιεῦνται ἐξ αὐτοῦ ἄρτους ὀπτοὺς πυρί. ἔστι δὲ καὶ ἡ ῥίζα τοῦ λωτοῦ τούτου ἐδωδίμη καὶ ἐγγλύσσει ἐπιεικέως, ἐὸν στρογγύλον, μέγαθος κατὰ μῆλον. ἔστι δὲ καὶ ἄλλα κρίνεα ῥόδοισι ἐμφερέα, ἐν τῷ ποταμῷ γινόμενα καὶ ταῦτα, ἐξ ὧν ὁ καρπὸς ἐν ἄλλῃ κάλυκι παραφυομένῃ ἐκ τῆς ῥίζης γίνεται, κηρίῳ σφηκῶν ἰδέην ὁμοιότατον· ἐν τούτῳ τρωκτὰ ὅσον τε πυρὴν ἐλαίης ἐγγίνεται συχνά, τρώγεται δὲ καὶ ἁπαλὰ ταῦτα καὶ αὖα. τὴν δὲ βύβλον τὴν ἐπέτειον γινομένην ἐπεὰν ἀνασπάσωσι ἐκ τῶν ἑλέων, τὰ μὲν ἄνω αὐτῆς ἀποτάμνοντες ἐς ἄλλο τι τρέπουσι, τὸ δὲ κάτω λελειμμένον ὅσον τε ἐπὶ πῆχυν τρώγουσι καὶ πωλέουσι· οἳ δὲ ἂν καὶ κάρτα βούλωνται χρηστῇ τῇ βύβλῳ χρᾶσθαι, ἐν κλιβάνῳ διαφανέι πνίξαντες οὕτω τρώγουσι. οἳ δὲ τινὲς αὐτῶν ζῶσι ἀπὸ τῶν ἰχθύων μοῦνον, τοὺς ἐπεὰν λάβωσι καὶ ἐξέλωσι τὴν κοιλίην, αὐαίνουσι πρὸς ἥλιον καὶ ἔπειτα αὔους ἐόντας σιτέονται.", "st": "2.92"}, {"sp": "N", "t": "οἱ δὲ ἰχθύες οἱ ἀγελαῖοι ἐν μὲν τοῖσι ποταμοῖσι οὐ μάλα γίνονται, τρεφόμενοι δὲ ἐν τῇσι λίμνῃσι τοιάδε ποιεῦσι. ἐπεάν σφεας ἐσίῃ οἶστρος κυΐσκεσθαι, ἀγεληδὸν ἐκπλέουσι ἐς θάλασσαν· ἡγέονται δὲ οἱ ἔρσενες ἀπορραίνοντες τοῦ θοροῦ, αἳ δὲ ἑπόμεναι ἀνακάπτουσι καὶ ἐξ αὐτοῦ κυΐσκονται. ἐπεὰν δὲ πλήρεες γένωνται ἐν τῇ θαλάσσῃ, ἀναπλώουσι ὀπίσω ἐς ἤθεα τὰ ἑωυτῶν ἕκαστοι, ἡγέονται μέντοι γε οὐκέτι οἱ αὐτοί, ἀλλὰ τῶν θηλέων γίνεται ἡ ἡγεμονία· ἡγεύμεναι δὲ ἀγεληδὸν ποιεῦσι οἷόν περ ἐποίευν οἱ ἔρσενες· τῶν γὰρ ᾠῶν ἀπορραίνουσι κατ’ ὀλίγους τῶν κέγχρων, οἱ δὲ ἔρσενες καταπίνουσι ἑπόμενοι. εἰσὶ δὲ οἱ κέγχροι οὗτοι ἰχθύες. ἐκ δὲ τῶν περιγινομένων καὶ μὴ καταπινομένων κέγχρων οἱ τρεφόμενοι ἰχθύες γίνονται. οἵ δ’ ἂν αὐτῶν ἁλῶσι ἐκπλώοντες ἐς θάλασσαν, φαίνονται τετριμμένοι τὰ ἐπ’ ἀριστερὰ τῶν κεφαλέων, οἳ δ’ ἂν ὀπίσω ἀναπλώοντες, τὰ ἐπὶ δεξιὰ τετρίφαται. πάσχουσι δὲ ταῦτα διὰ τόδε· ἐχόμενοι τῆς γῆς ἐπ’ ἀριστερὰ καταπλώουσι ἐς θάλασσαν, καὶ ἀναπλώοντες ὀπίσω τῆς αὐτῆς ἀντέχονται, ἐγχριμπτόμενοι καὶ ψαύοντες ὡς μάλιστα, ἵνα δὴ μὴ ἁμάρτοιεν τῆς ὁδοῦ διὰ τὸν ῥόον. ἐπεὰν δὲ πληθύνεσθαι ἄρχηται ὁ Νεῖλος, τά τε κοῖλα τῆς γῆς καὶ τὰ τέλματα τὰ παρὰ τὸν ποταμὸν πρῶτα ἄρχεται πίμπλασθαι διηθέοντος τοῦ ὕδατος ἐκ τοῦ ποταμοῦ· καὶ αὐτίκα τε πλέα γίνεται ταῦτα καὶ παραχρῆμα ἰχθύων σμικρῶν πίμπλαται πάντα. κόθεν δὲ οἰκὸς αὐτοὺς γίνεσθαι, ἐγώ μοι δοκέω κατανοέειν τοῦτο· τοῦ προτέρου ἔτεος ἐπεὰν ἀπολίπῃ ὁ Νεῖλος, οἱ ἰχθύες ἐντεκόντες ᾠὰ ἐς τὴν ἰλὺν ἅμα τῷ ἐσχάτῳ ὕδατι ἀπαλλάσσονται· ἐπεὰν δὲ περιελθόντος τοῦ χρόνου πάλιν ἐπέλθῃ τὸ ὕδωρ, ἐκ τῶν ᾠῶν τούτων παραυτίκα γίνονται οἱ ἰχθύες οὗτοι.", "st": "2.93"}, {"sp": "N", "t": "καὶ περὶ μὲν τοὺς ἰχθύας οὕτω ἔχει. ἀλείφατι δὲ χρέωνται Αἰγυπτίων οἱ περὶ τὰ ἕλεα οἰκέοντες ἀπὸ τῶν σιλλικυπρίων τοῦ καρποῦ, τὸ καλεῦσι μὲν Αἰγύπτιοι κίκι, ποιεῦσι δὲ ὧδε. παρὰ τὰ χείλεα τῶν τε ποταμῶν καὶ τῶν λιμνέων σπείρουσι τὰ σιλλικύπρια ταῦτα, τὰ ἐν Ἕλλησι αὐτόματα ἄγρια φύεται· ταῦτα ἐν τῇ Αἰγύπτῳ σπειρόμενα καρπὸν φέρει πολλὸν μὲν δυσώδεα δέ· τοῦτον ἐπεὰν συλλέξωνται, οἳ μὲν κόψαντες ἀπιποῦσι, οἳ δὲ καὶ φρύξαντες ἀπέψουσι, καὶ τὸ ἀπορρέον ἀπ’ αὐτοῦ συγκομίζονται. ἔστι δὲ πῖον καὶ οὐδὲν ἧσσον τοῦ ἐλαίου τῷ λύχνῳ προσηνές, ὀδμὴν δὲ βαρέαν παρέχεται.", "st": "2.94"}, {"sp": "N", "t": "πρὸς δὲ τοὺς κώνωπας ἀφθόνους ἐόντας τάδε σφι ἐστὶ μεμηχανημένα. τοὺς μὲν τὰ ἄνω τῶν ἑλέων οἰκέοντας οἱ πύργοι ὠφελέουσι, ἐς τοὺς ἀναβαίνοντες κοιμῶνται· οἱ γὰρ κώνωπες ὑπὸ τῶν ἀνέμων οὐκ οἷοί τε εἰσὶ ὑψοῦ πέτεσθαι. τοῖσι δὲ περὶ τὰ ἕλεα οἰκέουσι τάδε ἀντὶ τῶν πύργων ἄλλα μεμηχάνηται· πᾶς ἀνὴρ αὐτῶν ἀμφίβληστρον ἔκτηται, τῷ τῆς μὲν ἡμέρης ἰχθῦς ἀγρεύει, τὴν δὲ νύκτα τάδε αὐτῷ χρᾶται· ἐν τῇ ἀναπαύεται κοίτῃ, περὶ ταύτην ἵστησι τὸ ἀμφίβληστρον καὶ ἔπειτα ἐνδὺς ὑπ’ αὐτὸ κατεύδει. οἱ δὲ κώνωπες, ἢν μὲν ἐν ἱματίῳ ἐνειλιξάμενος εὕδῃ ἢ σινδόνι, διὰ τούτων δάκνουσι, διὰ δὲ τοῦ δικτύου οὐδὲ πειρῶνται ἀρχήν.", "st": "2.95"}, {"sp": "N", "t": "τὰ δὲ δὴ πλοῖά σφι, τοῖσι φορτηγέουσι, ἐστὶ ἐκ τῆς ἀκάνθης ποιεύμενα, τῆς ἡ μορφὴ μὲν ἐστὶ ὁμοιοτάτη τῷ Κυρηναίῳ λωτῷ, τὸ δὲ δάκρυον κόμμι ἐστί. ἐκ ταύτης ὦν τῆς ἀκάνθης κοψάμενοι ξύλα ὅσον τε διπήχεα πλινθηδὸν συντιθεῖσι ναυπηγεύμενοι τρόπον τοιόνδε· περὶ γόμφους πυκνοὺς καὶ μακροὺς περιείρουσι τὰ διπήχεα ξύλα· ἐπεὰν δὲ τῷ τρόπῳ τούτῳ ναυπηγήσωνται, ζυγὰ ἐπιπολῆς τείνουσι αὐτῶν· νομεῦσι δὲ οὐδὲν χρέωνται· ἔσωθεν δὲ τὰς ἁρμονίας ἐν ὦν ἐπάκτωσαν τῇ βύβλῳ. πηδάλιον δὲ ἓν ποιεῦνται, καὶ τοῦτο διὰ τῆς τρόπιος διαβύνεται. ἱστῷ δὲ ἀκανθίνῳ χρέωνται, ἱστίοισι δὲ βυβλίνοισι. ταῦτα τὰ πλοῖα ἀνὰ μὲν τὸν ποταμὸν οὐ δύναται πλέειν, ἢν μὴ λαμπρὸς ἄνεμος ἐπέχῃ, ἐκ γῆς δὲ παρέλκεται, κατὰ ῥόον δὲ κομίζεται ὧδε· ἔστι ἐκ μυρίκης πεποιημένη θύρη, κατερραμμένη ῥιπὶ καλάμων, καὶ λίθος τετρημένος διτάλαντος μάλιστά κῃ σταθμόν· τούτων τὴν μὲν θύρην δεδεμένην κάλῳ ἔμπροσθε τοῦ πλοίου ἀπιεῖ ἐπιφέρεσθαι, τὸν δὲ λίθον ἄλλῳ κάλῳ ὄπισθε. ἡ μὲν δὴ θύρη τοῦ ῥόου ἐμπίπτοντος χωρέει ταχέως καὶ ἕλκει τὴν βᾶριν (τοῦτο γὰρ δὴ οὔνομα ἐστὶ τοῖσι πλοίοισι τούτοισι), ὁ δὲ λίθος ὄπισθε ἐπελκόμενος καὶ ἐὼν ἐν βυσσῷ κατιθύνει τὸν πλόον. ἔστι δέ σφι τὰ πλοῖα ταῦτα πλήθεϊ πολλά, καὶ ἄγει ἔνια πολλὰς χιλιάδας ταλάντων.", "st": "2.96"}, {"sp": "N", "t": "ἐπεὰν δὲ ἐπέλθῃ ὁ Νεῖλος τὴν χώρην, αἱ πόλιες μοῦναι φαίνονται ὑπερέχουσαι, μάλιστά κῃ ἐμφερέες τῇσι ἐν τῷ Αἰγαίῳ πόντῳ νήσοισι· τὰ μὲν γὰρ ἄλλα τῆς Αἰγύπτου πέλαγος γίνεται, αἱ δὲ πόλιες μοῦναι ὑπερέχουσι. πορθμεύονται ὦν, ἐπεὰν τοῦτο γένηται, οὐκέτι κατὰ τὰ ῥέεθρα τοῦ ποταμοῦ ἀλλὰ διὰ μέσου τοῦ πεδίου. ἐς μέν γε Μέμφιν ἐκ Ναυκράτιος ἀναπλώοντι παρ’ αὐτὰς τὰς πυραμίδας γίνεται ὁ πλόος· ἔστι δὲ οὐδ’ οὗτος, ἀλλὰ παρὰ τὸ ὀξὺ τοῦ Δέλτα καὶ παρὰ Κερκάσωρον πόλιν· ἐς δὲ Ναύκρατιν ἀπὸ θαλάσσης καὶ Κανώβου διὰ πεδίου πλέων ἥξεις κατ’ Ἄνθυλλάν τε πόλιν καὶ τὴν Ἀρχάνδρου καλευμένην.", "st": "2.97"}, {"sp": "N", "t": "τουτέων δὲ ἡ μὲν Ἄνθυλλα ἐοῦσα λογίμη πόλις ἐς ὑποδήματα ἐξαίρετος δίδοται τοῦ αἰεὶ βασιλεύοντος Αἰγύπτου τῇ γυναικί (τοῦτο δὲ γίνεται ἐξ ὅσου ὑπὸ Πέρσῃσι ἐστὶ Αἴγυπτος), ἡ δὲ ἑτέρη πόλις δοκέει μοι τὸ οὔνομα ἔχειν ἀπὸ τοῦ Δαναοῦ γαμβροῦ Ἀρχάνδρου τοῦ Φθίου τοῦ Ἀχαιοῦ· καλέεται γὰρ δὴ Ἀρχάνδρου πόλις. εἴη δ’ ἂν καὶ ἄλλος τις Ἄρχανδρος, οὐ μέντοι γε Αἰγύπτιον τὸ οὔνομα.", "st": "2.98"}, {"sp": "N", "t": "μέχρι μὲν τούτου ὄψις τε ἐμὴ καὶ γνώμη καὶ ἱστορίη ταῦτα λέγουσα ἐστί, τὸ δὲ ἀπὸ τοῦδε Αἰγυπτίους ἔρχομαι λόγους ἐρέων κατὰ τὰ ἤκουον·", "st": "2.99"}, {"sp": "N", "t": "προσέσται δὲ αὐτοῖσί τι καὶ τῆς ἐμῆς ὄψιος. Μῖνα τὸν πρῶτον βασιλεύσαντα Αἰγύπτου οἱ ἱρέες ἔλεγον τοῦτο μὲν ἀπογεφυρῶσαι τὴν Μέμφιν. τὸν γὰρ ποταμὸν πάντα ῥέειν παρὰ τὸ ὄρος τὸ ψάμμινον πρὸς Λιβύης, τὸν δὲ Μῖνα ἄνωθεν, ὅσον τε ἑκατὸν σταδίους ἀπὸ Μέμφιος, τὸν πρὸς μεσαμβρίης ἀγκῶνα προσχώσαντα τὸ μὲν ἀρχαῖον ῥέεθρον ἀποξηρῆναι, τὸν δὲ ποταμὸν ὀχετεῦσαι τὸ μέσον τῶν ὀρέων ῥέειν. ἔτι δὲ καὶ νῦν ὑπὸ Περσέων ὁ ἀγκὼν οὗτος τοῦ Νείλου ὡς ἀπεργμένος ῥέῃ ἐν φυλακῇσι μεγάλῃσι ἔχεται, φρασσόμενος ἀνὰ πᾶν ἔτος· εἰ γὰρ ἐθελήσει ῥήξας ὑπερβῆναι ὁ ποταμὸς ταύτῃ, κίνδυνος πάσῃ Μέμφι κατακλυσθῆναι ἐστί. ὡς δὲ τῷ Μῖνι τούτῳ τῷ πρώτῳ γενομένῳ βασιλέι χέρσον γεγονέναι τὸ ἀπεργμένον, τοῦτο μὲν ἐν αὐτῷ πόλιν κτίσαι ταύτην ἥτις νῦν Μέμφις καλέεται· ἔστι γὰρ καὶ ἡ Μέμφις ἐν τῷ στεινῷ τῆς Αἰγύπτου· ἔξωθεν δὲ αὐτῆς περιορύξαι λίμνην ἐκ τοῦ ποταμοῦ πρὸς βορέην τε καὶ πρὸς ἑσπέρην (τὸ γὰρ πρὸς τὴν ἠῶ αὐτὸς ὁ Νεῖλος ἀπέργει), τοῦτο δὲ τοῦ Ἡφαίστου τὸ ἱρὸν ἱδρύσασθαι ἐν αὐτῇ, ἐὸν μέγα τε καὶ ἀξιαπηγητότατον.", "st": "2.99.2"}, {"sp": "N", "t": "μετὰ δὲ τοῦτον κατέλεγον οἱ ἱρέες ἐκ βύβλου ἄλλων βασιλέων τριηκοσίων καὶ τριήκοντα οὐνόματα. ἐν τοσαύτῃσι δὲ γενεῇσι ἀνθρώπων ὀκτωκαίδεκα μὲν Αἰθίοπες ἦσαν, μία δὲ γυνὴ ἐπιχωρίη, οἱ δὲ ἄλλοι ἄνδρες Αἰγύπτιοι. τῇ δὲ γυναικὶ οὔνομα ἦν, ἥτις ἐβασίλευσε, τό περ τῇ Βαβυλωνίῃ, Νίτωκρις· τὴν ἔλεγον τιμωρέουσαν ἀδελφεῷ, τὸν Αἰγύπτιοι βασιλεύοντα σφέων ἀπέκτειναν, ἀποκτείναντες δὲ οὕτω ἐκείνῃ ἀπέδοσαν τὴν βασιληίην, τούτῳ τιμωρέουσαν πολλοὺς Αἰγυπτίων διαφθεῖραι δόλῳ. ποιησαμένην γάρ μιν οἴκημα περίμηκες ὑπόγαιον καινοῦν τῷ λόγῳ, νόῳ δὲ ἄλλα μηχανᾶσθαι· καλέσασαν δέ μιν Αἰγυπτίων τοὺς μάλιστα μεταιτίους τοῦ φόνου ᾔδεε πολλοὺς ἱστιᾶν, δαινυμένοισι δὲ ἐπεῖναι τὸν ποταμὸν δι’ αὐλῶνος κρυπτοῦ μεγάλου. ταύτης μὲν πέρι τοσαῦτα ἔλεγον, πλὴν ὅτι αὐτήν μιν, ὡς τοῦτο ἐξέργαστο, ῥίψαι ἐς οἴκημα σποδοῦ πλέον, ὅκως ἀτιμώρητος γένηται.", "st": "2.100"}, {"sp": "N", "t": "τῶν δὲ ἄλλων βασιλέων οὐ γὰρ ἔλεγον οὐδεμίαν ἔργων ἀπόδεξιν καὶ οὐδὲν εἶναι λαμπρότητος, πλὴν ἑνὸς τοῦ ἐσχάτου αὐτῶν Μοίριος· τοῦτον δὲ ἀποδέξασθαι μνημόσυνα τοῦ Ἡφαίστου τὰ πρὸς βορέην ἄνεμον τετραμμένα προπύλαια, λίμνην τε ὀρύξαι, τῆς ἡ περίοδος ὅσων ἐστὶ σταδίων ὕστερον δηλώσω, πυραμίδας τε ἐν αὐτῇ οἰκοδομῆσαι, τῶν τοῦ μεγάθεος πέρι ὁμοῦ αὐτῇ τῇ λίμνῃ ἐπιμνήσομαι· τοῦτον μὲν τοσαῦτα ἀποδέξασθαι, τῶν δὲ ἄλλων οὐδένα οὐδέν.", "st": "2.101"}, {"sp": "N", "t": "παραμειψάμενος ὦν τούτους τοῦ ἐπὶ τούτοισι γενομένου βασιλέος, τῷ οὔνομα ἦν Σέσωστρις, τούτου μνήμην ποιήσομαι· τὸν ἔλεγον οἱ ἱρέες πρῶτον μὲν πλοίοισι μακροῖσι ὁρμηθέντα ἐκ τοῦ Ἀραβίου κόλπου τοὺς παρὰ τὴν Ἐρυθρὴν θάλασσαν κατοικημένους καταστρέφεσθαι, ἐς ὃ πλέοντά μιν πρόσω ἀπικέσθαι ἐς θάλασσαν οὐκέτι πλωτὴν ὑπὸ βραχέων. ἐνθεῦτεν δὲ ὡς ὀπίσω ἀπίκετο ἐς Αἴγυπτον, κατὰ τῶν ἱρέων τὴν φάτιν, πολλὴν στρατιὴν τῶν λαβὼν ἤλαυνε διὰ τῆς ἠπείρου, πᾶν ἔθνος τὸ ἐμποδὼν καταστρεφόμενος. ὁτέοισι μέν νυν αὐτῶν ἀλκίμοισι ἐνετύγχανε καὶ δεινῶς γλιχομένοισι περὶ τῆς ἐλευθερίης, τούτοισι μὲν στήλας ἐνίστη ἐς τὰς χώρας διὰ γραμμάτων λεγούσας τό τε ἑωυτοῦ οὔνομα καὶ τῆς πάτρης, καὶ ὡς δυνάμι τῇ ἑωυτοῦ κατεστρέψατο σφέας· ὅτεων δὲ ἀμαχητὶ καὶ εὐπετέως παρέλαβε τὰς πόλιας, τούτοισι δὲ ἐνέγραφε ἐν τῇσι στήλῃσι κατὰ ταὐτὰ καὶ τοῖσι ἀνδρηίοισι τῶν ἐθνέων γενομένοισι, καὶ δὴ καὶ αἰδοῖα γυναικὸς προσενέγραφε, δῆλα βουλόμενος ποιέειν ὡς εἴησαν ἀνάλκιδες.", "st": "2.102"}, {"sp": "N", "t": "ταῦτα δὲ ποιέων διεξήιε τὴν ἤπειρον, ἐς ὃ ἐκ τῆς Ἀσίης ἐς τὴν Εὐρώπην διαβὰς τούς τε Σκύθας κατεστρέψατο καὶ τοὺς Θρήικας. ἐς τούτους δέ μοι δοκέει καὶ προσώτατα ἀπικέσθαι ὁ Αἰγύπτιος στρατός· ἐν μὲν γὰρ τῇ τούτων χώρῃ φαίνονται σταθεῖσαι αἱ στῆλαι, τὸ δὲ προσωτέρω τούτων οὐκέτι. ἐνθεῦτεν δὲ ἐπιστρέψας ὀπίσω ἤιε, καὶ ἐπείτε ἐγίνετο ἐπὶ Φάσι ποταμῷ, οὐκ ἔχω τὸ ἐνθεῦτεν ἀτρεκέως εἰπεῖν εἴτε αὐτὸς ὁ βασιλεὺς Σέσωστρις ἀποδασάμενος τῆς ἑωυτοῦ στρατιῆς μόριον ὅσον δὴ αὐτοῦ κατέλιπε τῆς χώρης οἰκήτορας, εἴτε τῶν τινες στρατιωτέων τῇ πλάνῃ αὐτοῦ ἀχθεσθέντες περὶ Φᾶσιν ποταμὸν κατέμειναν.", "st": "2.103"}, {"sp": "N", "t": "φαίνονται μὲν γὰρ ἐόντες οἱ Κόλχοι Αἰγύπτιοι, νοήσας δὲ πρότερον αὐτὸς ἢ ἀκούσας ἄλλων λέγω. ὡς δέ μοι ἐν φροντίδι ἐγένετο, εἰρόμην ἀμφοτέρους, καὶ μᾶλλον οἱ Κόλχοι ἐμεμνέατο τῶν Αἰγυπτίων ἢ οἱ Αἰγύπτιοι τῶν Κόλχων· νομίζειν δ’ ἔφασαν οἱ Αἰγύπτιοι τῆς Σεσώστριος στρατιῆς εἶναι τοὺς Κόλχους. αὐτὸς δὲ εἴκασα τῇδε, καὶ ὅτι μελάγχροες εἰσὶ καὶ οὐλότριχες. καὶ τοῦτο μὲν ἐς οὐδὲν ἀνήκει· εἰσὶ γὰρ καὶ ἕτεροι τοιοῦτοι· ἀλλὰ τοῖσιδε καὶ μᾶλλον, ὅτι μοῦνοι πάντων ἀνθρώπων Κόλχοι καὶ Αἰγύπτιοι καὶ Αἰθίοπες περιτάμνονται ἀπ’ ἀρχῆς τὰ αἰδοῖα. Φοίνικες δὲ καὶ Σύροι οἱ ἐν τῇ Παλαιστίνῃ καὶ αὐτοὶ ὁμολογέουσι παρ’ Αἰγυπτίων μεμαθηκέναι, Σύριοι δὲ οἱ περὶ Θερμώδοντα καὶ Παρθένιον ποταμὸν καὶ Μάκρωνες οἱ τούτοισι ἀστυγείτονες ἐόντες ἀπὸ Κόλχων φασὶ νεωστὶ μεμαθηκέναι. οὗτοι γὰρ εἰσὶ οἱ περιταμνόμενοι ἀνθρώπων μοῦνοι, καὶ οὗτοι Αἰγυπτίοισι φαίνονται ποιεῦντες κατὰ ταὐτά. αὐτῶν δὲ Αἰγυπτίων καὶ Αἰθιόπων οὐκ ἔχω εἰπεῖν ὁκότεροι παρὰ τῶν ἑτέρων ἐξέμαθον· ἀρχαῖον γὰρ δή τι φαίνεται ἐόν. ὡς δὲ ἐπιμισγόμενοι Αἰγύπτῳ ἐξέμαθον, μέγα μοι καὶ τόδε τεκμήριον γίνεται· Φοινίκων ὁκόσοι τῇ Ἑλλάδι ἐπιμίσγονται, οὐκέτι Αἰγυπτίους μιμέονται κατὰ τὰ αἰδοῖα. ἀλλὰ τῶν ἐπιγινομένων οὐ περιτάμνουσι τὰ αἰδοῖα.", "st": "2.104"}, {"sp": "N", "t": "φέρε νῦν καὶ ἄλλο εἴπω περὶ τῶν Κόλχων, ὡς Αἰγυπτίοισι προσφερέες εἰσί· λίνον μοῦνοι οὗτοί τε καὶ Αἰγύπτιοι ἐργάζονται καὶ κατὰ ταὐτά, καὶ ἡ ζόη πᾶσα καὶ ἡ γλῶσσα ἐμφερής ἐστι ἀλλήλοισι. λίνον δὲ τὸ μὲν Κολχικὸν ὑπὸ Ἑλλήνων Σαρδωνικὸν κέκληται, τὸ μέντοι ἀπ’ Αἰγύπτου ἀπικνεύμενον καλέεται Αἰγύπτιον.", "st": "2.105"}, {"sp": "N", "t": "αἱ δὲ στῆλαι τὰς ἵστα κατὰ τὰς χώρας ὁ Αἰγύπτου βασιλεὺς Σέσωστρις, αἱ μὲν πλεῦνες οὐκέτι φαίνονται περιεοῦσαι, ἐν δὲ τῇ Παλαιστίνῃ Συρίῃ αὐτὸς ὥρων ἐούσας καὶ τὰ γράμματα τὰ εἰρημένα ἐνεόντα καὶ γυναικὸς αἰδοῖα. εἰσὶ δὲ καὶ περὶ Ἰωνίην δύο τύποι ἐν πέτρῃσι ἐγκεκολαμμένοι τούτου τοῦ ἀνδρός, τῇ τε ἐκ τῆς Ἐφεσίης ἐς Φώκαιαν ἔρχονται καὶ τῇ ἐκ Σαρδίων ἐς Σμύρνην. ἑκατέρωθι δὲ ἀνὴρ ἐγγέγλυπται μέγαθος πέμπτης σπιθαμῆς, τῇ μὲν δεξιῇ χειρὶ ἔχων αἰχμὴν τῇ δὲ ἀριστερῇ τόξα, καὶ τὴν ἄλλην σκευὴν ὡσαύτως· καὶ γὰρ Αἰγυπτίην καὶ Αἰθιοπίδα ἔχει· ἐκ δὲ τοῦ ὤμου ἐς τὸν ἕτερον ὦμον διὰ τῶν στηθέων γράμματα ἱρὰ Αἰγύπτια διήκει ἐγκεκολαμμένα, λέγοντα τάδε· ἐγὼ τήνδε τὴν χώρην ὤμοισι τοῖσι ἐμοῖσι ἐκτησάμην. ὅστις δὲ καὶ ὁκόθεν ἐστί, ἐνθαῦτα μὲν οὐ δηλοῖ, ἑτέρωθι δὲ δεδήλωκε· τὰ δὴ καὶ μετεξέτεροι τῶν θεησαμένων Μέμνονος εἰκόνα εἰκάζουσί μιν εἶναι, πολλὸν τῆς ἀληθείης ἀπολελειμμένοι.", "st": "2.106"}, {"sp": "N", "t": "τοῦτον δὴ τὸν Αἰγύπτιον Σέσωστριν ἀναχωρέοντα καὶ ἀνάγοντα πολλοὺς ἀνθρώπους τῶν ἐθνέων τῶν τὰς χώρας κατεστρέψατο, ἔλεγον οἱ ἱρέες, ἐπείτε ἐγίνετο ἀνακομιζόμενος ἐν Δάφνῃσι τῇσι Πηλουσίῃσι, τὸν ἀδελφεὸν ἑωυτοῦ, τῷ ἐπέτρεψε ὁ Σέσωστρις τὴν Αἴγυπτον, τοῦτον ἐπὶ ξείνια αὐτὸν καλέσαντα καὶ πρὸς αὐτῷ τοὺς παῖδας περινῆσαι ἔξωθεν τὴν οἰκίην ὕλῃ, περινήσαντα δὲ ὑποπρῆσαι. τὸν δὲ ὡς μαθεῖν τοῦτο, αὐτίκα συμβουλεύεσθαι τῇ γυναικί· καὶ γὰρ δὴ καὶ τὴν γυναῖκα αὐτὸν ἅμα ἄγεσθαι· τὴν δέ οἱ συμβουλεῦσαι τῶν παίδων ἐόντων ἓξ τοὺς δύο ἐπὶ τὴν πυρὴν ἐκτείναντα γεφυρῶσαι τὸ καιόμενον, αὐτοὺς δὲ ἐπ’ ἐκείνων ἐπιβαίνοντας ἐκσώζεσθαι. ταῦτα ποιῆσαι τὸν Σέσωστριν, καὶ δύο μὲν τῶν παίδων κατακαῆναι τρόπῳ τοιούτῳ, τοὺς δὲ λοιποὺς ἀποσωθῆναι ἅμα τῷ πατρί.", "st": "2.107"}, {"sp": "N", "t": "νοστήσας δὲ ὁ Σέσωστρις ἐς τὴν Αἴγυπτον καὶ τισάμενος τὸν ἀδελφεόν, τῷ μὲν ὁμίλῳ τὸν ἐπηγάγετο τῶν τὰς χώρας κατεστρέψατο, τούτῳ μὲν τάδε ἐχρήσατο· τούς τέ οἱ λίθους τοὺς ἐπὶ τούτου τοῦ βασιλέος κομισθέντας ἐς τοῦ Ἡφαίστου τὸ ἱρόν, ἐόντας μεγάθεϊ περιμήκεας, οὗτοι ἦσαν οἱ ἑλκύσαντες, καὶ τὰς διώρυχας τὰς νῦν ἐούσας ἐν Αἰγύπτῳ πάσας οὗτοι ἀναγκαζόμενοι ὤρυσσον, ἐποίευν τε οὐκ ἑκόντες Αἴγυπτον, τὸ πρὶν ἐοῦσαν ἱππασίμην καὶ ἁμαξευομένην πᾶσαν, ἐνδεᾶ τούτων. ἀπὸ γὰρ τούτου τοῦ χρόνου Αἴγυπτος ἐοῦσα πεδιὰς πᾶσα ἄνιππος καὶ ἀναμάξευτος γέγονε· αἴτιαι δὲ τούτων αἱ διώρυχες γεγόνασι ἐοῦσαι πολλαὶ καὶ παντοίους τρόπους ἔχουσαί. κατέταμνε δὲ τοῦδε εἵνεκα τὴν χώρην ὁ βασιλεύς· ὅσοι τῶν Αἰγυπτίων μὴ ἐπὶ τῷ ποταμῷ ἔκτηντο τὰς πόλις ἀλλ’ ἀναμέσους, οὗτοι, ὅκως τε ἀπίοι ὁ ποταμός, σπανίζοντες ὑδάτων πλατυτέροισι ἐχρέωντο τοῖσι πόμασι, ἐκ φρεάτων χρεώμενοι.", "st": "2.108"}, {"sp": "N", "t": "τούτων μὲν δὴ εἵνεκα κατετμήθη ἡ Αἴγυπτος. κατανεῖμαι δὲ τὴν χώρην Αἰγυπτίοισι ἅπασι τοῦτον ἔλεγον τὸν βασιλέα, κλῆρον ἴσον ἑκάστῳ τετράγωνον διδόντα, καὶ ἀπὸ τούτου τὰς προσόδους ποιήσασθαι, ἐπιτάξαντα ἀποφορὴν ἐπιτελέειν κατ’ ἐνιαυτόν. εἰ δὲ τινὸς τοῦ κλήρου ὁ ποταμός τι παρέλοιτο, ἐλθὼν ἂν πρὸς αὐτὸν ἐσήμαινε τὸ γεγενημένον· ὁ δὲ ἔπεμπε τοὺς ἐπισκεψομένους καὶ ἀναμετρήσοντας ὅσῳ ἐλάσσων ὁ χῶρος γέγονε, ὅκως τοῦ λοιποῦ κατὰ λόγον τῆς τεταγμένης ἀποφορῆς τελέοι. δοκέει δέ μοι ἐνθεῦτεν γεωμετρίη εὑρεθεῖσα ἐς τὴν Ἑλλάδα ἐπανελθεῖν· πόλον μὲν γὰρ καὶ γνώμονα καὶ τὰ δυώδεκα μέρεα τῆς ἡμέρης παρὰ Βαβυλωνίων ἔμαθον οἱ Ἕλληνες.", "st": "2.109"}, {"sp": "N", "t": "βασιλεὺς μὲν δὴ οὗτος μοῦνος Αἰγύπτιος Αἰθιοπίης ἦρξε, μνημόσυνα δὲ ἐλίπετο πρὸ τοῦ Ἡφαιστείου ἀνδριάντας λιθίνους, δύο μὲν τριήκοντα πηχέων, ἑωυτόν τε καὶ τὴν γυναῖκα, τοὺς δὲ παῖδας ἐόντας τέσσερας εἴκοσι πηχέων ἕκαστον· τῶν δὴ ὁ ἱρεὺς τοῦ Ἡφαίστου χρόνῳ μετέπειτα πολλῷ Δαρεῖον τὸν Πέρσην οὐ περιεῖδε ἱστάντα ἔμπροσθε ἀνδριάντα, φὰς οὔ οἱ πεποιῆσθαι ἔργα οἷά περ Σεσώστρι τῷ Αἰγυπτίῳ· Σέσωστριν μὲν γὰρ ἄλλα τε καταστρέψασθαι ἔθνεα οὐκ ἐλάσσω ἐκείνου καὶ δὴ καὶ Σκύθας, Δαρεῖον δὲ οὐ δυνασθῆναι Σκύθας ἑλεῖν· οὔκων δίκαιον εἶναι ἱστάναι ἔμπροσθε τῶν ἐκείνου ἀναθημάτων μὴ οὐκ ὑπερβαλλόμενον τοῖσι ἔργοισι. Δαρεῖον μέν νυν λέγουσι πρὸς ταῦτα συγγνώμην ποιήσασθαι.", "st": "2.110"}, {"sp": "N", "t": "Σεσώστριος δὲ τελευτήσαντος ἐκδέξασθαι ἔλεγον τὴν βασιληίην τὸν παῖδα αὐτοῦ Φερῶν, τὸν ἀποδέξασθαι μὲν οὐδεμίαν στρατηίην, συνενειχθῆναι δέ οἱ τυφλὸν γενέσθαι διὰ τοιόνδε πρῆγμα. τοῦ ποταμοῦ κατελθόντος μέγιστα δὴ τότε ἐπ’ ὀκτωκαίδεκα πήχεας, ὡς ὑπερέβαλε τὰς ἀρούρας, πνεύματος ἐμπεσόντος κυματίης ὁ ποταμὸς ἐγένετο· τὸν δὲ βασιλέα λέγουσι τοῦτον ἀτασθαλίῃ χρησάμενον, λαβόντα αἰχμὴν βαλεῖν ἐς μέσας τὰς δίνας τοῦ ποταμοῦ, μετὰ δὲ αὐτίκα καμόντα αὐτὸν τοὺς ὀφθαλμοὺς τυφλωθῆναι. δέκα μὲν δὴ ἔτεα εἶναί μιν τυφλόν, ἑνδεκάτῳ δὲ ἔτεϊ ἀπικέσθαι οἱ μαντήιον ἐκ Βουτοῦς πόλιος ὡς ἐξήκει τέ οἱ ὁ χρόνος τῆς ζημίης καὶ ἀναβλέψει γυναικὸς οὔρῳ νιψάμενος τοὺς ὀφθαλμούς, ἥτις παρὰ τὸν ἑωυτῆς ἄνδρα μοῦνον πεφοίτηκε, ἄλλων ἀνδρῶν ἐοῦσα ἄπειρος. καὶ τὸν πρώτης τῆς ἑωυτοῦ γυναικὸς πειρᾶσθαι, μετὰ δέ, ὡς οὐκ ἀνέβλεπε, ἐπεξῆς πασέων πειρᾶσθαι· ἀναβλέψαντα δὲ συναγαγεῖν τὰς γυναῖκας τῶν ἐπειρήθη, πλὴν ἢ τῆς τῷ οὔρῳ νιψάμενος ἀνέβλεψε, ἐς μίαν πόλιν, ἣ νῦν καλέεται Ἐρυθρὴ βῶλος· ἐς ταύτην συναλίσαντα ὑποπρῆσαι πάσας σὺν αὐτῇ τῇ πόλι· τῆς δὲ νιψάμενος τῷ οὔρῳ ἀνέβλεψε, ταύτην δὲ ἔσχε αὐτὸς γυναῖκα. ἀναθήματα δὲ ἀποφυγὼν τὴν πάθην τῶν ὀφθαλμῶν ἄλλα τε ἀνὰ τὰ ἱρὰ πάντα τὰ λόγιμα ἀνέθηκε καὶ τοῦ γε λόγον μάλιστα ἄξιον ἐστὶ ἔχειν, ἐς τοῦ Ἡλίου τὸ ἱρὸν ἀξιοθέητα ἀνέθηκε ἔργα, ὀβελοὺς δύο λιθίνους, ἐξ ἑνὸς ἐόντα ἑκάτερον λίθου, μῆκος μὲν ἑκάτερον πηχέων ἑκατόν, εὖρος δὲ ὀκτὼ πηχέων.", "st": "2.111"}, {"sp": "N", "t": "τούτου δὲ ἐκδέξασθαι τὴν βασιληίην ἔλεγον ἄνδρα Μεμφίτην, τῷ κατὰ τὴν Ἑλλήνων γλῶσσαν οὔνομα Πρωτέα εἶναι· τοῦ νῦν τέμενος ἐστὶ ἐν Μέμφι κάρτα καλόν τε καὶ εὖ ἐσκευασμένον, τοῦ Ἡφαιστείου πρὸς νότον ἄνεμον κείμενον. περιοικέουσι δὲ τὸ τέμενος τοῦτο Φοίνικες Τύριοι, καλέεται δὲ ὁ χῶρος οὗτος ὁ συνάπας Τυρίων στρατόπεδον. ἔστι δὲ ἐν τῷ τεμένεϊ τοῦ Πρωτέος ἱρὸν τὸ καλέεται ξείνης Ἀφροδίτης· συμβάλλομαι δὲ τοῦτο τὸ ἱρὸν εἶναι Ἑλένης τῆς Τυνδάρεω, καὶ τὸν λόγον ἀκηκοὼς ὡς διαιτήθη Ἑλένη παρὰ Πρωτέι, καὶ δὴ καὶ ὅτι ξείνης Ἀφροδίτης ἐπώνυμον ἐστί· ὅσα γὰρ ἄλλα Ἀφροδίτης ἱρά ἐστι, οὐδαμῶς ξείνης ἐπικαλέεται.", "st": "2.112"}, {"sp": "N", "t": "ἔλεγον δέ μοι οἱ ἱρέες ἱστορέοντι τὰ περὶ Ἑλένην γενέσθαι ὧδε. Ἀλέξανδρον ἁρπάσαντα Ἑλένην ἐκ Σπάρτης ἀποπλέειν ἐς τὴν ἑωυτοῦ· καί μιν, ὡς ἐγένετο ἐν τῷ Αἰγαίῳ, ἐξῶσται ἄνεμοι ἐκβάλλουσι ἐς τὸ Αἰγύπτιον πέλαγος, ἐνθεῦτεν δέ, οὐ γὰρ ἀνιεῖ τὰ πνεύματα, ἀπικνέεται ἐς Αἴγυπτον καὶ Αἰγύπτου ἐς τὸ νῦν Κανωβικὸν καλεύμενον στόμα τοῦ Νείλου καὶ ἐς Ταριχείας. ἦν δὲ ἐπὶ τῆς ἠιόνος τὸ καὶ νῦν ἐστι Ἡρακλέος ἱρόν, ἐς τὸ ἢν καταφυγὼν οἰκέτης ὅτευ ὦν ἀνθρώπων ἐπιβάληται στίγματα ἱρά, ἑωυτὸν διδοὺς τῷ θεῷ, οὐκ ἔξεστι τούτου ἅψασθαι. ὁ νόμος οὗτος διατελέει ἐὼν ὅμοιος μέχρι ἐμεῦ τῷ ἀπ’ ἀρχῆς· τοῦ ὦν δὴ Ἀλεξάνδρου ἀπιστέαται θεράποντες πυθόμενοι τὸν περὶ τὸ ἱρὸν ἔχοντα νόμον, ἱκέται δὲ ἱζόμενοι τοῦ θεοῦ κατηγόρεον τοῦ Ἀλεξάνδρου, βουλόμενοι βλάπτειν αὐτόν, πάντα λόγον ἐξηγεύμενοι ὡς εἶχε περὶ τὴν Ἑλένην τε καὶ τὴν ἐς Μενέλεων ἀδικίην· κατηγόρεον δὲ ταῦτα πρός τε τοὺς ἱρέας καὶ τὸν στόματος τούτου φύλακον, τῷ οὔνομα ἦν Θῶνις.", "st": "2.113"}, {"sp": "N", "t": "ἀκούσας δὲ τούτων ὁ Θῶνις πέμπει τὴν ταχίστην ἐς Μέμφιν παρὰ Πρωτέα ἀγγελίην λέγουσαν τάδε. ἥκει ξεῖνος γένος μὲν Τευκρός, ἔργον δὲ ἀνόσιον ἐν τῇ Ἑλλάδι ἐξεργασμένος· ξείνου γὰρ τοῦ ἑωυτοῦ ἐξαπατήσας τὴν γυναῖκα αὐτήν τε ταύτην ἄγων ἥκει καὶ πολλὰ κάρτα χρήματα, ὑπὸ ἀνέμων ἐς γῆν ταύτην ἀπενειχθείς. κότερα δῆτα τοῦτον ἐῶμεν ἀσινέα ἐκπλέειν ἢ ἀπελώμεθα τὰ ἔχων ἦλθε; ἀντιπέμπει πρὸς ταῦτα ὁ Πρωτεὺς λέγοντα τάδε. ἄνδρα τοῦτον, ὅστις κοτὲ ἐστὶ ἀνόσια ἐργασμένος ξεῖνον τὸν ἑωυτοῦ, συλλαβόντες ἀπάγετε παρ’ ἐμέ, ἵνα εἰδέω ὅ τι κοτὲ καὶ λέξει.", "st": "2.114"}, {"sp": "N", "t": "ἀκούσας δὲ ταῦτα ὁ Θῶνις συλλαμβάνει τὸν Ἀλέξανδρον καὶ τὰς νέας αὐτοῦ κατίσχει, μετὰ δὲ αὐτόν τε τοῦτον ἀνήγαγε ἐς Μέμφιν καὶ τὴν Ἑλένην τε καὶ τὰ χρήματα, πρὸς δὲ καὶ τοὺς ἱκέτας. ἀνακομισθέντων δὲ πάντων, εἰρώτα τὸν Ἀλέξανδρον ὁ Πρωτεὺς τίς εἴη καὶ ὁκόθεν πλέοι. ὁ δέ οἱ καὶ τὸ γένος κατέλεξε καὶ τῆς πάτρης εἶπε τὸ οὔνομα, καὶ δὴ καὶ τὸν πλόον ἀπηγήσατο ὁκόθεν πλέοι. μετὰ δὲ ὁ Πρωτεὺς εἰρώτα αὐτὸν ὁκόθεν τὴν Ἑλένην λάβοι· πλανωμένου δὲ τοῦ Ἀλεξάνδρου ἐν τῷ λόγῳ καὶ οὐ λέγοντος τὴν ἀληθείην, ἤλεγχον οἱ γενόμενοι ἱκέται, ἐξηγεύμενοι πάντα λόγον τοῦ ἀδικήματος. τέλος δὲ δή σφι λόγον τόνδε ἐκφαίνει ὁ Πρωτεύς, λέγων ὅτι ἐγὼ εἰ μὴ περὶ πολλοῦ ἡγεύμην μηδένα ξείνων κτείνειν, ὅσοι ὑπ’ ἀνέμων ἤδη ἀπολαμφθέντες ἦλθον ἐς χώρην τὴν ἐμήν, ἐγὼ ἄν σε ὑπὲρ τοῦ Ἕλληνος ἐτισάμην, ὅς, ὦ κάκιστε ἀνδρῶν, ξεινίων τυχὼν ἔργον ἀνοσιώτατον ἐργάσαο· παρὰ τοῦ σεωυτοῦ ξείνου τὴν γυναῖκα ἦλθες. καὶ μάλα ταῦτά τοι οὐκ ἤρκεσε, ἀλλ’ ἀναπτερώσας αὐτὴν οἴχεαι ἔχων ἐκκλέψας. καὶ οὐδὲ ταῦτά τοι μοῦνα ἤρκεσε, ἀλλὰ καὶ οἰκία τοῦ ξείνου κεραΐσας ἥκεις. νῦν ὦν ἐπειδὴ περὶ πολλοῦ ἥγημαι μὴ ξεινοκτονέειν, γυναῖκα μὲν ταύτην καὶ τὰ χρήματα οὔ τοι προήσω ἀπάγεσθαι, ἀλλ’ αὐτὰ ἐγὼ τῷ Ἕλληνι ξείνῳ φυλάξω, ἐς ὃ ἂν αὐτὸς ἐλθὼν ἐκεῖνος ἀπαγαγέσθαι ἐθέλῃ· αὐτὸν δέ σε καὶ τοὺς σοὺς συμπλόους τριῶν ἡμερέων προαγορεύω ἐκ τῆς ἐμῆς γῆς ἐς ἄλλην τινὰ μετορμίζεσθαι, εἰ δὲ μή, ἅτε πολεμίους περιέψεσθαι.", "st": "2.115"}, {"sp": "N", "t": "Ἑλένης μὲν ταύτην ἄπιξιν παρὰ Πρωτέα ἔλεγον οἱ ἱρέες γενέσθαι· δοκέει δέ μοι καὶ Ὅμηρος τὸν λόγον τοῦτον πυθέσθαι· ἀλλ’ οὐ γὰρ ὁμοίως ἐς τὴν ἐποποιίην εὐπρεπὴς ἦν τῷ ἑτέρῳ τῷ περ ἐχρήσατο, ἑκὼν μετῆκε αὐτόν, δηλώσας ὡς καὶ τοῦτον ἐπίσταιτο τὸν λόγον· δῆλον δὲ κατὰ [γὰρ] ἐποίησε ἐν Ἰλιάδι (καὶ οὐδαμῇ ἄλλῃ ἀνεπόδισε ἑωυτόν) πλάνην τὴν Ἀλεξάνδρου, ὡς ἀπηνείχθη ἄγων Ἑλένην τῇ τε δὴ ἄλλῃ πλαζόμενος καὶ ὡς ἐς Σιδῶνα τῆς Φοινίκης ἀπίκετο. ἐπιμέμνηται δὲ αὐτοῦ ἐν Διομήδεος ἀριστείῃ· λέγει δὲ τὰ ἔπεα ὧδε.", "st": "2.116"}, {"sp": "N", "t": "ἔνθ’ ἔσαν οἱ πέπλοι παμποίκιλοι, ἔργα γυναικῶν<br>Σιδονίων, τὰς αὐτὸς Ἀλέξανδρος θεοειδής<br>ἤγαγε Σιδονίηθεν, ἐπιπλὼς εὐρέα πόντον,<br>τὴν ὁδὸν ἣν Ἑλένην περ ἀνήγαγεν εὐπατέρειαν.", "st": "2.116b"}, {"sp": "N", "t": "ἐπιμέμνηται δὲ καὶ ἐν Ὀδυσσείῃ ἐν τοῖσιδε τοῖσι ἔπεσι.", "st": "2.116.4"}, {"sp": "N", "t": "τοῖα Διὸς θυγάτηρ ἔχε φάρμακα μητιόεντα,<br>ἐσθλά, τά οἱ Πολύδαμνα πόρεν Θῶνος παράκοιτις<br>Αἰγυπτίη, τῇ πλεῖστα φέρει ζείδωρος ἄρουρα<br>φάρμακα, πολλὰ μὲν ἐσθλὰ μεμιγμένα, πολλὰ δὲ λυγρά.", "st": "2.116.4b"}, {"sp": "N", "t": "καὶ τάδε ἕτερα πρὸς Τηλέμαχον Μενέλεως λέγει.", "st": "2.116.5"}, {"sp": "N", "t": "Αἰγύπτῳ μ’ ἔτι δεῦρο θεοὶ μεμαῶτα νέεσθαι<br>ἔσχον, ἐπεὶ οὔ σφιν ἔρεξα τεληέσσας ἑκατόμβας.", "st": "2.116.5b"}, {"sp": "N", "t": "ἐν τούτοισι τοῖσι ἔπεσι δηλοῖ ὅτι ἠπίστατο τὴν ἐς Αἴγυπτον Ἀλεξάνδρου πλάνην· ὁμουρέει γὰρ ἡ Συρίη Αἰγύπτῳ, οἱ δὲ Φοίνικες, τῶν ἐστὶ ἡ Σιδών, ἐν τῇ Συρίῃ οἰκέουσι.", "st": "2.116.6"}, {"sp": "N", "t": "κατὰ ταῦτα δὲ τὰ ἔπεα καὶ τόδε τὸ χωρίον οὐκ ἥκιστα ἀλλὰ μάλιστα δηλοῖ ὅτι οὐκ Ὁμήρου τὰ Κύπρια ἔπεα ἐστὶ ἀλλ’ ἄλλου τινός. ἐν μὲν γὰρ τοῖσι Κυπρίοισι εἴρηται ὡς τριταῖος ἐκ Σπάρτης Ἀλέξανδρος ἀπίκετο ἐς τὸ Ἴλιον ἄγων Ἑλένην, εὐαέι τε πνεύματι χρησάμενος καὶ θαλάσσῃ λείῃ· ἐν δὲ Ἰλιάδι λέγει ὡς ἐπλάζετο ἄγων αὐτήν.", "st": "2.117"}, {"sp": "N", "t": "Ὅμηρος μέν νυν καὶ τὰ Κύπρια ἔπεα χαιρέτω. εἰρομένου δέ μευ τοὺς ἱρέας εἰ μάταιον λόγον λέγουσι οἱ Ἕλληνες τὰ περὶ Ἴλιον γενέσθαι ἢ οὔ, ἔφασαν πρὸς ταῦτα τάδε, ἱστορίῃσι φάμενοι εἰδέναι παρ’ αὐτοῦ Μενέλεω. ἐλθεῖν μὲν γὰρ μετὰ τὴν Ἑλένης ἁρπαγὴν ἐς τὴν Τευκρίδα γῆν Ἑλλήνων στρατιὴν πολλὴν βοηθεῦσαν Μενέλεῳ, ἐκβᾶσαν δὲ ἐς γῆν καὶ ἱδρυθεῖσαν τὴν στρατιὴν πέμπειν ἐς τὸ Ἴλιον ἀγγέλους, σὺν δέ σφι ἰέναι καὶ αὐτὸν Μενέλεων· τοὺς δ’ ἐπείτε ἐσελθεῖν ἐς τὸ τεῖχος, ἀπαιτέειν Ἑλένην τε καὶ τὰ χρήματα τά οἱ οἴχετο κλέψας Ἀλέξανδρος, τῶν τε ἀδικημάτων δίκας αἰτέειν· τοὺς δὲ Τευκροὺς τὸν αὐτὸν λόγον λέγειν τότε καὶ μετέπειτα, καὶ ὀμνύντας καὶ ἀνωμοτί, μὴ μὲν ἔχειν Ἑλένην μηδὲ τὰ ἐπικαλεύμενα χρήματα, ἀλλ’ εἶναι αὐτὰ πάντα ἐν Αἰγύπτῳ, καὶ οὐκ ἂν δικαίως αὐτοὶ δίκας ὑπέχειν τῶν Πρωτεὺς ὁ Αἰγύπτιος βασιλεὺς ἔχει. οἱ δὲ Ἕλληνες καταγελᾶσθαι δοκέοντες ὑπ’ αὐτῶν οὕτω δὴ ἐπολιόρκεον, ἐς ὃ ἐξεῖλον· ἑλοῦσι δὲ τὸ τεῖχος ὡς οὐκ ἐφαίνετο ἡ Ἑλένη, ἀλλὰ τὸν αὐτὸν λόγον τῷ προτέρῳ ἐπυνθάνοντο, οὕτω δὴ πιστεύσαντες τῷ λόγῳ τῷ πρώτῳ οἱ Ἕλληνες αὐτὸν Μενέλεων ἀποστέλλουσι παρὰ Πρωτέα.", "st": "2.118"}, {"sp": "N", "t": "ἀπικόμενος δὲ ὁ Μενέλεως ἐς τὴν Αἴγυπτον καὶ ἀναπλώσας ἐς τὴν Μέμφιν, εἴπας τὴν ἀληθείην τῶν πρηγμάτων, καὶ ξεινίων ἤντησε μεγάλων καὶ Ἑλένην ἀπαθέα κακῶν ἀπέλαβε, πρὸς δὲ καὶ τὰ ἑωυτοῦ χρήματα πάντα. τυχὼν μέντοι τούτων ἐγένετο Μενέλεως ἀνὴρ ἄδικος ἐς Αἰγυπτίους. ἀποπλέειν γὰρ ὁρμημένον αὐτὸν ἶσχον ἄπλοιαι· ἐπειδὴ δὲ τοῦτο ἐπὶ πολλὸν τοιοῦτον ἦν, ἐπιτεχνᾶται πρῆγμα οὐκ ὅσιον· λαβὼν γὰρ δύο παιδία ἀνδρῶν ἐπιχωρίων ἔντομα σφέα ἐποίησε. μετὰ δὲ ὡς ἐπάιστος ἐγένετο τοῦτο ἐργασμένος, μισηθείς τε καὶ διωκόμενος οἴχετο φεύγων τῇσι νηυσὶ ἐπὶ Λιβύης· τὸ ἐνθεῦτεν δὲ ὅκου ἔτι ἐτράπετο οὐκ εἶχον εἰπεῖν Αἰγύπτιοι. τούτων δὲ τὰ μὲν ἱστορίῃσι ἔφασαν ἐπίστασθαι, τὰ δὲ παρ’ ἑωυτοῖσι γενόμενα ἀτρεκέως ἐπιστάμενοι λέγειν.", "st": "2.119"}, {"sp": "N", "t": "ταῦτα μὲν Αἰγυπτίων οἱ ἱρέες ἔλεγον· ἐγὼ δὲ τῷ λόγῳ τῷ περὶ Ἑλένης λεχθέντι καὶ αὐτὸς προστίθεμαι, τάδε ἐπιλεγόμενος, εἰ ἦν Ἑλένη ἐν Ἰλίῳ, ἀποδοθῆναι ἂν αὐτὴν τοῖσι Ἕλλησι ἤτοι ἑκόντος γε ἢ ἀέκοντος Ἀλεξάνδρου. οὐ γὰρ δὴ οὕτω γε φρενοβλαβὴς ἦν ὁ Πρίαμος οὐδὲ οἱ ἄλλοι οἱ προσήκοντες αὐτῷ, ὥστε τοῖσι σφετέροισι σώμασι καὶ τοῖσι τέκνοισι καὶ τῇ πόλι κινδυνεύειν ἐβούλοντο, ὅκως Ἀλέξανδρος Ἑλένῃ συνοικέῃ. εἰ δέ τοι καὶ ἐν τοῖσι πρώτοισι χρόνοισι ταῦτα ἐγίνωσκον, ἐπεὶ πολλοὶ μὲν τῶν ἄλλων Τρώων, ὁκότε συμμίσγοιεν τοῖσι Ἕλλησι, ἀπώλλυντο, αὐτοῦ δὲ Πριάμου οὐκ ἔστι ὅτε οὐ δύο ἢ τρεῖς ἢ καὶ ἔτι πλέους τῶν παίδων μάχης γινομένης ἀπέθνησκον, εἰ χρή τι τοῖσι ἐποποιοῖσι χρεώμενον λέγειν, τούτων δὲ τοιούτων συμβαινόντων ἐγὼ μὲν ἔλπομαι, εἰ καὶ αὐτὸς Πρίαμος συνοίκεε Ἑλένῃ, ἀποδοῦναι ἂν αὐτὴν τοῖσι Ἀχαιοῖσι, μέλλοντά γε δὴ τῶν παρεόντων κακῶν ἀπαλλαγήσεσθαι. οὐ μὲν οὐδὲ ἡ βασιληίη ἐς Ἀλέξανδρον περιήιε, ὥστε γέροντος Πριάμου ἐόντος ἐπ’ ἐκείνῳ τὰ πρήγματα εἶναι, ἀλλὰ Ἕκτωρ καὶ πρεσβύτερος καὶ ἀνὴρ ἐκείνου μᾶλλον ἐὼν ἔμελλε αὐτὴν Πριάμου ἀποθανόντος παραλάμψεσθαι, τὸν οὐ προσῆκε ἀδικέοντι τῷ ἀδελφεῷ ἐπιτρέπειν, καὶ ταῦτα μεγάλων κακῶν δι’ αὐτὸν συμβαινόντων ἰδίῃ τε αὐτῷ καὶ τοῖσι ἄλλοισι πᾶσι Τρωσί. ἀλλ’ οὐ γὰρ εἶχον Ἑλένην ἀποδοῦναι, οὐδὲ λέγουσι αὐτοῖσι τὴν ἀληθείην ἐπίστευον οἱ Ἕλληνες, ὡς μὲν ἐγὼ γνώμην ἀποφαίνομαι, τοῦ δαιμονίου παρασκευάζοντος, ὅκως πανωλεθρίῃ ἀπολόμενοι καταφανὲς τοῦτο τοῖσι ἀνθρώποισι ποιήσωσι, ὡς τῶν μεγάλων ἀδικημάτων μεγάλαι εἰσὶ καὶ αἱ τιμωρίαι παρὰ τῶν θεῶν. καὶ ταῦτα μὲν τῇ ἐμοὶ δοκέει εἴρηται.", "st": "2.120"}, {"sp": "N", "t": "Πρωτέος δὲ ἐκδέξασθαι τὴν βασιληίην Ῥαμψίνιτον ἔλεγον, ὃς μνημόσυνα ἐλίπετο τὰ προπύλαια τὰ πρὸς ἑσπέρην τετραμμένα τοῦ Ἡφαιστείου, ἀντίους δὲ τῶν προπυλαίων ἔστησε ἀνδριάντας δύο, ἐόντας τὸ μέγαθος πέντε καὶ εἴκοσι πηχέων, τῶν Αἰγύπτιοι τὸν μὲν πρὸς βορέω ἑστεῶτα καλέουσι θέρος, τὸν δὲ πρὸς νότον χειμῶνα· καὶ τὸν μὲν καλέουσι θέρος, τοῦτον μὲν προσκυνέουσί τε καὶ εὖ ποιέουσι, τὸν δὲ χειμῶνα καλεόμενον τὰ ἔμπαλιν τούτων ἔρδουσι πλοῦτον δὲ τούτῳ τῷ βασιλέι γενέσθαι ἀργύρου μέγαν, τὸν οὐδένα τῶν ὕστερον ἐπιτραφέντων βασιλέων δύνασθαι ὑπερβαλέσθαι οὐδ’ ἐγγὺς ἐλθεῖν. βουλόμενον δὲ αὐτὸν ἐν ἀσφαλείῃ τὰ χρήματα θησαυρίζειν οἰκοδομέεσθαι οἴκημα λίθινον, τοῦ τῶν τοίχων ἕνα ἐς τὸ ἔξω μέρος τῆς οἰκίης ἔχειν. τὸν δὲ ἐργαζόμενον ἐπιβουλεύοντα τάδε μηχανᾶσθαι· τῶν λίθων παρασκευάσασθαι ἕνα ἐξαιρετὸν εἶναι ἐκ τοῦ τοίχου ῥηιδίως καὶ ὑπὸ δύο ἀνδρῶν καὶ ὑπὸ ἑνός. ὡς δὲ ἐπετελέσθη τὸ οἴκημα, τὸν μὲν βασιλέα θησαυρίσαι τὰ χρήματα ἐν αὐτῷ· χρόνου δὲ περιιόντος τὸν οἰκοδόμον περὶ τελευτὴν τοῦ βίου ἐόντα ἀνακαλέσασθαι τοὺς παῖδας (εἶναι γὰρ αὐτῷ δύο), τούτοισι δὲ ἀπηγήσασθαι ὡς ἐκείνων προορῶν, ὅκως βίον ἄφθονον ἔχωσι, τεχνάσαιτο οἰκοδομέων τὸν θησαυρὸν τοῦ βασιλέος· σαφέως δὲ αὐτοῖσι πάντα ἐξηγησάμενον τὰ περὶ τὴν ἐξαίρεσιν τοῦ λίθου δοῦναι τὰ μέτρα αὐτοῦ, λέγοντα ὡς ταῦτα διαφυλάσσοντες ταμίαι τῶν βασιλέος χρημάτων ἔσονται. καὶ τὸν μὲν τελευτῆσαι τὸν βίον, τοὺς δὲ παῖδας οὐκ ἐς μακρὴν ἔργου ἔχεσθαι, ἐπελθόντας δὲ ἐπὶ τὰ βασιλήια νυκτὸς καὶ τὸν λίθον ἐπὶ τῷ οἰκοδομήματι ἀνευρόντας ῥηιδίως μεταχειρίσασθαι καὶ τῶν χρημάτων πολλὰ ἐξενείκασθαι. ὡς δὲ τυχεῖν τὸν βασιλέα ἀνοίξαντα τὸ οἴκημα, θωμάσαι ἰδόντα τῶν χρημάτων καταδεᾶ τὰ ἀγγήια, οὐκ ἔχειν δὲ ὅντινα ἐπαιτιᾶται, τῶν τε σημάντρων ἐόντων σόων καὶ τοῦ οἰκήματος κεκληιμένου. ὡς δὲ αὐτῷ καὶ δὶς καὶ τρὶς ἀνοίξαντι αἰεὶ ἐλάσσω φαίνεσθαι τὰ χρήματα (τοὺς γὰρ κλέπτας οὐκ ἀνιέναι κεραΐζοντας), ποιῆσαί μιν τάδε· πάγας προστάξαι ἐργάσασθαι καὶ ταύτας περὶ τὰ ἀγγήια ἐν τοῖσι τὰ χρήματα ἐνῆν στῆσαι. τῶν δὲ φωρῶν ὥσπερ ἐν τῷ πρὸ τοῦ χρόνῳ ἐλθόντων καὶ ἐσδύντος τοῦ ἑτέρου αὐτῶν, ἐπεὶ πρὸς τὸ ἄγγος προσῆλθε, ἰθέως τῇ πάγῃ ἐνέχεσθαι. ὡς δὲ γνῶναι αὐτὸν ἐν οἵῳ κακῷ ἦν, ἰθέως καλέειν τὸν ἀδελφεὸν καὶ δηλοῦν αὐτῷ τὰ παρεόντα, καὶ κελεύειν τὴν ταχίστην ἐσδύντα ἀποταμεῖν αὐτοῦ τὴν κεφαλήν, ὅκως μὴ αὐτὸς ὀφθεὶς καὶ γνωρισθεὶς ὃς εἴη προσαπολέσῃ κἀκεῖνον. τῷ δὲ δόξαι εὖ λέγειν, καὶ ποιῆσαί μιν πεισθέντα ταῦτα, καὶ καταρμόσαντα τὸν λίθον ἀπιέναι ἐπ’ οἴκου, φέροντα τὴν κεφαλὴν τοῦ ἀδελφεοῦ. ὡς δὲ ἡμέρη ἐγένετο, ἐσελθόντα τὸν βασιλέα ἐς τὸ οἴκημα ἐκπεπλῆχθαι ὁρῶντα τὸ σῶμα τοῦ φωρὸς ἐν τῇ πάγῃ ἄνευ τῆς κεφαλῆς ἐόν, τὸ δὲ οἴκημα ἀσινὲς καὶ οὔτε ἔσοδον οὔτε ἔκδυσιν οὐδεμίαν ἔχον. ἀπορεύμενον δέ μιν τάδε ποιῆσαι· τοῦ φωρὸς τὸν νέκυν κατὰ τοῦ τείχεος κατακρεμάσαι, φυλάκους δὲ αὐτοῦ καταστήσαντα ἐντείλασθαί σφι, τὸν ἂν ἴδωνται ἀποκλαύσαντα ἢ κατοικτισάμενον, συλλαβόντας ἄγειν πρὸς ἑωυτόν. ἀνακρεμαμένου δὲ τοῦ νέκυος τὴν μητέρα δεινῶς φέρειν, λόγους δὲ πρὸς τὸν περιεόντα παῖδα ποιευμένην προστάσσειν αὐτῷ ὅτεῳ τρόπῳ δύναται μηχανᾶσθαι ὅκως τὸ σῶμα τοῦ ἀδελφεοῦ καταλύσας κομιεῖ· εἰ δὲ τούτων ἀμελήσει, διαπειλέειν αὐτὴν ὡς ἐλθοῦσα πρὸς τὸν βασιλέα μηνύσει αὐτὸν ἔχοντα τὰ χρήματα. ὡς δὲ χαλεπῶς ἐλαμβάνετο ἡ μήτηρ τοῦ περιεόντος παιδὸς καὶ πολλὰ πρὸς αὐτὴν λέγων οὐκ ἔπειθε, ἐπιτεχνήσασθαι τοιάδε μιν· ὄνους κατασκευασάμενον καὶ ἀσκοὺς πλήσαντα οἴνου ἐπιθεῖναι ἐπὶ τῶν ὄνων καὶ ἔπειτα ἐλαύνειν αὐτούς· ὡς δὲ κατὰ τοὺς φυλάσσοντας ἦν τὸν κρεμάμενον νέκυν, ἐπισπάσαντα τῶν ἀσκῶν δύο ἢ τρεῖς ποδεῶνας αὐτὸν λύειν ἀπαμμένους· ὡς δὲ ἔρρεε ὁ οἶνος, τὴν κεφαλήν μιν κόπτεσθαι μεγάλα βοῶντα ὡς οὐκ ἔχοντα πρὸς ὁκοῖον τῶν ὄνων πρῶτον τράπηται. τοὺς δὲ φυλάκους ὡς ἰδεῖν πολλὸν ῥέοντα τὸν οἶνον, συντρέχειν ἐς τὴν ὁδὸν ἀγγήια ἔχοντας, καὶ τὸν ἐκκεχυμένον οἶνον συγκομίζειν ἐν κέρδεϊ ποιευμένους· τὸν δὲ διαλοιδορέεσθαι πᾶσι ὀργὴν προσποιεύμενον, παραμυθευμένων δὲ αὐτὸν τῶν φυλάκων χρόνῳ πρηΰνεσθαι προσποιέεσθαι καὶ ὑπίεσθαι τῆς ὀργῆς, τέλος δὲ ἐξελάσαι αὐτὸν τοὺς ὄνους ἐκ τῆς ὁδοῦ καὶ κατασκευάζειν. ὡς δὲ λόγους τε πλέους ἐγγίνεσθαι καί τινα καὶ σκῶψαι μιν καὶ ἐς γέλωτα προαγαγέσθαι, ἐπιδοῦναι αὐτοῖσι τῶν ἀσκῶν ἕνα· τοὺς δὲ αὐτοῦ ὥσπερ εἶχον κατακλιθέντας πίνειν διανοέεσθαι, καὶ ἐκεῖνον παραλαμβάνειν καὶ κελεύειν μετ’ ἑωυτῶν μείναντα συμπίνειν· τὸν δὲ πεισθῆναί τε δὴ καὶ καταμεῖναι. ὡς δέ μιν παρὰ τὴν πόσιν φιλοφρόνως ἠσπάζοντο, ἐπιδοῦναι αὐτοῖσι καὶ ἄλλον τῶν ἀσκῶν· δαψιλέι δὲ τῷ ποτῷ χρησαμένους τοὺς φυλάκους ὑπερμεθυσθῆναι καὶ κρατηθέντας ὑπὸ τοῦ ὕπνου αὐτοῦ ἔνθα περ ἔπινον κατακοιμηθῆναι. τὸν δέ, ὡς πρόσω ἦν τῆς νυκτός, τό τε σῶμα τοῦ ἀδελφεοῦ καταλῦσαι καὶ τῶν φυλάκων ἐπὶ λύμῃ πάντων ξυρῆσαι τὰς δεξιὰς παρηίδας, ἐπιθέντα δὲ τὸν νέκυν ἐπὶ τοὺς ὄνους ἀπελαύνειν ἐπ’ οἴκου, ἐπιτελέσαντα τῇ μητρὶ τὰ προσταχθέντα. τὸν δὲ βασιλέα, ὡς αὐτῷ ἀπηγγέλθη τοῦ φωρὸς ὁ νέκυς ἐκκεκλεμμένος, δεινὰ ποιέειν· πάντως δὲ βουλόμενον εὑρεθῆναι ὅστις κοτὲ εἴη ὁ ταῦτα μηχανώμενος, ποιῆσαί μιν τάδε, ἐμοὶ μὲν οὐ πιστά· τὴν θυγατέρα τὴν ἑωυτοῦ κατίσαι ἐπ’ οἰκήματος, ἐντειλάμενον πάντας τε ὁμοίως προσδέκεσθαι, καὶ πρὶν συγγενέσθαι, ἀναγκάζειν λέγειν αὐτῇ ὅ τι δὴ ἐν τῷ βίῳ ἔργασται αὐτῷ σοφώτατον καὶ ἀνοσιώτατον· ὃς δ’ ἂν ἀπηγήσηται τὰ περὶ τὸν φῶρα γεγενημένα, τοῦτον συλλαμβάνειν καὶ μὴ ἀπιέναι ἔξω. ὡς δὲ τὴν παῖδα ποιέειν τὰ ἐκ τοῦ πατρὸς προσταχθέντα, τὸν φῶρα πυθόμενον τῶν εἵνεκα ταῦτα ἐπρήσσετο, βουληθέντα πολυτροπίῃ τοῦ βασιλέος περιγενέσθαι ποιέειν τάδε· νεκροῦ προσφάτου ἀποταμόντα ἐν τῷ ὤμῳ τὴν χεῖρα ἰέναι αὐτὸν ἔχοντα αὐτὴν ὑπὸ τῷ ἱματίῳ. ἐσελθόντα δὲ ὡς τοῦ βασιλέος τὴν θυγατέρα καὶ εἰρωτώμενον τά περ καὶ οἱ ἄλλοι, ἀπηγήσασθαι ὡς ἀνοσιώτατον μὲν εἴη ἐργασμένος ὅτι τοῦ ἀδελφεοῦ ἐν τῷ θησαυρῷ τοῦ βασιλέος ὑπὸ πάγης ἁλόντος ἀποτάμοι τὴν κεφαλήν, σοφώτατον δὲ ὅτι τοὺς φυλάκους καταμεθύσας καταλύσειε τοῦ ἀδελφεοῦ κρεμάμενον τὸν νέκυν. τὴν δὲ ὡς ἤκουσε ἅπτεσθαι αὐτοῦ. τὸν δὲ φῶρα ἐν τῷ σκότεϊ προτεῖναι αὐτῇ τοῦ νεκροῦ τὴν χεῖρα· τὴν δὲ ἐπιλαβομένην ἔχειν, νομίζουσαν αὐτοῦ ἐκείνου τῆς χειρὸς ἀντέχεσθαι· τὸν δὲ φῶρα προέμενον αὐτῇ οἴχεσθαι διὰ θυρέων φεύγοντα. ὡς δὲ καὶ ταῦτα ἐς τὸν βασιλέα ἀνηνείχθη, ἐκπεπλῆχθαι μὲν ἐπὶ τῇ πολυφροσύνῃ τε καὶ τόλμῃ τοῦ ἀνθρώπου, τέλος δὲ διανέμοντα ἐς πάσας τὰς πόλις ἐπαγγέλλεσθαι ἀδείην τε διδόντα καὶ μεγάλα ὑποδεκόμενον ἐλθόντι ἐς ὄψιν τὴν ἑωυτοῦ. τὸν δὲ φῶρα πιστεύσαντα ἐλθεῖν πρὸς αὐτόν, Ῥαμψίνιτον δὲ μεγάλως θωμάσαι, καί οἱ τὴν θυγατέρα ταύτην συνοικίσαι ὡς πλεῖστα ἐπισταμένῳ ἀνθρώπων. Αἰγυπτίους μὲν γὰρ τῶν ἄλλων προκεκρίσθαι, ἐκεῖνον δὲ Αἰγυπτίων.", "st": "2.121"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα ἔλεγον τοῦτον τὸν βασιλέα ζωὸν καταβῆναι κάτω ἐς τὸν οἱ Ἕλληνες Ἅιδην νομίζουσι εἶναι, καὶ κεῖθι συγκυβεύειν τῇ Δήμητρι, καὶ τὰ μὲν νικᾶν αὐτὴν τὰ δὲ ἑσσοῦσθαι ὑπ’ αὐτῆς, καί μιν πάλιν ἀπικέσθαι δῶρον ἔχοντα παρ’ αὐτῆς χειρόμακτρον χρύσεον. ἀπὸ δὲ τῆς Ῥαμψινίτου καταβάσιος, ὡς πάλιν ἀπίκετο, ὁρτὴν δὴ ἀνάγειν Αἰγυπτίους ἔφασαν· τὴν καὶ ἐγὼ οἶδα ἔτι καὶ ἐς ἐμὲ ἐπιτελέοντας αὐτούς, οὐ μέντοι εἴ γε διὰ ταῦτα ὁρτάζουσι ἔχω λέγειν. φᾶρος δὲ αὐτημερὸν ἐξυφήναντες οἱ ἱρέες κατ’ ὦν ἔδησαν ἑνὸς ἑωυτῶν μίτρῃ τοὺς ὀφθαλμούς, ἀγαγόντες δέ μιν ἔχοντα τὸ φᾶρος ἐς ὁδὸν φέρουσαν ἐς ἱρὸν Δήμητρος αὐτοὶ ἀπαλλάσσονται ὀπίσω· τὸν δὲ ἱρέα τοῦτον καταδεδεμένον τοὺς ὀφθαλμοὺς λέγουσι ὑπὸ δύο λύκων ἄγεσθαι ἐς τὸ ἱρὸν τῆς Δήμητρος ἀπέχον τῆς πόλιος εἴκοσι σταδίους, καὶ αὖτις ὀπίσω ἐκ τοῦ ἱροῦ ἀπάγειν μιν τοὺς λύκους ἐς τὠυτὸ χωρίον.", "st": "2.122"}, {"sp": "N", "t": "τοῖσι μέν νυν ὑπ’ Αἰγυπτίων λεγομένοισι χράσθω ὅτεῳ τὰ τοιαῦτα πιθανά ἐστι· ἐμοὶ δὲ παρὰ πάντα τὸν λόγον ὑπόκειται ὅτι τὰ λεγόμενα ὑπ’ ἑκάστων ἀκοῇ γράφω. ἀρχηγετέειν δὲ τῶν κάτω Αἰγύπτιοι λέγουσι Δήμητρα καὶ Διόνυσον. πρῶτοι δὲ καὶ τόνδε τὸν λόγον Αἰγύπτιοι εἰσὶ οἱ εἰπόντες, ὡς ἀνθρώπου ψυχὴ ἀθάνατος ἐστί, τοῦ σώματος δὲ καταφθίνοντος ἐς ἄλλο ζῷον αἰεὶ γινόμενον ἐσδύεται, ἐπεὰν δὲ πάντα περιέλθῃ τὰ χερσαῖα καὶ τὰ θαλάσσια καὶ τὰ πετεινά, αὖτις ἐς ἀνθρώπου σῶμα γινόμενον ἐσδύνει· τὴν περιήλυσιν δὲ αὐτῇ γίνεσθαι ἐν τρισχιλίοισι ἔτεσι. τούτῳ τῷ λόγῳ εἰσὶ οἳ Ἑλλήνων ἐχρήσαντο, οἳ μὲν πρότερον οἳ δὲ ὕστερον, ὡς ἰδίῳ ἑωυτῶν ἐόντι· τῶν ἐγὼ εἰδὼς τὰ οὐνόματα οὐ γράφω.", "st": "2.123"}, {"sp": "N", "t": "μέχρι μέν νυν Ῥαμψινίτου βασιλέος εἶναι ἐν Αἰγύπτῳ πᾶσαν εὐνομίην ἔλεγον καὶ εὐθηνέειν Αἴγυπτον μεγάλως, μετὰ δὲ τοῦτον βασιλεύσαντα σφέων Χέοπα ἐς πᾶσαν κακότητα ἐλάσαι. κατακληίσαντα γάρ μιν πάντα τὰ ἱρὰ πρῶτα μὲν σφέας θυσιέων τουτέων ἀπέρξαι, μετὰ δὲ ἐργάζεσθαι ἑωυτῷ κελεύειν πάντας Αἰγυπτίους. τοῖσι μὲν δὴ ἀποδεδέχθαι ἐκ τῶν λιθοτομιέων τῶν ἐν τῷ Ἀραβίῳ ὄρεϊ, ἐκ τουτέων ἕλκειν λίθους μέχρι τοῦ Νείλου· διαπεραιωθέντας δὲ τὸν ποταμὸν πλοίοισι τοὺς λίθους ἑτέροισι ἐπέταξε ἐκδέκεσθαι καὶ πρὸς τὸ Λιβυκὸν καλεύμενον ὄρος, πρὸς τοῦτο ἕλκειν. ἐργάζοντο δὲ κατὰ δέκα μυριάδας ἀνθρώπων αἰεὶ τὴν τρίμηνον ἑκάστην. χρόνον δὲ ἐγγενέσθαι τριβομένῳ τῷ λεῷ δέκα ἔτεα μὲν τῆς ὁδοῦ κατ’ ἣν εἷλκον τοὺς λίθους, τὴν ἔδειμαν ἔργον ἐὸν οὐ πολλῷ τεῳ ἔλασσον τῆς πυραμίδος. ὡς ἐμοὶ δοκέειν· τῆς μὲν γὰρ μῆκος εἰσὶ πέντε στάδιοι, εὖρος δὲ δέκα ὀργυιαί, ὕψος δέ, τῇ ὑψηλοτάτη ἐστὶ αὐτὴ ἑωυτῆς, ὀκτὼ ὀργυιαί, λίθου δὲ ξεστοῦ καὶ ζῴων ἐγγεγλυμμένων· ταύτης τε δὴ τὰ δέκα ἔτεα γενέσθαι καὶ τῶν ἐπὶ τοῦ λόφου ἐπ’ οὗ ἑστᾶσι αἱ πυραμίδες, τῶν ὑπὸ γῆν οἰκημάτων, τὰς ἐποιέετο θήκας ἑωυτῷ ἐν νήσῳ, διώρυχα τοῦ Νείλου ἐσαγαγών. τῇ δὲ πυραμίδι αὐτῇ χρόνον γενέσθαι εἴκοσι ἔτεα ποιευμένῃ· τῆς ἐστὶ πανταχῇ μέτωπον ἕκαστον ὀκτὼ, πλέθρα ἐούσης τετραγώνου καὶ ὕψος ἴσον, λίθου δὲ ξεστοῦ τε καὶ ἁρμοσμένου τὰ μάλιστα· οὐδεὶς τῶν λίθων τριήκοντα ποδῶν ἐλάσσων.", "st": "2.124"}, {"sp": "N", "t": "ἐποιήθη δὲ ὧδε αὕτη ἡ πυραμίς· ἀναβαθμῶν τρόπον, τὰς μετεξέτεροι κρόσσας οἳ δὲ βωμίδας ὀνομάζουσι, τοιαύτην τὸ πρῶτον ἐπείτε ἐποίησαν αὐτήν, ἤειρον τοὺς ἐπιλοίπους λίθους μηχανῇσι ξύλων βραχέων πεποιημένῃσι, χαμᾶθεν μὲν ἐπὶ τὸν πρῶτον στοῖχον τῶν ἀναβαθμῶν ἀείροντες· ὅκως δὲ ἀνίοι ὁ λίθος ἐπ’ αὐτόν, ἐς ἑτέρην μηχανὴν ἐτίθετο ἑστεῶσαν ἐπὶ τοῦ πρώτου στοίχου, ἀπὸ τούτου δὲ ἐπὶ τὸν δεύτερον εἵλκετο στοῖχον ἐπ’ ἄλλης μηχανῆς· ὅσοι γὰρ δὴ στοῖχοι ἦσαν τῶν ἀναβαθμῶν, τοσαῦται καὶ μηχαναὶ ἦσαν, εἴτε καὶ τὴν αὐτὴν μηχανὴν ἐοῦσαν μίαν τε καὶ εὐβάστακτον μετεφόρεον ἐπὶ στοῖχον ἕκαστον, ὅκως τὸν λίθον ἐξέλοιεν· λελέχθω γὰρ ἡμῖν ἐπ’ ἀμφότερα, κατά περ λέγεται. ἐξεποιήθη δ’ ὦν τὰ ἀνώτατα αὐτῆς πρῶτα, μετὰ δὲ τὰ ἐχόμενα τούτων ἐξεποίευν, τελευταῖα δὲ αὐτῆς τὰ ἐπίγαια καὶ τὰ κατωτάτω ἐξεποίησαν. σεσήμανται δὲ διὰ γραμμάτων Αἰγυπτίων ἐν τῇ πυραμίδι ὅσα ἔς τε συρμαίην καὶ κρόμμυα καὶ σκόροδα ἀναισιμώθη τοῖσι ἐργαζομένοισι· καὶ ὡς ἐμὲ εὖ μεμνῆσθαι τὰ ὁ ἑρμηνεύς μοι ἐπιλεγόμενος τὰ γράμματα ἔφη, ἑξακόσια καὶ χίλια τάλαντα ἀργυρίου τετελέσθαι. εἰ δ’ ἔστι οὕτω ἔχοντα ταῦτα, κόσα οἰκὸς ἄλλα δεδαπανῆσθαι ἐστὶ ἔς τε σίδηρον τῷ ἐργάζοντο καὶ σιτία καὶ ἐσθῆτα τοῖσι ἐργαζομένοισι, ὁκότε χρόνον μὲν οἰκοδόμεον τὰ ἔργα τὸν εἰρημένον, ἄλλον δέ, ὡς ἐγὼ δοκέω, ἐν τῷ τοὺς λίθους ἔταμνον καὶ ἦγον καὶ τὸ ὑπὸ γῆν ὄρυγμα ἐργάζοντο, οὐκ ὀλίγον χρόνον.", "st": "2.125"}, {"sp": "N", "t": "ἐς τοῦτο δὲ ἐλθεῖν Χέοπα κακότητος ὥστε χρημάτων δεόμενον τὴν θυγατέρα τὴν ἑωυτοῦ κατίσαντα ἐπ’ οἰκήματος προστάξαι πρήσσεσθαι ἀργύριον ὁκόσον δή τι· οὐ γὰρ δὴ τοῦτό γε ἔλεγον. τὴν δὲ τά τε ὑπὸ τοῦ πατρὸς ταχθέντα πρήσσεσθαι, ἰδίῃ δὲ καὶ αὐτὴν διανοηθῆναι μνημήιον καταλιπέσθαι, καὶ τοῦ ἐσιόντος πρὸς αὐτὴν ἑκάστου δέεσθαι ὅκως ἂν αὐτῇ ἕνα λίθον ἐν τοῖσι ἔργοισι δωρέοιτο. ἐκ τούτων δὲ τῶν λίθων ἔφασαν τὴν πυραμίδα οἰκοδομηθῆναι τὴν ἐν μέσῳ τῶν τριῶν ἑστηκυῖαν, ἔμπροσθε τῆς μεγάλης πυραμίδος, τῆς ἐστὶ τὸ κῶλον ἕκαστον ὅλου καὶ ἡμίσεος πλέθρου.", "st": "2.126"}, {"sp": "N", "t": "βασιλεῦσαι δὲ τὸν Χέοπα τοῦτον Αἰγύπτιοι ἔλεγον πεντήκοντα ἔτεα, τελευτήσαντος δὲ τούτου ἐκδέξασθαι τὴν βασιληίην τὸν ἀδελφεὸν αὐτοῦ Χεφρῆνα· καὶ τοῦτον δὲ τῷ αὐτῷ τρόπῳ διαχρᾶσθαι τῷ ἑτέρῳ τά τε ἄλλα καὶ πυραμίδα ποιῆσαι, ἐς μὲν τὰ ἐκείνου μέτρα οὐκ ἀνήκουσαν· ταῦτα γὰρ ὦν καὶ ἡμεῖς ἐμετρήσαμεν· (οὔτε γὰρ ὕπεστι οἰκήματα ὑπὸ γῆν, οὔτε ἐκ τοῦ Νείλου διῶρυξ ἥκει ἐς αὐτὴν ὥσπερ ἐς τὴν ἑτέρην ῥέουσα· δι’ οἰκοδομημένου δὲ αὐλῶνος ἔσω νῆσον περιρρέει, ἐν τῇ αὐτὸν λέγουσι κεῖσθαι Χέοπα)· ὑποδείμας δὲ τὸν πρῶτον δόμον λίθου Αἰθιοπικοῦ ποικίλου, τεσσεράκοντα πόδας ὑποβὰς τῆς ἑτέρης τὠυτὸ μέγαθος, ἐχομένην τῆς μεγάλης οἰκοδόμησε. ἑστᾶσι δὲ ἐπὶ λόφου τοῦ αὐτοῦ ἀμφότεραι, μάλιστα ἐς ἑκατὸν πόδας ὑψηλοῦ. βασιλεῦσαι δὲ ἔλεγον Χεφρῆνα ἓξ καὶ πεντήκοντα ἔτεα.", "st": "2.127"}, {"sp": "N", "t": "ταῦτα ἕξ τε καὶ ἑκατὸν λογίζονται ἔτεα, ἐν τοῖσι Αἰγυπτίοισί τε πᾶσαν εἶναι κακότητα καὶ τὰ ἱρὰ χρόνου τοσούτου κατακληισθέντα οὐκ ἀνοιχθῆναι. τούτους ὑπὸ μίσεος οὐ κάρτα θέλουσι Αἰγύπτιοι ὀνομάζειν, ἀλλὰ καὶ τὰς πυραμίδας καλέουσι ποιμένος Φιλίτιος, ὃς τοῦτον τὸν χρόνον ἔνεμε κτήνεα κατὰ ταῦτα τὰ χωρία.", "st": "2.128"}, {"sp": "N", "t": "μετὰ δὲ τοῦτον βασιλεῦσαι Αἰγύπτου Μυκερῖνον ἔλεγον Χέοπος παῖδα· τῷ τὰ μὲν τοῦ πατρὸς ἔργα ἀπαδεῖν, τὸν δὲ τά τε ἱρὰ ἀνοῖξαι καὶ τὸν λεὼν τετρυμένον ἐς τὸ ἔσχατον κακοῦ ἀνεῖναι πρὸς ἔργα τε καὶ θυσίας, δίκας δέ σφι πάντων βασιλέων δικαιότατα κρίνειν. κατὰ τοῦτο μέν νυν τὸ ἔργον ἁπάντων ὅσοι ἤδη βασιλέες ἐγένοντο Αἰγυπτίων αἰνέουσι μάλιστα τοῦτον. τά τε ἄλλα γάρ μιν κρίνειν εὖ, καὶ δὴ καὶ τῷ ἐπιμεμφομένῳ ἐκ τῆς δίκης παρ’ ἑωυτοῦ διδόντα ἄλλα ἀποπιμπλάναι αὐτοῦ τὸν θυμόν. ἐόντι δὲ ἠπίῳ τῷ Μυκερίνῳ κατὰ τοὺς πολιήτας καὶ ταῦτα ἐπιτηδεύοντι πρῶτον κακῶν ἄρξαι τὴν θυγατέρα ἀποθανοῦσαν αὐτοῦ, τὴν μοῦνόν οἱ εἶναι ἐν τοῖσι οἰκίοισι τέκνον. τὸν δὲ ὑπεραλγήσαντά τε τῷ περιεπεπτώκεε πρήγματι, καὶ βουλόμενον περισσότερόν τι τῶν ἄλλων θάψαι τὴν θυγατέρα, ποιήσασθαι βοῦν ξυλίνην κοίλην, καὶ ἔπειτα καταχρυσώσαντά μιν ταύτην ἔσω ἐν αὐτῇ θάψαι ταύτην δὴ τὴν ἀποθανοῦσαν θυγατέρα.", "st": "2.129"}, {"sp": "N", "t": "αὕτη ὦν ἡ βοῦς γῇ οὐκ ἐκρύφθη, ἀλλ’ ἔτι καὶ ἐς ἐμὲ ἦν φανερή, ἐν Σάι μὲν πόλι ἐοῦσα, κειμένη δὲ ἐν τοῖσι βασιληίοισι ἐν οἰκήματι ἠσκημένῳ· θυμιήματα δὲ παρ’ αὐτῇ παντοῖα καταγίζουσι ἀνὰ πᾶσαν ἡμέρην, νύκτα δὲ ἑκάστην πάννυχος λύχνος παρακαίεται. ἀγχοῦ δὲ τῆς βοὸς ταύτης ἐν ἄλλῳ οἰκήματι εἰκόνες τῶν παλλακέων τῶν Μυκερίνου ἑστᾶσι, ὡς ἔλεγον οἱ ἐν Σάι πόλι ἱρέες· ἑστᾶσι μὲν γὰρ ξύλιναι κολοσσοί, ἐοῦσαι ἀριθμὸν ὡς εἴκοσι μάλιστά κῃ, γυμναὶ ἐργασμέναι· αἵτινες μέντοι εἰσί, οὐκ ἔχω εἰπεῖν πλὴν ἢ τὰ λεγόμενα.", "st": "2.130"}, {"sp": "N", "t": "οἳ δὲ τινὲς λέγουσι περὶ τῆς βοὸς ταύτης καὶ τῶν κολοσσῶν τόνδε τὸν λόγον, ὡς Μυκερῖνος ἠράσθη τῆς ἑωυτοῦ θυγατρὸς καὶ ἔπειτα ἐμίγη οἱ ἀεκούσῃ· μετὰ δὲ λέγουσι ὡς ἡ παῖς ἀπήγξατο ὑπὸ ἄχεος, ὁ δέ μιν ἔθαψε ἐν τῇ βοῒ ταύτῃ, ἡ δὲ μήτηρ αὐτῆς τῶν ἀμφιπόλων τῶν προδουσέων τὴν θυγατέρα τῷ πατρὶ ἀπέταμε τὰς χεῖρας, καὶ νῦν τὰς εἰκόνας αὐτέων εἶναι πεπονθυίας τά περ αἱ ζωαὶ ἔπαθον. ταῦτα δὲ λέγουσι φλυηρέοντες, ὡς ἐγὼ δοκέω, τά τε ἄλλα καὶ δὴ καὶ τὰ περὶ τὰς χεῖρας τῶν κολοσσῶν· ταύτας γὰρ ὦν καὶ ἡμεῖς ὡρῶμεν ὅτι ὑπὸ χρόνου τὰς χεῖρας ἀποβεβλήκασι, αἳ ἐν ποσὶ αὐτέων ἐφαίνοντο ἐοῦσαι ἔτι καὶ ἐς ἐμέ.", "st": "2.131"}, {"sp": "N", "t": "ἡ δὲ βοῦς τὰ μὲν ἄλλα κατακέκρυπται φοινικέῳ εἵματι, τὸν αὐχένα δὲ καὶ τὴν κεφαλὴν φαίνει κεχρυσωμένα παχέι κάρτα χρυσῷ· μεταξὺ δὲ τῶν κερέων ὁ τοῦ ἡλίου κύκλος μεμιμημένος ἔπεστι χρύσεος. ἔστι δὲ ἡ βοῦς οὐκ ὀρθὴ ἀλλ’ ἐν γούνασι κειμένη, μέγαθος δὲ ὅση περ μεγάλη βοῦς ζωή. ἐκφέρεται δὲ ἐκ τοῦ οἰκήματος ἀνὰ πάντα ἔτεα, ἐπεὰν τύπτωνται Αἰγύπτιοι τὸν οὐκ ὀνομαζόμενον θεὸν ὑπ’ ἐμεῦ ἐπὶ τοιούτῳ πρήγματι· τότε ὦν καὶ τὴν βοῦν ἐκφέρουσι ἐς τὸ φῶς· φασὶ γὰρ αὐτὴν δεηθῆναι τοῦ πατρὸς Μυκερίνου ἀποθνήσκουσαν ἐν τῷ ἐνιαυτῷ ἅπαξ μιν τὸν ἥλιον κατιδεῖν.", "st": "2.132"}, {"sp": "N", "t": "μετὰ δὲ τῆς θυγατρὸς τὸ πάθος δεύτερα τούτῳ τῷ βασιλέι τάδε γενέσθαι· ἐλθεῖν οἱ μαντήιον ἐκ Βουτοῦς πόλιος ὡς μέλλοι ἓξ ἔτεα μοῦνον βιοὺς τῷ ἑβδόμῳ τελευτήσειν. τὸν δὲ δεινὸν ποιησάμενον πέμψαι ἐς τὸ μαντήιον τῷ θεῷ ὀνείδισμα, ἀντιμεμφόμενον ὅτι ὁ μὲν αὐτοῦ πατὴρ καὶ πάτρως, ἀποκληίσαντες τὰ ἱρὰ καὶ θεῶν οὐ μεμνημένοι ἀλλὰ καὶ τοὺς ἀνθρώπους φθείροντες, ἐβίωσαν χρόνον ἐπὶ πολλόν, αὐτὸς δ’ εὐσεβὴς ἐὼν μέλλοι ταχέως οὕτω τελευτήσειν. ἐκ δὲ τοῦ χρηστηρίου αὐτῷ δεύτερα ἐλθεῖν λέγοντα τούτων εἵνεκα καὶ συνταχύνειν αὐτὸν τὸν βίον· οὐ γὰρ ποιῆσαί μιν τὸ χρεὸν ἦν ποιέειν· δεῖν γὰρ Αἴγυπτον κακοῦσθαι ἐπ’ ἔτεα πεντήκοντά τε καὶ ἑκατόν, καὶ τοὺς μὲν δύο τοὺς πρὸ ἐκείνου γενομένους βασιλέας μαθεῖν τοῦτο, κεῖνον δὲ οὔ. ταῦτα ἀκούσαντα τὸν Μυκερῖνον, ὡς κατακεκριμένων ἤδη οἱ τούτων, λύχνα ποιησάμενον πολλά, ὅκως γίνοιτο νύξ, ἀνάψαντα αὐτὰ πίνειν τε καὶ εὐπαθέειν, οὔτε ἡμέρης οὔτε νυκτὸς ἀνιέντα, ἔς τε τὰ ἕλεα καὶ τὰ ἄλσεα πλανώμενον καὶ ἵνα πυνθάνοιτο εἶναι ἐνηβητήρια ἐπιτηδεότατα. ταῦτα δὲ ἐμηχανᾶτο θέλων τὸ μαντήιον ψευδόμενον ἀποδέξαι, ἵνα οἱ δυώδεκα ἔτεα ἀντὶ ἓξ ἐτέων γένηται, αἱ νύκτες ἡμέραι ποιεύμεναι.", "st": "2.133"}, {"sp": "N", "t": "πυραμίδα δὲ οὗτος ἀπελίπετο πολλὸν ἐλάσσω τοῦ πατρός, εἴκοσι ποδῶν καταδέουσαν κῶλον ἕκαστον τριῶν πλέθρων, ἐούσης τετραγώνου, λίθου δὲ ἐς τὸ ἥμισυ Αἰθιοπικοῦ· τὴν δὴ μετεξέτεροι φασὶ Ἑλλήνων Ῥοδώπιος ἑταίρης γυναικὸς εἶναι, οὐκ ὀρθῶς λέγοντες. οὐδὲ ὦν οὐδὲ εἰδότες μοι φαίνονται λέγειν οὗτοι ἥτις ἦν ἡ Ῥοδῶπις· οὐ γὰρ ἄν οἱ πυραμίδα ἀνέθεσαν ποιήσασθαι τοιαύτην, ἐς τὴν ταλάντων χιλιάδες ἀναρίθμητοι ὡς λόγῳ εἰπεῖν ἀναισίμωνται· πρὸς δὲ ὅτι κατὰ Ἄμασιν βασιλεύοντα ἦν ἀκμάζουσα Ῥοδῶπις, ἀλλ’ οὐ κατὰ τοῦτον. ἔτεσι γὰρ κάρτα πολλοῖσι ὕστερον τούτων τῶν βασιλέων τῶν τὰς πυραμίδας ταύτας ἦν λιπομένων Ῥοδῶπις, γενεὴν μὲν ἀπὸ Θρηίκης, δούλη δὲ ἦν Ἰάδμονος τοῦ Ἡφαιστοπόλιος ἀνδρὸς Σαμίου, σύνδουλος δὲ Αἰσώπου τοῦ λογοποιοῦ. καὶ γὰρ οὗτος Ἰάδμονος ἐγένετο, ὡς διέδεξε τῇδε οὐκ ἥκιστα· ἐπείτε γὰρ πολλάκις κηρυσσόντων Δελφῶν ἐκ θεοπροπίου ὃς βούλοιτο ποινὴν τῆς Αἰσώπου ψυχῆς ἀνελέσθαι, ἄλλος μὲν οὐδεὶς ἐφάνη, Ἰάδμονος δὲ παιδὸς παῖς ἄλλος Ἰάδμων ἀνείλετο. οὕτω καὶ Αἴσωπος Ἰάδμονος ἐγένετο.", "st": "2.134"}, {"sp": "N", "t": "Ῥοδῶπις δὲ ἐς Αἴγυπτον ἀπίκετο Ξάνθεω τοῦ Σαμίου κομίσαντος, ἀπικομένη δὲ κατ’ ἐργασίην ἐλύθη χρημάτων μεγάλων ὑπὸ ἀνδρὸς Μυτιληναίου Χαράξου τοῦ Σκαμανδρωνύμου παιδός, ἀδελφεοῦ δὲ Σαπφοῦς τῆς μουσοποιοῦ. οὕτω δὴ ἡ Ῥοδῶπις ἐλευθερώθη, καὶ κατέμεινέ τε ἐν Αἰγύπτῳ καὶ κάρτα ἐπαφρόδιτος γενομένη μεγάλα ἐκτήσατο χρήματα ὡς ἂν εἶναι Ῥοδώπι, ἀτὰρ οὐκ ὥς γε ἐς πυραμίδα τοιαύτην ἐξικέσθαι. τῆς γὰρ τὴν δεκάτην τῶν χρημάτων ἰδέσθαι ἐστὶ ἔτι καὶ ἐς τόδε παντὶ τῷ βουλομένῳ, οὐδὲν δεῖ μεγάλα οἱ χρήματα ἀναθεῖναι. ἐπεθύμησε γὰρ Ῥοδῶπις μνημήιον ἑωυτῆς ἐν τῇ Ἑλλάδι καταλιπέσθαι, ποίημα ποιησαμένη τοῦτο τὸ μὴ τυγχάνοι ἄλλῳ ἐξευρημένον καὶ ἀνακείμενον ἐν ἱρῷ, τοῦτο ἀναθεῖναι ἐς Δελφοὺς μνημόσυνον ἑωυτῆς. τῆς ὦν δεκάτης τῶν χρημάτων ποιησαμένη ὀβελοὺς βουπόρους πολλοὺς σιδηρέους, ὅσον ἐνεχώρεε ἡ δεκάτη οἱ, ἀπέπεμπε ἐς Δελφούς· οἳ καὶ νῦν ἔτι συννενέαται ὄπισθε μὲν τοῦ βωμοῦ τὸν Χῖοι ἀνέθεσαν, ἀντίον δὲ αὐτοῦ τοῦ νηοῦ. φιλέουσι δέ κως ἐν τῇ Ναυκράτι ἐπαφρόδιτοι γίνεσθαι αἱ ἑταῖραι. τοῦτο μὲν γὰρ αὕτη, τῆς πέρι λέγεται ὅδε ὁ λόγος, οὕτω δή τι κλεινὴ ἐγένετο ὡς καὶ οἱ πάντες Ἕλληνες Ῥοδώπιος τὸ οὔνομα ἐξέμαθον· τοῦτο δὲ ὕστερον ταύτης, τῇ οὔνομα ἦν Ἀρχιδίκη, ἀοίδιμος ἀνὰ τὴν Ἑλλάδα ἐγένετο, ἧσσον δὲ τῆς ἑτέρης περιλεσχήνευτος. Χάραξος δὲ ὡς λυσάμενος Ῥοδῶπιν ἀπενόστησε ἐς Μυτιλήνην, ἐν μέλεϊ Σαπφὼ πολλὰ κατεκερτόμησέ μιν.", "st": "2.135"}, {"sp": "N", "t": "Ῥοδώπιος μέν νυν πέρι πέπαυμαι. μετὰ δὲ Μυκερῖνον γενέσθαι Αἰγύπτου βασιλέα ἔλεγον οἱ ἱρέες Ἄσυχιν, τὸν τὰ πρὸς ἥλιον ἀνίσχοντα ποιῆσαι τῷ Ἡφαίστῳ προπύλαια, ἐόντα πολλῷ τε κάλλιστα καὶ πολλῷ μέγιστα· ἔχει μὲν γὰρ καὶ τὰ πάντα προπύλαια τύπους τε ἐγγεγλυμμένους καὶ ἄλλην ὄψιν οἰκοδομημάτων μυρίην, ἐκεῖνα δὲ καὶ μακρῷ μάλιστα. ἐπὶ τούτου βασιλεύοντος ἔλεγον, ἀμιξίης ἐούσης πολλῆς χρημάτων, γενέσθαι νόμον Αἰγυπτίοισι, ἀποδεικνύντα ἐνέχυρον τοῦ πατρὸς τὸν νέκυν οὕτω λαμβάνειν τὸ χρέος· προστεθῆναι δὲ ἔτι τούτῳ τῷ νόμῳ τόνδε, τὸν διδόντα τὸ χρέος καὶ ἁπάσης κρατέειν τῆς τοῦ λαμβάνοντος θήκης, τῷ δὲ ὑποτιθέντι τοῦτο τὸ ἐνέχυρον τήνδε ἐπεῖναι ζημίην μὴ βουλομένῳ ἀποδοῦναι τὸ χρέος, μήτε αὐτῷ ἐκείνῳ τελευτήσαντι εἶναι ταφῆς κυρῆσαι μήτ’ ἐν ἐκείνῳ τῷ πατρωίῳ τάφῳ μήτ’ ἐν ἄλλῳ μηδενί, μήτε ἄλλον μηδένα τῶν ἑωυτοῦ ἀπογενόμενον θάψαι. ὑπερβαλέσθαι δὲ βουλόμενον τοῦτον τὸν βασιλέα τοὺς πρότερον ἑωυτοῦ βασιλέας γενομένους Αἰγύπτου μνημόσυνον πυραμίδα λιπέσθαι ἐκ πλίνθων ποιήσαντα, ἐν τῇ γράμματα ἐν λίθῳ ἐγκεκολαμμένα τάδε λέγοντα ἐστί. μή με κατονοσθῇς πρὸς τὰς λιθίνας πυραμίδας· προέχω γὰρ αὐτέων τοσοῦτον ὅσον ὁ Ζεὺς τῶν ἄλλων θεῶν.", "st": "2.136"}, {"sp": "N", "t": "κοντῷ γὰρ ὑποτύπτοντες ἐς λίμνην, ὅ τι πρόσσχοιτο τοῦ πηλοῦ τῷ κοντῷ, τοῦτο συλλέγοντες πλίνθους εἴρυσαν καί με τρόπῳ τοιούτῳ ἐξεποίησαν.", "st": "2.136b"}, {"sp": "N", "t": "τοῦτον μὲν τοσαῦτα ἀποδέξασθαι. μετὰ δὲ τοῦτον βασιλεῦσαι ἄνδρα τυφλὸν ἐξ Ἀνύσιος πόλιος, τῷ οὔνομα Ἄνυσιν εἶναι. ἐπὶ τούτου βασιλεύοντος ἐλάσαι ἐπ’ Αἴγυπτον χειρὶ πολλῇ Αἰθίοπάς τε καὶ Σαβακῶν τὸν Αἰθιόπων βασιλέα. τὸν μὲν δὴ τυφλὸν τοῦτον οἴχεσθαι φεύγοντα ἐς τὰ ἕλεα, τὸν δὲ Αἰθίοπα βασιλεύειν Αἰγύπτου ἐπ’ ἔτεα πεντήκοντα, ἐν τοῖσι αὐτὸν τάδε ἀποδέξασθαι· ὅκως τῶν τις Αἰγυπτίων ἁμάρτοι τι, κτείνειν μὲν αὐτῶν οὐδένα ἐθέλειν, τὸν δὲ κατὰ μέγαθος τοῦ ἀδικήματος ἑκάστῳ δικάζειν ἐπιτάσσοντα χώματα χοῦν πρὸς τῇ ἑωυτῶν πόλι, ὅθεν ἕκαστος ἦν τῶν ἀδικεόντων. καὶ οὕτω ἔτι αἱ πόλιες ἐγένοντο ὑψηλότεραι· τὸ μὲν γὰρ πρῶτον ἐχώσθησαν ὑπὸ τῶν τὰς διώρυχας ὀρυξάντων ἐπὶ Σεσώστριος βασιλέος, δεύτερα δὲ ἐπὶ τοῦ Αἰθίοπος καὶ κάρτα ὑψηλαὶ ἐγένοντο. ὑψηλέων δὲ καὶ ἑτερέων γενομενέων ἐν τῇ Αἰγύπτῳ πολίων, ὡς ἐμοὶ δοκέει, μάλιστα ἡ ἐν Βουβάστι πόλις ἐξεχώσθη, ἐν τῇ καὶ ἱρόν ἐστι Βουβάστιος ἀξιαπηγητότατον· μέζω μὲν γὰρ ἄλλα καὶ πολυδαπανώτερα ἐστὶ ἱρά, ἡδονὴ δὲ ἰδέσθαι οὐδὲν τούτου μᾶλλον. ἡ δὲ Βούβαστις κατὰ Ἑλλάδα γλῶσσαν ἐστὶ Ἄρτεμις.", "st": "2.137"}, {"sp": "N", "t": "τὸ δ’ ἱρὸν αὐτῆς ὧδε ἔχει. πλὴν τῆς ἐσόδου τὸ ἄλλο νῆσος ἐστί· ἐκ γὰρ τοῦ Νείλου διώρυχες ἐσέχουσι οὐ συμμίσγουσαι ἀλλήλῃσι, ἀλλ’ ἄχρι τῆς ἐσόδου τοῦ ἱροῦ ἑκατέρη ἐσέχει, ἣ μὲν τῇ περιρρέουσα ἣ δὲ τῇ, εὖρος ἐοῦσα ἑκατέρη ἑκατὸν ποδῶν, δένδρεσι κατάσκιος. τὰ δὲ προπύλαια ὕψος μὲν δέκα ὀργυιέων ἐστί, τύποισι δὲ ἑξαπήχεσι ἐσκευάδαται ἀξίοισι λόγου. ἐὸν δ’ ἐν μέσῃ τῇ πόλι τὸ ἱρὸν κατορᾶται πάντοθεν περιιόντι· ἅτε γὰρ τῆς πόλιος μὲν ἐκκεχωσμένης ὑψοῦ, τοῦ δ’ ἱροῦ οὐ κεκινημένου ὡς ἀρχῆθεν ἐποιήθη, ἔσοπτον ἐστί. περιθέει δὲ αὐτὸ αἱμασιὴ ἐγγεγλυμμένη τύποισι, ἔστι δὲ ἔσωθεν ἄλσος δενδρέων μεγίστων πεφυτευμένον περὶ νηὸν μέγαν, ἐν τῷ δὴ τὤγαλμα ἔνι· εὖρος δὲ καὶ μῆκος τοῦ ἱροῦ πάντῃ σταδίου ἐστί. κατὰ μὲν δὴ τὴν ἔσοδον ἐστρωμένη ἐστὶ ὁδὸς λίθου ἐπὶ σταδίους τρεῖς μάλιστά κῃ, διὰ τῆς ἀγορῆς φέρουσα ἐς τὸ πρὸς ἠῶ, εὖρος δὲ ὡς τεσσέρων πλέθρων· τῇ δὲ καὶ τῇ τῆς ὁδοῦ δένδρεα οὐρανομήκεα πέφυκε· φέρει δὲ ἐς Ἑρμέω ἱρόν. τὸ μὲν δὴ ἱρὸν τοῦτο οὕτω ἔχει.", "st": "2.138"}, {"sp": "N", "t": "τέλος δὲ τῆς ἀπαλλαγῆς τοῦ Αἰθίοπος ὧδε ἔλεγον γενέσθαι· ὄψιν ἐν τῷ ὕπνῳ τοιήνδε ἰδόντα αὐτὸν οἴχεσθαι φεύγοντα· ἐδόκεε οἱ ἄνδρα ἐπιστάντα συμβουλεύειν τοὺς ἱρέας τοὺς ἐν Αἰγύπτῳ συλλέξαντα πάντας μέσους διαταμεῖν. ἰδόντα δὲ τὴν ὄψιν ταύτην λέγειν αὐτὸν ὡς πρόφασίν οἱ δοκέοι ταύτην τοὺς θεοὺς προδεικνύναι, ἵνα ἀσεβήσας περὶ τὰ ἱρὰ κακόν τι πρὸς θεῶν ἢ πρὸς ἀνθρώπων λάβοι· οὔκων ποιήσειν ταῦτα, ἀλλὰ γάρ οἱ ἐξεληλυθέναι τὸν χρόνον, ὁκόσον κεχρῆσθαι ἄρξαντα Αἰγύπτου ἐκχωρήσειν. ἐν γὰρ τῇ Αἰθιοπίῃ ἐόντι αὐτῷ τὰ μαντήια, τοῖσι χρέωνται Αἰθίοπες, ἀνεῖλε ὡς δέοι αὐτὸν Αἰγύπτου βασιλεῦσαι ἔτεα πεντήκοντα. ὡς ὦν ὁ χρόνος οὗτος ἐξήιε καὶ αὐτὸν ἡ ὄψις τοῦ ἐνυπνίου ἐπετάρασσε, ἑκὼν ἀπαλλάσσετο ἐκ τῆς Αἰγύπτου ὁ Σαβακῶς.", "st": "2.139"}, {"sp": "N", "t": "ὡς δ’ ἄρα οἴχεσθαι τὸν Αἰθίοπα ἐξ Αἰγύπτου, αὖτις τὸν τυφλὸν ἄρχειν ἐκ τῶν ἑλέων ἀπικόμενον, ἔνθα πεντήκοντα ἔτεα νῆσον χώσας σποδῷ τε καὶ γῇ οἴκεε. ὅκως γάρ οἱ φοιτᾶν σῖτον ἄγοντας Αἰγυπτίων, ὡς ἑκάστοισι προστετάχθαι, σιγῇ τοῦ Αἰθίοπος, ἐς τὴν δωρεὴν κελεύειν σφέας καὶ σποδὸν κομίζειν. ταύτην τὴν νῆσον οὐδεὶς πρότερον ἐδυνάσθη Ἀμυρταίου ἐξευρεῖν, ἀλλὰ ἔτεα ἐπὶ πλέω ἢ ἑπτακόσια οὐκ οἷοί τε ἦσαν αὐτὴν ἀνευρεῖν οἱ πρότεροι γενόμενοι βασιλέες Ἀμυρταίου. οὔνομα δὲ ταύτῃ τῇ νήσῳ Ἐλβώ, μέγαθος δ’ ἐστὶ πάντῃ δέκα σταδίων.", "st": "2.140"}, {"sp": "N", "t": "μετὰ δὲ τοῦτον βασιλεῦσαι τὸν ἱρέα τοῦ Ἡφαίστου, τῷ οὔνομα εἶναι Σεθῶν· τὸν ἐν ἀλογίῃσι ἔχειν παραχρησάμενον τῶν μαχίμων Αἰγυπτίων ὡς οὐδὲν δεησόμενον αὐτῶν, ἄλλα τε δὴ ἄτιμα ποιεῦντα ἐς αὐτούς, καί σφεας ἀπελέσθαι τὰς ἀρούρας· τοῖσι ἐπὶ τῶν προτέρων βασιλέων δεδόσθαι ἐξαιρέτους ἑκάστῳ δυώδεκα ἀρούρας. μετὰ δὲ ἐπ’ Αἴγυπτον ἐλαύνειν στρατὸν μέγαν Σαναχάριβον βασιλέα Ἀραβίων τε καὶ Ἀσσυρίων· οὔκων δὴ ἐθέλειν τοὺς μαχίμους τῶν Αἰγυπτίων βοηθέειν. τὸν δ’ ἱρέα ἐς ἀπορίην ἀπειλημένον ἐσελθόντα ἐς τὸ μέγαρον πρὸς τὤγαλμα ἀποδύρεσθαι οἷα κινδυνεύει παθεῖν. ὀλοφυρόμενον δ’ ἄρα μιν ἐπελθεῖν ὕπνον, καί οἱ δόξαι ἐν τῇ ὄψι ἐπιστάντα τὸν θεὸν θαρσύνειν ὡς οὐδὲν πείσεται ἄχαρι ἀντιάζων τὸν Ἀραβίων στρατόν· αὐτὸς γάρ οἱ πέμψειν τιμωρούς. τούτοισι δή μιν πίσυνον τοῖσι ἐνυπνίοισι, παραλαβόντα Αἰγυπτίων τοὺς βουλομένους οἱ ἕπεσθαι, στρατοπεδεύσασθαι ἐν Πηλουσίῳ· ταύτῃ γὰρ εἰσὶ αἱ ἐσβολαί· ἕπεσθαι δέ οἱ τῶν μαχίμων μὲν οὐδένα ἀνδρῶν, καπήλους δὲ καὶ χειρώνακτας καὶ ἀγοραίους ἀνθρώπους. ἐνθαῦτα ἀπικομένοισι τοῖσι ἐναντίοισι αὐτοῖσι ἐπιχυθέντας νυκτὸς μῦς ἀρουραίους κατὰ μὲν φαγεῖν τοὺς φαρετρεῶνας αὐτῶν κατὰ δὲ τὰ τόξα, πρὸς δὲ τῶν ἀσπίδων τὰ ὄχανα, ὥστε τῇ ὑστεραίῃ φευγόντων σφέων γυμνῶν πεσεῖν πολλούς. καὶ νῦν οὗτος ὁ βασιλεὺς ἕστηκε ἐν τῷ ἱρῷ τοῦ Ἡφαίστου λίθινος, ἔχων ἐπὶ τῆς χειρὸς μῦν, λέγων διὰ γραμμάτων τάδε· ἐς ἐμέ τις ὁρέων εὐσεβὴς ἔστω.", "st": "2.141"}, {"sp": "N", "t": "ἐς μὲν τοσόνδε τοῦ λόγου Αἰγύπτιοί τε καὶ οἱ ἱρέες ἔλεγον, ἀποδεικνύντες ἀπὸ τοῦ πρώτου βασιλέος ἐς τοῦ Ἡφαίστου τὸν ἱρέα τοῦτον τὸν τελευταῖον βασιλεύσαντα μίαν τε καὶ τεσσεράκοντα καὶ τριηκοσίας γενεὰς ἀνθρώπων γενομένας, καὶ ἐν ταύτῃσι ἀρχιερέας καὶ βασιλέας ἑκατέρους τοσούτους γενομένους. καίτοι τριηκόσιαι μὲν ἀνδρῶν γενεαὶ δυνέαται μύρια ἔτεα· γενεαὶ γὰρ τρεῖς ἀνδρῶν ἑκατὸν ἔτεα ἐστί· μιῆς δὲ καὶ τεσσεράκοντα ἔτι τῶν ἐπιλοίπων γενεέων, αἳ ἐπῆσαν τῇσι τριηκοσίῃσι, ἐστὶ τεσσεράκοντα καὶ τριηκόσια καὶ χίλια ἔτεα. οὕτω ἐν μυρίοισί τε ἔτεσι καὶ χιλίοισι καὶ τριηκοσίοισί τε καὶ τεσσεράκοντα ἔλεγον θεὸν ἀνθρωποειδέα οὐδένα γενέσθαι· οὐ μέντοι οὐδὲ πρότερον οὐδὲ ὕστερον ἐν τοῖσι ὑπολοίποισι Αἰγύπτου βασιλεῦσι γενομένοισι ἔλεγον οὐδὲν τοιοῦτο. ἐν τοίνυν τούτῳ τῷ χρόνῳ τετράκις ἔλεγον ἐξ ἠθέων τὸν ἥλιον ἀνατεῖλαι· ἔνθα τε νῦν καταδύεται, ἐνθεῦτεν δὶς ἐπαντεῖλαι, καὶ ἔνθεν νῦν ἀνατέλλει, ἐνθαῦτα δὶς καταδῦναι. καὶ οὐδὲν τῶν κατ’ Αἴγυπτον ὑπὸ ταῦτα ἑτεροιωθῆναι, οὔτε τὰ ἐκ τῆς γῆς οὔτε τὰ ἐκ τοῦ ποταμοῦ σφι γινόμενα, οὔτε τὰ ἀμφὶ νούσους οὔτε τὰ κατὰ τοὺς θανάτους.", "st": "2.142"}, {"sp": "N", "t": "πρότερον δὲ Ἑκαταίῳ τῷ λογοποιῷ ἐν Θήβῃσι γενεηλογήσαντί τε ἑωυτὸν καὶ ἀναδήσαντι τὴν πατριὴν ἐς ἑκκαιδέκατον θεὸν ἐποίησαν οἱ ἱρέες τοῦ Διὸς οἷόν τι καὶ ἐμοὶ οὐ γενεηλογήσαντι ἐμεωυτόν· ἐσαγαγόντες ἐς τὸ μέγαρον ἔσω ἐὸν μέγα ἐξηρίθμεον δεικνύντες κολοσσοὺς ξυλίνους τοσούτους ὅσους περ εἶπον· ἀρχιερεὺς γὰρ ἕκαστος αὐτόθι ἱστᾷ ἐπὶ τῆς ἑωυτοῦ ζόης εἰκόνα ἑωυτοῦ· ἀριθμέοντες ὦν καὶ δεικνύντες οἱ ἱρέες ἐμοὶ ἀπεδείκνυσαν παῖδα πατρὸς ἑωυτῶν ἕκαστον ἐόντα, ἐκ τοῦ ἄγχιστα ἀποθανόντος τῆς εἰκόνος διεξιόντες διὰ πασέων, ἕως οὗ ἀπέδεξαν ἁπάσας αὐτάς. Ἑκαταίῳ δὲ γενεηλογήσαντι ἑωυτὸν καὶ ἀναδήσαντι ἐς ἑκκαιδέκατον θεὸν ἀντεγενεηλόγησαν ἐπὶ τῇ ἀριθμήσι, οὐ δεκόμενοι παρ’ αὐτοῦ ἀπὸ θεοῦ γενέσθαι ἄνθρωπον· ἀντεγενεηλόγησαν δὲ ὧδε, φάμενοι ἕκαστον τῶν κολοσσῶν πίρωμιν ἐκ πιρώμιος γεγονέναι, ἐς ὃ τοὺς πέντε καὶ τεσσεράκοντα καὶ τριηκοσίους ἀπέδεξαν κολοσσούς [πίρωμιν ἐπονομαζόμενον], καὶ οὔτε ἐς θεὸν οὔτε ἐς ἥρωα ἀνέδησαν αὐτούς. πίρωμις δὲ ἐστὶ κατὰ Ἑλλάδα γλῶσσαν καλὸς κἀγαθός.", "st": "2.143"}, {"sp": "N", "t": "ἤδη ὦν τῶν αἱ εἰκόνες ἦσαν, τοιούτους ἀπεδείκνυσαν σφέας πάντας ἐόντας, θεῶν δὲ πολλὸν ἀπαλλαγμένους. τὸ δὲ πρότερον τῶν ἀνδρῶν τούτων θεοὺς εἶναι τοὺς ἐν Αἰγύπτῳ ἄρχοντας, οὐκ ἐόντας ἅμα τοῖσι ἀνθρώποισι, καὶ τούτων αἰεὶ ἕνα τὸν κρατέοντα εἶναι· ὕστατον δὲ αὐτῆς βασιλεῦσαι Ὦρον τὸν Ὀσίριος παῖδα, τὸν Ἀπόλλωνα Ἕλληνες ὀνομάζουσι· τοῦτον καταπαύσαντα Τυφῶνα βασιλεῦσαι ὕστατον Αἰγύπτου. Ὄσιρις δὲ ἐστὶ Διόνυσος κατὰ Ἑλλάδα γλῶσσαν.", "st": "2.144"}, {"sp": "N", "t": "ἐν Ἕλλησι μέν νυν νεώτατοι τῶν θεῶν νομίζονται εἶναι Ἡρακλέης τε καὶ Διόνυσος καὶ Πάν, παρ’ Αἰγυπτίοισι δὲ Πὰν μὲν ἀρχαιότατος καὶ τῶν ὀκτὼ τῶν πρώτων λεγομένων θεῶν, Ἡρακλέης δὲ τῶν δευτέρων τῶν δυώδεκα λεγομένων εἶναι, Διόνυσος δὲ τῶν τρίτων, οἳ ἐκ τῶν δυώδεκα θεῶν ἐγένοντο. Ἡρακλέι μὲν δὴ ὅσα αὐτοὶ Αἰγύπτιοι φασὶ εἶναι ἔτεα ἐς Ἄμασιν βασιλέα, δεδήλωταί μοι πρόσθε· Πανὶ δὲ ἔτι τούτων πλέονα λέγεται εἶναι, Διονύσῳ δ’ ἐλάχιστα τούτων, καὶ τούτῳ πεντακισχίλια καὶ μύρια λογίζονται εἶναι ἐς Ἄμασιν βασιλέα. καὶ ταῦτα Αἰγύπτιοι ἀτρεκέως φασὶ ἐπίστασθαι, αἰεί τε λογιζόμενοι καὶ αἰεὶ ἀπογραφόμενοι τὰ ἔτεα. Διονύσῳ μέν νυν τῷ ἐκ Σεμέλης τῆς Κάδμου λεγομένῳ γενέσθαι κατὰ ἑξακόσια ἔτεα καὶ χίλια μάλιστα ἐστὶ ἐς ἐμέ, Ἡρακλέι δὲ τῷ Ἀλκμήνης κατὰ εἰνακόσια ἔτεα· Πανὶ δὲ τῷ ἐκ Πηνελόπης (ἐκ ταύτης γὰρ καὶ Ἑρμέω λέγεται γενέσθαι ὑπὸ Ἑλλήνων ὁ Πάν) ἐλάσσω ἔτεα ἐστὶ τῶν Τρωικῶν, κατὰ ὀκτακόσια μάλιστα ἐς ἐμέ.", "st": "2.145"}, {"sp": "N", "t": "τούτων ὦν ἀμφοτέρων πάρεστι χρᾶσθαι τοῖσί τις πείσεται λεγομένοισι μᾶλλον· ἐμοὶ δ’ ὦν ἡ περὶ αὐτῶν γνώμη ἀποδέδεκται. εἰ μὲν γὰρ φανεροί τε ἐγένοντο καὶ κατεγήρασαν καὶ οὗτοι ἐν τῇ Ἑλλάδι, κατά περ Ἡρακλέης ὁ ἐξ Ἀμφιτρύωνος γενόμενος, καὶ δὴ καὶ Διόνυσος ὁ ἐκ Σεμέλης καὶ Πὰν ὁ ἐκ Πηνελόπης γενόμενος, ἔφη ἄν τις καὶ τούτους ἄλλους ἄνδρας γενομένους ἔχειν τὰ ἐκείνων οὐνόματα τῶν προγεγονότων θεῶν. νῦν δὲ Διόνυσόν τε λέγουσι οἱ Ἕλληνες ὡς αὐτίκα γενόμενον ἐς τὸν μηρὸν ἐνερράψατο Ζεὺς καὶ ἤνεικε ἐς Νύσαν τὴν ὑπὲρ Αἰγύπτου ἐοῦσαν ἐν τῇ Αἰθιοπίῃ, καὶ Πανός γε πέρι οὐκ ἔχουσι εἰπεῖν ὅκῃ ἐτράπετο γενόμενος. δῆλά μοι γέγονε ὅτι ὕστερον ἐπύθοντο οἱ Ἕλληνες τούτων τὰ οὐνόματα ἢ τὰ τῶν ἄλλων θεῶν·", "st": "2.146"}, {"sp": "N", "t": "ἀπ’ οὗ δὲ ἐπύθοντο χρόνου, ἀπὸ τούτου γενεηλογέουσι αὐτῶν τὴν γένεσιν.", "st": "2.146b"}, {"sp": "N", "t": "ταῦτα μέν νυν αὐτοὶ Αἰγύπτιοι λέγουσι· ὅσα δὲ οἵ τε ἄλλοι ἄνθρωποι καὶ Αἰγύπτιοι λέγουσι ὁμολογέοντες τοῖσι ἄλλοισι κατὰ ταύτην τὴν χώρην γενέσθαι, ταῦτ’ ἤδη φράσω·", "st": "2.147"}, {"sp": "N", "t": "προσέσται δέ τι αὐτοῖσι καὶ τῆς ἐμῆς ὄψιος. ἐλευθερωθέντες Αἰγύπτιοι μετὰ τὸν ἱρέα τοῦ Ἡφαίστου βασιλεύσαντα, οὐδένα γὰρ χρόνον οἷοί τε ἦσαν ἄνευ βασιλέος διαιτᾶσθαι, ἐστήσαντο δυώδεκα βασιλέας, δυώδεκα μοίρας δασάμενοι Αἴγυπτον πᾶσαν. οὗτοι ἐπιγαμίας ποιησάμενοι ἐβασίλευον νόμοισι τοῖσιδε χρεώμενοι, μήτε καταιρέειν ἀλλήλους μήτε πλέον τι δίζησθαι ἔχειν τὸν ἕτερον τοῦ ἑτέρου, εἶναί τε φίλους τὰ μάλιστα. τῶνδε δὲ εἵνεκα τοὺς νόμους τούτους ἐποιέοντο, ἰσχυρῶς περιστέλλοντες· ἐκέχρηστό σφι κατ’ ἀρχὰς αὐτίκα ἐνισταμένοισι ἐς τὰς τυραννίδας τὸν χαλκέῃ φιάλῃ σπείσαντα αὐτῶν ἐν τῷ ἱρῷ τοῦ Ἡφαίστου, τοῦτον ἁπάσης βασιλεύσειν Αἰγύπτου· ἐς γὰρ δὴ τὰ πάντα ἱρὰ συνελέγοντο.", "st": "2.147.2"}, {"sp": "N", "t": "καὶ δή σφι μνημόσυνα ἔδοξε λιπέσθαι κοινῇ, δόξαν δέ σφι ἐποιήσαντο λαβύρινθον, ὀλίγον ὑπὲρ τῆς λίμνης τῆς Μοίριος κατὰ Κροκοδείλων καλεομένην πόλιν μάλιστά κῃ κείμενον· τὸν ἐγὼ ἤδη εἶδον λόγου μέζω. εἰ γάρ τις τὰ ἐξ Ἑλλήνων τείχεά τε καὶ ἔργων ἀπόδεξιν συλλογίσαιτο, ἐλάσσονος πόνου τε ἂν καὶ δαπάνης φανείη ἐόντα τοῦ λαβυρίνθου τούτου. καίτοι ἀξιόλογός γε καὶ ὁ ἐν Ἐφέσῳ ἐστὶ νηὸς καὶ ὁ ἐν Σάμῳ. ἦσαν μέν νυν καὶ αἱ πυραμίδες λόγου μέζονες, καὶ πολλῶν ἑκάστη αὐτέων Ἑλληνικῶν ἔργων καὶ μεγάλων ἀνταξίη, ὁ δὲ δὴ λαβύρινθος καὶ τὰς πυραμίδας ὑπερβάλλει· τοῦ [γὰρ] δυώδεκα μὲν εἰσὶ αὐλαὶ κατάστεγοι, ἀντίπυλοι ἀλλήλῃσι, ἓξ μὲν πρὸς βορέω ἓξ δὲ πρὸς νότον τετραμμέναι, συνεχέες· τοῖχος δὲ ἔξωθεν ὁ αὐτός σφεας περιέργει. οἰκήματα δ’ ἔνεστι διπλᾶ, τὰ μὲν ὑπόγαια τὰ δὲ μετέωρα ἐπ’ ἐκείνοισι, τρισχίλια ἀριθμόν, πεντακοσίων καὶ χιλίων ἑκάτερα. τὰ μέν νυν μετέωρα τῶν οἰκημάτων αὐτοί τε ὡρῶμεν διεξιόντες καὶ αὐτοὶ θεησάμενοι λέγομεν, τὰ δὲ αὐτῶν ὑπόγαια λόγοισι ἐπυνθανόμεθα· οἱ γὰρ ἐπεστεῶτες τῶν Αἰγυπτίων δεικνύναι αὐτὰ οὐδαμῶς ἤθελον, φάμενοι θήκας αὐτόθι εἶναι τῶν τε ἀρχὴν τὸν λαβύρινθον τοῦτον οἰκοδομησαμένων βασιλέων καὶ τῶν ἱρῶν κροκοδείλων. οὕτω τῶν μὲν κάτω πέρι οἰκημάτων ἀκοῇ παραλαβόντες λέγομεν, τὰ δὲ ἄνω μέζονα ἀνθρωπηίων ἔργων αὐτοὶ ὡρῶμεν· αἵ τε γὰρ διέξοδοι διὰ τῶν στεγέων καὶ οἱ ἑλιγμοὶ διὰ τῶν αὐλέων ἐόντες ποικιλώτατοι θῶμα μυρίον παρείχοντο ἐξ αὐλῆς τε ἐς τὰ οἰκήματα διεξιοῦσι καὶ ἐκ τῶν οἰκημάτων ἐς παστάδας, ἐς στέγας τε ἄλλας ἐκ τῶν παστάδων καὶ ἐς αὐλὰς ἄλλας ἐκ τῶν οἰκημάτων. ὀροφὴ δὲ πάντων τούτων λιθίνη κατά περ οἱ τοῖχοι, οἱ δὲ τοῖχοι τύπων ἐγγεγλυμμένων πλέοι, αὐλὴ δὲ ἑκάστη περίστυλος λίθου λευκοῦ ἁρμοσμένου τὰ μάλιστα. τῆς δὲ γωνίης τελευτῶντος τοῦ λαβυρίνθου ἔχεται πυραμὶς τεσσερακοντόργυιος, ἐν τῇ ζῷα μεγάλα ἐγγέγλυπται· ὁδὸς δ’ ἐς αὐτὴν ὑπὸ γῆν πεποίηται.", "st": "2.148"}, {"sp": "N", "t": "τοῦ δὲ λαβυρίνθου τούτου ἐόντος τοιούτου θῶμα ἔτι μέζον παρέχεται ἡ Μοίριος καλεομένη λίμνη, παρ’ ἣν ὁ λαβύρινθος οὗτος οἰκοδόμηται· τῆς τὸ περίμετρον τῆς περιόδου εἰσὶ στάδιοι ἑξακόσιοι καὶ τρισχίλιοι, σχοίνων ἑξήκοντα ἐόντων, ἴσοι καὶ αὐτῆς Αἰγύπτου τὸ παρὰ θάλασσαν. κεῖται δὲ μακρὴ ἡ λίμνη πρὸς βορέην τε καὶ νότον, ἐοῦσα βάθος, τῇ βαθυτάτη αὐτὴ ἑωυτῆς, πεντηκοντόργυιος. ὅτι δὲ χειροποίητος ἐστὶ καὶ ὀρυκτή, αὐτὴ δηλοῖ· ἐν γὰρ μέσῃ τῇ λίμνῃ μάλιστά κῃ ἑστᾶσι δύο πυραμίδες, τοῦ ὕδατος ὑπερέχουσαι πεντήκοντα ὀργυιὰς ἑκατέρη, καὶ τὸ κατ’ ὕδατος οἰκοδόμηται ἕτερον τοσοῦτον, καὶ ἐπ’ ἀμφοτέρῃσι ἔπεστι κολοσσὸς λίθινος κατήμενος ἐν θρόνῳ. οὕτω αἱ μὲν πυραμίδες εἰσὶ ἑκατὸν ὀργυιέων, αἱ δ’ ἑκατὸν ὀργυιαὶ δίκαιαι εἰσὶ στάδιον ἑξάπλεθρον, ἑξαπέδου τε τῆς ὀργυιῆς μετρεομένης καὶ τετραπήχεος, τῶν ποδῶν μὲν τετραπαλαίστων ἐόντων, τοῦ δὲ πήχεος ἑξαπαλαίστου. τὸ δὲ ὕδωρ τὸ ἐν τῇ λίμνῃ αὐθιγενὲς μὲν οὐκ ἔστι ἄνυδρος γὰρ δὴ δεινῶς ἐστι ἡ ταύτῃ, ἐκ τοῦ Νείλου δὲ κατὰ διώρυχα ἐσῆκται, καὶ ἓξ μὲν μῆνας ἔσω ῥέει ἐς τὴν λίμνην, ἓξ δὲ μῆνας ἔξω ἐς τὸν Νεῖλον αὖτις· καὶ ἐπεὰν μὲν ἐκρέῃ ἔξω, ἣ δὲ τότε τοὺς ἓξ μῆνας ἐς τὸ βασιλήιον καταβάλλει ἐπ’ ἡμέρην ἑκάστην τάλαντον ἀργυρίου ἐκ τῶν ἰχθύων, ἐπεὰν δὲ ἐσίῃ τὸ ὕδωρ ἐς αὐτήν, εἴκοσι μνέας.", "st": "2.149"}, {"sp": "N", "t": "ἔλεγον δὲ οἱ ἐπιχώριοι καὶ ὡς ἐς τὴν Σύρτιν τὴν ἐς Λιβύην ἐκδιδοῖ ἡ λίμνη αὕτη ὑπὸ γῆν, τετραμμένη τὸ πρὸς ἑσπέρην ἐς τὴν μεσόγαιαν παρὰ τὸ ὄρος τὸ ὑπὲρ Μέμφιος. ἐπείτε δὲ τοῦ ὀρύγματος τούτου οὐκ ὥρων τὸν χοῦν οὐδαμοῦ ἐόντα, ἐπιμελὲς γὰρ δή μοι ἦν, εἰρόμην τοὺς ἄγχιστα οἰκέοντας τῆς λίμνης ὅκου εἴη ὁ χοῦς ὁ ἐξορυχθείς. οἳ δὲ ἔφρασάν μοι ἵνα ἐξεφορήθη, καὶ εὐπετέως ἔπειθον· ᾔδεα γὰρ λόγῳ καὶ ἐν Νίνῳ τῇ Ἀσσυρίων πόλι γενόμενον ἕτερον τοιοῦτον. τὰ γὰρ Σαρδαναπάλλου τοῦ Νίνου βασιλέος ἐόντα μεγάλα χρήματα καὶ φυλασσόμενα ἐν θησαυροῖσι καταγαίοισι ἐπενόησαν κλῶπες ἐκφορῆσαι. ἐκ δὴ ὦν τῶν σφετέρων οἰκίων ἀρξάμενοι οἱ κλῶπες ὑπὸ γῆν σταθμεόμενοι ἐς τὰ βασιλήια οἰκία ὤρυσσον, τὸν δὲ χοῦν τὸν ἐκφορεόμενον ἐκ τοῦ ὀρύγματος, ὅκως γένοιτο νύξ, ἐς τὸν Τίγρην ποταμὸν παραρρέοντα τὴν Νίνον ἐξεφόρεον, ἐς ὃ κατεργάσαντο ὅ τι ἐβούλοντο. τοιοῦτον ἕτερον ἤκουσα καὶ κατὰ τὸ τῆς ἐν Αἰγύπτῳ λίμνης ὄρυγμα γενέσθαι, πλὴν οὐ νυκτὸς ἀλλὰ μετ’ ἡμέρην ποιεύμενον· ὀρύσσοντας γὰρ τὸν χοῦν τοὺς Αἰγυπτίους ἐς τὸν Νεῖλον φορέειν· ὁ δὲ ὑπολαμβάνων ἔμελλε διαχέειν. ἡ μέν νυν λίμνη αὕτη οὕτω λέγεται ὀρυχθῆναι·", "st": "2.150"}, {"sp": "N", "t": "τῶν δὲ δυώδεκα βασιλέων δικαιοσύνῃ χρεωμένων, ἀνὰ χρόνον ὡς ἔθυσαν ἐν τῷ ἱρῷ τοῦ Ἡφαίστου, τῇ ὑστάτῃ τῆς ὁρτῆς, μελλόντων κατασπείσειν, ὁ ἀρχιερεὺς ἐξήνεικέ σφι φιάλας χρυσέας, τῇσί περ ἐώθεσαν σπένδειν, ἁμαρτὼν τοῦ ἀριθμοῦ, ἕνδεκα δυώδεκα ἐοῦσι. ἐνθαῦτα ὡς οὐκ εἶχε φιάλην ὁ ἔσχατος ἑστεὼς αὐτῶν Ψαμμήτιχος, περιελόμενος τὴν κυνέην ἐοῦσαν χαλκέην ὑπέσχε τε καὶ ἔσπενδε. κυνέας δὲ καὶ οἱ ἄλλοι ἅπαντες ἐφόρεόν τε βασιλέες καὶ ἐτύγχανον τότε ἔχοντες. Ψαμμήτιχος μέν νυν οὐδενὶ δολερῷ νόῳ χρεώμενος ὑπέσχε τὴν κυνέην· οἳ δὲ ἐν φρενὶ λαβόντες τό τε ποιηθὲν ἐκ Ψαμμητίχου καὶ τὸ χρηστήριον, ὅτι ἐκέχρηστό σφι τὸν χαλκέῃ σπείσαντα αὐτῶν φιάλῃ τοῦτον βασιλέα ἔσεσθαι μοῦνον Αἰγύπτου, ἀναμνησθέντες τοῦ χρησμοῦ κτεῖναι μὲν οὐκ ἐδικαίωσαν Ψαμμήτιχον, ὡς ἀνεύρισκον βασανίζοντες ἐξ οὐδεμιῆς προνοίης αὐτὸν ποιήσαντα, ἐς δὲ τὰ ἕλεα ἔδοξέ σφι διῶξαι ψιλώσαντας τὰ πλεῖστα τῆς δυνάμιος, ἐκ δὲ τῶν ἑλέων ὁρμώμενον μὴ ἐπιμίσγεσθαι τῇ ἄλλῃ Αἰγύπτῳ.", "st": "2.151"}, {"sp": "N", "t": "τὸν δὲ Ψαμμήτιχον τοῦτον πρότερον φεύγοντα τὸν Αἰθίοπα Σαβακῶν, ὅς οἱ τὸν πατέρα Νεκῶν ἀπέκτεινε, τοῦτον φεύγοντα τότε ἐς Συρίην, ὡς ἀπαλλάχθη ἐκ τῆς ὄψιος τοῦ ὀνείρου ὁ Αἰθίοψ, κατήγαγον Αἰγυπτίων οὗτοι οἳ ἐκ νομοῦ τοῦ Σαΐτεω εἰσί. μετὰ δὲ βασιλεύοντα τὸ δεύτερον πρὸς τῶν ἕνδεκα βασιλέων καταλαμβάνει μιν διὰ τὴν κυνέην φεύγειν ἐς τὰ ἕλεα. ἐπιστάμενος ὦν ὡς περιυβρισμένος εἴη πρὸς αὐτῶν, ἐπενόεε τίσασθαι τοὺς διώξαντας. πέμψαντι δέ οἱ ἐς Βουτοῦν πόλιν ἐς τὸ χρηστήριον τῆς Λητοῦς, ἔνθα δὴ Αἰγυπτίοισι ἐστὶ μαντήιον ἀψευδέστατον, ἦλθε χρησμὸς ὡς τίσις ἥξει ἀπὸ θαλάσσης χαλκέων ἀνδρῶν ἐπιφανέντων. καὶ τῷ μὲν δὴ ἀπιστίη μεγάλη ὑπεκέχυτο χαλκέους οἱ ἄνδρας ἥξειν ἐπικούρους. χρόνου δὲ οὐ πολλοῦ διελθόντος ἀναγκαίη κατέλαβε Ἴωνάς τε καὶ Κᾶρας ἄνδρας κατὰ ληίην ἐκπλώσαντας ἀπενειχθῆναι ἐς Αἴγυπτον, ἐκβάντας δὲ ἐς γῆν καὶ ὁπλισθέντας χαλκῷ ἀγγέλλει τῶν τις Αἰγυπτίων ἐς τὰ ἕλεα ἀπικόμενος τῷ Ψαμμητίχῳ, ὡς οὐκ ἰδὼν πρότερον χαλκῷ ἄνδρας ὁπλισθέντας, ὡς χάλκεοι ἄνδρες ἀπιγμένοι ἀπὸ θαλάσσης λεηλατεῦσι τὸ πεδίον. ὁ δὲ μαθὼν τὸ χρηστήριον ἐπιτελεύμενον φίλα τε τοῖσι Ἴωσι καὶ Καρσὶ ποιέεται καί σφεας μεγάλα ὑπισχνεύμενος πείθει μετ’ ἑωυτοῦ γενέσθαι. ὡς δὲ ἔπεισε, οὕτω ἅμα τοῖσι τὰ ἑωυτοῦ βουλομένοισι Αἰγυπτίοισι καὶ τοῖσι ἐπικούροισι καταιρέει τοὺς βασιλέας.", "st": "2.152"}, {"sp": "N", "t": "κρατήσας δὲ Αἰγύπτου πάσης ὁ Ψαμμήτιχος ἐποίησε τῷ Ἡφαίστῳ προπύλαια ἐν Μέμφι τὰ πρὸς νότον ἄνεμον τετραμμένα, αὐλήν τε τῷ Ἄπι, ἐν τῇ τρέφεται ἐπεὰν φανῇ ὁ Ἆπις, οἰκοδόμησε ἐναντίον τῶν προπυλαίων, πᾶσάν τε περίστυλον ἐοῦσαν καὶ τύπων πλέην· ἀντὶ δὲ κιόνων ὑπεστᾶσι κολοσσοὶ δυωδεκαπήχεες τῇ αὐλῇ. ὁ δὲ Ἆπις κατὰ τὴν Ἑλλήνων γλῶσσαν ἐστὶ Ἔπαφος.", "st": "2.153"}, {"sp": "N", "t": "τοῖσι δὲ Ἴωσι καὶ τοῖσι Καρσὶ τοῖσι συγκατεργασαμένοισι αὐτῷ ὁ Ψαμμήτιχος δίδωσι χώρους ἐνοικῆσαι ἀντίους ἀλλήλων, τοῦ Νείλου τὸ μέσον ἔχοντος, τοῖσι οὐνόματα ἐτέθη Στρατόπεδα· τούτους τε δή σφι τοὺς χώρους δίδωσι καὶ τὰ ἄλλα τὰ ὑπέσχετο πάντα ἀπέδωκε. καὶ δὴ καὶ παῖδας παρέβαλε αὐτοῖσι Αἰγυπτίους τὴν Ἑλλάδα γλῶσσαν ἐκδιδάσκεσθαι. ἀπὸ δὲ τούτων ἐκμαθόντων τὴν γλῶσσαν οἱ νῦν ἑρμηνέες ἐν Αἰγύπτῳ γεγόνασι. οἱ δὲ Ἴωνές τε καὶ οἱ Κᾶρες τούτους τοὺς χώρους οἴκησαν χρόνον ἐπὶ πολλόν· εἰσὶ δὲ οὗτοι οἱ χῶροι πρὸς θαλάσσης ὀλίγον ἔνερθε Βουβάστιος πόλιος, ἐπὶ τῷ Πηλουσίῳ καλεομένῳ στόματι τοῦ Νείλου. τούτους μὲν δὴ χρόνῳ ὕστερον βασιλεὺς Ἄμασις ἐξαναστήσας ἐνθεῦτεν κατοίκισε ἐς Μέμφιν, φυλακὴν ἑωυτοῦ ποιεύμενος πρὸς Αἰγυπτίων.", "st": "2.154"}, {"sp": "N", "t": "τούτων δὲ οἰκισθέντων ἐν Αἰγύπτῳ, οἱ Ἕλληνες οὕτω ἐπιμισγόμενοι τούτοισι τὰ περὶ Αἴγυπτον γινόμενα ἀπὸ Ψαμμητίχου βασιλέος ἀρξάμενοι πάντα καὶ τὰ ὕστερον ἐπιστάμεθα ἀτρεκέως· πρῶτοι γὰρ οὗτοι ἐν Αἰγύπτῳ ἀλλόγλωσσοι κατοικίσθησαν. ἐξ ὧν δὲ ἐξανέστησαν χώρων, ἐν τούτοισι δὲ οἵ τε ὁλκοὶ τῶν νεῶν καὶ τὰ ἐρείπια τῶν οἰκημάτων τὸ μέχρι ἐμεῦ ἦσαν.", "st": "2.154.4"}, {"sp": "N", "t": "Ψαμμήτιχος μέν νυν οὕτω ἔσχε Αἴγυπτον. τοῦ δὲ χρηστηρίου τοῦ ἐν Αἰγύπτῳ πολλὰ ἐπεμνήσθην ἤδη, καὶ δὴ λόγον περὶ αὐτοῦ ὡς ἀξίου ἐόντος ποιήσομαι. τὸ γὰρ χρηστήριον τοῦτο τὸ ἐν Αἰγύπτῳ ἐστὶ μὲν Λητοῦς ἱρόν, ἐν πόλι δὲ μεγάλῃ ἱδρυμένον κατὰ τὸ Σεβεννυτικὸν καλεόμενον στόμα τοῦ Νείλου, ἀναπλέοντι ἀπὸ θαλάσσης ἄνω. οὔνομα δὲ τῇ πόλι ταύτῃ ὅκου τὸ χρηστήριον ἐστὶ Βουτώ, ὡς καὶ πρότερον ὠνόμασταί μοι. ἱρὸν δὲ ἐστὶ ἐν τῇ Βουτοῖ ταύτῃ Ἀπόλλωνος καὶ Ἀρτέμιδος, καὶ ὅ γε νηὸς τῆς Λητοῦς, ἐν τῷ δὴ τὸ χρηστήριον ἔνι, αὐτός τε τυγχάνει ἐὼν μέγας καὶ τὰ προπύλαια ἔχει ἐς ὕψος δέκα ὀργυιέων. τὸ δέ μοι τῶν φανερῶν ἦν θῶμα μέγιστον παρεχόμενον, φράσω· ἔστι ἐν τῷ τεμένεϊ τούτῳ Λητοῦς νηὸς ἐξ ἑνὸς λίθου πεποιημένος ἔς τε ὕψος καὶ ἐς μῆκος καὶ τοῖχος ἕκαστος τούτοισι ἴσος τεσσεράκοντα πηχέων τούτων ἕκαστον ἐστί, τὸ δὲ καταστέγασμα τῆς ὀροφῆς ἄλλος ἐπίκειται λίθος, ἔχων τὴν παρωροφίδα τετράπηχυν.", "st": "2.155"}, {"sp": "N", "t": "οὕτω μέν νυν ὁ νηὸς τῶν φανερῶν μοι τῶν περὶ τοῦτο τὸ ἱρὸν ἐστὶ θωμαστότατον, τῶν δὲ δευτέρων νῆσος ἡ Χέμμις καλευμένη· ἔστι μὲν ἐν λίμνῃ βαθέῃ καὶ πλατέῃ κειμένη παρὰ τὸ ἐν Βουτοῖ ἱρόν, λέγεται δὲ ὑπ’ Αἰγυπτίων εἶναι αὕτη ἡ νῆσος πλωτή. αὐτὸς μὲν ἔγωγε οὔτε πλέουσαν οὔτε κινηθεῖσαν εἶδον, τέθηπα δὲ ἀκούων εἰ νῆσος ἀληθέως ἐστὶ πλωτή. ἐν δὲ ὦν ταύτῃ νηός τε Ἀπόλλωνος μέγας ἔνι καὶ βωμοὶ τριφάσιοι ἐνιδρύαται, ἐμπεφύκασι δ’ ἐν αὐτῇ φοίνικες συχνοὶ καὶ ἄλλα δένδρεα καὶ καρποφόρα καὶ ἄφορα πολλά. λόγον δὲ τόνδε ἐπιλέγοντες οἱ Αἰγύπτιοι φασὶ εἶναι αὐτὴν πλωτήν, ὡς ἐν τῇ νήσῳ ταύτῃ οὐκ ἐούσῃ πρότερον πλωτῇ Λητώ, ἐοῦσα τῶν ὀκτὼ θεῶν τῶν πρώτων γενομένων, οἰκέουσα δὲ ἐν Βουτοῖ πόλι, ἵνα δή οἱ τὸ χρηστήριον τοῦτο ἐστί, Ἀπόλλωνα παρ’ Ἴσιος παρακαταθήκην δεξαμένη διέσωσε κατακρύψασα ἐν τῇ νῦν πλωτῇ λεγομένῃ νήσῳ, ὅτε τὸ πᾶν διζήμενος ὁ Τυφῶν ἐπῆλθε, θέλων ἐξευρεῖν τοῦ Ὀσίριος τὸν παῖδα. Ἀπόλλωνα δὲ καὶ Ἄρτεμιν Διονύσου καὶ Ἴσιος λέγουσι εἶναι παῖδας, Λητοῦν δὲ τροφὸν αὐτοῖσι καὶ σώτειραν γενέσθαι. Αἰγυπτιστὶ δὲ Ἀπόλλων μὲν Ὦρος, Δημήτηρ δὲ Ἶσις, Ἄρτεμις δὲ Βούβαστις. ἐκ τούτου δὲ τοῦ λόγου καὶ οὐδενὸς ἄλλου Αἰσχύλος ὁ Εὐφορίωνος ἥρπασε τὸ ἐγὼ φράσω, μοῦνος δὴ ποιητέων τῶν προγενομένων· ἐποίησε γὰρ Ἄρτεμιν εἶναι θυγατέρα Δήμητρος. τὴν δὲ νῆσον διὰ τοῦτο γενέσθαι πλωτήν.", "st": "2.156"}, {"sp": "N", "t": "ταῦτα μὲν οὕτω λέγουσι.", "st": "2.156b"}, {"sp": "N", "t": "Ψαμμήτιχος δὲ ἐβασίλευσε Αἰγύπτου τέσσερα καὶ πεντήκοντα ἔτεα, τῶν τὰ ἑνὸς δέοντα τριήκοντα Ἄζωτον τῆς Συρίης μεγάλην πόλιν προσκατήμενος ἐπολιόρκεε, ἐς ὃ ἐξεῖλε. αὕτη δὲ ἡ Ἄζωτος ἁπασέων πολίων ἐπὶ πλεῖστον χρόνον πολιορκεομένη ἀντέσχε τῶν ἡμεῖς ἴδμεν.", "st": "2.157"}, {"sp": "N", "t": "Ψαμμητίχου δὲ Νεκῶς παῖς ἐγένετο καὶ ἐβασίλευσε Αἰγύπτου, ὃς τῇ διώρυχι ἐπεχείρησε πρῶτος τῇ ἐς τὴν Ἐρυθρὴν θάλασσαν φερούσῃ, τὴν Δαρεῖος ὁ Πέρσης δεύτερα διώρυξε· τῆς μῆκος ἐστὶ πλόος ἡμέραι τέσσερες, εὖρος δὲ ὠρύχθη ὥστε τριήρεας δύο πλέειν ὁμοῦ ἐλαστρευμένας. ἦκται δὲ ἀπὸ τοῦ Νείλου τὸ ὕδωρ ἐς αὐτήν· ἦκται δὲ κατύπερθε ὀλίγον Βουβάστιος πόλιος παρὰ Πάτουμον τὴν Ἀραβίην πόλιν, ἐσέχει δὲ ἐς τὴν Ἐρυθρὴν θάλασσαν. ὀρώρυκται δὲ πρῶτον μὲν τοῦ πεδίου τοῦ Αἰγυπτίου τὰ πρὸς Ἀραβίην ἔχοντα· ἔχεται δὲ κατύπερθε τοῦ πεδίου τὸ κατὰ Μέμφιν τεῖνον ὄρος, ἐν τῷ αἱ λιθοτομίαι ἔνεισι· τοῦ ὦν δὴ ὄρεος τούτου παρὰ τὴν ὑπώρεαν ἦκται ἡ διῶρυξ ἀπ’ ἑσπέρης μακρὴ πρὸς τὴν ἠῶ, καὶ ἔπειτα τείνει ἐς διασφάγας, φέρουσα ἀπὸ τοῦ ὄρεος πρὸς μεσαμβρίην τε καὶ νότον ἄνεμον ἐς τὸν κόλπον τὸν Ἀράβιον. τῇ δὲ ἐλάχιστον ἐστὶ καὶ συντομώτατον ἐκ τῆς βορηίης θαλάσσης ὑπερβῆναι ἐς τὴν νοτίην καὶ Ἐρυθρὴν τὴν αὐτὴν ταύτην καλεομένην, ἀπὸ τοῦ Κασίου ὄρεος τοῦ οὐρίζοντος Αἴγυπτόν τε καὶ Συρίην, ἀπὸ τούτου εἰσὶ στάδιοι ἀπαρτὶ χίλιοι ἐς τὸν Ἀράβιον κόλπον. τοῦτο μὲν τὸ συντομώτατον, ἡ δὲ διῶρυξ πολλῷ μακροτέρη, ὅσῳ σκολιωτέρη ἐστί· τὴν ἐπὶ Νεκῶ βασιλέος ὀρύσσοντες Αἰγυπτίων ἀπώλοντο δυώδεκα μυριάδες. Νεκῶς μέν νυν μεταξὺ ὀρύσσων ἐπαύσατο μαντηίου ἐμποδίου γενομένου τοιοῦδε, τῷ βαρβάρῳ αὐτὸν προεργάζεσθαι. βαρβάρους δὲ πάντας οἱ Αἰγύπτιοι καλέουσι τοὺς μὴ σφίσι ὁμογλώσσους.", "st": "2.158"}, {"sp": "N", "t": "παυσάμενος δὲ τῆς διώρυχος ὁ Νεκῶς ἐτράπετο πρὸς στρατηίας, καὶ τριήρεες αἳ μὲν ἐπὶ τῇ βορηίῃ θαλάσσῃ ἐποιήθησαν, αἳ δ’ ἐν τῷ Ἀραβίῳ κόλπῳ ἐπὶ τῇ Ἐρυθρῇ θαλάσσῃ, τῶν ἔτι οἱ ὁλκοὶ ἐπίδηλοι. καὶ ταύτῃσί τε ἐχρᾶτο ἐν τῷ δέοντι καὶ Σύροισι πεζῇ ὁ Νεκῶς συμβαλὼν ἐν Μαγδώλῳ ἐνίκησε, μετὰ δὲ τὴν μάχην Κάδυτιν πόλιν τῆς Συρίης ἐοῦσαν μεγάλην εἷλε. ἐν τῇ δὲ ἐσθῆτι ἔτυχε ταῦτα κατεργασάμενος, ἀνέθηκε τῷ Ἀπόλλωνι πέμψας ἐς Βραγχίδας τὰς Μιλησίων. μετὰ δέ, ἑκκαίδεκα ἔτεα τὰ πάντα ἄρξας, τελευτᾷ, τῷ παιδὶ Ψάμμι παραδοὺς τὴν ἀρχήν.", "st": "2.159"}, {"sp": "N", "t": "ἐπὶ τοῦτον δὴ τὸν Ψάμμιν βασιλεύοντα Αἰγύπτου ἀπίκοντο Ἠλείων ἄγγελοι, αὐχέοντες δικαιότατα καὶ κάλλιστα τιθέναι τὸν ἐν Ὀλυμπίῃ ἀγῶνα πάντων ἀνθρώπων, καὶ δοκέοντες παρὰ ταῦτα οὐδ’ ἂν τοὺς σοφωτάτους ἀνθρώπων Αἰγυπτίους οὐδὲν ἐπεξευρεῖν· ὡς δὲ ἀπικόμενοι ἐς τὴν Αἴγυπτον οἱ Ἠλεῖοι ἔλεγον τῶν εἵνεκα ἀπίκοντο, ἐνθαῦτα ὁ βασιλεὺς οὗτος συγκαλέεται Αἰγυπτίων τοὺς λεγομένους εἶναι σοφωτάτους. συνελθόντες δὲ οἱ Αἰγύπτιοι ἐπυνθάνοντο τῶν Ἠλείων λεγόντων ἅπαντα τὰ κατήκει σφέας ποιέειν περὶ τὸν ἀγῶνα· ἀπηγησάμενοι δὲ τὰ πάντα ἔφασαν ἥκειν ἐπιμαθησόμενοι εἴ τι ἔχοιεν Αἰγύπτιοι τούτων δικαιότερον ἐπεξευρεῖν. οἳ δὲ βουλευσάμενοι ἐπειρώτων τοὺς Ἠλείους εἴ σφι οἱ πολιῆται ἐναγωνίζονται. οἳ δὲ ἔφασαν καὶ σφέων καὶ τῶν ἄλλων Ἑλλήνων ὁμοίως τῷ βουλομένῳ ἐξεῖναι ἀγωνίζεσθαι. οἱ δὲ Αἰγύπτιοι ἔφασαν σφέας οὕτω τιθέντας παντὸς τοῦ δικαίου ἡμαρτηκέναι. οὐδεμίαν γὰρ εἶναι μηχανὴν ὅκως οὐ τῷ ἀστῷ ἀγωνιζομένῳ προσθήσονται, ἀδικέοντες τὸν ξεῖνον. ἀλλ’ εἰ δὴ βούλονται δικαίως τιθέναι καὶ τούτου εἵνεκα ἀπικοίατο ἐς Αἴγυπτον, ξείνοισι ἀγωνιστῇσι ἐκέλευον τὸν ἀγῶνα τιθέναι, Ἠλείων δὲ μηδενὶ εἶναι ἀγωνίζεσθαι. ταῦτα μὲν Αἰγύπτιοι Ἠλείοισι ὑπεθήκαντο.", "st": "2.160"}, {"sp": "N", "t": "ψάμμιος δὲ ἓξ ἔτεα μοῦνον βασιλεύσαντος Αἰγύπτου καὶ στρατευσαμένου ἐς Αἰθιοπίην καὶ μεταυτίκα τελευτήσαντος ἐξεδέξατο Ἀπρίης ὁ Ψάμμιος· ὃς μετὰ Ψαμμήτιχον τὸν ἑωυτοῦ προπάτορα ἐγένετο εὐδαιμονέστατος τῶν πρότερον βασιλέων, ἐπ’ ἔτεα πέντε καὶ εἴκοσι ἄρξας, ἐν τοῖσι ἐπί τε Σιδῶνα στρατὸν ἤλασε καὶ ἐναυμάχησε τῷ Τυρίῳ. ἐπεὶ δέ οἱ ἔδεε κακῶς γενέσθαι, ἐγίνετο ἀπὸ προφάσιος τὴν ἐγὼ μεζόνως μὲν ἐν τοῖσι Λιβυκοῖσι λόγοισι ἀπηγήσομαι, μετρίως δ’ ἐν τῷ παρεόντι. ἀποπέμψας γὰρ στράτευμα ὁ Ἀπρίης ἐπὶ Κυρηναίους μεγαλωστὶ προσέπταισε, Αἰγύπτιοι δὲ ταῦτα ἐπιμεμφόμενοι ἀπέστησαν ἀπ’ αὐτοῦ, δοκέοντες τὸν Ἀπρίην ἐκ προνοίης αὐτοὺς ἀποπέμψαι ἐς φαινόμενον κακόν, ἵνα δὴ σφέων φθορὴ γένηται, αὐτὸς δὲ τῶν λοιπῶν Αἰγυπτίων ἀσφαλέστερον ἄρχοι. ταῦτα δὲ δεινὰ ποιεύμενοι οὗτοί τε οἱ ἀπονοστήσαντες καὶ οἱ τῶν ἀπολομένων φίλοι ἀπέστησαν ἐκ τῆς ἰθέης.", "st": "2.161"}, {"sp": "N", "t": "πυθόμενος δὲ Ἀπρίης ταῦτα πέμπει ἐπ’ αὐτοὺς Ἄμασιν καταπαύσοντα λόγοισι. ὁ δὲ ἐπείτε ἀπικόμενος κατελάμβανε τοὺς Αἰγυπτίους ταῦτα μὴ ποιέειν, λέγοντος αὐτοῦ τῶν τις Αἰγυπτίων ὄπισθε στὰς περιέθηκέ οἱ κυνέην, καὶ περιτιθεὶς ἔφη ἐπὶ βασιληίῃ περιτιθέναι. καὶ τῷ οὔ κως ἀεκούσιον ἐγίνετο τὸ ποιεύμενον, ὡς διεδείκνυε. ἐπείτε γὰρ ἐστήσαντό μιν βασιλέα τῶν Αἰγυπτίων οἱ ἀπεστεῶτες, παρεσκευάζετο ὡς ἐλῶν ἐπὶ τὸν Ἀπρίην. πυθόμενος δὲ ταῦτα ὁ Ἀπρίης ἔπεμπε ἐπ’ Ἄμασιν ἄνδρα δόκιμον τῶν περὶ ἑωυτὸν Αἰγυπτίων, τῷ οὔνομα ἦν Πατάρβημις, ἐντειλάμενος αὐτῷ ζῶντα Ἄμασιν ἀγαγεῖν παρ’ ἑωυτόν. ὡς δὲ ἀπικόμενος τὸν Ἄμασιν ἐκάλεε ὁ Πατάρβημις, ὁ Ἄμασις, ἔτυχε γὰρ ἐπ’ ἵππου κατήμενος, ἐπαείρας ἀπεματάισε, καὶ τοῦτό μιν ἐκέλευε Ἀπρίῃ ἀπάγειν. ὅμως δὲ αὐτὸν ἀξιοῦν τὸν Πατάρβημιν βασιλέος μεταπεμπομένου ἰέναι πρὸς αὐτόν· τὸν δὲ αὐτῷ ὑποκρίνεσθαι ὡς ταῦτα πάλαι παρεσκευάζετο ποιέειν, καὶ αὐτῷ οὐ μέμψεσθαι Ἀπρίην· παρέσεσθαι γὰρ καὶ αὐτὸς καὶ ἄλλους ἄξειν. τὸν δὲ Πατάρβημιν ἔκ τε τῶν λεγομένων οὐκ ἀγνοέειν τὴν διάνοιαν, καὶ παρασκευαζόμενον ὁρῶντα σπουδῇ ἀπιέναι, βουλόμενον τὴν ταχίστην βασιλέι δηλῶσαι τὰ πρησσόμενα. ὡς δὲ ἀπικέσθαι αὐτὸν πρὸς τὸν Ἀπρίην οὐκ ἄγοντα τὸν Ἄμασιν, οὐδένα λόγον αὐτῷ δόντα ἀλλὰ περιθύμως ἔχοντα περιταμεῖν προστάξαι αὐτοῦ τά τε ὦτα καὶ τὴν ῥῖνα. ἰδόμενοι δ’ οἱ λοιποὶ τῶν Αἰγυπτίων, οἳ ἔτι τὰ ἐκείνου ἐφρόνεον, ἄνδρα τὸν δοκιμώτατον ἑωυτῶν οὕτω αἰσχρῶς λύμῃ διακείμενον, οὐδένα δὴ χρόνον ἐπισχόντες ἀπιστέατο πρὸς τοὺς ἑτέρους καὶ ἐδίδοσαν σφέας αὐτοὺς Ἀμάσι.", "st": "2.162"}, {"sp": "N", "t": "πυθόμενος δὲ καὶ ταῦτα ὁ Ἀπρίης ὥπλιζε τοὺς ἐπικούρους καὶ ἤλαυνε ἐπὶ τοὺς Αἰγυπτίους· εἶχε δὲ περὶ ἑωυτὸν Κᾶράς τε καὶ Ἴωνας ἄνδρας ἐπικούρους τρισμυρίους· ἦν δέ οἱ τὰ βασιλήια ἐν Σάι πόλι, μεγάλα ἐόντα καὶ ἀξιοθέητα. καὶ οἵ τε περὶ τὸν Ἀπρίην ἐπὶ τοὺς Αἰγυπτίους ἤισαν καὶ οἱ περὶ τὸν Ἄμασιν ἐπὶ τοὺς ξείνους· ἔν τε δὴ Μωμέμφι πόλι ἐγένοντο ἀμφότεροι καὶ πειρήσεσθαι ἔμελλον ἀλλήλων.", "st": "2.163"}, {"sp": "N", "t": "ἔστι δὲ Αἰγυπτίων ἑπτὰ γένεα, καὶ τούτων οἳ μὲν ἱρέες οἳ δὲ μάχιμοι κεκλέαται, οἳ δὲ βουκόλοι οἳ δὲ συβῶται, οἳ δὲ κάπηλοι, οἳ δὲ ἑρμηνέες, οἳ δὲ κυβερνήται. γένεα μὲν Αἰγυπτίων τοσαῦτα ἐστί, οὐνόματα δέ σφι κέεται ἀπὸ τῶν τεχνέων. οἱ δὲ μάχιμοι αὐτῶν καλέονται μὲν Καλασίριές τε καὶ Ἑρμοτύβιες, ἐκ νομῶν δὲ τῶνδε εἰσί· κατὰ γὰρ δὴ νομοὺς Αἴγυπτος ἅπασα διαραίρηται.", "st": "2.164"}, {"sp": "N", "t": "Ἑρμοτυβίων μὲν οἵδε εἰσὶ νομοί, Βουσιρίτης, Σαΐτης, Χεμμίτης, Παπρημίτης, νῆσος ἡ Προσωπῖτις καλεομένη, Ναθῶ τὸ ἥμισυ. ἐκ μὲν τούτων τῶν νομῶν Ἑρμοτύβιες εἰσί, γενόμενοι, ὅτε ἐπὶ πλείστους ἐγένοντο, ἑκκαίδεκα μυριάδες. καὶ τούτων βαναυσίης οὐδεὶς δεδάηκε οὐδέν, ἀλλ’ ἀνέωνται ἐς τὸ μάχιμον.", "st": "2.165"}, {"sp": "N", "t": "καλασιρίων δὲ οἵδε ἄλλοι νομοί εἰσι, Θηβαῖος, Βουβαστίτης, Ἀφθίτης, Τανίτης, Μενδήσιος, Σεβεννύτης, Ἀθριβίτης, Φαρβαϊθίτης, Θμουΐτης, Ὀνουφίτης, Ἀνύτιος, Μυεκφορίτης· οὗτος ὁ νομὸς ἐν νήσῳ οἰκέει ἀντίον Βουβάστιος πόλιος. οὗτοι δὲ οἱ νομοὶ Καλασιρίων εἰσί, γενόμενοι, ὅτε ἐπὶ πλείστους ἐγένοντο, πέντε καὶ εἴκοσι μυριάδες ἀνδρῶν. οὐδὲ τούτοισι ἔξεστι τέχνην ἐπασκῆσαι οὐδεμίαν, ἀλλὰ τὰ ἐς πόλεμον ἐπασκέουσι μοῦνα, παῖς παρὰ πατρὸς ἐκδεκόμενος.", "st": "2.166"}, {"sp": "N", "t": "εἰ μέν νυν καὶ τοῦτο παρ’ Αἰγυπτίων μεμαθήκασι οἱ Ἕλληνες, οὐκ ἔχω ἀτρεκέως κρῖναι, ὁρέων καὶ Θρήικας καὶ Σκύθας καὶ Πέρσας καὶ Λυδοὺς καὶ σχεδὸν πάντας τοὺς βαρβάρους ἀποτιμοτέρους τῶν ἄλλων ἡγημένους πολιητέων τοὺς τὰς τέχνας μανθάνοντας καὶ τοὺς ἐκγόνους τούτων, τοὺς δὲ ἀπαλλαγμένους τῶν χειρωναξιέων γενναίους νομιζομένους εἶναι, καὶ μάλιστα τοὺς ἐς τὸν πόλεμον ἀνειμένους· μεμαθήκασι δ’ ὦν τοῦτο πάντες οἱ Ἕλληνες καὶ μάλιστα Λακεδαιμόνιοι. ἥκιστα δὲ Κορίνθιοι ὄνονται τοὺς χειροτέχνας.", "st": "2.167"}, {"sp": "N", "t": "γέρεα δέ σφι ἦν τάδε ἐξαραιρημένα μούνοισι Αἰγυπτίων πάρεξ τῶν ἱρέων, ἄρουραι ἐξαίρετοι δυώδεκα ἑκάστῳ ἀτελέες. ἡ δὲ ἄρουρα ἑκατὸν πηχέων ἐστὶ Αἰγυπτίων πάντῃ, ὁ δὲ Αἰγύπτιος πῆχυς τυγχάνει ἴσος ἐὼν τῷ Σαμίῳ. ταῦτα μὲν δὴ τοῖσι ἅπασι ἦν ἐξαραιρημένα, τάδε δὲ ἐν περιτροπῇ ἐκαρποῦντο καὶ οὐδαμὰ ὡυτοί. Καλασιρίων χίλιοι καὶ Ἑρμοτυβίων ἐδορυφόρεον ἐνιαυτὸν ἕκαστοι τὸν βασιλέα· τούτοισι ὦν τάδε πάρεξ τῶν ἀρουρέων ἄλλα ἐδίδοτο ἐπ’ ἡμέρῃ ἑκάστῃ, ὀπτοῦ σίτου σταθμὸς πέντε μνέαι ἑκάστῳ, κρεῶν βοέων δύο μνέαι, οἴνου τέσσερες ἀρυστῆρες. ταῦτα τοῖσι αἰεὶ δορυφορέουσι ἐδίδοτο.", "st": "2.168"}, {"sp": "N", "t": "ἐπείτε δὲ συνιόντες ὅ τε Ἀπρίης ἄγων τοὺς ἐπικούρους καὶ ὁ Ἄμασις πάντας Αἰγυπτίους ἀπίκοντο ἐς Μώμεμφιν πόλιν, συνέβαλον· καὶ ἐμαχέσαντο μὲν εὖ οἱ ξεῖνοι, πλήθεϊ δὲ πολλῷ ἐλάσσονες ἐόντες κατὰ τοῦτο ἑσσώθησαν. Ἀπρίεω δὲ λέγεται εἶναι ἥδε διάνοια, μηδ’ ἂν θεόν μιν μηδένα δύνασθαι παῦσαι τῆς βασιληίης· οὕτω ἀσφαλέως ἑωυτῷ ἱδρῦσθαι ἐδόκεε. καὶ δὴ τότε συμβαλὼν ἑσσώθη καὶ ζωγρηθεὶς ἀπήχθη ἐς Σάιν πόλιν, ἐς τὰ ἑωυτοῦ οἰκία πρότερον ἐόντα, τότε δὲ Ἀμάσιος ἤδη βασιληία. ἐνθαῦτα δὲ τέως μὲν ἐτρέφετο ἐν τοῖσι βασιληίοισι, καί μιν Ἄμασις εὖ περιεῖπε· τέλος δὲ μεμφομένων Αἰγυπτίων ὡς οὐ ποιέοι δίκαια τρέφων τὸν σφίσι τε καὶ ἑωυτῷ ἔχθιστον, οὕτω δὴ παραδιδοῖ τὸν Ἀπρίην τοῖσι Αἰγυπτίοισι. οἳ δέ μιν ἀπέπνιξαν καὶ ἔπειτα ἔθαψαν ἐν τῇσι πατρωίῃσι ταφῇσι· αἳ δὲ εἰσὶ ἐν τῷ ἱρῷ τῆς Ἀθηναίης, ἀγχοτάτω τοῦ μεγάρου, ἐσιόντι ἀριστερῆς χειρός. ἔθαψαν δὲ Σαῗται πάντας τοὺς ἐκ νομοῦ τούτου γενομένους βασιλέας ἔσω ἐν τῷ ἱρῷ. καὶ γὰρ τὸ τοῦ Ἀμάσιος σῆμα ἑκαστέρω μὲν ἐστὶ τοῦ μεγάρου ἢ τὸ τοῦ Ἀπρίεω καὶ τῶν τούτου προπατόρων, ἔστι μέντοι καὶ τοῦτο ἐν τῇ αὐλῇ τοῦ ἱροῦ, παστὰς λιθίνη μεγάλη καὶ ἠσκημένη στύλοισί τε φοίνικας τὰ δένδρεα μεμιμημένοισι καὶ τῇ ἄλλῃ δαπάνῃ· ἔσω δὲ ἐν τῇ παστάδι διξὰ θυρώματα ἕστηκε, ἐν δὲ τοῖσι θυρώμασι ἡ θήκη ἐστί.", "st": "2.169"}, {"sp": "N", "t": "εἰσὶ δὲ καὶ αἱ ταφαὶ τοῦ οὐκ ὅσιον ποιεῦμαι ἐπὶ τοιούτῳ πρήγματι ἐξαγορεύειν τὸ οὔνομα ἐν Σάι, ἐν τῷ ἱρῷ τῆς Ἀθηναίης, ὄπισθε τοῦ νηοῦ, παντὸς τοῦ τῆς Ἀθηναίης ἐχόμεναι τοίχου. καὶ ἐν τῷ τεμένεϊ ὀβελοὶ ἑστᾶσι μεγάλοι λίθινοι, λίμνη τε ἐστὶ ἐχομένη λιθίνῃ κρηπῖδι κεκοσμημένη καὶ ἐργασμένη εὖ κύκλῳ καὶ μέγαθος, ὡς ἐμοὶ ἐδόκεε, ὅση περ ἡ ἐν Δήλῳ ἡ τροχοειδὴς καλεομένη.", "st": "2.170"}, {"sp": "N", "t": "ἐν δὲ τῇ λίμνῃ ταύτῃ τὰ δείκηλα τῶν παθέων αὐτοῦ νυκτὸς ποιεῦσι, τὰ καλέουσι μυστήρια Αἰγύπτιοι. περὶ μέν νυν τούτων εἰδότι μοι ἐπὶ πλέον ὡς ἕκαστα αὐτῶν ἔχει, εὔστομα κείσθω. καὶ τῆς Δήμητρος τελετῆς πέρι, τὴν οἱ Ἕλληνες θεσμοφόρια καλέουσι, καὶ ταύτης μοι πέρι εὔστομα κείσθω, πλὴν ὅσον αὐτῆς ὁσίη ἐστὶ λέγειν· αἱ Δαναοῦ θυγατέρες ἦσαν αἱ τὴν τελετὴν ταύτην ἐξ Αἰγύπτου ἐξαγαγοῦσαι καὶ διδάξασαι τὰς Πελασγιώτιδας γυναῖκας· μετὰ δὲ ἐξαναστάσης πάσης Πελοποννήσου ὑπὸ Δωριέων ἐξαπώλετο ἡ τελετή, οἱ δὲ ὑπολειφθέντες Πελοποννησίων καὶ οὐκ ἐξαναστάντες Ἀρκάδες διέσωζον αὐτὴν μοῦνοι.", "st": "2.171"}, {"sp": "N", "t": "Ἀπρίεω δὲ ὧδε καταραιρημένου ἐβασίλευσε Ἄμασις, νομοῦ μὲν Σαΐτεω ἐών, ἐκ τῆς δὲ ἦν πόλιος, οὔνομά οἱ ἐστὶ Σιούφ. τὰ μὲν δὴ πρῶτα κατώνοντο τὸν Ἄμασιν Αἰγύπτιοι καὶ ἐν οὐδεμιῇ μοίρῃ μεγάλῃ ἦγον ἅτε δὴ δημότην τὸ πρὶν ἐόντα καὶ οἰκίης οὐκ ἐπιφανέος· μετὰ δὲ σοφίῃ αὐτοὺς ὁ Ἄμασις, οὐκ ἀγνωμοσύνῃ προσηγάγετο. ἦν οἱ ἄλλα τε ἀγαθὰ μυρία, ἐν δὲ καὶ ποδανιπτὴρ χρύσεος, ἐν τῷ αὐτός τε ὁ Ἄμασις καὶ οἱ δαιτυμόνες οἱ πάντες τοὺς πόδας ἑκάστοτε ἐναπενίζοντο· τοῦτον κατ’ ὦν κόψας ἄγαλμα δαίμονος ἐξ αὐτοῦ ἐποιήσατο, καὶ ἵδρυσε τῆς πόλιος ὅκου ἦν ἐπιτηδεότατον· οἱ δὲ Αἰγύπτιοι φοιτέοντες πρὸς τὤγαλμα ἐσέβοντο μεγάλως. μαθὼν δὲ ὁ Ἄμασις τὸ ἐκ τῶν ἀστῶν ποιεύμενον, συγκαλέσας Αἰγυπτίους ἐξέφηνε φὰς ἐκ τοῦ ποδανιπτῆρος τὤγαλμα γεγονέναι, ἐς τὸν πρότερον μὲν τοὺς Αἰγυπτίους ἐνεμέειν τε καὶ ἐνουρέειν καὶ πόδας ἐναπονίζεσθαι, τότε δὲ μεγάλως σέβεσθαι. ἤδη ὦν ἔφη λέγων ὁμοίως αὐτὸς τῷ ποδανιπτῆρι πεπρηγέναι· εἰ γὰρ πρότερον εἶναι δημότης, ἀλλ’ ἐν τῷ παρεόντι εἶναι αὐτῶν βασιλεύς· καὶ τιμᾶν τε καὶ προμηθέεσθαι ἑωυτοῦ ἐκέλευε.", "st": "2.172"}, {"sp": "N", "t": "τοιούτῳ μὲν τρόπῳ προσηγάγετο τοὺς Αἰγυπτίους ὥστε δικαιοῦν δουλεύειν, ἐχρᾶτο δὲ καταστάσι πρηγμάτων τοιῇδε· τὸ μὲν ὄρθριον μέχρι ὅτευ πληθούσης ἀγορῆς προθύμως ἔπρησσε τὰ προσφερόμενα πρήγματα, τὸ δὲ ἀπὸ τούτου ἔπινέ τε καὶ κατέσκωπτε τοὺς συμπότας καὶ ἦν μάταιός τε καὶ παιγνιήμων. ἀχθεσθέντες δὲ τούτοισι οἱ φίλοι αὐτοῦ ἐνουθέτεον αὐτὸν τοιάδε λέγοντες. ὦ βασιλεῦ, οὐκ ὀρθῶς, σεωυτοῦ προέστηκας, ἐς τὸ ἄγαν φαῦλον προάγων σεωυτόν. σὲ γὰρ ἐχρῆν ἐν θρόνῳ σεμνῷ σεμνὸν θωκέοντα δι’ ἡμέρης πρήσσειν τὰ πρήγματα, καὶ οὕτω Αἰγύπτιοί τ’ ἂν ἠπιστέατο ὡς ὑπ’ ἀνδρὸς μεγάλου ἄρχονται, καὶ ἄμεινον σὺ ἂν ἤκουες· νῦν δὲ ποιέεις οὐδαμῶς βασιλικά. ὃ δ’ ἀμείβετο τοῖσιδε αὐτούς. τὰ τόξα οἱ ἐκτημένοι, ἐπεὰν μὲν δέωνται χρᾶσθαι, ἐντανύουσι· εἰ γὰρ δὴ τὸν πάντα χρόνον ἐντεταμένα εἴη, ἐκραγείη ἄν, ὥστε ἐς τὸ δέον οὐκ ἂν ἔχοιεν αὐτοῖσι χρᾶσθαι. οὕτω δὲ καὶ ἀνθρώπου κατάστασις· εἰ ἐθέλοι κατεσπουδάσθαι αἰεὶ μηδὲ ἐς παιγνίην τὸ μέρος ἑωυτὸν ἀνιέναι, λάθοι ἂν ἤτοι μανεὶς ἢ ὅ γε ἀπόπληκτος γενόμενος· τὰ ἐγὼ ἐπιστάμενος μέρος ἑκατέρῳ νέμω. ταῦτα μὲν τοὺς φίλους ἀμείψατο.", "st": "2.173"}, {"sp": "N", "t": "λέγεται δὲ ὁ Ἄμασις, καὶ ὅτε ἦν ἰδιώτης, ὡς φιλοπότης ἦν καὶ φιλοσκώμμων καὶ οὐδαμῶς κατεσπουδασμένος ἀνήρ· ὅκως δέ μιν ἐπιλείποι πίνοντά τε καὶ εὐπαθέοντα τὰ ἐπιτήδεα, κλέπτεσκε ἂν περιιών· οἳ δ’ ἄν μιν φάμενοι ἔχειν τὰ σφέτερα χρήματα ἀρνεύμενον ἄγεσκον ἐπὶ μαντήιον, ὅκου ἑκάστοισι εἴη. πολλὰ μὲν δὴ καὶ ἡλίσκετο ὑπὸ τῶν μαντηίων, πολλὰ δὲ καὶ ἀπέφευγε. ἐπείτε δὲ καὶ ἐβασίλευσε, ἐποίησε τοιάδε· ὅσοι μὲν αὐτὸν τῶν θεῶν ἀπέλυσαν μὴ φῶρα εἶναι, τούτων μὲν τῶν ἱρῶν οὔτε ἐπεμέλετο οὔτε ἐς ἐπισκευὴν ἐδίδου οὐδέν, οὐδὲ φοιτέων ἔθυε ὡς οὐδενὸς ἐοῦσι ἀξίοισι ψευδέα τε μαντήια ἐκτημένοισι· ὅσοι δέ μιν κατέδησαν φῶρα εἶναι, τούτων δὲ ὡς ἀληθέων θεῶν ἐόντων καὶ ἀψευδέα μαντήια παρεχομένων τὰ μάλιστα ἐπεμέλετο.", "st": "2.174"}, {"sp": "N", "t": "καὶ τοῦτο μὲν ἐν Σάι τῇ Ἀθηναίῃ προπύλαια θωμάσια οἷα ἐξεποίησε, πολλὸν πάντας ὑπερβαλόμενος τῷ τε ὕψεϊ καὶ τῷ μεγάθεϊ, ὅσων τε τὸ μέγαθος λίθων ἐστὶ καὶ ὁκοίων τεῶν· τοῦτο δὲ κολοσσοὺς μεγάλους καὶ ἀνδρόσφιγγας περιμήκεας ἀνέθηκε, λίθους τε ἄλλους ἐς ἐπισκευὴν ὑπερφυέας τὸ μέγαθος ἐκόμισε. ἠγάγετο δὲ τούτων τοὺς μὲν ἐκ τῶν κατὰ Μέμφιν ἐουσέων λιθοτομιέων, τοὺς δὲ ὑπερμεγάθεας ἐξ Ἐλεφαντίνης πόλιος πλόον καὶ εἴκοσι ἡμερέων ἀπεχούσης ἀπὸ Σάιος. τὸ δὲ οὐκ ἥκιστα αὐτῶν ἀλλὰ μάλιστα θωμάζω, ἔστι τόδε· οἴκημα μουνόλιθον ἐκόμισε ἐξ Ἐλεφαντίνης πόλιος, καὶ τοῦτο ἐκόμιζον μὲν ἐπ’ ἔτεα τρία, δισχίλιοι δέ οἱ προσετετάχατο ἄνδρες ἀγωγέες, καὶ οὗτοι ἅπαντες ἦσαν κυβερνῆται. τῆς δὲ στέγης ταύτης τὸ μὲν μῆκος ἔξωθεν ἐστὶ εἷς τε καὶ εἴκοσι πήχεες, εὖρος δὲ τεσσερεσκαίδεκα, ὕψος δὲ ὀκτώ. ταῦτα μὲν τὰ μέτρα ἔξωθεν τῆς στέγης τῆς μουνολίθου ἐστί, ἀτὰρ ἔσωθεν τὸ μῆκος ὀκτωκαίδεκα πηχέων καὶ πυγόνος …, τὸ δὲ ὕψος πέντε πηχέων ἐστί. αὕτη τοῦ ἱροῦ κέεται παρὰ τὴν ἔσοδον· ἔσω γάρ μιν ἐς τὸ ἱρόν φασι τῶνδε εἵνεκα οὐκ ἐσελκύσαι· τὸν ἀρχιτέκτονα αὐτῆς ἑλκομένης τῆς στέγης ἀναστενάξαι, οἷά τε χρόνου ἐγγεγονότος πολλοῦ καὶ ἀχθόμενον τῷ ἔργῳ, τὸν δὲ Ἄμασιν ἐνθύμιον ποιησάμενον οὐκ ἐᾶν ἔτι προσωτέρω ἑλκύσαι. ἤδη δὲ τινὲς λέγουσι ὡς ἄνθρωπος διεφθάρη ὑπ’ αὐτῆς τῶν τις αὐτὴν μοχλευόντων, καὶ ἀπὸ τούτου οὐκ ἐσελκυσθῆναι.", "st": "2.175"}, {"sp": "N", "t": "ἀνέθηκε δὲ καὶ ἐν τοῖσι ἄλλοισι ἱροῖσι ὁ Ἄμασις πᾶσι τοῖσι ἐλλογίμοισι ἔργα τὸ μέγαθος ἀξιοθέητα, ἐν δὲ καὶ ἐν Μέμφι τὸν ὕπτιον κείμενον κολοσσὸν τοῦ Ἡφαιστείου ἔμπροσθε, τοῦ πόδες πέντε καὶ ἑβδομήκοντα εἰσὶ τὸ μῆκος· ἐπὶ δὲ τῷ αὐτῷ βάθρῳ ἑστᾶσι τοῦ αὐτοῦ ἐόντος λίθου δύο κολοσσοί, εἴκοσι ποδῶν τὸ μέγαθος ἐὼν ἑκάτερος, ὃ μὲν ἔνθεν ὃ δ’ ἔνθεν τοῦ μεγάλου. ἔστι δὲ λίθινος ἕτερος τοσοῦτος καὶ ἐν Σάι, κείμενος κατὰ τὸν αὐτὸν τρόπον τῷ ἐν Μέμφι. τῇ Ἴσι τε τὸ ἐν Μέμφι ἱρὸν Ἄμασις ἐστὶ ὁ ἐξοικοδομήσας, ἐὸν μέγα τε καὶ ἀξιοθεητότατον.", "st": "2.176"}, {"sp": "N", "t": "ἐπ’ Ἀμάσιος δὲ βασιλέος λέγεται Αἴγυπτος μάλιστα δὴ τότε εὐδαιμονῆσαι καὶ τὰ ἀπὸ τοῦ ποταμοῦ τῇ χώρῃ γινόμενα καὶ τὰ ἀπὸ τῆς χώρης τοῖσι ἀνθρώποισι, καὶ πόλις ἐν αὐτῇ γενέσθαι τὰς ἁπάσας τότε δισμυρίας τὰς οἰκεομένας. νόμον τε Αἰγυπτίοισι τόνδε Ἄμασις ἐστὶ ὁ καταστήσας, ἀποδεικνύναι ἔτεος ἑκάστου τῷ νομάρχῃ πάντα τινὰ Αἰγυπτίων ὅθεν βιοῦται· μὴ δὲ ποιεῦντα ταῦτα μηδὲ ἀποφαίνοντα δικαίην ζόην ἰθύνεσθαι θανάτῳ. Σόλων δὲ ὁ Ἀθηναῖος λαβὼν ἐξ Αἰγύπτου τοῦτον τὸν νόμον Ἀθηναίοισι ἔθετο· τῷ ἐκεῖνοι ἐς αἰεὶ χρέωνται ἐόντι ἀμώμῳ νόμῳ.", "st": "2.177"}, {"sp": "N", "t": "φιλέλλην δὲ γενόμενος ὁ Ἄμασις ἄλλα τε ἐς Ἑλλήνων μετεξετέρους ἀπεδέξατο, καὶ δὴ καὶ τοῖσι ἀπικνευμένοισι ἐς Αἴγυπτον ἔδωκε Ναύκρατιν πόλιν ἐνοικῆσαι· τοῖσι δὲ μὴ βουλομένοισι αὐτῶν οἰκέειν, αὐτοῦ δὲ ναυτιλλομένοισι ἔδωκε χώρους ἐνιδρύσασθαι βωμοὺς καὶ τεμένεα θεοῖσι. τὸ μέν νυν μέγιστον αὐτῶν τέμενος, καὶ ὀνομαστότατον ἐὸν καὶ χρησιμώτατον, καλεύμενον δὲ Ἑλλήνιον, αἵδε αἱ πόλιες εἰσὶ αἱ ἱδρυμέναι κοινῇ, Ἱώνων μὲν Χίος καὶ Τέως καὶ Φώκαια καὶ Κλαζομεναί, Δωριέων δὲ Ῥόδος καὶ Κνίδος καὶ Ἁλικαρνησσὸς καὶ Φάσηλις, Αἰολέων δὲ ἡ Μυτιληναίων μούνη. τουτέων μὲν ἐστὶ τοῦτο τὸ τέμενος, καὶ προστάτας τοῦ ἐμπορίου αὗται αἱ πόλιες εἰσὶ αἱ παρέχουσαι· ὅσαι δὲ ἄλλαι πόλιες μεταποιεῦνται, οὐδέν σφι μετεὸν μεταποιεῦνται. χωρὶς δὲ Αἰγινῆται ἐπὶ ἑωυτῶν ἱδρύσαντο τέμενος Διός, καὶ ἄλλο Σάμιοι Ἥρης καὶ Μιλήσιοι Ἀπόλλωνος.", "st": "2.178"}, {"sp": "N", "t": "ἦν δὲ τὸ παλαιὸν μούνη Ναύκρατις ἐμπόριον καὶ ἄλλο οὐδὲν Αἰγύπτου· εἰ δέ τις ἐς τῶν τι ἄλλο στομάτων τοῦ Νείλου ἀπίκοιτο, χρῆν ὀμόσαι μὴ μὲν ἑκόντα ἐλθεῖν, ἀπομόσαντα δὲ τῇ νηὶ αὐτῇ πλέειν ἐς τὸ Κανωβικόν· ἢ εἰ μή γε οἷά τε εἴη πρὸς ἀνέμους ἀντίους πλέειν, τὰ φορτία ἔδεε περιάγειν ἐν βάρισι περὶ τὸ Δέλτα, μέχρι οὗ ἀπίκοιτο ἐς Ναύκρατιν. οὕτω μὲν δὴ Ναύκρατις ἐτετίμητο.", "st": "2.179"}, {"sp": "N", "t": "Ἀμφικτυόνων δὲ μισθωσάντων τὸν ἐν Δελφοῖσι νῦν ἐόντα νηὸν τριηκοσίων ταλάντων ἐξεργάσασθαι (ὁ γὰρ πρότερον ἐὼν αὐτόθι αὐτόματος κατεκάη), τοὺς Δελφοὺς δὴ ἐπέβαλλε τεταρτημόριον τοῦ μισθώματος παρασχεῖν. πλανώμενοι δὲ οἱ Δελφοὶ περὶ τὰς πόλις ἐδωτίναζον, ποιεῦντες δὲ τοῦτο οὐκ ἐλάχιστον ἐξ Αἰγύπτου ἠνείκαντο· Ἄμασις μὲν γάρ σφι ἔδωκε χίλια στυπτηρίης τάλαντα, οἱ δὲ ἐν Αἰγύπτῳ οἰκέοντες Ἕλληνες εἴκοσι μνέας.", "st": "2.180"}, {"sp": "N", "t": "Κυρηναίοισι δὲ Ἄμασις φιλότητά τε καὶ συμμαχίην συνεθήκατο, ἐδικαίωσε δὲ καὶ γῆμαι αὐτόθεν, εἴτ’ ἐπιθυμήσας Ἑλληνίδος γυναικὸς εἴτε καὶ ἄλλως φιλότητος Κυρηναίων εἵνεκα· γαμέει δὲ ὦν οἳ μὲν λέγουσι Βάττου οἳ δ’ Ἀρκεσίλεω θυγατέρα, οἳ δὲ Κριτοβούλου ἀνδρὸς τῶν ἀστῶν δοκίμου, τῇ οὔνομα ἦν Λαδίκη· τῇ ἐπείτε συγκλίνοιτο ὁ Ἄμασις, μίσγεσθαι οὐκ οἷός τε ἐγίνετο, τῇσι δὲ ἄλλῃσι γυναιξὶ ἐχρᾶτο. ἐπείτε δὲ πολλὸν τοῦτο ἐγίνετο, εἶπε ὁ Ἄμασις πρὸς τὴν Λαδίκην ταύτην καλεομένην, ὦ γύναι, κατά με ἐφάρμαξας, καὶ ἔστι τοι οὐδεμία μηχανὴ μὴ οὐκ ἀπολωλέναι κάκιστα γυναικῶν πασέων. ἡ δὲ Λαδίκη, ἐπείτε οἱ ἀρνευμένῃ οὐδὲν ἐγίνετο πρηΰτερος ὁ Ἄμασις, εὔχεται ἐν τῷ νόῳ τῇ Ἀφροδίτῃ, ἤν οἱ ὑπ’ ἐκείνην τὴν νύκτα μιχθῇ ὁ Ἄμασις, τοῦτο γάρ οἱ κακοῦ εἶναι μῆχος, ἄγαλμά οἱ ἀποπέμψειν ἐς Κυρήνην. μετὰ δὲ τὴν εὐχὴν αὐτίκα οἱ ἐμίχθη ὁ Ἄμασις. καὶ τὸ ἐνθεῦτεν ἤδη, ὁκότε ἔλθοι Ἄμασις πρὸς αὐτήν, ἐμίσγετο, καὶ κάρτα μιν ἔστερξε μετὰ τοῦτο. ἡ δὲ Λαδίκη ἀπέδωκε τὴν εὐχὴν τῇ θεῷ· ποιησαμένη γὰρ ἄγαλμα ἀπέπεμψε ἐς Κυρήνην, τὸ ἔτι καὶ ἐς ἐμὲ ἦν σόον, ἔξω τετραμμένον τοῦ Κυρηναίων ἄστεος. ταύτην τὴν Λαδίκην, ὡς ἐπεκράτησε Καμβύσης Αἰγύπτου καὶ ἐπύθετο αὐτῆς ἥτις εἴη, ἀπέπεμψε ἀσινέα ἐς Κυρήνην.", "st": "2.181"}, {"sp": "N", "t": "ἀνέθηκε δὲ καὶ ἀναθήματα ὁ Ἄμασις ἐς τὴν Ἑλλάδα, τοῦτο μὲν ἐς Κυρήνην ἄγαλμα ἐπίχρυσον Ἀθηναίης καὶ εἰκόνα ἑωυτοῦ γραφῇ εἰκασμένην, τοῦτο δὲ τῇ ἐν Λίνδῳ Ἀθηναίῃ δύο τε ἀγάλματα λίθινα καὶ θώρηκα λίνεον ἀξιοθέητον, τοῦτο δ’ ἐς Σάμον τῇ Ἥρῃ εἰκόνας ἑωυτοῦ διφασίας ξυλίνας, αἳ ἐν τῷ νηῷ τῷ μεγάλῳ ἱδρύατο ἔτι καὶ τὸ μέχρι ἐμεῦ, ὄπισθε τῶν θυρέων. ἐς μέν νυν Σάμον ἀνέθηκε κατὰ ξεινίην τὴν ἑωυτοῦ τε καὶ Πολυκράτεος τοῦ Αἰάκεος, ἐς δὲ Λίνδον ξεινίης μὲν οὐδεμιῆς εἵνεκεν, ὅτι δὲ τὸ ἱρὸν τὸ ἐν Λίνδῳ τὸ τῆς Ἀθηναίης λέγεται τὰς Δαναοῦ θυγατέρας ἱδρύσασθαι προσσχούσας, ὅτε ἀπεδίδρησκον τοὺς Αἰγύπτου παῖδας. ταῦτα μὲν ἀνέθηκε ὁ Ἄμασις, εἷλε δὲ Κύπρον πρῶτος ἀνθρώπων καὶ κατεστρέψατο ἐς φόρου ἀπαγωγήν.", "st": "2.182"}, {"sp": "HDR", "t": "Ἱστοριῶν Γ· Θάλεια", "st": "3"}, {"sp": "N", "t": "ἐπὶ τοῦτον δὴ τὸν Ἄμασιν Καμβύσης ὁ Κύρου ἐστρατεύετο, ἄγων καί ἄλλους τῶν ἦρχε καὶ Ἑλλήνων Ἴωνάς τε καὶ Αἰολέας, δι’ αἰτίην τοιήνδε. πέμψας Καμβύσης ἐς Αἴγυπτον κήρυκα αἴτεε Ἄμασιν θυγατέρα, αἴτεε δὲ ἐκ βουλῆς ἀνδρὸς Αἰγυπτίου, ὃς μεμφόμενος Ἄμασιν ἔπρηξε ταῦτα ὅτι μιν ἐξ ἁπάντων τῶν ἐν Αἰγύπτῳ ἰητρῶν ἀποσπάσας ἀπὸ γυναικός τε καὶ τέκνων ἔκδοτον ἐποίησε ἐς Πέρσας, ὅτε Κῦρος πέμψας παρὰ Ἄμασιν αἴτεε ἰητρὸν ὀφθαλμῶν ὃς εἴη ἄριστος τῶν ἐν Αἰγύπτῳ. ταῦτα δὴ ἐπιμεμφόμενος ὁ Αἰγύπτιος ἐνῆγε τῇ συμβουλῇ κελεύων αἰτέειν τὸν Καμβύσεα Ἄμασιν θυγατέρα, ἵνα ἢ δοὺς ἀνιῷτο ἢ μὴ δοὺς Καμβύσῃ ἀπέχθοιτο. ὁ δὲ Ἄμασις τῇ δυνάμι τῶν Περσέων ἀχθόμενος καὶ ἀρρωδέων οὐκ εἶχε οὔτε δοῦναι οὔτε ἀρνήσασθαι· εὖ γὰρ ἠπίστατο ὅτι οὐκ ὡς γυναῖκά μιν ἔμελλε Καμβύσης ἕξειν ἀλλ’ ὡς παλλακήν. ταῦτα δὴ ἐκλογιζόμενος ἐποίησε τάδε. ἦν Ἀπρίεω τοῦ προτέρου βασιλέος θυγάτηρ κάρτα μεγάλη τε καὶ εὐειδὴς μούνη τοῦ οἴκου λελειμμένη, οὔνομα δέ οἱ ἦν Νίτητις· ταύτην δὴ τὴν παῖδα ὁ Ἄμασις κοσμήσας ἐσθῆτί τε καὶ χρυσῷ ἀποπέμπει ἐς Πέρσας ὡς ἑωυτοῦ θυγατέρα. μετὰ δὲ χρόνον ὥς μιν ἠσπάζετο πατρόθεν ὀνομάζων, λέγει πρὸς αὐτὸν ἡ παῖς ὦ βασιλεῦ, διαβεβλημένος ὑπὸ Ἀμάσιος οὐ μανθάνεις. ὃς ἐμὲ σοὶ κόσμῳ ἀσκήσας ἀπέπεμψε ὡς ἑωυτοῦ θυγατέρα διδούς, ἐοῦσαν τῇ ἀληθείῃ Ἀπρίεω, τὸν ἐκεῖνος ἐόντα ἑωυτοῦ δεσπότεα μετ’ Αἰγυπτίων ἐπαναστὰς ἐφόνευσε. τοῦτο δὴ τὸ ἔπος καὶ αὕτη ἡ αἰτίη ἐγγενομένη ἤγαγε Καμβύσεα τὸν Κύρου μεγάλως θυμωθέντα ἐπ’ Αἴγυπτον.", "st": "3.1"}, {"sp": "N", "t": "οὕτω μέν νυν λέγουσι Πέρσαι. Αἰγύπτιοι δὲ οἰκηιοῦνται Καμβύσεα, φάμενοί μιν ἐκ ταύτης δὴ τῆς Ἀπρίεω θυγατρὸς γενέσθαι· Κῦρον γὰρ εἶναι τὸν πέμψαντα παρὰ Ἄμασιν ἐπὶ τὴν θυγατέρα, ἀλλ’ οὐ Καμβύσεα. λέγοντες δὲ ταῦτα οὐκ ὀρθῶς λέγουσι. οὐ μὲν οὐδὲ λέληθε αὐτούς (εἰ γὰρ τινὲς καὶ ἄλλοι, τὰ Περσέων νόμιμα ἐπιστέαται καὶ Αἰγύπτιοι) ὅτι πρῶτα μὲν νόθον οὔ σφι νόμος ἐστὶ βασιλεῦσαι γνησίου παρεόντος, αὖτις δὲ ὅτι Κασσανδάνης τῆς Φαρνάσπεω θυγατρὸς ἦν παῖς Καμβύσης, ἀνδρὸς Ἀχαιμενίδεω, ἀλλ’ οὐκ ἐκ τῆς Αἰγυπτίης. ἀλλὰ παρατρέπουσι τὸν λόγον προσποιεύμενοι τῇ Κύρου οἰκίῃ συγγενέες εἶναι.", "st": "3.2"}, {"sp": "N", "t": "καὶ ταῦτα μὲν ὧδε ἔχει. λέγεται δὲ καὶ ὅδε λόγος, ἐμοὶ μὲν οὐ πιθανός, ὡς τῶν Περσίδων γυναικῶν ἐσελθοῦσά τις παρὰ τὰς Κύρου γυναῖκας, ὡς εἶδε τῇ Κασσανδάνῃ παρεστεῶτα τέκνα εὐειδέα τε καὶ μεγάλα, πολλῷ ἐχρᾶτο τῷ ἐπαίνῳ ὑπερθωμάζουσα, ἡ δὲ Κασσανδάνη ἐοῦσα τοῦ Κύρου γυνὴ εἶπε τάδε· τοιῶνδε μέντοι ἐμὲ παίδων μητέρα ἐοῦσαν Κῦρος ἐν ἀτιμίῃ ἔχει, τὴν δὲ ἀπ’ Αἰγύπτου ἐπίκτητον ἐν τιμῇ τίθεται. τὴν μὲν ἀχθομένην τῇ Νιτήτι εἰπεῖν ταῦτα, τῶν δέ οἱ παίδων τὸν πρεσβύτερον εἰπεῖν Καμβύσεα· τοιγάρ τοι ὦ μῆτερ, ἐπεὰν ἐγὼ γένωμαι ἀνήρ, Αἰγύπτου τὰ μὲν ἄνω κάτω θήσω, τὰ δὲ κάτω ἄνω. ταῦτα εἰπεῖν αὐτὸν ἔτεα ὡς δέκα κου γεγονότα, καὶ τὰς γυναῖκας ἐν θώματι γενέσθαι· τὸν δὲ διαμνημονεύοντα οὕτω δή, ἐπείτε ἀνδρώθη καὶ ἔσχε τὴν βασιληίην, ποιήσασθαι τὴν ἐπ’ Αἴγυπτον στρατηίην.", "st": "3.3"}, {"sp": "N", "t": "συνήνεικε δὲ καὶ ἄλλο τι τοιόνδε πρῆγμα γενέσθαι ἐς τὴν ἐπιστράτευσιν ταύτην. ἦν τῶν ἐπικούρων Ἀμάσιος ἀνὴρ γένος μὲν Ἁλικαρνησσεύς, οὔνομα δέ οἱ Φάνης, καὶ γνώμην ἱκανὸς καὶ τὰ πολεμικὰ ἄλκιμος. οὗτος ὁ Φάνης μεμφόμενός κού τι Ἀμάσι ἐκδιδρήσκει πλοίῳ ἐξ Αἰγύπτου, βουλόμενος Καμβύσῃ ἐλθεῖν ἐς λόγους. οἷα δὲ ἐόντα αὐτὸν ἐν τοῖσι ἐπικούροισι λόγου οὐ σμικροῦ ἐπιστάμενόν τε τὰ περὶ Αἴγυπτον ἀτρεκέστατα, μεταδιώκει ὁ Ἄμασις σπουδὴν ποιεύμενος ἑλεῖν, μεταδιώκει δὲ τῶν εὐνούχων τὸν πιστότατον ἀποστείλας τριήρεϊ κατ’ αὐτόν, ὃς αἱρέει μιν ἐν Λυκίῃ, ἑλὼν δὲ οὐκ ἀνήγαγε ἐς Αἴγυπτον· σοφίῃ γάρ μιν περιῆλθε ὁ Φάνης· καταμεθύσας γὰρ τοὺς φυλάκους ἀπαλλάσσετο ἐς Πέρσας. ὁρμημένῳ δὲ στρατεύεσθαι Καμβύσῃ ἐπ’ Αἴγυπτον καὶ ἀπορέοντι τὴν ἔλασιν, ὅκως τὴν ἄνυδρον διεκπερᾷ, ἐπελθὼν φράζει μὲν καὶ τὰ ἄλλα τὰ Ἀμάσιος πρήγματα, ἐξηγέεται δὲ καὶ τὴν ἔλασιν, ὧδε παραινέων, πέμψαντα παρὰ τὸν Ἀραβίων βασιλέα δέεσθαι τὴν διέξοδόν οἱ ἀσφαλέα παρασχεῖν.", "st": "3.4"}, {"sp": "N", "t": "μούνῃ δὲ ταύτῃ εἰσὶ φανεραὶ ἐσβολαὶ ἐς Αἴγυπτον. ἀπὸ γὰρ Φοινίκης μέχρι οὔρων τῶν Καδύτιος πόλιος ἐστὶ Σύρων τῶν Παλαιστίνων καλεομένων· ἀπὸ δὲ Καδύτιος ἐούσης πόλιος, ὡς ἐμοὶ δοκέει, Σαρδίων οὐ πολλῷ ἐλάσσονος, ἀπὸ ταύτης τὰ ἐμπόρια τὰ ἐπὶ θαλάσσης μέχρι Ἰηνύσου πόλιος ἐστὶ τοῦ Ἀραβίου, ἀπὸ δὲ Ἰηνύσου αὖτις Σύρων μέχρι Σερβωνίδος λίμνης, παρ’ ἣν δὴ τὸ Κάσιον ὄρος τείνει ἐς θάλασσαν· ἀπὸ δὲ Σερβωνίδος λίμνης, ἐν τῇ δὴ λόγος τὸν Τυφῶ κεκρύφθαι, ἀπὸ ταύτης ἤδη Αἴγυπτος. τὸ δὴ μεταξὺ Ἰηνύσου πόλιος καὶ Κασίου τε ὄρεος καὶ τῆς Σερβωνίδος λίμνης, ἐὸν τοῦτο οὐκ ὀλίγον χωρίον ἀλλὰ ὅσον τε ἐπὶ τρεῖς ἡμέρας ὁδόν, ἄνυδρον ἐστὶ δεινῶς.", "st": "3.5"}, {"sp": "N", "t": "τὸ δὲ ὀλίγοι τῶν ἐς Αἴγυπτον ναυτιλλομένων ἐννενώκασι, τοῦτο ἔρχομαι φράσων. ἐς Αἴγυπτον ἐκ τῆς Ἑλλάδος πάσης καὶ πρὸς ἐκ Φοινίκης κέραμος ἐσάγεται πλήρης οἴνου δὶς τοῦ ἔτεος ἑκάστου, καὶ ἓν κεράμιον οἰνηρὸν ἀριθμῷ κεινὸν οὐκ ἔστι ὡς λόγῳ εἰπεῖν ἰδέσθαι. κοῦ δῆτα, εἴποι τις ἄν, ταῦτα ἀναισιμοῦται; ἐγὼ καὶ τοῦτο φράσω· δεῖ τὸν μὲν δήμαρχον ἕκαστον ἐκ τῆς ἑωυτοῦ πόλιος συλλέξαντα πάντα τὸν κέραμον ἄγειν ἐς Μέμφιν, τοὺς δὲ ἐκ Μέμφιος ἐς ταῦτα δὴ τὰ ἄνυδρα τῆς Συρίης κομίζειν πλήσαντας ὕδατος. οὕτω ὁ ἐπιφοιτέων κέραμος καὶ ἐξαιρεόμενος ἐν Αἰγύπτῳ ἐπὶ τὸν παλαιὸν κομίζεται ἐς Συρίην.", "st": "3.6"}, {"sp": "N", "t": "οὕτω μέν νυν Πέρσαι εἰσὶ οἱ τὴν ἐσβολὴν ταύτην παρασκευάσαντες ἐς Αἴγυπτον, κατὰ δὴ τὰ εἰρημένα σάξαντες ὕδατι, ἐπείτε τάχιστα παρέλαβον Αἴγυπτον. τότε δὲ οὐκ ἐόντος κω ὕδατος ἑτοίμου, Καμβύσης πυθόμενος τοῦ Ἁλικαρνησσέος ξείνου, πέμψας παρὰ τὸν Ἀράβιον ἀγγέλους καὶ δεηθεὶς τῆς ἀσφαλείης ἔτυχε, πίστις δούς τε καὶ δεξάμενος παρ’ αὐτοῦ.", "st": "3.7"}, {"sp": "N", "t": "σέβονται δὲ Ἀράβιοι πίστις ἀνθρώπων ὅμοια τοῖσι μάλιστα, ποιεῦνται δὲ αὐτὰς τρόπῳ τοιῷδε· τῶν βουλομένων τὰ πιστὰ ποιέεσθαι ἄλλος ἀνήρ, ἀμφοτέρων αὐτῶν ἐν μέσῳ ἑστεώς, λίθῳ ὀξέι τὸ ἔσω τῶν χειρῶν παρὰ τοὺς δακτύλους τοὺς μεγάλους ἐπιτάμνει τῶν ποιευμένων τὰς πίστις, καὶ ἔπειτα λαβὼν ἐκ τοῦ ἱματίου ἑκατέρου κροκύδα ἀλείφει τῷ αἵματι ἐν μέσῳ κειμένους λίθους ἑπτά· τοῦτο δὲ ποιέων ἐπικαλέει τε τὸν Διόνυσον καὶ τὴν Οὐρανίην. ἐπιτελέσαντος δὲ τούτου ταῦτα, ὁ τὰς πίστις ποιησάμενος τοῖσι φίλοισι παρεγγυᾷ τὸν ξεῖνον ἢ καὶ τὸν ἀστόν, ἢν πρὸς ἀστὸν ποιέηται· οἱ δὲ φίλοι καὶ αὐτοὶ τὰς πίστις δικαιεῦσι σέβεσθαι. Διόνυσον δὲ θεῶν μοῦνον καὶ τὴν Οὐρανίην ἡγέονται εἶναι, καὶ τῶν τριχῶν τὴν κουρὴν κείρεσθαι φασὶ κατά περ αὐτὸν τὸν Διόνυσον κεκάρθαι· κείρονται δὲ περιτρόχαλα, ὑποξυρῶντες τοὺς κροτάφους. ὀνομάζουσι δὲ τὸν μὲν Διόνυσον Ὀροτάλτ, τὴν δὲ Οὐρανίην Ἀλιλάτ.", "st": "3.8"}, {"sp": "N", "t": "ἐπεὶ ὦν τὴν πίστιν τοῖσι ἀγγέλοισι τοῖσι παρὰ Καμβύσεω ἀπιγμένοισι ἐποιήσατο ὁ Ἀράβιος, ἐμηχανᾶτο τοιάδε· ἀσκοὺς καμήλων πλήσας, ὕδατος ἐπέσαξε ἐπὶ τὰς ζωὰς τῶν καμήλων πάσας, τοῦτο δὲ ποιήσας ἤλασε ἐς τὴν ἄνυδρον καὶ ὑπέμενε ἐνθαῦτα τὸν Καμβύσεω στρατόν. οὗτος μὲν ὁ πιθανώτερος τῶν λόγων εἴρηται, δεῖ δὲ καὶ τὸν ἧσσον πιθανόν, ἐπεί γε δὴ λέγεται, ῥηθῆναι. ποταμός ἐστι μέγας ἐν τῇ Ἀραβίῃ τῷ οὔνομα Κόρυς, ἐκδιδοῖ δὲ οὗτος ἐς τὴν Ἐρυθρὴν καλεομένην θάλασσαν· ἀπὸ τούτου δὴ ὦν τοῦ ποταμοῦ λέγεται τὸν βασιλέα τῶν Ἀραβίων, ῥαψάμενον τῶν ὠμοβοέων καὶ τῶν ἄλλων δερμάτων ὀχετὸν μήκεϊ ἐξικνεύμενον ἐς τὴν ἄνυδρον, ἀγαγεῖν διὰ δὴ τούτων τὸ ὕδωρ, ἐν δὲ τῇ ἀνύδρῳ μεγάλας δεξαμενὰς ὀρύξασθαι, ἵνα δεκόμεναι τὸ ὕδωρ σώζωσι. ὁδὸς δ’ ἐστὶ δυώδεκα ἡμερέων ἀπὸ τοῦ ποταμοῦ ἐς ταύτην τὴν ἄνυδρον. ἄγειν δέ μιν δι’ ὀχετῶν τριῶν ἐς τριξὰ χωρία.", "st": "3.9"}, {"sp": "N", "t": "ἐν δὲ τῷ Πηλουσίῳ καλεομένῳ στόματι τοῦ Νείλου ἐστρατοπεδεύετο Ψαμμήνιτος ὁ Ἀμάσιος παῖς ὑπομένων Καμβύσεα. Ἄμασιν γὰρ οὐ κατέλαβε ζῶντα Καμβύσης ἐλάσας ἐπ’ Αἴγυπτον, ἀλλὰ βασιλεύσας ὁ Ἄμασις τέσσερα καὶ τεσσεράκοντα ἔτεα ἀπέθανε, ἐν τοῖσι οὐδέν οἱ μέγα ἀνάρσιον πρῆγμα συνηνείχθη· ἀποθανὼν δὲ καὶ ταριχευθεὶς ἐτάφη ἐν τῇσι ταφῇσι ἐν τῷ ἱρῷ, τὰς αὐτὸς οἰκοδομήσατο. ἐπὶ Ψαμμηνίτου δὲ τοῦ Ἀμάσιος βασιλεύοντος Αἰγύπτου φάσμα Αἰγυπτίοισι μέγιστον δὴ ἐγένετο· ὕσθησαν γὰρ Θῆβαι αἱ Αἰγύπτιαι, οὔτε πρότερον οὐδαμὰ ὑσθεῖσαι οὔτε ὕστερον τὸ μέχρι ἐμεῦ, ὡς λέγουσι αὐτοὶ Θηβαῖοι· οὐ γὰρ δὴ ὕεται τὰ ἄνω τῆς Αἰγύπτου τὸ παράπαν· ἀλλὰ καὶ τότε ὕσθησαν αἱ Θῆβαι ψακάδι.", "st": "3.10"}, {"sp": "N", "t": "οἱ δὲ Πέρσαι ἐπείτε διεξελάσαντες τὴν ἄνυδρον ἵζοντο πέλας τῶν Αἰγυπτίων ὡς συμβαλέοντες, ἐνθαῦτα οἱ ἐπίκουροι οἱ τοῦ Αἰγυπτίου, ἐόντες ἄνδρες Ἕλληνές τε καὶ Κᾶρες, μεμφόμενοι τῷ Φάνῃ ὅτι στρατὸν ἤγαγε ἐπ’ Αἴγυπτον ἀλλόθροον, μηχανῶνται πρῆγμα ἐς αὐτὸν τοιόνδε. ἦσαν τῷ Φάνῃ παῖδες ἐν Αἰγύπτῳ καταλελειμμένοι· τοὺς ἀγαγόντες ἐς τὸ στρατόπεδον καὶ ἐς ὄψιν τοῦ πατρὸς κρητῆρα ἐν μέσῳ ἔστησαν ἀμφοτέρων τῶν στρατοπέδων, μετὰ δὲ ἀγινέοντες κατὰ ἕνα ἕκαστον τῶν παίδων ἔσφαζον ἐς τὸν κρητῆρα· διὰ πάντων δὲ διεξελθόντες τῶν παίδων οἶνόν τε καὶ ὕδωρ ἐσεφόρεον ἐς αὐτόν, ἐμπιόντες δὲ τοῦ αἵματος πάντες οἱ ἐπίκουροι οὕτω δὴ συνέβαλον. μάχης δὲ γενομένης καρτερῆς καὶ πεσόντων ἐξ ἀμφοτέρων τῶν στρατοπέδων πλήθεϊ πολλῶν ἐτράποντο οἱ Αἰγύπτιοι.", "st": "3.11"}, {"sp": "N", "t": "θῶμα δὲ μέγα εἶδον πυθόμενος παρὰ τῶν ἐπιχωρίων· τῶν γὰρ ὀστέων περικεχυμένων χωρὶς ἑκατέρων τῶν ἐν τῇ μάχῃ ταύτῃ πεσόντων (χωρὶς μὲν γὰρ τῶν Περσέων ἔκειτο τὰ ὀστέα, ὡς ἐχωρίσθη κατ’ ἀρχάς, ἑτέρωθι δὲ τῶν Αἰγυπτίων), αἱ μὲν τῶν Περσέων κεφαλαί εἰσι ἀσθενέες οὕτω ὥστε, εἰ θέλεις ψήφῳ μούνῃ βαλεῖν, διατετρανέεις, αἱ δὲ τῶν Αἰγυπτίων οὕτω δή τι ἰσχυραί, μόγις ἂν λίθῳ παίσας διαρρήξειας. αἴτιον δὲ τούτου τόδε ἔλεγον, καὶ ἐμέ γ’ εὐπετέως ἔπειθον, ὅτι Αἰγύπτιοι μὲν αὐτίκα ἀπὸ παιδίων ἀρξάμενοι ξυρῶνται τὰς κεφαλὰς καὶ πρὸς τὸν ἥλιον παχύνεται τὸ ὀστέον. τὠυτὸ δὲ τοῦτο καὶ τοῦ μὴ φαλακροῦσθαι αἴτιον ἐστί· Αἰγυπτίων γὰρ ἄν τις ἐλαχίστους ἴδοιτο φαλακροὺς πάντων ἀνθρώπων. τούτοισι μὲν δὴ τοῦτο ἐστὶ αἴτιον ἰσχυρὰς φορέειν τὰς κεφαλάς, τοῖσι δὲ Πέρσῃσι ὅτι ἀσθενέας φορέουσι τὰς κεφαλὰς αἴτιον τόδε· σκιητροφέουσι ἐξ ἀρχῆς πίλους τιάρας φορέοντες. ταῦτα μέν νυν τοιαῦτα· εἶδον δὲ καὶ ἄλλα ὅμοια τούτοισι ἐν Παπρήμι τῶν ἅμα Ἀχαιμένεϊ τῷ Δαρείου διαφθαρέντων ὑπὸ Ἰνάρω τοῦ Λίβυος.", "st": "3.12"}, {"sp": "N", "t": "οἱ δὲ Αἰγύπτιοι ἐκ τῆς μάχης ὡς ἐτράποντο, ἔφευγον οὐδενὶ κόσμῳ· κατειληθέντων δὲ ἐς Μέμφιν, ἔπεμπε ἀνὰ ποταμὸν Καμβύσης νέα Μυτιληναίην κήρυκα ἄγουσαν ἄνδρα Πέρσην, ἐς ὁμολογίην προκαλεόμενος Αἰγυπτίους. οἳ δὲ ἐπείτε τὴν νέα εἶδον ἐσελθοῦσαν ἐς τὴν Μέμφιν, ἐκχυθέντες ἁλέες ἐκ τοῦ τείχεος τήν τε νέα διέφθειραν καὶ τοὺς ἄνδρας κρεουργηδὸν διασπάσαντες ἐφόρεον ἐς τὸ τεῖχος. καὶ Αἰγύπτιοι μὲν μετὰ τοῦτο πολιορκεύμενοι χρόνῳ παρέστησαν, οἱ δὲ προσεχέες Λίβυες δείσαντες τὰ περὶ τὴν Αἴγυπτον γεγονότα παρέδοσαν σφέας αὐτοὺς ἀμαχητὶ καὶ φόρον τε ἐτάξαντο καὶ δῶρα ἔπεμπον. ὣς δὲ Κυρηναῖοι καὶ Βαρκαῖοι, δείσαντες ὁμοίως καὶ οἱ Λίβυες, τοιαῦτα ἐποίησαν. Καμβύσης δὲ τὰ μὲν παρὰ Λιβύων ἐλθόντα δῶρα φιλοφρόνως ἐδέξατο· τὰ δὲ παρὰ Κυρηναίων ἀπικόμενα μεμφθείς, ὡς ἐμοὶ δοκέει, ὅτι ἦν ὀλίγα· ἔπεμψαν γὰρ δὴ πεντακοσίας μνέας ἀργυρίου οἱ Κυρηναῖοι· ταύτας δρασσόμενος αὐτοχειρίῃ διέσπειρε τῇ στρατιῇ.", "st": "3.13"}, {"sp": "N", "t": "ἡμέρῃ δὲ δεκάτῃ ἀπ’ ἧς παρέλαβε τὸ τεῖχος τὸ ἐν Μέμφι Καμβύσης, κατίσας ἐς τὸ προάστειον ἐπὶ λύμῃ τὸν βασιλέα τῶν Αἰγυπτίων Ψαμμήνιτον, βασιλεύσαντα μῆνας ἕξ, τοῦτον κατίσας σὺν ἄλλοισι Αἰγυπτίοισι διεπειρᾶτο αὐτοῦ τῆς ψυχῆς ποιέων τοιάδε· στείλας αὐτοῦ τὴν θυγατέρα ἐσθῆτι δουληίῃ ἐξέπεμπε ἐπ’ ὕδωρ ἔχουσαν ὑδρήιον, συνέπεμπε δὲ καὶ ἄλλας παρθένους ἀπολέξας ἀνδρῶν τῶν πρώτων, ὁμοίως ἐσταλμένας τῇ τοῦ βασιλέος. ὡς δὲ βοῇ τε καὶ κλαυθμῷ παρήισαν αἱ παρθένοι παρὰ τοὺς πατέρας, οἱ μὲν ἄλλοι πάντες ἀντεβόων τε καὶ ἀντέκλαιον ὁρῶντες τὰ τέκνα κεκακωμένα, ὁ δὲ Ψαμμήνιτος προϊδὼν καὶ μαθὼν ἔκυψε ἐς τὴν γῆν. παρελθουσέων δὲ τῶν ὑδροφόρων, δεύτερά οἱ τὸν παῖδα ἔπεμπε μετ’ ἄλλων Αἰγυπτίων δισχιλίων τὴν αὐτὴν ἡλικίην ἐχόντων, τούς τε αὐχένας κάλῳ δεδεμένους καὶ τὰ στόματα ἐγκεχαλινωμένους· ἤγοντο δὲ ποινὴν τίσοντες Μυτιληναίων τοῖσι ἐν Μέμφι ἀπολομένοισι σὺν τῇ νηί. ταῦτα γὰρ ἐδίκασαν οἱ βασιλήιοι δικασταί, ὑπὲρ ἀνδρὸς ἑκάστου δέκα Αἰγυπτίων τῶν πρώτων ἀνταπόλλυσθαι. ὁ δὲ ἰδὼν παρεξιόντας καὶ μαθὼν τὸν παῖδα ἡγεόμενον ἐπὶ θάνατον, τῶν ἄλλων Αἰγυπτίων τῶν περικατημένων αὐτὸν κλαιόντων καὶ δεινὰ ποιεύντων, τὠυτὸ ἐποίησε τὸ καὶ ἐπὶ τῇ θυγατρί. παρελθόντων δὲ καὶ τούτων, συνήνεικε ὥστε τῶν συμποτέων οἱ ἄνδρα ἀπηλικέστερον, ἐκπεπτωκότα ἐκ τῶν ἐόντων ἔχοντά τε οὐδὲν εἰ μὴ ὅσα πτωχὸς καὶ προσαιτέοντα τὴν στρατιήν, παριέναι Ψαμμήνιτόν τε τὸν Ἀμάσιος καὶ τοὺς ἐν τῷ προαστείῳ κατημένους Αἰγυπτίων. ὁ δὲ Ψαμμήνιτος ὡς εἶδε, ἀνακλαύσας μέγα καὶ καλέσας ὀνομαστὶ τὸν ἑταῖρον ἐπλήξατο τὴν κεφαλήν. ἦσαν δ’ ἄρα αὐτοῦ φύλακοι, οἳ τὸ ποιεύμενον πᾶν ἐξ ἐκείνου ἐπ’ ἑκάστῃ ἐξόδῳ Καμβύσῃ ἐσήμαινον. θωμάσας δὲ ὁ Καμβύσης τὰ ποιεύμενα, πέμψας ἄγγελον εἰρώτα αὐτὸν λέγων τάδε. δεσπότης σε Καμβύσης, Ψαμμήνιτε, εἰρωτᾷ δι’ ὅ τι δὴ τὴν μὲν θυγατέρα ὁρέων κεκακωμένην καὶ τὸν παῖδα ἐπὶ θάνατον στείχοντα οὔτε ἀνέβωσας οὔτε ἀπέκλαυσας, τὸν δὲ πτωχὸν οὐδὲν σοὶ προσήκοντα, ὡς ἄλλων πυνθάνεται, ἐτίμησας. ὃ μὲν δὴ ταῦτα ἐπειρώτα, ὃ δ’ ἀμείβετο τοῖσιδε. ὦ παῖ Κύρου, τὰ μὲν οἰκήια ἦν μέζω κακὰ ἢ ὥστε ἀνακλαίειν, τὸ δὲ τοῦ ἑταίρου πένθος ἄξιον ἦν δακρύων, ὃς ἐκ πολλῶν τε καὶ εὐδαιμόνων ἐκπεσὼν ἐς πτωχηίην ἀπῖκται ἐπὶ γήραος οὐδῷ. καὶ ταῦτα ὡς ἀπενειχθέντα ὑπὸ τούτου εὖ δοκέειν σφι εἰρῆσθαι, ὡς [δὲ] λέγεται ὑπ’ Αἰγυπτίων, δακρύειν μὲν Κροῖσον (ἐτετεύχεε γὰρ καὶ οὗτος ἐπισπόμενος Καμβύσῃ ἐπ’ Αἴγυπτους), δακρύειν δὲ Περσέων τοὺς παρεόντας· αὐτῷ τε Καμβύσῃ ἐσελθεῖν οἶκτον τινά, καὶ αὐτίκα κελεύειν τόν τέ οἱ παῖδα ἐκ τῶν ἀπολλυμένων σώζειν καὶ αὐτὸν ἐκ τοῦ προαστείου ἀναστήσαντας ἄγειν παρ’ ἑωυτόν.", "st": "3.14"}, {"sp": "N", "t": "τὸν μὲν δὴ παῖδα εὗρον αὐτοῦ οἱ μετιόντες οὐκέτι περιεόντα ἀλλὰ πρῶτον κατακοπέντα, αὐτὸν δὲ Ψαμμήνιτον ἀναστήσαντες ἦγον παρὰ Καμβύσεα· ἔνθα τοῦ λοιποῦ διαιτᾶτο ἔχων οὐδὲν βίαιον. εἰ δὲ καὶ ἠπιστήθη μὴ πολυπρηγμονέειν, ἀπέλαβε ἂν Αἴγυπτον ὥστε ἐπιτροπεύειν αὐτῆς, ἐπεὶ τιμᾶν ἐώθασι Πέρσαι τῶν βασιλέων τοὺς παῖδας· τῶν, εἰ καὶ σφέων ἀποστέωσι, ὅμως τοῖσί γε παισὶ αὐτῶν ἀποδιδοῦσι τὴν ἀρχήν. πολλοῖσι μέν νυν καὶ ἄλλοισι ἐστὶ σταθμώσασθαι ὅτι τοῦτο οὕτω νενομίκασι ποιέειν, ἐν δὲ καὶ τῷ τε Ἰνάρω παιδὶ Θαννύρᾳ, ὃς ἀπέλαβε τήν οἱ ὁ πατὴρ εἶχε ἀρχήν, καὶ τῷ Ἀμυρταίου Παυσίρι· καὶ γὰρ οὗτος ἀπέλαβε τὴν τοῦ πατρὸς ἀρχήν. καίτοι Ἰνάρω γε καὶ Ἀμυρταίου οὐδαμοί κω Πέρσας κακὰ πλέω ἐργάσαντο. νῦν δὲ μηχανώμενος κακὰ ὁ Ψαμμήνιτος ἔλαβε τὸν μισθόν· ἀπιστὰς γὰρ Αἰγυπτίους ἥλω· ἐπείτε δὲ ἐπάιστος ἐγένετο ὑπὸ Καμβύσεω, αἷμα ταύρου πιὼν ἀπέθανε παραχρῆμα. οὕτω δὴ οὗτος ἐτελεύτησε.", "st": "3.15"}, {"sp": "N", "t": "Καμβύσης δὲ ἐκ Μέμφιος ἀπίκετο ἐς Σάιν πόλιν, βουλόμενος ποιῆσαι τὰ δὴ καὶ ἐποίησε. ἐπείτε γὰρ ἐσῆλθε ἐς τὰ τοῦ Ἀμάσιος οἰκία, αὐτίκα ἐκέλευε ἐκ τῆς ταφῆς τὸν Ἀμάσιος νέκυν ἐκφέρειν ἔξω· ὡς δὲ ταῦτα ἐπιτελέα ἐγένετο, μαστιγοῦν ἐκέλευε καὶ τὰς τρίχας ἀποτίλλειν καὶ κεντοῦν τε καὶ τἆλλα πάντα λυμαίνεσθαι. ἐπείτε δὲ καὶ ταῦτα ἔκαμον ποιεῦντες (ὁ γὰρ δὴ νεκρὸς ἅτε τεταριχευμένος ἀντεῖχέ τε καὶ οὐδὲν διεχέετο), ἐκέλευσέ μιν ὁ Καμβύσης κατακαῦσαι, ἐντελλόμενος οὐκ ὅσια· Πέρσαι γὰρ θεὸν νομίζουσι εἶναι πῦρ. τὸ ὦν κατακαίειν γε τοὺς νεκροὺς οὐδαμῶς ἐν νόμῳ οὐδετέροισι ἐστί, Πέρσῃσι μὲν δι’ ὅ περ εἴρηται, θεῷ οὐ δίκαιον εἶναι λέγοντες νέμειν νεκρὸν ἀνθρώπου· Αἰγυπτίοισι δὲ νενόμισται πῦρ θηρίον εἶναι ἔμψυχον, πάντα δὲ αὐτὸ κατεσθίειν τά περ ἂν λάβῃ, πλησθὲν δὲ αὐτὸ τῆς βορῆς συναποθνήσκειν τῷ κατεσθιομένῳ. οὔκων θηρίοισι νόμος οὐδαμῶς σφι ἐστὶ τὸν νέκυν διδόναι, καὶ διὰ ταῦτα ταριχεύουσι, ἵνα μὴ κείμενος ὑπὸ εὐλέων καταβρωθῇ. οὕτω οὐδετέροισι νομιζόμενα ἐνετέλλετο ποιέειν ὁ Καμβύσης. ὡς μέντοι, Αἰγύπτιοι λέγουσι, οὐκ Ἄμασις ἦν ὁ ταῦτα παθών, ἀλλὰ ἄλλος τις τῶν Αἰγυπτίων ἔχων τὴν αὐτὴν ἡλικίην Ἀμάσι, τῷ λυμαινόμενοι Πέρσαι ἐδόκεον Ἀμάσι λυμαίνεσθαι. λέγουσι γὰρ ὡς πυθόμενος ἐκ μαντηίου ὁ Ἄμασις τὰ περὶ ἑωυτὸν ἀποθανόντα μέλλοντα γίνεσθαι, οὕτω δὴ ἀκεόμενος τὰ ἐπιφερόμενα τὸν μὲν ἄνθρωπον τοῦτον τὸν μαστιγωθέντα ἀποθανόντα ἔθαψε ἐπὶ τῇσι θύρῃσι ἐντὸς τῆς ἑωυτοῦ θήκης, ἑωυτὸν δὲ ἐνετείλατο τῷ παιδὶ ἐν μυχῷ τῆς θήκης ὡς μάλιστα θεῖναι. αἱ μέν νυν ἐκ τοῦ Ἀμάσιος ἐντολαὶ αὗται αἱ ἐς τὴν ταφήν τε καὶ τὸν ἄνθρωπον ἔχουσαι οὔ μοι δοκέουσι ἀρχὴν γενέσθαι, ἄλλως δ’ αὐτὰ Αἰγύπτιοι σεμνοῦν.", "st": "3.16"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα ὁ Καμβύσης ἐβουλεύσατο τριφασίας στρατηίας, ἐπί τε Καρχηδονίους καὶ ἐπὶ Ἀμμωνίους καὶ ἐπὶ τοὺς μακροβίους Αἰθίοπας, οἰκημένους δὲ Λιβύης ἐπὶ τῇ νοτίῃ θαλάσσῃ· βουλευομένῳ δέ οἱ ἔδοξε ἐπὶ μὲν Καρχηδονίους τὸν ναυτικὸν στρατὸν ἀποστέλλειν, ἐπὶ δὲ Ἀμμωνίους τοῦ πεζοῦ ἀποκρίναντα, ἐπὶ δὲ τοὺς Αἰθίοπας κατόπτας πρῶτον, ὀψομένους τε τὴν ἐν τούτοισι τοῖσι Αἰθίοψι λεγομένην εἶναι ἡλίου τράπεζαν εἰ ἔστι ἀληθέως, καὶ πρὸς ταύτῃ τὰ ἄλλα κατοψομένους, δῶρα δὲ τῷ λόγῳ φέροντας τῷ βασιλέι αὐτῶν.", "st": "3.17"}, {"sp": "N", "t": "ἡ δὲ τράπεζα τοῦ ἡλίου τοιήδε τις λέγεται εἶναι, λειμὼν ἐστὶ ἐν τῷ προαστείῳ ἐπίπλεος κρεῶν ἑφθῶν πάντων τῶν τετραπόδων, ἐς τὸν τὰς μὲν νύκτας ἐπιτηδεύοντας τιθέναι τὰ κρέα τοὺς ἐν τέλεϊ ἑκάστοτε ἐόντας τῶν ἀστῶν, τὰς δὲ ἡμέρας δαίνυσθαι προσιόντα τὸν βουλόμενον. φάναι δὲ τοὺς ἐπιχωρίους ταῦτα τὴν γῆν αὐτὴν ἀναδιδόναι ἑκάστοτε.", "st": "3.18"}, {"sp": "N", "t": "ἡ μὲν δὴ τράπεζα τοῦ ἡλίου καλεομένη λέγεται εἶναι τοιήδε. Καμβύσῃ δὲ ὡς ἔδοξε πέμπειν τοὺς κατασκόπους, αὐτίκα μετεπέμπετο ἐξ Ἐλεφαντίνης πόλιος τῶν Ἰχθυοφάγων ἀνδρῶν τοὺς ἐπισταμένους τὴν Αἰθιοπίδα γλῶσσαν. ἐν ᾧ δὲ τούτους μετήισαν, ἐν τούτῳ ἐκέλευε ἐπὶ τὴν Καρχηδόνα πλέειν τὸν ναυτικὸν στρατόν. Φοίνικες δὲ οὐκ ἔφασαν ποιήσειν ταῦτα· ὁρκίοισι γὰρ μεγάλοισι ἐνδεδέσθαι, καὶ οὐκ ἂν ποιέειν ὅσια ἐπὶ τοὺς παῖδας τοὺς ἑωυτῶν στρατευόμενοι. Φοινίκων δὲ οὐ βουλομένων οἱ λοιποὶ οὐκ ἀξιόμαχοι ἐγίνοντο. Καρχηδόνιοι μέν νυν οὕτω δουλοσύνην διέφυγον πρὸς Περσέων· Καμβύσης γὰρ βίην οὐκ ἐδικαίου προσφέρειν Φοίνιξι, ὅτι σφέας τε αὐτοὺς ἐδεδώκεσαν Πέρσῃσι καὶ πᾶς ἐκ Φοινίκων ἤρτητο ὁ ναυτικὸς στρατός. δόντες δὲ καὶ Κύπριοι σφέας αὐτοὺς Πέρσῃσι ἐστρατεύοντο ἐπ’ Αἴγυπτον.", "st": "3.19"}, {"sp": "N", "t": "ἐπείτε δὲ τῷ Καμβύσῃ ἐκ τῆς Ἐλεφαντίνης ἀπίκοντο οἱ Ἰχθυοφάγοι, ἔπεμπε αὐτοὺς ἐς τοὺς Αἰθίοπας ἐντειλάμενος τὰ λέγειν χρῆν καὶ δῶρα φέροντας πορφύρεόν τε εἷμα καὶ χρύσεον στρεπτὸν περιαυχένιον καὶ ψέλια καὶ μύρου ἀλάβαστρον καὶ φοινικηίου οἴνου κάδον. οἱ δὲ Αἰθίοπες οὗτοι, ἐς τοὺς ἀπέπεμπε ὁ Καμβύσης, λέγονται εἶναι μέγιστοι καὶ κάλλιστοι ἀνθρώπων πάντων. νόμοισι δὲ καὶ ἄλλοισι χρᾶσθαι αὐτοὺς κεχωρισμένοισι τῶν ἄλλων ἀνθρώπων καὶ δὴ καὶ κατὰ τὴν βασιληίην τοιῷδε· τὸν ἂν τῶν ἀστῶν κρίνωσι μέγιστόν τε εἶναι καὶ κατὰ τὸ μέγαθος ἔχειν τὴν ἰσχύν, τοῦτον ἀξιοῦσι βασιλεύειν.", "st": "3.20"}, {"sp": "N", "t": "ἐς τούτους δὴ ὦν τοὺς ἄνδρας ὡς ἀπίκοντο οἱ Ἰχθυοφάγοι, διδόντες τὰ δῶρα τῷ, βασιλέι αὐτῶν ἔλεγον τάδε. βασιλεὺς ὁ Περσέων Καμβύσης, βουλόμενος φίλος καὶ ξεῖνός τοι γενέσθαι, ἡμέας τε ἀπέπεμψε ἐς λόγους τοι ἐλθεῖν κελεύων, καὶ δῶρα ταῦτά τοι διδοῖ τοῖσι καὶ αὐτὸς μάλιστα ἥδεται χρεώμενος. ὁ δὲ Αἰθίοψ μαθὼν ὅτι κατόπται ἥκοιεν, λέγει πρὸς αὐτοὺς τοιάδε. οὔτε ὁ Περσέων βασιλεὺς δῶρα ὑμέας ἔπεμψε φέροντας προτιμῶν πολλοῦ ἐμοὶ ξεῖνος γενέσθαι, οὔτε ὑμεῖς λέγετε ἀληθέα (ἥκετε γὰρ κατόπται τῆς ἐμῆς ἀρχῆς), οὔτε ἐκεῖνος ἀνήρ δίκαιος. εἰ γὰρ ἦν δίκαιος, οὔτ’ ἂν ἐπεθύμησε χώρης ἄλλης ἢ τῆς ἑωυτοῦ, οὔτ’ ἂν ἐς δουλοσύνην ἀνθρώπους ἦγε ὑπ’ ὧν μηδὲν ἠδίκηται. νῦν δὲ αὐτῷ τόξον τόδε διδόντες τάδε ἔπεα λέγετε. βασιλεὺς ὁ Αἰθιόπων συμβουλεύει τῷ Περσέων βασιλέι, ἐπεὰν οὕτω εὐπετέως ἕλκωσι τὰ τόξα Πέρσαι ἐόντα μεγάθεϊ τοσαῦτα, τότε ἐπ’ Αἰθίοπας τοὺς μακροβίους πλήθεϊ ὑπερβαλλόμενον στρατεύεσθαι· μέχρι δὲ τούτου θεοῖσι εἰδέναι χάριν, οἳ οὐκ ἐπὶ νόον τρέπουσι Αἰθιόπων παισὶ γῆν ἄλλην προσκτᾶσθαι τῇ ἑωυτῶν.", "st": "3.21"}, {"sp": "N", "t": "ταῦτα δὲ εἴπας καὶ ἀνεὶς τὸ τόξον παρέδωκε τοῖσι ἥκουσι. λαβὼν δὲ τὸ εἷμα τὸ πορφύρεον εἰρώτα ὅ τι εἴη καὶ ὅκως πεποιημένον· εἰπόντων δὲ τῶν Ἰχθυοφάγων τὴν ἀληθείην περὶ τῆς πορφύρης καὶ τῆς βαφῆς, δολεροὺς μὲν τοὺς ἀνθρώπους ἔφη εἶναι, δολερὰ δὲ αὐτῶν τὰ εἵματα. δεύτερα δὲ τὸν χρυσὸν εἰρώτα τὸν στρεπτὸν τὸν περιαυχένιον καὶ τὰ ψέλια· ἐξηγεομένων δὲ τῶν Ἰχθυοφάγων τὸν κόσμον αὐτοῦ, γελάσας ὁ βασιλεὺς καὶ νομίσας εἶναι σφέα πέδας εἶπε ὡς παρ’ ἑωυτοῖσι εἰσὶ ῥωμαλεώτεραι τουτέων πέδαι. τρίτον δὲ εἰρώτα τὸ μύρον· εἰπόντων δὲ τῆς ποιήσιος πέρι καὶ ἀλείψιος, τὸν αὐτὸν λόγον τὸν καὶ περὶ τοῦ εἵματος εἶπε. ὡς δὲ ἐς τὸν οἶνον ἀπίκετο καὶ ἐπύθετο αὐτοῦ τὴν ποίησιν, ὑπερησθεὶς τῷ πόματι ἐπείρετο ὅ τι τε σιτέεται ὁ βασιλεὺς καὶ χρόνον ὁκόσον μακρότατον ἀνὴρ Πέρσης ζώει. οἳ δὲ σιτέεσθαι μὲν τὸν ἄρτον εἶπον, ἐξηγησάμενοι τῶν πυρῶν τὴν φύσιν, ὀγδώκοντα δὲ ἔτεα ζόης πλήρωμα ἀνδρὶ μακρότατον προκεῖσθαι. πρὸς ταῦτα ὁ Αἰθίοψ ἔφη οὐδὲν θωμάζειν εἰ σιτεόμενοι κόπρον ἔτεα ὀλίγα ζώουσι· οὐδὲ γὰρ ἂν τοσαῦτα δύνασθαι ζώειν σφέας, εἰ μὴ τῷ πόματι ἀνέφερον, φράζων τοῖσι Ἰχθυοφάγοισι τὸν οἶνον· τούτῳ γὰρ ἑωυτοὺς ὑπὸ Περσέων ἑσσοῦσθαι.", "st": "3.22"}, {"sp": "N", "t": "ἀντειρομένων δὲ τὸν βασιλέα τῶν Ἰχθυοφάγων τῆς ζόης καὶ διαίτης πέρι, ἔτεα μὲν ἐς εἴκοσι καὶ ἑκατὸν τοὺς πολλοὺς αὐτῶν ἀπικνέεσθαι, ὑπερβάλλειν δὲ τινὰς καὶ ταῦτα, σίτησιν δὲ εἶναι κρέα τε ἑφθὰ καὶ πόμα γάλα. θῶμα δὲ ποιευμένων τῶν κατασκόπων περὶ τῶν ἐτέων, ἐπὶ κρήνην σφι ἡγήσασθαι, ἀπ’ ἧς λουόμενοι λιπαρώτεροι ἐγίνοντο, κατά περ εἰ ἐλαίου εἴη· ὄζειν δὲ ἀπ’ αὐτῆς ὡς εἰ ἴων. ἀσθενὲς δὲ τὸ ὕδωρ τῆς κρήνης ταύτης οὕτω δή τι ἔλεγον εἶναι οἱ κατάσκοποι ὥστε μηδὲν οἷόν τ’ εἶναι ἐπ’ αὐτοῦ ἐπιπλέειν, μήτε ξύλον μήτε τῶν ὅσα ξύλου ἐστὶ ἐλαφρότερα, ἀλλὰ πάντα σφέα χωρέειν ἐς βυσσόν. τὸ δὲ ὕδωρ τοῦτο εἴ σφι ἐστὶ ἀληθέως οἷόν τι λέγεται, διὰ τοῦτο ἂν εἶεν, τούτῳ τὰ πάντα χρεώμενοι, μακρόβιοι. ἀπὸ τῆς κρήνης δὲ ἀπαλλασσομένων, ἀγαγεῖν σφεας ἐς δεσμωτήριον ἀνδρῶν, ἔνθα τοὺς πάντας ἐν πέδῃσι χρυσέῃσι δεδέσθαι. ἔστι δὲ ἐν τούτοισι τοῖσι Αἰθίοψι πάντων ὁ χαλκὸς σπανιώτατον καὶ τιμιώτατον. θεησάμενοι δὲ καὶ τὸ δεσμωτήριον, ἐθεήσαντο καὶ τὴν τοῦ ἡλίου λεγομένην τράπεζαν.", "st": "3.23"}, {"sp": "N", "t": "μετὰ δὲ ταύτην τελευταίας ἐθεήσαντο τὰς θήκας αὐτῶν, αἳ λέγονται σκευάζεσθαι ἐξ ὑέλου τρόπῳ τοιῷδε· ἐπεὰν τὸν νεκρὸν ἰσχνήνωσι, εἴτε δὴ κατά περ Αἰγύπτιοι εἴτε ἄλλως κως, γυψώσαντες ἅπαντα αὐτὸν γραφῇ κοσμέουσι, ἐξομοιεῦντες τὸ εἶδος ἐς τὸ δυνατόν, ἔπειτα δέ οἱ περιιστᾶσι στήλην ἐξ ὑέλου πεποιημένην κοίλην· ἣ δέ σφι πολλὴ καὶ εὐεργὸς ὀρύσσεται. ἐν μέσῃ δὲ τῇ στήλῃ ἐνεὼν διαφαίνεται ὁ νέκυς, οὔτε ὀδμὴν οὐδεμίαν ἄχαριν παρεχόμενος οὔτε ἄλλο ἀεικὲς οὐδέν, καὶ ἔχει πάντα φανερὰ ὁμοίως αὐτῷ τῷ νέκυϊ. ἐνιαυτὸν μὲν δὴ ἔχουσι τὴν στήλην ἐν τοῖσι οἰκίοισι οἱ μάλιστα προσήκοντες, πάντων ἀπαρχόμενοι καὶ θυσίας οἱ προσάγοντες· μετὰ δὲ ταῦτα ἐκκομίσαντες ἱστᾶσι περὶ τὴν πόλιν.", "st": "3.24"}, {"sp": "N", "t": "θεησάμενοι δὲ τὰ πάντα οἱ κατάσκοποι ἀπαλλάσσοντο ὀπίσω. ἀπαγγειλάντων δὲ ταῦτα τούτων, αὐτίκα ὁ Καμβύσης ὀργὴν ποιησάμενος ἐστρατεύετο ἐπὶ τοὺς Αἰθίοπας, οὔτε παρασκευὴν σίτου οὐδεμίαν παραγγείλας, οὔτε λόγον ἑωυτῷ δοὺς ὅτι ἐς τὰ ἔσχατα γῆς ἔμελλε στρατεύεσθαι· οἷα δὲ ἐμμανής τε ἐὼν καὶ οὐ φρενήρης, ὡς ἤκουε τῶν Ἰχθυοφάγων, ἐστρατεύετο, Ἑλλήνων μὲν τοὺς παρεόντας αὐτοῦ τάξας ὑπομένειν, τὸν δὲ πεζὸν πάντα ἅμα ἀγόμενος. ἐπείτε δὲ στρατευόμενος ἐγένετο ἐν Θήβῃσι, ἀπέκρινε τοῦ στρατοῦ ὡς πέντε μυριάδας, καὶ τούτοισι μὲν ἐνετέλλετο Ἀμμωνίους ἐξανδραποδισαμένους τὸ χρηστήριον τὸ τοῦ Διὸς ἐμπρῆσαι, αὐτὸς δὲ τὸν λοιπὸν ἄγων στρατὸν ἤιε ἐπὶ τοὺς Αἰθίοπας. πρὶν δὲ τῆς ὁδοῦ τὸ πέμπτον μέρος διεληλυθέναι τὴν στρατιήν, αὐτίκα πάντα αὐτοὺς τὰ εἶχον σιτίων ἐχόμενα ἐπελελοίπεε, μετὰ δὲ τὰ σιτία καὶ τὰ ὑποζύγια ἐπέλιπε κατεσθιόμενα. εἰ μέν νυν μαθὼν ταῦτα ὁ Καμβύσης ἐγνωσιμάχεε καὶ ἀπῆγε ὀπίσω τὸν στρατόν, ἐπὶ τῇ ἀρχῆθεν γενομένῃ ἁμαρτάδι ἦν ἂν ἀνὴρ σοφός· νῦν δὲ οὐδένα λόγον ποιεύμενος ἤιε αἰεὶ ἐς τὸ πρόσω. οἱ δὲ στρατιῶται ἕως μέν τι εἶχον ἐκ τῆς γῆς λαμβάνειν, ποιηφαγέοντες διέζωον, ἐπεὶ δὲ ἐς τὴν ψάμμον ἀπίκοντο, δεινὸν ἔργον αὐτῶν τινες ἐργάσαντο· ἐκ δεκάδος γὰρ ἕνα σφέων αὐτῶν ἀποκληρώσαντες κατέφαγον. πυθόμενος δὲ ταῦτα ὁ Καμβύσης, δείσας τὴν ἀλληλοφαγίην, ἀπεὶς τὸν ἐπ’ Αἰθίοπας στόλον ὀπίσω ἐπορεύετο καὶ ἀπικνέεται ἐς Θήβας πολλοὺς ἀπολέσας τοῦ στρατοῦ· ἐκ Θηβέων δὲ καταβὰς ἐς Μέμφιν τοὺς Ἕλληνας ἀπῆκε ἀποπλέειν.", "st": "3.25"}, {"sp": "N", "t": "ὁ μὲν ἐπ’ Αἰθίοπας στόλος οὕτω ἔπρηξε· οἱ δ’ αὐτῶν ἐπ’ Ἀμμωνίους ἀποσταλέντες στρατεύεσθαι, ἐπείτε ὁρμηθέντες ἐκ τῶν Θηβέων ἐπορεύοντο ἔχοντες ἀγωγούς, ἀπικόμενοι μὲν φανεροί εἰσι ἐς Ὄασιν πόλιν, τὴν ἔχουσι μὲν Σάμιοι τῆς Αἰσχριωνίης φυλῆς λεγόμενοι εἶναι, ἀπέχουσι δὲ ἑπτὰ ἡμερέων ὁδὸν ἀπὸ Θηβέων διὰ ψάμμου· ὀνομάζεται δὲ ὁ χῶρος οὗτος κατὰ Ἑλλήνων γλῶσσαν Μακάρων νῆσος. ἐς μὲν δὴ τοῦτον τὸν χῶρον λέγεται ἀπικέσθαι τὸν στρατόν, τὸ ἐνθεῦτεν δέ, ὅτι μὴ αὐτοὶ Ἀμμώνιοι καὶ οἱ τούτων ἀκούσαντες, ἄλλοι οὐδένες οὐδὲν ἔχουσι εἰπεῖν περὶ αὐτῶν· οὔτε γὰρ ἐς τοὺς Ἀμμωνίους ἀπίκοντο οὔτε ὀπίσω ἐνόστησαν. λέγεται δὲ κατὰ τάδε ὑπ’ αὐτῶν Ἀμμωνίων· ἐπειδὴ ἐκ τῆς Ὀάσιος ταύτης ἰέναι διὰ τῆς ψάμμου ἐπὶ σφέας, γενέσθαι τε αὐτοὺς μεταξύ κου μάλιστα αὐτῶν τε καὶ τῆς Ὀάσιος, ἄριστον αἱρεομένοισι αὐτοῖσι ἐπιπνεῦσαι νότον μέγαν τε καὶ ἐξαίσιον, φορέοντα δὲ θῖνας τῆς ψάμμου καταχῶσαι σφέας, καὶ τρόπῳ τοιούτῳ ἀφανισθῆναι. Ἀμμώνιοι μὲν οὕτω λέγουσι γενέσθαι περὶ τῆς στρατιῆς ταύτης.", "st": "3.26"}, {"sp": "N", "t": "ἀπιγμένου δὲ Καμβύσεω ἐς Μέμφιν ἐφάνη Αἰγυπτίοισι ὁ Ἆπις, τὸν Ἕλληνες Ἔπαφον καλέουσι· ἐπιφανέος δὲ τούτου γενομένου αὐτίκα οἱ Αἰγύπτιοι εἵματα ἐφόρεον τὰ κάλλιστα καὶ ἦσαν ἐν θαλίῃσι. ἰδὼν δὲ ταῦτα τοὺς Αἰγυπτίους ποιεῦντας ὁ Καμβύσης, πάγχυ σφέας καταδόξας ἑωυτοῦ κακῶς πρήξαντος χαρμόσυνα ταῦτα ποιέειν, ἐκάλεε τοὺς ἐπιτρόπους τῆς Μέμφιος, ἀπικομένους δὲ ἐς ὄψιν εἴρετο ὅ τι πρότερον μὲν ἐόντος αὐτοῦ ἐν Μέμφι ἐποίευν τοιοῦτον οὐδὲν Αἰγύπτιοι, τότε δὲ ἐπεὶ αὐτὸς παρείη τῆς στρατιῆς πλῆθός τι ἀποβαλών. οἳ δὲ ἔφραζον ὥς σφι θεὸς εἴη φανεὶς διὰ χρόνου πολλοῦ ἐωθὼς ἐπιφαίνεσθαι, καὶ ὡς ἐπεὰν φανῇ τότε πάντες Αἰγύπτιοι κεχαρηκότες ὁρτάζοιεν. ταῦτα ἀκούσας ὁ Καμβύσης ἔφη ψεύδεσθαι σφέας καὶ ὡς ψευδομένους θανάτῳ ἐζημίου.", "st": "3.27"}, {"sp": "N", "t": "ἀποκτείνας δὲ τούτους δεύτερα τοὺς ἱρέας ἐκάλεε ἐς ὄψιν· λεγόντων δὲ κατὰ ταὐτὰ τῶν ἱρέων, οὐ λήσειν ἔφη αὐτὸν εἰ θεός τις χειροήθης ἀπιγμένος εἴη Αἰγυπτίοισι. τοσαῦτα δὲ εἴπας ἀπάγειν ἐκέλευε τὸν Ἆπιν τοὺς ἱρέας. οἳ μὲν δὴ μετήισαν ἄξοντες. ὁ δὲ Ἆπις οὗτος ὁ Ἔπαφος γίνεται μόσχος ἐκ βοός, ἥτις οὐκέτι οἵη τε γίνεται ἐς γαστέρα ἄλλον βάλλεσθαι γόνον. Αἰγύπτιοι δὲ λέγουσι σέλας ἐπὶ τὴν βοῦν ἐκ τοῦ οὐρανοῦ κατίσχειν, καί μιν ἐκ τούτου τίκτειν τὸν Ἆπιν. ἔχει δὲ ὁ μόσχος οὗτος ὁ Ἆπις καλεόμενος σημήια τοιάδε ἐὼν μέλας, ἐπὶ μὲν τῷ μετώπῳ λευκόν τι τρίγωνον, ἐπὶ δὲ τοῦ νώτου αἰετὸν εἰκασμένον, ἐν δὲ τῇ οὐρῇ τὰς τρίχας διπλᾶς, ὑπὸ δὲ τῇ γλώσσῃ κάνθαρον.", "st": "3.28"}, {"sp": "N", "t": "ὡς δὲ ἤγαγον τὸν Ἆπιν οἱ ἱρέες, ὁ Καμβύσης, οἷα ἐὼν ὑπομαργότερος, σπασάμενος τὸ ἐγχειρίδιον, θέλων τύψαι τὴν γαστέρα τοῦ Ἄπιος παίει τὸν μηρόν· γελάσας δὲ εἶπε πρὸς τοὺς ἱρέας ὦ κακαὶ κεφαλαί, τοιοῦτοι θεοὶ γίνονται, ἔναιμοί τε καὶ σαρκώδεες καὶ ἐπαΐοντες σιδηρίων; ἄξιος μέν γε Αἰγυπτίων οὗτός γε ὁ θεός, ἀτάρ τοι ὑμεῖς γε οὐ χαίροντες γέλωτα ἐμὲ θήσεσθε. ταῦτα εἴπας ἐνετείλατο τοῖσι ταῦτα πρήσσουσι τοὺς μὲν ἱρέας ἀπομαστιγῶσαι, Αἰγυπτίων δὲ τῶν ἄλλων τὸν ἂν λάβωσι ὁρτάζοντα κτείνειν. ὁρτὴ μὲν δὴ διελέλυτο Αἰγυπτίοισι, οἱ δὲ ἱρέες ἐδικαιεῦντο, ὁ δὲ Ἆπις πεπληγμένος τὸν μηρὸν ἔφθινε ἐν τῷ ἱρῷ κατακείμενος. καὶ τὸν μὲν τελευτήσαντα ἐκ τοῦ τρώματος ἔθαψαν οἱ ἱρέες λάθρῃ Καμβύσεω.", "st": "3.29"}, {"sp": "N", "t": "Καμβύσης δέ, ὡς λέγουσι Αἰγύπτιοι, αὐτίκα διὰ τοῦτο τὸ ἀδίκημα ἐμάνη, ἐὼν οὐδὲ πρότερον φρενήρης. καὶ πρῶτα μὲν τῶν κακῶν ἐξεργάσατο τὸν ἀδελφεὸν Σμέρδιν ἐόντα πατρὸς καὶ μητρὸς τῆς αὐτῆς, τὸν ἀπέπεμψε ἐς Πέρσας φθόνῳ ἐξ Αἰγύπτου, ὅτι τὸ τόξον μοῦνος Περσέων ὅσον τε ἐπὶ δύο δακτύλους εἴρυσε, τὸ παρὰ τοῦ Αἰθίοπος ἤνεικαν οἱ Ἰχθυοφάγοι, τῶν δὲ ἄλλων Περσέων οὐδεὶς οἷός τε ἐγένετο. ἀποιχομένου ὦν ἐς Πέρσας τοῦ Σμέρδιος ὄψιν εἶδε ὁ Καμβύσης ἐν τῷ ὕπνῳ τοιήνδε· ἔδοξέ οἱ ἄγγελον ἐλθόντα ἐκ Περσέων ἀγγέλλειν ὡς ἐν τῷ θρόνῳ τῷ βασιληίῳ ἱζόμενος Σμέρδις τῇ κεφαλῇ τοῦ οὐρανοῦ ψαύσειε. πρὸς ὦν ταῦτα δείσας περὶ ἑωυτοῦ μή μιν ἀποκτείνας ὁ ἀδελφεὸς ἄρχῃ, πέμπει Πρηξάσπεα ἐς Πέρσας, ὃς ἦν οἱ ἀνὴρ Περσέων πιστότατος, ἀποκτενέοντά μιν. ὁ δὲ ἀναβὰς ἐς Σοῦσα ἀπέκτεινε Σμέρδιν, οἳ μὲν λέγουσι ἐπ’ ἄγρην ἐξαγαγόντα, οἳ δὲ ἐς τὴν Ἐρυθρὴν θάλασσαν προαγαγόντα καταποντῶσαι.", "st": "3.30"}, {"sp": "N", "t": "πρῶτον μὲν δὴ λέγουσι Καμβύσῃ τῶν κακῶν ἄρξαι τοῦτο· δεύτερα δὲ ἐξεργάσατο τὴν ἀδελφεὴν ἑσπομένην οἱ ἐς Αἴγυπτον, τῇ καὶ συνοίκεε καὶ ἦν οἱ ἀπ’ ἀμφοτέρων ἀδελφεή. ἔγημε δὲ αὐτὴν ὧδε· οὐδαμῶς γὰρ ἐώθεσαν πρότερον τῇσι ἀδελφεῇσι συνοικέειν Πέρσαι. ἠράσθη μιῆς τῶν ἀδελφεῶν Καμβύσης, καὶ ἔπειτα βουλόμενος αὐτὴν γῆμαι, ὅτι οὐκ ἐωθότα ἐπενόεε ποιήσειν, εἴρετο καλέσας τοὺς βασιληίους δικαστὰς εἴ τις ἐστὶ κελεύων νόμος τὸν βουλόμενον ἀδελφεῇ συνοικέειν. οἱ δὲ βασιλήιοι δικασταὶ κεκριμένοι ἄνδρες γίνονται Περσέων, ἐς οὗ ἀποθάνωσι ἤ σφι παρευρεθῇ τι ἄδικον, μέχρι τούτου· οὗτοι δὲ τοῖσι πέρσῃσι δίκας δικάζουσι καὶ ἐξηγηταὶ τῶν πατρίων θεσμῶν γίνονται, καὶ πάντα ἐς τούτους ἀνακέεται. εἰρομένου ὦν τοῦ Καμβύσεω, ὑπεκρίνοντο αὐτῷ οὗτοι καὶ δίκαια καὶ ἀσφαλέα, φάμενοι νόμον οὐδένα ἐξευρίσκειν ὃς κελεύει ἀδελφεῇ συνοικέειν ἀδελφεόν, ἄλλον μέντοι ἐξευρηκέναι νόμον, τῷ βασιλεύοντι Περσέων ἐξεῖναι ποιέειν τὸ ἂν βούληται. οὕτω οὔτε τὸν νόμον ἔλυσαν δείσαντες Καμβύσεα, ἵνα τε μὴ αὐτοὶ ἀπόλωνται τὸν νόμον περιστέλλοντες, παρεξεῦρον ἄλλον νόμον σύμμαχον τῷ θέλοντι γαμέειν ἀδελφεάς. τότε μὲν δὴ ὁ Καμβύσης ἔγημε τὴν ἐρωμένην, μετὰ μέντοι οὐ πολλὸν χρόνον ἔσχε ἄλλην ἀδελφεήν. τουτέων δῆτα τὴν νεωτέρην ἐπισπομένην οἱ ἐπ’ Αἴγυπτον κτείνει.", "st": "3.31"}, {"sp": "N", "t": "ἀμφὶ δὲ τῷ θανάτῳ αὐτῆς διξὸς ὥσπερ περὶ Σμέρδιος λέγεται λόγος. Ἕλληνες μὲν λέγουσι Καμβύσεα συμβαλεῖν σκύμνον λέοντος σκύλακι κυνός, θεωρέειν δὲ καὶ τὴν γυναῖκα ταύτην, νικωμένου δὲ τοῦ σκύλακος ἀδελφεὸν αὐτοῦ ἄλλον σκύλακα ἀπορρήξαντα τὸν δεσμὸν παραγενέσθαι οἱ, δύο δὲ γενομένους οὕτω δὴ τοὺς σκύλακας ἐπικρατῆσαι τοῦ σκύμνου. καὶ τὸν μὲν Καμβύσεα ἥδεσθαι θεώμενον, τὴν δὲ παρημένην δακρύειν. Καμβύσεα δὲ μαθόντα τοῦτο ἐπειρέσθαι δι’ ὅ τι δακρύει, τὴν δὲ εἰπεῖν ὡς ἰδοῦσα τὸν σκύλακα τῷ ἀδελφεῷ τιμωρήσαντα δακρύσειε, μνησθεῖσά τε Σμέρδιος καὶ μαθοῦσα ὡς ἐκείνῳ οὐκ εἴη ὁ τιμωρήσων. Ἕλληνες μὲν δὴ διὰ τοῦτο τὸ ἔπος φασὶ αὐτὴν ἀπολέσθαι ὑπὸ Καμβύσεω, Αἰγύπτιοι δὲ ὡς τραπέζῃ παρακατημένων λαβοῦσαν θρίδακα τὴν γυναῖκα περιτῖλαι καὶ ἐπανειρέσθαι τὸν ἄνδρα κότερον περιτετιλμένη ἡ θρίδαξ ἢ δασέα εἴη καλλίων, καὶ τὸν φάναι δασέαν, τὴν δ’ εἰπεῖν ταύτην μέντοι κοτὲ σὺ τὴν θρίδακα ἐμιμήσαο τὸν Κύρου οἶκον ἀποψιλώσας. τὸν δὲ θυμωθέντα ἐμπηδῆσαι αὐτῇ ἐχούσῃ ἐν γαστρί, καί μιν ἐκτρώσασαν ἀποθανεῖν.", "st": "3.32"}, {"sp": "N", "t": "ταῦτα μὲν ἐς τοὺς οἰκηίους ὁ Καμβύσης ἐξεμάνη, εἴτε δὴ διὰ τὸν Ἆπιν εἴτε καὶ ἄλλως, οἷα πολλὰ ἔωθε ἀνθρώπους κακὰ καταλαμβάνειν· καὶ γὰρ τινὰ ἐκ γενεῆς νοῦσον μεγάλην λέγεται ἔχειν ὁ Καμβύσης, τὴν ἱρὴν ὀνομάζουσι τινές. οὔ νύν τοι ἀεικὲς οὐδὲν ἦν τοῦ σώματος νοῦσον μεγάλην νοσέοντος μηδὲ τὰς φρένας ὑγιαίνειν.", "st": "3.33"}, {"sp": "N", "t": "τάδε δ’ ἐς τοὺς ἄλλους Πέρσας ἐξεμάνη. λέγεται γὰρ εἰπεῖν αὐτὸν πρὸς Πρηξάσπεα, τὸν ἐτίμα τε μάλιστα καί οἱ τὰς ἀγγελίας ἐφόρεε οὗτος, τούτου τε ὁ παῖς οἰνοχόος ἦν τῷ Καμβύσῃ, τιμὴ δὲ καὶ αὕτη οὐ σμικρή· εἰπεῖν δὲ λέγεται τάδε. Πρήξασπες, κοῖόν με τινὰ νομίζουσι Πέρσαι εἶναι ἄνδρα τίνας τε λόγους περὶ ἐμέο ποιεῦνται; τὸν δὲ εἰπεῖν ὦ δέσποτα, τὰ μὲν ἄλλα πάντα μεγάλως ἐπαινέαι, τῇ δὲ φιλοινίῃ σε φασὶ πλεόνως προσκεῖσθαι. τὸν μὲν δὴ λέγειν ταῦτα περὶ Περσέων, τὸν δὲ θυμωθέντα τοιάδε ἀμείβεσθαι. νῦν ἄρα με φασὶ Πέρσαι οἴνῳ προσκείμενον παραφρονέειν καὶ οὐκ εἶναι νοήμονα· οὐδ’ ἄρα σφέων οἱ πρότεροι λόγοι ἦσαν ἀληθέες. πρότερον γὰρ δὴ ἄρα, Περσέων οἱ συνέδρων ἐόντων καὶ Κροίσου, εἴρετο Καμβύσης κοῖός τις δοκέοι ἀνὴρ εἶναι πρὸς τὸν πατέρα τελέσαι Κῦρον, οἳ δὲ ἀμείβοντο ὡς εἴη ἀμείνων τοῦ πατρός· τά τε γὰρ ἐκείνου πάντα ἔχειν αὐτὸν καὶ προσεκτῆσθαι Αἴγυπτόν τε καὶ τὴν θάλασσαν. Πέρσαι μὲν ταῦτα ἔλεγον, Κροῖσος δὲ παρεών τε καὶ οὐκ ἀρεσκόμενος τῇ κρίσι εἶπε πρὸς τὸν Καμβύσεα τάδε. ἐμοὶ μέν νυν, ὦ παῖ Κύρου, οὐ δοκέεις ὅμοιος εἶναι τῷ πατρί· οὐ γάρ κώ τοι ἐστὶ υἱὸς οἷον σε ἐκεῖνος κατελίπετο. ἥσθη τε ταῦτα ἀκούσας ὁ Καμβύσης καὶ ἐπαίνεε τὴν Κροίσου κρίσιν.", "st": "3.34"}, {"sp": "N", "t": "τούτων δὴ ὦν ἐπιμνησθέντα ὀργῇ λέγειν πρὸς τὸν Πρηξάσπεα σύ νυν μάθε εἰ λέγουσι Πέρσαι ἀληθέα εἴτε αὐτοὶ λέγοντες ταῦτα παραφρονέουσι· εἰ μὲν γὰρ τοῦ παιδὸς τοῦ σοῦ τοῦδε ἑστεῶτος ἐν τοῖσι προθύροισι βαλὼν τύχοιμι μέσης τῆς καρδίης, Πέρσαι φανέονται λέγοντες οὐδέν· ἢν δὲ ἁμάρτω, φάναι Πέρσας τε λέγειν ἀληθέα καί με μὴ σωφρονέειν. ταῦτα δὲ εἰπόντα καὶ διατείναντα τὸ τόξον βαλεῖν τὸν παῖδα, πεσόντος δὲ τοῦ παιδὸς ἀνασχίζειν αὐτὸν κελεύειν καὶ σκέψασθαι τὸ βλῆμα· ὡς δὲ ἐν τῇ καρδίῃ εὑρεθῆναι ἐνεόντα τὸν ὀιστόν, εἰπεῖν πρὸς τὸν πατέρα τοῦ παιδὸς γελάσαντα καὶ περιχαρέα γενόμενον Πρήξασπες, ὡς μὲν ἐγὼ τε οὐ μαίνομαι Πέρσαι τε παραφρονέουσι, δῆλά τοι γέγονε. νῦν δέ μοι εἰπέ, τίνα εἶδες ἤδη πάντων ἀνθρώπων οὕτω ἐπίσκοπα τοξεύοντα; Πρηξάσπεα δὲ ὁρῶντα ἄνδρα οὐ φρενήρεα καὶ περὶ ἑωυτῷ δειμαίνοντα εἰπεῖν δέσποτα, οὐδ’ ἂν αὐτὸν ἔγωγε δοκέω τὸν θεὸν οὕτω ἂν καλῶς βαλεῖν. τότε μὲν ταῦτα ἐξεργάσατο, ἑτέρωθι δὲ Περσέων ὁμοίους τοῖσι πρώτοισι δυώδεκα ἐπ’ οὐδεμιῇ αἰτίῃ ἀξιοχρέῳ ἑλὼν ζώοντας ἐπὶ κεφαλὴν κατώρυξε.", "st": "3.35"}, {"sp": "N", "t": "ταῦτα δέ μιν ποιεῦντα ἐδικαίωσε Κροῖσος ὁ Λυδὸς νουθετῆσαι τοῖσιδε τοῖσι ἔπεσι. ὦ βασιλεῦ, μὴ πάντα ἡλικίῃ καὶ θυμῷ ἐπίτραπε, ἀλλ’ ἴσχε καὶ καταλάμβανε σεωυτόν· ἀγαθόν τι πρόνοον εἶναι, σοφὸν δὲ ἡ προμηθίη. σὺ δὲ κτείνεις μὲν ἄνδρας σεωυτοῦ πολιήτας ἐπ’ οὐδεμιῇ αἰτίῃ ἀξιοχρέῳ ἑλών, κτείνεις δὲ παῖδας. ἢν δὲ πολλὰ τοιαῦτα ποιέῃς, ὅρα ὅκως μή σευ ἀποστήσονται Πέρσαι. ἐμοὶ δὲ πατὴρ σὸς Κῦρος ἐνετέλλετο πολλὰ κελεύων σε νουθετέειν καὶ ὑποτίθεσθαι ὅ τι ἂν εὑρίσκω ἀγαθόν. ὃ μὲν δὴ εὐνοίην φαίνων συνεβούλευέ οἱ ταῦτα· ὃ δ’ ἀμείβετο τοῖσιδε. σὺ καὶ ἐμοὶ τολμᾷς συμβουλεύειν, ὃς χρηστῶς μὲν τὴν σεωυτοῦ πατρίδα ἐπετρόπευσας, εὖ δὲ τῷ πατρὶ τῷ ἐμῷ συνεβούλευσας, κελεύων αὐτὸν Ἀράξεα ποταμὸν διαβάντα ἰέναι ἐπὶ Μασσαγέτας, βουλομένων ἐκείνων διαβαίνειν ἐς τὴν ἡμετέρην, καὶ ἀπὸ μὲν σεωυτὸν ὤλεσας τῆς σεωυτοῦ πατρίδος κακῶς προστάς, ἀπὸ δὲ ὤλεσας Κῦρον πειθόμενον σοί, ἀλλ’ οὔτι χαίρων, ἐπεί τοι καὶ πάλαι ἐς σὲ προφάσιός τευ ἐδεόμην ἐπιλαβέσθαι. ταῦτα δὲ εἴπας ἐλάμβανε τὸ τόξον ὡς κατατοξεύσων αὐτόν, Κροῖσος δὲ ἀναδραμὼν ἔθεε ἔξω. ὁ δὲ ἐπείτε τοξεῦσαι οὐκ εἶχε, ἐνετείλατο τοῖσι θεράπουσι λαβόντας μιν ἀποκτεῖναι. οἱ δὲ θεράποντες ἐπιστάμενοι τὸν τρόπον αὐτοῦ κατακρύπτουσι τὸν Κροῖσον ἐπὶ τῷδε τῷ λόγῳ ὥστε, εἰ μὲν μεταμελήσῃ τῷ Καμβύσῃ καὶ ἐπιζητέῃ τὸν Κροῖσον, οἳ δὲ ἐκφήναντες αὐτὸν δῶρα λάμψονται ζωάγρια Κροίσου, ἢν δὲ μὴ μεταμέληται μηδὲ ποθέῃ μιν, τότε καταχρᾶσθαι. ἐπόθησέ τε δὴ ὁ Καμβύσης τὸν Κροῖσον οὐ πολλῷ μετέπειτα χρόνῳ ὕστερον, καὶ οἱ θεράποντες μαθόντες τοῦτο ἐπηγγέλλοντο αὐτῷ ὡς περιείη. Καμβύσης δὲ Κροίσῳ μὲν συνήδεσθαι ἔφη περιεόντι, ἐκείνους μέντοι τοὺς περιποιήσαντας οὐ καταπροΐξεσθαι ἀλλ’ ἀποκτενέειν· καὶ ἐποίησε ταῦτα.", "st": "3.36"}, {"sp": "N", "t": "ὃ μὲν δὴ τοιαῦτα πολλὰ ἐς Πέρσας τε καὶ τοὺς συμμάχους ἐξεμαίνετο, μένων ἐν Μέμφι καὶ θήκας τε παλαιὰς ἀνοίγων καὶ σκεπτόμενος τοὺς νεκρούς. ὣς δὲ δὴ καὶ ἐς τοῦ Ἡφαίστου τὸ ἱρὸν ἦλθε καὶ πολλὰ τῷ ἀγάλματι κατεγέλασε. ἔστι γὰρ τοῦ Ἡφαίστου τὤγαλμα τοῖσι Φοινικηίοισι Παταΐκοισι ἐμφερέστατον, τοὺς οἱ Φοίνικες ἐν τῇσι πρῴρῃσι τῶν τριηρέων περιάγουσι. ὃς δὲ τούτους μὴ ὄπωπε, ὧδε σημανέω· πυγμαίου ἀνδρὸς μίμησις ἐστί. ἐσῆλθε δὲ καὶ ἐς τῶν Καβείρων τὸ ἱρόν, ἐς τὸ οὐ θεμιτόν ἐστι ἐσιέναι ἄλλον γε ἢ τὸν ἱρέα· ταῦτα δὲ τὰ ἀγάλματα καὶ ἐνέπρησε πολλὰ κατασκώψας. ἔστι δὲ καὶ ταῦτα ὅμοια τοῖσι τοῦ Ἡφαίστου· τούτου δὲ σφέας παῖδας λέγουσι εἶναι.", "st": "3.37"}, {"sp": "N", "t": "πανταχῇ ὦν μοι δῆλα ἐστὶ ὅτι ἐμάνη μεγάλως ὁ Καμβύσης· οὐ γὰρ ἂν ἱροῖσί τε καὶ νομαίοισι ἐπεχείρησε καταγελᾶν. εἰ γάρ τις προθείη πᾶσι ἀνθρώποισι ἐκλέξασθαι κελεύων νόμους τοὺς καλλίστους ἐκ τῶν πάντων νόμων, διασκεψάμενοι ἂν ἑλοίατο ἕκαστοι τοὺς ἑωυτῶν· οὕτω νομίζουσι πολλόν τι καλλίστους τοὺς ἑωυτῶν νόμους ἕκαστοι εἶναι. οὔκων οἰκός ἐστι ἄλλον γε ἢ μαινόμενον ἄνδρα γέλωτα τὰ τοιαῦτα τίθεσθαι· ὡς δὲ οὕτω νενομίκασι τὰ περὶ τοὺς νόμους πάντες ἄνθρωποι, πολλοῖσί τε καὶ ἄλλοισι τεκμηρίοισι πάρεστι σταθμώσασθαι, ἐν δὲ δὴ καὶ τῷδε. Δαρεῖος ἐπὶ τῆς ἑωυτοῦ ἀρχῆς καλέσας Ἑλλήνων τοὺς παρεόντας εἴρετο ἐπὶ κόσῳ ἂν χρήματι βουλοίατο τοὺς πατέρας ἀποθνήσκοντας κατασιτέεσθαι· οἳ δὲ ἐπ’ οὐδενὶ ἔφασαν ἔρδειν ἂν τοῦτο. Δαρεῖος δὲ μετὰ ταῦτα καλέσας Ἰνδῶν τοὺς καλεομένους Καλλατίας, οἳ τοὺς γονέας κατεσθίουσι, εἴρετο, παρεόντων τῶν Ἑλλήνων καὶ δι’ ἑρμηνέος μανθανόντων τὰ λεγόμενα, ἐπὶ τίνι χρήματι δεξαίατ’ ἂν τελευτῶντας τοὺς πατέρας κατακαίειν πυρί· οἳ δὲ ἀμβώσαντες μέγα εὐφημέειν μιν ἐκέλευον. οὕτω μέν νυν ταῦτα νενόμισται, καὶ ὀρθῶς μοι δοκέει Πίνδαρος ποιῆσαι νόμον πάντων βασιλέα φήσας εἶναι.", "st": "3.38"}, {"sp": "N", "t": "Καμβύσεω δὲ ἐπ’ Αἴγυπτον στρατευομένου ἐποιήσαντο καὶ Λακεδαιμόνιοι στρατηίην ἐπὶ Σάμον τε καὶ Πολυκράτεα τὸν Αἰάκεος· ὃς ἔσχε Σάμον ἐπαναστάς, καὶ τὰ μὲν πρῶτα τριχῇ δασάμενος τὴν πόλιν … τοῖσι ἀδελφεοῖσι Πανταγνώτῳ καὶ Συλοσῶντι ἔνειμε, μετὰ δὲ τὸν μὲν αὐτῶν ἀποκτείνας τὸν δὲ νεώτερον Συλοσῶντα ἐξελάσας ἔσχε πᾶσαν Σάμον, σχὼν δὲ ξεινίην Ἀμάσι τῷ Αἰγύπτου βασιλέι συνεθήκατο, πέμπων τε δῶρα καὶ δεκόμενος ἄλλα παρ’ ἐκείνου. ἐν χρόνῳ δὲ ὀλίγῳ αὐτίκα τοῦ Πολυκράτεος τὰ πρήγματα ηὔξετο καὶ ἦν βεβωμένα ἀνά τε τὴν Ἰωνίην καὶ τὴν ἄλλην Ἑλλάδα· ὅκου γὰρ ἰθύσειε στρατεύεσθαι, πάντα οἱ ἐχώρεε εὐτυχέως. ἔκτητο δὲ πεντηκοντέρους τε ἑκατὸν καὶ χιλίους τοξότας, ἔφερε δὲ καὶ ἦγε πάντας διακρίνων οὐδένα· τῷ γὰρ φίλῳ ἔφη χαριεῖσθαι μᾶλλον ἀποδιδοὺς τὰ ἔλαβε ἢ ἀρχὴν μηδὲ λαβών. συχνὰς μὲν δὴ τῶν νήσων ἀραιρήκεε, πολλὰ δὲ καὶ τῆς ἠπείρου ἄστεα· ἐν δὲ δὴ καὶ Λεσβίους πανστρατιῇ βοηθέοντας Μιλησίοισι ναυμαχίῃ κρατήσας εἷλε, οἳ τὴν τάφρον περὶ τὸ τεῖχος τὸ ἐν Σάμῳ πᾶσαν δεδεμένοι ὤρυξαν.", "st": "3.39"}, {"sp": "N", "t": "καί κως τὸν Ἄμασιν εὐτυχέων μεγάλως ὁ Πολυκράτης οὐκ ἐλάνθανε, ἀλλά οἱ τοῦτ’ ἦν ἐπιμελές. πολλῷ δὲ ἔτι πλεῦνός οἱ εὐτυχίης γινομένης γράψας ἐς βυβλίον τάδε ἐπέστειλε ἐς Σάμον. Ἄμασις Πολυκράτεϊ ὧδε λέγει. ἡδὺ μὲν πυνθάνεσθαι ἄνδρα φίλον καὶ ξεῖνον εὖ πρήσσοντα· ἐμοὶ δὲ αἱ σαὶ μεγάλαι εὐτυχίαι οὐκ ἀρέσκουσι, τὸ θεῖον ἐπισταμένῳ ὡς ἔστι φθονερόν· καί κως βούλομαι καὶ αὐτὸς καὶ τῶν ἂν κήδωμαι τὸ μέν τι εὐτυχέειν τῶν πρηγμάτων τὸ δὲ προσπταίειν, καὶ οὕτω διαφέρειν τὸν αἰῶνα ἐναλλὰξ πρήσσων ἢ εὐτυχέειν τὰ πάντα. οὐδένα γάρ κω λόγῳ οἶδα ἀκούσας ὅστις ἐς τέλος οὐ κακῶς ἐτελεύτησε πρόρριζος, εὐτυχέων τὰ πάντα. σύ νυν ἐμοὶ πειθόμενος ποίησον πρὸς τὰς εὐτυχίας τοιάδε· φροντίσας τὸ ἂν εὕρῃς ἐόν τοι πλείστου ἄξιον καὶ ἐπ’ ᾧ σὺ ἀπολομένῳ μάλιστα τὴν ψυχὴν ἀλγήσεις, τοῦτο ἀπόβαλε οὕτω ὅκως μηκέτι ἥξει ἐς ἀνθρώπους· ἤν τε μὴ ἐναλλὰξ ἤδη τὠπὸ τούτου αἱ εὐτυχίαι τοι τῇσι πάθῃσι προσπίπτωσι, τρόπῳ τῷ ἐξ ἐμεῦ ὑποκειμένῳ ἀκέο.", "st": "3.40"}, {"sp": "N", "t": "ταῦτα ἐπιλεξάμενος ὁ Πολυκράτης καὶ νόῳ λαβὼν ὥς οἱ εὖ ὑπετίθετο Ἄμασις, ἐδίζητο ἐπ’ ᾧ ἂν μάλιστα τὴν ψυχὴν ἀσηθείη ἀπολομένῳ τῶν κειμηλίων, διζήμενος δὲ εὕρισκε τόδε. ἦν οἱ σφρηγὶς τὴν ἐφόρεε χρυσόδετος, σμαράγδου μὲν λίθου ἐοῦσα, ἔργον δὲ ἦν Θεοδώρου τοῦ Τηλεκλέος Σαμίου. ἐπεὶ ὦν ταύτην οἱ ἐδόκεε ἀποβαλεῖν, ἐποίεε τοιάδε· πεντηκόντερον πληρώσας ἀνδρῶν ἐσέβη ἐς αὐτήν, μετὰ δὲ ἀναγαγεῖν ἐκέλευε ἐς τὸ πέλαγος· ὡς δὲ ἀπὸ τῆς νήσου ἑκὰς ἐγένετο, περιελόμενος τὴν σφρηγῖδα πάντων ὁρώντων τῶν συμπλόων ῥίπτει ἐς τὸ πέλαγος. τοῦτο δὲ ποιήσας ἀπέπλεε, ἀπικόμενος δὲ ἐς τὰ οἰκία συμφορῇ ἐχρᾶτο.", "st": "3.41"}, {"sp": "N", "t": "πέμπτῃ δὲ ἢ ἕκτῃ ἡμέρῃ ἀπὸ τούτων τάδε οἱ συνήνεικε γενέσθαι. ἀνὴρ ἁλιεὺς λαβὼν ἰχθὺν μέγαν τε καὶ καλὸν ἠξίου μιν Πολυκράτεϊ δῶρον δοθῆναι· φέρων δὴ ἐπὶ τὰς θύρας Πολυκράτεϊ ἔφη ἐθέλειν ἐλθεῖν ἐς ὄψιν, χωρήσαντος δέ οἱ τούτου ἔλεγε διδοὺς τὸν ἰχθύν ὦ βασιλεῦ, ἐγὼ τόνδε ἑλὼν οὐκ ἐδικαίωσα φέρειν ἐς ἀγορήν, καίπερ ἐὼν ἀποχειροβίοτος, ἀλλά μοι ἐδόκεε σεῦ τε εἶναι ἄξιος καὶ τῆς σῆς ἀρχῆς· σοὶ δή μιν φέρων δίδωμι. ὁ δὲ ἡσθεὶς τοῖσι ἔπεσι ἀμείβεται τοῖσιδε. κάρτα τε εὖ ἐποίησας καὶ χάρις διπλῆ τῶν τε λόγων καὶ τοῦ δώρου, καί σε ἐπὶ δεῖπνον καλέομεν. ὃ μὲν δὴ ἁλιεὺς μέγα ποιεύμενος ταῦτα ἤιε ἐς τὰ οἰκία, τὸν δὲ ἰχθὺν τάμνοντες οἱ θεράποντες εὑρίσκουσι ἐν τῇ νηδύι αὐτοῦ ἐνεοῦσαν τὴν Πολυκράτεος σφρηγῖδα. ὡς δὲ εἶδόν τε καὶ ἔλαβον τάχιστα, ἔφερον κεχαρηκότες παρὰ τὸν Πολυκράτεα, διδόντες δέ οἱ τὴν σφρηγῖδα ἔλεγον ὅτεῳ τρόπῳ εὑρέθη. τὸν δὲ ὡς ἐσῆλθε θεῖον εἶναι τὸ πρῆγμα, γράφει ἐς βυβλίον πάντα τὰ ποιήσαντά μιν οἷα καταλελάβηκε, γράψας δὲ ἐς Αἴγυπτον ἐπέθηκε.", "st": "3.42"}, {"sp": "N", "t": "ἐπιλεξάμενος δὲ ὁ Ἄμασις τὸ βυβλίον τὸ παρὰ τοῦ Πολυκράτεος ἧκον, ἔμαθε ὅτι ἐκκομίσαι τε ἀδύνατον εἴη ἀνθρώπῳ ἄνθρωπον ἐκ τοῦ μέλλοντος γίνεσθαι πρήγματος, καὶ ὅτι οὐκ εὖ τελευτήσειν μέλλοι Πολυκράτης εὐτυχέων τὰ πάντα, ὃς καὶ τὰ ἀποβάλλει εὑρίσκει. πέμψας δέ οἱ κήρυκα ἐς Σάμον διαλύεσθαι ἔφη τὴν ξεινίην. τοῦδε δὲ εἵνεκεν ταῦτα ἐποίεε, ἵνα μὴ συντυχίης δεινῆς τε καὶ μεγάλης Πολυκράτεα καταλαβούσης αὐτὸς ἀλγήσειε τὴν ψυχὴν ὡς περὶ ξείνου ἀνδρός.", "st": "3.43"}, {"sp": "N", "t": "ἐπὶ τοῦτον δὴ ὦν τὸν Πολυκράτεα εὐτυχέοντα τὰ πάντα ἐστρατεύοντο Λακεδαιμόνιοι, ἐπικαλεσαμένων τῶν μετὰ ταῦτα Κυδωνίην τὴν ἐν Κρήτῃ κτισάντων Σαμίων. πέμψας δὲ κήρυκα λάθρῃ Σαμίων Πολυκράτης παρὰ Καμβύσεα τὸν Κύρου συλλέγοντα στρατὸν ἐπ’ Αἴγυπτον, ἐδεήθη ὅκως ἂν καὶ παρ’ ἑωυτὸν πέμψας ἐς Σάμον δέοιτο στρατοῦ. Καμβύσης δὲ ἀκούσας τούτων προθύμως ἔπεμψε ἐς Σάμον δεόμενος Πολυκράτεος στρατὸν ναυτικὸν ἅμα πέμψαι ἑωυτῷ ἐπ’ Αἴγυπτον. ὁ δὲ ἐπιλέξας τῶν ἀστῶν τοὺς ὑπώπτευε μάλιστα ἐς ἐπανάστασιν ἀπέπεμπε τεσσεράκοντα τριήρεσι, ἐντειλάμενος Καμβύσῃ ὀπίσω τούτους μὴ ἀποπέμπειν.", "st": "3.44"}, {"sp": "N", "t": "οἳ μὲν δὴ λέγουσι τοὺς ἀποπεμφθέντας Σαμίων ὑπὸ Πολυκράτεος οὐκ ἀπικέσθαι ἐς Αἴγυπτον, ἀλλ’ ἐπείτε ἐγένοντο ἐν Καρπάθῳ πλέοντες, δοῦναι σφίσι λόγον, καί σφι ἁδεῖν τὸ προσωτέρω μηκέτι πλέειν· οἳ δὲ λέγουσι ἀπικομένους τε ἐς Αἴγυπτον καὶ φυλασσομένους ἐνθεῦτεν αὐτοὺς ἀποδρῆναι. καταπλέουσι δὲ ἐς τὴν Σάμον Πολυκράτης νηυσὶ ἀντιάσας ἐς μάχην κατέστη· νικήσαντες δὲ οἱ κατιόντες ἀπέβησαν ἐς τὴν νῆσον, πεζομαχήσαντες δὲ ἐν αὐτῇ ἑσσώθησαν, καὶ οὕτω δὴ ἔπλεον ἐς Λακεδαίμονα. εἰσὶ δὲ οἳ λέγουσι τοὺς ἀπ’ Αἰγύπτου νικῆσαι Πολυκράτεα, λέγοντες ἐμοὶ δοκέειν οὐκ ὀρθῶς· οὐδὲν γὰρ ἔδει σφέας Λακεδαιμονίους ἐπικαλέεσθαι, εἴ περ αὐτοὶ ἦσαν ἱκανοὶ Πολυκράτεα παραστήσασθαι. πρὸς δὲ τούτοισι οὐδὲ λόγος αἱρέει, τῷ ἐπίκουροί τε μισθωτοὶ καὶ τοξόται οἰκήιοι ἦσαν πλήθεϊ πολλοί, τοῦτον ὑπὸ τῶν κατιόντων Σαμίων ἐόντων ὀλίγων ἑσσωθῆναι. τῶν δ’ ὑπ’ ἑωυτῷ ἐόντων πολιητέων τὰ τέκνα καὶ τὰς γυναῖκας ὁ Πολυκράτης ἐς τοὺς νεωσοίκους συνειλήσας εἶχε ἑτοίμους, ἢν ἄρα προδιδῶσι οὗτοι πρὸς τοὺς κατιόντας, ὑποπρῆσαι αὐτοῖσι τοῖσι νεωσοίκοισι.", "st": "3.45"}, {"sp": "N", "t": "ἐπείτε δὲ οἱ ἐξελασθέντες Σαμίων ὑπὸ Πολυκράτεος ἀπίκοντο ἐς τὴν Σπάρτην, καταστάντες ἐπὶ τοὺς ἄρχοντας ἔλεγον πολλὰ οἷα κάρτα δεόμενοι· οἳ δέ σφι τῇ πρώτῃ καταστάσι ὑπεκρίναντο τὰ μὲν πρῶτα λεχθέντα ἐπιλελῆσθαι, τὰ δὲ ὕστατα οὐ συνιέναι. μετὰ δὲ ταῦτα δεύτερα καταστάντες ἄλλο μὲν εἶπον οὐδέν, θύλακον δὲ φέροντες ἔφασαν τὸν θύλακον ἀλφίτων δέεσθαι. οἳ δέ σφι ὑπεκρίναντο τῷ θυλάκῳ περιεργάσθαι· βοηθέειν δ’ ὦν ἔδοξε αὐτοῖσι.", "st": "3.46"}, {"sp": "N", "t": "καὶ ἔπειτα παρασκευασάμενοι ἐστρατεύοντο Λακεδαιμόνιοι ἐπὶ Σάμον, ὡς μὲν Σάμιοι λέγουσι, εὐεργεσίας ἐκτίνοντες, ὅτι σφι πρότεροι αὐτοὶ νηυσὶ ἐβοήθησαν ἐπὶ Μεσσηνίους· ὡς δὲ Λακεδαιμόνιοι λέγουσι, οὐκ οὕτω τιμωρῆσαι δεομένοισι Σαμίοισι ἐστρατεύοντο ὡς τίσασθαι βουλόμενοι τοῦ κρητῆρος τῆς ἁρπαγῆς, τὸν ἦγον Κροίσῳ, καὶ τοῦ θώρηκος, τὸν αὐτοῖσι Ἄμασις ὁ Αἰγύπτου βασιλεὺς ἔπεμψε δῶρον. καὶ γὰρ θώρηκα ἐληίσαντο τῷ προτέρῳ ἔτεϊ ἢ τὸν κρητῆρα οἱ Σάμιοι, ἐόντα μὲν λίνεον καὶ ζῴων ἐνυφασμένων συχνῶν, κεκοσμημένον δὲ χρυσῷ καὶ εἰρίοισι ἀπὸ ξύλου· τῶν δὲ εἵνεκα θωμάσαι ἄξιον, ἁρπεδόνη ἑκάστη τοῦ θώρηκος ποιέει· ἐοῦσα γὰρ λεπτὴ ἔχει ἁρπεδόνας ἐν ἑωυτῇ τριηκοσίας καὶ ἑξήκοντα, πάσας φανεράς. τοιοῦτος ἕτερος ἐστὶ καὶ τὸν ἐν Λίνδῳ ἀνέθηκε τῇ Ἀθηναίῃ Ἄμασις.", "st": "3.47"}, {"sp": "N", "t": "συνεπελάβοντο δὲ τοῦ στρατεύματος τοῦ ἐπὶ Σάμον ὥστε γενέσθαι καὶ Κορίνθιοι προθύμως· ὕβρισμα γὰρ καὶ ἐς τούτους εἶχε ἐκ τῶν Σαμίων γενόμενον γενεῇ πρότερον τοῦ στρατεύματος τούτου, κατὰ δὲ τὸν αὐτὸν χρόνον τοῦ κρητῆρος τῇ ἁρπαγῇ γεγονός. Κερκυραίων γὰρ παῖδας τριηκοσίους ἀνδρῶν τῶν πρώτων Περίανδρος ὁ Κυψέλου ἐς Σάρδις ἀπέπεμψε παρὰ Ἀλυάττεα ἐπ’ ἐκτομῇ· προσσχόντων δὲ ἐς τὴν Σάμον τῶν ἀγόντων τοὺς παῖδας Κορινθίων, πυθόμενοι οἱ Σάμιοι τὸν λόγον, ἐπ’ οἷσι ἀγοίατο ἐς Σάρδις, πρῶτα μὲν τοὺς παῖδας ἐδίδαξαν ἱροῦ ἅψασθαι Ἀρτέμιδος· μετὰ δὲ οὐ περιορῶντες ἀπέλκειν τοὺς ἱκέτας ἐκ τοῦ ἱροῦ, σιτίων δὲ τοὺς παῖδας ἐργόντων Κορινθίων, ἐποιήσαντο οἱ Σάμιοι ὁρτήν, τῇ καὶ νῦν ἔτι χρέωνται κατὰ ταὐτά. νυκτὸς γὰρ ἐπιγενομένης, ὅσον χρόνον ἱκέτευον οἱ παῖδες, ἵστασαν χοροὺς παρθένων τε καὶ ἠιθέων, ἱστάντες δὲ τοὺς χοροὺς τρωκτὰ σησάμου τε καὶ μέλιτος ἐποιήσαντο νόμον φέρεσθαι, ἵνα ἁρπάζοντες οἱ τῶν Κερκυραίων παῖδες ἔχοιεν τροφήν. ἐς τοῦτο δὲ τόδε ἐγίνετο, ἐς ὃ οἱ Κορίνθιοι τῶν παίδων οἱ φύλακοι οἴχοντο ἀπολιπόντες· τοὺς δὲ παῖδας ἀπήγαγον ἐς Κέρκυραν οἱ Σάμιοι.", "st": "3.48"}, {"sp": "N", "t": "εἰ μέν νυν Περιάνδρου τελευτήσαντος τοῖσι Κορινθίοισι φίλα ἦν πρὸς τοὺς Κερκυραίους, οἳ δὲ οὐκ ἂν συνελάβοντο τοῦ στρατεύματος τοῦ ἐπὶ Σάμον ταύτης εἵνεκεν τῆς αἰτίης. νῦν δὲ αἰεὶ ἐπείτε ἔκτισαν τὴν νῆσον εἰσὶ ἀλλήλοισι διάφοροι, ἐόντες ἑωυτοῖσι … τούτων ὦν εἵνεκεν ἀπεμνησικάκεον τοῖσι Σαμίοισι οἱ Κορίνθιοι. ἀπέπεμπε δὲ ἐς Σάρδις ἐπ’ ἐκτομῇ Περίανδρος τῶν πρώτων Κερκυραίων ἐπιλέξας τοὺς παῖδας τιμωρεύμενος· πρότεροι γὰρ οἱ Κερκυραῖοι ἦρξαν ἐς αὐτὸν πρῆγμα ἀτάσθαλον ποιήσαντες.", "st": "3.49"}, {"sp": "N", "t": "ἐπείτε γὰρ τὴν ἑωυτοῦ γυναῖκα Μέλισσαν Περίανδρος ἀπέκτεινε, συμφορὴν τοιήνδε οἱ ἄλλην συνέβη πρὸς τῇ γεγονυίῃ γενέσθαι. ἦσάν οἱ ἐκ Μελίσσης δύο παῖδες, ἡλικίην ὃ μὲν ἑπτακαίδεκα ὁ δὲ ὀκτωκαίδεκα ἔτεα γεγονώς. τούτους ὁ μητροπάτωρ Προκλέης ἐὼν Ἐπιδαύρου τύραννος μεταπεμψάμενος παρ’ ἑωυτὸν ἐφιλοφρονέετο, ὡς οἰκὸς ἦν θυγατρὸς ἐόντας τῆς ἑωυτοῦ παῖδας. ἐπείτε δὲ σφέας ἀπεπέμπετο, εἶπε προπέμπων αὐτούς ἆρα ἴστε, ὦ παῖδες, ὃς ὑμέων τὴν μητέρα ἀπέκτεινε; τοῦτο τὸ ἔπος ὁ μὲν πρεσβύτερος αὐτῶν ἐν οὐδενὶ λόγῳ ἐποιήσατο· ὁ δὲ νεώτερος, τῷ οὔνομα ἦν Λυκόφρων, ἤλγησε ἀκούσας οὕτω ὥστε ἀπικόμενος ἐς τὴν Κόρινθον ἅτε φονέα τῆς μητρὸς τὸν πατέρα οὔτε προσεῖπε, διαλεγομένῳ τε οὔτε προσδιελέγετο ἱστορέοντί τε λόγον οὐδένα ἐδίδου. τέλος δέ μιν περιθύμως ἔχων ὁ Περίανδρος ἐξελαύνει ἐκ τῶν οἰκίων.", "st": "3.50"}, {"sp": "N", "t": "ἐξελάσας δὲ τοῦτον ἱστόρεε τὸν πρεσβύτερον τά σφι ὁ μητροπάτωρ διελέχθη. ὁ δέ οἱ ἀπηγέετο ὡς σφέας φιλοφρόνως ἐδέξατο· ἐκείνου δὲ τοῦ ἔπεος τό σφι ὁ Προκλέης ἀποστέλλων εἶπε, ἅτε οὐ νόῳ λαβών, οὐκ ἐμέμνητο. Περίανδρος δὲ οὐδεμίαν μηχανὴν ἔφη εἶναι μὴ οὔ σφι ἐκεῖνον ὑποθέσθαι τι, ἐλιπάρεέ τε ἱστορέων· ὁ δὲ ἀναμνησθεὶς εἶπε καὶ τοῦτο. Περίανδρος δὲ νόῳ λαβὼν [καὶ τοῦτο] καὶ μαλακὸν ἐνδιδόναι βουλόμενος οὐδέν, τῇ ὁ ἐξελασθεὶς ὑπ’ αὐτοῦ παῖς δίαιταν ἐποιέετο, ἐς τούτους πέμπων ἄγγελον ἀπηγόρευε μή μιν δέκεσθαι οἰκίοισι. ὁ δὲ ὅκως ἀπελαυνόμενος ἔλθοι ἐς ἄλλην οἰκίην, ἀπηλαύνετ’ ἂν καὶ ἀπὸ ταύτης, ἀπειλέοντός τε τοῦ Περίανδρου τοῖσι δεξαμένοισι καὶ ἐξέργειν κελεύοντος· ἀπελαυνόμενος δ’ ἂν ἤιε ἐπ’ ἑτέρην τῶν ἑταίρων· οἳ δὲ ἅτε Περιάνδρου ἐόντα παῖδα καίπερ δειμαίνοντες ὅμως ἐδέκοντο.", "st": "3.51"}, {"sp": "N", "t": "τέλος δὲ ὁ Περίανδρος κήρυγμα ἐποιήσατο, ὃς ἂν ἢ οἰκίοισι ὑποδέξηταί μιν ἢ προσδιαλεχθῇ, ἱρὴν ζημίην τοῦτον τῷ Ἀπόλλωνι ὀφείλειν, ὅσην δὴ εἴπας. πρὸς ὦν δὴ τοῦτο τὸ κήρυγμα οὔτε τίς οἱ διαλέγεσθαι οὔτε οἰκίοισι δέκεσθαι ἤθελε· πρὸς δὲ οὐδὲ αὐτὸς ἐκεῖνος ἐδικαίου πειρᾶσθαι ἀπειρημένου, ἀλλὰ διακαρτερέων ἐν τῇσι στοῇσι ἐκαλινδέετο. τετάρτῃ δὲ ἡμέρῃ ἰδών μιν ὁ Περίανδρος ἀλουσίῃσί τε καὶ ἀσιτίῃσι συμπεπτωκότα οἴκτειρε· ὑπεὶς δὲ τῆς ὀργῆς ἤιε ἆσσον καὶ ἔλεγε ὦ παῖ, κότερα τούτων αἱρετώτερα ἐστί, ταῦτα τὸ νῦν ἔχων πρήσσεις, ἢ τὴν τυραννίδα καὶ τὰ ἀγαθὰ τὰ νῦν ἐγὼ ἔχω, ταῦτα ἐόντα τῷ πατρὶ ἐπιτήδεον παραλαμβάνειν, ὃς ἐὼν ἐμός τε παῖς καὶ Κορίνθου τῆς εὐδαίμονος βασιλεὺς ἀλήτην βίον εἵλευ, ἀντιστατέων τε καὶ ὀργῇ χρεώμενος ἐς τόν σε ἥκιστα ἐχρῆν. εἰ γάρ τις συμφορὴ ἐν αὐτοῖσι γέγονε, ἐξ ἧς ὑποψίην ἐς ἐμὲ ἔχεις, ἐμοί τε αὕτη γέγονε καὶ ἐγὼ αὐτῆς τὸ πλεῦν μέτοχος εἰμί, ὅσῳ αὐτός σφεα ἐξεργασάμην. σὺ δὲ μαθὼν ὅσῳ φθονέεσθαι κρέσσον ἐστὶ ἢ οἰκτείρεσθαι, ἅμα τε ὁκοῖόν τι ἐς τοὺς τοκέας καὶ ἐς τοὺς κρέσσονας τεθυμῶσθαι, ἄπιθι ἐς τὰ οἰκία. Περίανδρος μὲν τούτοισι αὐτὸν κατελάμβανε· ὁ δὲ ἄλλο μὲν οὐδὲν ἀμείβεται τὸν πατέρα, ἔφη δέ μιν ἱρὴν ζημίην ὀφείλειν τῷ θεῷ ἑωυτῷ ἐς λόγους ἀπικόμενον. μαθὼν δὲ ὁ Περίανδρος ὡς ἄπορόν τι τὸ κακὸν εἴη τοῦ παιδὸς καὶ ἀνίκητον, ἐξ ὀφθαλμῶν μιν ἀποπέμπεται στείλας πλοῖον ἐς Κέρκυραν· ἐπεκράτεε γὰρ καὶ ταύτης· ἀποστείλας δὲ τοῦτον ὁ Περίανδρος ἐστρατεύετο ἐπὶ τὸν πενθερὸν Προκλέα ὡς τῶν παρεόντων οἱ πρηγμάτων ἐόντα αἰτιώτατον, καὶ εἷλε μὲν τὴν Ἐπίδαυρον, εἷλε δὲ αὐτὸν Προκλέα καὶ ἐζώγρησε.", "st": "3.52"}, {"sp": "N", "t": "ἐπεὶ δὲ τοῦ χρόνου προβαίνοντος ὅ τε Περίανδρος παρηβήκεε καὶ συνεγινώσκετο ἑωυτῷ οὐκέτι εἶναι δυνατὸς τὰ πρήγματα ἐπορᾶν τε καὶ διέπειν, πέμψας ἐς τὴν Κέρκυραν ἀπεκάλεε τὸν Λυκόφρονα ἐπὶ τὴν τυραννίδα· ἐν γὰρ δὴ τῷ πρεσβυτέρῳ τῶν παίδων οὔκων ἐνώρα, ἀλλά οἱ κατεφαίνετο εἶναι νωθέστερος. ὁ δὲ Λυκόφρων οὐδὲ ἀνακρίσιος ἠξίωσε τὸν φέροντα τὴν ἀγγελίην. Περίανδρος δὲ περιεχόμενος τοῦ νεηνίεω δεύτερα ἀπέστειλε ἐπ’ αὐτὸν τὴν ἀδελφεήν, ἑωυτοῦ δὲ θυγατέρα, δοκέων μιν μάλιστα ταύτῃ ἂν πείθεσθαι. ἀπικομένης δὲ ταύτης καὶ λεγούσης, ὦ παῖ, βούλεαι τήν τε τυραννίδα ἐς ἄλλους πεσεῖν καὶ τὸν οἶκον τοῦ πατρὸς διαφορηθέντα μᾶλλον ἢ αὐτός σφεα ἀπελθὼν ἔχειν; ἄπιθι ἐς τὰ οἰκία, παῦσαι σεωυτὸν ζημιῶν. φιλοτιμίη κτῆμα σκαιόν. μὴ τῷ κακῷ τὸ κακὸν ἰῶ. πολλοὶ τῶν δικαίων τὰ ἐπιεικέστερα προτιθεῖσι, πολλοὶ δὲ ἤδη τὰ μητρώια διζήμενοι τὰ πατρώια ἀπέβαλον. τυραννὶς χρῆμα σφαλερόν, πολλοὶ δὲ αὐτῆς ἐρασταί εἰσι, ὁ δὲ γέρων τε ἤδη καὶ παρηβηκώς· μὴ δῷς τὰ σεωυτοῦ ἀγαθὰ ἄλλοισι. ἣ μὲν δὴ τὰ ἐπαγωγότατα διδαχθεῖσα ὑπὸ τοῦ πατρὸς ἔλεγε πρὸς αὐτόν· ὁ δὲ ὑποκρινάμενος ἔφη οὐδαμὰ ἥξειν ἐς Κόρινθον, ἔστ’ ἂν πυνθάνηται περιεόντα τὸν πατέρα. ἀπαγγειλάσης δὲ ταύτης ταῦτα, τὸ τρίτον Περίανδρος κήρυκα πέμπει βουλόμενος αὐτὸς μὲν ἐς Κέρκυραν ἥκειν, ἐκεῖνον δὲ ἐκέλευε ἐς Κόρινθον ἀπικόμενον διάδοχον γίνεσθαι τῆς τυραννίδος. καταινέσαντος δὲ ἐπὶ τούτοισι τοῦ παιδός, ὁ μὲν Περίανδρος ἐστέλλετο ἐς τὴν Κέρκυραν, ὁ δὲ παῖς οἱ ἐς τὴν Κόρινθον. μαθόντες δὲ οἱ Κερκυραῖοι τούτων ἕκαστα, ἵνα μή σφι Περίανδρος ἐς τὴν χώρην ἀπίκηται, κτείνουσι τὸν νεηνίσκον. ἀντὶ τούτων μὲν Περίανδρος Κερκυραίους ἐτιμωρέετο.", "st": "3.53"}, {"sp": "N", "t": "Λακεδαιμόνιοι δὲ στόλῳ μεγάλῳ ὡς ἀπίκοντο, ἐπολιόρκεον Σάμον· προσβαλόντες δὲ πρὸς τὸ τεῖχος τοῦ μὲν πρὸς θαλάσσῃ ἑστεῶτος πύργου κατὰ τὸ προάστειον τῆς πόλιος ἐπέβησαν, μετὰ δὲ αὐτοῦ βοηθήσαντος Πολυκράτεος χειρὶ πολλῇ ἀπηλάσθησαν. κατὰ δὲ τὸν ἐπάνω πύργον τὸν ἐπὶ τῆς ῥάχιος τοῦ ὄρεος ἐπεόντα ἐπεξῆλθον οἵ τε ἐπίκουροι καὶ αὐτῶν Σαμίων συχνοί, δεξάμενοι δὲ τοὺς Λακεδαιμονίους ἐπ’ ὀλίγον χρόνον ἔφευγον ὀπίσω, οἳ δὲ ἐπισπόμενοι ἔκτεινον.", "st": "3.54"}, {"sp": "N", "t": "εἰ μέν νυν οἱ παρεόντες Λακεδαιμονίων ὅμοιοι ἐγένοντο ταύτην τὴν ἡμέρην Ἀρχίῃ τε καὶ Λυκώπῃ, αἱρέθη ἂν Σάμος· Ἀρχίης γὰρ καὶ Λυκώπης μοῦνοι συνεσπεσόντες φεύγουσι ἐς τὸ τεῖχος τοῖσι Σαμίοισι καὶ ἀποκληισθέντες τῆς ὀπίσω ὁδοῦ ἀπέθανον ἐν τῇ πόλι τῇ Σαμίων. τρίτῳ δέ ἀπ’ Ἀρχίεω τούτου γεγονότι ἄλλῳ Ἀρχίῃ τῷ Σαμίου τοῦ Ἀρχίεω αὐτὸς ἐν Πιτάνῃ συνεγενόμην (δήμου γὰρ τούτου ἦν), ὃς ξείνων πάντων μάλιστα ἐτίμα τε Σαμίους καί οἱ τῷ πατρὶ ἔφη Σάμιον τοὔνομα τεθῆναι, ὅτι οἱ ὁ πατὴρ Ἀρχίης ἐν Σάμῳ ἀριστεύσας ἐτελεύτησε· τιμᾶν δὲ Σαμίους ἔφη, διότι ταφῆναί οἱ τὸν πάππον δημοσίῃ ὑπὸ Σαμίων.", "st": "3.55"}, {"sp": "N", "t": "Λακεδαιμόνιοι δέ, ὥς σφι τεσσεράκοντα ἐγεγόνεσαν ἡμέραι πολιορκέουσι Σάμον ἐς τὸ πρόσω τε οὐδὲν προεκόπτετο τῶν πρηγμάτων, ἀπαλλάσσοντο ἐς Πελοπόννησον. ὡς δὲ ὁ ματαιότερος λόγος ὅρμηται, λέγεται Πολυκράτεα ἐπιχώριον νόμισμα κόψαντα πολλὸν μολύβδου καταχρυσώσαντα δοῦναί σφι, τοὺς δὲ δεξαμένους οὕτω δὴ ἀπαλλάσσεσθαι. ταύτην πρώτην στρατηίην ἐς τὴν Ἀσίην Λακεδαιμόνιοι Δωριέες ἐποιήσαντο.", "st": "3.56"}, {"sp": "N", "t": "οἱ δ’ ἐπὶ τὸν Πολυκράτεα στρατευσάμενοι Σαμίων, ἐπεὶ οἱ Λακεδαιμόνιοι αὐτοὺς ἀπολιπεῖν ἔμελλον, καὶ αὐτοὶ ἀπέπλεον ἐς Σίφνον, χρημάτων γὰρ ἐδέοντο, τὰ δὲ τῶν Σιφνίων πρήγματα ἤκμαζε τοῦτον τὸν χρόνον, καὶ νησιωτέων μάλιστα ἐπλούτεον, ἅτε ἐόντων αὐτοῖσι ἐν τῇ νήσῳ χρυσέων καὶ ἀργυρέων μετάλλων, οὕτω ὥστε ἀπὸ τῆς δεκάτης τῶν γινομένων αὐτόθεν χρημάτων θησαυρὸς ἐν Δελφοῖσι ἀνάκειται ὅμοια τοῖσι πλουσιωτάτοισι· αὐτοὶ δὲ τὰ γινόμενα τῷ ἐνιαυτῷ ἑκάστῳ χρήματα διενέμοντο. ὅτε ὦν ἐποιεῦντο τὸν θησαυρόν, ἐχρέωντο τῷ χρηστηρίῳ εἰ αὐτοῖσι τὰ παρεόντα ἀγαθὰ οἷά τε ἐστὶ πολλὸν χρόνον παραμένειν· ἡ δὲ Πυθίη ἔχρησέ σφι τάδε.", "st": "3.57"}, {"sp": "N", "t": "ἀλλ’ ὅταν ἐν Σίφνῳ πρυτανήια λευκὰ γένηται<br>λεύκοφρύς τ’ ἀγορή, τότε δὴ δεῖ φράδμονος ἀνδρός<br>φράσσασθαι ξύλινόν τε λόχον κήρυκά τ’ ἐρυθρόν.", "st": "3.57.4"}, {"sp": "N", "t": "τοῖσι δὲ Σιφνίοισι ἦν τότε ἡ ἀγορὴ καὶ τὸ πρυτανήιον Παρίῳ λίθῳ ἠσκημένα.", "st": "3.57.4b"}, {"sp": "N", "t": "τοῦτον τὸν χρησμὸν οὐκ οἷοί τε ἦσαν γνῶναι οὔτε τότε εὐθὺς οὔτε τῶν Σαμίων ἀπιγμένων. ἐπείτε γὰρ τάχιστα πρὸς τὴν Σίφνον προσῖσχον οἱ Σάμιοι, ἔπεμπον τῶν νεῶν μίαν πρέσβεας ἄγουσαν ἐς τὴν πόλιν. τὸ δὲ παλαιὸν ἅπασαι αἱ νέες ἦσαν μιλτηλιφέες, καὶ ἦν τοῦτο τὸ ἡ Πυθίη προηγόρευε τοῖσι Σιφνίοισι, φυλάξασθαι τὸν ξύλινον λόχον κελεύουσα καὶ κήρυκα ἐρυθρόν. ἀπικόμενοι ὦν οἱ ἄγγελοι ἐδέοντο τῶν Σιφνίων δέκα τάλαντά σφι χρῆσαι· οὐ φασκόντων δὲ χρήσειν τῶν Σιφνίων αὐτοῖσι, οἱ Σάμιοι τοὺς χώρους αὐτῶν ἐπόρθεον. πυθόμενοι δὲ εὐθὺς ἧκον οἱ Σίφνιοι βοηθέοντες καὶ συμβαλόντες αὐτοῖσι ἑσσώθησαν, καὶ αὐτῶν πολλοὶ ἀπεκληίσθησαν τοῦ ἄστεος ὑπὸ τῶν Σαμίων, καὶ αὐτοὺς μετὰ ταῦτα ἑκατὸν τάλαντα ἔπρηξαν.", "st": "3.58"}, {"sp": "N", "t": "παρὰ δὲ Ἑρμιονέων νῆσον ἀντὶ χρημάτων παρέλαβον Ὑδρέην τὴν ἐπὶ Πελοποννήσῳ καὶ αὐτὴν Τροιζηνίοισι παρακατέθεντο· αὐτοὶ δὲ Κυδωνίην τὴν ἐν Κρήτῃ ἔκτισαν, οὐκ ἐπὶ τοῦτο πλέοντες ἀλλὰ Ζακυνθίους ἐξελῶντες ἐκ τῆς νήσου. ἔμειναν δ’ ἐν ταύτῃ καὶ εὐδαιμόνησαν ἐπ’ ἔτεα πέντε, ὥστε τὰ ἱρὰ τὰ ἐν Κυδωνίῃ ἐόντα νῦν οὗτοι εἰσὶ οἱ ποιήσαντες [καὶ τὸν τῆς Δικτύνης νηόν]. ἕκτῳ δὲ ἔτεϊ Αἰγινῆται αὐτοὺς ναυμαχίῃ νικήσαντες ἠνδραποδίσαντο μετὰ Κρητῶν, καὶ τῶν νεῶν καπρίους ἐχουσέων τὰς πρῴρας ἠκρωτηρίασαν καὶ ἀνέθεσαν ἐς τὸ ἱρὸν τῆς Ἀθηναίης ἐν Αἰγίνῃ. ταῦτα δὲ ἐποίησαν ἔγκοτον ἔχοντες Σαμίοισι Αἰγινῆται· πρότεροι γὰρ Σάμιοι ἐπ’ Ἀμφικράτεος βασιλεύοντος ἐν Σάμῳ στρατευσάμενοι ἐπ’ Αἴγιναν μεγάλα κακὰ ἐποίησαν Αἰγινήτας καὶ ἔπαθον ὑπ’ ἐκείνων. ἡ μὲν αἰτίη αὕτη.", "st": "3.59"}, {"sp": "N", "t": "ἐμήκυνα δὲ περὶ Σαμίων μᾶλλον, ὅτι σφι τρία ἐστὶ μέγιστα ἁπάντων Ἑλλήνων ἐξεργασμένα, ὄρεός τε ὑψηλοῦ ἐς πεντήκοντα καὶ ἑκατὸν ὀργυιάς, τούτου ὄρυγμα κάτωθεν ἀρξάμενον, ἀμφίστομον. τὸ μὲν μῆκος τοῦ ὀρύγματος ἑπτὰ στάδιοι εἰσί, τὸ δὲ ὕψος καὶ εὖρος ὀκτὼ ἑκάτερον πόδες. διὰ παντὸς δὲ αὐτοῦ ἄλλο ὄρυγμα εἰκοσίπηχυ βάθος ὀρώρυκται, τρίπουν δὲ τὸ εὖρος, δι’ οὗ τὸ ὕδωρ ὀχετευόμενον διὰ τῶν σωλήνων παραγίνεται ἐς τὴν πόλιν ἀγόμενον ἀπὸ μεγάλης πηγῆς. ἀρχιτέκτων δὲ τοῦ ὀρύγματος τούτου ἐγένετο Μεγαρεὺς Εὐπαλῖνος Ναυστρόφου. τοῦτο μὲν δὴ ἓν τῶν τριῶν ἐστι, δεύτερον δὲ περὶ λιμένα χῶμα ἐν θαλάσσῃ, βάθος καὶ εἴκοσι ὀργυιέων· μῆκος δὲ τοῦ χώματος μέζον δύο σταδίων. τρίτον δέ σφι ἐξέργασται νηὸς μέγιστος πάντων νηῶν τῶν ἡμεῖς ἴδμεν· τοῦ ἀρχιτέκτων πρῶτος ἐγένετο Ῥοῖκος Φιλέω ἐπιχώριος. τούτων εἵνεκεν μᾶλλόν τι περὶ Σαμίων ἐμήκυνα.", "st": "3.60"}, {"sp": "N", "t": "Καμβύσῃ δὲ τῷ Κύρου χρονίζοντι περὶ Αἴγυπτον καὶ παραφρονήσαντι ἐπανιστέαται ἄνδρες Μάγοι δύο ἀδελφεοί, τῶν τὸν ἕτερον καταλελοίπεε τῶν οἰκίων μελεδωνὸν ὁ Καμβύσης. οὗτος δὴ ὦν οἱ ἐπανέστη μαθών τε τὸν Σμέρδιος θάνατον ὡς κρύπτοιτο γενόμενος, καὶ ὡς ὀλίγοι εἴησαν οἱ ἐπιστάμενοι αὐτὸν Περσέων, οἱ δὲ πολλοὶ περιεόντα μιν εἰδείησαν. πρὸς ταῦτα βουλεύσας τάδε ἐπεχείρησε τοῖσι βασιληίοισι. ἦν οἱ ἀδελφεός, τὸν εἶπά οἱ συνεπαναστῆναι, οἰκὼς μάλιστα τὸ εἶδος Σμέρδι τῷ Κύρου, τὸν ὁ Καμβύσης ἐόντα ἑωυτοῦ ἀδελφεὸν ἀπέκτεινε· ἦν τε δὴ ὅμοιος εἶδος τῷ Σμέρδι καὶ δὴ καὶ οὔνομα τὠυτὸ εἶχε Σμέρδιν. τοῦτον τὸν ἄνδρα ἀναγνώσας ὁ Μάγος Πατιζείθης ὥς οἱ αὐτὸς πάντα διαπρήξει, εἷσε ἄγων ἐς τὸν βασιλήιον θρόνον. ποιήσας δὲ τοῦτο κήρυκας τῇ τε ἄλλῃ διέπεμπε καὶ δὴ καὶ ἐς Αἴγυπτον προερέοντα τῷ στρατῷ ὡς Σμέρδιος τοῦ Κύρου ἀκουστέα εἴη τοῦ λοιποῦ ἀλλ’ οὐ Καμβύσεω.", "st": "3.61"}, {"sp": "N", "t": "οἵ τε δὴ ὦν ἄλλοι κήρυκες προηγόρευον ταῦτα καὶ δὴ καὶ ὁ ἐπ’ Αἴγυπτον ταχθείς, εὕρισκε γὰρ Καμβύσεα καὶ τὸν στρατὸν ἐόντα τῆς Συρίης ἐν Ἀγβατάνοισι, προηγόρευε στὰς ἐς μέσον τὰ ἐντεταλμένα ἐκ τοῦ Μάγου. Καμβύσης δὲ ἀκούσας ταῦτα ἐκ τοῦ κήρυκος καὶ ἐλπίσας μιν λέγειν ἀληθέα αὐτός τε προδεδόσθαι ἐκ Πρηξάσπεος (πεμφθέντα γὰρ αὐτὸν ὡς ἀποκτενέοντα Σμέρδιν οὐ ποιῆσαι ταῦτα), βλέψας ἐς τὸν Πρηξάσπεα εἶπε Πρήξασπες, οὕτω μοι διεπρήξαο τό τοι προσέθηκα πρῆγμα; ὁ δὲ εἶπε ὦ δέσποτα, οὐκ ἔστι ταῦτα ἀληθέα, ὅκως κοτὲ σοὶ Σμέρδις ἀδελφεὸς σὸς ἐπανέστηκε, οὐδὲ ὅκως τι ἐξ ἐκείνου τοῦ ἀνδρὸς νεῖκός τοι ἔσται ἢ μέγα ἢ σμικρόν· ἐγὼ γὰρ αὐτός, ποιήσας τὰ σύ με ἐκέλευες, ἔθαψά μιν χερσὶ τῇσι ἐμεωυτοῦ. εἰ μέν νυν οἱ τεθνεῶτες ἀνεστᾶσι, προσδέκεό τοι καὶ Ἀστυάγεα τὸν Μῆδον ἐπαναστήσεσθαι· εἰ δ’ ἔστι ὥσπερ πρὸ τοῦ, οὐ μή τί τοι ἔκ γε ἐκείνου νεώτερον ἀναβλάστῃ. νῦν ὦν μοι δοκέει μεταδιώξαντας τὸν κήρυκα ἐξετάζειν εἰρωτεῦντας παρ’ ὅτευ ἥκων προαγορεύει ἡμῖν Σμέρδιος βασιλέος ἀκούειν.", "st": "3.62"}, {"sp": "N", "t": "ταῦτα εἴπαντος Πρηξάσπεος, ἤρεσε γὰρ Καμβύσῃ, αὐτίκα μεταδίωκτος γενόμενος ὁ κῆρυξ ἧκε· ἀπιγμένον δέ μιν εἴρετο ὁ Πρηξάσπης τάδε. ὤνθρωπε, φὴς γὰρ ἥκειν παρὰ Σμέρδιος τοῦ Κύρου ἄγγελος· νῦν ὦν εἴπας τὴν ἀληθείην ἄπιθι χαίρων, κότερα αὐτός τοι Σμέρδις φαινόμενος ἐς ὄψιν ἐνετέλλετο ταῦτα ἢ τῶν τις ἐκείνου ὑπηρετέων. ὁ δὲ εἶπε ἐγὼ Σμέρδιν μὲν τὸν Κύρου, ἐξ ὅτευ βασιλεὺς Καμβύσης ἤλασε ἐς Αἴγυπτον, οὔκω ὄπωπα· ὁ δέ μοι Μάγος τὸν Καμβύσης ἐπίτροπον τῶν οἰκίων ἀπέδεξε, οὗτος ταῦτα ἐνετείλατο, φὰς Σμέρδιν τὸν Κύρου εἶναι τὸν ταῦτα ἐπιθέμενον εἶπαι πρὸς ὑμέας. ὃ μὲν δή σφι ἔλεγε οὐδὲν ἐπικατεψευσμένος, Καμβύσης δὲ εἶπε Πρήξασπες, σὺ μὲν οἷα ἀνὴρ ἀγαθὸς ποιήσας τὸ κελευόμενον αἰτίην ἐκπέφευγας· ἐμοὶ δὲ τίς ἂν εἴη Περσέων ὁ ἐπανεστεὼς ἐπιβατεύων τοῦ Σμέρδιος οὐνόματος; ὁ δὲ εἶπε ἐγώ μοι δοκέω συνιέναι τὸ γεγονὸς τοῦτο, ὦ βασιλεῦ· οἱ Μάγοι εἰσί τοι οἱ ἐπανεστεῶτες, τόν τε ἔλιπες μελεδωνὸν τῶν οἰκίων, Πατιζείθης, καὶ ὁ τούτου ἀδελφεὸς Σμέρδις.", "st": "3.63"}, {"sp": "N", "t": "ἐνθαῦτα ἀκούσαντα Καμβύσεα τὸ Σμέρδιος οὔνομα ἔτυψε ἡ ἀληθείη τῶν τε λόγων καὶ τοῦ ἐνυπνίου· ὃς ἐδόκεε ἐν τῷ ὕπνῳ ἀπαγγεῖλαι τινά οἱ ὡς Σμέρδις ἱζόμενος ἐς τὸν βασιλήιον θρόνον ψαύσειε τῇ κεφαλῇ τοῦ οὐρανοῦ. μαθὼν δὲ ὡς μάτην ἀπολωλεκὼς εἴη τὸν ἀδελφεόν, ἀπέκλαιε Σμέρδιν· ἀποκλαύσας δὲ καὶ περιημεκτήσας τῇ ἁπάσῃ συμφορῇ ἀναθρώσκει ἐπὶ τὸν ἵππον, ἐν νόῳ ἔχων τὴν ταχίστην ἐς Σοῦσα στρατεύεσθαι ἐπὶ τὸν Μάγον. καί οἱ ἀναθρώσκοντι ἐπὶ τὸν ἵππον τοῦ κολεοῦ τοῦ ξίφεος ὁ μύκης ἀποπίπτει, γυμνωθὲν δὲ τὸ ξίφος παίει τὸν μηρόν· τρωματισθεὶς δὲ κατὰ τοῦτο τῇ αὐτὸς πρότερον τὸν τῶν Αἰγυπτίων θεὸν Ἆπιν ἔπληξε, ὥς οἱ καιρίῃ ἔδοξε τετύφθαι, εἴρετο ὁ Καμβύσης ὅ τι τῇ πόλι οὔνομα εἴη· οἳ δὲ εἶπαν ὅτι Ἀγβάτανα. τῷ δὲ ἔτι πρότερον ἐκέχρηστο ἐκ Βουτοῦς πόλιος ἐν Ἀγβατάνοισι τελευτήσειν τὸν βίον. ὃ μὲν δὴ ἐν τοῖσι Μηδικοῖσι Ἀγβατάνοισι ἐδόκεε τελευτήσειν γηραιός, ἐν τοῖσί οἱ ἦν τὰ πάντα πρήγματα· τὸ δὲ χρηστήριον ἐν τοῖσι ἐν Συρίῃ Ἀγβατάνοισι ἔλεγε ἄρα. καὶ δὴ ὡς τότε ἐπειρόμενος ἐπύθετο τῆς πόλιος τὸ οὔνομα, ὑπὸ τῆς συμφορῆς τῆς τε ἐκ τοῦ Μάγου ἐκπεπληγμένος καὶ τοῦ τρώματος ἐσωφρόνησε, συλλαβὼν δὲ τὸ θεοπρόπιον εἶπε ἐνθαῦτα Καμβύσεα τὸν Κύρου ἐστὶ πεπρωμένον τελευτᾶν.", "st": "3.64"}, {"sp": "N", "t": "τότε μὲν τοσαῦτα. ἡμέρῃσι δὲ ὕστερον ὡς εἴκοσι μεταπεμψάμενος Περσέων τῶν παρεόντων τοὺς λογιμωτάτους ἔλεγέ σφι τάδε. ὦ Πέρσαι, καταλελάβηκέ με, τὸ πάντων μάλιστα ἔκρυπτον πρηγμάτων, τοῦτο ἐς ὑμέας ἐκφῆναι. ἐγὼ γὰρ ἐὼν ἐν Αἰγύπτῳ εἶδον ὄψιν ἐν τῷ ὕπνῳ, τὴν μηδαμὰ ὄφελον ἰδεῖν· ἐδόκεον δέ μοι ἄγγελον ἐλθόντα ἐξ οἴκου ἀγγέλλειν ὡς Σμέρδις ἱζόμενος ἐς τὸν βασιλήιον θρόνον ψαύσειε τῇ κεφαλῇ τοῦ οὐρανοῦ. δείσας δὲ μὴ ἀπαιρεθέω τὴν ἀρχὴν πρὸς τοῦ ἀδελφεοῦ, ἐποίησα ταχύτερα ἢ σοφώτερα· ἐν τῇ γὰρ ἀνθρωπηίῃ φύσι οὐκ ἐνῆν ἄρα τὸ μέλλον γίνεσθαι ἀποτρέπειν. ἐγὼ δὲ ὁ μάταιος Πρηξάσπεα ἀποπέμπω ἐς Σοῦσα ἀποκτενέοντα Σμέρδιν. ἐξεργασθέντος δὲ κακοῦ τοσούτου ἀδεῶς διαιτώμην, οὐδαμὰ ἐπιλεξάμενος μή κοτέ τίς μοι Σμέρδιος ὑπαραιρημένου ἄλλος ἐπανασταίη ἀνθρώπων. παντὸς δὲ τοῦ μέλλοντος ἔσεσθαι ἁμαρτὼν ἀδελφεοκτόνος τε οὐδὲν δέον γέγονα καὶ τῆς βασιληίης οὐδὲν ἧσσον ἐστέρημαι· Σμέρδις γὰρ δὴ ἦν ὁ Μάγος τόν μοι ὁ δαίμων προέφαινε ἐν τῇ ὄψι ἐπαναστήσεσθαι. τὸ μὲν δὴ ἔργον ἐξέργασταί μοι, καὶ Σμέρδιν τὸν Κύρου μηκέτι ὑμῖν ἐόντα λογίζεσθε· οἱ δὲ ὑμῖν Μάγοι κρατέουσι τῶν βασιληίων, τόν τε ἔλιπον ἐπίτροπον τῶν οἰκίων καὶ ὁ ἐκείνου ἀδελφεὸς Σμέρδις. τὸν μέν νυν μάλιστα χρῆν ἐμεῦ αἰσχρὰ πρὸς τῶν Μάγων πεπονθότος τιμωρέειν ἐμοί, οὗτος μὲν ἀνοσίῳ μόρῳ τετελεύτηκε ὑπὸ τῶν ἑωυτοῦ οἰκηιοτάτων· τούτου δὲ μηκέτι ἐόντος, δεύτερα τῶν λοιπῶν ὑμῖν ὦ Πέρσαι γίνεταί μοι ἀναγκαιότατον ἐντέλλεσθαι τὰ θέλω μοι γενέσθαι τελευτῶν τὸν βίον· καὶ δὴ ὑμῖν τάδε ἐπισκήπτω θεοὺς τοὺς βασιληίους ἐπικαλέων καὶ πᾶσι ὑμῖν καὶ μάλιστα Ἀχαιμενιδέων τοῖσι παρεοῦσι, μὴ περιιδεῖν τὴν ἡγεμονίην αὖτις ἐς Μήδους περιελθοῦσαν, ἀλλ’ εἴτε δόλῳ ἔχουσι αὐτὴν κτησάμενοι, δόλῳ ἀπαιρεθῆναι ὑπὸ ὑμέων, εἴτε καὶ σθένεϊ τεῷ κατεργασάμενοι, σθένεϊ κατὰ τὸ καρτερὸν ἀνασώσασθαι. καὶ ταῦτα μὲν ποιεῦσι ὑμῖν γῆ τε καρπὸν ἐκφέροι καὶ γυναῖκές τε καὶ ποῖμναι τίκτοιεν, ἐοῦσι ἐς τὸν ἅπαντα χρόνον ἐλευθέροισι· μὴ δὲ ἀνασωσαμένοισι τὴν ἀρχὴν μηδ’ ἐπιχειρήσασι ἀνασώζειν τὰ ἐναντία τούτοισι ἀρῶμαι ὑμῖν γενέσθαι, καὶ πρὸς ἔτι τούτοισι τὸ τέλος Περσέων ἑκάστῳ ἐπιγενέσθαι οἷον ἐμοὶ ἐπιγέγονε. ἅμα τε εἴπας ταῦτα ὁ Καμβύσης ἀπέκλαιε πᾶσαν τὴν ἑωυτοῦ πρῆξιν.", "st": "3.65"}, {"sp": "N", "t": "πέρσαι δὲ ὡς τὸν βασιλέα εἶδον ἀνακλαύσαντα πάντες τά τε ἐσθῆτος ἐχόμενα εἶχον, ταῦτα κατηρείκοντο καὶ οἰμωγῇ ἀφθόνῳ διεχρέωντο. μετὰ δὲ ταῦτα ὡς ἐσφακέλισέ τε τὸ ὀστέον καὶ ὁ μηρὸς τάχιστα ἐσάπη, ἀπήνεικε Καμβύσεα τὸν Κύρου, βασιλεύσαντα μὲν τὰ πάντα ἑπτὰ ἔτεα καὶ πέντε μῆνας, ἄπαιδα δὲ τὸ παράπαν ἐόντα ἔρσενος καὶ θήλεος γόνου. Περσέων δὲ τοῖσι παρεοῦσι ἀπιστίη πολλὴ ὑπεκέχυτο τοὺς Μάγους ἔχειν τὰ πρήγματα, ἀλλ’ ἠπιστέατο ἐπὶ διαβολῇ εἰπεῖν Καμβύσεα τὰ εἶπε περὶ τοῦ Σμέρδιος θανάτου, ἵνα οἱ ἐκπολεμωθῇ πᾶν τὸ Περσικόν.", "st": "3.66"}, {"sp": "N", "t": "οὗτοι μέν νυν ἠπιστέατο Σμέρδιν τὸν Κύρου βασιλέα ἐνεστεῶτα· δεινῶς γὰρ καὶ ὁ Πρηξάσπης ἔξαρνος ἦν μὴ μὲν ἀποκτεῖναι Σμέρδιν· οὐ γὰρ ἦν οἱ ἀσφαλὲς Καμβύσεω τετελευτηκότος φάναι τὸν Κύρου υἱὸν ἀπολωλεκέναι αὐτοχειρίῃ. ὁ δὲ δὴ Μάγος τελευτήσαντος Καμβύσεω ἀδεῶς ἐβασίλευσε, ἐπιβατεύων τοῦ ὁμωνύμου Σμέρδιος τοῦ Κύρου, μῆνας ἑπτὰ τοὺς ἐπιλοίπους Καμβύσῃ ἐς τὰ ὀκτὼ ἔτεα τῆς πληρώσιος· ἐν τοῖσι ἀπεδέξατο ἐς τοὺς ὑπηκόους πάντας εὐεργεσίας μεγάλας, ὥστε ἀποθανόντος αὐτοῦ πόθον ἔχειν πάντας τοὺς ἐν τῇ Ἀσίῃ πάρεξ αὐτῶν Περσέων. διαπέμψας γὰρ ὁ Μάγος ἐς πᾶν ἔθνος τῶν ἦρχε προεῖπε ἀτελείην εἶναι στρατηίης καὶ φόρου ἐπ’ ἔτεα τρία.", "st": "3.67"}, {"sp": "N", "t": "προεῖπε μὲν δὴ ταῦτα αὐτίκα ἐνιστάμενος ἐς τὴν ἀρχήν, ὀγδόῳ δὲ μηνὶ ἐγένετο κατάδηλος τρόπῳ τοιῷδε. Ὀτάνης ἦν Φαρνάσπεω μὲν παῖς, γένεϊ δὲ καὶ χρήμασι ὅμοιος τῷ πρώτῳ Περσέων. οὗτος ὁ Ὀτάνης πρῶτος ὑπώπτευσε τὸν Μάγον ὡς οὐκ εἴη ὁ Κύρου Σμέρδις ἀλλ’ ὅς περ ἦν, τῇδε συμβαλόμενος, ὅτι τε οὐκ ἐξεφοίτα ἐκ τῆς ἀκροπόλιος καὶ ὅτι οὐκ ἐκάλεε ἐς ὄψιν ἑωυτῷ οὐδένα τῶν λογίμων Περσέων· ὑποπτεύσας δέ μιν ἐποίεε τάδε. ἔσχε αὐτοῦ Καμβύσης θυγατέρα, τῇ οὔνομα ἦν Φαιδύμη· τὴν αὐτὴν δὴ ταύτην εἶχε τότε ὁ Μάγος καὶ ταύτῃ τε συνοίκεε καὶ τῇσι ἄλλῃσι πάσῃσι τῇσι τοῦ Καμβύσεω γυναιξί. πέμπων δὴ ὦν ὁ Ὀτάνης παρὰ ταύτην τὴν θυγατέρα ἐπυνθάνετο παρ’ ὅτεῳ ἀνθρώπων κοιμῷτο, εἴτε μετὰ Σμέρδιος τοῦ Κύρου εἴτε μετὰ ἄλλου τευ. ἣ δέ οἱ ἀντέπεμπε φαμένη οὐ γινώσκειν· οὔτε γὰρ τὸν Κύρου Σμέρδιν ἰδέσθαι οὐδαμὰ οὔτε ὅστις εἴη ὁ συνοικέων αὐτῇ εἰδέναι. ἔπεμπε δεύτερα ὁ Ὀτάνης λέγων εἰ μὴ αὐτὴ Σμέρδιν τὸν Κύρου γινώσκεις, σὺ δὲ παρὰ Ἀτόσσης πύθευ ὅτεῳ τούτῳ συνοικέει αὐτή τε ἐκείνη καὶ σύ· πάντως γὰρ δή κου τόν γε ἑωυτῆς ἀδελφεὸν γινώσκει. ἀντιπέμπει πρὸς ταῦτα ἡ θυγάτηρ οὔτε Ἀτόσσῃ δύναμαι ἐς λόγους ἐλθεῖν οὔτε ἄλλην οὐδεμίαν ἰδέσθαι τῶν συγκατημενέων γυναικῶν. ἐπείτε γὰρ τάχιστα οὗτος ὥνθρωπος, ὅστις κοτὲ ἐστί, παρέλαβε τὴν βασιληίην, διέσπειρε ἡμέας ἄλλην ἄλλῃ τάξας.", "st": "3.68"}, {"sp": "N", "t": "ἀκούοντι δὲ ταῦτα τῷ Ὀτάνῃ μᾶλλον κατεφαίνετο τὸ πρῆγμα. τρίτην δὲ ἀγγελίην ἐσπέμπει παρ’ αὐτὴν λέγουσαν ταῦτα. ὦ θύγατερ, δεῖ σε γεγονυῖαν εὖ κίνδυνον ἀναλαβέσθαι τὸν ἂν ὁ πατὴρ ὑποδύνειν κελεύῃ. εἰ γὰρ δὴ μή ἐστι ὁ Κύρου Σμέρδις ἀλλὰ τὸν καταδοκέω ἐγώ, οὔτοι μιν σοί τε συγκοιμώμενον καὶ τὸ Περσέων κράτος ἔχοντα δεῖ χαίροντα ἀπαλλάσσειν, ἀλλὰ δοῦναι δίκην. νῦν ὦν ποίησον τάδε· ἐπεὰν σοὶ συνεύδῃ καὶ μάθῃς αὐτὸν κατυπνωμένον, ἄφασον αὐτοῦ τὰ ὦτα· καὶ ἢν μὲν φαίνηται ἔχων ὦτα, νόμιζε σεωυτὴν Σμέρδι τῷ Κύρου συνοικέειν, ἢν δὲ μὴ ἔχων, σὺ δὲ τῷ Μάγῳ Σμέρδι. ἀντιπέμπει πρὸς ταῦτα ἡ Φαιδύμη φαμένη κινδυνεύσειν μεγάλως, ἢν ποιέῃ ταῦτα· εἰ γὰρ δὴ μὴ τυγχάνει τὰ ὦτα ἔχων, ἐπίλαμπτος δὲ ἀφάσσουσα ἔσται, εὖ εἰδέναι ὡς ἀιστώσει μιν· ὅμως μέντοι ποιήσειν ταῦτα. ἣ μὲν δὴ ὑπεδέξατο ταῦτα τῷ πατρὶ κατεργάσεσθαι. τοῦ δὲ Μάγου τούτου τοῦ Σμέρδιος Κῦρος ὁ Καμβύσεω ἄρχων τὰ ὦτα ἀπέταμε ἐπ’ αἰτίῃ δή τινι οὐ σμικρῇ. ἡ ὦν δὴ Φαιδύμη αὕτη, ἡ τοῦ Ὀτάνεω θυγάτηρ, πάντα ἐπιτελέουσα τὰ ὑπεδέξατο τῷ πατρί, ἐπείτε αὐτῆς μέρος ἐγίνετο τῆς ἀπίξιος παρὰ τὸν Μάγον (ἐν περιτροπῇ γὰρ δὴ αἱ γυναῖκες φοιτέουσι τοῖσι Πέρσῃσι), ἐλθοῦσα παρ’ αὐτὸν ηὗδε, ὑπνωμένου δὲ καρτερῶς τοῦ Μάγου ἤφασε τὰ ὦτα. μαθοῦσα δὲ οὐ χαλεπῶς ἀλλ’ εὐπετέως οὐκ ἔχοντα τὸν ἄνδρα ὦτα, ὡς ἡμέρη τάχιστα ἐγεγόνεε, πέμψασα ἐσήμηνε τῷ πατρὶ τὰ γενόμενα.", "st": "3.69"}, {"sp": "N", "t": "ὁ δὲ Ὀτάνης παραλαβὼν Ἀσπαθίνην καὶ Γοβρύην, Περσέων τε πρώτους ἐόντας καὶ ἑωυτῷ ἐπιτηδεοτάτους ἐς πίστιν, ἀπηγήσατο πᾶν τὸ πρῆγμα· οἳ δὲ καὶ αὐτοὶ ἄρα ὑπώπτευον οὕτω τοῦτο ἔχειν, ἀνενείκαντος δὲ τοῦ Ὀτάνεω τοὺς λόγους ἐδέξαντο, καὶ ἔδοξέ σφι ἕκαστον ἄνδρα Περσέων προσεταιρίσασθαι τοῦτον ὅτεῳ πιστεύει μάλιστα. Ὀτάνης μέν νυν ἐσάγεται Ἰνταφρένεα, Γοβρύης δὲ Μεγάβυζον, Ἀσπαθίνης δὲ Ὑδάρνεα. γεγονότων δὲ τούτων ἓξ παραγίνεται ἐς τὰ Σοῦσα Δαρεῖος ὁ Ὑστάσπεος ἐκ Περσέων ἥκων· τούτων γὰρ δὴ ἦν οἱ ὁ πατὴρ ὕπαρχος. ἐπεὶ ὦν οὗτος ἀπίκετο, τοῖσι ἓξ τῶν Περσέων ἔδοξε καὶ Δαρεῖον προσεταιρίσασθαι.", "st": "3.70"}, {"sp": "N", "t": "συνελθόντες δὲ οὗτοι ἐόντες ἑπτὰ ἐδίδοσαν σφίσι πίστις καὶ λόγους. ἐπείτε δὲ ἐς Δαρεῖον ἀπίκετο γνώμην ἀποφαίνεσθαι, ἔλεγέ σφι τάδε. ἐγὼ ταῦτα ἐδόκεον μὲν αὐτὸς μοῦνος ἐπίστασθαι, ὅτι τε ὁ Μάγος εἴη ὁ βασιλεύων καὶ Σμέρδις ὁ Κύρου τετελεύτηκε· καὶ αὐτοῦ τούτου εἵνεκεν ἥκω σπουδῇ ὡς συστήσων ἐπὶ τῷ Μάγῳ θάνατον. ἐπείτε δὲ συνήνεικε ὥστε καὶ ὑμέας εἰδέναι καὶ μὴ μοῦνον ἐμέ, ποιέειν αὐτίκα μοι δοκέει καὶ μὴ ὑπερβάλλεσθαι· οὐ γὰρ ἄμεινον. εἶπε πρὸς ταῦτα ὁ Ὀτάνης ὦ παῖ Ὑστάσπεος, εἶς τε πατρὸς ἀγαθοῦ καὶ ἐκφαίνειν ἔοικας σεωυτὸν ἐόντα τοῦ πατρὸς οὐδὲν ἥσσω· τὴν μέντοι ἐπιχείρησιν ταύτην μὴ οὕτω συντάχυνε ἀβούλως, ἀλλ’ ἐπὶ τὸ σωφρονέστερον αὐτὴν λάμβανε· δεῖ γὰρ πλεῦνας γενομένους οὕτω ἐπιχειρέειν. λέγει πρὸς ταῦτα Δαρεῖος ἄνδρες οἱ παρεόντες, τρόπῳ τῷ εἰρημένῳ ἐξ Ὀτάνεω εἰ χρήσεσθε, ἐπίστασθε ὅτι ἀπολέεσθε κάκιστα· ἐξοίσει γάρ τις πρὸς τὸν Μάγον, ἰδίῃ περιβαλλόμενος ἑωυτῷ κέρδεα. μάλιστα μέν νυν ὠφείλετε ἐπ’ ὑμέων αὐτῶν βαλλόμενοι ποιέειν ταῦτα· ἐπείτε δὲ ὑμῖν ἀναφέρειν ἐς πλεῦνας ἐδόκεε καὶ ἐμοὶ ὑπερέθεσθε, ἢ ποιέωμεν σήμερον ἢ ἴστε ὑμῖν ὅτι ἢν ὑπερπέσῃ ἡ νῦν ἡμέρη, ὡς οὐκ ἄλλος φθὰς ἐμεῦ κατήγορος ἔσται, ἀλλά σφεα αὐτὸς ἐγὼ κατερέω πρὸς τὸν Μάγον.", "st": "3.71"}, {"sp": "N", "t": "λέγει πρὸς ταῦτα Ὀτάνης, ἐπειδὴ ὥρα σπερχόμενον Δαρεῖον, ἐπείτε ἡμέας συνταχύνειν ἀναγκάζεις καὶ ὑπερβάλλεσθαι οὐκ ἐᾷς, ἴθι ἐξηγέο αὐτὸς ὅτεῳ τρόπῳ πάριμεν ἐς τὰ βασιλήια καὶ ἐπιχειρήσομεν αὐτοῖσι. φυλακὰς γὰρ δὴ διεστεώσας οἶδάς κου καὶ αὐτός, εἰ μὴ ἰδών, ἀλλ’ ἀκούσας· τὰς τέῳ τρόπῳ περήσομεν; ἀμείβεται Δαρεῖος τοῖσιδε. Ὀτάνη, ἦ πολλά ἐστι τὰ λόγῳ μὲν οὐκ οἷά τε δηλῶσαι, ἔργῳ δέ· ἄλλα δ’ ἐστὶ τὰ λόγῳ μὲν οἷά τε, ἔργον δὲ οὐδὲν ἀπ’ αὐτῶν λαμπρὸν γίνεται. ὑμεῖς δὲ ἴστε φυλακὰς τὰς κατεστεώσας ἐούσας οὐδὲν χαλεπὰς παρελθεῖν. τοῦτο μὲν γὰρ ἡμέων ἐόντων τοιῶνδε οὐδεὶς ὅστις οὐ παρήσει, τὰ μέν κου καταιδεόμενος ἡμέας, τὰ δέ κου καὶ δειμαίνων· τοῦτο δὲ ἔχω αὐτὸς σκῆψιν εὐπρεπεστάτην τῇ πάριμεν, φὰς ἄρτι τε ἥκειν ἐκ Περσέων καὶ βούλεσθαί τι ἔπος παρὰ τοῦ πατρὸς σημῆναι τῷ βασιλέι. ἔνθα γάρ τι δεῖ ψεῦδος λέγεσθαι, λεγέσθω. τοῦ γὰρ αὐτοῦ γλιχόμεθα οἵ τε ψευδόμενοι καὶ οἱ τῇ ἀληθείῃ διαχρεώμενοι. οἳ μέν γε ψεύδονται τότε ἐπεάν τι μέλλωσι τοῖσι ψεύδεσι πείσαντες κερδήσεσθαι, οἳ δ’ ἀληθίζονται ἵνα τῇ ἀληθείῃ ἐπισπάσωνται κέρδος καί τι μᾶλλόν σφι ἐπιτράπηται. οὕτω οὐ ταὐτὰ ἀσκέοντες τὠυτοῦ περιεχόμεθα. εἰ δὲ μηδὲν κερδήσεσθαι μέλλοιεν, ὁμοίως ἂν ὅ τε ἀληθιζόμενος ψευδὴς εἴη καὶ ὁ ψευδόμενος ἀληθής. ὃς ἂν μέν νυν τῶν πυλουρῶν ἑκὼν παριῇ, αὐτῷ οἱ ἄμεινον ἐς χρόνον ἔσται· ὃς δ’ ἂν ἀντιβαίνειν πειρᾶται, δεικνύσθω ἐνθαῦτα ἐὼν πολέμιος, καὶ ἔπειτα ὠσάμενοι ἔσω ἔργου ἐχώμεθα.", "st": "3.72"}, {"sp": "N", "t": "λέγει Γοβρύης μετὰ ταῦτα ἄνδρες φίλοι, ἡμῖν κότε κάλλιον παρέξει ἀνασώσασθαι τὴν ἀρχήν, ἢ εἴ γε μὴ οἷοί τε ἐσόμεθα αὐτὴν ἀναλαβεῖν, ἀποθανεῖν; ὅτε γε ἀρχόμεθα μὲν ἐόντες Πέρσαι ὑπὸ Μήδου ἀνδρὸς Μάγου, καὶ τούτου ὦτα οὐκ ἔχοντος. ὅσοι τε ὑμέων Καμβύσῃ νοσέοντι παρεγένοντο, πάντως κου μέμνησθε τὰ ἐπέσκηψε Πέρσῃσι τελευτῶν τὸν βίον μὴ πειρωμένοισι ἀνακτᾶσθαι τὴν ἀρχήν· τὰ τότε οὐκ ἐνεδεκόμεθα, ἀλλ’ ἐπὶ διαβολῇ ἐδοκέομεν εἰπεῖν Καμβύσεα. νῦν ὦν τίθεμαι ψῆφον πείθεσθαι Δαρείῳ καὶ μὴ διαλύεσθαι ἐκ τοῦ συλλόγου τοῦδε ἀλλ’ ἢ ἐπὶ τὸν Μάγον ἰθέως. ταῦτα εἶπε Γοβρύης, καὶ πάντες ταύτῃ αἴνεον.", "st": "3.73"}, {"sp": "N", "t": "ἐν ᾧ δὲ οὗτοι ταῦτα ἐβουλεύοντο, ἐγίνετο κατὰ συντυχίην τάδε. τοῖσι Μάγοισι ἔδοξε βουλευομένοισι Πρηξάσπεα φίλον προσθέσθαι, ὅτι τε ἐπεπόνθεε πρὸς Καμβύσεω ἀνάρσια, ὅς οἱ τὸν παῖδα τοξεύσας ἀπολωλέκεε, καὶ διότι μοῦνος ἠπίστατο τὸν Σμέρδιος τοῦ Κύρου θάνατον αὐτοχειρίῃ μιν ἀπολέσας, πρὸς δ’ ἔτι ἐόντα ἐν αἴνῃ μεγίστῃ τὸν Πρηξάσπεα ἐν Πέρσῃσι. τούτων δή μιν εἵνεκεν καλέσαντες φίλον προσεκτῶντο πίστι τε λαβόντες καὶ ὁρκίοισι, ἦ μὲν ἕξειν παρ’ ἑωυτῷ μηδ’ ἐξοίσειν μηδενὶ ἀνθρώπων τὴν ἀπὸ σφέων ἀπάτην ἐς Πέρσας γεγονυῖαν, ὑπισχνεύμενοι τὰ πάντα οἱ μυρία δώσειν. ὑποσχομένου δὲ τοῦ Πρηξάσπεος ποιήσειν ταῦτα, ὡς ἀνέπεισάν μιν οἱ Μάγοι, δεύτερα προσέφερον, αὐτοὶ μὲν φάμενοι Πέρσας πάντας συγκαλέειν ὑπὸ τὸ βασιλήιον τεῖχος, κεῖνον δ’ ἐκέλευον ἀναβάντα ἐπὶ πύργον ἀγορεῦσαι ὡς ὑπὸ τοῦ Κύρου Σμέρδιος ἄρχονται καὶ ὑπ’ οὐδενὸς ἄλλου. ταῦτα δὲ οὕτω ἐνετέλλοντο ὡς πιστοτάτου δῆθεν ἐόντος αὐτοῦ ἐν Πέρσῃσι καὶ πολλάκις ἀποδεξαμένου γνώμην ὡς περιείη ὁ Κύρου Σμέρδις, καὶ ἐξαρνησαμένου τὸν φόνον αὐτοῦ.", "st": "3.74"}, {"sp": "N", "t": "φαμένου δὲ καὶ ταῦτα ἑτοίμου εἶναι ποιέειν τοῦ Πρηξάσπεος, συγκαλέσαντες Πέρσας οἱ Μάγοι ἀνεβίβασαν αὐτὸν ἐπὶ πύργον καὶ ἀγορεύειν ἐκέλευον. ὁ δὲ τῶν μὲν ἐκεῖνοι προσεδέοντο αὐτοῦ, τούτων μὲν ἑκὼν ἐπελήθετο, ἀρξάμενος δὲ ἀπ’ Ἀχαιμένεος ἐγενεηλόγησε τὴν πατριὴν τὴν Κύρου, μετὰ δὲ ὡς ἐς τοῦτον κατέβη τελευτῶν ἔλεγε ὅσα ἀγαθὰ Κῦρος Πέρσας πεποιήκοι, διεξελθὼν δὲ ταῦτα ἐξέφαινε τὴν ἀληθείην, φάμενος πρότερον μὲν κρύπτειν (οὐ γάρ οἱ εἶναι ἀσφαλὲς λέγειν τὰ γενόμενα), ἐν δὲ τῷ παρεόντι, ἀναγκαίην μιν καταλαμβάνειν φαίνειν. καὶ δὴ ἔλεγε τὸν μὲν Κύρου Σμέρδιν ὡς αὐτὸς ὑπὸ Καμβύσεω ἀναγκαζόμενος ἀποκτείνειε, τοὺς Μάγους δὲ βασιλεύειν. Πέρσῃσι δὲ πολλὰ ἐπαρησάμενος εἰ μὴ ἀνακτησαίατο ὀπίσω τὴν ἀρχὴν καὶ τοὺς Μάγους τισαίατο, ἀπῆκε ἑωυτὸν ἐπὶ κεφαλὴν φέρεσθαι ἀπὸ τοῦ πύργου κάτω. Πρηξάσπης μέν νυν ἐὼν τὸν πάντα χρόνον ἀνὴρ δόκιμος οὕτω ἐτελεύτησε.", "st": "3.75"}, {"sp": "N", "t": "οἱ δὲ δὴ ἑπτὰ τῶν Περσέων ὡς ἐβουλεύσαντο αὐτίκα ἐπιχειρέειν τοῖσι Μάγοισι καὶ μὴ ὑπερβάλλεσθαι, ἤισαν εὐξάμενοι τοῖσι θεοῖσι, τῶν περὶ Πρηξάσπεα πρηχθέντων εἰδότες οὐδέν. ἔν τε δὴ τῇ ὁδῷ μέσῃ στείχοντες ἐγίνοντο καὶ τὰ περὶ Πρηξάσπεα γεγονότα ἐπυνθάνοντο. ἐνθαῦτα ἐκστάντες τῆς ὁδοῦ ἐδίδοσαν αὖτις σφίσι λόγους, οἳ μὲν ἀμφὶ τὸν Ὀτάνην πάγχυ κελεύοντες ὑπερβαλέσθαι μηδὲ οἰδεόντων τῶν πρηγμάτων ἐπιτίθεσθαι, οἳ δὲ ἀμφὶ τὸν Δαρεῖον αὐτίκα τε ἰέναι καὶ τὰ δεδογμένα ποιέειν μηδὲ ὑπερβάλλεσθαι. ὠθιζομένων δ’ αὐτῶν ἐφάνη ἰρήκων ἑπτὰ ζεύγεα δύο αἰγυπιῶν ζεύγεα διώκοντα καὶ τίλλοντά τε καὶ ἀμύσσοντα. ἰδόντες δὲ ταῦτα οἱ ἑπτὰ τήν τε Δαρείου πάντες αἴνεον γνώμην καὶ ἔπειτα ἤισαν ἐπὶ τὰ βασιλήια τεθαρσηκότες τοῖσι ὄρνισι.", "st": "3.76"}, {"sp": "N", "t": "ἐπιστᾶσι δὲ ἐπὶ τὰς πύλας ἐγίνετο οἷόν τι Δαρείῳ ἡ γνώμη ἔφερε· καταιδεόμενοι γὰρ οἱ φύλακοι ἄνδρας τοὺς Περσέων πρώτους καὶ οὐδὲν τοιοῦτο ὑποπτεύοντες ἐξ αὐτῶν ἔσεσθαι, παρίεσαν θείῃ πομπῇ χρεωμένους, οὐδ’ ἐπειρώτα οὐδείς. ἐπείτε δὲ καὶ παρῆλθον ἐς τὴν αὐλήν, ἐνέκυρσαν τοῖσι τὰς ἀγγελίας ἐσφέρουσι εὐνούχοισι· οἵ σφεας ἱστόρεον ὅ τι θέλοντες ἥκοιεν, καὶ ἅμα ἱστορέοντες τούτους τοῖσι πυλουροῖσι ἀπείλεον ὅτι σφέας παρῆκαν, ἶσχόν τε βουλομένους τοὺς ἑπτὰ ἐς τὸ πρόσω παριέναι. οἳ δὲ διακελευσάμενοι καὶ σπασάμενοι τὰ ἐγχειρίδια τούτους μὲν τοὺς ἴσχοντας αὐτοῦ ταύτῃ συγκεντέουσι, αὐτοὶ δὲ ἤισαν δρόμῳ ἐς τὸν ἀνδρεῶνα.", "st": "3.77"}, {"sp": "N", "t": "οἱ δὲ Μάγοι ἔτυχον ἀμφότεροι τηνικαῦτα ἐόντες τε ἔσω καὶ τὰ ἀπὸ Πρηξάσπεος γενόμενα ἐν βουλῇ ἔχοντες. ἐπεὶ ὦν εἶδον τοὺς εὐνούχους τεθορυβημένους τε καὶ βοῶντας, ἀνά τε ἔδραμον πάλιν ἀμφότεροι καὶ ὡς ἔμαθον τὸ ποιεύμενον πρὸς ἀλκὴν ἐτράποντο. ὃ μὲν δὴ αὐτῶν φθάνει τὰ τόξα κατελόμενος, ὁ δὲ πρὸς τὴν αἰχμὴν ἐτράπετο. ἐνθαῦτα δὴ συνέμισγον ἀλλήλοισι. τῷ μὲν δὴ τὰ τόξα ἀναλαβόντι αὐτῶν, ἐόντων τε ἀγχοῦ τῶν πολεμίων καὶ προσκειμένων, ἦν χρηστὰ οὐδέν· ὁ δ’ ἕτερος τῇ αἰχμῇ ἠμύνετο καὶ τοῦτο μὲν Ἀσπαθίνην παίει ἐς τὸν μηρόν, τοῦτο δὲ Ἰνταφρένεα ἐς τὸν ὀφθαλμόν· καὶ ἐστερήθη μὲν τοῦ ὀφθαλμοῦ ἐκ τοῦ τρώματος ὁ Ἰνταφρένης, οὐ μέντοι ἀπέθανέ γε. τῶν μὲν δὴ Μάγων οὕτερος τρωματίζει τούτους· ὁ δὲ ἕτερος, ἐπείτε οἱ τὰ τόξα οὐδὲν χρηστὰ ἐγίνετο, ἦν γὰρ δὴ θάλαμος ἐσέχων ἐς τὸν ἀνδρεῶνα, ἐς τοῦτον καταφεύγει, θέλων αὐτοῦ προσθεῖναι τὰς θύρας, καί οἱ συνεσπίπτουσι τῶν ἑπτὰ δύο, Δαρεῖός τε καὶ Γοβρύης. συμπλακέντος δὲ Γοβρύεω τῷ Μάγῳ ὁ Δαρεῖος ἐπεστεὼς ἠπόρεε οἷα ἐν σκότεϊ, προμηθεόμενος μὴ πλήξῃ τὸν Γοβρύην. ὁρέων δέ μιν ἀργὸν ἐπεστεῶτα ὁ Γοβρύης εἴρετο ὅ τι οὐ χρᾶται τῇ χειρί· ὁ δὲ εἶπε Προμηθεόμενος σέο, μὴ πλήξω. Γοβρύης δὲ ἀμείβετο ὤθεε τὸ ξίφος καὶ δι’ ἀμφοτέρων. Δαρεῖος δὲ πειθόμενος ὦσέ τε τὸ ἐγχειρίδιον καὶ ἔτυχέ κως τοῦ Μάγου.", "st": "3.78"}, {"sp": "N", "t": "ἀποκτείναντες δὲ τοὺς Μάγους καὶ ἀποταμόντες αὐτῶν τὰς κεφαλάς, τοὺς μὲν τρωματίας ἑωυτῶν αὐτοῦ λείπουσι καὶ ἀδυνασίης εἵνεκεν καὶ φυλακῆς τῆς ἀκροπόλιος, οἱ δὲ πέντε αὐτῶν ἔχοντες τῶν Μάγων τὰς κεφαλὰς ἔθεον βοῇ τε καὶ πατάγῳ χρεώμενοι, καὶ Πέρσας τοὺς ἄλλους ἐπεκαλέοντο ἐξηγεόμενοί τε τὸ πρῆγμα καὶ δεικνύοντες τὰς κεφαλάς, καὶ ἅμα ἔκτεινον πάντα τινὰ τῶν Μάγων τὸν ἐν ποσὶ γινόμενον. οἱ δὲ Πέρσαι μαθόντες τὸ γεγονὸς ἐκ τῶν ἑπτὰ καὶ τῶν Μάγων τὴν ἀπάτην, ἐδικαίευν καὶ αὐτοὶ ἕτερα τοιαῦτα ποιέειν, σπασάμενοι δὲ τὰ ἐγχειρίδια ἔκτεινον ὅκου τινὰ Μάγον εὕρισκον· εἰ δὲ μὴ νὺξ ἐπελθοῦσα ἔσχε, ἔλιπον ἂν οὐδένα Μάγον. ταύτην τὴν ἡμέρην θεραπεύουσι Πέρσαι κοινῇ μάλιστα τῶν ἡμερέων, καὶ ἐν αὐτῇ ὁρτὴν μεγάλην ἀνάγουσι, ἣ κέκληται ὑπὸ Περσέων μαγοφόνια· ἐν τῇ Μάγον οὐδένα ἔξεστι φανῆναι ἐς τὸ φῶς, ἀλλὰ κατ’ οἴκους ἑωυτοὺς οἱ Μάγοι ἔχουσι τὴν ἡμέρην ταύτην.", "st": "3.79"}, {"sp": "N", "t": "ἐπείτε δὲ κατέστη ὁ θόρυβος καὶ ἐκτὸς πέντε ἡμερέων ἐγένετο, ἐβουλεύοντο οἱ ἐπαναστάντες τοῖσι Μάγοισι περὶ τῶν πάντων πρηγμάτων καὶ ἐλέχθησαν λόγοι ἄπιστοι μὲν ἐνίοισι Ἑλλήνων, ἐλέχθησαν δ’ ὦν. Ὀτάνης μὲν ἐκέλευε ἐς μέσον Πέρσῃσι καταθεῖναι τὰ πρήγματα, λέγων τάδε. ἐμοὶ δοκέει ἕνα μὲν ἡμέων μούναρχον μηκέτι γενέσθαι. οὔτε γὰρ ἡδὺ οὔτε ἀγαθόν. εἴδετε μὲν γὰρ τὴν Καμβύσεω ὕβριν ἐπ’ ὅσον ἐπεξῆλθε, μετεσχήκατε δὲ καὶ τῆς τοῦ Μάγου ὕβριος. κῶς δ’ ἂν εἴη χρῆμα κατηρτημένον μουναρχίη, τῇ ἔξεστι ἀνευθύνῳ ποιέειν τὰ βούλεται; καὶ γὰρ ἂν τὸν ἄριστον ἀνδρῶν πάντων στάντα ἐς ταύτην ἐκτὸς τῶν ἐωθότων νοημάτων στήσειε. ἐγγίνεται μὲν γάρ οἱ ὕβρις ὑπὸ τῶν παρεόντων ἀγαθῶν, φθόνος δὲ ἀρχῆθεν ἐμφύεται ἀνθρώπῳ. δύο δ’ ἔχων ταῦτα ἔχει πᾶσαν κακότητα· τὰ μὲν γὰρ ὕβρι κεκορημένος ἔρδει πολλὰ καὶ ἀτάσθαλα, τὰ δὲ φθόνῳ. καίτοι ἄνδρα γε τύραννον ἄφθονον ἔδει εἶναι, ἔχοντά γε πάντα τὰ ἀγαθά. τὸ δὲ ὑπεναντίον τούτου ἐς τοὺς πολιήτας πέφυκε· φθονέει γὰρ τοῖσι ἀρίστοισι περιεοῦσί τε καὶ ζώουσι, χαίρει δὲ τοῖσι κακίστοισι τῶν ἀστῶν, διαβολὰς δὲ ἄριστος ἐνδέκεσθαι. ἀναρμοστότατον δὲ πάντων· ἤν τε γὰρ αὐτὸν μετρίως θωμάζῃς, ἄχθεται ὅτι οὐ κάρτα θεραπεύεται, ἤν τε θεραπεύῃ τις κάρτα, ἄχθεται ἅτε θωπί. τὰ δὲ δὴ μέγιστα ἔρχομαι ἐρέων· νόμαιά τε κινέει πάτρια καὶ βιᾶται γυναῖκας κτείνει τε ἀκρίτους. πλῆθος δὲ ἄρχον πρῶτα μὲν οὔνομα πάντων κάλλιστον ἔχει, ἰσονομίην, δεύτερα δὲ τούτων τῶν ὁ μούναρχος ποιέει οὐδέν· πάλῳ μὲν ἀρχὰς ἄρχει, ὑπεύθυνον δὲ ἀρχὴν ἔχει, βουλεύματα δὲ πάντα ἐς τὸ κοινὸν ἀναφέρει. τίθεμαι ὦν γνώμην μετέντας ἡμέας μουναρχίην τὸ πλῆθος ἀέξειν· ἐν γὰρ τῷ πολλῷ ἔνι τὰ πάντα.", "st": "3.80"}, {"sp": "N", "t": "Ὀτάνης μὲν δὴ ταύτην γνώμην ἐσέφερε· Μεγάβυζος δὲ ὀλιγαρχίῃ ἐκέλευε ἐπιτρέπειν, λέγων τάδε. τὰ μὲν Ὀτάνης εἶπε τυραννίδα παύων, λελέχθω κἀμοὶ ταῦτα, τὰ δ’ ἐς τὸ πλῆθος ἄνωγε φέρειν τὸ κράτος, γνώμης τῆς ἀρίστης ἡμάρτηκε· ὁμίλου γὰρ ἀχρηίου οὐδέν ἐστι ἀξυνετώτερον οὐδὲ ὑβριστότερον. καίτοι τυράννου ὕβριν φεύγοντας ἄνδρας ἐς δήμου ἀκολάστου ὕβριν πεσεῖν ἐστὶ οὐδαμῶς ἀνασχετόν. ὃ μὲν γὰρ εἴ τι ποιέει, γινώσκων ποιέει, τῷ δὲ οὐδὲ γινώσκειν ἔνι· κῶς γὰρ ἂν γινώσκοι ὃς οὔτ’ ἐδιδάχθη οὔτε εἶδε καλὸν οὐδὲν οἰκήιον, ὠθέει τε ἐμπεσὼν τὰ πρήγματα ἄνευ νόου, χειμάρρῳ ποταμῷ εἴκελος; δήμῳ μέν νυν, οἳ Πέρσῃσι κακὸν νοέουσι, οὗτοι χράσθων, ἡμεῖς δὲ ἀνδρῶν τῶν ἀρίστων ἐπιλέξαντες ὁμιλίην τούτοισι περιθέωμεν τὸ κράτος· ἐν γὰρ δὴ τούτοισι καὶ αὐτοὶ ἐνεσόμεθα· ἀρίστων δὲ ἀνδρῶν οἰκὸς ἄριστα βουλεύματα γίνεσθαι.", "st": "3.81"}, {"sp": "N", "t": "Μεγάβυζος μὲν δὴ ταύτην γνώμην ἐσέφερε· τρίτος δὲ Δαρεῖος ἀπεδείκνυτο γνώμην, λέγων ἐμοὶ δὲ τὰ μὲν εἶπε Μεγάβυζος ἐς τὸ πλῆθος ἔχοντα δοκέει ὀρθῶς λέξαι, τὰ δὲ ἐς ὀλιγαρχίην οὐκ ὀρθῶς. τριῶν γὰρ προκειμένων καὶ πάντων τῷ λόγῳ ἀρίστων ἐόντων, δήμου τε ἀρίστου καὶ ὀλιγαρχίης καὶ μουνάρχου, πολλῷ τοῦτο προέχειν λέγω. ἀνδρὸς γὰρ ἑνὸς τοῦ ἀρίστου οὐδὲν ἄμεινον ἂν φανείη· γνώμῃ γὰρ τοιαύτῃ χρεώμενος ἐπιτροπεύοι ἂν ἀμωμήτως τοῦ πλήθεος, σιγῷτό τε ἂν βουλεύματα ἐπὶ δυσμενέας ἄνδρας οὕτω μάλιστα. ἐν δὲ ὀλιγαρχίῃ πολλοῖσι ἀρετὴν ἐπασκέουσι ἐς τὸ κοινὸν ἔχθεα ἴδια ἰσχυρὰ φιλέει ἐγγίνεσθαι· αὐτὸς γὰρ ἕκαστος βουλόμενος κορυφαῖος εἶναι γνώμῃσί τε νικᾶν ἐς ἔχθεα μεγάλα ἀλλήλοισι ἀπικνέονται, ἐξ ὧν στάσιες ἐγγίνονται, ἐκ δὲ τῶν στασίων φόνος· ἐκ δὲ τοῦ φόνου ἀπέβη ἐς μουναρχίην, καὶ ἐν τούτῳ διέδεξε ὅσῳ ἐστὶ τοῦτο ἄριστον. δήμου τε αὖ ἄρχοντος ἀδύνατα μὴ οὐ κακότητα ἐγγίνεσθαι· κακότητος τοίνυν ἐγγινομένης ἐς τὰ κοινὰ ἔχθεα μὲν οὐκ ἐγγίνεται τοῖσι κακοῖσι, φιλίαι δὲ ἰσχυραί· οἱ γὰρ κακοῦντες τὰ κοινὰ συγκύψαντες ποιεῦσι. τοῦτο δὲ τοιοῦτο γίνεται ἐς ὃ ἂν προστάς τις τοῦ δήμου τοὺς τοιούτους παύσῃ. ἐκ δὲ αὐτῶν θωμάζεται οὗτος δὴ ὑπὸ τοῦ δήμου, θωμαζόμενος δὲ ἀν’ ὦν ἐφάνη μούναρχος ἐών, καὶ ἐν τούτῳ δηλοῖ καὶ οὗτος ὡς ἡ μουναρχίη κράτιστον. ἑνὶ δὲ ἔπεϊ πάντα συλλαβόντα εἰπεῖν, κόθεν ἡμῖν ἡ ἐλευθερίη ἐγένετο καὶ τεῦ δόντος; κότερα παρὰ τοῦ δήμου ἢ ὀλιγαρχίης ἢ μουνάρχου; ἔχω τοίνυν γνώμην ἡμέας ἐλευθερωθέντας διὰ ἕνα ἄνδρα τὸ τοιοῦτο περιστέλλειν, χωρίς τε τούτου πατρίους νόμους μὴ λύειν ἔχοντας εὖ· οὐ γὰρ ἄμεινον.", "st": "3.82"}, {"sp": "N", "t": "γνῶμαι μὲν δὴ τρεῖς αὗται προεκέατο, οἱ δὲ τέσσερες τῶν ἑπτὰ ἀνδρῶν προσέθεντο ταύτῃ. ὡς δὲ ἑσσώθη τῇ γνώμῃ ὁ Ὀτάνης Πέρσῃσι ἰσονομίην σπεύδων ποιῆσαι, ἔλεξε ἐς μέσον αὐτοῖσι τάδε. ἄνδρες στασιῶται, δῆλα γὰρ δὴ ὅτι δεῖ ἕνα γε τινὰ ἡμέων βασιλέα γενέσθαι, ἤτοι κλήρῳ γε λαχόντα, ἢ ἐπιτρεψάντων τῷ Περσέων πλήθεϊ τὸν ἂν ἐκεῖνο ἕληται, ἢ ἄλλῃ τινὶ μηχανῇ. ἐγὼ μέν νυν ὑμῖν οὐκ ἐναγωνιεῦμαι· οὔτε γὰρ ἄρχειν οὔτε ἄρχεσθαι ἐθέλω· ἐπὶ τούτῳ δὲ ὑπεξίσταμαι τῆς ἀρχῆς, ἐπ’ ᾧ τε ὑπ’ οὐδενὸς ὑμέων ἄρξομαι, οὔτε αὐτὸς ἐγὼ οὔτε οἱ ἀπ’ ἐμεῦ αἰεὶ γινόμενοι. τούτου εἴπαντος ταῦτα ὡς συνεχώρεον οἱ ἓξ ἐπὶ τούτοισι, οὗτος μὲν δή σφι οὐκ ἐνηγωνίζετο ἀλλ’ ἐκ μέσου κατῆστο, καὶ νῦν αὕτη ἡ οἰκίη διατελέει μούνη ἐλευθέρη ἐοῦσα Περσέων καὶ ἄρχεται τοσαῦτα ὅσα αὐτὴ θέλει, νόμους οὐκ ὑπερβαίνουσα τοὺς Περσέων.", "st": "3.83"}, {"sp": "N", "t": "οἱ δὲ λοιποὶ τῶν ἑπτὰ ἐβουλεύοντο ὡς βασιλέα δικαιότατα στήσονται· καί σφι ἔδοξε Ὀτάνῃ μὲν καὶ τοῖσι ἀπὸ Ὀτάνεω αἰεὶ γινομένοισι, ἢν ἐς ἄλλον τινὰ τῶν ἑπτὰ ἔλθῃ ἡ βασιληίη, ἐξαίρετα δίδοσθαι ἐσθῆτά τε Μηδικὴν ἔτεος ἑκάστου καὶ τὴν πᾶσαν δωρεὴν ἣ γίνεται ἐν Πέρσῃσι τιμιωτάτη. τοῦδε δὲ εἵνεκεν ἐβούλευσάν οἱ δίδοσθαι ταῦτα, ὅτι ἐβούλευσέ τε πρῶτος τὸ πρῆγμα καὶ συνέστησε αὐτούς. ταῦτα μὲν δὴ Ὀτάνῃ ἐξαίρετα, τάδε δὲ ἐς τὸ κοινὸν ἐβούλευσαν, παριέναι ἐς τὰ βασιλήια πάντα τὸν βουλόμενον τῶν ἑπτὰ ἄνευ ἐσαγγελέος, ἢν μὴ τυγχάνῃ εὕδων μετὰ γυναικὸς βασιλεύς, γαμέειν δὲ μὴ ἐξεῖναι ἄλλοθεν τῷ βασιλέι ἢ ἐκ τῶν συνεπαναστάντων. περὶ δὲ τῆς βασιληίης ἐβούλευσαν τοιόνδε· ὅτευ ἂν ὁ ἵππος ἡλίου ἐπανατέλλοντος πρῶτος φθέγξηται, ἐν τῷ προαστείῳ αὐτῶν ἐπιβεβηκότων, τοῦτον ἔχειν τὴν βασιληίην.", "st": "3.84"}, {"sp": "N", "t": "Δαρείῳ δὲ ἦν ἱπποκόμος ἀνὴρ σοφός, τῷ οὔνομα ἦν Οἰβάρης. πρὸς τοῦτον τὸν ἄνδρα, ἐπείτε διελύθησαν, ἔλεξε Δαρεῖος τάδε. Οἴβαρες, ἡμῖν δέδοκται περὶ τῆς βασιληίης ποιέειν κατὰ τάδε· ὅτευ ἂν ὁ ἵππος πρῶτος φθέγξηται ἅμα τῷ ἡλίῳ ἀνιόντι αὐτῶν ἐπαναβεβηκότων, τοῦτον ἔχειν τὴν βασιληίην. νῦν ὦν εἴ τινα ἔχεις σοφίην, μηχανῶ ὡς ἂν ἡμεῖς σχῶμεν τοῦτο τὸ γέρας καὶ μὴ ἄλλος τις. ἀμείβεται Οἰβάρης τοῖσιδε. εἰ μὲν δὴ ὦ δέσποτα ἐν τούτῳ τοι ἐστὶ ἢ βασιλέα εἶναι ἢ μή, θάρσεε τούτου εἵνεκεν καὶ θυμὸν ἔχε ἀγαθόν, ὡς βασιλεὺς οὐδεὶς ἄλλος πρὸ σεῦ ἔσται· τοιαῦτα ἔχω φάρμακα. λέγει Δαρεῖος εἰ τοίνυν τι τοιοῦτον ἔχεις σόφισμα, ὥρη μηχανᾶσθαι καὶ μὴ ἀναβάλλεσθαι, ὡς τῆς ἐπιούσης ἡμέρης ὁ ἀγὼν ἡμῖν ἐστί. ἀκούσας ταῦτα ὁ Οἰβάρης ποιέει τοιόνδε· ὡς ἐγίνετο ἡ νύξ, τῶν θηλέων ἵππων μίαν, τὴν ὁ Δαρείου ἵππος ἔστεργε μάλιστα, ταύτην ἀγαγὼν ἐς τὸ προάστειον κατέδησε καὶ ἐπήγαγε τὸν Δαρείου ἵππον, καὶ τὰ μὲν πολλὰ περιῆγε ἀγχοῦ τῇ ἵππῳ ἐγχρίμπτων τῇ θηλέῃ, τέλος δὲ ἐπῆκε ὀχεῦσαι τὸν ἵππον.", "st": "3.85"}, {"sp": "N", "t": "ἅμ’ ἡμέρῃ δὲ διαφωσκούσῃ οἱ ἓξ κατὰ συνεθήκαντο παρῆσαν ἐπὶ τῶν ἵππων· διεξελαυνόντων δὲ κατὰ τὸ προάστειον, ὡς κατὰ τοῦτο τὸ χωρίον ἐγίνοντο ἵνα τῆς παροιχομένης νυκτὸς κατεδέδετο ἡ θήλεα ἵππος, ἐνθαῦτα ὁ Δαρείου ἵππος προσδραμὼν ἐχρεμέτισε· ἅμα δὲ τῷ ἵππῳ τοῦτο ποιήσαντι ἀστραπὴ ἐξ αἰθρίης καὶ βροντὴ ἐγένετο. ἐπιγενόμενα δὲ ταῦτα τῷ Δαρείῳ ἐτελέωσέ μιν ὥσπερ ἐκ συνθέτου τευ γενόμενα· οἳ δὲ καταθορόντες ἀπὸ τῶν ἵππων προσεκύνεον τὸν Δαρεῖον.", "st": "3.86"}, {"sp": "N", "t": "οἳ μὲν δή φασι τὸν Οἰβάρεα ταῦτα μηχανήσασθαι, οἳ δὲ τοιάδε (καὶ γὰρ ἐπ’ ἀμφότερα λέγεται ὑπὸ Περσέων), ὡς τῆς ἵππου ταύτης τῶν ἄρθρων ἐπιψαύσας τῇ χειρὶ ἔχοι αὐτὴν κρύψας ἐν τῇσι ἀναξυρίσι· ὡς δὲ ἅμα τῷ ἡλίῳ ἀνιόντι ἀπίεσθαι μέλλειν τοὺς ἵππους, τὸν Οἰβάρεα τοῦτον ἐξείραντα τὴν χεῖρα πρὸς τοῦ Δαρείου ἵππου τοὺς μυκτῆρας προσενεῖκαι, τὸν δὲ αἰσθόμενον φριμάξασθαί τε καὶ χρεμετίσαι.", "st": "3.87"}, {"sp": "N", "t": "Δαρεῖός τε δὴ ὁ Ὑστάσπεος βασιλεὺς ἀπεδέδεκτο, καί οἱ ἦσαν ἐν τῇ Ἀσίῃ πάντες κατήκοοι πλὴν Ἀραβίων, Κύρου τε καταστρεψαμένου καὶ ὕστερον αὖτις Καμβύσεω. Ἀράβιοι δὲ οὐδαμὰ κατήκουσαν ἐπὶ δουλοσύνῃ Πέρσῃσι, ἀλλὰ ξεῖνοι ἐγένοντο παρέντες Καμβύσεα ἐπ’ Αἴγυπτον· ἀεκόντων γὰρ Ἀραβίων οὐκ ἂν ἐσβάλοιεν Πέρσαι ἐς Αἴγυπτον. γάμους τε τοὺς πρώτους ἐγάμεε Πέρσῃσι ὁ Δαρεῖος, Κύρου μὲν δύο θυγατέρας Ἄτοσσάν τε καὶ Ἀρτυστώνην, τὴν μὲν Ἄτοσσαν προσυνοικήσασαν Καμβύσῃ τε τῷ ἀδελφεῷ καὶ αὖτις τῷ Μάγῳ, τὴν δὲ Ἀρτυστώνην παρθένον· ἑτέρην δὲ Σμέρδιος τοῦ Κύρου θυγατέρα ἔγημε, τῇ οὔνομα ἦν Πάρμυς· ἔσχε δὲ καὶ τὴν τοῦ Ὀτάνεω θυγατέρα, ἣ τὸν Μάγον κατάδηλον ἐποίησε· δυνάμιός τε πάντα οἱ ἐπιμπλέατο. πρῶτον μέν νυν τύπον ποιησάμενος λίθινον ἔστησε· ζῷον δέ οἱ ἐνῆν ἀνὴρ ἱππεύς, ἐπέγραψε δὲ γράμματα λέγοντα τάδε· Δαρεῖος ὁ Ὑστάσπεος σύν τε τοῦ ἵππου τῇ ἀρετῇ τὸ οὔνομα λέγων καὶ Οἰβάρεος τοῦ ἱπποκόμου ἐκτήσατο τὴν Περσέων βασιληίην.", "st": "3.88"}, {"sp": "N", "t": "ποιήσας δὲ ταῦτα ἐν Πέρσῃσι ἀρχὰς κατεστήσατο εἴκοσι, τὰς αὐτοὶ καλέουσι σατραπηίας· καταστήσας δὲ τὰς ἀρχὰς καὶ ἄρχοντας ἐπιστήσας ἐτάξατο φόρους οἱ προσιέναι κατὰ ἔθνεά τε καὶ πρὸς τοῖσι ἔθνεσι τοὺς πλησιοχώρους προστάσσων, καὶ ὑπερβαίνων τοὺς προσεχέας τὰ ἑκαστέρω ἄλλοισι ἄλλα ἔθνεα νέμων. ἀρχὰς δὲ καὶ φόρων πρόσοδον τὴν ἐπέτειον κατὰ τάδε διεῖλε. τοῖσι μὲν αὐτῶν ἀργύριον ἀπαγινέουσι εἴρητο Βαβυλώνιον σταθμὸν τάλαντον ἀπαγινέειν, τοῖσι δὲ χρυσίον ἀπαγινέουσι Εὐβοϊκόν. τὸ δὲ Βαβυλώνιον τάλαντον δύναται Εὐβοΐδας ὀκτὼ καὶ ἑβδομήκοντα μνέας. ἐπὶ γὰρ Κύρου ἄρχοντος καὶ αὖτις Καμβύσεω ἦν κατεστηκὸς οὐδὲν φόρου πέρι, ἀλλὰ δῶρα ἀγίνεον. διὰ δὲ ταύτην τὴν ἐπίταξιν τοῦ φόρου καὶ παραπλήσια ταύτῃ ἄλλα λέγουσι Πέρσαι ὡς Δαρεῖος μὲν ἦν κάπηλος, Καμβύσης δὲ δεσπότης, Κῦρος δὲ πατήρ, ὃ μὲν ὅτι ἐκαπήλευε πάντα τὰ πρήγματα, ὁ δὲ ὅτι χαλεπός τε ἦν καὶ ὀλίγωρος, ὁ δὲ ὅτι ἤπιός τε καὶ ἀγαθά σφι πάντα ἐμηχανήσατο.", "st": "3.89"}, {"sp": "N", "t": "ἀπὸ μὲν δὴ Ἰώνων καὶ Μαγνήτων τῶν ἐν τῇ Ἀσίῃ καὶ Αἰολέων καὶ Καρῶν καὶ Λυκίων καὶ Μιλυέων καὶ Παμφύλων (εἷς γὰρ ἦν οἱ τεταγμένος οὗτος φόρος) προσήιε τετρακόσια τάλαντα ἀργυρίου. ὁ μὲν δὴ πρῶτος οὗτός οἱ νομὸς κατεστήκεε, ἀπὸ δὲ Μυσῶν καὶ Λυδῶν καὶ Λασονίων καὶ Καβαλέων καὶ Ὑτεννέων πεντακόσια τάλαντα· δεύτερος νομὸς οὗτος. ἀπὸ δὲ Ἑλλησποντίων τῶν ἐπὶ δεξιὰ ἐσπλέοντι καὶ Φρυγῶν καὶ Θρηίκων τῶν ἐν τῇ Ἀσίῃ καὶ Παφλαγόνων καὶ Μαριανδυνῶν καὶ Συρίων ἑξήκοντα καὶ τριηκόσια τάλαντα ἦν φόρος· νομὸς τρίτος οὗτος. ἀπὸ δὲ Κιλίκων ἵπποι τε λευκοὶ ἑξήκοντα καὶ τριηκόσιοι, ἑκάστης ἡμέρης εἷς γινόμενος, καὶ τάλαντα ἀργυρίου πεντακόσια· τούτων δὲ τεσσεράκοντα καὶ ἑκατὸν ἐς τὴν φρουρέουσαν ἵππον τὴν Κιλικίην χώρην ἀναισιμοῦτο, τὰ δὲ τριηκόσια καὶ ἑξήκοντα Δαρείῳ ἐφοίτα· νομὸς τέταρτος οὗτος.", "st": "3.90"}, {"sp": "N", "t": "ἀπὸ δὲ Ποσιδηίου πόλιος, τὴν Ἀμφίλοχος ὁ Ἀμφιάρεω οἴκισε ἐπ’ οὔροισι τοῖσι Κιλίκων τε καὶ Σύρων, ἀρξάμενος ἀπὸ ταύτης μέχρι Αἰγύπτου, πλὴν μοίρης τῆς Ἀραβίων (ταῦτα γὰρ ἦν ἀτελέα), πεντήκοντα καὶ τριηκόσια τάλαντα φόρος ἦν. ἔστι δὲ ἐν τῷ νομῷ τούτῳ Φοινίκη τε πᾶσα καὶ Συρίη ἡ Παλαιστίνη καλεομένη καὶ Κύπρος· νομὸς πέμπτος οὗτος. ἀπ’ Αἰγύπτου δὲ καὶ Λιβύων τῶν προσεχέων Αἰγύπτῳ καὶ Κυρήνης τε καὶ Βάρκης (ἐς γὰρ τὸν Αἰγύπτιον νομὸν αὗται ἐκεκοσμέατο) ἑπτακόσια προσήιε τάλαντα, πάρεξ τοῦ ἐκ τῆς Μοίριος λίμνης γινομένου ἀργυρίου, τὸ ἐγίνετο ἐκ τῶν ἰχθύων· τούτου τε δὴ χωρὶς τοῦ ἀργυρίου καὶ τοῦ [ἐπιμετρουμένου] σίτου προσήιε ἑπτακόσια τάλαντα· σίτου γὰρ δύο καὶ δέκα μυριάδας Περσέων τε τοῖσι ἐν τῷ Λευκῷ τείχεϊ τῷ ἐν Μέμφι κατοικημένοισι καταμετρέουσι καὶ τοῖσι τούτων ἐπικούροισι. νομὸς ἕκτος οὗτος. Σατταγύδαι δὲ καὶ Γανδάριοι καὶ Δαδίκαι τε καὶ Ἀπαρύται ἐς τὠυτὸ τεταγμένοι ἑβδομήκοντα καὶ ἑκατὸν τάλαντα προσέφερον· νομὸς δὲ οὗτος ἕβδομος. ἀπὸ Σούσων δὲ καὶ τῆς ἄλλης Κισσίων χώρης τριηκόσια· νομὸς ὄγδοος οὗτος.", "st": "3.91"}, {"sp": "N", "t": "ἀπὸ Βαβυλῶνος δὲ καὶ τῆς λοιπῆς Ἀσσυρίης χίλιά οἱ προσήιε τάλαντα ἀργυρίου καὶ παῖδες ἐκτομίαι πεντακόσιοι· νομὸς εἴνατος οὗτος. ἀπὸ δὲ Ἀγβατάνων καὶ τῆς λοιπῆς Μηδικῆς καὶ Παρικανίων καὶ Ὀρθοκορυβαντίων πεντήκοντά τε καὶ τετρακόσια τάλαντα· νομὸς δέκατος οὗτος. Κάσπιοι δὲ καὶ Παυσίκαι καὶ Παντίμαθοί τε καὶ Δαρεῖται ἐς τὠυτὸ συμφέροντες διηκόσια τάλαντα ἀπαγίνεον· νομὸς ἑνδέκατος οὗτος.", "st": "3.92"}, {"sp": "N", "t": "ἀπὸ Βακτριανῶν δὲ μέχρι Αἰγλῶν ἑξήκοντα καὶ τριηκόσια τάλαντα φόρος ἦν· νομὸς δυωδέκατος οὗτος. ἀπὸ Πακτυϊκῆς δὲ καὶ Ἀρμενίων καὶ τῶν προσεχέων μέχρι τοῦ πόντου τοῦ Εὐξείνου τετρακόσια τάλαντα· νομὸς τρίτος καὶ δέκατος οὗτος. ἀπὸ δὲ Σαγαρτίων καὶ Σαραγγέων καὶ Θαμαναίων καὶ Οὐτίων καὶ Μύκων καὶ τῶν ἐν τῇσι νήσοισι οἰκεόντων τῶν ἐν τῇ Ἐρυθρῇ θαλάσσῃ, ἐν τῇσι τοὺς ἀνασπάστους καλεομένους κατοικίζει βασιλεύς, ἀπὸ τούτων πάντων ἑξακόσια τάλαντα ἐγίνετο φόρος· νομὸς τέταρτος καὶ δέκατος οὗτος. Σάκαι δὲ καὶ Κάσπιοι πεντήκοντα καὶ διηκόσια ἀπαγίνεον τάλαντα· νομὸς πέμπτος καὶ δέκατος οὗτος. Πάρθοι δὲ καὶ Χοράσμιοι καὶ Σόγδοι τε καὶ Ἄρειοι τριηκόσια τάλαντα· νομὸς ἕκτος καὶ δέκατος οὗτος.", "st": "3.93"}, {"sp": "N", "t": "Παρικάνιοι δὲ καὶ Αἰθίοπες οἱ ἐκ τῆς Ἀσίης τετρακόσια τάλαντα ἀπαγίνεον· νομὸς ἕβδομος καὶ δέκατος οὗτος. Ματιηνοῖσι δὲ καὶ Σάσπειρσι καὶ Ἀλαροδίοισι διηκόσια ἐπετέτακτο τάλαντα· νομὸς ὄγδοος καὶ δέκατος οὗτος. Μόσχοισι δὲ καὶ Τιβαρηνοῖσι καὶ Μάκρωσι καὶ Μοσσυνοίκοισι καὶ Μαρσὶ τριηκόσια τάλαντα προείρητο· νομὸς εἴνατος καὶ δέκατος οὗτος. Ἰνδῶν δὲ πλῆθός τε πολλῷ πλεῖστον ἐστὶ πάντων τῶν ἡμεῖς ἴδμεν ἀνθρώπων, καὶ φόρον ἀπαγίνεον πρὸς πάντας τοὺς ἄλλους ἑξήκοντα καὶ τριηκόσια τάλαντα ψήγματος· νομὸς εἰκοστὸς οὗτος.", "st": "3.94"}, {"sp": "N", "t": "τὸ μὲν δὴ ἀργύριον τὸ Βαβυλώνιον πρὸς τὸ Εὐβοϊκὸν συμβαλλόμενον τάλαντον γίνεται ὀγδώκοντα καὶ ὀκτακόσια καὶ εἰνακισχίλια τάλαντα· τὸ δὲ χρυσίον τρισκαιδεκαστάσιον λογιζόμενον, τὸ ψῆγμα εὑρίσκεται ἐὸν Εὐβοϊκῶν ταλάντων ὀγδώκοντα καὶ ἑξακοσίων καὶ τετρακισχιλίων. τούτων ὦν πάντων συντιθεμένων τὸ πλῆθος Εὐβοϊκὰ τάλαντα συνελέγετο ἐς τὸν ἐπέτειον φόρον Δαρείῳ μύρια καὶ τετρακισχίλια καὶ πεντακόσια καὶ ἑξήκοντα· τὸ δ’ ἔτι τούτων ἔλασσον ἀπιεὶς οὐ λέγω.", "st": "3.95"}, {"sp": "N", "t": "οὗτος Δαρείῳ προσήιε φόρος ἀπὸ τῆς τε Ἀσίης καὶ τῆς Λιβύης ὀλιγαχόθεν. προϊόντος μέντοι τοῦ χρόνου καὶ ἀπὸ νήσων προσήιε ἄλλος φόρος καὶ τῶν ἐν τῇ Εὐρώπῃ μέχρι Θεσσαλίης οἰκημένων. τοῦτον τὸν φόρον θησαυρίζει βασιλεὺς τρόπῳ τοιῷδε· ἐς πίθους κεραμίνους τήξας καταχέει, πλήσας δὲ τὸ ἄγγος περιαιρέει τὸν κέραμον· ἐπεὰν δὲ δεηθῇ χρημάτων, κατακόπτει τοσοῦτο ὅσου ἂν ἑκάστοτε δέηται.", "st": "3.96"}, {"sp": "N", "t": "αὗται μὲν ἀρχαί τε ἦσαν καὶ φόρων ἐπιτάξιες. ἡ Περσὶς δὲ χώρη μούνη μοι οὐκ εἴρηται δασμοφόρος· ἀτελέα γὰρ Πέρσαι νέμονται χώρην. οἵδε δὲ φόρον μὲν οὐδένα ἐτάχθησαν φέρειν, δῶρα δὲ ἀγίνεον· Αἰθίοπες οἱ πρόσουροι Αἰγύπτῳ, τοὺς Καμβύσης ἐλαύνων ἐπὶ τοὺς μακροβίους Αἰθίοπας κατεστρέψατο, οἵ τε περί τε Νύσην τὴν ἱρὴν κατοίκηνται καὶ τῷ Διονύσῳ ἀνάγουσι τὰς ὁρτάς· [οὗτοι οἱ Αἰθίοπες καὶ οἱ πλησιόχωροι τούτοισι σπέρματι μὲν χρέωνται τῷ αὐτῷ τῷ καὶ οἱ Καλλαντίαι Ἰνδοί, οἰκήματα δὲ ἔκτηνται κατάγαια.] οὗτοι συναμφότεροι διὰ τρίτου ἔτεος ἀγίνεον, ἀγινέουσι δὲ καὶ τὸ μέχρι ἐμεῦ, δύο χοίνικας ἀπύρου χρυσίου καὶ διηκοσίας φάλαγγας ἐβένου καὶ πέντε παῖδας Αἰθίοπας καὶ ἐλέφαντος ὀδόντας μεγάλους εἴκοσι. Κόλχοι δὲ τὰ ἐτάξαντο ἐς τὴν δωρεὴν καὶ οἱ προσεχέες μέχρι Καυκάσιος ὄρεος (ἐς τοῦτο γὰρ τὸ ὄρος ὑπὸ Πέρσῃσι ἄρχεται, τὰ δὲ πρὸς βορέην ἄνεμον τοῦ Καυκάσιος Περσέων οὐδὲν ἔτι φροντίζει), οὗτοι ὦν δῶρα τὰ ἐτάξαντο ἔτι καὶ ἐς ἐμὲ διὰ πεντετηρίδος ἀγίνεον, ἑκατὸν παῖδας καὶ ἑκατὸν παρθένους. Ἀράβιοι δὲ χίλια τάλαντα ἀγίνεον λιβανωτοῦ ἀνὰ πᾶν ἔτος. ταῦτα μὲν οὗτοι δῶρα πάρεξ τοῦ φόρου βασιλέι ἐκόμιζον.", "st": "3.97"}, {"sp": "N", "t": "τὸν δὲ χρυσὸν τοῦτον τὸν πολλὸν οἱ Ἰνδοί, ἀπ’ οὗ τὸ ψῆγμα τῷ βασιλέι τὸ εἰρημένον κομίζουσι, τρόπῳ τοιῷδε κτῶνται. ἔστι τῆς Ἰνδικῆς χώρης τὸ πρὸς ἥλιον ἀνίσχοντα ψάμμος· τῶν γὰρ ἡμεῖς ἴδμεν, τῶν καὶ πέρι ἀτρεκές τι λέγεται, πρῶτοι πρὸς ἠῶ καὶ ἡλίου ἀνατολὰς οἰκέουσι ἀνθρώπων τῶν ἐν τῇ Ἀσίῃ Ἰνδοί· Ἰνδῶν γὰρ τὸ πρὸς τὴν ἠῶ ἐρημίη ἐστὶ διὰ τὴν ψάμμον. ἔστι δὲ πολλὰ ἔθνεα Ἰνδῶν καὶ οὐκ ὁμόφωνα σφίσι, καὶ οἳ μὲν αὐτῶν νομάδες εἰσὶ οἳ δὲ οὔ, οἳ δὲ ἐν τοῖσι ἕλεσι οἰκέουσι τοῦ ποταμοῦ καὶ ἰχθύας σιτέονται ὠμούς, τοὺς αἱρέουσι ἐκ πλοίων καλαμίνων ὁρμώμενοι· καλάμου δὲ ἓν γόνυ πλοῖον ἕκαστον ποιέεται. οὗτοι μὲν δὴ τῶν Ἰνδῶν φορέουσι ἐσθῆτα φλοΐνην· ἐπεὰν ἐκ τοῦ ποταμοῦ φλοῦν ἀμήσωσι καὶ κόψωσι, τὸ ἐνθεῦτεν φορμοῦ τρόπον καταπλέξαντες ὡς θώρηκα ἐνδύνουσι.", "st": "3.98"}, {"sp": "N", "t": "ἄλλοι δὲ τῶν Ἰνδῶν πρὸς ἠῶ οἰκέοντες τούτων νομάδες εἰσὶ κρεῶν ἐδεσταὶ ὠμῶν, καλέονται δὲ Παδαῖοι, νομαίοισι δὲ τοιοῖσιδε λέγονται χρᾶσθαι· ὃς ἂν κάμῃ τῶν ἀστῶν, ἤν τε γυνὴ ἤν τε ἀνήρ, τὸν μὲν ἄνδρα ἄνδρες οἱ μάλιστά οἱ ὁμιλέοντες κτείνουσι, φάμενοι αὐτὸν τηκόμενον τῇ νούσῳ τὰ κρέα σφίσι διαφθείρεσθαι· ὁ δὲ ἄπαρνος ἐστὶ μὴ μὲν νοσέειν, οἱ δὲ οὐ συγγινωσκόμενοι ἀποκτείναντες κατευωχέονται. ἣ δὲ ἂν γυνὴ κάμῃ, ὡσαύτως αἱ ἐπιχρεώμεναι μάλιστα γυναῖκες ταὐτὰ τοῖσι ἀνδράσι ποιεῦσι. τὸν γὰρ δὴ ἐς γῆρας ἀπικόμενον θύσαντες κατευωχέονται· ἐς δὲ τούτου λόγον οὐ πολλοί τινες αὐτῶν ἀπικνέονται· πρὸ γὰρ τοῦ τὸν ἐς νοῦσον πίπτοντα πάντα κτείνουσι.", "st": "3.99"}, {"sp": "N", "t": "ἑτέρων δὲ ἐστὶ Ἰνδῶν ὅδε ἄλλος τρόπος· οὔτε κτείνουσι οὐδὲν ἔμψυχον οὔτε τι σπείρουσι οὔτε οἰκίας νομίζουσι ἐκτῆσθαι ποιηφαγέουσί τε· καὶ αὐτοῖσι ἐστὶ ὅσον κέγχρος τὸ μέγαθος ἐν κάλυκι, αὐτόματον ἐκ τῆς γῆς γινόμενον, τὸ συλλέγοντες αὐτῇ τῇ κάλυκι ἕψουσί τε καὶ σιτέονται. ὃς δ’ ἂν ἐς νοῦσον αὐτῶν πέσῃ, ἐλθὼν ἐς τὴν ἔρημον κεῖται· φροντίζει δὲ οὐδεὶς οὔτε ἀποθανόντος οὔτε κάμνοντος.", "st": "3.100"}, {"sp": "N", "t": "μίξις δὲ τούτων τῶν Ἰνδῶν τῶν κατέλεξα πάντων ἐμφανής ἐστι κατά περ τῶν προβάτων, καὶ τὸ χρῶμα φορέουσι ὅμοιον πάντες καὶ παραπλήσιον Αἰθίοψι. ἡ γονὴ δὲ αὐτῶν, τὴν ἀπίενται ἐς τὰς γυναῖκας, οὐ κατά περ τῶν ἄλλων ἀνθρώπων ἐστὶ λευκή, ἀλλὰ μέλαινα κατά περ τὸ χρῶμα. τοιαύτην δὲ καὶ Αἰθίοπες ἀπίενται θορήν. οὗτοι μὲν τῶν Ἰνδῶν ἑκαστέρω τῶν Περσέων οἰκέουσι καὶ πρὸς νότου ἀνέμου, καὶ Δαρείου βασιλέος οὐδαμὰ ὑπήκουσαν.", "st": "3.101"}, {"sp": "N", "t": "ἄλλοι δὲ τῶν Ἰνδῶν Κασπατύρῳ τε πόλι καὶ τῇ Πακτυϊκῇ χώρῃ εἰσὶ πρόσουροι, πρὸς ἄρκτου τε καὶ βορέω ἀνέμου κατοικημένοι τῶν ἄλλων Ἰνδῶν, οἳ Βακτρίοισι παραπλησίην ἔχουσι δίαιταν. οὗτοι καὶ μαχιμώτατοι εἰσὶ Ἰνδῶν καὶ οἱ ἐπὶ τὸν χρυσὸν στελλόμενοι εἰσὶ οὗτοι· κατὰ γὰρ τοῦτο ἐστὶ ἐρημίη διὰ τὴν ψάμμον. ἐν δὴ ὦν τῇ ἐρημίῃ ταύτῃ καὶ τῇ ψάμμῳ γίνονται μύρμηκες μεγάθεα ἔχοντες κυνῶν μὲν ἐλάσσονα ἀλωπέκων δὲ μέζονα· εἰσὶ γὰρ αὐτῶν καὶ παρὰ βασιλέι τῷ Περσέων ἐνθεῦτεν θηρευθέντες. οὗτοι ὦν οἱ μύρμηκες ποιεύμενοι οἴκησιν ὑπὸ γῆν ἀναφορέουσι τὴν ψάμμον κατά περ οἱ ἐν τοῖσι Ἕλλησι μύρμηκες κατὰ τὸν αὐτὸν τρόπον, εἰσὶ δὲ καὶ αὐτοὶ τὸ εἶδος ὁμοιότατοι· ἡ δὲ ψάμμος ἡ ἀναφερομένη ἐστὶ χρυσῖτις. ἐπὶ δὴ ταύτην τὴν ψάμμον στέλλονται ἐς τὴν ἔρημον οἱ Ἰνδοί, ζευξάμενος ἕκαστος καμήλους τρεῖς, σειρηφόρον μὲν ἑκατέρωθεν ἔρσενα παρέλκειν, θήλεαν δὲ ἐς μέσον· ἐπὶ ταύτην δὴ αὐτὸς ἀναβαίνει, ἐπιτηδεύσας ὅκως ἀπὸ τέκνων ὡς νεωτάτων ἀποσπάσας ζεύξει. αἱ γάρ σφι κάμηλοι ἵππων οὐκ ἥσσονες ἐς ταχυτῆτα εἰσί, χωρὶς δὲ ἄχθεα δυνατώτεραι πολλὸν φέρειν.", "st": "3.102"}, {"sp": "N", "t": "τὸ μὲν δὴ εἶδος ὁκοῖόν τι ἔχει ἡ κάμηλος, ἐπισταμένοισι τοῖσι Ἕλλησι οὐ συγγράφω· τὸ δὲ μὴ ἐπιστέαται αὐτῆς, τοῦτο φράσω· κάμηλος ἐν τοῖσι ὀπισθίοισι σκέλεσι ἔχει τέσσερας μηροὺς καὶ γούνατα τέσσερα, τά τε αἰδοῖα διὰ τῶν ὀπισθίων σκελέων πρὸς τὴν οὐρὴν τετραμμένα.", "st": "3.103"}, {"sp": "N", "t": "οἱ δὲ δὴ Ἰνδοὶ τρόπῳ τοιούτῳ καὶ ζεύξι τοιαύτῃ χρεώμενοι ἐλαύνουσι ἐπὶ τὸν χρυσὸν λελογισμένως ὅκως καυμάτων τῶν θερμοτάτων ἐόντων ἔσονται ἐν τῇ ἁρπαγῇ· ὑπὸ γὰρ τοῦ καύματος οἱ μύρμηκες ἀφανέες γίνονται ὑπὸ γῆν. θερμότατος δὲ ἐστὶ ὁ ἥλιος τούτοισι τοῖσι ἀνθρώποισι τὸ ἑωθινόν, οὐ κατά περ τοῖσι ἄλλοισι μεσαμβρίης, ἀλλ’ ὑπερτείλας μέχρι οὗ ἀγορῆς διαλύσιος. τοῦτον δὲ τὸν χρόνον καίει πολλῷ μᾶλλον ἢ τῇ μεσαμβρίῃ τὴν Ἑλλάδα, οὕτω ὥστ’ ἐν ὕδατι λόγος αὐτούς ἐστι βρέχεσθαι τηνικαῦτα. μεσοῦσα δὲ ἡ ἡμέρη σχεδὸν παραπλησίως καίει τούς τε ἄλλους ἀνθρώπους καὶ τοὺς Ἰνδούς. ἀποκλινομένης δὲ τῆς μεσαμβρίης γίνεταί σφι ὁ ἥλιος κατά περ τοῖσι ἄλλοισι ὁ ἑωθινός, καὶ τὸ ἀπὸ τούτου ἀπιὼν ἐπὶ μᾶλλον ψύχει, ἐς ὃ ἐπὶ δυσμῇσι ἐὼν καὶ τὸ κάρτα ψύχει.", "st": "3.104"}, {"sp": "N", "t": "ἐπεὰν δὲ ἔλθωσι ἐς τὸν χῶρον οἱ Ἰνδοὶ ἔχοντες θυλάκια, ἐμπλήσαντες ταῦτα τῆς ψάμμου τὴν ταχίστην ἐλαύνουσι ὀπίσω· αὐτίκα γὰρ οἱ μύρμηκες ὀδμῇ, ὡς δὴ λέγεται ὑπὸ Περσέων, μαθόντες διώκουσι. εἶναι δὲ ταχυτῆτα οὐδενὶ ἑτέρῳ ὅμοιον, οὕτω ὥστε, εἰ μὴ προλαμβάνειν τοὺς Ἰνδοὺς τῆς ὁδοῦ ἐν ᾧ τοὺς μύρμηκας συλλέγεσθαι, οὐδένα ἂν σφέων ἀποσώζεσθαι. τοὺς μέν νυν ἔρσενας τῶν καμήλων, εἶναι γὰρ ἥσσονας θέειν τῶν θηλέων, παραλύεσθαι ἐπελκομένους, οὐκ ὁμοῦ ἀμφοτέρους· τὰς δὲ θηλέας ἀναμιμνησκομένας τῶν ἔλιπον τέκνων ἐνδιδόναι μαλακὸν οὐδέν. τὸν μὲν δὴ πλέω τοῦ χρυσοῦ οὕτω οἱ Ἰνδοὶ κτῶνται, ὡς Πέρσαι φασί· ἄλλος δὲ σπανιώτερος ἐστι ἐν τῇ χώρῃ ὀρυσσόμενος.", "st": "3.105"}, {"sp": "N", "t": "αἱ δ’ ἐσχατιαί κως τῆς οἰκεομένης τὰ κάλλιστα ἔλαχον, κατά περ ἡ Ἑλλὰς τὰς ὥρας πολλόν τι κάλλιστα κεκρημένας ἔλαχε. τοῦτο μὲν γὰρ πρὸς τὴν ἠῶ ἐσχάτη τῶν οἰκεομενέων ἡ Ἰνδική ἐστι, ὥσπερ ὀλίγῳ πρότερον εἴρηκα· ἐν ταύτῃ τοῦτο μὲν τὰ ἔμψυχα, τετράποδά τε καὶ τὰ πετεινά, πολλῷ μέζω ἢ ἐν τοῖσι ἄλλοισι χωρίοισι ἐστί, πάρεξ τῶν ἵππων (οὗτοι δὲ ἑσσοῦνται ὑπὸ τῶν Μηδικῶν, Νησαίων δὲ καλευμένων ἵππων), τοῦτο δὲ χρυσὸς ἄπλετος αὐτόθι ἐστί, ὃ μὲν ὀρυσσόμενος, ὁ δὲ καταφορεύμενος ὑπὸ ποταμῶν, ὁ δὲ ὥσπερ ἐσήμηνα ἁρπαζόμενος. τὰ δὲ δένδρεα τὰ ἄγρια αὐτόθι φέρει καρπὸν εἴρια καλλονῇ τε προφέροντα καὶ ἀρετῇ τῶν ἀπὸ τῶν ὀίων· καὶ ἐσθῆτι Ἰνδοὶ ἀπὸ τούτων τῶν δενδρέων χρέωνται.", "st": "3.106"}, {"sp": "N", "t": "πρὸς δ’ αὖ μεσαμβρίης ἐσχάτη Ἀραβίη τῶν οἰκεομενέων χωρέων ἐστί, ἐν δὲ ταύτῃ λιβανωτός τε ἐστὶ μούνῃ χωρέων πασέων φυόμενος καὶ σμύρνη καὶ κασίη καὶ κινάμωμον καὶ λήδανον. ταῦτα πάντα πλὴν τῆς σμύρνης δυσπετέως κτῶνται οἱ Ἀράβιοι. τὸν μέν γε λιβανωτὸν συλλέγουσι τὴν στύρακα θυμιῶντες, τὴν ἐς Ἕλληνας Φοίνικες ἐξάγουσι· ταύτην θυμιῶντες λαμβάνουσι· τὰ γὰρ δένδρεα ταῦτα τὰ λιβανωτοφόρα ὄφιες ὑπόπτεροι, μικροὶ τὰ μεγάθεα, ποικίλοι τὰ εἴδεα, φυλάσσουσι πλήθεϊ πολλοὶ περὶ δένδρον ἕκαστον, οὗτοι οἵ περ ἐπ’ Αἴγυπτον ἐπιστρατεύονται, οὐδενὶ δὲ ἄλλῳ ἀπελαύνονται ἀπὸ τῶν δενδρέων ἢ τῆς στύρακος τῷ καπνῷ.", "st": "3.107"}, {"sp": "N", "t": "λέγουσι δὲ καὶ τόδε Ἀράβιοι, ὡς πᾶσα ἂν γῆ ἐπίμπλατο τῶν ὀφίων τούτων, εἰ μὴ γίνεσθαι κατ’ αὐτοὺς οἷόν τι κατὰ τὰς ἐχίδνας ἠπιστάμην γίνεσθαι. καί κως τοῦ θείου ἡ προνοίη, ὥσπερ καὶ οἰκός ἐστι, ἐοῦσα σοφή, ὅσα μὲν ψυχήν τε δειλὰ καὶ ἐδώδιμα, ταῦτα μὲν πάντα πολύγονα πεποίηκε, ἵνα μὴ ἐπιλίπῃ κατεσθιόμενα, ὅσα δὲ σχέτλια καὶ ἀνιηρά, ὀλιγόγονα. τοῦτο μέν, ὅτι ὁ λαγὸς ὑπὸ παντὸς θηρεύεται θηρίου καὶ ὄρνιθος καὶ ἀνθρώπου, οὕτω δή τι πολύγονον ἐστί· ἐπικυΐσκεται μοῦνον πάντων θηρίων, καὶ τὸ μὲν δασὺ τῶν τέκνων ἐν τῇ γαστρὶ τὸ δὲ ψιλόν, τὸ δὲ ἄρτι ἐν τῇσι μήτρῃσι πλάσσεται, τὸ δὲ ἀναιρέεται. τοῦτο μὲν δὴ τοιοῦτο ἐστί· ἡ δὲ δὴ λέαινα ἐὸν ἰσχυρότατον καὶ θρασύτατον ἅπαξ ἐν τῷ βίῳ τίκτει ἕν· τίκτουσα γὰρ συνεκβάλλει τῷ τέκνῳ τὰς μήτρας. τὸ δὲ αἴτιον τούτου τόδε ἐστί· ἐπεὰν ὁ σκύμνος ἐν τῇ μητρὶ ἐὼν ἄρχηται διακινεόμενος, ὁ δὲ ἔχων ὄνυχας θηρίων πολλὸν πάντων ὀξυτάτους ἀμύσσει τὰς μήτρας, αὐξόμενός τε δὴ πολλῷ μᾶλλον ἐσικνέεται καταγράφων· πέλας τε δὴ ὁ τόκος ἐστί, καὶ τὸ παράπαν λείπεται αὐτέων ὑγιὲς οὐδέν.", "st": "3.108"}, {"sp": "N", "t": "ὣς δὲ καὶ οἱ ἔχιδναί τε καὶ οἱ ἐν Ἀραβίοισι ὑπόπτεροι ὄφιες εἰ ἐγίνοντο ὡς ἡ φύσις αὐτοῖσι ὑπάρχει, οὐκ ἂν ἦν βιώσιμα ἀνθρώποισι· νῦν δ’ ἐπεὰν θορνύωνται κατὰ ζεύγεα καὶ ἐν αὐτῇ ᾖ ὁ ἔρσην τῇ ἐκποιήσι, ἀπιεμένου αὐτοῦ τὴν γονὴν ἡ θήλεα ἅπτεται τῆς δειρῆς, καὶ ἐμφῦσα οὐκ ἀνιεῖ πρὶν ἂν διαφάγῃ. ὁ μὲν δὴ ἔρσην ἀποθνήσκει τρόπῳ τῷ εἰρημένῳ, ἡ δὲ θήλεα τίσιν τοιήνδε ἀποτίνει τῷ ἔρσενι· τῷ γονέι τιμωρέοντα ἔτι ἐν τῇ γαστρὶ ἐόντα τὰ τέκνα διεσθίει τὴν μητέρα, διαφαγόντα δὲ τὴν νηδὺν αὐτῆς οὕτω τὴν ἔκδυσιν ποιέεται. οἱ δὲ ἄλλοι ὄφιες ἐόντες ἀνθρώπων οὐ δηλήμονες τίκτουσί τε ᾠὰ καὶ ἐκλέπουσι πολλόν τι χρῆμα τῶν τέκνων. αἱ μέν νυν ἔχιδναι κατὰ πᾶσαν τὴν γῆν εἰσί, οἱ δὲ ὑπόπτεροι ὄφιες ἀθρόοι εἰσὶ ἐν τῇ Ἀραβίῃ καὶ οὐδαμῇ ἄλλῃ· κατὰ τοῦτο δοκέουσι πολλοὶ εἶναι.", "st": "3.109"}, {"sp": "N", "t": "τὸν μὲν δὴ λιβανωτὸν τοῦτον οὕτω κτῶνται Ἀράβιοι, τὴν δὲ κασίην ὧδε. ἐπεὰν καταδήσωνται βύρσῃσι καὶ δέρμασι ἄλλοισι πᾶν τὸ σῶμα καὶ τὸ πρόσωπον πλὴν αὐτῶν τῶν ὀφθαλμῶν, ἔρχονται ἐπὶ τὴν κασίην· ἣ δὲ ἐν λίμνῃ φύεται οὐ βαθέῃ, περὶ δὲ αὐτὴν καὶ ἐν αὐτῇ αὐλίζεταί κου θηρία πτερωτά, τῇσι νυκτερίσι προσείκελα μάλιστα, καὶ τέτριγε δεινόν, καὶ ἐς ἀλκὴν ἄλκιμα· τὰ δεῖ ἀπαμυνομένους ἀπὸ τῶν ὀφθαλμῶν οὕτω δρέπειν τὴν κασίην.", "st": "3.110"}, {"sp": "N", "t": "τὸ δὲ δὴ κινάμωμον ἔτι τούτων θωμαστότερον συλλέγουσι. ὅκου μὲν γὰρ γίνεται καὶ ἥτις μιν γῆ ἡ τρέφουσα ἐστί, οὐκ ἔχουσι εἰπεῖν, πλὴν ὅτι λόγῳ οἰκότι χρεώμενοι ἐν τοῖσιδε χωρίοισι φασὶ τινὲς αὐτὸ φύεσθαι ἐν τοῖσι ὁ Διόνυσος ἐτράφη· ὄρνιθας δὲ λέγουσι μεγάλας φορέειν ταῦτα τὰ κάρφεα τὰ ἡμεῖς ἀπὸ Φοινίκων μαθόντες κινάμωμον καλέομεν, φορέειν δὲ τὰς ὄρνιθας ἐς νεοσσιὰς προσπεπλασμένας ἐκ πηλοῦ πρὸς ἀποκρήμνοισι ὄρεσι, ἔνθα πρόσβασιν ἀνθρώπῳ οὐδεμίαν εἶναι. πρὸς ὦν δὴ ταῦτα τοὺς Ἀραβίους σοφίζεσθαι τάδε· βοῶν τε καὶ ὄνων τῶν ἀπογινομένων καὶ τῶν ἄλλων ὑποζυγίων τὰ μέλεα διαταμόντας ὡς μέγιστα κομίζειν ἐς ταῦτα τὰ χωρία, καί σφεα θέντας ἀγχοῦ τῶν νεοσσιέων ἀπαλλάσσεσθαι ἑκὰς αὐτέων· τὰς δὲ ὄρνιθας καταπετομένας τὰ μέλεα τῶν ὑποζυγίων ἀναφορέειν ἐπὶ τὰς νεοσσιάς, τὰς δὲ οὐ δυναμένας ἴσχειν καταρρήγνυσθαι ἐπὶ γῆν, τοὺς δὲ ἐπιόντας συλλέγειν. οὕτω μὲν τὸ κινάμωμον συλλεγόμενον ἐκ τούτων ἀπικνέεσθαι ἐς τὰς ἄλλας χώρας.", "st": "3.111"}, {"sp": "N", "t": "τὸ δὲ δὴ λήδανον, τὸ καλέουσι Ἀράβιοι λάδανον, ἔτι τούτου θωμασιώτερον γίνεται· ἐν γὰρ δυσοδμοτάτῳ γινόμενον εὐωδέστατον ἐστί· τῶν γὰρ αἰγῶν τῶν τράγων ἐν τοῖσι πώγωσι εὑρίσκεται ἐγγινόμενον οἷον γλοιὸς ἀπὸ τῆς ὕλης. χρήσιμον δ’ ἐς πολλὰ τῶν μύρων ἐστί, θυμιῶσί τε μάλιστα τοῦτο Ἀράβιοι.", "st": "3.112"}, {"sp": "N", "t": "τοσαῦτα μὲν θυωμάτων πέρι εἰρήσθω, ἀπόζει δὲ τῆς χώρης τῆς Ἀραβίης θεσπέσιον ὡς ἡδύ. δύο δὲ γένεα ὀίων σφι ἐστὶ θώματος ἄξια, τὰ οὐδαμόθι ἑτέρωθι ἐστί. τὸ μὲν αὐτῶν ἕτερον ἔχει τὰς οὐρὰς μακράς, τριῶν πηχέων οὐκ ἐλάσσονας, τὰς εἴ τις ἐπείη σφι ἐπέλκειν, ἕλκεα ἂν ἔχοιεν ἀνατριβομενέων πρὸς τῇ γῇ τῶν οὐρέων· νῦν δ’ ἅπας τις τῶν ποιμένων ἐπίσταται ξυλουργέειν ἐς τοσοῦτο· ἁμαξίδας γὰρ ποιεῦντες ὑποδέουσι αὐτὰς τῇσι οὐρῇσι, ἑνὸς ἑκάστου κτήνεος τὴν οὐρὴν ἐπὶ ἁμαξίδα ἑκάστην καταδέοντες. τὸ δὲ ἕτερον γένος τῶν ὀίων τὰς οὐρὰς πλατέας φορέουσι καὶ ἐπὶ πῆχυν πλάτος.", "st": "3.113"}, {"sp": "N", "t": "ἀποκλινομένης δὲ μεσαμβρίης παρήκει πρὸς δύνοντα ἥλιον ἡ Αἰθιοπίη χώρη ἐσχάτη τῶν οἰκεομενέων· αὕτη δὲ χρυσόν τε φέρει πολλὸν καὶ ἐλέφαντας ἀμφιλαφέας καὶ δένδρεα πάντα ἄγρια καὶ ἔβενον καὶ ἄνδρας μεγίστους καὶ καλλίστους καὶ μακροβιωτάτους.", "st": "3.114"}, {"sp": "N", "t": "αὗται μέν νυν ἔν τε τῇ Ἀσίῃ ἐσχατιαί εἰσι καὶ ἐν τῇ Λιβύῃ. περὶ δὲ τῶν ἐν τῇ Εὐρώπῃ τῶν πρὸς ἑσπέρην ἐσχατιέων ἔχω μὲν οὐκ ἀτρεκέως λέγειν· οὔτε γὰρ ἔγωγε ἐνδέκομαι Ἠριδανὸν καλέεσθαι πρὸς βαρβάρων ποταμὸν ἐκδιδόντα ἐς θάλασσαν τὴν πρὸς βορέην ἄνεμον, ἀπ’ ὅτευ τὸ ἤλεκτρον φοιτᾶν λόγος ἐστί, οὔτε νήσους οἶδα Κασσιτερίδας ἐούσας, ἐκ τῶν ὁ κασσίτερος ἡμῖν φοιτᾷ. τοῦτο μὲν γὰρ ὁ Ἠριδανὸς αὐτὸ κατηγορέει τὸ οὔνομα ὡς ἔστι Ἑλληνικὸν καὶ οὐ βάρβαρον, ὑπὸ ποιητέω δὲ τινὸς ποιηθέν· τοῦτο δὲ οὐδενὸς αὐτόπτεω γενομένου δύναμαι ἀκοῦσαι, τοῦτο μελετῶν, ὅκως θάλασσα ἐστὶ τὰ ἐπέκεινα Εὐρώπης. ἐξ ἐσχάτης δ’ ὦν ὁ κασσίτερος ἡμῖν φοιτᾷ καὶ τὸ ἤλεκτρον.", "st": "3.115"}, {"sp": "N", "t": "πρὸς δὲ ἄρκτου τῆς Εὐρώπης πολλῷ τι πλεῖστος χρυσὸς φαίνεται ἐών· ὅκως μὲν γινόμενος, οὐκ ἔχω οὐδὲ τοῦτο ἀτρεκέως εἶπαι, λέγεται δὲ ὑπὲκ τῶν γρυπῶν ἁρπάζειν Ἀριμασποὺς ἄνδρας μουνοφθάλμους. πείθομαι δὲ οὐδὲ τοῦτο ὅκως μουνόφθαλμοι ἄνδρες φύονται, φύσιν ἔχοντες τὴν ἄλλην ὁμοίην τοῖσι ἄλλοισι ἀνθρώποισι· αἱ δὲ ὦν ἐσχατιαὶ οἴκασι, περικληίουσαι τὴν ἄλλην χώρην καὶ ἐντὸς ἀπέργουσαι, τὰ κάλλιστα δοκέοντα ἡμῖν εἶναι καὶ σπανιώτατα ἔχειν αὗται.", "st": "3.116"}, {"sp": "N", "t": "ἔστι δὲ πεδίον ἐν τῇ Ἀσίῃ περικεκληιμένον ὄρεϊ πάντοθεν, διασφάγες δὲ τοῦ ὄρεος εἰσὶ πέντε. τοῦτο τὸ πεδίον ἦν μὲν κοτὲ Χορασμίων, ἐν οὔροισι ἐὸν Χορασμίων τε αὐτῶν καὶ Ὑρκανίων καὶ Πάρθων καὶ Σαραγγέων καὶ Θαμαναίων, ἐπείτε δὲ Πέρσαι ἔχουσι τὸ κράτος, ἐστὶ τοῦ βασιλέος. ἐκ δὴ ὦν τοῦ περικληίοντος ὄρεος τούτου ῥέει ποταμὸς μέγας, οὔνομα δέ οἱ ἐστὶ Ἄκης. οὗτος πρότερον μὲν ἄρδεσκε διαλελαμμένος πενταχοῦ τούτων τῶν εἰρημένων τὰς χώρας, διὰ διασφάγος ἀγόμενος ἑκάστης ἑκάστοισι· ἐπείτε δὲ ὑπὸ τῷ Πέρσῃ εἰσί, πεπόνθασι τοιόνδε· τὰς διασφάγας τῶν ὀρέων ἐνδείμας ὁ βασιλεὺς πύλας ἐπ’ ἑκάστῃ διασφάγι ἔστησε· ἀποκεκληιμένου δὲ τοῦ ὕδατος τῆς ἐξόδου τὸ πεδίον τὸ ἐντὸς τῶν ὀρέων πέλαγος γίνεται, ἐνδιδόντος μὲν τοῦ ποταμοῦ, ἔχοντος δὲ οὐδαμῇ ἐξήλυσιν. οὗτοι ὦν οἵ περ ἔμπροσθε ἐώθεσαν χρᾶσθαι τῷ ὕδατι, οὐκ ἔχοντες αὐτῷ χρᾶσθαι συμφορῇ μεγάλῃ διαχρέωνται. τὸν μὲν γὰρ χειμῶνα ὕει σφι ὁ θεὸς ὥσπερ καὶ τοῖσι ἄλλοισι ἀνθρώποισι, τοῦ δὲ θέρεος σπείροντες μελίνην καὶ σήσαμον χρηίσκονται τῷ ὕδατι. ἐπεὰν ὦν μηδέν σφι παραδιδῶται τοῦ ὕδατος, ἐλθόντες ἐς τοὺς Πέρσας αὐτοί τε καὶ γυναῖκες, στάντες κατὰ τὰς θύρας τοῦ βασιλέος βοῶσι ὠρυόμενοι, ὁ δὲ βασιλεὺς τοῖσι δεομένοισι αὐτῶν μάλιστα ἐντέλλεται ἀνοίγειν τὰς πύλας τὰς ἐς τοῦτο φερούσας. ἐπεὰν δὲ διάκορος ἡ γῆ σφεων γένηται πίνουσα τὸ ὕδωρ, αὗται μὲν αἱ πύλαι ἀποκληίονται, ἄλλας δ’ ἐντέλλεται ἀνοίγειν ἄλλοισι τοῖσι δεομένοισι μάλιστα τῶν λοιπῶν. ὡς δ’ ἐγὼ οἶδα ἀκούσας, χρήματα μεγάλα πρησσόμενος ἀνοίγει πάρεξ τοῦ φόρου.", "st": "3.117"}, {"sp": "N", "t": "ταῦτα μὲν δὴ ἔχει οὕτω. τῶν δὲ τῷ Μάγῳ ἐπαναστάντων ἑπτὰ ἀνδρῶν, ἕνα αὐτῶν Ἰνταφρένεα κατέλαβε ὑβρίσαντα τάδε ἀποθανεῖν αὐτίκα μετὰ τὴν ἐπανάστασιν. ἤθελε ἐς τὰ βασιλήια ἐσελθὼν χρηματίσασθαι τῷ βασιλέι· καὶ γὰρ δὴ καὶ ὁ νόμος οὕτω εἶχε, τοῖσι ἐπαναστᾶσι τῷ Μάγῳ ἔσοδον εἶναι παρὰ βασιλέα ἄνευ ἀγγέλου, ἢν μὴ γυναικὶ τυγχάνῃ μισγόμενος βασιλεύς. οὔκων δὴ Ἰνταφρένης ἐδικαίου οὐδένα οἱ ἐσαγγεῖλαι, ἀλλ’ ὅτι ἦν τῶν ἑπτά, ἐσιέναι ἤθελε. ὁ δὲ πυλουρὸς καὶ ὁ ἀγγελιηφόρος οὐ περιώρων, φάμενοι τὸν βασιλέα γυναικὶ μίσγεσθαι. ὁ δὲ Ἰνταφρένης δοκέων σφέας ψεύδεα λέγειν ποιέει τοιάδε· σπασάμενος τὸν ἀκινάκεα ἀποτάμνει αὐτῶν τά τε ὦτα καὶ τὰς ῥῖνας, καὶ ἀνείρας περὶ τὸν χαλινὸν τοῦ ἵππου περὶ τοὺς αὐχένας σφέων ἔδησε, καὶ ἀπῆκε.", "st": "3.118"}, {"sp": "N", "t": "οἳ δὲ τῷ βασιλέι δεικνύουσι ἑωυτοὺς καὶ τὴν αἰτίην εἶπον δι’ ἣν πεπονθότες εἴησαν. Δαρεῖος δὲ ἀρρωδήσας μὴ κοινῷ λόγῳ οἱ ἓξ πεποιηκότες ἔωσι ταῦτα, μεταπεμπόμενος ἕνα ἕκαστον ἀπεπειρᾶτο γνώμης, εἰ συνέπαινοι εἰσὶ τῷ πεποιημένῳ. ἐπείτε δὲ ἐξέμαθε ὡς οὐ σὺν κείνοισι εἴη ταῦτα πεποιηκώς, ἔλαβε αὐτόν τε τὸν Ἰνταφρένεα καὶ τοὺς παῖδας αὐτοῦ καὶ τοὺς οἰκηίους πάντας, ἐλπίδας πολλὰς ἔχων μετὰ τῶν συγγενέων μιν ἐπιβουλεύειν οἱ ἐπανάστασιν, συλλαβὼν δὲ σφέας ἔδησε τὴν ἐπὶ θανάτῳ. ἡ δὲ γυνὴ τοῦ Ἰνταφρένεος φοιτῶσα ἐπὶ τὰς θύρας τοῦ βασιλέος κλαίεσκε ἂν καὶ ὀδυρέσκετο· ποιεῦσα δὲ αἰεὶ τὠυτὸ τοῦτο τὸν Δαρεῖον ἔπεισε οἰκτεῖραί μιν. πέμψας δὲ ἄγγελον ἔλεγε τάδε· ὦ γύναι, βασιλεύς τοι Δαρεῖος διδοῖ ἕνα τῶν δεδεμένων οἰκηίων ῥύσασθαι τὸν βούλεαι ἐκ πάντων. ἣ δὲ βουλευσαμένη ὑπεκρίνετο τάδε· εἰ μὲν δή μοι διδοῖ βασιλεὺς ἑνὸς τὴν ψυχήν, αἱρέομαι ἐκ πάντων τὸν ἀδελφεόν. πυθόμενος δὲ Δαρεῖος ταῦτα καὶ θωμάσας τὸν λόγον, πέμψας ἠγόρευε ὦ γύναι, εἰρωτᾷ σε βασιλεύς, τίνα ἔχουσα γνώμην, τὸν ἄνδρα τε καὶ τὰ τέκνα ἐγκαταλιποῦσα, τὸν ἀδελφεὸν εἵλευ περιεῖναί τοι, ὃς καὶ ἀλλοτριώτερός τοι τῶν παίδων καὶ ἧσσον κεχαρισμένος τοῦ ἀνδρός ἐστι. ἣ δ’ ἀμείβετο τοῖσιδε. ὦ βασιλεῦ, ἀνὴρ μέν μοι ἂν ἄλλος γένοιτο, εἰ δαίμων ἐθέλοι, καὶ τέκνα ἄλλα, εἰ ταῦτα ἀποβάλοιμι· πατρὸς δὲ καὶ μητρὸς οὐκέτι μευ ζωόντων ἀδελφεὸς ἂν ἄλλος οὐδενὶ τρόπῳ γένοιτο. ταύτῃ τῇ γνώμῃ χρεωμένη ἔλεξα ταῦτα. εὖ τε δὴ ἔδοξε τῷ Δαρείῳ εἰπεῖν ἡ γυνή, καί οἱ ἀπῆκε τοῦτόν τε τὸν παραιτέετο καὶ τῶν παίδων τὸν πρεσβύτατον, ἡσθεὶς αὐτῇ, τοὺς δὲ ἄλλους ἀπέκτεινε πάντας. τῶν μὲν δὴ ἑπτὰ εἷς αὐτίκα τρόπῳ τῷ εἰρημένῳ ἀπολώλεε.", "st": "3.119"}, {"sp": "N", "t": "κατὰ δέ κου μάλιστα τὴν Καμβύσεω νοῦσον ἐγίνετο τάδε. ὑπὸ Κύρου κατασταθεὶς ἦν Σαρδίων ὕπαρχος Ὀροίτης ἀνὴρ Πέρσης· οὗτος ἐπεθύμησε πρήγματος οὐκ ὁσίου· οὔτε γάρ τι παθὼν οὔτε ἀκούσας μάταιον ἔπος πρὸς Πολυκράτεος τοῦ Σαμίου, οὐδὲ ἰδὼν πρότερον, ἐπεθύμεε λαβὼν αὐτὸν ἀπολέσαι, ὡς μὲν οἱ πλεῦνες λέγουσι, διὰ τοιήνδε τινὰ αἰτίην. ἐπὶ τῶν βασιλέος θυρέων κατήμενον τόν τε Ὀροίτεα καὶ ἄλλον Πέρσην τῷ οὔνομα εἶναι Μιτροβάτεα, νομοῦ ἄρχοντα τοῦ ἐν Δασκυλείῳ, τούτους ἐκ λόγων ἐς νείκεα συμπεσεῖν, κρινομένων δὲ περὶ ἀρετῆς εἰπεῖν τὸν Μιτροβάτεα τῷ Ὀροίτῃ προφέροντα σὺ γὰρ ἐν ἀνδρῶν λόγῳ, ὃς βασιλέι νῆσον Σάμον πρὸς τῷ σῷ νομῷ προσκειμένην οὐ προσεκτήσαο, ὧδε δή τι ἐοῦσαν εὐπετέα χειρωθῆναι, τὴν τῶν τις ἐπιχωρίων πεντεκαίδεκα ὁπλίτῃσι ἐπαναστὰς ἔσχε καὶ νῦν αὐτῆς τυραννεύει; οἳ μὲν δή μιν φασὶ τοῦτο ἀκούσαντα καὶ ἀλγήσαντα τῷ ὀνείδεϊ ἐπιθυμῆσαι οὐκ οὕτω τὸν εἴπαντα ταῦτα τίσασθαι ὡς Πολυκράτεα πάντως ἀπολέσαι, δι’ ὅντινα κακῶς ἤκουσε.", "st": "3.120"}, {"sp": "N", "t": "οἱ δὲ ἐλάσσονες λέγουσι πέμψαι Ὀροίτεα ἐς Σάμον κήρυκα ὅτευ δὴ χρήματος δεησόμενον (οὐ γὰρ ὦν δὴ τοῦτό γε λέγεται), καὶ τὸν Πολυκράτεα τυχεῖν κατακείμενον ἐν ἀνδρεῶνι, παρεῖναι δέ οἱ καὶ Ἀνακρέοντα τὸν Τήιον· καί κως εἴτ’ ἐκ προνοίης αὐτὸν κατηλογέοντα τὰ Ὀροίτεω πρήγματα, εἴτε καὶ συντυχίη τις τοιαύτη ἐπεγένετο· τόν τε γὰρ κήρυκα τὸν Ὀροίτεω παρελθόντα διαλέγεσθαι, καὶ τὸν Πολυκράτεα (τυχεῖν γὰρ ἀπεστραμμένον πρὸς τὸν τοῖχον) οὔτε τι μεταστραφῆναι οὔτε ὑποκρίνασθαι.", "st": "3.121"}, {"sp": "N", "t": "αἰτίαι μὲν δὴ αὗται διφάσιαι λέγονται τοῦ θανάτου τοῦ Πολυκράτεος γενέσθαι, πάρεστι δὲ πείθεσθαι ὁκοτέρῃ τις βούλεται αὐτέων. ὁ δὲ ὦν Ὀροίτης ἱζόμενος ἐν Μαγνησίῃ τῇ ὑπὲρ Μαιάνδρου ποταμοῦ οἰκημένῃ ἔπεμπε Μύρσον τὸν Γύγεω ἄνδρα Λυδὸν ἐς Σάμον ἀγγελίην φέροντα, μαθὼν τοῦ Πολυκράτεος τὸν νόον. Πολυκράτης γὰρ ἐστὶ πρῶτος τῶν ἡμεῖς ἴδμεν Ἑλλήνων ὃς θαλασσοκρατέειν ἐπενοήθη, πάρεξ Μίνωός τε τοῦ Κνωσσίου καὶ εἰ δή τις ἄλλος πρότερος τούτου ἦρξε τῆς θαλάσσης· τῆς δὲ ἀνθρωπηίης λεγομένης γενεῆς Πολυκράτης πρῶτος, ἐλπίδας πολλὰς ἔχων Ἰωνίης τε καὶ νήσων ἄρξειν. μαθὼν ὦν ταῦτά μιν διανοεύμενον ὁ Ὀροίτης πέμψας ἀγγελίην ἔλεγε τάδε. Ὀροίτης Πολυκράτεϊ ὧδε λέγει. πυνθάνομαι ἐπιβουλεύειν σε πρήγμασι μεγάλοισι, καὶ χρήματά τοι οὐκ εἶναι κατὰ τὰ φρονήματα. σύ νυν ὧδε ποιήσας ὀρθώσεις μὲν σεωυτόν, σώσεις δὲ καὶ ἐμέ· ἐμοὶ γὰρ βασιλεὺς Καμβύσης ἐπιβουλεύει θάνατον, καί μοι τοῦτο ἐξαγγέλλεται σαφηνέως. σύ νυν ἐμὲ ἐκκομίσας αὐτὸν καὶ χρήματα, τὰ μὲν αὐτῶν αὐτὸς ἔχε, τὰ δὲ ἐμὲ ἔα ἔχειν· εἵνεκέν τε χρημάτων ἄρξεις ἁπάσης τῆς Ἑλλάδος. εἰ δέ μοι ἀπιστέεις τὰ περὶ τῶν χρημάτων, πέμψον ὅστις τοι πιστότατος τυγχάνει ἐών, τῷ ἐγὼ ἀποδέξω.", "st": "3.122"}, {"sp": "N", "t": "ταῦτα ἀκούσας Πολυκράτης ἥσθη τε καὶ ἐβούλετο· καί κως ἱμείρετο γὰρ χρημάτων μεγάλως, ἀποπέμπει πρῶτα κατοψόμενον Μαιάνδριον Μαιανδρίου ἄνδρα τῶν ἀστῶν, ὅς οἱ ἦν γραμματιστής· ὃς χρόνῳ οὐ πολλῷ ὕστερον τούτων τὸν κόσμον τὸν ἐκ τοῦ ἀνδρεῶνος τοῦ Πολυκράτεος ἐόντα ἀξιοθέητον ἀνέθηκε πάντα ἐς τὸ Ἥραιον. ὁ δὲ Ὀροίτης μαθὼν τὸν κατάσκοπον ἐόντα προσδόκιμον ἐποίεε τοιάδε· λάρνακας ὀκτὼ πληρώσας λίθων πλὴν κάρτα βραχέος τοῦ περὶ αὐτὰ τὰ χείλεα, ἐπιπολῆς τῶν λίθων χρυσὸν ἐπέβαλε, καταδήσας δὲ τὰς λάρνακας εἶχε ἑτοίμας. ἐλθὼν δὲ ὁ Μαιάνδριος καὶ θεησάμενος ἀπήγγελλε τῷ Πολυκράτεϊ.", "st": "3.123"}, {"sp": "N", "t": "ὁ δὲ πολλὰ μὲν τῶν μαντίων ἀπαγορευόντων πολλὰ δὲ τῶν φίλων ἐστέλλετο αὐτόσε, πρὸς δὲ καὶ ἰδούσης τῆς θυγατρὸς ὄψιν ἐνυπνίου τοιήνδε· ἐδόκεε οἷ τὸν πατέρα ἐν τῷ ἠέρι μετέωρον ἐόντα λοῦσθαι μὲν ὑπὸ τοῦ Διός, χρίεσθαι δὲ ὑπὸ τοῦ ἡλίου. ταύτην ἰδοῦσα τὴν ὄψιν παντοίη ἐγίνετο μὴ ἀποδημῆσαι τὸν Πολυκράτεα παρὰ τὸν Ὀροίτεα, καὶ δὴ καὶ ἰόντος αὐτοῦ ἐπὶ τὴν πεντηκόντερον ἐπεφημίζετο. ὁ δέ οἱ ἠπείλησε, ἢν σῶς ἀπονοστήσῃ, πολλόν μιν χρόνον παρθενεύεσθαι. ἣ δὲ ἠρήσατο ἐπιτελέα ταῦτα γενέσθαι· βούλεσθαι γὰρ παρθενεύεσθαι πλέω χρόνον ἢ τοῦ πατρὸς ἐστερῆσθαι.", "st": "3.124"}, {"sp": "N", "t": "Πολυκράτης δὲ πάσης συμβουλίης ἀλογήσας ἔπλεε παρὰ τὸν Ὀροίτεα, ἅμα ἀγόμενος ἄλλους τε πολλοὺς τῶν ἑταίρων, ἐν δὲ δὴ καὶ Δημοκήδεα τὸν Καλλιφῶντος Κροτωνιήτην ἄνδρα, ἰητρόν τε ἐόντα καὶ τὴν τέχνην ἀσκέοντα ἄριστα τῶν κατ’ ἑωυτόν. ἀπικόμενος δὲ ἐς τὴν Μαγνησίην ὁ Πολυκράτης διεφθάρη κακῶς, οὔτε ἑωυτοῦ ἀξίως οὔτε τῶν ἑωυτοῦ φρονημάτων· ὅτι γὰρ μὴ οἱ Συρηκοσίων γενόμενοι τύραννοι οὐδὲ εἷς τῶν ἄλλων Ἑλληνικῶν τυράννων ἄξιος ἐστὶ Πολυκράτεϊ μεγαλοπρεπείην συμβληθῆναι. ἀποκτείνας δέ μιν οὐκ ἀξίως ἀπηγήσιος Ὀροίτης ἀνεσταύρωσε· τῶν δέ οἱ ἑπομένων ὅσοι μὲν ἦσαν Σάμιοι, ἀπῆκε, κελεύων σφέας ἑωυτῷ χάριν εἰδέναι ἐόντας ἐλευθέρους, ὅσοι δὲ ἦσαν ξεῖνοί τε καὶ δοῦλοι τῶν ἑπομένων, ἐν ἀνδραπόδων λόγῳ ποιεύμενος εἶχε. Πολυκράτης δὲ ἀνακρεμάμενος ἐπετέλεε πᾶσαν τὴν ὄψιν τῆς θυγατρός· ἐλοῦτο μὲν γὰρ ὑπὸ τοῦ Διὸς ὅκως ὕοι, ἐχρίετο δὲ ὑπὸ τοῦ ἡλίου, ἀνιεὶς αὐτὸς ἐκ τοῦ σώματος ἰκμάδα.", "st": "3.125"}, {"sp": "N", "t": "Πολυκράτεος μὲν δὴ αἱ πολλαὶ εὐτυχίαι ἐς τοῦτο ἐτελεύτησαν τῇ οἱ Ἄμασις ὁ Αἰγύπτου βασιλεὺς προεμαντεύσατο. χρόνῳ δὲ οὐ πολλῷ ὕστερον καὶ Ὀροίτεα Πολυκράτεος τίσιες μετῆλθον. μετὰ γὰρ τὸν Καμβύσεω θάνατον καὶ τῶν Μάγων τὴν βασιληίην μένων ἐν τῇσι Σάρδισι Ὀροίτης ὠφέλεε μὲν οὐδὲν Πέρσας ὑπὸ Μήδων ἀπαραιρημένους τὴν ἀρχήν· ὁ δὲ ἐν ταύτῃ τῇ ταραχῇ κατὰ μὲν ἔκτεινε Μιτροβάτεα τὸν ἐκ Δασκυλείου ὕπαρχον, ὅς οἱ ὠνείδισε τὰ ἐς Πολυκράτεα ἔχοντα, κατὰ δὲ τοῦ Μιτροβάτεω τὸν παῖδα Κρανάσπην, ἄνδρας ἐν Πέρσῃσι δοκίμους, ἄλλα τε ἐξύβρισε παντοῖα καί τινα ἀγγελιηφόρον ἐλθόντα Δαρείου παρ’ αὐτόν, ὡς οὐ πρὸς ἡδονήν οἱ ἦν τὰ ἀγγελλόμενα, κτείνει μιν ὀπίσω κομιζόμενον, ἄνδρας οἱ ὑπείσας κατ’ ὁδόν, ἀποκτείνας δέ μιν ἠφάνισε αὐτῷ ἵππῳ.", "st": "3.126"}, {"sp": "N", "t": "Δαρεῖος δὲ ὡς ἔσχε τὴν ἀρχήν, ἐπεθύμεε τὸν Ὀροίτεα τίσασθαι πάντων τῶν ἀδικημάτων εἵνεκεν καὶ μάλιστα Μιτροβάτεω καὶ τοῦ παιδός. ἐκ μὲν δὴ τῆς ἰθέης στρατὸν ἐπ’ αὐτὸν οὐκ ἐδόκεε πέμπειν ἅτε οἰδεόντων ἔτι τῶν πρηγμάτων, καὶ νεωστὶ ἔχων τὴν ἀρχὴν καὶ τὸν Ὀροίτεα μεγάλην τὴν ἰσχὺν πυνθανόμενος ἔχειν· τὸν χίλιοι μὲν Περσέων ἐδορυφόρεον, εἶχε δὲ νομὸν τόν τε Φρύγιον καὶ Λύδιον καὶ Ἰωνικόν. πρὸς ταῦτα δὴ ὦν ὁ Δαρεῖος τάδε ἐμηχανήσατο. συγκαλέσας Περσέων τοὺς δοκιμωτάτους ἔλεγέ σφι τάδε. ὦ Πέρσαι, τίς ἄν μοι τοῦτο ὑμέων ὑποστὰς ἐπιτελέσειε σοφίῃ καὶ μὴ βίῃ τε καὶ ὁμίλῳ; ἔνθα γὰρ σοφίης δέει, βίης ἔργον οὐδέν· ὑμέων δὲ ὦν τίς μοι Ὀροίτεα ἢ ζώοντα ἀγάγοι ἢ ἀποκτείνειε; ὃς ὠφέλησε μέν κω Πέρσας οὐδέν, κακὰ δὲ μεγάλα ἔοργε· τοῦτο μὲν δύο ἡμέων ἠίστωσε, Μιτροβάτεά τε καὶ τὸν παῖδα αὐτοῦ, τοῦτο δὲ τοὺς ἀνακαλέοντας αὐτὸν καὶ πεμπομένους ὑπ’ ἐμεῦ κτείνει, ὕβριν οὐκ ἀνασχετὸν φαίνων. πρίν τι ὦν μέζον ἐξεργάσασθαί μιν Πέρσας κακόν, καταλαμπτέος ἐστὶ ἡμῖν θανάτῳ.", "st": "3.127"}, {"sp": "N", "t": "Δαρεῖος μὲν ταῦτα ἐπειρώτα, τῷ δὲ ἄνδρες τριήκοντα ὑπέστησαν, αὐτὸς ἕκαστος ἐθέλων ποιέειν ταῦτα. ἐρίζοντας δὲ Δαρεῖος κατελάμβανε κελεύων πάλλεσθαι· παλλομένων δὲ λαγχάνει ἐκ πάντων Βαγαῖος ὁ Ἀρτόντεω· λαχὼν δὲ ὁ Βαγαῖος ποιέει τάδε· βυβλία γραψάμενος πολλὰ καὶ περὶ πολλῶν ἔχοντα πρηγμάτων σφρηγῖδά σφι ἐπέβαλε τὴν Δαρείου, μετὰ δὲ ἤιε ἔχων ταῦτα ἐς τὰς Σάρδις. ἀπικόμενος δὲ καὶ Ὀροίτεω ἐς ὄψιν ἐλθών, τῶν βυβλίων ἓν ἕκαστον περιαιρεόμενος ἐδίδου τῷ γραμματιστῇ τῷ βασιληίῳ ἐπιλέγεσθαι· γραμματιστὰς δὲ βασιληίους οἱ πάντες ὕπαρχοι ἔχουσι· ἀποπειρώμενος δὲ τῶν δορυφόρων ἐδίδου τὰ βυβλία ὁ Βαγαῖος, εἰ ἐνδεξαίατο ἀπόστασιν ἀπὸ Ὀροίτεω. ὁρέων δὲ σφέας τά τε βυβλία σεβομένους μεγάλως καὶ τὰ λεγόμενα ἐκ τῶν βυβλίων ἔτι μεζόνως, διδοῖ ἄλλο ἐν τῷ ἐνῆν ἔπεα τάδε· ὦ Πέρσαι, βασιλεὺς Δαρεῖος ἀπαγορεύει ὑμῖν μὴ δορυφορέειν Ὀροίτεα. οἳ δὲ ἀκούσαντες τούτων μετῆκάν οἱ τὰς αἰχμάς. ἰδὼν δὲ τοῦτο σφέας ὁ Βαγαῖος πειθομένους τῷ βυβλίῳ, ἐνθαῦτα δὴ θαρσήσας τὸ τελευταῖον τῶν βυβλίων διδοῖ τῷ γραμματιστῇ, ἐν τῷ ἐγέγραπτο βασιλεὺς Δαρεῖος Πέρσῃσι τοῖσι ἐν Σάρδισι ἐντέλλεται κτείνειν Ὀροίτεα. οἱ δὲ δορυφόροι ὡς ἤκουσαν ταῦτα, σπασάμενοι τοὺς ἀκινάκας κτείνουσι παραυτίκα μιν, οὕτω δὴ Ὀροίτεα τὸν Πέρσην Πολυκράτεος τοῦ Σαμίου τίσιες μετῆλθον.", "st": "3.128"}, {"sp": "N", "t": "ἀπικομένων δὲ καὶ ἀνακομισθέντων τῶν Ὀροίτεω χρημάτων ἐς τὰ Σοῦσα, συνήνεικε χρόνῳ οὐ πολλῷ ὕστερον βασιλέα Δαρεῖον ἐν ἄγρῃ θηρῶν ἀποθρώσκοντα ἀπ’ ἵππου στραφῆναι τὸν πόδα. καί κως ἰσχυροτέρως ἐστράφη· ὁ γάρ οἱ ἀστράγαλος ἐξεχώρησε ἐκ τῶν ἄρθρων. νομίζων δὲ καὶ πρότερον περὶ ἑωυτὸν ἔχειν Αἰγυπτίων τοὺς δοκέοντας εἶναι πρώτους τὴν ἰητρικήν, τούτοισι ἐχρᾶτο. οἳ δὲ στρεβλοῦντες καὶ βιώμενοι τὸν πόδα κακὸν μέζον ἐργάζοντο. ἐπ’ ἑπτὰ μὲν δὴ ἡμέρας καὶ ἑπτὰ νύκτας ὑπὸ τοῦ παρεόντος κακοῦ ὁ Δαρεῖος ἀγρυπνίῃσι εἴχετο· τῇ δὲ δὴ ὀγδόῃ ἡμέρῃ ἔχοντί οἱ φλαύρως, παρακούσας τις πρότερον ἔτι ἐν Σάρδισι τοῦ Κροτωνιήτεω Δημοκήδεος τὴν τέχνην ἀγγέλλει τῷ Δαρείῳ· ὁ δὲ ἄγειν μιν τὴν ταχίστην παρ’ ἑωυτὸν ἐκέλευσε· τὸν δὲ ὡς ἐξεῦρον ἐν τοῖσι Ὀροίτεω ἀνδραπόδοισι ὅκου δὴ ἀπημελημένον, παρῆγον ἐς μέσον πέδας τε ἕλκοντα καὶ ῥάκεσι ἐσθημένον.", "st": "3.129"}, {"sp": "N", "t": "σταθέντα δὲ ἐς μέσον εἰρώτα ὁ Δαρεῖος τὴν τέχνην εἰ ἐπίσταιτο· ὁ δὲ οὐκ ὑπεδέκετο, ἀρρωδέων μὴ ἑωυτὸν ἐκφήνας τὸ παράπαν τῆς Ἑλλάδος ᾖ ἀπεστερημένος· κατεφάνη τε τῷ Δαρείῳ τεχνάζειν ἐπιστάμενος, καὶ τοὺς ἀγαγόντας αὐτὸν ἐκέλευσε μάστιγάς τε καὶ κέντρα παραφέρειν ἐς τὸ μέσον. ὁ δὲ ἐνθαῦτα δὴ ὦν ἐκφαίνει, φὰς ἀτρεκέως μὲν οὐκ ἐπίστασθαι, ὁμιλήσας δὲ ἰητρῷ φλαύρως ἔχειν τὴν τέχνην. μετὰ δέ, ὥς οἱ ἐπέτρεψε, Ἑλληνικοῖσι ἰήμασι χρεώμενος καὶ ἤπια μετὰ τὰ ἰσχυρὰ προσάγων ὕπνου τέ μιν λαγχάνειν ἐποίεε καὶ ἐν χρόνῳ ὀλίγῳ ὑγιέα μιν ἀπέδεξε, οὐδαμὰ ἔτι ἐλπίζοντα ἀρτίπουν ἔσεσθαι. δωρέεται δή μιν μετὰ ταῦτα ὁ Δαρεῖος πεδέων χρυσέων δύο ζεύγεσι· ὁ δέ μιν ἐπείρετο εἴ οἱ διπλήσιον τὸ κακὸν ἐπίτηδες νέμει, ὅτι μιν ὑγιέα ἐποίησε. ἡσθεὶς δὲ τῷ ἔπεϊ ὁ Δαρεῖος ἀποπέμπει μιν παρὰ τὰς ἑωυτοῦ γυναῖκας· παράγοντες δὲ οἱ εὐνοῦχοι ἔλεγον πρὸς τὰς γυναῖκας ὡς βασιλέι οὗτος εἴη ὃς τὴν ψυχὴν ἀπέδωκε. ὑποτύπτουσα δὲ αὐτέων ἑκάστη φιάλῃ τοῦ χρυσοῦ ἐς θήκην ἐδωρέετο Δημοκήδεα οὕτω δή τι δαψιλέι δωρεῇ ὡς τοὺς ἀποπίπτοντας ἀπὸ τῶν φιαλέων στατῆρας ἑπόμενος ὁ οἰκέτης, τῷ οὔνομα ἦν Σκίτων, ἀνελέγετο καί οἱ χρῆμα πολλόν τι χρυσοῦ συνελέχθη.", "st": "3.130"}, {"sp": "N", "t": "ὁ δὲ Δημοκήδης οὗτος ὧδε ἐκ Κρότωνος ἀπιγμένος Πολυκράτεϊ ὡμίλησε· πατρὶ συνείχετο ἐν τῇ Κρότωνι ὀργὴν χαλεπῷ· τοῦτον ἐπείτε οὐκ ἐδύνατο φέρειν, ἀπολιπὼν οἴχετο ἐς Αἴγιναν. καταστὰς δὲ ἐς ταύτην πρώτῳ ἔτεϊ ὑπερεβάλετο τοὺς ἄλλους ἰητρούς, ἀσκευής περ ἐὼν καὶ ἔχων οὐδὲν τῶν ὅσα περὶ τὴν τέχνην ἐστὶ ἐργαλήια. καί μιν δευτέρῳ ἔτεϊ ταλάντου Αἰγινῆται δημοσίῃ μισθοῦνται, τρίτῳ δὲ ἔτεϊ Ἀθηναῖοι ἑκατὸν μνέων, τετάρτῳ δὲ ἔτεϊ Πολυκράτης δυῶν ταλάντων. οὕτω μὲν ἀπίκετο ἐς τὴν Σάμον, καὶ ἀπὸ τούτου τοῦ ἀνδρὸς οὐκ ἥκιστα Κροτωνιῆται ἰητροὶ εὐδοκίμησαν. ἐγένετο γὰρ ὦν τοῦτο ὅτε πρῶτοι μὲν Κροτωνιῆται ἰητροὶ ἐλέγοντο ἀνὰ τὴν Ἑλλάδα εἶναι, δεύτεροι δὲ Κυρηναῖοι. κατὰ τὸν αὐτὸν δὲ τοῦτον χρόνον καὶ Ἀργεῖοι ἤκουον μουσικὴν εἶναι Ἑλλήνων πρῶτοι.", "st": "3.131"}, {"sp": "N", "t": "τότε δὴ ὁ Δημοκήδης ἐν τοῖσι Σούσοισι ἐξιησάμενος Δαρεῖον οἶκόν τε μέγιστον εἶχε καὶ ὁμοτράπεζος βασιλέι ἐγεγόνεε, πλήν τε ἑνὸς τοῦ ἐς Ἕλληνας ἀπιέναι πάντα τἆλλά οἱ παρῆν. καὶ τοῦτο μὲν τοὺς Αἰγυπτίους ἰητρούς, οἳ βασιλέα πρότερον ἰῶντο, μέλλοντας ἀνασκολοπιεῖσθαι ὅτι ὑπὸ Ἕλληνος ἰητροῦ ἑσσώθησαν, τούτους βασιλέα παραιτησάμενος ἐρρύσατο· τοῦτο δὲ μάντιν Ἠλεῖον Πολυκράτεϊ ἐπισπόμενον καὶ ἀπημελημένον ἐν τοῖσι ἀνδραπόδοισι ἐρρύσατο. ἦν δὲ μέγιστον πρῆγμα Δημοκήδης παρὰ βασιλέι.", "st": "3.132"}, {"sp": "N", "t": "ἐν χρόνῳ δὲ ὀλίγῳ μετὰ ταῦτα τάδε ἄλλα συνήνεικε γενέσθαι. Ἀτόσσῃ τῇ Κύρου μὲν θυγατρὶ Δαρείου δὲ γυναικὶ ἐπὶ τοῦ μαστοῦ ἔφυ φῦμα, μετὰ δὲ ἐκραγὲν ἐνέμετο πρόσω. ὅσον μὲν δὴ χρόνον ἦν ἔλασσον, ἣ δὲ κρύπτουσα καὶ αἰσχυνομένη ἔφραζε οὐδενί· ἐπείτε δὲ ἐν κακῷ ἦν, μετεπέμψατο τὸν Δημοκήδεα καί οἱ ἐπέδεξε. ὁ δὲ φὰς ὑγιέα ποιήσειν ἐξορκοῖ μιν ἦ μέν οἱ ἀντυπουργήσειν ἐκείνην τοῦτο τὸ ἂν αὐτῆς δεηθῇ· δεήσεσθαι δὲ οὐδενὸς τῶν ὅσα ἐς αἰσχύνην ἐστὶ φέροντα.", "st": "3.133"}, {"sp": "N", "t": "ὡς δὲ ἄρα μιν μετὰ ταῦτα ἰώμενος ὑγιέα ἀπέδεξε, ἐνθαῦτα δὴ διδαχθεῖσα ὑπὸ τοῦ Δημοκήδεος ἡ Ἄτοσσα προσέφερε ἐν τῇ κοίτῃ Δαρείῳ λόγον τοιόνδε. ὦ βασιλεῦ, ἔχων δύναμιν τοσαύτην κάτησαι, οὔτε τι ἔθνος προσκτώμενος οὔτε δύναμιν Πέρσῃσι. οἰκὸς δὲ ἐστὶ ἄνδρα καὶ νέον καὶ χρημάτων μεγάλων δεσπότην φαίνεσθαί τι ἀποδεικνύμενον, ἵνα καὶ Πέρσαι ἐκμάθωσι ὅτι ὑπ’ ἀνδρὸς ἄρχονται. ἐπ’ ἀμφότερα δέ τοι συμφέρει ταῦτα ποιέειν, καὶ ἵνα σφέων Πέρσαι ἐπίστωνται ἄνδρα εἶναι τὸν προεστεῶτα, καὶ ἵνα τρίβωνται πολέμῳ μηδὲ σχολὴν ἄγοντες ἐπιβουλεύωσί τοι. νῦν γὰρ ἄν τι καὶ ἀποδέξαιο ἔργον, ἕως νέος εἶς ἡλικίην· αὐξομένῳ γὰρ τῷ σώματι συναύξονται καὶ αἱ φρένες, γηράσκοντι δὲ συγγηράσκουσι καὶ ἐς τὰ πρήγματα πάντα ἀπαμβλύνονται. ἣ μὲν δὴ ταῦτα ἐκ διδαχῆς ἔλεγε, ὃ δ’ ἀμείβετο τοῖσιδε. ὦ γύναι, πάντα ὅσα περ αὐτὸς ἐπινοέω ποιήσειν εἴρηκας· ἐγὼ γὰρ βεβούλευμαι ζεύξας γέφυραν ἐκ τῆσδε τῆς ἠπείρου ἐς τὴν ἑτέρην ἤπειρον ἐπὶ Σκύθας στρατεύεσθαι· καὶ ταῦτα ὀλίγου χρόνου ἔσται τελεύμενα. λέγει Ἄτοσσα τάδε. ὅρα νυν, ἐπὶ Σκύθας μὲν τὴν πρώτην ἰέναι ἔασον· οὗτοι γάρ, ἐπεὰν σὺ βούλῃ, ἔσονταί τοι· σὺ δέ μοι ἐπὶ τὴν Ἑλλάδα στρατεύεσθαι. ἐπιθυμέω γὰρ λόγῳ πυνθανομένη Λακαίνας τέ μοι γενέσθαι θεραπαίνας καὶ Ἀργείας καὶ Ἀττικὰς καὶ Κορινθίας. ἔχεις δὲ ἄνδρα ἐπιτηδεότατον ἀνδρῶν πάντων δέξαι τε ἕκαστα τῆς Ἑλλάδος καὶ κατηγήσασθαι, τοῦτον ὅς σευ τὸν πόδα ἐξιήσατο. ἀμείβεται Δαρεῖος ὦ γύναι, ἐπεὶ τοίνυν τοι δοκέει τῆς Ἑλλάδος ἡμέας πρῶτα ἀποπειρᾶσθαι, κατασκόπους μοι δοκέει Περσέων πρῶτον ἄμεινον εἶναι ὁμοῦ τούτῳ τῷ σὺ λέγεις πέμψαι ἐς αὐτούς, οἳ μαθόντες καὶ ἰδόντες ἐξαγγελέουσι ἕκαστα αὐτῶν ἡμῖν· καὶ ἔπειτα ἐξεπιστάμενος ἐπ’ αὐτοὺς τρέψομαι.", "st": "3.134"}, {"sp": "N", "t": "ταῦτα εἶπε καὶ ἅμα ἔπος τε καὶ ἔργον ἐποίεε. ἐπείτε γὰρ τάχιστα ἡμέρη ἐπέλαμψε, καλέσας Περσέων ἄνδρας δοκίμους πεντεκαίδεκα ἐνετέλλετό σφι ἑπομένους Δημοκήδεϊ διεξελθεῖν τὰ παραθαλάσσια τῆς Ἑλλάδος, ὅκως τε μὴ διαδρήσεται σφέας ὁ Δημοκήδης, ἀλλά μιν πάντως ὀπίσω ἀπάξουσι. ἐντειλάμενος δὲ τούτοισι ταῦτα, δεύτερα καλέσας αὐτὸν Δημοκήδεα ἐδέετο αὐτοῦ ὅκως ἐξηγησάμενος πᾶσαν καὶ ἐπιδέξας τὴν Ἑλλάδα τοῖσι Πέρσῃσι ὀπίσω ἥξει· δῶρα δέ μιν τῷ πατρὶ καὶ τοῖσι ἀδελφεοῖσι ἐκέλευε πάντα τὰ ἐκείνου ἔπιπλα λαβόντα ἄγειν, φὰς ἄλλα οἱ πολλαπλήσια ἀντιδώσειν· πρὸς δὲ ἐς τὰ δῶρα ὁλκάδα οἱ ἔφη συμβαλέεσθαι πλήσας ἀγαθῶν παντοίων, τὴν ἅμα οἱ πλεύσεσθαι. Δαρεῖος μὲν δή, δοκέειν ἐμοί, ἀπ’ οὐδενὸς δολεροῦ νόου ἐπαγγέλλετό οἱ ταῦτα. Δημοκήδης δὲ δείσας μή εὑ ἐκπειρῷτο Δαρεῖος, οὔτι ἐπιδραμὼν πάντα τὰ διδόμενα ἐδέκετο, ἀλλὰ τὰ μὲν ἑωυτοῦ κατὰ χώρην ἔφη καταλείψειν, ἵνα ὀπίσω σφέα ἀπελθὼν ἔχοι, τὴν μέντοι ὁλκάδα, τήν οἱ Δαρεῖος ἐπαγγέλλετο ἐς τὴν δωρεὴν τοῖσι ἀδελφεοῖσι, δέκεσθαι ἔφη. ἐντειλάμενος δὲ καὶ τούτῳ ταὐτὰ ὁ Δαρεῖος ἀποστέλλει αὐτοὺς ἐπὶ θάλασσαν.", "st": "3.135"}, {"sp": "N", "t": "καταβάντες δὲ οὗτοι ἐς Φοινίκην καὶ Φοινίκης ἐς Σιδῶνα πόλιν αὐτίκα μὲν τριήρεας δύο ἐπλήρωσαν, ἅμα δὲ αὐτῇσι καὶ γαῦλον μέγαν παντοίων ἀγαθῶν· παρεσκευασμένοι δὲ πάντα ἔπλεον ἐς τὴν Ἑλλάδα, προσίσχοντες δὲ αὐτῆς τὰ παραθαλάσσια ἐθηεῦντο καὶ ἀπεγράφοντο, ἐς ὃ τὰ πολλὰ αὐτῆς καὶ ὀνομαστὰ θεησάμενοι ἀπίκοντο τῆς Ἰταλίης ἐς Τάραντα. ἐνθαῦτα δὲ ἐκ ῥηστώνης τῆς Δημοκήδεος Ἀριστοφιλίδης τῶν Ταραντίνων ὁ βασιλεὺς τοῦτο μὲν τὰ πηδάλια παρέλυσε τῶν Μηδικέων νεῶν, τοῦτο δὲ αὐτοὺς τοὺς Πέρσας εἶρξε ὡς κατασκόπους δῆθεν ἐόντας. ἐν ᾧ δὲ οὗτοι ταῦτα ἔπασχον, ὁ Δημοκήδης ἐς τὴν Κρότωνα ἀπικνέεται· ἀπιγμένου δὲ ἤδη τούτου ἐς τὴν ἑωυτοῦ ὁ Ἀριστοφιλίδης ἔλυσε τοὺς Πέρσας, καὶ τὰ παρέλαβε τῶν νεῶν ἀπέδωκέ σφι.", "st": "3.136"}, {"sp": "N", "t": "πλέοντες δὲ ἐνθεῦτεν οἱ Πέρσαι καὶ διώκοντες Δημοκήδεα ἀπικνέονται ἐς τὴν Κρότωνα, εὑρόντες δέ μιν ἀγοράζοντα ἅπτοντο αὐτοῦ. τῶν δὲ Κροτωνιητέων οἳ μὲν καταρρωδέοντες τὰ Περσικὰ πρήγματα προϊέναι ἕτοιμοι ἦσαν, οἳ δὲ ἀντάπτοντο καὶ τοῖσι σκυτάλοισι ἔπαιον τοὺς Πέρσας προϊσχομένους ἔπεα τάδε. ἄνδρες Κροτωνιῆται, ὁρᾶτε τὰ ποιέετε· ἄνδρα βασιλέος δρηπέτην γενόμενον ἐξαιρέεσθε. κῶς ταῦτα βασιλέι Δαρείῳ ἐκχρήσει περιυβρίσθαι; κῶς δὲ ὑμῖν τὰ ποιεύμενα ἕξει καλῶς, ἢν ἀπέλησθε ἡμέας; ἐπὶ τίνα δὲ τῆσδε προτέρην στρατευσόμεθα πόλιν; τίνα δὲ προτέρην ἀνδραποδίζεσθαι περιησόμεθα; ταῦτα λέγοντες τοὺς Κροτωνιήτας οὔκων ἔπειθον, ἀλλ’ ἐξαιρεθέντες τε τὸν Δημοκήδεα καὶ τὸν γαῦλον τὸν ἅμα ἤγοντο ἀπαιρεθέντες ἀπέπλεον ὀπίσω ἐς τὴν Ἀσίην, οὐδ’ ἔτι ἐζήτησαν τὸ προσωτέρω τῆς Ἑλλάδος ἀπικόμενοι ἐκμαθεῖν, ἐστερημένοι τοῦ ἡγεμόνος. τοσόνδε μέντοι ἐνετείλατό σφι Δημοκήδης ἀναγομένοισι, κελεύων εἰπεῖν σφεας Δαρείῳ ὅτι ἅρμοσται τὴν Μίλωνος θυγατέρα Δημοκήδης γυναῖκα. τοῦ γὰρ δὴ παλαιστέω Μίλωνος ἦν οὔνομα πολλὸν παρὰ βασιλέι· κατὰ δὲ τοῦτό μοι δοκέει σπεῦσαι τὸν γάμον τοῦτον τελέσας χρήματα μεγάλα Δημοκήδης, ἵνα φανῇ πρὸς Δαρείου ἐὼν καὶ ἐν τῇ ἑωυτοῦ δόκιμος.", "st": "3.137"}, {"sp": "N", "t": "ἀναχθέντες δὲ ἐκ τῆς Κρότωνος οἱ Πέρσαι ἐκπίπτουσι τῇσι νηυσὶ ἐς Ἰηπυγίην, καί σφεας δουλεύοντας ἐνθαῦτα Γίλλος ἀνὴρ Ταραντῖνος φυγὰς ῥυσάμενος ἀπήγαγε παρὰ βασιλέα Δαρεῖον. ὁ δὲ ἀντὶ τούτων ἕτοιμος ἦν διδόναι τοῦτο ὅ τι βούλοιτο αὐτός. Γίλλος δὲ αἱρέεται κάτοδόν οἱ ἐς Τάραντα γενέσθαι, προαπηγησάμενος τὴν συμφορήν· ἵνα δὲ μὴ συνταράξῃ τὴν Ἑλλάδα, ἢν δι’ αὐτὸν στόλος μέγας πλέῃ ἐπὶ τὴν Ἰταλίην, Κνιδίους μούνους ἀποχρᾶν οἱ ἔφη τοὺς κατάγοντας γίνεσθαι, δοκέων ἀπὸ τούτων ἐόντων τοῖσι Ταραντίνοισι φίλων μάλιστα τὴν κάτοδόν οἱ ἔσεσθαι. Δαρεῖος δὲ ὑποδεξάμενος ἐπετέλεε· πέμψας γὰρ ἄγγελον ἐς Κνίδον κατάγειν σφέας ἐκέλευε Γίλλον ἐς Τάραντα. πειθόμενοι δὲ Δαρείῳ Κνίδιοι Ταραντίνους οὔκων ἔπειθον, βίην δὲ ἀδύνατοι ἦσαν προσφέρειν. ταῦτα μέν νυν οὕτω ἐπρήχθη· οὗτοι δὲ πρῶτοι ἐκ τῆς Ἀσίης ἐς τὴν Ἑλλάδα ἀπίκοντο Πέρσαι, καὶ οὗτοι διὰ τοιόνδε πρῆγμα κατάσκοποι ἐγένοντο.", "st": "3.138"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα Σάμον βασιλεὺς Δαρεῖος αἱρέει, πολίων πασέων πρώτην Ἑλληνίδων καὶ βαρβάρων, διὰ τοιήνδε τινὰ αἰτίην. Καμβύσεω τοῦ Κύρου στρατευομένου ἐπ’ Αἴγυπτον ἄλλοι τε συχνοὶ ἐς τὴν Αἴγυπτον ἀπίκοντο Ἑλλήνων, οἳ μέν, ὡς οἰκός, κατ’ ἐμπορίην στρατευόμενοι, οἳ δὲ τινὲς καὶ αὐτῆς τῆς χώρης θεηταί· τῶν ἦν καὶ Συλοσῶν ὁ Αἰάκεος, Πολυκράτεός τε ἐὼν ἀδελφεὸς καὶ φεύγων ἐκ Σάμου. τοῦτον τὸν Συλοσῶντα κατέλαβε εὐτυχίη τις τοιήδε. λαβὼν χλανίδα καὶ περιβαλόμενος πυρρὴν ἠγόραζε ἐν τῇ Μέμφι· ἰδὼν δὲ αὐτὸν Δαρεῖος, δορυφόρος τε ἐὼν Καμβύσεω καὶ λόγου οὐδενός κω μεγάλου, ἐπεθύμησε τῆς χλανίδος καὶ αὐτὴν προσελθὼν ὠνέετο. ὁ δὲ Συλοσῶν ὁρέων τὸν Δαρεῖον μεγάλως ἐπιθυμέοντα τῆς χλανίδος, θείῃ τύχῃ χρεώμενος λέγει ἐγὼ ταύτην πωλέω μὲν οὐδενὸς χρήματος, δίδωμι δὲ ἄλλως, εἴ περ οὕτω δεῖ γενέσθαι πάντως τοι. αἰνέσας ταῦτα ὁ Δαρεῖος παραλαμβάνει τὸ εἷμα.", "st": "3.139"}, {"sp": "N", "t": "ὁ μὲν δὴ Συλοσῶν ἠπίστατο τοῦτό οἱ ἀπολωλέναι δι’ εὐηθείην. ὡς δὲ τοῦ χρόνου προβαίνοντος Καμβύσης τε ἀπέθανε καὶ τῷ Μάγῳ ἐπανέστησαν οἱ ἑπτὰ καὶ ἐκ τῶν ἑπτὰ Δαρεῖος τὴν βασιληίην ἔσχε, πυνθάνεται ὁ Συλοσῶν ὡς ἡ βασιληίη περιεληλύθοι ἐς τοῦτον τὸν ἄνδρα τῷ κοτὲ αὐτὸς ἔδωκε ἐν Αἰγύπτῳ δεηθέντι τὸ εἷμα. ἀναβὰς δὲ ἐς τὰ Σοῦσα ἵζετο ἐς τὰ πρόθυρα τῶν βασιλέος οἰκίων καὶ ἔφη Δαρείου εὐεργέτης εἶναι. ἀγγέλλει ταῦτα ἀκούσας ὁ πυλουρὸς τῷ βασιλέι· ὁ δὲ θωμάσας λέγει πρὸς αὐτόν καὶ τίς ἐστὶ Ἑλλήνων εὐεργέτης τῷ ἐγὼ προαιδεῦμαι, νεωστὶ μὲν τὴν ἀρχὴν ἔχων; ἀναβέβηκε δ’ ἤ τις ἢ οὐδείς κω παρ’ ἡμέας αὐτῶν, ἔχω δὲ χρέος εἰπεῖν οὐδὲν ἀνδρὸς Ἕλληνος. ὅμως δὲ αὐτὸν παράγετε ἔσω, ἵνα εἰδέω τί θέλων λέγει ταῦτα. παρῆγε ὁ πυλουρὸς τὸν Συλοσῶντα, στάντα δὲ ἐς μέσον εἰρώτων οἱ ἑρμηνέες τίς τε εἴη καὶ τί ποιήσας εὐεργέτης φησὶ εἶναι βασιλέος. εἶπε ὦν ὁ Συλοσῶν πάντα τὰ περὶ τὴν χλανίδα γενόμενα, καὶ ὡς αὐτὸς εἴη κεῖνος ὁ δούς. ἀμείβεται πρὸς ταῦτα Δαρεῖος ὦ γενναιότατε ἀνδρῶν, σὺ κεῖνος εἶς ὃς ἐμοὶ οὐδεμίαν ἔχοντί κω δύναμιν ἔδωκας εἰ καὶ σμικρά, ἀλλ’ ὦν ἴση γε ἡ χάρις ὁμοίως ὡς εἰ νῦν κοθέν τι μέγα λάβοιμι· ἀντ’ ὧν τοι χρυσὸν καὶ ἄργυρον ἄπλετον δίδωμι, ὡς μή κοτέ τοι μεταμελήσῃ Δαρεῖον τὸν Ὑστάσπεος εὖ ποιήσαντι. λέγει πρὸς ταῦτα ὁ Συλοσῶν ἐμοὶ μήτε χρυσὸν ὦ βασιλεῦ μήτε ἄργυρον δίδου, ἀλλ’ ἀνασωσάμενός μοι δὸς τὴν πατρίδα Σάμον, τὴν νῦν ἀδελφεοῦ τοῦ ἐμοῦ Πολυκράτεος ἀποθανόντος ὑπὸ Ὀροίτεω ἔχει δοῦλος ἡμέτερος· ταύτην μοι δὸς ἄνευ τε φόνου καὶ ἐξανδραποδίσιος.", "st": "3.140"}, {"sp": "N", "t": "ταῦτα ἀκούσας Δαρεῖος ἀπέστελλε στρατιήν τε καὶ στρατηγὸν Ὀτάνεα ἀνδρῶν τῶν ἑπτὰ γενόμενον, ἐντειλάμενος, ὅσων ἐδεήθη ὁ Συλοσῶν, ταῦτά οἱ ποιέειν ἐπιτελέα. καταβὰς δὲ ἐπὶ τὴν θάλασσαν ὁ Ὀτάνης ἔστελλε τὴν στρατιήν.", "st": "3.141"}, {"sp": "N", "t": "τῆς δὲ Σάμου Μαιάνδριος ὁ Μαιανδρίου εἶχε τὸ κράτος, ἐπιτροπαίην παρὰ Πολυκράτεος λαβὼν τὴν ἀρχήν· τῷ δικαιοτάτῳ ἀνδρῶν βουλομένῳ γενέσθαι οὐκ ἐξεγένετο. ἐπειδὴ γάρ οἱ ἐξαγγέλθη ὁ Πολυκράτεος θάνατος, ἐποίεε τοιάδε· πρῶτα μὲν Διὸς ἐλευθερίου βωμὸν ἱδρύσατο καὶ τέμενος περὶ αὐτὸν οὔρισε τοῦτο τὸ νῦν ἐν τῷ προαστείῳ ἐστί· μετὰ δέ, ὥς οἱ ἐπεποίητο, ἐκκλησίην συναγείρας πάντων τῶν ἀστῶν ἔλεξε τάδε. ἐμοί, ὡς ἴστε καὶ ὑμεῖς, σκῆπτρον καὶ δύναμις πᾶσα ἡ Πολυκράτεος ἐπιτέτραπται, καί μοι παρέχει νῦν ὑμέων ἄρχειν. ἐγὼ δὲ τὰ τῷ πέλας ἐπιπλήσσω, αὐτὸς κατὰ δύναμιν οὐ ποιήσω· οὔτε γάρ μοι Πολυκράτης ἤρεσκε δεσπόζων ἀνδρῶν ὁμοίων ἑωυτῷ οὔτε ἄλλος ὅστις τοιαῦτα ποιέει. Πολυκράτης μέν νυν ἐξέπλησε μοῖραν τὴν ἑωυτοῦ, ἐγὼ δὲ ἐς μέσον τὴν ἀρχὴν τιθεὶς ἰσονομίην ὑμῖν προαγορεύω. τοσάδε μέντοι δικαιῶ γέρεα ἐμεωυτῷ γενέσθαι, ἐκ μέν γε τῶν Πολυκράτεος χρημάτων ἐξαίρετα ἓξ τάλαντά μοι γενέσθαι, ἱρωσύνην δὲ πρὸς τούτοισι αἱρεῦμαι αὐτῷ τέ μοι καὶ τοῖσι ἀπ’ ἐμεῦ αἰεὶ γινομένοισι τοῦ Διὸς τοῦ ἐλευθερίου· τῷ αὐτός τε ἱρὸν ἱδρυσάμην καὶ τὴν ἐλευθερίην ὑμῖν περιτίθημι. ὃ μὲν δὴ ταῦτα τοῖσι Σαμίοισι ἐπαγγέλλετο· τῶν δέ τις ἐξαναστὰς εἶπε ἀλλ’ οὐδ’ ἄξιος εἶς σύ γε ἡμέων ἄρχειν, γεγονώς τε κακῶς καὶ ἐὼν ὄλεθρος· ἀλλὰ μᾶλλον ὅκως λόγον δώσεις τῶν μετεχείρισας χρημάτων.", "st": "3.142"}, {"sp": "N", "t": "ταῦτα εἶπε ἐὼν ἐν τοῖσι ἀστοῖσι δόκιμος, τῷ οὔνομα ἦν Τελέσαρχος. Μαιάνδριος δὲ νόῳ λαβὼν ὡς εἰ μετήσει τὴν ἀρχήν, ἄλλος τις ἀντ’ αὐτοῦ τύραννος καταστήσεται, οὐδὲν ἔτι ἐν νόῳ εἶχε μετιέναι αὐτήν, ἀλλ’ ὡς ἀνεχώρησε ἐς τὴν ἀκρόπολιν, μεταπεμπόμενος ἕνα ἕκαστον ὡς δὴ λόγον τῶν χρημάτων δώσων, συνέλαβε σφέας καὶ κατέδησε. οἳ μὲν δὴ ἐδεδέατο, Μαιάνδριον δὲ μετὰ ταῦτα κατέλαβε νοῦσος. ἐλπίζων δέ μιν ἀποθανέεσθαι ὁ ἀδελφεός, τῷ οὔνομα ἦν Λυκάρητος, ἵνα εὐπετεστέρως κατάσχῃ τὰ ἐν τῇ Σάμῳ πρήγματα, κατακτείνει τοὺς δεσμώτας πάντας· οὐ γὰρ δή, ὡς οἴκασι, ἐβούλοντο εἶναι ἐλεύθεροι.", "st": "3.143"}, {"sp": "N", "t": "ἐπειδὴ ὦν ἀπίκοντο ἐς τὴν Σάμον οἱ Πέρσαι κατάγοντες Συλοσῶντα, οὔτε τίς σφι χεῖρας ἀνταείρεται, ὑπόσπονδοί τε ἔφασαν εἶναι ἕτοιμοι οἱ τοῦ Μαιανδρίου στασιῶται καὶ αὐτὸς Μαιάνδριος ἐκχωρῆσαι ἐκ τῆς νήσου. καταινέσαντος δ’ ἐπὶ τούτοισι Ὀτάνεω καὶ σπεισαμένου, τῶν Περσέων οἱ πλείστου ἄξιοι θρόνους θέμενοι κατεναντίον τῆς ἀκροπόλιος κατέατο.", "st": "3.144"}, {"sp": "N", "t": "Μαιανδρίῳ δὲ τῷ τυράννῳ ἦν ἀδελφεὸς ὑπομαργότερος, τῷ οὔνομα ἦν Χαρίλεως· οὗτος ὅ τι δὴ ἐξαμαρτὼν ἐν γοργύρῃ ἐδέδετο, καὶ δὴ τότε ἐπακούσας τε τὰ πρησσόμενα καὶ διακύψας διὰ τῆς γοργύρης, ὡς εἶδε τοὺς Πέρσας εἰρηναίως κατημένους, ἐβόα τε καὶ ἔφη λέγων Μαιανδρίῳ θέλειν ἐλθεῖν ἐς λόγους. ἐπακούσας δὲ ὁ Μαιάνδριος λύσαντας αὐτὸν ἐκέλευε ἄγειν παρ’ ἑωυτόν· ὡς δὲ ἄχθη τάχιστα, λοιδορέων τε καὶ κακίζων μιν ἀνέπειθε ἐπιθέσθαι τοῖσι Πέρσῃσι, λέγων τοιάδε. ἐμὲ μέν, ὦ κάκιστε ἀνδρῶν, ἐόντα σεωυτοῦ ἀδελφεὸν καὶ ἀδικήσαντα οὐδὲν ἄξιον δεσμοῦ δήσας γοργύρης ἠξίωσας· ὁρέων δὲ τοὺς Πέρσας ἐκβάλλοντάς τέ σε καὶ ἄνοικον ποιέοντας οὐ τολμᾷς τίσασθαι, οὕτω δή τι ἐόντας εὐπετέας χειρωθῆναι. ἀλλ’ εἴ τοι σὺ σφέας καταρρώδηκας, ἐμοὶ δὸς τοὺς ἐπικούρους, καί σφεας ἐγὼ τιμωρήσομαι τῆς ἐνθάδε ἀπίξιος· αὐτὸν δέ σε ἐκπέμψαι ἐκ τῆς νήσου ἕτοιμος εἰμί.", "st": "3.145"}, {"sp": "N", "t": "ταῦτα δὲ ἔλεξε ὁ Χαρίλεως· Μαιάνδριος δὲ ὑπέλαβε τὸν λόγον, ὡς μὲν ἐγὼ δοκέω, οὐκ ἐς τοῦτο ἀφροσύνης ἀπικόμενος ὡς δόξαι τὴν ἑωυτοῦ δύναμιν περιέσεσθαι τῆς βασιλέος, ἀλλὰ φθονήσας μᾶλλον Συλοσῶντι εἰ ἀπονητὶ ἔμελλε ἀπολάμψεσθαι ἀκέραιον τὴν πόλιν. ἐρεθίσας ὦν τοὺς Πέρσας ἤθελε ὡς ἀσθενέστατα ποιῆσαι τὰ Σάμια πρήγματα καὶ οὕτω παραδιδόναι, εὖ ἐξεπιστάμενος ὡς παθόντες οἱ Πέρσαι κακῶς προσεμπικρανέεσθαι ἔμελλον τοῖσι Σαμίοισι, εἰδώς τε ἑωυτῷ ἀσφαλέα ἔκδυσιν ἐοῦσαν ἐκ τῆς νήσου τότε ἐπεὰν αὐτὸς βούληται· ἐπεποίητο γάρ οἱ κρυπτὴ διῶρυξ ἐκ τῆς ἀκροπόλιος φέρουσα ἐπὶ θάλασσαν. αὐτὸς μὲν δὴ ὁ Μαιάνδριος ἐκπλέει ἐκ τῆς Σάμου· τοὺς δ’ ἐπικούρους πάντας ὁπλίσας ὁ Χαρίλεως, καὶ ἀναπετάσας τὰς πύλας, ἐξῆκε ἐπὶ τοὺς Πέρσας οὔτε προσδεκομένους τοιοῦτο οὐδὲν δοκέοντάς τε δὴ πάντα συμβεβάναι. ἐμπεσόντες δὲ οἱ ἐπίκουροι τῶν Περσέων τοὺς διφροφορευμένους τε καὶ λόγου πλείστου ἐόντας ἔκτεινον. καὶ οὗτοι μὲν ταῦτα ἐποίευν, ἡ δὲ ἄλλη στρατιὴ ἡ Περσικὴ ἐπεβοήθεε· πιεζεύμενοι δὲ οἱ ἐπίκουροι ὀπίσω κατειλήθησαν ἐς τὴν ἀκρόπολιν.", "st": "3.146"}, {"sp": "N", "t": "Ὀτάνης δὲ ὁ στρατηγὸς ἰδὼν πάθος μέγα Πέρσας πεπονθότας, ἐντολὰς μὲν τὰς Δαρεῖός οἱ ἀποστέλλων ἐνετέλλετο, μήτε κτείνειν μηδένα Σαμίων μήτε ἀνδραποδίζεσθαι ἀπαθέα τε κακῶν ἀποδοῦναι τὴν νῆσον Συλοσῶντι, τουτέων μὲν τῶν ἐντολέων μεμνημένος ἐπελανθάνετο, ὁ δὲ παρήγγειλε τῇ στρατιῇ πάντα τὸν ἂν λάβωσι καὶ ἄνδρα καὶ παῖδα ὁμοίως κτείνειν. ἐνθαῦτα τῆς στρατιῆς οἳ μὲν τὴν ἀκρόπολιν ἐπολιόρκεον, οἳ δὲ ἔκτεινον πάντα τὸν ἐμποδὼν γινόμενον ὁμοίως ἔν τε ἱρῷ καὶ ἔξω ἱροῦ.", "st": "3.147"}, {"sp": "N", "t": "Μαιάνδριος δὲ ἀποδρὰς ἐκ τῆς Σάμου ἐκπλέει ἐς Λακεδαίμονα· ἀπικόμενος δὲ ἐς αὐτὴν καὶ ἀνενεικάμενος τὰ ἔχων ἐξεχώρησε, ἐποίεε τοιάδε· ὅκως ποτήρια ἀργύρεά τε καὶ χρύσεα προθεῖτο, οἱ μὲν θεράποντες αὐτοῦ ἐξέσμων αὐτά, ὃ δ’ ἂν τὸν χρόνον τοῦτον τῷ Κλεομένεϊ τῷ Ἀναξανδρίδεω ἐν λόγοισι ἐών, βασιλεύοντι Σπάρτης, προῆγέ μιν ἐς τὰ οἰκία· ὅκως δὲ ἴδοιτο Κλεομένης τὰ ποτήρια, ἀπεθώμαζέ τε καὶ ἐξεπλήσσετο· ὁ δὲ ἂν ἐκέλευε αὐτὸν ἀποφέρεσθαι αὐτῶν ὅσα βούλοιτο. τοῦτο καὶ δὶς καὶ τρὶς εἴπαντος Μαιανδρίου ὁ Κλεομένης δικαιότατος ἀνδρῶν γίνεται, ὃς λαβεῖν μὲν διδόμενα οὐκ ἐδικαίου, μαθὼν δὲ ὡς ἄλλοισι διδοὺς τῶν ἀστῶν εὑρήσεται τιμωρίην, βὰς ἐπὶ τοὺς ἐφόρους ἄμεινον εἶναι ἔφη τῇ Σπάρτῃ τὸν ξεῖνον τὸν Σάμιον ἀπαλλάσσεσθαι ἐκ τῆς Πελοποννήσου, ἵνα μὴ ἀναπείσῃ ἢ αὐτὸν ἢ ἄλλον τινὰ Σπαρτιητέων κακὸν γενέσθαι. οἳ δ’ ὑπακούσαντες ἐξεκήρυξαν Μαιάνδριον.", "st": "3.148"}, {"sp": "N", "t": "τὴν δὲ Σάμον [σαγηνεύσαντες] οἱ Πέρσαι παρέδοσαν Συλοσῶντι ἔρημον ἐοῦσαν ἀνδρῶν. ὑστέρῳ μέντοι χρόνῳ καὶ συγκατοίκισε αὐτὴν ὁ στρατηγὸς Ὀτάνης ἔκ τε ὄψιος ὀνείρου καὶ νούσου ἥ μιν κατέλαβε νοσῆσαι τὰ αἰδοῖα.", "st": "3.149"}, {"sp": "N", "t": "ἐπὶ δὲ Σάμον στρατεύματος ναυτικοῦ οἰχομένου Βαβυλώνιοι ἀπέστησαν, κάρτα εὖ παρεσκευασμένοι· ἐν ὅσῳ γὰρ ὅ τε Μάγος ἦρχε καὶ οἱ ἑπτὰ ἐπανέστησαν, ἐν τούτῳ παντὶ τῷ χρόνῳ καὶ τῇ ταραχῇ ἐς τὴν πολιορκίην παρεσκευάζοντο. καί κως ταῦτα ποιεῦντες ἐλάνθανον. ἐπείτε δὲ ἐκ τοῦ ἐμφανέος ἀπέστησαν, ἐποίησαν τοιόνδε· τὰς μητέρας ἐξελόντες, γυναῖκα ἕκαστος μίαν προσεξαιρέετο τὴν ἐβούλετο ἐκ τῶν ἑωυτοῦ οἰκίων, τὰς δὲ λοιπὰς ἁπάσας συναγαγόντες ἀπέπνιξαν· τὴν δὲ μίαν ἕκαστος σιτοποιὸν ἐξαιρέετο· ἀπέπνιξαν δὲ αὐτάς, ἵνα μή σφεων τὸν σῖτον ἀναισιμώσωσι.", "st": "3.150"}, {"sp": "N", "t": "πυθόμενος δὲ ταῦτα ὁ Δαρεῖος καὶ συλλέξας πᾶσαν τὴν ἑωυτοῦ δύναμιν ἐστρατεύετο ἐπ’ αὐτούς, ἐπελάσας δὲ ἐπὶ τὴν Βαβυλῶνα ἐπολιόρκεε φροντίζοντας οὐδὲν τῆς πολιορκίης. ἀναβαίνοντες γὰρ ἐπὶ τοὺς προμαχεῶνας τοῦ τείχεος οἱ Βαβυλώνιοι κατωρχέοντο καὶ κατέσκωπτον Δαρεῖον καὶ τὴν στρατιὴν αὐτοῦ, καί τις αὐτῶν εἶπε τοῦτο τὸ ἔπος. τί κάτησθε ὦ Πέρσαι ἐνθαῦτα, ἀλλ’ οὐκ ἀπαλλάσσεσθε; τότε γὰρ αἱρήσετε ἡμέας, ἐπεὰν ἡμίονοι τέκωσι. τοῦτο εἶπε τῶν τις Βαβυλωνίων οὐδαμὰ ἐλπίζων ἂν ἡμίονον τεκεῖν.", "st": "3.151"}, {"sp": "N", "t": "ἑπτὰ δὲ μηνῶν καὶ ἐνιαυτοῦ διεληλυθότος ἤδη ὁ Δαρεῖός τε ἤσχαλλε καὶ ἡ στρατιὴ πᾶσα οὐ δυνατὴ ἐοῦσα ἑλεῖν τοὺς Βαβυλωνίους. καίτοι πάντα σοφίσματα καὶ πάσας μηχανὰς ἐπεποιήκεε ἐς αὐτοὺς Δαρεῖος· ἀλλ’ οὐδ’ ὣς ἐδύνατο ἑλεῖν σφεας, ἄλλοισί τε σοφίσμασι πειρησάμενος, καὶ δὴ καὶ τῷ Κῦρος εἷλε σφέας, καὶ τούτῳ ἐπειρήθη. ἀλλὰ γὰρ δεινῶς ἦσαν ἐν φυλακῇσι οἱ Βαβυλώνιοι, οὐδὲ σφέας οἷός τε ἦν ἑλεῖν.", "st": "3.152"}, {"sp": "N", "t": "ἐνθαῦτα εἰκοστῷ μηνὶ Ζωπύρῳ τῷ Μεγαβύζου, τούτου ὃς τῶν ἑπτὰ ἀνδρῶν ἐγένετο τῶν τὸν Μάγον κατελόντων, τούτῳ τῷ Μεγαβύζου παιδὶ Ζωπύρῳ ἐγένετο τέρας τόδε· τῶν οἱ σιτοφόρων ἡμιόνων μία ἔτεκε. ὡς δέ οἱ ἐξαγγέλθη καὶ ὑπὸ ἀπιστίης αὐτὸς ὁ Ζώπυρος εἶδε τὸ βρέφος, ἀπείπας τοῖσι ἰδοῦσι μηδενὶ φράζειν τὸ γεγονὸς ἐβουλεύετο. καί οἱ πρὸς τὰ τοῦ Βαβυλωνίου ῥήματα, ὃς κατ’ ἀρχὰς ἔφησε, ἐπεάν περ ἡμίονοι τέκωσι, τότε τὸ τεῖχος ἁλώσεσθαι, πρὸς ταύτην τὴν φήμην Ζωπύρῳ ἐδόκεε εἶναι ἁλώσιμος ἡ Βαβυλών· σὺν γὰρ θεῷ ἐκεῖνόν τε εἰπεῖν καὶ ἑωυτῷ τεκεῖν τὴν ἡμίονον.", "st": "3.153"}, {"sp": "N", "t": "ὡς δέ οἱ ἐδόκεε μόρσιμον εἶναι ἤδη τῇ Βαβυλῶνι ἁλίσκεσθαι, προσελθὼν Δαρείου ἀπεπυνθάνετο εἰ περὶ πολλοῦ κάρτα ποιέεται τὴν Βαβυλῶνα ἑλεῖν. πυθόμενος δὲ ὡς πολλοῦ τιμῷτο, ἄλλο ἐβουλεύετο, ὅκως αὐτός τε ἔσται ὁ ἑλὼν αὐτὴν καὶ ἑωυτοῦ τὸ ἔργον ἔσται· κάρτα γὰρ ἐν τοῖσι Πέρσῃσι αἱ ἀγαθοεργίαι ἐς τὸ πρόσω μεγάθεος τιμῶνται. ἄλλῳ μέν νυν οὐκ ἐφράζετο ἔργῳ δυνατὸς εἶναί μιν ὑποχειρίην ποιῆσαι, εἰ δ’ ἑωυτὸν λωβησάμενος αὐτομολήσειε ἐς αὐτούς. ἐνθαῦτα ἐν ἐλαφρῷ ποιησάμενος ἑωυτὸν λωβᾶται λώβην ἀνήκεστον· ἀποταμὼν γὰρ ἑωυτοῦ τὴν ῥῖνα καὶ τὰ ὦτα καὶ τὴν κόμην κακῶς περικείρας καὶ μαστιγώσας ἦλθε παρὰ Δαρεῖον.", "st": "3.154"}, {"sp": "N", "t": "Δαρεῖος δὲ κάρτα βαρέως ἤνεικε ἰδὼν ἄνδρα δοκιμώτατον λελωβημένον, ἔκ τε τοῦ θρόνου ἀναπηδήσας ἀνέβωσέ τε καὶ εἴρετό μιν ὅστις εἴη ὁ λωβησάμενος καὶ ὅ τι ποιήσαντα. ὁ δὲ εἶπε οὐκ ἔστι οὗτος ὡνήρ, ὅτι μὴ σύ, τῷ ἐστὶ δύναμις τοσαύτη ἐμὲ δὴ ὧδε διαθεῖναι· οὐδέ τις ἀλλοτρίων ὦ βασιλεῦ τάδε ἔργασται, ἀλλ’ αὐτὸς ἐγὼ ἐμεωυτόν, δεινόν τι ποιεύμενος Ἀσσυρίους Πέρσῃσι καταγελᾶν. ὃ δ’ ἀμείβετο ὦ σχετλιώτατε ἀνδρῶν, ἔργῳ τῷ αἰσχίστῳ οὔνομα τὸ κάλλιστον ἔθευ, φὰς διὰ τοὺς πολιορκεομένους σεωυτὸν ἀνηκέστως διαθεῖναι. τί δ’, ὦ μάταιε, λελωβημένου σεῦ θᾶσσον οἱ πολέμιοι παραστήσονται; κῶς οὐκ ἐξέπλωσας τῶν φρενῶν σεωυτὸν διαφθείρας; ὁ δὲ εἶπε εἰ μέν τοι ὑπερετίθεα τὰ ἔμελλον ποιήσειν, οὐκ ἄν με περιεῖδες· νῦν δ’ ἐπ’ ἐμεωυτοῦ βαλόμενος ἔπρηξα. ἤδη ὦν ἢν μὴ τῶν σῶν δεήσῃ, αἱρέομεν Βαβυλῶνα. ἐγὼ μὲν γὰρ ὡς ἔχω αὐτομολήσω ἐς τὸ τεῖχος καὶ φήσω πρὸς αὐτοὺς ὡς ὑπὸ σεῦ τάδε ἔπαθον· καὶ δοκέω, πείσας σφέας ταῦτα ἔχειν οὕτω, τεύξεσθαι στρατιῆς. σὺ δέ, ἀπ’ ἧς ἂν ἡμέρης ἐγὼ ἐσέλθω ἐς τὸ τεῖχος, ἀπὸ ταύτης ἐς δεκάτην ἡμέρην τῆς σεωυτοῦ στρατιῆς, τῆς οὐδεμία ἔσται ὤρη ἀπολλυμένης, ταύτης χιλίους τάξον κατὰ τὰς Σεμιράμιος καλεομένας πύλας· μετὰ δὲ αὖτις ἀπὸ τῆς δεκάτης ἐς ἑβδόμην ἄλλους μοι τάξον δισχιλίους κατὰ τὰς Νινίων καλεομένας πύλας· ἀπὸ δὲ τῆς ἑβδόμης διαλείπειν εἴκοσι ἡμέρας, καὶ ἔπειτα ἄλλους κάτισον ἀγαγὼν κατὰ τὰς Χαλδαίων καλεομένας πύλας, τετρακισχιλίους. ἐχόντων δὲ μήτε οἱ πρότεροι μηδὲν τῶν ἀμυνεύντων μήτε οὗτοι, πλὴν ἐγχειριδίων· τοῦτο δὲ ἐᾶν ἔχειν. μετὰ δὲ τὴν εἰκοστὴν ἡμέρην ἰθέως τὴν μὲν ἄλλην στρατιὴν κελεύειν πέριξ προσβάλλειν πρὸς τὸ τεῖχος, Πέρσας δέ μοι τάξον κατά τε τὰς Βηλίδας καλεομένας καὶ Κισσίας πύλας. ὡς γὰρ ἐγὼ δοκέω, ἐμέο μεγάλα ἔργα ἀποδεξαμένου, τά τε ἄλλα ἐπιτρέψονται ἐμοὶ Βαβυλώνιοι καὶ δὴ καὶ τῶν πυλέων τὰς βαλανάγρας· τὸ δὲ ἐνθεῦτεν ἐμοί τε καὶ Πέρσῃσι μελήσει τὰ δεῖ ποιέειν.", "st": "3.155"}, {"sp": "N", "t": "ταῦτα ἐντειλάμενος ἤιε ἐπὶ τὰς πύλας, ἐπιστρεφόμενος ὡς δὴ ἀληθέως αὐτόμολος. ὁρῶντες δὲ ἀπὸ τῶν πύργων οἱ κατὰ τοῦτο τεταγμένοι κατέτρεχον κάτω καὶ ὀλίγον τι παρακλίναντες τὴν ἑτέρην πύλην εἰρώτων τίς τε εἴη καὶ ὅτευ δεόμενος ἥκοι. ὁ δέ σφι ἠγόρευε ὡς εἴη τε Ζώπυρος καὶ αὐτομολέοι ἐς ἐκείνους. ἦγον δή μιν οἱ πυλουροί, ταῦτα ὡς ἤκουσαν, ἐπὶ τὰ κοινὰ τῶν Βαβυλωνίων· καταστὰς δὲ ἐπ’ αὐτὰ κατοικτίζετο, φὰς ὑπὸ Δαρείου πεπονθέναι τὰ ἐπεπόνθεε ὑπ’ ἑωυτοῦ, παθεῖν δὲ ταῦτα διότι συμβουλεῦσαι οἱ ἀπανιστάναι τὴν στρατιήν, ἐπείτε δὴ οὐδεὶς πόρος ἐφαίνετο τῆς ἁλώσιος. νῦν τε ἔφη λέγων ἐγὼ ὑμῖν ὦ Βαβυλώνιοι ἥκω μέγιστον ἀγαθόν, Δαρείῳ δὲ καὶ τῇ στρατιῇ καὶ Πέρσῃσι μέγιστον κακόν· οὐ γὰρ δὴ ἐμέ γε ὧδε λωβησάμενος καταπροΐξεται· ἐπίσταμαι δ’ αὐτοῦ πάσας τὰς διεξόδους τῶν βουλευμάτων. τοιαῦτα ἔλεγε.", "st": "3.156"}, {"sp": "N", "t": "οἳ δὲ Βαβυλώνιοι ὁρῶντες ἄνδρα τὸν ἐν Πέρσῃσι δοκιμώτατον ῥινός τε καὶ ὤτων ἐστερημένον, μάστιξί τε καὶ αἵματι ἀναπεφυρμένον, πάγχυ ἐλπίσαντες λέγειν μιν ἀληθέα καί σφι ἥκειν σύμμαχον, ἐπιτρέπεσθαι ἕτοιμοι ἦσαν τῶν ἐδέετο σφέων· ἐδέετο δὲ στρατιῆς. ὁ δὲ ἐπείτε αὐτῶν τοῦτο παρέλαβε, ἐποίεε τά περ τῷ Δαρείῳ συνεθήκατο· ἐξαγαγὼν γὰρ τῇ δεκάτῃ ἡμέρῃ τὴν στρατιὴν τῶν Βαβυλωνίων καὶ κυκλωσάμενος τοὺς χιλίους, τοὺς πρώτους ἐνετείλατο Δαρείῳ τάξαι, τούτους κατεφόνευσε. μαθόντες δέ μιν οἱ Βαβυλώνιοι τοῖσι ἔπεσι τὰ ἔργα παρεχόμενον ὅμοια, πάγχυ περιχαρέες ἐόντες πᾶν δὴ ἕτοιμοι ἦσαν ὑπηρετέειν. ὁ δὲ διαλιπὼν ἡμέρας τὰς συγκειμένας, αὖτις ἐπιλεξάμενος τῶν Βαβυλωνίων ἐξήγαγε καὶ κατεφόνευσε τῶν Δαρείου στρατιωτέων τοὺς δισχιλίους. ἰδόντες δὲ καὶ τοῦτο τὸ ἔργον οἱ Βαβυλώνιοι πάντες Ζώπυρον εἶχον ἐν στόμασι αἰνέοντες. ὁ δὲ αὖτις διαλιπὼν τὰς συγκειμένας ἡμέρας ἐξήγαγε ἐς τὸ προειρημένον, καὶ κυκλωσάμενος κατεφόνευσε τοὺς τετρακισχιλίους. ὡς δὲ καὶ τοῦτο κατέργαστο, πάντα δὴ ἦν ἐν τοῖσι Βαβυλωνίοισι Ζώπυρος, καὶ στρατάρχης τε οὗτός σφι καὶ τειχοφύλαξ ἀπεδέδεκτο.", "st": "3.157"}, {"sp": "N", "t": "προσβολὴν δὲ Δαρείου κατὰ τὰ συγκείμενα ποιευμένου πέριξ τὸ τεῖχος, ἐνθαῦτα δὴ πάντα τὸν δόλον ὁ Ζώπυρος ἐξέφαινε. οἱ μὲν γὰρ Βαβυλώνιοι ἀναβάντες ἐπὶ τὸ τεῖχος ἠμύνοντο τὴν Δαρείου στρατιὴν προσβάλλουσαν, ὁ δὲ Ζώπυρος τάς τε Κισσίας καὶ Βηλίδας καλεομένας πύλας ἀναπετάσας ἐσῆκε τοὺς Πέρσας ἐς τὸ τεῖχος. τῶν δὲ Βαβυλωνίων οἳ μὲν εἶδον τὸ ποιηθέν, οὗτοι μὲν ἔφευγον ἐς τοῦ Διὸς τοῦ Βήλου τὸ ἱρόν· οἳ δὲ οὐκ εἶδον, ἔμενον ἐν τῇ ἑωυτοῦ τάξι ἕκαστος, ἐς ὃ δὴ καὶ οὗτοι ἔμαθον προδεδομένοι.", "st": "3.158"}, {"sp": "N", "t": "Βαβυλὼν μέν νυν οὕτω τὸ δεύτερον αἱρέθη. Δαρεῖος δὲ ἐπείτε ἐκράτησε τῶν Βαβυλωνίων, τοῦτο μὲν σφέων τὸ τεῖχος περιεῖλε καὶ τὰς πύλας πάσας ἀπέσπασε· τὸ γὰρ πρότερον ἑλὼν Κῦρος τὴν Βαβυλῶνα ἐποίησε τούτων οὐδέτερον· τοῦτο δὲ ὁ Δαρεῖος τῶν ἀνδρῶν τοὺς κορυφαίους μάλιστα ἐς τρισχιλίους ἀνεσκολόπισε, τοῖσι δὲ λοιποῖσι Βαβυλωνίοισι ἀπέδωκε τὴν πόλιν οἰκέειν. ὡς δ’ ἕξουσι γυναῖκας οἱ Βαβυλώνιοι ἵνα σφι γενεὴ ὑπογίνηται, τάδε Δαρεῖος προϊδὼν ἐποίησε· τὰς γὰρ ἑωυτῶν, ὡς καὶ κατ’ ἀρχὰς δεδήλωται, ἀπέπνιξαν οἱ Βαβυλώνιοι τοῦ σίτου προορέοντες· ἐπέταξε τοῖσι περιοίκοισι ἔθνεσι γυναῖκας ἐς Βαβυλῶνα κατιστάναι, ὅσας δὴ ἑκάστοισι ἐπιτάσσων, ὥστε πέντε μυριάδων τὸ κεφαλαίωμα τῶν γυναικῶν συνῆλθε· ἐκ τουτέων δὲ τῶν γυναικῶν οἱ νῦν Βαβυλώνιοι γεγόνασι.", "st": "3.159"}, {"sp": "N", "t": "Ζωπύρου δὲ οὐδεὶς ἀγαθοεργίην Περσέων ὑπερεβάλετο παρὰ Δαρείῳ κριτῇ οὔτε τῶν ὕστερον γενομένων οὔτε τῶν πρότερον, ὅτι μὴ Κῦρος μοῦνος· τούτῳ γὰρ οὐδεὶς Περσέων ἠξίωσέ κω ἑωυτὸν συμβαλεῖν. πολλάκις δὲ Δαρεῖον λέγεται γνώμην τήνδε ἀποδέξασθαι, ὡς βούλοιτο ἂν Ζώπυρον εἶναι ἀπαθέα τῆς ἀεικείης μᾶλλον ἢ Βαβυλῶνάς οἱ εἴκοσι πρὸς τῇ ἐούσῃ προσγενέσθαι. ἐτίμησε δέ μιν μεγάλως· καὶ γὰρ δῶρά οἱ ἀνὰ πᾶν ἔτος ἐδίδου ταῦτα τὰ Πέρσῃσι ἐστὶ τιμιώτατα, καὶ τὴν Βαβυλῶνά οἱ ἔδωκε ἀτελέα νέμεσθαι μέχρι τῆς ἐκείνου ζόης, καὶ ἄλλα πολλὰ ἐπέδωκε. Ζωπύρου δὲ τούτου γίνεται Μεγάβυζος, ὃς ἐν Αἰγύπτῳ ἀντία Ἀθηναίων καὶ τῶν συμμάχων ἐστρατήγησε· Μεγαβύζου δὲ τούτου γίνεται Ζώπυρος, ὃς ἐς Ἀθήνας ηὐτομόλησε ἐκ Περσέων.", "st": "3.160"}], []);})();
